// 単語ごとの例文（英語・日本語訳・強調する語）。出典：田中コーパス／Tatoebaプロジェクト（CC BY 2.0 FR）。 ※make_examples.py で自動生成
EXAMPLES[1]=["I should think you are in the wrong.","あなたは間違っているとおもうのですが。","the"];
EXAMPLES[2]=["We have a lot of work to do.","私たちはするべき仕事がたくさんある。","to"];
EXAMPLES[3]=["I like both this one and that one.","これもあれもどっちも好きです。","and"];
EXAMPLES[4]=["I have to go to a meeting now.","今から会議に行かなければならない。","a"];
EXAMPLES[5]=["This is the way in which it happened.","こんなふうにそれは起こったのです。","in"];
EXAMPLES[6]=["I would like to go to the USA.","私はアメリカへ行きたいものだ。","I"];
EXAMPLES[7]=["This is the book you are looking for.","これが君の探している本です。","is"];
EXAMPLES[8]=["Is that really what you want to do?","それは、本当にあなたがしたいことなの？","that"];
EXAMPLES[9]=["He is the right man for the job.","彼はその仕事に適切だ。","for"];
EXAMPLES[10]=["Can I go to the movies with you?","私も一緒に映画観に行っていい？","you"];
EXAMPLES[11]=["I have a lot to say about it.","それについては言いたいことがたくさんある。","it"];
EXAMPLES[12]=["Are you on your way to the station?","駅に行く途中ですか？","on"];
EXAMPLES[13]=["What are you going to do with that?","それをどうするつもりですか。","with"];
EXAMPLES[14]=["This is all I can do for now.","今の私にはこれが精一杯です。","This"];
EXAMPLES[15]=["It was in 1950 that he was born.","彼が生まれたのは１９５０年だ。","was"];
EXAMPLES[16]=["Will we be in time for the train?","電車に間に合うだろうか。","be"];
EXAMPLES[17]=["He is selling it just as it is.","彼はそれをそのまま売っている。","as"];
EXAMPLES[18]=["What are you going to do with it?","それをどうするつもりですか。","are"];
EXAMPLES[19]=["I have to do a lot of things.","私はたくさんの事をしなければならない。","have"];
EXAMPLES[20]=["What in the world are you getting at?","一体君は何を言おうとしているんだい。","at"];
EXAMPLES[21]=["He will have to go to the station.","彼は駅に行かなければならないでしょう。","He"];
EXAMPLES[22]=["You do not have to do it now.","今それをする必要はないんだよ。","not"];
EXAMPLES[23]=["I was going to do that by myself.","一人でするつもりだった。","by"];
EXAMPLES[24]=["But, that thing is said to no one.","しかし、そのことは誰にも言っていない。","But"];
EXAMPLES[25]=["Come and see me from time to time.","時々遊びにいらっしゃい。","from"];
EXAMPLES[26]=["It was the best day of my life.","私の人生において、最高の日でした。","my"];
EXAMPLES[27]=["The more we have, the more we want.","人は持てばもつほどなおさら欲しくなる。","we"];
EXAMPLES[28]=["When will the world come to an end?","世界はいつ終わるのだろうか。","an"];
EXAMPLES[29]=["You have to do it on your own.","自分ひとりでやらなきゃダメだね。","your"];
EXAMPLES[30]=["This is all I can do for you.","あなたにしてあげる事は、これだけです。","all"];
EXAMPLES[31]=["Is that so? That was good to know!","そうですか、良かったです！","so"];
EXAMPLES[32]=["He is at his best in this work.","彼はこの作品が一番優れている。","his"];
EXAMPLES[33]=["They say that to see is to believe.","見る事は信じる事だといわれる。","They"];
EXAMPLES[34]=["It is kind of you to help me.","私を助けてくれてありがとう。","me"];
EXAMPLES[35]=["This one is as good as that one.","これはあれと同じくらいよい。","one"];
EXAMPLES[36]=["This is what I can do for you.","僕が君にできることはこれだけだ。","can"];
EXAMPLES[37]=["I will do all I can for you.","君のためにできるだけ骨を折ろう。","will"];
EXAMPLES[38]=["I know just the place for a party.","パーティーのためのうってつけの場所を知ってるよ。","just"];
EXAMPLES[39]=["I like her all the better for that.","それだからいっそう私は彼女のことが好きだ。","like"];
EXAMPLES[40]=["I have to think about what to do.","何をすべきか、考えなければならない。","about"];
EXAMPLES[41]=["I have looked for it up and down.","あちこちでそれを捜した。","up"];
EXAMPLES[42]=["Would you like to go out with me?","僕と付き合わない？","out"];
EXAMPLES[43]=["I will do what I can for you.","私はあなたのために出来る限りのことをします。","what"];
EXAMPLES[44]=["When are you going to say, I do?","いつ結婚するの？","When"];
EXAMPLES[45]=["I have a lot of things to do.","私はたくさんの事をしなければならない。","do"];
EXAMPLES[46]=["I have no time to go to America.","アメリカへ行く時間がない。","no"];
EXAMPLES[47]=["Who was that you were just talking to?","さっき話してた人誰？","Who"];
EXAMPLES[48]=["He is looked up to as their leader.","彼は彼らの指導者として尊敬されている。","their"];
EXAMPLES[49]=["You must buy milk, eggs, butter, and so on.","牛乳、バター卵などを買わなければならない。","and so on"];
EXAMPLES[50]=["I had to make up for the loss.","私は損失の埋め合わせをしなければならなかった。","had"];
EXAMPLES[51]=["All you have to do is go there.","あなたはそこへ行きさえすればよいのだ。","there"];
EXAMPLES[52]=["The money will do for the time being.","当分はその金で間に合うだろう。","time"];
EXAMPLES[53]=["I want to get to know you better.","もっとあなたのこと知りたいな。","get"];
EXAMPLES[54]=["Is this baby a he or a she?","この赤ちゃんは男ですか女ですか。","she"];
EXAMPLES[55]=["The more people have, the more they want.","人は持てば持つほどますます欲しくなる。","people"];
EXAMPLES[56]=["I need to look for a new job.","新しい仕事を探す必要がある。","new"];
EXAMPLES[57]=["I do not know how to use it.","私はその使い方を知りません。","how"];
EXAMPLES[58]=["I need some time to think about it.","考える時間が必要です。","some"];
EXAMPLES[59]=["The two of them are in the room.","二人は部屋にいます。","them"];
EXAMPLES[60]=["Not only you but also I was involved.","君ばかりか僕まで巻き添えを食らった。","also"];
EXAMPLES[61]=["This is all you have to do now.","君が今しなければならないのはこれだけだ。","now"];
EXAMPLES[62]=["One is new, and the other is old.","一つは新しくて、もう一つは古いものです。","other"];
EXAMPLES[63]=["The child is lonesome for its mother.","子供は母親にあいたがっている。","its"];
EXAMPLES[64]=["Would you like to come to our house?","家に来ませんか。","our"];
EXAMPLES[65]=["He was the only one in the room.","彼はたったひとりで部屋の中にいた。","only"];
EXAMPLES[66]=["He is a good man for the job.","彼は、その仕事に適した男だ。","good"];
EXAMPLES[67]=["I like him all the better for it.","それだからいっそう彼が好きだ。","him"];
EXAMPLES[68]=["I was the first one to do that.","一番最初にそれやったの、私なんだよ。","first"];
EXAMPLES[69]=["What are you going to do after this?","この後、何するの？","after"];
EXAMPLES[70]=["You know you have to do that, right?","それをやらないといけないって知ってるんだよね？","know"];
EXAMPLES[71]=["I would like to come and see you.","貴社にお伺いしたいと思います。","see"];
EXAMPLES[72]=["He is the shorter of the two boys.","彼はその二人の少年のうちの背の低い方だ。","two"];
EXAMPLES[73]=["Can you get by on what you make?","今の給料でやっていけるのか？","make"];
EXAMPLES[74]=["I think I should do it for you.","あなたのためにそれをすべきだと思うのです。","think"];
EXAMPLES[75]=["I have something to talk over with you.","あなたに相談したいことがあるの。","over"];
EXAMPLES[76]=["Do any of the members agree with you?","メンバーの誰かが君に賛成していますか。","any"];
EXAMPLES[77]=["Do you think that you could do that?","あなたにそれが出来ると思う？","could"];
EXAMPLES[78]=["Were all of these in the same bag?","同じ袋の中にそれ全部が入ってたの？","these"];
EXAMPLES[79]=["The more I get, the more I want.","持てば持つほどもっと欲しくなる。","want"];
EXAMPLES[80]=["He went to the back of the building.","彼は建物の奥に行ってみました。","back"];
EXAMPLES[81]=["It is really time for us to go.","出発する時間だ。","us"];
EXAMPLES[82]=["Do I have to go to the hospital?","病院に行かないとダメ？","go"];
EXAMPLES[83]=["The work was well done in a way.","その仕事はある意味では立派に成された。","well"];
EXAMPLES[84]=["It is said that he is in Britain.","彼はイギリスにいるそうだ。","said"];
EXAMPLES[85]=["The way I see it, he is right.","僕の見るところ彼は正しい。","way"];
EXAMPLES[86]=["This is the very thing that I wanted.","これこそ僕が欲しいと思っていたものだ。","very"];
EXAMPLES[87]=["He had much to do with the project.","彼はその計画におおいに関係があった。","much"];
EXAMPLES[88]=["That is the house where I was born.","あれは私が生まれた家だ。","where"];
EXAMPLES[89]=["Was it in May that I was born?","私は五月に生まれたかしら。","May"];
EXAMPLES[90]=["Will that be for here or to go?","持ち帰りですか。それともここでたべますか。","here"];
EXAMPLES[91]=["I need all the help I can get.","猫の手も借りたい。","need"];
EXAMPLES[92]=["Is that what you really want to do?","それ、あなたが本当にやりたいことなの？","really"];
EXAMPLES[93]=["I have a lot of work to do!","やることがいっぱいあるんです！","work"];
EXAMPLES[94]=["As for the money, it is all right.","そのお金に関しては大丈夫だ。","right"];
EXAMPLES[95]=["1980 was the year that I was born.","１９８０年は私が生まれた年です。","year"];
EXAMPLES[96]=["That was the best day of my life.","あの日が私の人生で最高の日だった。","day"];
EXAMPLES[97]=["If I can do it, you can, too.","私ができるんだったら、あなただってできるわ。","too"];
EXAMPLES[98]=["I want to see you before you go.","あなたが出かける前にお会いしたい。","before"];
EXAMPLES[99]=["Why in the world did you do that?","いったいあなたはなぜそんなことをしたのですか。","Why"];
EXAMPLES[100]=["I thought that I had a day off.","私は休みを取ったと思っていました。","off"];
EXAMPLES[101]=["Take it to the men in Room 318.","３１８号室のお客さんに持って行ってあげなさい。","Take"];
EXAMPLES[102]=["The building was still there in my time.","私のいたころはまだその建物はありました。","still"];
EXAMPLES[103]=["They made for the scene of the accident.","彼らは事故の現場へ急行した。","made"];
EXAMPLES[104]=["It is used by a great many people.","それは非常にたくさんの人々によって使われます。","many"];
EXAMPLES[105]=["I got there in time for the train.","汽車に間にあった。","got"];
EXAMPLES[106]=["I never thought it would come to this.","まさかこんなことになろうとは思わなかった。","never"];
EXAMPLES[107]=["In those days, I was still a student.","その当時、私はまだ学生であった。","those"];
EXAMPLES[108]=["It is kind of you to say so.","そう言ってくれてありがとう。","say"];
EXAMPLES[109]=["It was the best time of my life.","人生の絶頂期でした。","life"];
EXAMPLES[110]=["How in the world did you do it?","一体全体どうやって君はそれをしたんだい。","world"];
EXAMPLES[111]=["It is time you get down to work.","そろそろ本気で仕事に取り組むころだよ。","down"];
EXAMPLES[112]=["The difference is not so great for me.","その相違は私にはそれほど重要でない。","great"];
EXAMPLES[113]=["He was in time for the last bus.","彼は最終のバスに間に合った。","last"];
EXAMPLES[114]=["I have to do the best I can.","私は最善を尽くさなければならない。","best"];
EXAMPLES[115]=["He is the very man for the job.","彼はその仕事をするのにうってつけの人です。","man"];
EXAMPLES[116]=["I love the time I have with him.","彼と一緒にいる時間が大好きなの。","love"];
EXAMPLES[117]=["Come here and have a look at it.","こっちへ来てこれを見てごらん。","look"];
EXAMPLES[118]=["It is OK for me to use that?","それを使ってもよろしいでしょうか。","use"];
EXAMPLES[119]=["I have something I want to give you.","君に渡したい物があるんだ。","something"];
EXAMPLES[120]=["I had known that for a long time.","そんなことずっと前から知ってるよ。","long"];
EXAMPLES[121]=["It is time for her to go home.","もう彼女が帰る時間ですよ。","home"];
EXAMPLES[122]=["She and I are in the same class.","彼女と私は、同級生です。","same"];
EXAMPLES[123]=["I do not know every one of them.","私は彼らの全部を知っているというわけではない。","every"];
EXAMPLES[124]=["I would like you to come with me.","君に一緒に来て欲しいのですが。","come"];
EXAMPLES[125]=["This question is for all three of you.","この質問は、お三方にお聞きします。","three"];
EXAMPLES[126]=["I am going to have a good day.","いい一日になりそう。","am"];
EXAMPLES[127]=["How about the last part of the story?","物語の結末はどうでしたか。","part"];
EXAMPLES[128]=["He is different from the people around him.","彼は多くの点で周りの人と違う。","around"];
EXAMPLES[129]=["I always have to give in to him.","私はいつも彼に服従しなければならない。","always"];
EXAMPLES[130]=["This is much the better of the two.","これが２つの中で断然良い。","better"];
EXAMPLES[131]=["The young should be kind to the old.","若者は、老人に親切にすべきです。","old"];
EXAMPLES[132]=["You have to get him to help you.","あなたは彼に手伝ってもらわなければなりませんよ。","help"];
EXAMPLES[133]=["That is a high building, is it not?","高い建物ですね。","high"];
EXAMPLES[134]=["He is on another phone at the moment.","彼は今ほかの電話に出ています。","another"];
EXAMPLES[135]=["I slept a little during lunch break because I was so tired.","僕はあまりに疲れていたので昼休みにひと眠りした。","a little"];
EXAMPLES[136]=["There is no new thing under the sun.","太陽の下、新しいものは何ひとつない。","under"];
EXAMPLES[137]=["This is the very thing that you need.","これこそまさに君が必要としているものだ。","thing"];
EXAMPLES[138]=["I had a good time during the trip.","旅行中楽しい思いをした。","during"];
EXAMPLES[139]=["Do you know the rules of the game?","ゲームのルール知ってる？","game"];
EXAMPLES[140]=["I would like to give it to her.","彼女にそれを渡したいんだけど。","give"];
EXAMPLES[141]=["Why do I have to go to school?","何で学校に行かないといけないの？","school"];
EXAMPLES[142]=["I will go there in place of you.","私があなたの代わりにそこに行きましょう。","place"];
EXAMPLES[143]=["This is the house that he lives in.","これが彼が住んでいる家です。","house"];
EXAMPLES[144]=["Do I have to do it over again?","またやり直しですか。","again"];
EXAMPLES[145]=["I will make up for it next time.","この次に償いをするよ。","next"];
EXAMPLES[146]=["I will see you, each in your turn.","皆に順番に会いましょう。","each"];
EXAMPLES[147]=["I wanted to show it to you too.","君にも見せたかったよ。","show"];
EXAMPLES[148]=["Not all the students are against the plan.","学生の全員が計画に反対しているわけではない。","against"];
EXAMPLES[149]=["Do it by the end of this week.","今週末までにはやりなさいよ。","end"];
EXAMPLES[150]=["You must make the most of your time.","時間は最大限に活用すべきだ。","must"];
EXAMPLES[151]=["We feel the same way as you do.","私達も同じ気持ちです。","feel"];
EXAMPLES[152]=["Was the high school you went to big?","通ってた高校って、大きかった？","big"];
EXAMPLES[153]=["Are you sure you want to do this?","本当にこれがやりたいの？","sure"];
EXAMPLES[154]=["You two are the nucleus of the team.","君たち二人はこのチームの中心です。","team"];
EXAMPLES[155]=["I have the best family in the world!","僕の家族は世界一だよ！","family"];
EXAMPLES[156]=["I have to put the baby to bed.","赤ん坊を寝かしつけねばならない。","put"];
EXAMPLES[157]=["I like you. Please go out with me.","好きです。付き合ってください。","Please"];
EXAMPLES[158]=["I thought that that might be the case.","そんなことだろうと思ったよ。","might"];
EXAMPLES[159]=["This is all the money I have now.","これは今私が持っているすべてのお金です。","money"];
EXAMPLES[160]=["I'm in the second year of high school.","私は高校2年生だ。","second"];
EXAMPLES[161]=["He made the most of his free time.","彼は暇な時間を最大限に利用した。","free"];
EXAMPLES[162]=["Have you been there a number of times?","そこには何度か行った事があるんですか？","number"];
EXAMPLES[163]=["Do I have to do it right away?","今すぐにやらなくてはいけませんか。","away"];
EXAMPLES[164]=["He made the best of the time left.","彼は残りの時間を最大限に利用した。","left"];
EXAMPLES[165]=["Do you know how to play the game?","そのゲームの仕方知ってるの？","play"];
EXAMPLES[166]=["You can stay with us for the night.","今夜は泊まっていってもいいよ。","night"];
EXAMPLES[167]=["So, how is life in the big city?","それで、大都会での生活はどうなの？","city"];
EXAMPLES[168]=["There is no one with that name here.","こちらには、そういう名前の者はおりません。","name"];
EXAMPLES[169]=["I have a lot of work to do.","私はするべき仕事がたくさんあります。","lot"];
EXAMPLES[170]=["I think this and that are different things.","それとこれとは別だと思うよ。","different"];
EXAMPLES[171]=["I had nothing to do with the group.","私はそのグループとは関係なかった。","group"];
EXAMPLES[172]=["I can see the top of the mountain.","私はその山の頂上を見ることができます。","top"];
EXAMPLES[173]=["The women are in front of a library.","その女性達は図書館の前にいる。","women"];
EXAMPLES[174]=["We will take care of this for you.","すぐに処理します。","care"];
EXAMPLES[175]=["Before long, we'll be able to communicate with each other by T.V. telephone.","近い将来、テレビ電話でお互いに意志疎通ができるようになるだろう。","each other"];
EXAMPLES[176]=["I have come to see you on business.","私は仕事であなたに会いにきました。","business"];
EXAMPLES[177]=["It is necessary for you to start now.","君は今出発する必要がある。","start"];
EXAMPLES[178]=["The Japanese economic system is about to change.","日本の経済システムはまさに変わろうとしている。","system"];
EXAMPLES[179]=["What is the day of the week today?","今日は何曜日ですか？","week"];
EXAMPLES[180]=["Do you have a lot to do today?","今日はやることがたくさんある？","today"];
EXAMPLES[181]=["I have nothing to do at the moment.","今のところはすべきことはない。","nothing"];
EXAMPLES[182]=["I feel as if we have already met.","会ったことがあるような気がするんだけど。","already"];
EXAMPLES[183]=["I have nothing to do with the case.","私はその事件とは全く関係がない。","case"];
EXAMPLES[184]=["Do you like to live in the country?","田舎に住むことは好きですか。","live"];
EXAMPLES[185]=["I think the best is yet to come.","楽しいのはこれからだと思うよ。","yet"];
EXAMPLES[186]=["This book is easy for you to read.","この本は君には易しく読めます。","read"];
EXAMPLES[187]=["Do it the way I told you to.","私の言ったとおりにやりなさい。","told"];
EXAMPLES[188]=["The full story was yet to be told.","まだ全部の話がされたわけではなかった。","full"];
EXAMPLES[189]=["She was on the point of going out.","彼女は外出しようとしていた。","point"];
EXAMPLES[190]=["You are to do as I tell you.","私の言った通りにしなさい。","tell"];
EXAMPLES[191]=["What do you mean to say to me?","あなたは私に何を言おうとしているのですか。","mean"];
EXAMPLES[192]=["We got up at four in the morning.","私達は午前４時に起きた。","four"];
EXAMPLES[193]=["Is that a good or a bad thing?","それって、良いことなの？悪いことなの？","bad"];
EXAMPLES[194]=["He is a hard man to get at.","彼は近づきにくい人だ。","hard"];
EXAMPLES[195]=["The question is where to stop the car.","どこで車を止めるかが問題だ。","stop"];
EXAMPLES[196]=["I have something to live for in music.","おんがくにわたしは生きがいを持っています。","music"];
EXAMPLES[197]=["I would like to have some more water.","水のお代わりを下さい。","water"];
EXAMPLES[198]=["He did all there was in his power.","彼はできる限りのことをした。","power"];
EXAMPLES[199]=["The room is too small to play in.","その部屋は小さいので、中では遊べない。","small"];
EXAMPLES[200]=["I think his death is a national loss.","彼の死は国家的な損失だと思います。","national"];
EXAMPLES[201]=["He is at the head of the class.","彼はその組の首席だ。","head"];
EXAMPLES[202]=["It took me a while to get up.","目覚めるまで長かった。","took"];
EXAMPLES[203]=["One is red and the other is white.","一方は赤で、また一方は白である。","white"];
EXAMPLES[204]=["Shall I call for you in the morning?","午前中にお迎えにあがりましょうか。","call"];
EXAMPLES[205]=["It is up to us to be men.","男になるのは自分次第だ。","men"];
EXAMPLES[206]=["Would you like to give it a try?","やってみませんか？","try"];
EXAMPLES[207]=["He is just the man for the job.","彼こそ適材適所という者だ。","job"];
EXAMPLES[208]=["I know the person that you came with.","私は、あなたが一緒に来た人を知っています。","came"];
EXAMPLES[209]=["This is by far the best of all.","これは全部の中でだんぜん最高だ。","far"];
EXAMPLES[210]=["Yes. I have to read it by tomorrow.","うん。明日までに読まなくちゃならないんだ。","Yes"];
EXAMPLES[211]=["I can run the fastest of the three.","私は３人の中で一番速く走ることができます。","run"];
EXAMPLES[212]=["I was at the front of the line.","列の先頭でした。","line"];
EXAMPLES[213]=["I will contact you at a later date.","日を改めてご連絡します。","later"];
EXAMPLES[214]=["The more you know the less you know.","知れば知るほど分からなくなる。","less"];
EXAMPLES[215]=["Can I be of any service to you?","私で何かお役に立てますでしょうか。","service"];
EXAMPLES[216]=["As far as I know, he is American.","私の知る限り、彼はアメリカ人だ。","American"];
EXAMPLES[217]=["He works for the good of the country.","彼は国のために働いている。","country"];
EXAMPLES[218]=["I have nothing to open the can with.","その缶を開ける物がないんだ。","open"];
EXAMPLES[219]=["Thank you for your help, all of you.","みなさん、ご協力いただきありがとうございました。","Thank"];
EXAMPLES[220]=["The first season of the year is spring.","１年の最初の季節は春です。","season"];
EXAMPLES[221]=["He is known to everyone in the town.","彼は町の皆に知られている。","everyone"];
EXAMPLES[222]=["The children are at play in the garden.","子供達は庭で遊んでいる。","children"];
EXAMPLES[223]=["People in general are against the new law.","一般に人々は新しい法律に反対である。","general"];
EXAMPLES[224]=["I know the area around here quite well.","この辺は、よく知っています。","area"];
EXAMPLES[225]=["Here it is, all in black and white.","これです。全部書類にして持ってきたのは。","black"];
EXAMPLES[226]=["Do you want to get together after work?","仕事の後集まりたい？","together"];
EXAMPLES[227]=["It is kind of you to do so.","そうしてくれて君は親切ですね。","kind"];
EXAMPLES[228]=["This is the same car as I have.","これは私が持っているのと同じ車だ。","car"];
EXAMPLES[229]=["I got up at five in the morning.","朝の5時に起きました。","five"];
EXAMPLES[230]=["I want to punch you in the face.","お前の顔を殴りたい。","face"];
EXAMPLES[231]=["He told me the story of his life.","彼は彼の人生の話を私にしてくれた。","story"];
EXAMPLES[232]=["This is the most important matter of all.","これが全ての中で最も重要なことだ。","important"];
EXAMPLES[233]=["I hope it will be the only one.","こんなのは今日だけであってほしいわ。","hope"];
EXAMPLES[234]=["Of course, I will be at the party.","もちろん私はそのパーティーに行きます。","course"];
EXAMPLES[235]=["It is not good, to say the least.","控え目に言ってもこれは良くない。","least"];
EXAMPLES[236]=["I have wonderful news for all of you.","みんなにすばらしい知らせがあるんだ。","news"];
EXAMPLES[237]=["This is the same book as I have.","これは私が持っているのと同じ本です。","book"];
EXAMPLES[238]=["Do you have enough information to go on?","それだけの情報でやっていけますか。","information"];
EXAMPLES[239]=["Do they get up early in the morning?","彼らは朝早くおきますか。","early"];
EXAMPLES[240]=["Our children all go to the local school.","うちの子供は全員地元の学校に通っています。","local"];
EXAMPLES[241]=["Please tell me what happened – off the record, of course.","何があったか教えてください。もちろんここだけの話で。","of course"];
EXAMPLES[242]=["I was able to get him to understand.","彼にそれをわかってもらうことが出来た。","able"];
EXAMPLES[243]=["He is the right man for the post.","彼こそその地位にふさわしい人だ。","post"];
EXAMPLES[244]=["This video is not available in your country.","この動画は、お住まいの国では公開されていません。","video"];
EXAMPLES[245]=["You are too young to be in love.","君は恋するには若すぎる。","young"];
EXAMPLES[246]=["Is that the way you talk to me?","相手を見て物を言うがよい。","talk"];
EXAMPLES[247]=["It happened to me about a year ago.","一年ぐらい前に、私の身に起こったことです。","ago"];
EXAMPLES[248]=["The man took the boy by the hand.","その男は少年の手をつかまえた。","hand"];
EXAMPLES[249]=["I often talk to him on the bus.","バスの中で彼とよく喋ります。","often"];
EXAMPLES[250]=["I can do it in half the time.","私なら半時間でやれる。","half"];
EXAMPLES[251]=["The level of the school is high.","その学校のレベルは高い。","level"];
EXAMPLES[252]=["Not a single person was on the street.","通りには、人っ子一人いなかった。","single"];
EXAMPLES[253]=["Do you know what has become of him?","彼がどうしているか知っているかい？","become"];
EXAMPLES[254]=["I need to know what the problem was.","何が問題だったのか知る必要があるんだ。","problem"];
EXAMPLES[255]=["He is still sound in mind and body.","彼はまだ心身ともに健全だ。","body"];
EXAMPLES[256]=["You have to buy one at the office.","切符売り場で買わなければなりません。","office"];
EXAMPLES[257]=["My brother and I like the same food.","僕と弟は食物の好みが一緒です。","food"];
EXAMPLES[258]=["The island is to the south of Japan.","その島は日本の南のほうにある。","south"];
EXAMPLES[259]=["You should take care of your sick mother.","君は病気のお母さんの面倒をもっと見るべきだ。","take care of"];
EXAMPLES[260]=["Tom was the only guy in the class.","トムはクラスで唯一の男子だった。","guy"];
EXAMPLES[261]=["The situation got out of the government's control.","情勢は政府の力ではどうにもならなくなった。","control"];
EXAMPLES[262]=["What he said is, in a way, true.","彼の言ったことはある意味本当だ。","true"];
EXAMPLES[263]=["There is a large house on the hill.","丘の上に１軒の大きな家があります。","large"];
EXAMPLES[264]=["Would you like to wait in the room?","部屋でお待ちになりますか。","room"];
EXAMPLES[265]=["He has a lot of books on history.","彼は歴史の本をたくさん持っている。","history"];
EXAMPLES[266]=["This is the same watch as I lost.","これはわたしがなくしたのと同じ種類の時計だ。","lost"];
EXAMPLES[267]=["The girl that I like is over there.","僕が好きな女の子はあそこにいます。","girl"];
EXAMPLES[268]=["He is very difficult to get along with.","彼とうまくやっていくのは大変難しい。","along"];
EXAMPLES[269]=["The important thing to us is a friend.","私たちにとって大切なものは友達である。","friend"];
EXAMPLES[270]=["The more I think, the less I understand.","考えれば考えるほどわからなくなる。","understand"];
EXAMPLES[271]=["All in all, this was a nice party.","まあ、今日のはいいパーティーだった。","nice"];
EXAMPLES[272]=["The plans are still up in the air.","計画はまだ未定である。","air"];
EXAMPLES[273]=["Oh, that? Yeah, I heard that yesterday, then.","それなら、昨日聞いたわ。","Yeah"];
EXAMPLES[274]=["I thought that that was a good idea.","それはいい考えだと思ったよ。","idea"];
EXAMPLES[275]=["She is at the top of her class.","彼女はクラスでトップです。","class"];
EXAMPLES[276]=["I want to live close to the station.","駅から遠くないところに住みたい。","close"];
EXAMPLES[277]=["He said it was out of the question.","彼は全く不可能だと言った。","question"];
EXAMPLES[278]=["All you have to do is to wait.","ただ待ってさえいればいい。","wait"];
EXAMPLES[279]=["With all his money, he is not happy.","お金をもっていても彼は幸せではない。","happy"];
EXAMPLES[280]=["This is a man, that is a woman.","これは男です。それは女です。","woman"];
EXAMPLES[281]=["She is more human in thinking than you.","彼女はあなたよりも考え方が人間的だ。","human"];
EXAMPLES[282]=["His life was a long series of failures.","彼の生涯は長い失敗の連続だった。","series"];
EXAMPLES[283]=["Do you want to leave it like that?","そんなのでいいと思ってるの？","leave"];
EXAMPLES[284]=["How about getting the special of the day?","日替わり定食にしませんか。","special"];
EXAMPLES[285]=["In the north, it's cold in the winter.","北の方では冬が寒いです。","north"];
EXAMPLES[286]=["Who are the people I saw her with?","彼女と一緒にいた人たちは誰だろう？","saw"];
EXAMPLES[287]=["This is the same watch as I have.","これは私が持っているのと同じ時計だ。","watch"];
EXAMPLES[288]=["Before I know it, the data is gone.","いつのまにかデータがなくなってる。","data"];
EXAMPLES[289]=["I got up at 5 in the morning.","私は朝５時に起きた。","morning"];
EXAMPLES[290]=["Do I have to stay in the hospital?","入院しなければいけませんか。","stay"];
EXAMPLES[291]=["Put out the light and go to bed.","明かりを消して、寝なさい。","light"];
EXAMPLES[292]=["Are you the one who called the police?","警察に電話したのは、お前か？","police"];
EXAMPLES[293]=["It is a short drive to the park.","公園までは車ですぐです。","short"];
EXAMPLES[294]=["The truth will come out in the future.","将来真実が明らかになるだろう。","future"];
EXAMPLES[295]=["Either you or I will have to go.","あなたか私のどちらかが行かなければならないでしょう。","Either"];
EXAMPLES[296]=["The car made a turn to the left.","自動車は左折した。","turn"];
EXAMPLES[297]=["What age do you want to live to?","何歳まで生きたいですか？","age"];
EXAMPLES[298]=["Are you going to buy that or not?","それ買う気があるの？ないの？","buy"];
EXAMPLES[299]=["He is a third party to the accident.","彼はその事故には関係ありません。","third"];
EXAMPLES[300]=["The ABC company is in the red again.","ＡＢＣ会社はまた赤字だ。","red"];
EXAMPLES[301]=["He is going to be a father soon.","彼はもうすぐ父になる。","soon"];
EXAMPLES[302]=["Are you the one who wrote that report?","あの報告書を書いたのはあなたですか。","report"];
EXAMPLES[303]=["That's where the heart of the case is.","事件の核心はそこにあります。","heart"];
EXAMPLES[304]=["What time do we have to check out?","チェックアウト・タイムは何時ですか。","check"];
EXAMPLES[305]=["I filled in my name on the form.","用紙に自分の名を記入した。","form"];
EXAMPLES[306]=["Do you have any further questions to ask?","何かもっと質問がありますか。","further"];
EXAMPLES[307]=["He was really a child of his times.","彼はまさしく時代の子であった。","child"];
EXAMPLES[308]=["I knew it would be fun with you.","やっぱり、君といると楽しい。","fun"];
EXAMPLES[309]=["He is putting on an act for you.","彼は君のために一芝居打っているんだよ。","act"];
EXAMPLES[310]=["Who were you speaking to on the phone?","誰と電話で話していたのですか。","phone"];
EXAMPLES[311]=["This we can call a work of art.","これを私たちは芸術品と呼ぶ。","art"];
EXAMPLES[312]=["Do you have to go to market, too?","あなたも買い物に行かなければならないの。","market"];
EXAMPLES[313]=["We understand that he is for the plan.","彼はその計画に賛成と聞いている。","plan"];
EXAMPLES[314]=["The rest of us are to stay behind.","私たちの内残りの者はあとに残ることになっている。","behind"];
EXAMPLES[315]=["I get up at six in the morning.","私は朝６時におきます。","six"];
EXAMPLES[316]=["The town is to the west of London.","ロンドンの西に位置する町です。","west"];
EXAMPLES[317]=["Tell her not to get near the dog.","犬に近づかないよう彼女に言いなさい。","near"];
EXAMPLES[318]=["It was easy for me to do so.","私がそうすることはやさしさでした。","easy"];
EXAMPLES[319]=["You know, sometimes you need to hear it.","でもね、聞きたい時もあるのよ。","sometimes"];
EXAMPLES[320]=["That is the main street of this city.","あれがこの町の大通りだ。","street"];
EXAMPLES[321]=["The garden is in front of the house.","庭は家の前にあります。","front"];
EXAMPLES[322]=["It is her that I want to meet.","私が会いたいのは彼女なんです。","meet"];
EXAMPLES[323]=["She gave all her time to the study.","彼女は時間を全部その研究に注いだ。","study"];
EXAMPLES[324]=["I have to go there for my father.","私は父の代わりにそこへ行かなければならない。","father"];
EXAMPLES[325]=["Do you know the words to this song?","この歌の歌詞って、わかる？","song"];
EXAMPLES[326]=["March is the third month of the year.","「３月」は１年の中で３回目の月にあたります。","March"];
EXAMPLES[327]=["That's too bad. Please take care of yourself.","それはお気の毒に。お体を大切に。","That's too bad"];
EXAMPLES[328]=["January is the first month of the year.","一月は年の一番目の月です。","month"];
EXAMPLES[329]=["No one is here. They are all outside.","それらは一つもない。全て外にある。","outside"];
EXAMPLES[330]=["I gave her all the money I had.","ありったけの金を彼女に与えた。","gave"];
EXAMPLES[331]=["She is a kind of mother to me.","彼女は私には母親みたいなものです。","mother"];
EXAMPLES[332]=["I want to see you for a moment.","ちょっと会いたいのだけれど。","moment"];
EXAMPLES[333]=["This is the town I told you about.","ここが前に話した街です。","town"];
EXAMPLES[334]=["I was in London most of the summer.","夏の大半私はロンドンにいた。","summer"];
EXAMPLES[335]=["I would like to have a rest here.","ここで一休みしたいものです。","rest"];
EXAMPLES[336]=["I think it's fine the way it is.","このままでもいいと思います。","fine"];
EXAMPLES[337]=["What is more, he has a strong will.","おまけに彼は意志が強い。","strong"];
EXAMPLES[338]=["This is too good a chance to miss.","これは失うにはあまりにも惜しい機会だ。","miss"];
EXAMPLES[339]=["It was a beautiful day for a walk.","散歩日和だった。","beautiful"];
EXAMPLES[340]=["Would you like to go on a date?","デートしませんか？","date"];
EXAMPLES[341]=["He will stay here for a long period.","彼は長い期間ここに滞在するだろう。","period"];
EXAMPLES[342]=["We have a lot of rain in June.","六月には雨が多い。","June"];
EXAMPLES[343]=["I will be in high school next April.","私は来年の四月に学校に入っています。","April"];
EXAMPLES[344]=["He is the best player on our team.","彼は我々のチームで最もすぐれた選手である。","player"];
EXAMPLES[345]=["He is, so to speak, a star player.","彼はいわばスタープレーヤーだ。","star"];
EXAMPLES[346]=["I have to prepare for the English test.","僕は英語の試験の準備をしなければいけない。","English"];
EXAMPLES[347]=["I will come to you in an hour.","１時間して君のところに行きます。","hour"];
EXAMPLES[348]=["In any event, I will do my best.","とにかく最善を尽くします。","event"];
EXAMPLES[349]=["All right! You will be sorry for this.","よーし！覚えてろ。後で悔やむなよ。","sorry"];
EXAMPLES[350]=["The more you study the more you learn.","勉強すればするほど分かる。","learn"];
EXAMPLES[351]=["Do you know the boy in this picture?","この写真の男の子、知ってる？","boy"];
EXAMPLES[352]=["I guess there was some talk of that.","そういう話もあったな。","guess"];
EXAMPLES[353]=["The eagle is the king of the air.","鷲は空の王者です。","king"];
EXAMPLES[354]=["July is the seventh month of the year.","「７月」は１年の中で７回目の月にあたります。","July"];
EXAMPLES[355]=["He played an important role on the committee.","彼は委員会の中で重要な役割を果たした。","role"];
EXAMPLES[356]=["Would you like to go to a movie?","映画見に行かない？","movie"];
EXAMPLES[357]=["I used to go to church on Sunday.","昔、日曜日には教会へ行ったものだ。","church"];
EXAMPLES[358]=["It is too hot a day for work.","今日は仕事をするのには暑すぎる。","hot"];
EXAMPLES[359]=["The course of the ship was straight east.","船の進路は真東だった。","east"];
EXAMPLES[360]=["This will be a walk in the park.","こんなのちょちょいのちょいだよ。","park"];
EXAMPLES[362]=["Not a sound was heard in the room.","部屋には物音一つ聞こえなかった。","sound"];
EXAMPLES[363]=["I usually get to work at about 8.30.","普段は、8時半ぐらいに出勤します。","usually"];
EXAMPLES[364]=["She got a cool million dollars a day.","彼女は１日で大枚１００万ドルも手に入れた。","cool"];
EXAMPLES[365]=["It's already September; however, it is very hot.","もう９月なのに、めちゃ暑いな。","September"];
EXAMPLES[366]=["We all stand by you to the last.","私たちはあなたを最後まで支持します。","stand"];
EXAMPLES[367]=["I was reading a book at the time.","私はその時本を読んでいました。","reading"];
EXAMPLES[368]=["It is true that the earth is round.","地球が丸いというのは真実だ。","round"];
EXAMPLES[369]=["He has no friends to fall back on.","彼には頼れる友人がいない。","fall"];
EXAMPLES[370]=["Is this to eat here, or to go?","持ち帰りですか。それともここでたべますか。","eat"];
EXAMPLES[371]=["I want to take a picture of that.","それの写真を撮りたい。","picture"];
EXAMPLES[372]=["Do you know why the sky is blue?","なぜ空が青いか知っているか。","blue"];
EXAMPLES[373]=["What is that building with the green roof?","屋根が緑色の建物は何ですか。","green"];
EXAMPLES[374]=["Is that as fast as you can go?","その速さで精一杯ですか。","fast"];
EXAMPLES[375]=["I felt like I had to say something.","何かを言わなければいけない気がした。","felt"];
EXAMPLES[376]=["Tell me what you are looking forward to.","あなたが何を楽しみにしているのか私に教えて下さい。","forward"];
EXAMPLES[377]=["You find that it is shaped by science.","それが科学によって形作られていることが分かる。","science"];
EXAMPLES[378]=["This is John and that is his brother.","この人がジョンで、あの人は兄さんだ。","brother"];
EXAMPLES[379]=["There is a little water in the cup.","カップにはちょっと水が入っている。","cup"];
EXAMPLES[380]=["We cannot do the work in a day.","その仕事は1日ではできない。","cannot"];
EXAMPLES[381]=["I'm going to come to Boston in October.","１０月にボストンに来る予定だ。","October"];
EXAMPLES[382]=["Why is this only in a foreign language?","なんでこれだけ外国語？","language"];
EXAMPLES[383]=["My dog is the bigger of the two.","うちの犬は２匹のうち大きいほうです。","dog"];
EXAMPLES[384]=["It rains a lot from May to August.","雨がよく降るのは、５月から８月にかけてです。","August"];
EXAMPLES[385]=["It was in October or November of 2003.","2003年の10月か11月だった。","November"];
EXAMPLES[386]=["He is in a poor state of health.","彼の健康状態はよくない。","poor"];
EXAMPLES[387]=["Enjoy your life while you are able to.","できるあいだに人生を楽しみなさい。","Enjoy"];
EXAMPLES[388]=["The first month of the year is January.","一年の最初の月は一月です。","January"];
EXAMPLES[389]=["This is too good a chance to lose.","これは逃すのはもったいないチャンスだ。","lose"];
EXAMPLES[390]=["He looked for the key to the door.","彼は、そのドアのかぎを探した。","door"];
EXAMPLES[391]=["I have a bone to pick with you.","あなたに不満があります。","pick"];
EXAMPLES[392]=["I would like to have my hair cut.","散髪して下さい。","hair"];
EXAMPLES[393]=["Have you ever been to a foreign country?","外国へ行ったことがありますか？","foreign"];
EXAMPLES[394]=["I have to be back home by seven.","７時までに家に帰らなくてはならない。","seven"];
EXAMPLES[395]=["Would you like to go for a walk?","ちょっと散歩に行かない？","walk"];
EXAMPLES[396]=["Is it really that difficult to do that?","それをするのって本当にそんな難しいことなの？","difficult"];
EXAMPLES[397]=["I was in the hospital for a week.","一週間入院していたんです。","hospital"];
EXAMPLES[398]=["I was just about to go to bed.","ちょうど寝るところだったんだよ。","bed"];
EXAMPLES[399]=["He is popular with the people at large.","彼は一般に人々に人気がある。","popular"];
EXAMPLES[400]=["December is the last month of the year.","十二月は一年の最後の月です。","December"];
EXAMPLES[401]=["To know is one thing, to practice another.","知っていることと実行することは別物だ。","practice"];
EXAMPLES[402]=["Please listen to what I have to say.","俺の言うことちょっと聞いてよ。","listen"];
EXAMPLES[403]=["Please forget this, for the love of God.","頼むから、このことは忘れてくれ。","forget"];
EXAMPLES[404]=["You can see the sea on your right.","右手に海が見えますよ。","sea"];
EXAMPLES[405]=["Another step, and you will fall down the precipice.","もう一歩進めばあなたはがけから落ちるでしょう。","fall down"];
EXAMPLES[406]=["What do you do to pass the time?","何をして時間をつぶしますか。","pass"];
EXAMPLES[407]=["I pushed the table out of the way.","私はそのテーブルが邪魔にならないように押しのけた。","table"];
EXAMPLES[408]=["Ten to one he will forget about it.","十中八九、彼はそのことを忘れるだろう。","Ten"];
EXAMPLES[409]=["You are not to sleep in this room.","あなたはこの部屋で眠ったらいけません。","sleep"];
EXAMPLES[410]=["I had a man build me a house.","私はある人に家を建ててもらった。","build"];
EXAMPLES[411]=["What do you think is in this box?","この箱には何が入ってると思う？","box"];
EXAMPLES[412]=["Go straight, and you will find the station.","真っ直ぐ行きなさい、そうすれば駅が見えます。","straight"];
EXAMPLES[413]=["The money on the desk is not mine.","机の上のお金は私のものではありません。","mine"];
EXAMPLES[414]=["I look forward to hearing your thoughts on this matter.","これにつきまして、お考えをお聞かせ願えればと存じます。","look forward to"];
EXAMPLES[415]=["It is Paris that I want to visit.","私が訪れたいのはパリです。","visit"];
EXAMPLES[416]=["He stood with his back to the wall.","彼は背を壁に向けて立っていた。","wall"];
EXAMPLES[417]=["May I speak to you for a moment?","少しお話ししてもよろしいですか。","speak"];
EXAMPLES[418]=["The water of the river was very clear.","川の水はとても澄んでいた。","river"];
EXAMPLES[419]=["February is the second month of the year.","「２月」は１年の中で２回目の月にあたります。","February"];
EXAMPLES[420]=["I have no time to write to her.","私は彼女に手紙を書く時間がない。","write"];
EXAMPLES[421]=["At that time, I was still a student.","その当時、私はまだ学生であった。","student"];
EXAMPLES[422]=["It happened in the blink of an eye.","あっと言う間の出来事でした。","eye"];
EXAMPLES[423]=["He got up at eight in the morning.","彼は午前８時に起きました。","eight"];
EXAMPLES[424]=["It was dark and cold in the room.","部屋の中は暗くて寒かった。","cold"];
EXAMPLES[425]=["I have to go to the hospital tomorrow.","明日は、病院に行かないといけないんだ。","tomorrow"];
EXAMPLES[426]=["It is funny for him to say so.","彼がそういうなんて変だ。","funny"];
EXAMPLES[427]=["Is this the right way to the station?","駅へはこの道を行けばいいのですか。","station"];
EXAMPLES[428]=["We can see the island in the distance.","遠方にその島が見える。","island"];
EXAMPLES[429]=["Who is the woman in the brown coat?","茶色のコートを着た女性は誰ですか。","brown"];
EXAMPLES[430]=["It is to your advantage to join us.","私たちの仲間に入るのが有利だ。","join"];
EXAMPLES[431]=["The world is changing more and more quickly.","世界はますます急速に変化している。","quickly"];
EXAMPLES[432]=["The movie was interesting to all of us.","その映画は私達みんなにとって興味深かった。","interesting"];
EXAMPLES[433]=["I want to travel all over the world.","世界中を旅行をしたいんだ。","travel"];
EXAMPLES[434]=["Be careful not to slip on the ice.","氷の上で滑らないように注意しなさいね。","ice"];
EXAMPLES[435]=["Be sure to drop in at my house.","必ず私の家に立ち寄りなさい。","drop"];
EXAMPLES[437]=["You are welcome to do anything you like.","君は勝手に好きな事をしてよろしい。","welcome"];
EXAMPLES[438]=["Can I talk to you for a minute?","少しだけ、話してもいい？","minute"];
EXAMPLES[439]=["I want to sell everything in this room.","この部屋にあるもの全部、売っちゃいたい。","sell"];
EXAMPLES[440]=["We are subject to the laws of nature.","われわれは自然の法則に従う。","nature"];
EXAMPLES[441]=["I want to spend my life with you.","ずっと一緒にいたいです。","spend"];
EXAMPLES[442]=["It was my turn to clean the room.","私が部屋を掃除する番にあたっていた。","clean"];
EXAMPLES[443]=["What is your favorite song on this album?","このアルバムの中で、一番好きな曲ってどれ？","favorite"];
EXAMPLES[444]=["He would have his say on the subject.","彼はその問題について自分の意見を述べるといってきかなかった。","subject"];
EXAMPLES[445]=["He will be in time for the train.","彼は列車に間に合うでしょう。","train"];
EXAMPLES[446]=["What do you plan to do on Friday?","あなたは金曜日に何をするつもりですか。","Friday"];
EXAMPLES[447]=["He keeps to the letter of the law.","彼は法律の条文の意味に固執する。","letter"];
EXAMPLES[448]=["That man is in love with my sister.","あの人は私の姉に恋しているのです。","sister"];
EXAMPLES[449]=["What subject do you think he is interested in?","君は彼がどの学科に興味を持っていると思いますか。","interested in"];
EXAMPLES[450]=["It's on the first floor of that building.","あのビルの一階にあります。","floor"];
EXAMPLES[451]=["I can see a ship in the distance.","ずっと遠くに船が見える。","ship"];
EXAMPLES[452]=["Spring is the season I like the best.","春は、私が一番好きな季節です。","Spring"];
EXAMPLES[453]=["In the summer, people go to the beach.","夏になると人々は海辺へ行く。","beach"];
EXAMPLES[454]=["Is Sunday the first day of the week?","日曜日が１週間の最初の日ですか。","Sunday"];
EXAMPLES[455]=["I had to choose between A and B.","私はＡかＢのどちらかを選ばなくてはならなかった。","choose"];
EXAMPLES[456]=["In a sense, life is only a dream.","ある意味では、人生は夢にすぎない。","dream"];
EXAMPLES[457]=["It is said that he was very rich.","彼は以前、大変な金持ちだったと言われる。","rich"];
EXAMPLES[458]=["I want to get in touch with her.","私は彼女と連絡をとりたい。","touch"];
EXAMPLES[459]=["You can easily see the politician in him.","彼には容易に政治家としての態度が見うけられる。","easily"];
EXAMPLES[460]=["I was to have finished the work yesterday.","私はその仕事を昨日終える予定だったが終えることができなかった。","yesterday"];
EXAMPLES[461]=["The sound of the violin is very sweet.","バイオリンの音色はとても美しい。","sweet"];
EXAMPLES[462]=["He had the luck to catch the train.","彼は運よく列車に間に合った。","luck"];
EXAMPLES[463]=["The book I bought is on the desk.","僕の買った本は机の上にあるよ。","bought"];
EXAMPLES[464]=["What color is the roof of your house?","君んちの屋根って、何色なの？","color"];
EXAMPLES[465]=["Who is going to sit in for you?","誰が君の代わりをするんだい。","sit"];
EXAMPLES[466]=["Should I go with you to the doctor?","私も一緒にお医者さんのところに行った方がいい？","doctor"];
EXAMPLES[467]=["How is it going in the fish market?","魚市場の景気はどうですか。","fish"];
EXAMPLES[468]=["I really want to go on a trip.","旅行にめっちゃ行きたい。","trip"];
EXAMPLES[469]=["Would you like to go have a drink?","どこかへ飲みに行きましょうか。","drink"];
EXAMPLES[470]=["I came to Japan for the first time.","私は初めて日本に来た。","Japan"];
EXAMPLES[471]=["Does it snow a lot in the winter?","冬に雪がたくさん降りますか。","winter"];
EXAMPLES[472]=["What do you think of the new teacher?","新しい先生についてどう思いますか。","teacher"];
EXAMPLES[473]=["Is there a photo shop in the hotel?","ホテルの中に写真屋はありますか。","shop"];
EXAMPLES[474]=["The sick person had the best of care.","その病人は最上の看護を受けた。","sick"];
EXAMPLES[475]=["We have to be at work by nine.","私たちは９時までに仕事に出ていなければならない。","nine"];
EXAMPLES[476]=["We sat at the back of the hall.","私たちは会場の後ろに座った。","hall"];
EXAMPLES[477]=["Saturday is the day when he is free.","土曜日は彼が暇な日です。","Saturday"];
EXAMPLES[478]=["The weather is as fine as can be.","天気はこの上なくいい。","weather"];
EXAMPLES[479]=["The office was full of activity all day.","その事務所は一日中活気に満ちていた。","activity"];
EXAMPLES[480]=["Are you always at home in the evening?","あなたは晩にはいつもご在宅ですか。","evening"];
EXAMPLES[481]=["The women are in front of the library.","その女性達は図書館の前にいる。","library"];
EXAMPLES[482]=["The Queen made an address to the nation.","女王は国民に向けて演説をした。","Queen"];
EXAMPLES[483]=["I can find a tree by the house.","私は家のそばに木を見つけることができます。","tree"];
EXAMPLES[484]=["His speech was short and to the point.","彼のスピーチは短くて要領を得ていた。","speech"];
EXAMPLES[485]=["Can I ride this horse for a while?","しばらくこの馬に乗ってもいいですか。","ride"];
EXAMPLES[486]=["It's the most wonderful time of the year.","一年で一番素敵な時期です。","wonderful"];
EXAMPLES[487]=["Flower arrangement is a traditional art in Japan.","生け花は日本では伝統的な芸道である。","traditional"];
EXAMPLES[488]=["I know that he is a famous musician.","私は彼が有名な音楽家であることを知っている。","famous"];
EXAMPLES[489]=["The old castle is in a sad state.","その古城は荒れ果てている。","sad"];
EXAMPLES[490]=["Why do you have such a big mouth?","どうしてそんなに大きなお口なの？","mouth"];
EXAMPLES[491]=["April is the fourth month of the year.","四月は一年の４番目の月です。","fourth"];
EXAMPLES[492]=["The lake is a long way from here.","湖はここから遠く離れている。","lake"];
EXAMPLES[493]=["It is a long way to the village.","村まで長い道のりだ。","village"];
EXAMPLES[494]=["Some of the students like to draw pictures.","その生徒達の中には絵を描くのが好きなものもいる。","draw"];
EXAMPLES[495]=["It's the animal in me that wants it.","それを欲するのは私の中の獣性だ。","animal"];
EXAMPLES[496]=["I have a clear memory of my childhood.","子供の頃のことをよくおぼえている。","memory"];
EXAMPLES[497]=["I want to be able to read Japanese.","日本語を読めるようになりたいです。","Japanese"];
EXAMPLES[498]=["I need to be in Paris on Monday.","月曜日にパリにいなきゃいけないんだ。","Monday"];
EXAMPLES[499]=["Do you want me to open the window?","窓を開けましょうか。","window"];
EXAMPLES[500]=["The win is still not in the bag.","勝利はまだ手の内にない。","bag"];
EXAMPLES[501]=["Would you like to have dinner with me?","晩ご飯をご一緒にどうですか？","dinner"];
EXAMPLES[502]=["I let the cat out of the house.","私は猫を家の外に出した。","cat"];
EXAMPLES[503]=["The fifth volume of this set is missing.","この全集の５巻目が見当たらない。","fifth"];
EXAMPLES[504]=["She held on to it for dear life.","彼女はそれを後生大事にとっておいた。","dear"];
EXAMPLES[505]=["This is the longest bridge in the world.","この橋はもっとも長い橋だ。","bridge"];
EXAMPLES[506]=["The man was no better than a horse.","その男は、馬同然であった。","horse"];
EXAMPLES[507]=["Do you know how to read a map?","地図の見方って、わかる？","map"];
EXAMPLES[508]=["It happened that the day was my birthday.","たまたまその日は私の誕生日でした。","birthday"];
EXAMPLES[509]=["My daughter is the apple of my eye.","娘は目に入れても痛くない。","apple"];
EXAMPLES[510]=["It's not much of a surprise, is it?","そんなに驚くことじゃないよね？","surprise"];
EXAMPLES[511]=["He is not always busy in the morning.","彼は午前中はかならずしも忙しくない。","busy"];
EXAMPLES[512]=["I am no more excited than you are.","あなた同様私は興奮などしていない。","excited"];
EXAMPLES[513]=["That is the highest mountain in the world.","あれは世界一高い山です。","mountain"];
EXAMPLES[514]=["It seems to me that he is honest.","私には彼は正直なように思われる。","honest"];
EXAMPLES[515]=["Soccer is the best sport of the world!","サッカーは世界で一番のスポーツだ！","sport"];
EXAMPLES[516]=["Can you make me a cup of tea?","お茶を淹れてくれない？","tea"];
EXAMPLES[517]=["I arrived just in time for the plane.","私は飛行機にやっと間に合った。","plane"];
EXAMPLES[518]=["I have a lot to do this afternoon.","今日の午後しなければならない事がたくさんあります。","afternoon"];
EXAMPLES[519]=["I had to go home and change clothes.","家に帰って着替えなきゃいけなかったんだよ。","clothes"];
EXAMPLES[520]=["I would like to see the festival.","そのお祭りを見たいのですが。","festival"];
EXAMPLES[521]=["She is likely to live to one hundred.","彼女は１００歳まで生きられそうだ。","hundred"];
EXAMPLES[522]=["It is warm there all the year round.","そこは一年中暖かい。","warm"];
EXAMPLES[523]=["I could not bear to see the scene.","その光景は見るに堪えなかった。","bear"];
EXAMPLES[524]=["Is this the right way to the museum?","博物館へはこの道で良いのでしょうか。","museum"];
EXAMPLES[525]=["As I was tired, I took a rest.","疲れているので休んだ。","tired"];
EXAMPLES[526]=["The chair is in front of the door.","その椅子はドアの前にあります。","chair"];
EXAMPLES[527]=["I was too glad not to jump up.","嬉しさのあまりとび上がった。","jump"];
EXAMPLES[528]=["All the flowers in the garden are yellow.","庭の花はすべて黄色だ。","yellow"];
EXAMPLES[529]=["Would you like to go shopping with me?","買い物一緒に行く？","shopping"];
EXAMPLES[530]=["I like to sleep on a soft bed.","私は柔らかいベッドで眠るのが好きです。","soft"];
EXAMPLES[531]=["Will you teach me how to make this?","これの作り方を教えてくれる？","teach"];
EXAMPLES[532]=["This drama will be on the air tomorrow.","この劇はあす放送される。","drama"];
EXAMPLES[533]=["A ball hit her on the right leg.","ボールが彼女の右足に当たった。","leg"];
EXAMPLES[534]=["You should perform regular maintenance on your car.","あなたは車の定期点検をすべきです。","perform"];
EXAMPLES[535]=["What do you want to have for lunch?","お昼何食べたい？","lunch"];
EXAMPLES[536]=["We have a lot of snow in February.","二月には雪が多い。","snow"];
EXAMPLES[537]=["The cook served the family for many years.","コックは家族に長年仕えた。","cook"];
EXAMPLES[538]=["The mother told the children to be quiet.","母親は子供たちに静かにするように言った。","quiet"];
EXAMPLES[539]=["The actor is two years senior to me.","その俳優は私より２歳年上だ。","actor"];
EXAMPLES[540]=["She is on the wrong side of twenty.","彼女は２０歳を越えている。","twenty"];
EXAMPLES[541]=["That baby is really not cute at all.","あの赤ちゃんは本当に可愛くないね。","cute"];
EXAMPLES[542]=["There are about a thousand students in all.","生徒は全部で約千人です。","thousand"];
EXAMPLES[543]=["He had a big smile on his face.","満面の笑みだったよ。","smile"];
EXAMPLES[544]=["The bird on the roof is a crow.","屋根の上にいる鳥はからすです。","bird"];
EXAMPLES[545]=["We had to drive slowly all the way.","私達は道すがらずっと低速で運転しなければならなかった。","slowly"];
EXAMPLES[546]=["Which came first, the chicken or the egg?","タマゴが先か、ニワトリが先か？","chicken"];
EXAMPLES[547]=["Today is the last Tuesday of the month.","今日は今月最後の火曜日です。","Tuesday"];
EXAMPLES[548]=["I will be here from Monday to Thursday.","月曜から木曜までここにおります。","Thursday"];
EXAMPLES[549]=["What do you want to eat for breakfast?","朝ご飯に何が食べたい？","breakfast"];
EXAMPLES[550]=["The cost of the painting is very high.","その絵の値段はとても高い。","painting"];
EXAMPLES[551]=["Can I have a look at your newspaper?","ちょっと新聞を見せてもらえませんか。","newspaper"];
EXAMPLES[552]=["I am not more careful than you are.","私は君ほど注意深くない。","careful"];
EXAMPLES[553]=["We have to submit an essay by Wednesday.","水曜日までに小論文を提出しなくてはなりません。","Wednesday"];
EXAMPLES[554]=["He has no sympathy for single parent families.","彼には片親の家族に対する同情が全くない。","parent"];
EXAMPLES[555]=["What kind of fruit do you like best?","どんな種類の果物が一番好きですか。","fruit"];
EXAMPLES[556]=["It is a great pleasure to be here.","ここにいるのはとても楽しい。","pleasure"];
EXAMPLES[557]=["I want to excuse myself from the work.","私はその仕事を辞退したい。","excuse"];
EXAMPLES[558]=["The price of rice is going up again.","米の値段が再び上がっている。","rice"];
EXAMPLES[559]=["I would like you to sing a song.","あなたに歌を歌ってもらいたい。","sing"];
EXAMPLES[560]=["I have been to see the baseball game.","私は野球の試合を見に行ってきました。","baseball"];
EXAMPLES[561]=["It is an exciting time of the year.","１年中での楽しい時期です。","exciting"];
EXAMPLES[562]=["It is too small a hat for you.","その帽子はあなたには小さすぎる。","hat"];
EXAMPLES[563]=["It's a dull job to clean a bike.","自転車の掃除は退屈だ。","bike"];
EXAMPLES[564]=["You can have any cake on the table.","テーブルのケーキはどれを食べてもいい。","cake"];
EXAMPLES[565]=["The singer is going to be a hit.","その歌手は売れっ子になるだろう。","singer"];
EXAMPLES[566]=["My nose runs whenever I have a cold.","風邪を引くと私はいつも鼻水が出る。","nose"];
EXAMPLES[567]=["I put on my cap to go out.","私は外に出るために帽子をかぶった。","cap"];
EXAMPLES[568]=["I felt a severe pain in the shoulder.","肩に激痛を感じた。","shoulder"];
EXAMPLES[569]=["There is enough bread for all of you.","君たち全員に足りるだけのパンはある。","bread"];
EXAMPLES[570]=["I made out a tower in the distance.","遠くにかすかに塔が見えた。","tower"];
EXAMPLES[571]=["He is junior to me by two years.","彼は私より２歳年下だ。","junior"];
EXAMPLES[572]=["It is about the size of an egg.","それは卵くらいの大きさです。","egg"];
EXAMPLES[573]=["Well, it's all come out in the wash.","そうね。いずれ分かることね。","wash"];
EXAMPLES[574]=["Look Mom! I got an A in math!","ママ見て！数学でSを取ったよ！","math"];
EXAMPLES[575]=["How did you know that I was hungry?","私がお腹を空かしてたってどうしてわかったの？","hungry"];
EXAMPLES[576]=["My uncle is the manager of this hotel.","私の叔父はこのホテルの支配人です。","uncle"];
EXAMPLES[577]=["That is the temple which they live in.","あれは彼らが住んでいる寺です。","temple"];
EXAMPLES[578]=["I always take a bath in the morning.","私は毎朝、入浴することにしている。","bath"];
EXAMPLES[579]=["At last, I graduated from junior high school.","やっと中学を卒業しました。","junior high school"];
EXAMPLES[580]=["He listened with his ear to the door.","彼はドアに耳を押し当てて聞いていた。","ear"];
EXAMPLES[581]=["This desk is as good as that one.","この机はあの机と同じくらい上等です。","desk"];
EXAMPLES[582]=["Who is the boy swimming in the river?","川で泳いでいる少年は誰ですか。","swimming"];
EXAMPLES[583]=["This is an old type of American clock.","これは古い型のアメリカの時計です。","clock"];
EXAMPLES[584]=["This girl is the flower of the school.","あの娘は学校の花です。","flower"];
EXAMPLES[585]=["Please throw away your trash from this room.","ごみをこの部屋から捨てて下さい。","trash"];
EXAMPLES[586]=["May I use the telephone for a while?","ちょっと電話を貸していただけますか。","telephone"];
EXAMPLES[587]=["I have a cousin who is a lawyer.","私には弁護士のいとこがいる。","cousin"];
EXAMPLES[588]=["Why do you want to be a nurse?","なぜ看護婦になりたいのですか。","nurse"];
EXAMPLES[589]=["I expect to take a vacation in May.","私は５月に休暇をとるつもりだ。","vacation"];
EXAMPLES[590]=["He was the last but two to arrive.","彼は終わりから３番目に着いた。","arrive"];
EXAMPLES[591]=["There are about thirty people in this room.","この部屋には30人ぐらいいます。","thirty"];
EXAMPLES[592]=["June is the sixth month of the year.","「６月」は１年の中で６回目の月にあたります。","sixth"];
EXAMPLES[593]=["We collect stamps from all around the world.","僕たちは全世界の切手を集める。","collect"];
EXAMPLES[594]=["I don't know how to spell the word.","私はその単語のつづりがわかりません。","spell"];
EXAMPLES[595]=["One has to do one's best in anything.","何事にも最善を尽くさなければならない。","do one's best"];
EXAMPLES[596]=["What is on at the theater this month?","その劇場の今月の出し物はなんですか。","theater"];
EXAMPLES[597]=["Twelve years old is old for a dog.","１２歳といえば犬は年寄りだ。","Twelve"];
EXAMPLES[598]=["I ate at the side of my friend.","僕は友達の隣で食べた。","ate"];
EXAMPLES[599]=["Thank you for the chocolate. It was delicious.","チョコありがとう。おいしかったよ。","delicious"];
EXAMPLES[600]=["I played with the baby on my knee.","赤ん坊を膝の上であやした。","knee"];
EXAMPLES[601]=["The gray sweater I like more than the purple.","紫色のセーターより灰色のセーターの方が好きです。","purple"];
EXAMPLES[602]=["A mouse is running about in the room.","ネズミが一匹部屋の中を走りまわっている。","mouse"];
EXAMPLES[603]=["In her elementary school days, Mary dreamed of becoming a teacher.","メアリーは小学生のころ先生になることを夢見ていた。","elementary school"];
EXAMPLES[604]=["The man wore a mask of a tiger.","その男はトラの面をかぶっていた。","tiger"];
EXAMPLES[605]=["The cold was the worst in fifty years.","この寒さは５０年ぶりのひどさでした。","fifty"];
EXAMPLES[606]=["Do you have a beef with me?","私に何か文句でも？","beef"];
EXAMPLES[607]=["The leaves fall to the ground in autumn.","秋には木の葉が地面に落ちる。","autumn"];
EXAMPLES[608]=["I was lonely, with nobody to play with.","遊び相手がなくて孤独だった。","lonely"];
EXAMPLES[609]=["An odd shoe was left on the doorstep.","片方の靴が戸口の階段に残されていた。","shoe"];
EXAMPLES[610]=["My grandfather has made me what I am.","祖父が私を今日の私にしてくれた。","grandfather"];
EXAMPLES[611]=["I would like to brush up my English.","私は英語にみがきをかけたい。","brush"];
EXAMPLES[612]=["I froze at the sight of the snake.","ヘビを見て足がすくんでしまった。","snake"];
EXAMPLES[613]=["The higher you climb, the greater the fall.","上へ昇れば昇るほど、それだけ墜落の程度は大きくなる。","climb"];
EXAMPLES[614]=["Do you feel like you have a fever?","熱がありそう？","fever"];
EXAMPLES[615]=["He is said to be a great scientist.","彼は偉大な科学者であると言われている。","scientist"];
EXAMPLES[616]=["This dish is more delicious than that one.","この料理はあの料理よりおいしい。","dish"];
EXAMPLES[617]=["I would like to go for a swim.","泳ぎに行きたいものです。","swim"];
EXAMPLES[618]=["He was hard on forty at the time.","当時彼は４０歳になるところだった。","forty"];
EXAMPLES[619]=["August is the eighth month of the year.","「８月」は１年の中で８回目の月にあたります。","eighth"];
EXAMPLES[620]=["He is the black sheep of the family.","あいつは一家のつらよごし。","sheep"];
EXAMPLES[621]=["The garbage is giving off a terrible smell.","そのゴミはひどいにおいを出している。","garbage"];
EXAMPLES[622]=["They live in the house opposite to ours.","あの人たちは私たちの家の真向いの家に住んでいる。","ours"];
EXAMPLES[623]=["My aunt will come here for a week.","叔母がここに一週間泊りにやってくる。","aunt"];
EXAMPLES[624]=["The fact is that my cat is shy.","実はわたしの猫は恥ずかしがり屋なのです。","shy"];
EXAMPLES[625]=["There is a tall man in the classroom.","教室に背の高い男の人が一人います。","classroom"];
EXAMPLES[626]=["The farmer plants the corn in the spring.","農夫は春にとうもろこしの種をまく。","farmer"];
EXAMPLES[627]=["You have the choice of soup or salad.","スープかサラダのどちらかを選べます。","salad"];
EXAMPLES[628]=["Do you like the taste of the soup?","そのスープの味は好きですか？","soup"];
EXAMPLES[629]=["My grandmother is the oldest in this town.","祖母はこの町で最高齢です。","grandmother"];
EXAMPLES[630]=["What were you like when you were fifteen?","15のとき、君はどんな子だった？","fifteen"];
EXAMPLES[631]=["Be careful! There's a cow in the road!","気をつけて！道路に牛がいるんだ。","cow"];
EXAMPLES[632]=["2019 is the Year of the Pig.","2019年は亥年です。","Pig"];
EXAMPLES[633]=["The boy has never been to the zoo.","その男の子は今までに動物園に行ったことがない。","zoo"];
EXAMPLES[634]=["I have a lot of homework to do.","宿題がたくさんある。","homework"];
EXAMPLES[635]=["I go to bed at eleven every night.","私は毎晩１１時に寝る。","eleven"];
EXAMPLES[636]=["He told me to be here at noon.","彼は私に正午にここへ来るように言った。","noon"];
EXAMPLES[637]=["Tom has been beating the drum for the project.","トムはそのプロジェクトをずいぶん宣伝しているよ。","drum"];
EXAMPLES[638]=["Did you put a stamp on the envelope?","封筒には切手を貼りましたか？","stamp"];
EXAMPLES[639]=["I have kept a diary for three years.","私は三年間日記をつけている。","diary"];
EXAMPLES[640]=["You could say she has a sweet tooth.","彼女は甘いものに目がないといっていいでしょう。","tooth"];
EXAMPLES[641]=["He climbed up the tree like a monkey.","彼は猿のように木によじ登った。","monkey"];
EXAMPLES[642]=["I think that this is a sunny spot.","ここは陽だまりだと思うね。","sunny"];
EXAMPLES[643]=["September is the ninth month of the year.","「９月」は１年の中で９回目の月にあたります。","ninth"];
EXAMPLES[644]=["What are you going to name your doll?","お人形さん、何ていう名前にするの？","doll"];
EXAMPLES[645]=["Next year is the year of the rabbit.","来年は卯年です。","rabbit"];
EXAMPLES[646]=["I struggled to get out of the subway.","地下鉄から出るのに私はもがいた。","subway"];
EXAMPLES[647]=["This is the best dictionary that I have.","これが私の持っている一番いい辞書です。","dictionary"];
EXAMPLES[648]=["He has something of the musician in him.","彼には音楽家の素質がある。","musician"];
EXAMPLES[649]=["Can I borrow this for a little while?","少しの間、これを借りてもいいですか？","borrow"];
EXAMPLES[650]=["He married his daughter to a bank clerk.","彼は娘を銀行員にとつがせた。","clerk"];
EXAMPLES[651]=["Jerry is the bean counter for our company.","ジェリーは僕らの会社でお金の計算だけしている。","bean"];
EXAMPLES[652]=["That is the same bicycle as I have.","あれは私が持っているのと同じ自転車です。","bicycle"];
EXAMPLES[653]=["His car was blue and hers was red.","彼の車は青で、彼女のは赤だった。","hers"];
EXAMPLES[654]=["I have a headache but no other symptoms.","頭痛はありますが、他の症状はありません。","headache"];
EXAMPLES[655]=["Our car happened to pass theirs by the station.","私たちの車は駅の近くでたまたま彼らの車とすれ違った。","theirs"];
EXAMPLES[656]=["Do you have a pen or a pencil?","ペンか鉛筆を持っていますか。","pencil"];
EXAMPLES[657]=["Now you are sixteen, you should know better.","もう１６歳なのだから、もっと分別をもちなさいよ。","sixteen"];
EXAMPLES[658]=["Everything is hard. I'm throwing in the towel.","何もかもが難しい。お手上げだい。","towel"];
EXAMPLES[659]=["The tomato is a vegetable, not a fruit.","トマトは野菜で、果物ではない。","vegetable"];
EXAMPLES[660]=["Most people retire at the age of sixty.","たいていの人は６０歳で退職する。","sixty"];
EXAMPLES[661]=["October is the tenth month of the year.","「１０月」は１年の中で１０回目の月にあたります。","tenth"];
EXAMPLES[662]=["The airplane was just going to take off.","飛行機は離陸せんばかりであった。","airplane"];
EXAMPLES[663]=["I left a new umbrella in the bus.","新しい傘をバスの中に置き忘れた。","umbrella"];
EXAMPLES[664]=["The boy threw a stone at the frog.","その少年はカエルめがけて石ころを投げた。","frog"];
EXAMPLES[665]=["Tom said he would be thirteen next month.","来月１３歳になるって、トムが言ってたよ。","thirteen"];
EXAMPLES[666]=["His car got no more than fourteen miles.","彼の車は１４マイルしか走れなかった。","fourteen"];
EXAMPLES[667]=["The class was made up of seventeen children.","そのクラスは１７名の子供から成り立っていた。","seventeen"];
EXAMPLES[668]=["I bought a book and he a ruler.","私は本を買い、彼は定規を買った。","ruler"];
EXAMPLES[669]=["I took to drinking when I was eighteen.","私は十八歳で酒の味を覚えた。","eighteen"];
EXAMPLES[670]=["We arrived on the morning of the twentieth.","私たちは２０日の朝に到着しました。","twentieth"];
EXAMPLES[671]=["Today I have to drop by the supermarket.","今日はスーパーに寄らなければならない。","supermarket"];
EXAMPLES[672]=["It is true that he is over seventy.","確かに七十はすぎてる。","seventy"];
EXAMPLES[673]=["The original was written as a school textbook.","原作は学校の教科書として書かれた。","textbook"];
EXAMPLES[674]=["My grandfather died of a disease at eighty.","祖父は８０歳のときに病気で亡くなりました。","eighty"];
EXAMPLES[675]=["He wrote down her name in the notebook.","彼はノートに彼女の名前を書き留めた。","notebook"];
EXAMPLES[676]=["We have to save for a rainy day.","我々はまさかの時の為備えをしなければならない。","rainy"];
EXAMPLES[677]=["He is likely to live to be ninety.","彼は９０歳まで生きそうだ。","ninety"];
EXAMPLES[678]=["It's not wine. It's just grape juice.","ワインじゃないよ。ただのグレープジュースだよ。","grape"];
EXAMPLES[679]=["The girl with fair skin passes for nineteen.","その色白の女の子は１９歳でとおっている。","nineteen"];
EXAMPLES[680]=["The water in the glass is cloudy.","コップの水は濁ってる。","cloudy"];
EXAMPLES[681]=["December is the twelfth month of the year.","「１２月」は１年の中で１２回目の月にあたります。","twelfth"];
EXAMPLES[682]=["November is the eleventh month of the year.","「１１月」は１年の中で１１回目の月にあたります。","eleventh"];
EXAMPLES[683]=["As the weather was snowy, we went skiing.","雪の降る天気だったので、私たちはスキーに行った。","snowy"];
EXAMPLES[684]=["We'll go to the library and the bookstore.","僕たち、図書館と本屋さんに行くんだ。","bookstore"];
EXAMPLES[685]=["Mother is in the kitchen wearing an apron.","お母さんなら台所よ。前掛けかけて。","apron"];
EXAMPLES[686]=["He runs as fast as any other classmate.","彼はクラスメートの誰よりも足が速い。","classmate"];
EXAMPLES[687]=["I won't ask you anything else today.","今日はもう聞かないよ。","I won"];
EXAMPLES[691]=["I lost my inspiration.","私はひらめきを失った。","I lost"];
EXAMPLES[693]=["It almost scared me not to see you online for a whole day.","丸一日オンラインで君を見ないなんてびっくりだよ。","see you"];
EXAMPLES[694]=["Competition is not bad in itself.","競争それ自体は悪くない。","not bad"];
EXAMPLES[695]=["That's a misunderstanding, for sure. You're giving me too much credit.","それはきっと、誤解だ。きみはわたしを過大評価してる。","me too"];
EXAMPLES[696]=["I agree with some of your opinions.","君の意見の幾つかには賛成します。","I agree"];
EXAMPLES[697]=["I can't live that kind of life.","私はそんな風には生きられない。","I can't"];
EXAMPLES[698]=["The best way to make your dreams come true is to wake up.","夢を実現するのに一番良いのは目を覚ますことである。","wake up"];
EXAMPLES[700]=["I'm fine, thanks. Oh, Laura, this is my friend, Ayako.","とても元気よ！ねえ、ローラ、こちら友達の綾子。","I'm fine"];
EXAMPLES[701]=["I'm good at soccer.","私はサッカーが得意です。","I'm good"];
EXAMPLES[702]=["We have to stand up for minority rights.","我々は少数民族の権利を守らなければならない。","stand up"];
EXAMPLES[703]=["You may sit down in the chair.","椅子に座ってもよろしい。","sit down"];
EXAMPLES[704]=["You talk next and you be quiet.","君が次に話し、君は静かにしていなさい。","be quiet"];
EXAMPLES[705]=["In terms of the pay you will get, is this a good job?","君がもらう給料の点からこれはいい仕事かね。","good job"];
EXAMPLES[706]=["It's fun to learn about foreign cultures.","外国の文化について学ぶのは楽しい。","It's fun"];
EXAMPLES[707]=["No, thank you. I'm full.","ううん、もういいよ。お腹いっぱい。","I'm full"];
EXAMPLES[708]=["Put on your shoes. Let's go out for dinner.","靴を履いて夕食を食べに行きましょう。","Let's go"];
EXAMPLES[709]=["I'm home, mom!","ただいま、お母さん。","I'm home"];
EXAMPLES[710]=["You'd better hurry up.","急いだほうがいいよ。","hurry up"];
EXAMPLES[711]=["Quit pouting. Smile and cheer up.","ふくれっ面してないで、機嫌を直して笑ってごらんよ。","cheer up"];
EXAMPLES[712]=["Don't be angry with me, for I did it for your sake.","君のためにそれをしたのだから、怒らないでくれ。","I did it"];
EXAMPLES[713]=["You should take care of your sick mother.","君は病気のお母さんの面倒をもっと見るべきだ。","take care"];
EXAMPLES[714]=["I'm tired of eating fast food.","ファストフードはもう飽きた。","I'm tired"];
EXAMPLES[715]=["Thank you very much!","ありがとうございます！","Thank you"];
EXAMPLES[716]=["I'm sorry, I can't stay long.","申し訳ないけど長居できないんですよ。","I'm sorry"];
EXAMPLES[717]=["Excuse me; allow me to point out three errors in the above article.","失礼だが、上記の記事にある３つの誤りを指摘しておきたい。","Excuse me"];
EXAMPLES[718]=["Until next weekend, if that's OK.","もしよかったら、今度の週末までなんだけど。","that's OK"];
EXAMPLES[719]=["I think your work is all right.","君の仕事は申し分ないと思う。","all right"];
EXAMPLES[720]=["That's a good idea!","良い考えだね！","good idea"];
EXAMPLES[721]=["It's cute, and more importantly, of good quality.","可愛い。そして何より品がいい。","It's cute"];
EXAMPLES[722]=["I'm not wearing a diamond ring, but I'm happy.","ダイヤの指輪なんて身につけていないけど、私は幸せだ。","I'm happy"];
EXAMPLES[723]=["Let's eat out for a change.","気分転換に外食しましょう。","Let's eat"];
EXAMPLES[724]=["What time are you going on duty?","君は何時に勤務につくの？","What time"];
EXAMPLES[725]=["Turn left at the corner.","その角を左へ曲がりなさい。","Turn left"];
EXAMPLES[726]=["Our success was due in part to good luck.","我々の成功はある程度は幸運のおかげであった。","good luck"];
EXAMPLES[727]=["Well done! Your parents must be proud of you.","でかしたね。ご両親もさぞかし鼻が高いでしょうね。","Well done"];
EXAMPLES[728]=["Watch out! There's a big hole there.","気をつけて。そこに大きな穴があるよ。","Watch out"];
EXAMPLES[729]=["What did you come here so early for?","何でこんなに早く来たの？","come here"];
EXAMPLES[730]=["If you follow me, I'll show you the way to the hospital.","ついていらっしゃるなら、病院への道をご案内いたします。","follow me"];
EXAMPLES[731]=["Your answer isn't correct. Try again.","君の答えは正しくない。もう一度やりなさい。","Try again"];
EXAMPLES[733]=["Try and calm down.","気持ちを落ち着かせるようにしなさい。","calm down"];
EXAMPLES[734]=["This isn't your book. It's mine.","これはあなたの本じゃなくて、私のよ。","It's mine"];
EXAMPLES[735]=["He came after you left.","君が出たあと彼が来た。","after you"];
EXAMPLES[736]=["May God bless you.","神の恵みがありますように。","bless you"];
EXAMPLES[737]=["I like it very much.","とっても好きよ。","I like it"];
EXAMPLES[738]=["Yes, I love it.","はい、好きです。","I love it"];
EXAMPLES[739]=["Good night. Sweet dreams.","おやすみなさい、良い夢を！","Good night"];
EXAMPLES[740]=["I slept only two hours. No wonder I'm sleepy.","２時間しか寝なかった。眠いのは当然だ。","I'm sleepy"];
EXAMPLES[741]=["When are we eating? I'm hungry!","いつご飯食べるの？お腹空いたよ。","I'm hungry"];
EXAMPLES[742]=["No problem at all!","全く問題ありません！","No problem"];
EXAMPLES[743]=["Never mind. Anyone can make mistakes.","気にするな。誰でも間違うことはあるんだから。","Never mind"];
EXAMPLES[744]=["I'm sorry, but that's all we have right now.","すみません。今それだけしか置いてないんです。","that's all"];
EXAMPLES[745]=["Let's play baseball when the rain stops.","雨がやんだら野球をしよう。","Let's play"];
EXAMPLES[746]=["It's sunny here, but it's raining.","狐の嫁入りだ。","It's sunny"];
EXAMPLES[747]=["If it's rainy the mountain climbing will be called off.","雨天なら、山登りは、取りやめます。","it's rainy"];
EXAMPLES[748]=["It's snowy today.","今日は雪です。","It's snowy"];
EXAMPLES[749]=["It's windy and cold.","風が吹いていて、寒いです。","It's windy"];
EXAMPLES[750]=["Turn right at the crossroad.","その交差点を右に曲がってください。","Turn right"];
EXAMPLES[751]=["You can probably guess what happens though.","君には何が起こるか分かるんじゃないかと思うけどね。","guess what"];
EXAMPLES[752]=["This isn't my responsibility. It's yours.","これは私ではなくあなたの責任です。","It's yours"];
EXAMPLES[753]=["I'm coming with you.","一緒に行きます。","I'm coming"];
EXAMPLES[754]=["Uh.....yes, I think so.","ええっと、そうだと思います。","I think so"];
EXAMPLES[755]=["Look at me when I talk to you!","私が話しているときは私を見て！","Look at me"];
EXAMPLES[756]=["Are you OK for drinking water in an emergency?","緊急時の飲料水の確保は、大丈夫ですか？","Are you OK"];
EXAMPLES[757]=["Let me see a menu.","メニューをお願いします。","Let me see"];
EXAMPLES[758]=["I'm thirsty. Can I have a glass of water?","のどが渇いた水をいっぱいください。","I'm thirsty"];
EXAMPLES[759]=["Don't worry, be happy!","心配しないで、楽しくいこう！","Don't worry"];
EXAMPLES[761]=["Let's begin practicing voice projection.","まず発声練習から始めましょう。","Let's begin"];
EXAMPLES[762]=["That sounds good to me.","私はそれでもかまいませんよ。","sounds good"];
EXAMPLES[763]=["Since it's cloudy with a chance of rain today, we shouldn't go surfing.","きょうは雲行きが怪しいので波乗りを遠慮したほうがいいと思う。","it's cloudy"];
EXAMPLES[764]=["I'm leaving it to you.","君にまかせるよ。","I'm leaving"];
EXAMPLES[765]=["Go straight ahead until you reach the church.","教会に着くまでまっすぐ行きなさい。","Go straight"];
EXAMPLES[766]=["Let's share the money.","お金を分けよう。","Let's share"];
EXAMPLES[767]=["What's this chair doing here?","なあに、その椅子？","What's this"];
EXAMPLES[768]=["Let's start the ball rolling by introducing ourselves.","まず自分たちの自己紹介から話を始めよう。","Let's start"];
EXAMPLES[769]=["How are you? Did you have a good trip?","元気？旅行は良かった？","How are you"];
EXAMPLES[770]=["This is Ken. He really likes his dog.","こちらはケンです。彼は自分の犬が大好きです。","This is Ken"];
EXAMPLES[771]=["All you have to do is to wait for me to return.","君は私が帰るのを待ちさえすればよい。","wait for me"];
EXAMPLES[772]=["Hello, Tom. Good morning.","やぁ、トム。おはよう。","Good morning"];
EXAMPLES[773]=["Good evening. How many are in your party?","いらっしゃいませ、何名様ですか。","Good evening"];
EXAMPLES[775]=["You've got it in one. That's right.","君はすぐに分かったんだね。そのとおりだよ。","That's right"];
EXAMPLES[776]=["I understand your position perfectly.","君の立場は十分に理解している。","I understand"];
EXAMPLES[777]=["What's wrong with me?","どこが悪いのですか。","What's wrong"];
EXAMPLES[778]=["I don't know if I have the time.","時間があるか分かりません。","I don't know"];
EXAMPLES[779]=["I'm not sure about that. It depends.","それはよく分かりません。場合によるでしょうね。","I'm not sure"];
EXAMPLES[780]=["I like this. I'll take it.","これが気に入りました。これをもらいます。","I'll take it"];
EXAMPLES[782]=["All you have to do is do your best.","君は最善を尽くしさえすればよい。","do your best"];
EXAMPLES[783]=["You are working too hard. Take it easy for a while.","君は働きすぎだよ。しばらくのんびりしたら。","Take it easy"];
EXAMPLES[784]=["It's my turn to drive next.","今度は私が運転する番よ。","It's my turn"];
EXAMPLES[785]=["May I try it on?","着てみていいですか。","May I try it"];
EXAMPLES[786]=["It's high time to go. See you later.","もう行かなくちゃ。じゃ、またね。","See you later"];
EXAMPLES[788]=["Just a minute, please. I'll call him to the phone.","彼に代わりますので少々お待ち下さい。","Just a minute"];
EXAMPLES[789]=["Don't be late for school.","学校に遅刻するな。","Don't be late"];
EXAMPLES[790]=["Don't give up hope.","失望するな。","Don't give up"];
EXAMPLES[791]=["I have to go to sleep.","私は眠らなければなりません。","to go"];
EXAMPLES[792]=["You should eat more, or you won't get well soon.","君はもっと食べるべきだ。さもないと早く良くなれないぞ。","get well soon"];
EXAMPLES[793]=["Whose is this bag?","これは誰の鞄ですか。","Whose is this"];
EXAMPLES[794]=["May I come in?","入ってもよろしいですか。","May I come in"];
EXAMPLES[795]=["You can do it.","できるよ！","You can do it"];
EXAMPLES[796]=["Good afternoon, ladies and gentlemen.","皆さん、こんにちは。","Good afternoon"];
EXAMPLES[797]=["You're welcome to any book in my library.","私の図書は自由にお使い下さい。","You're welcome"];
EXAMPLES[799]=["Why don't you try this? It's delicious, you know!","これ召し上がりますか？おいしいですよ。","It's delicious"];
EXAMPLES[800]=["Happy birthday to you!","誕生日おめでとうございます。","Happy birthday"];
EXAMPLES[802]=["Open your book to page nine.","九ページを開きなさい。","Open your book"];
EXAMPLES[803]=["It's hot today, isn't it?","今日は暑いですね。","It's hot today"];
EXAMPLES[805]=["I'm getting tired. It's your turn to drive.","つかれてきました。今度はあなたが運転する番です。","It's your turn"];
EXAMPLES[806]=["This machine is most dangerous; don't touch it.","この機械はとても危険だから触るな。","don't touch it"];
EXAMPLES[807]=["Hi, my name is Ken Saitou.","こんにちは、ぼくの名前は斎藤健です。","my name is Ken"];
EXAMPLES[808]=["How much is it?","いくらですか？","How much is it"];
EXAMPLES[809]=["Can I help you?","何か手伝いましょうか。","Can I help you"];
EXAMPLES[810]=["What day is it today?","今日、何曜日？","What day is it"];
EXAMPLES[814]=["Please repeat after me.","私の後について繰り返してください。","repeat after me"];
EXAMPLES[815]=["You must get up a little earlier.","君はもう少し早く起きなければなりません。","get up"];
EXAMPLES[816]=["You have to raise your hand if you want to speak at the meeting.","会議で発言したいと思ったら挙手しなければ行けません。","raise your hand"];
EXAMPLES[817]=["You'd better go by bus.","君はバスで行くほうがよい。","by bus"];
EXAMPLES[818]=["Nowadays his father goes to work by car.","近ごろ彼の父は車で会社に行く。","by car"];
EXAMPLES[819]=["Thank you for asking me, but maybe next time.","誘ってもらって嬉しいけど、この次にしておくよ。","maybe next time"];
EXAMPLES[820]=["It's cold today so button your coat.","今日は寒いのでコートのボタンをかけなさい。","It's cold today"];
EXAMPLES[821]=["Don't hang up, but hold on please.","電話を切らないでそのまま待って下さい。","hold on please"];
EXAMPLES[822]=["Do you wash your hands before meals?","君は食事前に手を洗いますか。","wash your hands"];
EXAMPLES[823]=["All you have to do is to clean your room.","自分の部屋を掃除するだけでいいんだよ。","clean your room"];
EXAMPLES[824]=["See that dinner is ready by ten.","１０時までに夕食の準備をしておくように取り計らいなさい。","dinner is ready"];
EXAMPLES[825]=["It's over there, go ahead.","そこにありますのでどうぞ。","It's over there"];
EXAMPLES[826]=["Watch your step when going down the stairs.","階段をおりる時には足元に気をつけなさい。","Watch your step"];
EXAMPLES[829]=["Have a nice day.","よい一日をね。","Have a nice day"];
EXAMPLES[830]=["By the way, how old are you?","ところで、何歳ですか。","how old are you"];
EXAMPLES[831]=["I can walk to school in 10 minutes.","学校まで１０分で歩いて行ける。","walk to"];
EXAMPLES[832]=["Can you help me when I move?","引っ越すとき手伝ってもらえますか。","Can you help me"];
EXAMPLES[833]=["The meeting ended at noon.","会は正午に終わった。","at noon"];
EXAMPLES[834]=["If you look at the lyrics, they don't really mean much.","歌詞を見てみれば、あまり意味が無いことに気付くでしょう。","look at"];
EXAMPLES[835]=["Rosie was allowed to stay up till eleven o'clock.","ロージーは１１時まで起きている事を許された。","stay up"];
EXAMPLES[836]=["Anyway, I don't like it.","ともかく気にくわない。","I don't like it"];
EXAMPLES[837]=["What time is it by your watch?","あなたの時計では何時ですか。","What time is it"];
EXAMPLES[838]=["Have a good day, everyone.","みなさん、良い一日を。","Have a good day"];
EXAMPLES[839]=["Let's go to bed already.","もう寝ましょ。","Let's go to bed"];
EXAMPLES[840]=["As it is late, turn off the TV.","もう遅いからテレビを消しなさい。","turn off the TV"];
EXAMPLES[841]=["I will be able to see you tomorrow unless something unexpected turns up.","何か思いがけないことが起こらなければ、明日あなたに会えます。","see you tomorrow"];
EXAMPLES[842]=["I'm just looking, thank you.","どうも、ちょっと見るだけ。","I'm just looking"];
EXAMPLES[843]=["You should brush your teeth at least twice a day.","一日にせめて二回は歯を磨くべきだ。","brush your teeth"];
EXAMPLES[845]=["Long time no see!","ご無沙汰しています。","Long time no see"];
EXAMPLES[846]=["Hi! I'm Ichirou Tanaka. Nice to meet you.","こんにちは。僕は田中一郎です。よろしくお願いします。","Nice to meet you"];
EXAMPLES[847]=["Have a nice trip!","楽しいご旅行を。","Have a nice trip"];
EXAMPLES[848]=["I'm proud of you.","お前のことを誇りに思うよ。","I'm proud of you"];
EXAMPLES[850]=["How many books can I take out at one time?","一度に何冊借りられますか。","take out"];
EXAMPLES[851]=["Is it for here?","こちらで召し上がりますか。","for here"];
EXAMPLES[852]=["Do you understand the difficulty of my job?","あなたは私の仕事の難しさがわかっていますか。","Do you understand"];
EXAMPLES[853]=["All that you have to do is to wait for his reply.","君は彼の返事を待ちさえすればよい。","wait for"];
EXAMPLES[854]=["How's the weather in New York?","ニューヨークのお天気はどうですか。","How's the weather"];
EXAMPLES[855]=["I hate it when there are a lot of people.","人ごみは大嫌い。","a lot of"];
EXAMPLES[856]=["It's Monday today and it will be Tuesday tomorrow.","今日は月曜日で、明日は火曜日です。","It's Monday today"];
EXAMPLES[857]=["I have a question.","質問があります。","I have a question"];
EXAMPLES[858]=["There are many words that I don't understand.","分からない言葉がたくさんある。","I don't understand"];
EXAMPLES[859]=["Whenever I find something I like, it's too expensive.","欲しいものがみつかると、決まって高いものだ。","it's too expensive"];
EXAMPLES[860]=["It's three o'clock now; I'll come again in an hour.","今は３時です。１時間後にまた来ますね。","It's three o'clock"];
EXAMPLES[861]=["Jimmy, breakfast is ready. Come downstairs.","ジミー、朝ごはんできたわよ。降りてらしゃい。","breakfast is ready"];
EXAMPLES[862]=["I'll call you back when I get to the bus stop.","バス停に着いたら、また電話します。","I'll call you back"];
EXAMPLES[863]=["Did you sleep well last night, Steve?","スティーブ、昨晩はよく寝れましたか。","Did you sleep well"];
EXAMPLES[864]=["How about playing catch in the vacant lot near by?","近くの空き地でキャッチボールをするのはどうですか。","How about"];
EXAMPLES[866]=["Uhh, what was I going to say again?","あれ、私何言おうとしたんだっけ？","say again"];
EXAMPLES[867]=["My hobby is to listen to music.","私の趣味は音楽を聞くことです。","listen to"];
EXAMPLES[868]=["I had to help with the housework.","家の手伝いをしないといけなかったの。","help with"];
EXAMPLES[870]=["Thank you very much!","ありがとうございます！","Thank you very much"];
EXAMPLES[871]=["I found the field trip very educational.","その実施見学は非常にためになった。","field trip"];
EXAMPLES[872]=["Please write down your name, address, and phone number here.","どうぞここにあなたの住所、氏名、それに電話番号を書いて下さい。","write down"];
EXAMPLES[873]=["What did you say? Could you please say it again?","何ですって？もう一度言って下さい。","please say it again"];
EXAMPLES[874]=["Let's discuss your love problems on the way back from school.","君の恋愛問題は学校から帰る道々話しましょう。","on the way"];
EXAMPLES[875]=["Go back to your seat.","席にもどりなさい。","Go back to"];
EXAMPLES[877]=["How do you say this?","これはどう言えばいいかな？","How do you say this"];
EXAMPLES[878]=["It's fun to learn about foreign cultures.","外国の文化について学ぶのは楽しい。","learn about"];
EXAMPLES[879]=["That's all for today.","今日はこれまで。","That's all for today"];
EXAMPLES[880]=["Robert used to help his father in the store on weekends.","ロバートは週末は店で父を手伝ったものだった。","on weekends"];
EXAMPLES[881]=["Back in high school, I got up at 6 a.m. every morning.","高校生の時は毎朝6時に起きていた。","high school"];
EXAMPLES[882]=["Where is the station?","駅はどこですか。","Where is the station"];
EXAMPLES[883]=["You don't need to worry about such a thing.","君はそんなことを心配する必要はありません。","worry about"];
EXAMPLES[884]=["Since you look tired, you had better take a rest.","君は疲れているようだから、休んだ方がよい。","take a rest"];
EXAMPLES[885]=["Can I ask a question?","質問していい？","Can I ask a question"];
EXAMPLES[887]=["Turning right, you'll find the hospital on your left.","右に曲がると、左手に病院があります。","on your left"];
EXAMPLES[889]=["Mrs. Parker greeted him with a smile.","パーカー夫人はにこにこしながら彼を迎えた。","with a smile"];
EXAMPLES[890]=["You were in the second year of middle school last year, right?","あなた方は去年中学２年生でしたね。","middle school"];
EXAMPLES[891]=["It's nice to meet you too.","わたしも会えて嬉しいよ。","nice to meet you too"];
EXAMPLES[892]=["You can see the sea on your right.","右手に海が見えますよ。","on your right"];
EXAMPLES[893]=["Now that we are all here, we can start the farewell party.","みなさまがお揃いになったので、送別会を始められます。","farewell party"];
EXAMPLES[895]=["They helped one another to make the school festival a success.","学園祭を成功させるために彼らは互いに助け合った。","school festival"];
EXAMPLES[897]=["I have a headache.","頭痛がする。","have a headache"];
EXAMPLES[899]=["What is the difference between A and B?","ＡとＢの違いは何ですか。","between A and B"];
EXAMPLES[900]=["Sumo is great fun; otherwise she wouldn't be interested in it.","相撲はとてもおもしろい。そうでなければ彼女は相撲に興味を持たないだろう。","be interested in"];
EXAMPLES[901]=["Are you ready to order?","ご注文はお決まりですか？","Are you ready to order"];
EXAMPLES[902]=["We learn a lot from experience.","我々は経験から多くを学ぶ。","learn a lot from"];
EXAMPLES[903]=["May I go to the bathroom?","トイレに行ってもいいですか。","May I go to the bathroom"];
EXAMPLES[904]=["The entrance ceremony will be held at 10 o'clock.","入学式は十時から行います。","entrance ceremony"];
EXAMPLES[906]=["You have the wrong number.","間違えてかかっています。","You have the wrong number"];
EXAMPLES[907]=["He didn't come back to the base yesterday.","昨日、彼は基地に帰らなかった。","base"];
EXAMPLES[908]=["All you have to do is follow me.","あなたは私についてきさえすればよい。","follow"];
EXAMPLES[909]=["Are you a member of the baseball team?","君は野球チームのメンバーですか。","member"];
EXAMPLES[910]=["In the end, our team lost the final.","結局我々のチームは決勝戦で負けた。","final"];
EXAMPLES[911]=["I forgot to add that to my list.","リストに追加するの忘れてた。","list"];
EXAMPLES[912]=["I am ready to do anything for you.","君のためなら喜んでなんでもする。","ready"];
EXAMPLES[913]=["It was a very good experience for him.","それは彼にとってとてもいい経験だった。","experience"];
EXAMPLES[914]=["You should have seen the program on TV.","そのテレビ番組を見るべきだったのに。","program"];
EXAMPLES[915]=["Her job was to type all the letters.","彼女の仕事は手紙を全部タイプで打つ事でした。","type"];
EXAMPLES[916]=["I want to have a baby with you.","あなたとの赤ちゃんが欲しいな。","baby"];
EXAMPLES[917]=["You have a good chance to get well.","君はよくなる見込みが十分ある。","chance"];
EXAMPLES[918]=["My house is just across from the hospital.","私の家は病院の真向かいです。","across"];
EXAMPLES[919]=["It's time to put the plan in action.","計画を実行すべき時だ。","action"];
EXAMPLES[920]=["It is clear that he is at home.","彼が家にいることは明白だ。","clear"];
EXAMPLES[921]=["Mike is the only man on the board.","マイクはその委員会で唯ひとりの男性です。","board"];
EXAMPLES[922]=["She cut a picture out of the book.","彼女は本から一枚の絵を切り抜いた。","cut"];
EXAMPLES[923]=["The children are playing catch in the field.","子供たちが野原でキャッチボールをしている。","field"];
EXAMPLES[924]=["What you said was in the main right.","あなたが言ったことはおおむね正しかった。","main"];
EXAMPLES[925]=["I don't have the energy to do that.","それをする気力はない。","energy"];
EXAMPLES[926]=["Is there any space for one more person?","もう１人分の空きはありますか。","space"];
EXAMPLES[927]=["He made a killing in his new business.","彼は新商売で荒稼ぎをした。","killing"];
EXAMPLES[928]=["As yet, the project is in the air.","その計画は今のところ未決定である。","project"];
EXAMPLES[929]=["I applied for a position in the office.","私はその会社に職を求めた。","position"];
EXAMPLES[930]=["This is the record which I bought yesterday.","これは、私が昨日買ったレコードです。","record"];
EXAMPLES[931]=["Do you know the total population of Japan?","日本の総人口を知っていますか。","total"];
EXAMPLES[932]=["He is a member of the baseball club.","彼は野球部の一員だ。","club"];
EXAMPLES[933]=["I know the perfect place to do that.","それをするのにもってこいの場所知ってるよ。","perfect"];
EXAMPLES[934]=["State your name and social security number, please.","お名前と社会保障番号をおっしゃって下さい。","security"];
EXAMPLES[935]=["We sat in the center of the room.","私たちはその部屋の中央に座った。","center"];
EXAMPLES[936]=["The couple put their house on the market.","夫妻は家を売りに出した。","couple"];
EXAMPLES[937]=["It may be faster if you apply online.","オンライン申請する方が早いかもね。","online"];
EXAMPLES[938]=["I want to talk with you in private.","二人だけで話したいんだけど。","private"];
EXAMPLES[939]=["When will you return the money to me?","いつお金を返してくれますか。","return"];
EXAMPLES[940]=["In a sense, life is but a dream.","ある意味で、人生は夢にすぎない。","sense"];
EXAMPLES[941]=["I think I did well on the test.","試験ではうまくいったと思っている。","test"];
EXAMPLES[942]=["From this point of view, you are right.","この見地からすると、君の言うことは正しい。","view"];
EXAMPLES[943]=["The station is the middle of the city.","駅は市の中央にある。","middle"];
EXAMPLES[944]=["The diamond was set in a gold ring.","ダイアモンドは金の指輪にはめ込まれていた。","gold"];
EXAMPLES[945]=["I want to be alone for a while.","ちょっとひとりになりたいの。","alone"];
EXAMPLES[946]=["What is the average height of the players?","選手達の平均身長はどのくらいですか。","average"];
EXAMPLES[947]=["What do you think of the original plan?","その原案をどう思いますか。","original"];
EXAMPLES[948]=["I am not satisfied with my performance today.","今日の演奏の出来は私の意にかなったものではない。","performance"];
EXAMPLES[949]=["That is why I believe in the Press.","私が新聞の存在価値を信じるのはそのためだ。","Press"];
EXAMPLES[950]=["We have a lot of ground to cover.","話し合わねばならないことがたくさんある。","ground"];
EXAMPLES[951]=["What is the relationship between politics and war?","政治と戦争との関係は何でしょうか。","relationship"];
EXAMPLES[952]=["We think of the plan as of value.","私達は、その計画を価値あるものと見なす。","value"];
EXAMPLES[953]=["What is the official name for this place?","ここの正式名称は何ですか？","official"];
EXAMPLES[954]=["The computer is still on, is that okay?","パソコンの電源つけっぱなしだけど、いいの？","okay"];
EXAMPLES[955]=["What is the unemployment rate at the moment?","現在の失業率はどのくらいですか。","rate"];
EXAMPLES[956]=["I have a ton of stuff to do.","やることはいくらでもある。","stuff"];
EXAMPLES[957]=["Our team has topped the league this season.","今シーズンは我々のチームがリーグで優勝した。","league"];
EXAMPLES[958]=["Skillful management made a success of the business.","巧みな経営で事業は成功した。","management"];
EXAMPLES[959]=["She is said to have been a model.","彼女はモデルだったそうだ。","model"];
EXAMPLES[960]=["Do you have this in a size 13?","これの１３号ってありますか？","size"];
EXAMPLES[961]=["What is the central aim of this plan?","この計画の主なねらいは何ですか。","central"];
EXAMPLES[962]=["Is this the key you are looking for?","これはあなたの探している鍵ですか。","key"];
EXAMPLES[963]=["My mom is the best in the world!","僕のママは世界一だ！","mom"];
EXAMPLES[964]=["I turn over a page of the book.","本のページをめくる。","page"];
EXAMPLES[965]=["I regard him as a man of character.","私は彼のことを人格者とみなしている。","character"];
EXAMPLES[966]=["He is the chief of a police station.","彼は警察署長です。","chief"];
EXAMPLES[967]=["The football game is now on the air.","フットボールの試合が放送中なんだよ。","football"];
EXAMPLES[968]=["Who are you going to send that to?","それ誰に送るの？","send"];
EXAMPLES[969]=["I would like my hair in this style.","この髪型にしてください。","style"];
EXAMPLES[970]=["The well delivers a great deal of oil.","その油井はたくさんの原油を産出する。","oil"];
EXAMPLES[971]=["He is of a serious turn of mind.","彼は真面目な性格だ。","serious"];
EXAMPLES[972]=["Who is the girl singing on the stage?","舞台で歌っている少女は誰なんですか。","stage"];
EXAMPLES[973]=["The cause of death was a heart attack.","死因は心臓発作だった。","attack"];
EXAMPLES[974]=["The situation is bad enough as it is.","事態は今のままでももう十分悪くなっている。","situation"];
EXAMPLES[975]=["A great revolution has taken place in technology.","科学技術において、大きな革命が起こった。","technology"];
EXAMPLES[976]=["I am interested in creating my own website.","私は自分のサイトを作ることに興味があります。","website"];
EXAMPLES[977]=["I have no choice but to do that.","そうせざるを得ないね。","choice"];
EXAMPLES[978]=["It is not acceptable to our moral code.","それは私たちの道徳的規範には受け入れられない。","code"];
EXAMPLES[979]=["This is the best amp currently being sold.","これは今売っている中で最高のアンプです。","currently"];
EXAMPLES[980]=["He is not as simple as he seems.","彼は見かけほど単純ではない。","simple"];
EXAMPLES[981]=["I have simply nothing to say about it.","それについては全く言うことはありません。","simply"];
EXAMPLES[982]=["I get along well with all the staff.","スタッフの人たちともうまくいっています。","staff"];
EXAMPLES[983]=["He wanted to follow law as a career.","彼は法律を一生の職業にしたいと思っていた。","career"];
EXAMPLES[984]=["I read about his death in the paper.","私は新聞で彼の死去のことを知った。","paper"];
EXAMPLES[985]=["I hope you are in a safe place.","あなたが安全な場所にいるといいですね。","safe"];
EXAMPLES[986]=["I've heard the French version of this song.","この歌のフランス語版を聴いたことがある。","version"];
EXAMPLES[987]=["There was a voice crying in the field.","野原で叫ぶ声がした。","voice"];
EXAMPLES[988]=["Internet access is free all around the world.","世界中のいたるところで、ネットへのアクセスは自由で無料だ。","Internet"];
EXAMPLES[989]=["How many are there in your party, sir?","ご一行様は何名でいらっしゃいますか。","sir"];
EXAMPLES[990]=["It is difficult to gain access to him.","彼にはなかなか会えない。","access"];
EXAMPLES[991]=["It is your shadow in the deep sea.","深海で君の影がゆれる。","deep"];
EXAMPLES[992]=["He got a fair mark in the examination.","彼はその試験でまあまあの点をとった。","mark"];
EXAMPLES[993]=["He declined the offer and so did I.","彼は申し出を断った、そして私も断った。","offer"];
EXAMPLES[994]=["This work would do credit to a professional.","こういった仕事は、プロの誇りとなるだろう。","professional"];
EXAMPLES[995]=["I don't want to run such a risk.","私はそんな冒険を冒したくない。","risk"];
EXAMPLES[996]=["I found the lost ball in the park.","私は公園でなくしたボールを見つけた。","ball"];
EXAMPLES[997]=["I paid for it with a credit card.","クレジットカードで払いました。","card"];
EXAMPLES[998]=["He was looking for something in the dark.","彼は暗いところで何か捜し物をしていた。","dark"];
EXAMPLES[999]=["Nearly 80 percent of the land is mountains.","国土の８割近くが山です。","percent"];
EXAMPLES[1000]=["A police officer asked me for my name.","警官に名前を聞かれた。","officer"];
EXAMPLES[1001]=["What time did he ask for your response?","彼は何時に君の返事を要求したのか。","response"];
EXAMPLES[1002]=["A big rock rose out of the sea.","大きな岩が一つ海面から突き出ていた。","rock"];
EXAMPLES[1003]=["We tried to come up to the standard.","私達は標準に到達しようとした。","standard"];
EXAMPLES[1004]=["I tore the picture out of the album.","私はアルバムからその写真を引きはがした。","album"];
EXAMPLES[1005]=["A network of railroads spreads all over Japan.","日本全国に鉄道が網の目のようにできている。","network"];
EXAMPLES[1006]=["The police are on the track of the thief.","警察は泥棒を追跡中である。","track"];
EXAMPLES[1007]=["Would you like a single or a double?","シングルになさいますか、ダブルにしますか。","double"];
EXAMPLES[1008]=["I just want to have a normal life.","普通の生活を送りたいだけです。","normal"];
EXAMPLES[1009]=["He brought pressure to bear on our decision.","彼は我々の決定に圧力をかけた。","pressure"];
EXAMPLES[1010]=["I listen to the news on the radio.","ラジオでニュースを聞きます。","radio"];
EXAMPLES[1011]=["We read the full text of his speech.","私たちは彼の演説の全文を読んだ。","text"];
EXAMPLES[1012]=["He lives in the western part of town.","彼は町の西部に住んでいる。","western"];
EXAMPLES[1013]=["The campaign succeeded and he won the election.","その選挙運動が成功して、彼は選挙に勝った。","campaign"];
EXAMPLES[1014]=["The priest made the sign of the cross.","牧師は十字架を作った。","cross"];
EXAMPLES[1015]=["Hi, I didn't expect to see you here.","やあ、こんな所で会うとはね。","Hi"];
EXAMPLES[1016]=["I have a message for you from her.","君に彼女から伝言がある。","message"];
EXAMPLES[1017]=["I was nearly run over by a car.","危なく車にひかれるところだった。","nearly"];
EXAMPLES[1018]=["She is attached to the general affairs section.","彼女は庶務課に所属している。","section"];
EXAMPLES[1019]=["This is the car with the most speed.","この車はスピードが一番はやい車です。","speed"];
EXAMPLES[1020]=["He wrote a lot of books on China.","彼は中国に関する本をたくさん書いた。","China"];
EXAMPLES[1021]=["The Alps are in the center of Europe.","アルプス山脈はヨーロッパの中央にある。","Europe"];
EXAMPLES[1022]=["Can you take us to the British Museum?","大英博物館まで行ってくれますか。","British"];
EXAMPLES[1023]=["The reason is because I can speak Chinese.","何故ならば、私は中国語が話せます。","Chinese"];
EXAMPLES[1024]=["I thought that you were good at French.","フランス語得意なんだと思ってた。","French"];
EXAMPLES[1025]=["How do you say that in Russian?","ロシア語では、どう言うの？","Russian"];
EXAMPLES[1026]=["Do you have a European health insurance card?","ヨーロッパの健康保険カードをお持ちですか？","European"];
EXAMPLES[1027]=["I have to do that on my own.","私は一人でそれをしなければならない。","own"];
EXAMPLES[1028]=["He walked on and on in the rain.","彼は雨の中を歩き続けた。","rain"];
EXAMPLES[1029]=["Now the shoe is on the other foot.","形勢は逆転した。","foot"];
EXAMPLES[1030]=["I had enough to keep up with him.","彼についていくのがやっとだった。","enough"];
EXAMPLES[1031]=["I had to shout in order to be heard.","聞こえるように、僕は叫ばなければいけなかった。","shout"];
EXAMPLES[1032]=["Never has he been to such a place.","彼はそんな場所に行ったことがない。","such"];
EXAMPLES[1033]=["I got it! The answer is 24, right?","わかった！答えって２４だろう？","answer"];
EXAMPLES[1034]=["The cost of operating schools continued to rise.","学校を運営する費用が上昇し続けた。","rise"];
EXAMPLES[1035]=["It's up to you to decide the matter.","そのことを決めるのは君の役目だ。","decide"];
EXAMPLES[1036]=["She was left in the sun too long.","その子はあまりにも長く日光にさらされた。","sun"];
EXAMPLES[1037]=["I want to have a word with you.","ちょっと話があるんだけど。","word"];
EXAMPLES[1038]=["The ship arrived at the port on schedule.","船は予定通り港に到着した。","port"];
EXAMPLES[1039]=["Get hold of the rail just in case.","万一の時に備えて手すりにつかまりなさい。","hold"];
EXAMPLES[1040]=["Remember I will always be at your back.","あなたにはいつも私がついている事をお忘れなく。","Remember"];
EXAMPLES[1041]=["As usual, you get straight to the point.","相変わらず、単刀直入だね。","usual"];
EXAMPLES[1042]=["This TV set is the best of all.","このテレビがすべてのうちで一番よい。","set"];
EXAMPLES[1043]=["I have no reason to lie to you.","あなたに嘘をつく理由はない。","lie"];
EXAMPLES[1044]=["Are you for the war or against it?","君は戦争に賛成か反対か。","war"];
EXAMPLES[1045]=["Do you wear a suit outside of work?","仕事以外で、スーツを着たりする？","wear"];
EXAMPLES[1046]=["This is the more useful of the two.","これが２つのうちで役に立つ方です。","useful"];
EXAMPLES[1047]=["They were really cut from the same cloth.","本当に瓜二つだったわ。","cloth"];
EXAMPLES[1048]=["We were just about to enter the room.","私たちは部屋に入ろうとしていた。","enter"];
EXAMPLES[1049]=["I believed him to be in good health.","私は彼の具合がよいのだと信じていた。","health"];
EXAMPLES[1050]=["I want to invite you to a party.","君をパーティーに招待したいのですが。","invite"];
EXAMPLES[1051]=["He read the letter in a loud voice.","彼はその手紙を声高らかに読みあげた。","loud"];
EXAMPLES[1052]=["I think I am going to throw up.","戻しそう。","throw"];
EXAMPLES[1053]=["I will do my best to finish it.","私はそれを仕上げるのに全力を尽くすつもりだ。","finish"];
EXAMPLES[1054]=["He is the only person for the job.","彼こそその仕事にうってつけの人物だ。","person"];
EXAMPLES[1055]=["I don't want you to worry about me.","心配をかけたくないの。","worry"];
EXAMPLES[1056]=["Are you still in love with your wife?","今でも奥さんを愛していますか？","wife"];
EXAMPLES[1057]=["None of the meat was fit to eat.","その肉は全く食用に適さなかった。","meat"];
EXAMPLES[1058]=["I want to turn over a new leaf.","私は足を洗いたいと思っています。","leaf"];
EXAMPLES[1059]=["I wish I had been there with you.","私はあなたと一緒にそこにいたらよかったのだが。","wish"];
EXAMPLES[1060]=["The house is on top of the hill.","家は丘の上にある。","hill"];
EXAMPLES[1061]=["He is sure of success in the end.","彼は最後には成功すると確信している。","success"];
EXAMPLES[1062]=["The wind and rain put out the fire.","風と雨で火は治まりました。","wind"];
EXAMPLES[1063]=["This stone has a hole in the center.","この石には、真ん中に穴がある。","stone"];
EXAMPLES[1064]=["I am Christian but I don't eat pork.","私はクリスチャンですけど、豚肉は食べません。","pork"];
EXAMPLES[1065]=["I looked round the inside of the house.","私は家の中を見回した。","inside"];
EXAMPLES[1066]=["It is the factory my brother works in.","それは私の兄が働いている工場です。","factory"];
EXAMPLES[1067]=["You can see for miles from the roof.","屋上からは、何マイルも見渡せる。","roof"];
EXAMPLES[1068]=["I lived in this house in the past.","昔、この家に住んでたんだ。","past"];
EXAMPLES[1069]=["A sailor is at sea much of the time.","船乗りはほとんどの間航海に出ている。","sailor"];
EXAMPLES[1070]=["I do not put sugar in the coffee.","コーヒーに砂糖は入れないよ。","sugar"];
EXAMPLES[1071]=["That house is made of wood and stone.","その家は石と木材でつくられている。","wood"];
EXAMPLES[1072]=["They seem to make nothing of the problem.","彼らはその問題を軽く見ているようだ。","seem"];
EXAMPLES[1073]=["I wake up to the sound of music.","妙なる調べに目ざめると。","wake"];
EXAMPLES[1074]=["How would you like to pay for it?","お支払いはどのようにしますか。","pay"];
EXAMPLES[1075]=["I sometimes put a little salt in it.","私はときどきその中に少しの塩を入れる。","salt"];
EXAMPLES[1076]=["There was not a cloud in the sky.","空には雲一つなかった。","cloud"];
EXAMPLES[1077]=["What is it you want to ask me?","あなたは私に何の質問がしたいのですか。","ask"];
EXAMPLES[1078]=["The enemy were driven out of the land.","敵は国外に追い払われた。","land"];
EXAMPLES[1079]=["The Earth is a small but beautiful planet.","地球は小さいけど美しい惑星だ。","planet"];
EXAMPLES[1080]=["There is much water in the pond today.","今日は池にたくさんの水があります。","pond"];
EXAMPLES[1081]=["It is not a matter to laugh about.","それは笑いごとでない。","laugh"];
EXAMPLES[1082]=["What is the real cause of this tragedy?","この悲劇の本当の原因は何ですか。","real"];
EXAMPLES[1083]=["I stood at the end of the line.","私は列の一番後ろに立った。","stood"];
EXAMPLES[1084]=["I was told to wait for a while.","私は暫く待つように言われた。","while"];
EXAMPLES[1085]=["He will come to the church without fail.","彼はきっと教会へ来るだろう。","fail"];
EXAMPLES[1086]=["He was shot 3 times in the arm.","彼は腕を３度撃たれた。","arm"];
EXAMPLES[1087]=["I enjoyed talking with him at the party.","私は彼とパーティーでおしゃべりをして楽しんだ。","enjoyed"];
EXAMPLES[1088]=["A man came up and spoke to me.","男が近づいて私に話しかけた。","spoke"];
EXAMPLES[1089]=["The more you buy, the more you save.","量が多いほどお買い得です。","save"];
EXAMPLES[1090]=["He tried to get me to help him.","彼はどうしても私に手伝わせようとした。","tried"];
EXAMPLES[1091]=["The goods will be sold on the spot.","その商品は即売されるだろう。","sold"];
EXAMPLES[1092]=["Is he so foolish as to believe that?","彼はそんな事を信じるほどのばかなのか。","foolish"];
EXAMPLES[1093]=["I watched the game from beginning to end.","僕はそのゲームを最初から最後まで見ていた。","watched"];
EXAMPLES[1094]=["He played the game as best he could.","彼は出来るだけ一生懸命に試合をした。","played"];
EXAMPLES[1095]=["You will never realize what I went through.","私がどんな目にあったか君にはわかりっこない。","realize"];
EXAMPLES[1096]=["What is the difference between A and B?","ＡとＢの違いは何ですか。","between"];
EXAMPLES[1097]=["I was about to leave the house then.","私はその時まさに家を出ようとしているところだった。","then"];
EXAMPLES[1098]=["The church is between my house and yours.","教会は私の家とあなたの家の中にあります。","yours"];
EXAMPLES[1099]=["I feel a great joy for this job.","私はこの仕事に大きな喜びを感じている。","joy"];
EXAMPLES[1100]=["The strong should take care of the weak.","強者は弱者の面倒を見るべきだ。","weak"];
EXAMPLES[1101]=["I thought nothing of it at the time.","その時は、特に何も思わなかった。","thought"];
EXAMPLES[1102]=["He is senior to me by two years.","彼は僕より２才年上である。","senior"];
EXAMPLES[1103]=["This is a waste of time and money.","こんなの時間とお金の無駄遣いだよ。","waste"];
EXAMPLES[1104]=["The boy captured the bird with a net.","少年はその鳥を網で捕まえた。","net"];
EXAMPLES[1105]=["It is kind of her to help me.","私を手伝ってくれるとは、彼女は親切だ。","her"];
EXAMPLES[1106]=["A child was washed away by the wave!","子供が波にさらわれたぞ！","wave"];
EXAMPLES[1107]=["She went to the back of the line.","彼女は列の最後尾に並んでしまった。","went"];
EXAMPLES[1108]=["I want you to do it at once.","すぐにしてもらいたいです。","once"];
EXAMPLES[1109]=["Did you make a toy with a friend?","友達と一緒におもちゃを作ったの？","toy"];
EXAMPLES[1110]=["He is not what he used to be.","彼は昔の彼ではない。","used"];
EXAMPLES[1111]=["He is not as fat as he was.","彼は以前ほど太ってない。","fat"];
EXAMPLES[1112]=["It is a fact that I dislike him.","私は彼をきらっているということは事実だ。","dislike"];
EXAMPLES[1113]=["I studied for a while in the afternoon.","私は午後しばらくの間勉強した。","studied"];
EXAMPLES[1114]=["We are worried about where he is now.","彼が今どこにいるのか心配だ。","worried"];
EXAMPLES[1115]=["Is that so? That was good to hear!","そうですか、良かったです！","hear"];
EXAMPLES[1116]=["The students are talking about language and culture.","生徒たちは、言葉と文化について話しています。","culture"];
EXAMPLES[1117]=["This desk is a little low for me.","この机は私にはちょっと低い。","low"];
EXAMPLES[1118]=["What will you do when you grow up?","大人になったら何になる？","grow"];
EXAMPLES[1119]=["I went to drink a beer with friends.","私は友達とビールを飲みに行った。","beer"];
EXAMPLES[1120]=["To begin with, we have no money now.","初めに、我々には今お金がない。","begin"];
EXAMPLES[1121]=["Like it or not, you have to go.","気に入ろうが入るまいが、君は行かねばならない。","or"];
EXAMPLES[1122]=["He was absent from school for a week.","彼は一週間学校を休んだ。","absent"];
EXAMPLES[1123]=["If I can do it, so can you.","私ができるんなら、あなただってできるわ。","If"];
EXAMPLES[1124]=["He stopped to think which way to go.","彼は立ち止まってどちらの道へ行こうかと考えた。","stopped"];
EXAMPLES[1125]=["It took me more than two hours to translate a few pages of English.","２、３ページの英語を訳すのに２時間以上もかかりました。","a few"];
EXAMPLES[1126]=["Don't be scared of making mistakes.","失敗を怖がることはありません。","be scared of"];
EXAMPLES[1127]=["The train from Geneva will arrive at the station.","ジュネーブから来る列車が駅に到着します。","arrive at"];
EXAMPLES[1128]=["May I ask about your family?","家族について聞いてもいいですか。","ask about"];
EXAMPLES[1129]=["I may be antisocial, but it doesn't mean I don't talk to people.","私は反社会的かもしれないけれど人と話さないわけではない。","talk to"];
EXAMPLES[1130]=["These days, the motive for marriage is not necessarily pure. Take Jennifer for example.","近ごろでは、結婚の動機は必ずしも純粋とは限らない。例えばジェニファーを見てごらんよ。","for example"];
EXAMPLES[1131]=["We are faced with a host of problems.","私たちは多くの問題に直面している。","host"];
EXAMPLES[1132]=["You had better make the most of your opportunities.","君は機会を出来るだけ利用した方がいい。","most of"];
EXAMPLES[1133]=["Can you see the nest in the tree?","木の上に巣があるのが見える？","nest"];
EXAMPLES[1134]=["Would you like to go abroad?","君は外国へ行きたいですか。","go abroad"];
EXAMPLES[1136]=["Add 5 to 3 and you have 8.","３に５を加えると８になる。","Add"];
EXAMPLES[1138]=["Can you do it in one day?","君は１日でそれができますか。","one day"];
EXAMPLES[1139]=["I sat in the front of the bus.","私はバスの前の席に座った。","sat"];
EXAMPLES[1140]=["You ought to ask for your teacher's permission.","君は先生の許可を受けるべきだ。","ask for"];
EXAMPLES[1141]=["I want you to take this medicine now.","この薬を今服用してください。","medicine"];
EXAMPLES[1142]=["He is a clever boy, to be sure.","確かに彼は利口な少年だ。","clever"];
EXAMPLES[1143]=["What time should I go to the airport?","空港には何時に行けばいいのですか。","airport"];
EXAMPLES[1144]=["Though he is rich, he is not happy.","彼は金持ちであるにもかかわらず、幸せではない。","Though"];
EXAMPLES[1145]=["Hurry up, and you will be on time.","急ぎなさい、そうすれば間に合うだろう。","Hurry"];
EXAMPLES[1146]=["Did you ever hear the like of it?","君はそのようなことを聞いたことがあるか。","ever"];
EXAMPLES[1147]=["On the other hand we learned a great deal from the experience.","他方でその経験から学んだものも大きかった。","from the experience"];
EXAMPLES[1148]=["Do you know the meaning of this word?","この単語の意味を知っていますか。","meaning"];
EXAMPLES[1149]=["I hope that kind of happiness will come.","そんな幸せが訪れるといいな。","happiness"];
EXAMPLES[1150]=["I'll call back in twenty minutes.","２０分たったらこちらから電話をします。","call back"];
EXAMPLES[1151]=["Don't you even think of eating my chocolate!","私のチョコレートを食べることを考えさえしないで。","think of"];
EXAMPLES[1152]=["How in the world did you know that?","一体どうしてその事を知っていたの？","did"];
EXAMPLES[1153]=["You should look after the children from time to time.","君は時には子供の世話をしなければならない。","look after"];
EXAMPLES[1154]=["He must be a fool to do so.","そんなことをするとは彼はばかにちがいない。","fool"];
EXAMPLES[1155]=["What has made you decide to work for our company?","君はどうして私たちの会社で働く決心をしたのですか。","decide to"];
EXAMPLES[1156]=["I was almost afraid to talk to you.","君に話しかけるのがどうもこわかったのです。","afraid"];
EXAMPLES[1158]=["I translated the poem the best I could.","私はこの詩を自分に出来うる最上の翻訳にした。","poem"];
EXAMPLES[1159]=["You were kind to help me.","君は親切にも私を助けてくれた。","kind to"];
EXAMPLES[1160]=["The kid is a pain in the neck.","あの子にはうんざりする。","neck"];
EXAMPLES[1162]=["What has made you decide to work for our company?","君はどうして私たちの会社で働く決心をしたのですか。","work for"];
EXAMPLES[1163]=["Those who live in glass houses should not throw stones.","こわれやすいガラス張りの家に住む者は石を投げてはいけない。","live in"];
EXAMPLES[1164]=["I thought that I was going to die.","死ぬかと思った。","die"];
EXAMPLES[1165]=["You are crazy to lend money to him.","あんな男に金を貸すとは、君はどうかしているよ。","lend"];
EXAMPLES[1167]=["What is the capital of the United States?","アメリカの首都はどこですか。","capital"];
EXAMPLES[1168]=["The population of Canada is about 26 million.","カナダの人口は約２６００万人です。","million"];
EXAMPLES[1169]=["He was brought up to be a doctor.","彼は医者になるように育て上げられた。","brought"];
EXAMPLES[1170]=["This is the house in which he lived.","これが彼の住んでいた家です。","lived"];
EXAMPLES[1171]=["Try on another one.","もうひとつ別のを試してごらん。","Try on"];
EXAMPLES[1172]=["It is strange that you should know that.","あなたがそれを知っているのは不思議だ。","strange"];
EXAMPLES[1174]=["A change of air will do you good.","転地があなたにとって効果があるでしょう。","change"];
EXAMPLES[1175]=["Can I have a look at the magazine?","その雑誌を見せてくれますか。","magazine"];
EXAMPLES[1176]=["She doesn't want to talk about it.","彼女はそのことについて話したくないんだよ。","talk about"];
EXAMPLES[1177]=["He left his team as he could not get along with the manager.","監督と仲良くやれなかったので彼はチームをやめた。","get along with"];
EXAMPLES[1178]=["Tom is trying to discover the meaning of life.","トムは人生の意味を見出そうとしている。","discover"];
EXAMPLES[1179]=["There is a man working on the farm.","農場で一人の男が働いている。","farm"];
EXAMPLES[1180]=["Please explain to me how you did that.","どうやったのか、説明してください。","explain"];
EXAMPLES[1181]=["He made do with a bed of grass.","彼はベッドを草で間に合わせた。","grass"];
EXAMPLES[1182]=["What on earth are you trying to say?","一体、何が言いたいんだ？","earth"];
EXAMPLES[1183]=["If the laundry is dry, bring it in.","洗濯物乾いてたら取り込んで。","dry"];
EXAMPLES[1184]=["The result is a continual search for food in a changing environment.","その結果、変化する環境の中で、絶えず獲物を探し続けなければならないのである。","search for"];
EXAMPLES[1185]=["Never try to die.","自殺なんてするんじゃない。","try to"];
EXAMPLES[1186]=["My advice is for you to go home.","家に帰った方が良いと忠告します。","advice"];
EXAMPLES[1187]=["We went to the lake to row a boat.","ボートをこぎに湖に出かけた。","row"];
EXAMPLES[1188]=["You're going to leave for London next Sunday, aren't you?","君がロンドンへ出発するのは今度の日曜日だよね。","leave for"];
EXAMPLES[1189]=["Allow me to introduce my wife to you.","あなた方に妻を紹介させてください。","introduce"];
EXAMPLES[1190]=["When you return to your company, don't forget to keep in touch with me.","会社へ帰ってきたら、私に連絡をとることを忘れるな。","keep in touch"];
EXAMPLES[1191]=["I understood only at a much later time.","分かったのは相当後になってからだった。","understood"];
EXAMPLES[1192]=["Try to bring out the best in him.","彼のいいところを引き出すようにしなさい。","bring"];
EXAMPLES[1193]=["I have to go to sleep.","私は眠らなければなりません。","go to"];
EXAMPLES[1194]=["All you have to do is believe me.","君は僕を信じさえすれば良い。","believe"];
EXAMPLES[1195]=["What do you want to do in the future?","君は将来何をしたいですか。","in the future"];
EXAMPLES[1196]=["I never thought this was going to happen.","まさかこんなことになろうとは思わなかった。","happen"];
EXAMPLES[1197]=["Were you to take it back?","君はそれを取り返すはずでしたか。","take it back"];
EXAMPLES[1198]=["Mr Tanaka makes a living running a small stationery shop near the station.","田中さんは駅の近くで小さな文房具店を経営して生活を立てています。","stationery shop"];
EXAMPLES[1199]=["Everybody sang at the top of their lungs.","みんなは声を張り上げて歌った。","sang"];
EXAMPLES[1200]=["What is over there?","何がそこにありますか。","over there"];
EXAMPLES[1201]=["It is important for you to learn a foreign language.","君が外国語を学ぶ事は重要です。","foreign language"];
EXAMPLES[1202]=["There are some flies on the wall.","ハエが壁に止まっている。","on the wall"];
EXAMPLES[1203]=["You can make it! Go for it. I'll stand by you.","君なら成功できるよ、がんばって。僕は見捨てない。","stand by"];
EXAMPLES[1204]=["I work simply because I like to work.","私はただ単に働くのが好きだから働くのである。","because"];
EXAMPLES[1205]=["You have to go over this project carefully.","この計画を君は慎重に調べなければならない。","carefully"];
EXAMPLES[1206]=["What are you going to do in college?","大学で何をするつもりですか。","college"];
EXAMPLES[1207]=["If I were to be born again, I would be a musician.","仮に生まれ変わるようなことがあれば、音楽家になりたい。","be born"];
EXAMPLES[1208]=["I will get even with you some day.","覚えてろよ。","even"];
EXAMPLES[1209]=["Is this what you want me to carry?","私に運んでほしいものって、これ？","carry"];
EXAMPLES[1210]=["I think I did well on the exam.","試験ではうまくいったと思っている。","exam"];
EXAMPLES[1211]=["He is bright, but he is not honest.","彼は頭がいいが、正直ではない。","bright"];
EXAMPLES[1212]=["The baby cried on and off all night.","その赤ん坊は一晩中泣いたり泣き止んだりした。","cried"];
EXAMPLES[1213]=["Are you in favor of the new law?","あなたはその新しい法律に賛成ですか。","law"];
EXAMPLES[1214]=["I like animals, for example, cats and dogs.","例えば、猫や犬のような動物が好きです。","example"];
EXAMPLES[1215]=["I need to find a place to live.","住む場所を探す必要がある。","find"];
EXAMPLES[1216]=["Can I borrow your eraser for a moment?","ちょっと消しゴムをかしてくれませんか。","eraser"];
EXAMPLES[1217]=["He was sent for and had to go.","彼は呼ばれていて行かなければならなかった。","sent"];
EXAMPLES[1218]=["She has a lot of faults; even so, she is liked by everybody.","彼女には欠点が多いが、それでも皆から好かれる。","even so"];
EXAMPLES[1219]=["All you have to do is try hard to master English.","君は英語を習得するために一生懸命努力しさえすればよい。","try hard"];
EXAMPLES[1220]=["You learn a lot about your own country if you live abroad.","外国に住むと自分の国のことが良く分かる。","live abroad"];
EXAMPLES[1221]=["I don't know what to do from now on.","これから先何をすべきか分からない。","from now on"];
EXAMPLES[1222]=["I wonder if you don't get tired of doing the same thing every day.","よくも飽きずに毎日同じ事ができるね。","get tired"];
EXAMPLES[1224]=["London, where I live, used to be famous for its fog.","ロンドンは、私の住んでいるところだが、以前は霧で有名だった。","be famous for"];
EXAMPLES[1225]=["I need a pencil. Can I borrow yours?","鉛筆がいるんだけど。あなたの貸してくれない？","Can I borrow yours"];
EXAMPLES[1228]=["I'm looking for a gift for my wife.","妻への贈り物を探しているんです。","I'm looking for a gift"];
EXAMPLES[1230]=["I'll take this one.","これをもらいます。","I'll take this one"];
EXAMPLES[1232]=["May I try it on?","着てみていいですか。","May I try it on"];
EXAMPLES[1233]=["Is there anything else I can help you with?","他に何か手伝えることはある？","I can help you"];
EXAMPLES[1236]=["Let's meet at the station at eight tomorrow morning.","明日の朝８時に駅で会いましょう。","Let's meet at the station"];
EXAMPLES[1238]=["Don't be aloof, let's go together.","水臭いこと言うなよ、一緒に行こう。","let's go together"];
EXAMPLES[1239]=["I can only say that I agree with you.","君に賛成だとしか言えない。","I agree with you"];
EXAMPLES[1240]=["Mm-hm. I think so too.","うん、僕もその通りだと思うよ。","I think so too"];
EXAMPLES[1241]=["It's up to you to get to school on time.","学校に定刻に着くのは君の責任です。","It's up to you"];
EXAMPLES[1242]=["That's a good idea!","良い考えだね！","That's a good idea"];
EXAMPLES[1243]=["I think you're right.","君の言うとおりだと思うよ。","you're right"];
EXAMPLES[1244]=["Welcome back, Tom. We've missed you.","お帰りなさい、トム。あなたがいなくて寂しかったのですよ。","Welcome back"];
EXAMPLES[1245]=["See you next week!","また来週！","See you next week"];
EXAMPLES[1246]=["Have a nice weekend.","楽しい週末をね。","Have a nice weekend"];
EXAMPLES[1249]=["Banks open at nine o'clock.","銀行は９時に開く。","at nine o'clock"];
EXAMPLES[1251]=["Far from being bored, I had a great time.","退屈するどころか、結構楽しかった。","I had a great time"];
EXAMPLES[1252]=["Please tell the chef it was delicious.","料理長においしかったとお伝え下さい。","it was delicious"];
EXAMPLES[1253]=["That's great. Nobody gives me anything.","いいですね。私には誰もなにもくれない。","That's great"];
EXAMPLES[1254]=["Excuse me, could you say that again more slowly?","すみません、もう一度ゆっくり言ってください。","could you say that again"];
EXAMPLES[1256]=["What does this mean?","これはどういう意味ですか。","What does this mean"];
EXAMPLES[1258]=["Let me check it.","見てみましょう。","Let me check"];
EXAMPLES[1259]=["Good luck on your test.","試験頑張ってね。","Good luck on your test"];
EXAMPLES[1260]=["You must be careful not to make him angry.","君は彼を怒らせないように気をつけなければならない。","be careful"];
EXAMPLES[1261]=["Please help yourself to some fruit.","果物を自由にとって食べて下さい。","help yourself"];
EXAMPLES[1262]=["How was your trip?","旅行はどうでしたか？","How was your trip"];
EXAMPLES[1263]=["May I take a message?","何か伝えておきましょうか。","May I take a message"];
EXAMPLES[1264]=["Can I leave a message?","伝言をお願いできますか。","Can I leave a message"];
EXAMPLES[1265]=["Turn left at the corner.","その角を左へ曲がりなさい。","Turn left at the corner"];
EXAMPLES[1267]=["Go straight ahead and you will find it. You can't miss it.","まっすぐ行けばわかります。見逃すことはありませんよ。","You can't miss it"];
EXAMPLES[1268]=["Could you tell me the way to the station?","駅へ行く道を教えていただけませんでしょうか。","Could you tell me the way"];
EXAMPLES[1273]=["How was your weekend?","週末はどうだった？","How was your weekend"];
EXAMPLES[1274]=["I went to the zoo yesterday.","昨日動物園に行った。","I went to the zoo"];
EXAMPLES[1275]=["I'm doing my homework.","私は私の宿題をしています。","I'm doing my homework"];
EXAMPLES[1277]=["Don't forget your umbrella.","傘忘れないでね。","Don't forget your umbrella"];
EXAMPLES[1278]=["Whoever leaves the office last should turn off the light.","事務所を最後に出る人は誰でも明かりを消さなければならない。","turn off the light"];
EXAMPLES[1279]=["The dinner is almost ready.","夕食の準備はほとんどできています。","dinner is almost ready"];
EXAMPLES[1280]=["I'm looking forward to it.","私は楽しみにしています。","I'm looking forward to it"];
EXAMPLES[1281]=["That's a relief to hear.","それを聞いて安心した。","That's a relief"];
EXAMPLES[1282]=["I don't think so.","私はそう思わない。","I don't think so"];
EXAMPLES[1283]=["It depends on the context.","それは文脈による。","It depends"];
EXAMPLES[1284]=["I prefer tea to coffee.","僕はコーヒーより紅茶が好きだ。","I prefer tea"];
EXAMPLES[1286]=["To start with, I must thank you for your help.","まず第一にあなたの援助にお礼を申し上げます。","thank you for your help"];
EXAMPLES[1287]=["I'm sorry I'm late, but there's been a lot of work to do.","遅くなってすいません、やる事がたくさんあったもので。","I'm sorry I'm late"];
EXAMPLES[1288]=["That's all right as far as I am concerned.","私に関する限り、それでよろしい。","That's all right"];
EXAMPLES[1291]=["I'd love to see the movie.","ぜひその映画を見てみたいです。","I'd love to"];
EXAMPLES[1292]=["That sounds good to me.","私はそれでもかまいませんよ。","sounds good to me"];
EXAMPLES[1293]=["Let's see if I've got that right.","では、確認させていただきます。","Let's see"];
EXAMPLES[1294]=["I have no idea what you mean.","私はあなたの言うことがさっぱりわかりません。","I have no idea"];
EXAMPLES[1295]=["What time is it now in San Francisco?","サンフランシスコは今何時ですか？","What time is it now"];
EXAMPLES[1296]=["I made a mistake through doing it in a hurry.","私はあわててやったので間違いをおかした。","I made a mistake"];
EXAMPLES[1297]=["Let's try again, guys!","みんな、もう一度やってみよう！","Let's try again"];
EXAMPLES[1298]=["How do I get to the airport?","空港へはどうやって行けばいいの？","How do I get to the airport"];
EXAMPLES[1299]=["Which train should I take to go to Shibuya?","渋谷に行くにはどの電車に乗ればいいですか？","Which train should I take"];
EXAMPLES[1301]=["Let's take a taxi.","タクシーに乗ろうよ。","Let's take a taxi"];
EXAMPLES[1302]=["How's the weather there?","そっちの天気は？","How's the weather there"];
EXAMPLES[1304]=["You had better take an umbrella with you.","傘を持っていった方がいいよ。","take an umbrella"];
EXAMPLES[1306]=["I like playing tennis.","私はテニスをするのが好きです。","I like playing tennis"];
EXAMPLES[1307]=["Do you play any sports?","君は何かスポーツをやりますか。","Do you play any sports"];
EXAMPLES[1308]=["I speak Japanese a little, but I'm not good at it, yet.","私は日本語が少し話せますが、まだ上手じゃありません。","I'm not good at it"];
EXAMPLES[1311]=["Better luck next time.","次はきっとうまくいきますよ。","Better luck next time"];
EXAMPLES[1312]=["Can you do me a favor?","お願いしたいことがあるのですが。","Can you do me a favor"];
EXAMPLES[1313]=["Of course you can take it if you want.","もちろん欲しければとってもいいよ。","Of course you can"];
EXAMPLES[1314]=["I'm afraid I can't help you.","お役に立てないと思います。","I'm afraid I can't"];
EXAMPLES[1316]=["That's fine with me.","私は結構ですよ。","That's fine with me"];
EXAMPLES[1317]=["What do you think I've been doing?","何をしてたと思う？","What do you think"];
EXAMPLES[1319]=["I can't decide unless you tell me your plan.","君の考えを話してくれなければ決断できないよ。","I can't decide"];
EXAMPLES[1320]=["Let's split the Bill.","支払いは割り勘にしよう。","Let's split the Bill"];
EXAMPLES[1321]=["No, no, it's on me.","いいえ、それは私のおごりです。","it's on me"];
EXAMPLES[1323]=["Everything will be fine.","全部うまくいくよ。","Everything will be fine"];
EXAMPLES[1324]=["Let me think about it and I'll get back to you.","この件につきましては、考えるお時間をいただけますか。こちらからまた改めてご連絡申し上げます。","Let me think about it"];
EXAMPLES[1325]=["I'll do my best not to disturb your studying.","あなたの勉強を邪魔しないようにします。","I'll do my best"];
EXAMPLES[1326]=["What happened? There's water all over the apartment.","何が起こったの？アパート全体水浸しだよ。","What happened"];
EXAMPLES[1327]=["I feel much better today.","今日はずっと具合がいい。","I feel much better"];
EXAMPLES[1328]=["I have a headache.","頭痛がする。","I have a headache"];
EXAMPLES[1329]=["I think you should see a doctor.","医者に見てもらうべきだと思う。","you should see a doctor"];
EXAMPLES[1330]=["Take this medicine in case you get sick.","具合が悪くなったらこの薬を飲みなさい。","Take this medicine"];
EXAMPLES[1331]=["Let's take a break for coffee.","休憩してコーヒーを飲もう。","Let's take a break"];
EXAMPLES[1334]=["Come on! We're going to be late.","急げ、さもないと遅れるぞ。","We're going to be late"];
EXAMPLES[1335]=["What's the date today?","今日は何日ですか。","What's the date today"];
EXAMPLES[1339]=["You shouldn't have done such a thing.","君はそんなことすべきではなかったのに。","You shouldn't have"];
EXAMPLES[1341]=["Make a wish and blow out the candles.","願いごとを言ってロウソクを吹いて消しなさい。","Make a wish"];
EXAMPLES[1342]=["That's very kind of you.","どうもご親切さま。","That's very kind of you"];
EXAMPLES[1343]=["Thanks for inviting me to the movies.","映画に誘ってくれてありがとう。","Thanks for inviting me"];
EXAMPLES[1344]=["I'm glad to hear that you've got well.","あなたがすっかり回復されたことを聞いて喜んでいます。","I'm glad to hear that"];
EXAMPLES[1346]=["I can't believe it!","信じられない！","I can't believe it"];
EXAMPLES[1347]=["What a surprise to see you here!","ここで君に会うとは驚きだ。","What a surprise"];
EXAMPLES[1348]=["I'll miss you so much.","きっとあなたが恋しくて仕方なくなるわ。","I'll miss you"];
EXAMPLES[1349]=["Let's keep in touch.","交際を続けましょう。","Let's keep in touch"];
EXAMPLES[1352]=["Could you take our picture?","写真を撮っていただけますか。","Could you take our picture"];
EXAMPLES[1353]=["I'm a little hungry.","ちょっと小腹がすいたな。","I'm a little hungry"];
EXAMPLES[1355]=["What would you like to drink?","何をお飲みになりますか。","What would you like"];
EXAMPLES[1357]=["I don't want anything to drink.","私は飲む物は何も欲しくはありません。","anything to drink"];
EXAMPLES[1359]=["Did you make this doll by yourself?","この人形は君一人で作ったの？","Did you make this"];
EXAMPLES[1360]=["Let me give you a hand.","手伝いましょう。","Let me give you a hand"];
EXAMPLES[1362]=["It was nice meeting you here.","ここで君に会えてうれしかった。","It was nice meeting you"];
EXAMPLES[1363]=["The same to you.","ご同様に。","same to you"];
EXAMPLES[1365]=["Can I ask you something strange?","変なこと聞いてもいい？","Can I ask you something"];
EXAMPLES[1368]=["I would like to try it. Where is the fitting room?","これを試着したいのですが。試着室はどこですか。","Where is the fitting room"];
EXAMPLES[1371]=["It doesn't fit here.","ここには収まらないわ。","It doesn't fit"];
EXAMPLES[1374]=["I'll think about it.","考えとくよ。","I'll think about it"];
EXAMPLES[1375]=["Excuse me. May I use your bathroom?","すみません。お手洗いをお借りしてもよろしいですか？","May I use your bathroom"];
EXAMPLES[1376]=["Make yourself at home.","勝手に何でも使って。","Make yourself at home"];
EXAMPLES[1377]=["Would you like some tea or coffee?","紅茶またはコーヒーはいかが？","Would you like some tea"];
EXAMPLES[1378]=["It's getting late. I don't wanna go home alone.","もう遅くなってきたし、ひとりで帰りたくないわ。","It's getting late"];
EXAMPLES[1383]=["Bye! Let's do this again!","バイバイ。また遊ぼうね！","Let's do this again"];
EXAMPLES[1384]=["I owe you one, Scott.","恩に着る、スコット。","I owe you one"];
EXAMPLES[1386]=["I was fat when I was a kid.","子供の時は、デブでした。","kid"];
EXAMPLES[1387]=["I am a big fan of the arts.","芸術が大好きだね。","fan"];
EXAMPLES[1388]=["I will contact you again in the future.","また後日、連絡します。","contact"];
EXAMPLES[1389]=["Please feel free to link to my page.","このページはリンクフリーです。","link"];
EXAMPLES[1390]=["The sale will be over in two days.","後二日でバーゲンがなくなる。","sale"];
EXAMPLES[1391]=["They had plenty of money for the tour.","彼らは旅行用のお金はたくさんもっていた。","tour"];
EXAMPLES[1392]=["This was an additional fund for buying books.","これは本を買うための足しになった。","additional"];
EXAMPLES[1393]=["I left the computer on, is that okay?","パソコンの電源つけっぱなしだけど、いいの？","computer"];
EXAMPLES[1394]=["The touching episode came home to me.","その痛ましいエピソードは私には痛切に感じられた。","episode"];
EXAMPLES[1395]=["To do her justice, she is not plain.","彼女を公平に評価すれば、彼女は不器量ではない。","justice"];
EXAMPLES[1396]=["He played a major part in the movement.","彼はその運動で主要な役割を果たした。","movement"];
EXAMPLES[1397]=["I found the photo you were looking for.","お探しの写真を見つけましたよ。","photo"];
EXAMPLES[1398]=["You should be more thoughtful of your safety.","君は自分の安全にもっと気を配るべきだ。","safety"];
EXAMPLES[1399]=["I went to the scene of the crime.","私は犯罪の現場に行ってみた。","scene"];
EXAMPLES[1400]=["The president made a statement on the issue.","大統領はその件について声明を発表した。","statement"];
EXAMPLES[1401]=["This team is trained by a good coach.","このチームはよいコーチに指導されている。","coach"];
EXAMPLES[1402]=["As compared with his, my collection is nothing.","私のコレクションは彼のものと比較すれば取るに足らない。","collection"];
EXAMPLES[1403]=["Do you have a lot of guns?","銃はたくさんありますか。","guns"];
EXAMPLES[1404]=["She walked about in search of the dress.","彼女はそのドレスを探すのに歩き回った。","search"];
EXAMPLES[1405]=["They set up their backs against the claim.","その要求に対して怒った。","claim"];
EXAMPLES[1406]=["My dad is not home at the moment.","今、父は家にいません。","dad"];
EXAMPLES[1407]=["What kind of job is he fit for?","彼はどんな仕事にむいているのですか。","fit"];
EXAMPLES[1408]=["He is generally at home in the evening.","彼は夜にはたいがい家にいる。","generally"];
EXAMPLES[1409]=["Which is the best hotel in the town?","その町で最高のホテルはどこですか。","hotel"];
EXAMPLES[1410]=["My dream is to be the First Lady.","私の夢は大統領夫人になることです。","Lady"];
EXAMPLES[1411]=["He is looked up to as a leader.","彼はリーダーとして尊敬されている。","leader"];
EXAMPLES[1412]=["Nobody that I know has been to Australia.","僕の知っている中ではオーストラリアに行ったことがある人はいない。","Nobody"];
EXAMPLES[1413]=["One plus two is equal to three.","１足す２は３である。","plus"];
EXAMPLES[1414]=["You're not a regular customer here, are you?","ここじゃ馴染みのない客だね。","regular"];
EXAMPLES[1415]=["Would you like to wait in the bar?","バーでお待ちになりますか。","bar"];
EXAMPLES[1416]=["The battle is not always to the strong.","戦いは強い者が勝つとはかぎらない。","battle"];
EXAMPLES[1417]=["It is said that she is seriously ill.","彼女は重病だそうだ。","seriously"];
EXAMPLES[1418]=["We had a lovely time at the dance.","ダンスパーティー、すごくすてきだったわ。","dance"];
EXAMPLES[1419]=["The Self Defense Forces were sent to Iraq.","自衛隊がイラクに派遣されたわ。","Defense"];
EXAMPLES[1420]=["I know this is none of my business.","私が口を挟むことではないのは分かってます。","none"];
EXAMPLES[1421]=["The pain in my back is getting worse.","私の背骨の痛みはひどくなっています。","worse"];
EXAMPLES[1422]=["It is necessary to prepare for the worst.","最悪の事態に備えることが必要です。","worst"];
EXAMPLES[1423]=["I want to be in a rock band.","ロックバンドに入りたいな。","band"];
EXAMPLES[1424]=["To put it clearly, I don't like him.","はっきり言ってぼくは彼がきらいだ。","clearly"];
EXAMPLES[1425]=["I will make every effort to get it.","私はそれを得るためにあらゆる努力をします。","effort"];
EXAMPLES[1426]=["Do you go to church on Christmas Day?","クリスマスの日に教会に行きますか。","Christmas"];
EXAMPLES[1427]=["Can you direct me to the post office?","郵便局へ行く道を教えてくれませんか。","direct"];
EXAMPLES[1428]=["Marriage is the last thing on my mind.","結婚するつもりなんかこれっぽっちもありません。","Marriage"];
EXAMPLES[1429]=["It's important to take care of your skin.","肌のお手入れは大切よ。","skin"];
EXAMPLES[1430]=["Thus they decided that I was innocent.","そういうわけで彼らは私が無実だと結論した。","Thus"];
EXAMPLES[1431]=["Will he be able to catch the train?","彼は列車に間に合うでしょうか。","catch"];
EXAMPLES[1432]=["The storm brought about a lot of damage.","嵐は大変な損害をもたらした。","damage"];
EXAMPLES[1433]=["I found it difficult to use the machine.","私はその機械を使うのは難しいと解った。","machine"];
EXAMPLES[1434]=["He is a professor of the medical department.","彼は医学部の教授だ。","professor"];
EXAMPLES[1435]=["The family is the basic unit of society.","家族は社会の基本的単位である。","basic"];
EXAMPLES[1436]=["They made John the captain of the team.","彼らはジョンをチームのキャプテンにした。","captain"];
EXAMPLES[1437]=["I think highly of your way of thinking.","私はあなたの考え方を高く評価しています。","highly"];
EXAMPLES[1438]=["It is not always easy to face reality.","現実に直面することは必ずしも簡単ではない。","reality"];
EXAMPLES[1439]=["The dog is called Spot by the family.","その犬は家族にスポットと呼ばれている。","Spot"];
EXAMPLES[1440]=["You are fully up to the challenge, right.","チャレンジ精神旺盛だね。","challenge"];
EXAMPLES[1441]=["I'd prefer not to comment on that now.","今は、それについてコメントしたくない。","comment"];
EXAMPLES[1442]=["I work in a travel agency.","私は旅行代理店で働いています。","agency"];
EXAMPLES[1443]=["This is the best camera in the store.","これが店で一番いいカメラです。","camera"];
EXAMPLES[1444]=["She devoted herself to mission work in Africa.","彼女はアフリカでの伝道の仕事に身をささげた。","mission"];
EXAMPLES[1445]=["I feel I'm growing out of pop music.","私はポップ・ミュージックはそろそろ卒業しようと思っているの。","pop"];
EXAMPLES[1446]=["The trial is not open to the public.","その裁判は公開されていない。","trial"];
EXAMPLES[1447]=["I want to have a cup of coffee.","私はコーヒーが飲みたい。","coffee"];
EXAMPLES[1448]=["I stand for freedom of speech for everyone.","私はあらゆる言論の自由に賛成だ。","freedom"];
EXAMPLES[1449]=["I have a job interview in the morning.","午前中は、就職面接があるの。","interview"];
EXAMPLES[1450]=["Is it OK if I change the channel?","チャンネル変えてもいい？","channel"];
EXAMPLES[1451]=["There is a little water in the glass.","コップに少し水が入っている。","glass"];
EXAMPLES[1452]=["Tom and Mary live in a mobile home.","トムとメアリーはトレーラーハウスで暮らしている。","mobile"];
EXAMPLES[1453]=["I would love to see the Northern Lights.","オーロラを見てみたいな。","Northern"];
EXAMPLES[1454]=["Jack is a powerful acquisition for our team.","ジャックは我がチームの強力な新メンバーだ。","powerful"];
EXAMPLES[1455]=["They may properly claim the protection of the law.","彼らが法律の保護を求めるのは当然だ。","protection"];
EXAMPLES[1456]=["The royal palace was built on a hill.","王宮は丘の上に建てられた。","royal"];
EXAMPLES[1457]=["Get away from the screen and have fun.","画面から離れて楽しんでね。","screen"];
EXAMPLES[1458]=["Please tell me when to serve the food.","いつ食事を出したらよいか教えて下さい。","serve"];
EXAMPLES[1459]=["I like the slow rhythm of that song.","あの歌のゆっくりしたリズムが好きです。","slow"];
EXAMPLES[1460]=["He was at the bottom of the class.","彼はクラスでびりだった。","bottom"];
EXAMPLES[1461]=["Please tell me how to start the engine.","エンジンのかけ方を教えてください。","engine"];
EXAMPLES[1462]=["The partner was discouraged to his large victory.","彼の大勝利に相手は落胆した。","partner"];
EXAMPLES[1463]=["He lives in the southern part of the city.","彼は市の南部に住んでいます。","southern"];
EXAMPLES[1464]=["That's a real one from a top brand.","それ本物のトップブランドだべ。","brand"];
EXAMPLES[1465]=["I was in time for the last bus.","最終バスに間に合ったよ。","bus"];
EXAMPLES[1466]=["He robbed me of every cent I had.","彼は私から有り金を全部奪った。","cent"];
EXAMPLES[1467]=["Such men count for much in the society.","そのような人が社会で重要なのだ。","count"];
EXAMPLES[1468]=["Legal changes threaten online sales in digital commerce.","法律の変更で、電子商取引におけるオンライン販売が脅かされている。","digital"];
EXAMPLES[1469]=["He is the lawful owner of the company.","彼はその会社の合法的な所有者だ。","owner"];
EXAMPLES[1470]=["The products are sold on a world scale.","その製品は世界的な規模で販売されている。","scale"];
EXAMPLES[1471]=["The lower a golf score is, the better.","ゴルフではスコアが少ないほど良い。","score"];
EXAMPLES[1472]=["I think this and that are separate things.","それとこれとは別だと思うよ。","separate"];
EXAMPLES[1473]=["Click the picture to go to the next page!","画像をクリックすると次ページへ移ります！","Click"];
EXAMPLES[1474]=["That kind of dress is now in fashion.","あの種の服が今流行だ。","fashion"];
EXAMPLES[1475]=["They decided to pull down the old building.","古い建物を取り壊すことに決めた。","pull"];
EXAMPLES[1476]=["If you push it, the door will open.","押せばドアが開きます。","push"];
EXAMPLES[1477]=["His behavior was often a target of criticism.","彼の振る舞いはしばしば非難の対象になった。","target"];
EXAMPLES[1478]=["He is now in the prime of manhood.","彼は今男盛りだ。","prime"];
EXAMPLES[1479]=["The ring was not to be found anywhere.","指輪はどこにも見つからなかった。","ring"];
EXAMPLES[1480]=["Do you know the difference between silver and tin?","銀とブリキの区別がつきますか。","silver"];
EXAMPLES[1481]=["The eye is the window of the soul.","目は心の窓である。","soul"];
EXAMPLES[1482]=["I am becoming a working adult in January.","社会人になって初めてのお正月です。","adult"];
EXAMPLES[1483]=["He has something of the artist in him.","彼にはかなり芸術的な素質がある。","artist"];
EXAMPLES[1484]=["Is there a paperback edition of this book?","この本のペーパーバック版はありますか。","edition"];
EXAMPLES[1485]=["The research institute was established in the late 1960s.","その研究所が設立されたのは１９６０年代後半です。","institute"];
EXAMPLES[1486]=["I am in favor of the option.","私はその意見に賛成だ。","option"];
EXAMPLES[1487]=["Is there somebody you want to talk to?","誰か話をしたい人はいる？","somebody"];
EXAMPLES[1488]=["I don't have the strength to keep trying.","私にはやり続けるだけの強さがない。","strength"];
EXAMPLES[1489]=["He wants to go back to the wild.","彼は野生に戻りたいと思っている。","wild"];
EXAMPLES[1490]=["He called out the name of the winner.","彼は優勝者の名前を大声で叫んだ。","winner"];
EXAMPLES[1491]=["There is a training camp with the club.","クラブで合宿がある。","camp"];
EXAMPLES[1492]=["He entered into the game with great spirit.","彼は元気に試合に参加した。","spirit"];
EXAMPLES[1493]=["Could you turn the television down a bit?","テレビの音を少し下げてくれませんか。","television"];
EXAMPLES[1494]=["I have the same trouble as you have.","私はあなたと同じ問題を抱えています。","trouble"];
EXAMPLES[1495]=["Japan is in the eastern part of Asia.","日本はアジアの東部にあります。","eastern"];
EXAMPLES[1496]=["They study about the function of the brain.","彼らは脳の機能について研究している。","function"];
EXAMPLES[1497]=["That child was happy to get the gift.","その子供は贈り物をもらってうれしかった。","gift"];
EXAMPLES[1498]=["Were you the one who shut the door?","ドアを閉めたのって、お前か？","shut"];
EXAMPLES[1499]=["He is a man of birth and breeding.","彼は生まれも育ちもいい人だ。","birth"];
EXAMPLES[1500]=["Send a copy of the report to me.","レポートのコピー、送って。","copy"];
EXAMPLES[1501]=["He assumed the leadership of the political party.","彼はその政党の主導権をにぎった。","leadership"];
EXAMPLES[1502]=["I was lucky to be there on time.","時間どおりに着いて運がよかった。","lucky"];
EXAMPLES[1503]=["You must request the latest version of the software.","あなたは新しいバージョンのソフトウェアを要求すべきである。","software"];
EXAMPLES[1504]=["I'd like to find out my bank balance.","残高を知りたいのですが。","balance"];
EXAMPLES[1505]=["You talk as if you were the boss.","まるで頭のような話し方をする。","boss"];
EXAMPLES[1506]=["I have no connection to the matter.","私はその件とは無関係だ。","connection"];
EXAMPLES[1507]=["I would like to try this dress on.","私は試しにこの服を着てみたいわ。","dress"];
EXAMPLES[1508]=["The magic of his words attracted the audience.","彼のことばの魔力が聴衆を魅了した。","magic"];
EXAMPLES[1509]=["We sent you the book at your request.","御依頼により本をお送りしました。","request"];
EXAMPLES[1510]=["I will stick a stamp on the envelope.","封筒に切手をはります。","stick"];
EXAMPLES[1511]=["He turned up the volume on the television.","彼はテレビの音量を大きくした。","volume"];
EXAMPLES[1512]=["Nothing is to be compared to its beauty.","何もその美しさとは比較にならない。","beauty"];
EXAMPLES[1513]=["He turned to the left at the corner.","彼は角で左に曲がった。","corner"];
EXAMPLES[1514]=["No cultural background is necessary to understand art.","芸術を理解するのに文化的背景は必要ではない。","cultural"];
EXAMPLES[1515]=["Do you think he is a good driver?","彼は運転がうまいと思いますか。","driver"];
EXAMPLES[1516]=["Have you come to file a damage report?","被害届を出すためにきたのか？","file"];
EXAMPLES[1517]=["I wish I could fly like a bird.","鳥のように空を飛べたらいいのになあ。","fly"];
EXAMPLES[1518]=["They are made in a variety of sizes.","それらはいろいろな大きさに作られている。","variety"];
EXAMPLES[1519]=["He was a hard worker in his youth.","若いときは、彼は働き者であった。","youth"];
EXAMPLES[1520]=["I think that my German is really bad.","私のドイツ語は本当にひどいものだと思う。","German"];
EXAMPLES[1521]=["He was an Australian, as I knew by his accent.","彼の言葉のなまりからわかったのだが、彼はオーストラリア人であった。","Australian"];
EXAMPLES[1522]=["He taught a group of Indian boys.","彼はインドの少年のグループを教えた。","Indian"];
EXAMPLES[1523]=["African elephants have less hair than Asian elephants.","アフリカゾウはアジアゾウより毛が少ない。","African"];
EXAMPLES[1524]=["What are you going to do this weekend?","今週末は何するの？","weekend"];
EXAMPLES[1525]=["Which is the more expensive of the two?","二つのうちのどちらが値段が高いんですか。","expensive"];
EXAMPLES[1526]=["It can't be helped.","仕方がないよ。","It can't be helped"];
EXAMPLES[1527]=["I appreciate it, but I think I shouldn't.","ありがとう、でも遠慮しておきます。","I appreciate it"];
EXAMPLES[1529]=["The parking lot is open to until when?","駐車場の営業時間は何時までですか？","until"];
EXAMPLES[1530]=["Sorry to bother you, but I'm afraid something urgent has come up.","ご迷惑をおかけしますが、急を要することが起こったものですから。","Sorry to bother you"];
EXAMPLES[1532]=["We spent the night in a cheap hotel.","私たちは安いホテルで一晩を過ごした。","cheap"];
EXAMPLES[1533]=["Please wait a minute.","少々お待ち下さい。","Please wait a minute"];
EXAMPLES[1534]=["She will attend the meeting instead of me.","彼女は私の代わりにその会合に出席するでしょう。","instead"];
EXAMPLES[1535]=["Well, but what about the money?","よろしい、でもお金はどうなるんだい。","what about"];
EXAMPLES[1536]=["My mother and I were in the garden.","母と私は庭にいました。","garden"];
EXAMPLES[1537]=["A poor school record will count against you when you look for a job.","学校の成績が悪いと仕事を探す時に不利だ。","look for"];
EXAMPLES[1538]=["Please speak more slowly.","もっとゆっくり言ってください。","Please speak more slowly"];
EXAMPLES[1539]=["We can't sleep because of the noise.","うるさくて眠れないんです。","because of"];
EXAMPLES[1540]=["Could you show me the way to the bus stop?","バス停までの道を教えてくれませんか。","Could you show me the way"];
EXAMPLES[1542]=["Please call me later.","あとで電話ちょうだい。","Please call me later"];
EXAMPLES[1544]=["May I borrow this book?","この本を借りてもいいですか。","May I borrow this book"];
EXAMPLES[1545]=["Please turn off the light.","ライトのスイッチを切ってください。","Please turn off the light"];
EXAMPLES[1546]=["Shall I help you with the washing-up?","汚れた食器を洗うのを手伝いましょうか。","Shall I help you"];
EXAMPLES[1547]=["Let me help you with your baggage.","荷物をお持ちしましょう。","Let me help you"];
EXAMPLES[1548]=["The team was quite nervous before the game.","そのチームは試合前でとても神経質になっていた。","nervous"];
EXAMPLES[1550]=["Life lies in front of you.","君には前途がある。","in front of"];
EXAMPLES[1552]=["I have to go to sleep.","私は眠らなければなりません。","have to"];
EXAMPLES[1553]=["Let me know if there is anything I can do.","何か私にできることがありましたらお知らせ下さい。","Let me know"];
EXAMPLES[1554]=["He is a bit on the heavy side.","彼は少々太りぎみです。","heavy"];
EXAMPLES[1555]=["Don't hesitate to tell me if you need anything.","何か必要なものがあったら、遠慮なく言ってください。","tell me if you need anything"];
EXAMPLES[1556]=["I need to ask you a silly question.","バカな質問があるんだ。","need to"];
EXAMPLES[1557]=["Hold on a second, I'll be right back. Don't hang up!","ちょっと待って、すぐ戻るから。切らないでよ！","I'll be right back"];
EXAMPLES[1558]=["How about some coffee?","コーヒーはどう？","How about some coffee"];
EXAMPLES[1560]=["We have a break from 10:40 to 11:00.","１０時４０分から１１時まで休み時間です。","break"];
EXAMPLES[1561]=["Let's eat out tonight.","今夜は外に食事をしに行きましょうか。","Let's eat out tonight"];
EXAMPLES[1562]=["I thought that we were going to win.","私たちは勝つものだと思っていました。","win"];
EXAMPLES[1563]=["Why don't you ask her yourself?","自分で聞いてみたら？","Why don't you ask her"];
EXAMPLES[1564]=["If I were healthy, I would be happy.","健康だったら、幸せなのになあ。","healthy"];
EXAMPLES[1565]=["Look at the sign in front of you.","目の前の貼り紙を見て。","sign"];
EXAMPLES[1566]=["That's fine, but how about this one?","それでもいいんだけど、こういうのはどうかしら？","how about this one"];
EXAMPLES[1567]=["Maybe you did do that the wrong way.","多分、間違ったやり方でやっちゃったんだよ。","Maybe"];
EXAMPLES[1568]=["How often do you go abroad?","君はどれくらいよく海外に行きますか。","How often"];
EXAMPLES[1569]=["It will hurt a little, but not much.","少しだけ痛いです。","hurt"];
EXAMPLES[1574]=["The cat has just passed by beside me.","ねこが私のそばを丁度今横切った。","beside"];
EXAMPLES[1576]=["Let's leave early in the morning, OK?","朝早く出発しましょうね。","Let's leave early"];
EXAMPLES[1577]=["We're going up into the mountains, so why don't you come with us?","山に行くところですが、ご一緒にどうですか。","why don't you come with us"];
EXAMPLES[1578]=["This is the time you should get up.","もう起きる時間ですよ。","should"];
EXAMPLES[1580]=["I'm free this afternoon.","今日の午後なら空いてるよ。","I'm free this afternoon"];
EXAMPLES[1582]=["I look forward to hearing your thoughts on this matter.","これにつきまして、お考えをお聞かせ願えればと存じます。","look forward to"];
EXAMPLES[1585]=["I went for a drive in the country.","私は田舎にドライブに出かけた。","drive"];
EXAMPLES[1587]=["I'm an idealist. I don't know where I'm going, but I'm on my way.","私は理想主義者だ。自分がどこに向かっているのかは分からないが、どこかに向かっているのは確かだ。","I'm on my way"];
EXAMPLES[1588]=["I'll be there at two o'clock without fail.","必ず２時にそこへ行きます。","I'll be there at two"];
EXAMPLES[1591]=["One is tall and the other is short.","一方は背が高く、もう一方は背が低い。","tall"];
EXAMPLES[1592]=["Are you busy now?","今は忙しいですか。","Are you busy now"];
EXAMPLES[1594]=["We have plenty of time tonight.","今夜は十分な時間がある。","We have plenty of time"];
EXAMPLES[1595]=["Sorry, I'm running late. I'm in traffic and the cars won't budge a bit.","ごめん遅れそう。渋滞してて車が動かないのよ。","I'm running late"];
EXAMPLES[1597]=["The tickets sold out within a week.","チケットは一週間で完売した。","sold out"];
EXAMPLES[1598]=["I forgot my homework.","宿題を忘れました。","I forgot my homework"];
EXAMPLES[1600]=["He was still at university at that time.","当時、あいつはまだ大学生だったよ。","university"];
EXAMPLES[1603]=["Kyoto gets lots of visitors from all over the world.","京都は世界中からたくさんの観光客が訪れる。","lots of"];
EXAMPLES[1605]=["Some people are anxious to invent convenient things.","便利なものを発明しようと熱心な人もいます。","invent"];
EXAMPLES[1607]=["One hundred and fifty thousand couples are expected to get married in Shanghai in 2006.","2006年上海では15万組の夫婦が結婚すると予想されている。","get married"];
EXAMPLES[1608]=["I passed the city hall on my way to the station.","駅へ行く途中で市役所の前を通った。","city hall"];
EXAMPLES[1609]=["May I use the computer?","パソコン使ってもいい？","May I use the computer"];
EXAMPLES[1610]=["The bank is next to the post office.","銀行は郵便局の隣です。","bank"];
EXAMPLES[1612]=["I was able to win the first prize.","私は１等賞を取ることができた。","prize"];
EXAMPLES[1617]=["Many people everywhere in the world want peace.","世界のいたる所で多くの人々が平和を望んでいる。","everywhere"];
EXAMPLES[1619]=["When is the best time to plant corn?","トウモロコシを植えるのに最適な時期はいつですか？","plant"];
EXAMPLES[1620]=["Are you planning to take part in the meeting?","君はその会合に出席するつもりですか。","take part in"];
EXAMPLES[1621]=["Do you have a larger size?","もっと大きいサイズはありますか。","Do you have a larger size"];
EXAMPLES[1622]=["Have I hit the nail on the head?","図星ですか？","hit"];
EXAMPLES[1623]=["Where can I try this on?","どこで試着できますか。","can I try this on"];
EXAMPLES[1624]=["Are you angry because of what I said?","君は僕が言ったことに腹を立てているのか。","angry"];
EXAMPLES[1625]=["Well done! Your parents must be proud of you.","でかしたね。ご両親もさぞかし鼻が高いでしょうね。","be proud of"];
EXAMPLES[1626]=["The room is dirty, so I'll clean it.","部屋が汚いので、掃除します。","dirty"];
EXAMPLES[1627]=["Do you take credit cards?","クレジットカードは使えますか。","Do you take credit cards"];
EXAMPLES[1629]=["I have made a promise to do it.","私はそれをすると言う約束をした。","promise"];
EXAMPLES[1630]=["John talked with his customer on the phone.","ジョンはお客さんと電話で話した。","customer"];
EXAMPLES[1632]=["He is twice as old as she is.","彼の年齢は彼女の倍である。","twice"];
EXAMPLES[1634]=["Here is your change.","はい、おつりです。","Here is your change"];
EXAMPLES[1635]=["I had to speak at a moment's notice.","私は何の予告もされないでその場で話をしなければならなかった。","notice"];
EXAMPLES[1636]=["This is the place where the accident was.","ここがあの事故があった場所です。","accident"];
EXAMPLES[1637]=["It took me more than two hours to translate a few pages of English.","２、３ページの英語を訳すのに２時間以上もかかりました。","more than"];
EXAMPLES[1638]=["Could I have some water?","お水をいただけますか。","Could I have some water"];
EXAMPLES[1639]=["The cost of the book is 4 dollars.","この本の値段は、４ドルです。","cost"];
EXAMPLES[1640]=["I want you to keep up with me.","こちらの調子に合わせてください。","keep"];
EXAMPLES[1642]=["This is why I was late for school.","こういうわけで私は学校に遅れた。","late"];
EXAMPLES[1644]=["I ran in order to be on time.","間に合うように走ってきたんです。","order"];
EXAMPLES[1646]=["You may as well withdraw from the club right away.","君は直ちにクラブを脱退したほうがよい。","right away"];
EXAMPLES[1647]=["Is it far from here?","ここから遠いの？","far from"];
EXAMPLES[1648]=["Pick up your things and go away.","あなたの物を持って行け。","Pick up"];
EXAMPLES[1649]=["Is breakfast included in the price?","朝食込みの値段ですか？","Is breakfast included"];
EXAMPLES[1651]=["I have to pay a little more attention.","もうちょっと注意しないと。","attention"];
EXAMPLES[1652]=["She would not give in to her husband.","彼女はどうしても夫に折れようとしなかった。","husband"];
EXAMPLES[1654]=["She is going to have an international marriage.","彼女は国際結婚をするつもりです。","international"];
EXAMPLES[1657]=["If it gets boring, I will go home.","つまんなかったら帰る。","boring"];
EXAMPLES[1659]=["I was very glad to hear the news.","その知らせを聞いてとてもうれしかった。","glad"];
EXAMPLES[1660]=["It's below her to say such a thing.","そんなことを言うのは彼女にふさわしくない。","below"];
EXAMPLES[1662]=["The streets of New York are very wide.","ニューヨークの道路はとても広い。","wide"];
EXAMPLES[1664]=["It is amazing that you won the prize.","君が入賞したのには驚いた。","amazing"];
EXAMPLES[1665]=["How long does it take to get to the station?","あなたが駅に着くのにどのくらいかかりますか。","How long does it take"];
EXAMPLES[1666]=["The price of the car is too high.","その車の値段は高すぎる。","price"];
EXAMPLES[1668]=["Even if I try, it's no use, anyway.","俺なんかどうせやっても無駄だよ。","anyway"];
EXAMPLES[1669]=["Go straight ahead until you reach the church.","教会に着くまでまっすぐ行きなさい。","Go straight ahead"];
EXAMPLES[1670]=["Is this the right way to Yokohama Station?","横浜駅へ行くのにはこの道でいいのですか。","Is this the right way"];
EXAMPLES[1671]=["Bill was singled out for a special award.","ビルが特別賞に選ばれた。","award"];
EXAMPLES[1672]=["I got off at the wrong station.","私は駅を間違えて下車しました。","I got off at the wrong station"];
EXAMPLES[1673]=["You can see the ocean on your right.","右手に海が見えますよ。","ocean"];
EXAMPLES[1674]=["Would you please tell me when to get off?","いつ降りたらよいか教えて下さい。","please tell me when to get off"];
EXAMPLES[1675]=["You're still working part time at a bakery?","パン屋のバイトまだやってるの？","bakery"];
EXAMPLES[1677]=["He is to come to my house tonight.","彼は今晩私の家に来ることになっています。","tonight"];
EXAMPLES[1678]=["You had better take an umbrella with you.","傘を持っていった方がいいよ。","take an umbrella with you"];
EXAMPLES[1679]=["It is you who is in the wrong.","間違っているのは君だ。","wrong"];
EXAMPLES[1680]=["Spring is my favorite season.","春は、私が一番好きな季節です。","Spring is my favorite season"];
EXAMPLES[1682]=["I tried to imagine life on the moon.","私は月での生活を想像してみた。","imagine"];
EXAMPLES[1684]=["What would the world be like without women?","女性がいなければ世界はどうなっていただろう。","without"];
EXAMPLES[1686]=["You can see a house through the trees.","木立の合間から家が見えます。","through"];
EXAMPLES[1687]=["Since when have you not had a girlfriend?","いつから彼女いないの？","Since"];
EXAMPLES[1688]=["Do you see a ship on the horizon?","水平線に船が見えますか。","horizon"];
EXAMPLES[1690]=["Could you turn on the light, please?","明かりをつけてくれませんか。","turn on"];
EXAMPLES[1691]=["How are you feeling this morning?","今朝は気分はいかがですか。","How are you feeling"];
EXAMPLES[1692]=["Turn off the television. I can't concentrate.","気が散るからテレビを消してくれ。","Turn off"];
EXAMPLES[1693]=["I have a fever of 102 degrees.","１０２゜Ｆの熱があります。","I have a fever"];
EXAMPLES[1694]=["It was a party to celebrate her birthday.","それは彼女の誕生日を祝うパーティーだった。","celebrate"];
EXAMPLES[1695]=["There's nothing to be afraid of.","恐いものは、何もない。","be afraid of"];
EXAMPLES[1696]=["This rule has no application to the case.","この規則はその事例に適用できない。","rule"];
EXAMPLES[1697]=["You'll have to get off at the bank and take the A52.","銀行のところで降りて、Ａ５２に乗り換えないと駄目ですよ。","get off"];
EXAMPLES[1698]=["I was very careful, but I caught a cold.","気をつけていたのに、風邪をひいてしまいました。","I caught a cold"];
EXAMPLES[1699]=["I have no more money in my wallet.","財布に金が無くなった。","wallet"];
EXAMPLES[1700]=["You should get some rest.","ちょっと休んだほうがいいよ。","You should get some rest"];
EXAMPLES[1701]=["Why did you try to run away?","君はなぜ逃げ出そうとしたのですか。","run away"];
EXAMPLES[1703]=["My stomach hurts. Can I have some stomach medicine?","おなかが痛いんです。胃腸薬をください。","My stomach hurts"];
EXAMPLES[1704]=["It's no crime to steal from a thief.","泥棒から盗むのは罪じゃない。","steal"];
EXAMPLES[1706]=["The eye is the mirror of the soul.","目は心の鏡。","mirror"];
EXAMPLES[1707]=["I think you had better stay with us.","君は私たちの家に泊まったほうがよいと思う。","stay with"];
EXAMPLES[1708]=["Don't stay up late every night.","毎晩遅くまで起きていてはいけない。","Don't stay up late"];
EXAMPLES[1709]=["Drink plenty of water.","水をたくさん飲んでね。","Drink plenty of water"];
EXAMPLES[1710]=["Get over here and be quick about it!","こっちへ来い、ぐずぐずしないで。","quick"];
EXAMPLES[1711]=["I twisted my ankle.","足首をひねった。","I twisted my ankle"];
EXAMPLES[1712]=["Not bad. But I'm a little tired.","悪くないよ。でも、ちょっと疲れてるんだ。","I'm a little tired"];
EXAMPLES[1713]=["Oh, you must be good at sports.","へえ、きっとスポーツが得意なんだろうね。","be good at"];
EXAMPLES[1714]=["Of all these cakes, I like this one best.","これらすべてのケーキの中で、私はこれが一番好きだ。","I like this one"];
EXAMPLES[1715]=["He is the minister responsible for the environment.","彼が環境担当の大臣です。","environment"];
EXAMPLES[1716]=["There is a large hole in the wall.","壁に大きな穴が開いています。","hole"];
EXAMPLES[1718]=["He cut his finger in opening a can.","彼は缶詰をあけているうちに指を切った。","finger"];
EXAMPLES[1720]=["The earth is the shape of an orange.","地球はオレンジの形をしています。","shape"];
EXAMPLES[1721]=["He is a big man in the company.","彼は会社の重要人物だ。","company"];
EXAMPLES[1722]=["I prefer tea to coffee.","僕はコーヒーより紅茶が好きだ。","I prefer tea to coffee"];
EXAMPLES[1723]=["You have a good taste in interior design.","インテリアの趣味がいいですね。","taste"];
EXAMPLES[1724]=["This is my favorite song.","これね、私が一番好きな曲なの。","This is my favorite song"];
EXAMPLES[1725]=["It is in fact your fault.","それは実際君の所為である。","in fact"];
EXAMPLES[1727]=["You should prepare a room for the visitor.","客のために部屋を準備しておきなさい。","visitor"];
EXAMPLES[1728]=["I enjoy reading, cuddling by the fireplace and slow dancing.","読書と暖炉の側で抱き合うのとスローダンスが好き。","I enjoy reading"];
EXAMPLES[1729]=["It made my blood boil to hear that.","それを聞いてはらわたが煮えくり返った。","boil"];
EXAMPLES[1730]=["He grew up to be a great person.","彼は成長し立派な人間になった。","grew"];
EXAMPLES[1731]=["We're joined by the red string of fate!","運命の赤い糸でつながってるんだよ。","joined"];
EXAMPLES[1736]=["Can I have a few words with you?","ちょっと顔を貸してくれませんか。","few"];
EXAMPLES[1737]=["We won the match by 10 to 4.","私たちは１０対４の得点で試合に勝った。","We won the match"];
EXAMPLES[1738]=["You have to have a piece of pie.","ぜひパイをお召し上がりください。","piece"];
EXAMPLES[1741]=["This is the reason why he did it.","これが、彼がそうした理由です。","reason"];
EXAMPLES[1742]=["We spent a peaceful day in the countryside.","我々は田舎で穏やかな一日を過ごした。","peaceful"];
EXAMPLES[1744]=["Do you think that you can handle it?","自分の手に負えると思う？","handle"];
EXAMPLES[1746]=["I am thirsty. Give me something to drink!","喉がカラカラ。なんか飲み物！","thirsty"];
EXAMPLES[1748]=["Please leave a message on my answering machine.","留守番電話にメッセージを入れてください。","Please leave a message"];
EXAMPLES[1750]=["The more you have, the more you want.","多く持てば持つほど欲しくなる。","more"];
EXAMPLES[1751]=["What is the main purpose of this plan?","この計画の主な目的はなんですか。","purpose"];
EXAMPLES[1753]=["Just a moment, please.","ちょっと待って下さい。","Just a moment"];
EXAMPLES[1754]=["The line is busy again.","また話し中だ。","The line is busy"];
EXAMPLES[1756]=["My phone is out of battery.","携帯の電池が切れてしまった。","My phone is out of battery"];
EXAMPLES[1757]=["Tommy, can you hear me?","トミー、聞こえるかい？","can you hear me"];
EXAMPLES[1758]=["Help me move it out of the way.","邪魔にならないように動かすの手伝って。","move"];
EXAMPLES[1760]=["My daughter is the same age as you.","娘は、あなたと同い年よ。","daughter"];
EXAMPLES[1762]=["Above all, try to be kind to the old.","何よりもまず、老人に親切にするように努めなさい。","be kind to"];
EXAMPLES[1764]=["I don't agree with him.","彼には賛成できません。","agree with"];
EXAMPLES[1766]=["Can you fix him up for the night?","今晩泊めてくれないかな。","fix"];
EXAMPLES[1767]=["I want you to be by my side.","私のそばにいて欲しい。","side"];
EXAMPLES[1769]=["I can't find my key.","鍵が見つからない。","I can't find my key"];
EXAMPLES[1770]=["Waaahhh! I lost my wallet.","ウワーン。財布をなくした！","I lost my wallet"];
EXAMPLES[1771]=["The watch was not to be found anywhere.","腕時計はどこにも見つからなかった。","anywhere"];
EXAMPLES[1775]=["I feel that something is wrong.","何かおかしいと思います。","something is wrong"];
EXAMPLES[1777]=["I can't think about the design any more.","もうこれ以上、デザインを考えられない。","design"];
EXAMPLES[1778]=["We have a 20% share of the market.","私達の市場シェアは２０％です。","share"];
EXAMPLES[1779]=["I know that you did your best.","きみが全力をつくしたことをぼくは知っている。","you did your best"];
EXAMPLES[1780]=["When and where did you receive the gift?","いつ、どこでその贈り物を受け取ったのですか。","receive"];
EXAMPLES[1781]=["Too much smoking tends to injure the voice.","煙草を吸い過ぎると、声を悪くしやすい。","injure"];
EXAMPLES[1783]=["She drew back in horror at the sight.","彼女はその光景を見て恐怖で後ずさりした。","horror"];
EXAMPLES[1784]=["We got her to attend to the patient.","我々は彼女に病人を看護してもらった。","attend"];
EXAMPLES[1785]=["Kyoto is visited by many people every year.","京都は、毎年多くの人々に訪れられます。","every year"];
EXAMPLES[1786]=["I don't think you need to worry so much; you'll be fine.","そんなに心配しなくても大丈夫なんじゃないかな。","you'll be fine"];
EXAMPLES[1787]=["You can take your time.","自分のペースでやってください。","take your time"];
EXAMPLES[1788]=["I don't have the strength to keep trying.","私にはやり続けるだけの強さがない。","keep trying"];
EXAMPLES[1789]=["I'm happy for you.","よかったね。","I'm happy for you"];
EXAMPLES[1790]=["It sounds fun. Let's do it!","楽しそう。やろうやろう！","sounds fun"];
EXAMPLES[1791]=["We should tell children how to protect themselves.","自分を守る方法を子供たちに教えるべきだ。","protect"];
EXAMPLES[1792]=["Please set the table.","食卓を膳立てしてください。","Please set the table"];
EXAMPLES[1793]=["The house was built in the 16th century.","この家は１６世紀に建てられました。","century"];
EXAMPLES[1794]=["Bill was late for school as usual.","ビルはいつものように学校に遅刻した。","as usual"];
EXAMPLES[1796]=["What is the difference between this and that?","これとそちらとの違いは何だい。","difference"];
EXAMPLES[1798]=["Believe it or not, I can actually draw.","信じられないかもしれないが、実際私は絵を描けるんだよ。","actually"];
EXAMPLES[1799]=["I'm doing the laundry while the weather is good.","天気がいい内に、洗濯をしています。","I'm doing the laundry"];
EXAMPLES[1800]=["We would play baseball after school in those days.","我々はその当時よく放課後に野球をしたものだった。","in those days"];
EXAMPLES[1802]=["I used to work in a noisy room.","よく騒がしい部屋で働いたものだった。","noisy"];
EXAMPLES[1803]=["It was only recently that he got well.","彼が良くなったのはつい最近の事です。","recently"];
EXAMPLES[1805]=["The fact is I do not love her.","実は私は彼女を愛してはいないのです。","fact"];
EXAMPLES[1806]=["Turn on the light please.","どうか明かりをつけて下さい。","Turn on the light please"];
EXAMPLES[1807]=["I lost sight of him on the way.","私は途中で彼とはぐれてしまった。","sight"];
EXAMPLES[1808]=["They looked on him as a great judge.","彼らは彼を偉大な判事だと見なしていた。","judge"];
EXAMPLES[1810]=["I am going to complain to the manager.","支配人に文句を言ってやる。","complain"];
EXAMPLES[1811]=["I'll be back by six o'clock.","六時までに戻る。","I'll be back by six"];
EXAMPLES[1812]=["The place is easy to reach from here.","その場所にはここから簡単に行ける。","reach"];
EXAMPLES[1813]=["But I have an appointment with my client tomorrow.","だけど、明日はお客さんとも会わなくちゃいけないし・・・。","I have an appointment"];
EXAMPLES[1814]=["I need to make a copy.","コピーとっとかなきゃ。","I need to make a copy"];
EXAMPLES[1816]=["It is up to you to support him.","彼を養うのは君の責任だ。","support"];
EXAMPLES[1817]=["It's just around the corner.","すぐその角を曲がったところだ。","It's just around the corner"];
EXAMPLES[1818]=["I have nothing to do with the matter.","僕はその件と何も関係がない。","matter"];
EXAMPLES[1821]=["This is my first time to be here.","ここに来るのは初めてなんです。","This is my first time"];
EXAMPLES[1822]=["They are a good airline to fly with.","あれは空の旅に利用するにはいい航空会社だ。","airline"];
EXAMPLES[1823]=["No, this is my second time.","いや、これが二回目だ。","this is my second time"];
EXAMPLES[1824]=["I finally found the solution to the problem.","私はついにこの問題の解答を見出した。","finally"];
EXAMPLES[1826]=["It's OK to cry when you need to.","泣きたい時には泣けばいいんだよ。","cry"];
EXAMPLES[1827]=["Did you fall in love with her at first sight?","君は彼女にひとめぼれしたのかい。","at first"];
EXAMPLES[1829]=["What grade did you get on the test?","試験の成績はどうだった。","grade"];
EXAMPLES[1831]=["I tried to warn her, but she wouldn't listen.","注意しようとしたが、聞く耳を持たなかった。","warn"];
EXAMPLES[1832]=["This house is very comfortable to live in.","この家は住むのにとても快適だ。","comfortable"];
EXAMPLES[1833]=["The addition of salt greatly improved the flavor.","塩を加えたら味が大いに良くなった。","flavor"];
EXAMPLES[1834]=["The shape of a box is usually square.","箱の形は普通四角です。","square"];
EXAMPLES[1835]=["English is a kind of universal language.","英語は一種の世界言語である。","a kind of"];
EXAMPLES[1836]=["I don't want the investigation to burn out.","捜査を立ち消えにしてほしくない。","burn"];
EXAMPLES[1837]=["If only you had told me the whole story at that time!","君があの時一部始終を私に話してくれていたらよかったのに。","at that time"];
EXAMPLES[1838]=["Are you going to continue working until 10:00?","１０時まで仕事を頑張るつもりですか？","continue"];
EXAMPLES[1839]=["He said that he must see the manager.","彼は支配人に会わなければならないと言った。","manager"];
EXAMPLES[1840]=["You are not at all wrong.","君は必ずしも間違ってはいない。","not at all"];
EXAMPLES[1841]=["It is said that he will go abroad.","彼は海外に行くそうです。","abroad"];
EXAMPLES[1842]=["She is a teacher fresh from the university.","彼女はその大学をでたばかりの教師だ。","fresh"];
EXAMPLES[1843]=["I have been silent for a long time.","長いことごぶさたしました。","silent"];
EXAMPLES[1844]=["He has several men to work for him.","彼には、自分のために働いてくれる部下が数名いる。","several"];
EXAMPLES[1845]=["However, we can be people of the earth.","しかし、地球人になることは可能なのです。","However"];
EXAMPLES[1846]=["That book is of no interest to me.","その本には興味はないなぁ。","interest"];
EXAMPLES[1847]=["With hunger and fatigue, the dog died at last.","空腹やら疲労やらで、その犬はとうとう死んだ。","at last"];
EXAMPLES[1848]=["I want to go somewhere on a trip.","どこか旅行に行きたい。","somewhere"];
EXAMPLES[1849]=["Mike was very kind. He got my car repaired for free.","マイクはとても親切でした。彼は私の車を無料で修理してくれました。","for free"];
EXAMPLES[1850]=["Each party shall consist of no less than fifteen people.","各隊は少なくとも十五人以上で構成すること。","less than"];
EXAMPLES[1851]=["In this case, I think he is correct.","この件では私は彼が正しいと思うの。","correct"];
EXAMPLES[1852]=["I think that it was probably last Friday.","たしか先週の金曜日だったと思います。","probably"];
EXAMPLES[1853]=["The meeting is to be held at three.","その会は３時から行われることになっています。","held"];
EXAMPLES[1854]=["He turned his back on the old tradition.","彼は古い伝統に背を向けた。","tradition"];
EXAMPLES[1855]=["Cover the seeds with a bit of soil.","種の上に少し土をかぶせなさい。","soil"];
EXAMPLES[1856]=["We won the match by 10 to 4.","私たちは１０対４の得点で試合に勝った。","won"];
EXAMPLES[1857]=["Exchange the old part for a new one.","古い部品を新しいのと交換しなさい。","Exchange"];
EXAMPLES[1858]=["The police were heading for a shake down.","警察は徹底的捜査をしようとしてた。","shake"];
EXAMPLES[1859]=["The problem is how to raise the funds.","問題はいかにして資金を集めるかである。","raise"];
EXAMPLES[1860]=["As to me, I agree to the plan.","私に関して言えば、その計画には賛成だ。","agree"];
EXAMPLES[1861]=["A dog has a sharp sense of smell.","犬はにおいの感覚が鋭い。","smell"];
EXAMPLES[1862]=["I like both that one and this one.","あっちのもこっちのも両方とも気に入ってるよ。","both"];
EXAMPLES[1863]=["This house is too narrow to live in.","この家は住むには狭すぎる。","narrow"];
EXAMPLES[1864]=["I hope to graduate from university next spring.","私は来春大学を卒業したいです。","graduate"];
EXAMPLES[1865]=["This work can be done within a week.","この仕事は１週間以内にできる。","within"];
EXAMPLES[1866]=["It is dangerous to play in the street.","通りで遊ぶと危険です。","dangerous"];
EXAMPLES[1867]=["I read the book from beginning to end.","私はその本を初めから終わりまで読んだ。","beginning"];
EXAMPLES[1868]=["Watermelons are in season now.","スイカは今が出盛りだ。","in season"];
EXAMPLES[1869]=["For the love of Heaven, don't get angry.","お願いだから、怒らないでください。","Heaven"];
EXAMPLES[1870]=["Social unrest may come about as a result of the endless rising of prices.","間断ない物価上昇の結果、社会不安が起こるかもしれない。","as a result of"];
EXAMPLES[1871]=["Are you sure this is the right address?","本当にこれが正しい住所なの？","address"];
EXAMPLES[1872]=["Today, we had an evacuation drill at school.","今日、学校で避難訓練をしました。","evacuation"];
EXAMPLES[1873]=["I found the key I was looking for.","私は探していた鍵を見つけた。","found"];
EXAMPLES[1874]=["I have no personal hostility to the system.","その制度に対する個人的な敵意はない。","personal"];
EXAMPLES[1875]=["You should pay your rent in advance.","君は部屋代を前もって払うべきだ。","in advance"];
EXAMPLES[1876]=["If I drop out of contact, let the police know, OK?","もし音信不通になったら警察に連絡してね。","drop out"];
EXAMPLES[1877]=["The people of America fought for their independence.","米国の人民は独立のために戦った。","independence"];
EXAMPLES[1878]=["I was taken in by his gentle manner.","彼の親切な態度にすっかり騙された。","gentle"];
EXAMPLES[1879]=["A second is a sixtieth part of a minute.","一秒は一分の六十分の一です。","A second"];
EXAMPLES[1880]=["They, as well as you, are ordinary people.","あなた方ばかりでなく彼らも普通の人々だ。","ordinary"];
EXAMPLES[1881]=["These days more and more people are traveling abroad.","近頃外国旅行をする人がだんだん増えている。","more and more"];
EXAMPLES[1882]=["The sentence is fine the way it is.","この文はこのままでも大丈夫だよ。","sentence"];
EXAMPLES[1883]=["Susie sat up until midnight, when she heard a strange noise.","スージーは真夜中までおきていた。すると奇妙な物音が聞こえた。","up until"];
EXAMPLES[1884]=["I read the whole book in a day.","一日で完読しました。","whole"];
EXAMPLES[1885]=["I practiced calligraphy while looking at the model drawing.","手本を見ながら習字をしました。","calligraphy"];
EXAMPLES[1886]=["It took me some time to calm down.","冷静になるのに少し時間がかかりました。","calm"];
EXAMPLES[1887]=["We can see thousands of stars in the sky.","空に数千の星を見ることができる。","thousands of"];
EXAMPLES[1889]=["For all his wealth, he was still unhappy.","彼は金持ちにもかかわらず不幸でした。","unhappy"];
EXAMPLES[1890]=["There is almost no violence in that city.","その市にはほとんど暴力事件はない。","violence"];
EXAMPLES[1891]=["Awesome! The cherry trees are blooming already.","すごい！もう桜が咲いてるよ。","Awesome"];
EXAMPLES[1892]=["The enemy of my enemy is my friend.","敵の敵は味方です。","enemy"];
EXAMPLES[1893]=["I have someone I want you to meet.","会ってほしい人がいるんだ。","someone"];
EXAMPLES[1894]=["I hit the mark with the arrow.","私は矢を的に当てた。","arrow"];
EXAMPLES[1895]=["Do not bother to come to my home.","わざわざ家に来なくてもいいですよ。","bother"];
EXAMPLES[1896]=["He had plenty of fight left in him.","彼にはまだ多くの闘志が残っていた。","fight"];
EXAMPLES[1897]=["If it is worth doing, do it well.","それをやる価値があるなら、立派にやれ。","worth"];
EXAMPLES[1898]=["Such is the custom of the people here.","そういうのがここの人たちの習慣だ。","custom"];
EXAMPLES[1899]=["No one expected him to announce his candidacy again.","彼がまた立候補するとは誰も予期していなかった。","announce"];
EXAMPLES[1900]=["It is illegal to park a car there.","あそこに駐車するのは違法です。","illegal"];
EXAMPLES[1901]=["The use of electronic computers is growing rapidly.","コンピューターの使用は急速に増加しつつある。","electronic"];
EXAMPLES[1902]=["I have a bicycle of the latest model.","私は最新型の自転車を持っている。","latest"];
EXAMPLES[1903]=["I had to take shelter under a tree.","木の下で雨宿りしなければなりませんでした。","shelter"];
EXAMPLES[1904]=["I all but lost you in the crowd.","私は人ごみの中で君をもう少しで見失うところだった。","crowd"];
EXAMPLES[1905]=["Tom always gets the job done surprisingly fast.","トムはいつも驚くほど仕事が早い。","surprisingly"];
EXAMPLES[1907]=["I had my only son die of cancer.","私はガンで一人息子に死なれた。","cancer"];
EXAMPLES[1908]=["I'll find someone to fill in for you.","君の代行者を見つけよう。","fill"];
EXAMPLES[1909]=["The number of mistakes is ten at most.","間違いの数は多くて１０個です。","at most"];
EXAMPLES[1910]=["Your composition was good except for the spelling.","君の作文は綴り字以外はよく書けていた。","spelling"];
EXAMPLES[1911]=["My brother is working at a gas station.","私の兄は、ガソリンスタンドで働いている。","gas"];
EXAMPLES[1912]=["I'll get something to drink for both of you.","君たち二人に何か飲み物を持ってきてあげよう。","both of"];
EXAMPLES[1913]=["The question is how to avoid nuclear war.","問題は、いかに核戦争を避けるかである。","nuclear"];
EXAMPLES[1914]=["This is the reason I disagree with you.","こういうわけで私はあなたに反対なのです。","disagree"];
EXAMPLES[1915]=["We think nuclear weapons will destroy our earth.","核兵器はわが地球を滅ぼすと思う。","destroy"];
EXAMPLES[1916]=["Let's eat out for a change.","気分転換に外食しましょう。","eat out"];
EXAMPLES[1917]=["I would like to give him a present for his birthday.","彼の誕生日に贈り物をあげたいんです。","would like to"];
EXAMPLES[1918]=["Compared to our house, his is a palace.","我々の家と比べると、彼の家は宮殿だ。","palace"];
EXAMPLES[1919]=["Did you really bake the pie by yourself?","そのパイ本当に自分で作ったの？","bake"];
EXAMPLES[1921]=["The functions of his brain were very active.","彼の頭脳の働きは活発だった。","brain"];
EXAMPLES[1923]=["He's going to get fired.","彼はクビになるだろうね。","get fired"];
EXAMPLES[1924]=["She was on the border of killing herself.","彼女は自殺寸前だった。","border"];
EXAMPLES[1925]=["He is a specialist in sustainable development.","彼は持続可能な開発の専門家です。","sustainable"];
EXAMPLES[1926]=["You must encourage him to try again.","もう一度やってみるようにと彼を励ましなさい。","encourage"];
EXAMPLES[1927]=["Fossil fuel prices shot through the roof.","化石燃料の値段が急騰した。","Fossil fuel"];
EXAMPLES[1928]=["It is a matter of life or death.","それは命にかかわる問題だ。","death"];
EXAMPLES[1929]=["The inventor is known all over the world.","その発明家は世界中に知られている。","inventor"];
EXAMPLES[1930]=["2013 is the year that I was born.","２０１３年は僕が生まれた年なんだ。","born"];
EXAMPLES[1931]=["I was never in the habit of lying.","嘘つきなんかじゃなかった。","habit"];
EXAMPLES[1932]=["Once a month, I go to the barber.","月に一度、床屋に行きます。","barber"];
EXAMPLES[1933]=["In case of an emergency, call the police.","緊急の場合は警察を呼びなさい。","emergency"];
EXAMPLES[1934]=["Steady the boat so we can get on safely.","安全に乗れるようボートを押さえてくれ。","get on"];
EXAMPLES[1935]=["Did you see the news about the earthquake?","地震のニュース見た？","earthquake"];
EXAMPLES[1936]=["You'd better take your umbrella, just in case it rains.","雨が降るといけないので、傘を持っていった方がいい。","just in case"];
EXAMPLES[1937]=["I spread the big map on the table.","私は机の上に大きな地図を広げた。","spread"];
EXAMPLES[1938]=["Seaside resorts, such as Newport, are very crowded in summer.","海岸の避暑地は、例えばニューボートがそうだが、夏には非常に混雑する。","such as"];
EXAMPLES[1939]=["The day before yesterday was a tough day.","一昨日は大変な1日だった。","tough"];
EXAMPLES[1940]=["I have a cold sore on my lip.","唇にヘルペスができています。","lip"];
EXAMPLES[1941]=["She held her hands tightly over her ears.","彼女はしっかり耳をおさえていた。","tightly"];
EXAMPLES[1942]=["Was the president in favor of the plan?","大統領はその計画に賛成したのですか。","president"];
EXAMPLES[1943]=["This hotel is relatively expensive for this town.","このホテルはこの町にしては比較的高い。","relatively"];
EXAMPLES[1944]=["The rich are not always happy.","金持ちが必ずしも幸福とは限らない。","not always"];
EXAMPLES[1945]=["They drove the car one after the other.","彼らは交互に車を運転した。","drove"];
EXAMPLES[1946]=["Jane will be excited to see the flowers.","ジェーンはその花を見て興奮するだろう。","be excited"];
EXAMPLES[1947]=["Will you take this document to the branch?","この書類を支社に届けてくれませんか。","branch"];
EXAMPLES[1948]=["Do you believe in God?","神の実在を信じますか。","believe in"];
EXAMPLES[1949]=["I have a lot in common with him.","私と彼は共通することが多い。","common"];
EXAMPLES[1950]=["The price of this tie is too high.","このネクタイの値段は高すぎる。","tie"];
EXAMPLES[1951]=["Will the strike affect the price of coal?","ストライキは石炭の価格に影響を与えますか。","coal"];
EXAMPLES[1952]=["Do you care for sweets?","甘い物好きですか。","care for"];
EXAMPLES[1953]=["I cannot agree to your proposal.","私は貴方の提案には同意できません。","agree to"];
EXAMPLES[1954]=["If something happens, feel free to call me.","何かあったらすぐに連絡してください。","feel free to"];
EXAMPLES[1955]=["Don't look to me for any help except in case of emergency.","緊急の場合以外は私の援助をあてにしてはいけません。","in case of"];
EXAMPLES[1957]=["We are working in the interest of peace.","我々は平和のために働いている。","peace"];
EXAMPLES[1958]=["I think he is something of a poet.","彼はちょっとした詩人だと思う。","poet"];
EXAMPLES[1960]=["We thought we would write out the directions, in case you got lost.","君が迷子になるといけないので、地図を書こうと思った。","in case"];
EXAMPLES[1961]=["He is definitely not a bad person.","彼はきっと悪い人ではない。","definitely"];
EXAMPLES[1962]=["The boy gave a rose to the girl.","少年は一輪のバラを少女に贈った。","rose"];
EXAMPLES[1963]=["The small statue is said to be made of fine gold.","その小さな像は純金でできていると言われている。","be made of"];
EXAMPLES[1964]=["She is said to be a domestic woman.","彼女は家庭的な女性だそうです。","domestic"];
EXAMPLES[1965]=["You'd better stay at home rather than go out on such a day.","君はこんな日には出かけるよりも家にいたほうがいいよ。","rather than"];
EXAMPLES[1966]=["Try to make the most of your time.","時間を最大限に活用するようにしなさい。","most"];
EXAMPLES[1967]=["Sometimes I run out of money.","ときどきお金が足りなくなります。","run out of"];
EXAMPLES[1969]=["Both of my parents are strict with me.","俺の親二人とも俺に厳しいんだ。","strict"];
EXAMPLES[1970]=["He was raised in an artistic family.","彼は芸術的な家庭に育った。","artistic"];
EXAMPLES[1972]=["He is involved in the case a little.","彼はその事件とまったく無縁ではない。","little"];
EXAMPLES[1973]=["I wonder, did you think of that yourself?","自分で考えたのかな？","wonder"];
EXAMPLES[1974]=["People are crying out against the new tax.","人々は新しい税金に対して反対を叫んでいる。","tax"];
EXAMPLES[1975]=["I just don't know what to say.","何と言ったらいいか・・・。","what to"];
EXAMPLES[1976]=["The coastal ecosystem of British Columbia is rapidly declining.","ブリティッシュコロンビアの沿岸生態系の劣化が急速に進行している。","ecosystem"];
EXAMPLES[1977]=["There are still people who are illiterate.","読めない人がまだいます。","illiterate"];
EXAMPLES[1978]=["I'll be in trouble if the story gets out.","その話が漏れると私は困ったことになる。","be in trouble"];
EXAMPLES[1979]=["You are to start as early as possible.","できるだけ早くに出発すべきだ。","possible"];
EXAMPLES[1980]=["You make mistakes if you do things in a hurry.","物事をあわててすると、間違いをします。","in a hurry"];
EXAMPLES[1981]=["The press ban on the case was removed yesterday.","その記事は昨日記事解禁となった。","ban"];
EXAMPLES[1982]=["The place was alive with creative young people.","その場所は創造力豊かな若い人であふれていた。","creative"];
EXAMPLES[1983]=["My parents are travelling overseas for a week.","両親は一週間、海外旅行に行っています。","overseas"];
EXAMPLES[1984]=["I want to discuss the price with you.","価格に関して話し合いたいのですが。","discuss"];
EXAMPLES[1985]=["It was believed that the earth was flat.","地球は平らだと信じられていた。","flat"];
EXAMPLES[1986]=["I keep a daily record of the temperature.","私は温度を毎日記録している。","daily"];
EXAMPLES[1988]=["This book tells that life is hopeful.","この本を読めば、人生は希望に満ちていることが分かる。","hopeful"];
EXAMPLES[1989]=["School has started and I like it so far.","学校が始まりましたが、今のところいやなことはありません。","so far"];
EXAMPLES[1990]=["The movie was so dull that the audience left one by one.","映画がつまらないので観客は一人また一人と出ていった。","one by one"];
EXAMPLES[1991]=["A strong wind blew all day long.","強い風が１日中吹いた。","all day long"];
EXAMPLES[1992]=["This is an animal found in that desert.","これはその砂漠で見つけられた動物だ。","desert"];
EXAMPLES[1993]=["You should be ready for the worst.","君は最悪の事態を覚悟しなくてはならない。","be ready for"];
EXAMPLES[1994]=["He was a former university professor and researcher.","彼はかつて大学教授であり、研究者でもあった。","researcher"];
EXAMPLES[1995]=["You belong in a better place than this.","君はもっとましな地位にあるべき人だ。","belong"];
EXAMPLES[1996]=["This kitchen is very functional.","この台所、すごく機能的ね。","functional"];
EXAMPLES[1997]=["The electricity has been off since this morning.","今朝から停電している。","electricity"];
EXAMPLES[1998]=["The money was enough to establish him in business.","資金は彼が商売で身を立てるのに十分だった。","establish"];
EXAMPLES[1999]=["I was amazed to learn I had won.","自分が勝ったと知って驚いた。","amazed"];
EXAMPLES[2000]=["The heavy rain brought floods in the valley.","激しい雨がその流域に洪水をもたらした。","valley"];
EXAMPLES[2001]=["Nothing but a full apology would satisfy him.","彼を納得させるには十分に謝るしかなかった。","satisfy"];
EXAMPLES[2002]=["In Finland public transport is always on time.","フィンランドの公共交通機関は時間を正確に守る。","transport"];
EXAMPLES[2003]=["I want you to live more like a human being.","あなたには、もっと人間らしく生きてほしいの。","human being"];
EXAMPLES[2004]=["Her death was a great blow to him.","彼女の死は彼には大打撃だった。","blow"];
EXAMPLES[2005]=["It makes no difference to me whether you believe it or not.","君がそれを信じようと信じまいと僕にはどうでも良い。","believe it or not"];
EXAMPLES[2006]=["He has a monthly income of 2,000 dollars.","彼は月収２０００ドルの金が入る。","monthly"];
EXAMPLES[2007]=["I ordered you to get out.","君に出て行けと命じたのだ。","get out"];
EXAMPLES[2008]=["Although the sun was out, it was cold.","陽は出ていたけれど、寒かった。","Although"];
EXAMPLES[2009]=["That dress is made out of silk.","そのドレスは絹製です。","silk"];
EXAMPLES[2010]=["The free market system is endangered.","自由市場システムが危機にひんしている。","endangered"];
EXAMPLES[2011]=["When would be a convenient time for you?","いつがご都合よろしいでしょうか？","convenient"];
EXAMPLES[2012]=["There are a lot of students in the gym.","体育館にたくさんの生徒がいます。","gym"];
EXAMPLES[2013]=["Go ahead and talk.","遠慮無く話せよ。","Go ahead"];
EXAMPLES[2014]=["Some animals will not breed when kept in cages.","檻の中で飼われると子どもを産まない動物もいる。","breed"];
EXAMPLES[2015]=["You don't have to wrap it up.","包む必要はありません。","wrap"];
EXAMPLES[2016]=["The number of cars is on the increase.","車の数がますます増えている。","increase"];
EXAMPLES[2017]=["How can I get to the railway station?","駅へはどのように行けばよいですか。","railway"];
EXAMPLES[2018]=["On one hand he is kind, but on the other hand he is lazy.","一方では彼は親切だが、他方では怠け者だ。","on the other hand"];
EXAMPLES[2019]=["Can you supply me with all I need?","あなたは私が必要としているものすべてを私に供給できますか。","supply"];
EXAMPLES[2020]=["You'll be paid according to the amount of work you do.","君の賃金は仕事量に応じて支払われる。","according to"];
EXAMPLES[2021]=["This road will lead you to the park.","この道を行けば、公園に出られます。","lead"];
EXAMPLES[2023]=["There are too many items in the survey.","アンケートの項目が多すぎる。","survey"];
EXAMPLES[2024]=["Let me help you to do the work.","あなたの仕事の手助けをさせて下さい。","Let"];
EXAMPLES[2025]=["You should study hard so that you can pass the examination.","君は試験に受かるように一生懸命勉強すべきだ。","so that"];
EXAMPLES[2026]=["I don't care for that sort of thing.","そのようなことは好きではありません。","sort"];
EXAMPLES[2027]=["Some of the students went by bus, and others on foot.","学生たちはバスで行く者もいれば、歩いて行く者もいた。","on foot"];
EXAMPLES[2028]=["I sold the best jewel that I had.","私は持っているうちで一番良い宝石を売った。","jewel"];
EXAMPLES[2029]=["Did you fall in love with her at first sight?","君は彼女にひとめぼれしたのかい。","fall in love with"];
EXAMPLES[2030]=["The beautiful bird is said to be in danger of dying out.","その美しい鳥は絶滅の恐れがあると言われています。","be in danger of"];
EXAMPLES[2031]=["We have to do something for the dead.","私たちは死んだ人々のために何かしなければならない。","dead"];
EXAMPLES[2032]=["A friend in need is a friend indeed.","まさかの時の友は真の友。","indeed"];
EXAMPLES[2033]=["The government of that country is now stable.","その国の政府は今安定している。","government"];
EXAMPLES[2034]=["During the war, they lived in the countryside.","彼らは戦争中田舎に住んでいた。","countryside"];
EXAMPLES[2035]=["Will this amount of money meet your need?","このお金であなたの要求に見合いますか。","amount"];
EXAMPLES[2036]=["Our knowledge on the problem is rather limited.","この問題についての知識はかなり限られている。","limited"];
EXAMPLES[2037]=["The climate here is like that of France.","当地の気候はフランスのそれと似ている。","climate"];
EXAMPLES[2038]=["You have put everything out of order.","君は何もかもめちゃくちゃにしてしまった。","out of order"];
EXAMPLES[2039]=["The assembly consisted of people concerned about human rights.","その集会は人権に関心を持つ人々の集まりだった。","human rights"];
EXAMPLES[2040]=["The children were sitting so as to surround the fire.","子どもたちは火を囲むように座っていました。","surround"];
EXAMPLES[2041]=["She always carries the Holy Bible about.","彼女はいつも聖書を持ち歩いている。","Holy"];
EXAMPLES[2042]=["Thank you for your instruction. It really helped.","ご教示ありがとうございます。助かりました。","instruction"];
EXAMPLES[2043]=["He has the strength to survive the illness.","彼にはその病気を乗り切るだけの力がある。","survive"];
EXAMPLES[2044]=["Tom bought a weekly magazine at the station.","トムは駅で週刊誌を買った。","weekly"];
EXAMPLES[2046]=["This is the only one in the store.","店にあるのはこれだけです。","store"];
EXAMPLES[2047]=["I have a high opinion of this book.","私はこの本を高く評価している。","opinion"];
EXAMPLES[2048]=["Ken goes swimming day after day.","ケンは毎日水泳に行く。","day after day"];
EXAMPLES[2049]=["His son is lazy and good for nothing.","彼の息子は怠け者で役に立たない。","lazy"];
EXAMPLES[2050]=["That week had nothing to do with discrimination.","その週間は差別とは関係がなかった。","discrimination"];
EXAMPLES[2051]=["The root cause of any divorce is marriage.","あらゆる離婚の主たる原因は結婚である。","root"];
EXAMPLES[2052]=["Fold A-7 in half and stick it together.","Ａ—７を二つ折りにして貼り合わせる。","Fold"];
EXAMPLES[2053]=["I think you should do a bit more.","もう少しやった方がいいと思うわ。","bit"];
EXAMPLES[2054]=["What happened? There's water all over the apartment.","何が起こったの？アパート全体水浸しだよ。","all over"];
EXAMPLES[2055]=["He contributed to the development to the city.","彼はその町の発展に貢献した。","development"];
EXAMPLES[2056]=["The steam ship has gone out of sight.","汽船は見えなくなった。","steam"];
EXAMPLES[2057]=["Are you still in a lot of pain?","まだ痛みがひどいですか？","pain"];
EXAMPLES[2058]=["I'd like two one-way tickets from A to B.","Ａ市からＢ市までのチケット、片道２まいください。","from A to B"];
EXAMPLES[2059]=["The treaty bans the use of chemical weapons.","条約は化学兵器の使用を禁止している。","chemical"];
EXAMPLES[2060]=["What time did she check out of the hotel?","何時に彼女はホテルを出ましたか。","check out"];
EXAMPLES[2061]=["In the end, capture the stomach to win.","結局、胃袋を掴んだもの勝ちだよね。","capture"];
EXAMPLES[2062]=["Will you make me a paper crane?","私に鶴を折ってもらえますか。","paper crane"];
EXAMPLES[2063]=["The statesman seems to be concerned with the affair.","その政治家は事件と関係があるようだ。","be concerned with"];
EXAMPLES[2065]=["We have just a tiny bit of garden.","うちの庭は猫の額ほどの狭さなんですよ。","tiny"];
EXAMPLES[2066]=["He tried his best not to get wet.","彼は出来るだけ濡れないようにした。","wet"];
EXAMPLES[2067]=["I can't get over how different the weather is here.","気候があまりに違うんで、びっくりしています。","get over"];
EXAMPLES[2068]=["Are the police going to arrest me?","警察が私を逮捕しに来るの？","arrest"];
EXAMPLES[2069]=["There is a curious story about an Englishman.","あるイギリス人についてのおもしろい話があります。","curious"];
EXAMPLES[2071]=["She will have it that the conditions are unfair.","彼女は条件が不公平だと言い張る。","unfair"];
EXAMPLES[2072]=["The situation is too terrible to look at.","目も当てられない状況だ。","terrible"];
EXAMPLES[2073]=["I hope to see you soon.","近々お会いできるのを楽しみにしています。","hope to"];
EXAMPLES[2074]=["I accept that he was telling the truth.","彼が真実を告げていたものと私は認めます。","accept"];
EXAMPLES[2075]=["I'd like to see the Statue of Liberty.","私は自由の女神像を見たいです。","Statue"];
EXAMPLES[2076]=["Is there anything else I need to do?","私がやらなきゃいけないことって、他に何かある？","else"];
EXAMPLES[2077]=["This is the site of a castle.","ここは城の跡です。","site"];
EXAMPLES[2078]=["Some hospitals hand out free samples of baby milk.","一部の病院は幼児用ミルクの無料見本を配布する。","hand out"];
EXAMPLES[2079]=["It's up to you to make the decision.","結論を下すのは君の義務です。","decision"];
EXAMPLES[2081]=["The radio broadcast the news in detail.","ラジオがこのニュースを詳しく放送した。","in detail"];
EXAMPLES[2082]=["The boy observed the growth of the plant.","その少年は植物の成長を観察した。","growth"];
EXAMPLES[2083]=["He bought some stationery at the school store.","彼は学校の売店で文房具を買った。","stationery"];
EXAMPLES[2084]=["Above all, I want to see him again.","何よりも、彼にもう一度会いたい。","Above"];
EXAMPLES[2085]=["Don't forget to include me in the count.","忘れずに俺も頭数に入れてくれよ。","include"];
EXAMPLES[2086]=["Trees give off oxygen and absorb carbon dioxide.","樹木は酸素を排出し、二酸化炭素を吸収する。","carbon dioxide"];
EXAMPLES[2087]=["I hope it won't be long before I hear from her.","近いうちに彼女から便りがあることを願っている。","hear from"];
EXAMPLES[2088]=["The law does not apply to this case.","その法則はこの場合当てはまらない。","apply"];
EXAMPLES[2089]=["You are not old enough to go swimming by yourself.","君は独りで泳ぎに行ける歳ではない。","enough to"];
EXAMPLES[2090]=["You can depend on his help.","君は彼の援助を当てにすることができる。","depend on"];
EXAMPLES[2091]=["The enemy dropped many bombs on the factory.","敵は工場に多くの爆弾を落とした。","bombs"];
EXAMPLES[2092]=["The residents were curious about other people's business.","そこの住民達は他人の事にやたらと興味を持つ人たちだった。","residents"];
EXAMPLES[2093]=["There was a large audience in the room.","部屋の中に多くの聴衆がいた。","audience"];
EXAMPLES[2094]=["I know him to be a brave man.","彼は勇気のある人です。","brave"];
EXAMPLES[2096]=["You must strike while the iron is hot.","鉄は熱いうちに打たねばならぬ。","iron"];
EXAMPLES[2098]=["Japan has a lot of trade with Canada.","日本はカナダと大量の貿易をしている。","trade"];
EXAMPLES[2100]=["Sports keep us in good shape.","スポーツはからだの調子をよくする。","in good shape"];
EXAMPLES[2101]=["I'll find someone to fill in for you.","君の代行者を見つけよう。","fill in"];
EXAMPLES[2102]=["I was just in time for the flight.","その飛行機にちょうどまにあった。","flight"];
EXAMPLES[2103]=["Have fun, but don't get lost.","楽しく遊んできなさい。でも道に迷わないように。","get lost"];
EXAMPLES[2104]=["We must develop the renewable energy sources.","私たちは再生できるエネルギー源を開発しなければならない。","renewable"];
EXAMPLES[2105]=["You are watching TV all the time.","君はいつもテレビばかり見ているね。","all the time"];
EXAMPLES[2107]=["Is this your first time to donate blood?","献血は今回が初めて？","donate"];
EXAMPLES[2108]=["He came to be known as a great novelist.","彼は偉大な小説家として知られるようになった。","be known as"];
EXAMPLES[2109]=["We specialize in the import of machinery parts.","弊社は機械パーツの輸入を行っています。","import"];
EXAMPLES[2110]=["This is a secret. Keep it to yourself.","これは秘密です。他人に明かさないでください。","secret"];
EXAMPLES[2111]=["The book was given to him by me.","本は私から彼に与えられました。","given"];
EXAMPLES[2112]=["If you keep trying, you will make progress.","あきらめずに歩き続ければ、進歩するでしょう。","progress"];
EXAMPLES[2113]=["We have two unused rooms in our house.","私たちの家には、使われていない部屋が二つあります。","unused"];
EXAMPLES[2114]=["I have neither time nor money for that.","私にはそんなことをする暇も金もない。","neither"];
EXAMPLES[2115]=["Your essay has some mistakes, but as a whole it is very good.","君の作文にはいくつか間違いがあるが、全体としてみると、非常によくできているよ。","as a whole"];
EXAMPLES[2116]=["The yen is still low against the dollar.","円安が進んでいるね。","yen"];
EXAMPLES[2117]=["I used to debate the problem with her.","私はよく彼女とその問題を議論したものだ。","debate"];
EXAMPLES[2118]=["Ann sang a lullaby for her little sister.","アンは妹のために子守唄を歌ってあげた。","lullaby"];
EXAMPLES[2119]=["Birds of a feather will gather together.","類は友を呼ぶ。","feather"];
EXAMPLES[2120]=["You must go through with your plan.","君は計画を遣り通さなければならない。","go through"];
EXAMPLES[2121]=["I made a note of the telephone number.","私はその電話番号を書き留めた。","note"];
EXAMPLES[2122]=["Take care not to awake the sleeping baby.","眠っている赤ん坊を起こさないように注意しなさい。","awake"];
EXAMPLES[2123]=["He must be crazy to talk like that.","そんな話し方をするとは、彼は狂っていたに違いない。","crazy"];
EXAMPLES[2124]=["Japan is full of beautiful cities. Kyoto and Nara, for instance.","日本には美しい都市が多い。例えば京都、奈良だ。","for instance"];
EXAMPLES[2125]=["Could I have a plastic bag for those?","ビニール袋に入れてください。","plastic bag"];
EXAMPLES[2126]=["There was a brief break in the discussion.","話し合いはちょっと中断した。","discussion"];
EXAMPLES[2127]=["I'm just going to drop by the post office.","ちょっと郵便局へいってくる。","drop by"];
EXAMPLES[2128]=["Is this made out of wood or metal?","これは木製ですか、鉄製ですか？","metal"];
EXAMPLES[2129]=["In relation to this, I am to blame.","これに関しては私にも責任がある。","relation"];
EXAMPLES[2130]=["At one time Nigeria was a British colony.","ナイジェリアはかつてイギリスの植民地であった。","colony"];
EXAMPLES[2131]=["You can always count on Tom.","君はトムをいつもあてに出来る。","count on"];
EXAMPLES[2132]=["He has no children to succeed to him.","彼には自分を継承してくれる子供が一人もいない。","succeed"];
EXAMPLES[2133]=["Is it certain that he will help us?","彼が我々を助けてくれるというのは確かですか。","certain"];
EXAMPLES[2135]=["The furniture in this office is really modern.","この事務所の家具はなかなか近代的だ。","modern"];
EXAMPLES[2136]=["You must get rid of that bad habit.","君はその悪い癖をなくさなければならない。","get rid of"];
EXAMPLES[2137]=["The alcohol is beginning to affect his speech.","アルコールが彼の話し方に影響しはじめている。","affect"];
EXAMPLES[2138]=["He is no match for me in tennis.","テニスでは、彼は私にかなわない。","match"];
EXAMPLES[2139]=["The beautiful of that country is beyond description.","その国の美しさは言葉に表現できないくらいだ。","beyond"];
EXAMPLES[2140]=["And yet, the contrary is always true as well.","しかし、逆もまた真である。","as well"];
EXAMPLES[2141]=["No matter which you make, you will be satisfied with it.","どちらをとっても、あなたは満足するでしょう。","be satisfied with"];
EXAMPLES[2142]=["She sat next to him and listened quietly.","彼女は彼の隣に座り、静かに聴いた。","quietly"];
EXAMPLES[2143]=["The blood on the road must be mine.","路上の血痕は俺のものに違いない。","blood"];
EXAMPLES[2144]=["I was so excited that I could not fall asleep.","興奮していたので、私は寝付かれなかった。","fall asleep"];
EXAMPLES[2145]=["They were watching for the signal to start.","彼らは出発の合図を待っていた。","signal"];
EXAMPLES[2146]=["The citizens demonstrated to protest against the new project.","市民は新しい計画に抗議してデモをした。","protest"];
EXAMPLES[2147]=["This bird is now in danger of extinction.","この鳥は今、絶滅の危機に瀕しています。","extinction"];
EXAMPLES[2148]=["In terms of salary, that job is fantastic.","給料の点からはその仕事は魅力的だ。","fantastic"];
EXAMPLES[2149]=["Do you belong to any clubs?","君は何かクラブに入っていますか。","belong to"];
EXAMPLES[2150]=["The king was pleased with him at first.","はじめのうちは王様は彼に満足した。","pleased"];
EXAMPLES[2151]=["The school should do away with the uniform.","その学校は、制服を廃止すべきだ。","uniform"];
EXAMPLES[2152]=["A stranger spoke to me on the bus.","バスの中で、見知らぬ人が私に話しかけてきた。","stranger"];
EXAMPLES[2153]=["I had an interesting conversation with my neighbor.","私は近所の人と楽しい会話をしました。","neighbor"];
EXAMPLES[2154]=["What you need the most now is courage.","君が今一番必要なものは勇気です。","courage"];
EXAMPLES[2155]=["It's a quarter after nine in the morning.","今は朝の９時１５分だよ。","quarter"];
EXAMPLES[2156]=["By the time you get out of jail, she'll probably have gotten married.","君が刑務所から出てくる頃は、彼女も結婚しているだろう。","get out of"];
EXAMPLES[2157]=["You might have to eat those words a few years from now.","何年かしたら、その考えが間違っていたって思うかもよ。","from now"];
EXAMPLES[2158]=["He was in the army for thirty years.","彼は３０年間陸軍にいた。","army"];
EXAMPLES[2159]=["I wonder if we're alone in the universe.","宇宙には僕らしかいないんだろうか？","universe"];
EXAMPLES[2160]=["You are working too hard. Take it easy for a while.","君は働きすぎだよ。しばらくのんびりしたら。","for a while"];
EXAMPLES[2161]=["I will show you how to solve it.","解き方を教えてあげるよ。","solve"];
EXAMPLES[2162]=["As of midnight tonight the contract becomes effective.","今夜の１２時からその契約は効力を発する。","effective"];
EXAMPLES[2163]=["I plan to pursue a career in international finance.","国際金融で仕事を続けるつもりです。","pursue"];
EXAMPLES[2164]=["The first step is the most important step.","最初の一歩が肝心なのよ。","step"];
EXAMPLES[2166]=["It is difficult to relate to someone who has different values from you.","価値観の違う人とうまくやっていくのは難しい。","relate to"];
EXAMPLES[2168]=["The house is not in very good condition.","その家はあまりいい状態ではない。","condition"];
EXAMPLES[2169]=["He was not a financial burden on her.","彼は家計の上で彼女の負担にはなっていなかった。","burden"];
EXAMPLES[2170]=["They sat in the shade of a tree.","彼らは木蔭に座った。","shade"];
EXAMPLES[2171]=["As a result, he became a great merchant.","その結果として、彼は偉大な商人になった。","merchant"];
EXAMPLES[2172]=["My son is going to be a teacher.","私の息子は先生になるつもりなの。","son"];
EXAMPLES[2173]=["You will have heard the news, I think?","ニュースをお聞きになったでしょう。","heard"];
EXAMPLES[2174]=["Leaves collect on the sidewalk in the fall.","秋には木の葉が歩道に集まる。","sidewalk"];
EXAMPLES[2175]=["There's around 6 billion people in the world.","世界には約６０億の人々が暮らしている。","billion"];
EXAMPLES[2176]=["What do you plan to do after graduation?","卒業したらどうするつもりですか。","graduation"];
EXAMPLES[2177]=["It's hard to tell Englishmen from Americans just by the way they look.","顔だけでイギリス人とアメリカ人を区別することは難しい。","by the way"];
EXAMPLES[2178]=["There is every promise of the boy's release.","少年の釈放の見込みが大いにある。","release"];
EXAMPLES[2179]=["I could not sleep because of the heat.","暑くて眠れなかったんだ。","heat"];
EXAMPLES[2180]=["Perhaps Tom can help you find a job.","多分、トムが仕事を探すの手伝ってくれるよ。","Perhaps"];
EXAMPLES[2181]=["Besides being a businessman, he is a musician.","彼は実業家であるばかりでなく、音楽家でもある。","Besides"];
EXAMPLES[2182]=["It was a successful presentation of a play.","成功を収めた劇の上映。","successful"];
EXAMPLES[2183]=["These are the weapons used by the ancients.","これらは古代人によって使われた武器である。","weapons"];
EXAMPLES[2184]=["You'd better go home as soon as possible.","君はできる限り早く家に帰った方がいい。","as soon as possible"];
EXAMPLES[2185]=["It is necessary for you to go there.","あなたはそこへ行く必要があります。","necessary"];
EXAMPLES[2186]=["Can I extend my stay for another day?","もう一日延泊できますか。","extend"];
EXAMPLES[2187]=["The party came to an end at midnight.","そのパーティーは真夜中に終わった。","midnight"];
EXAMPLES[2188]=["Try to be a more rational consumer.","もっと合理的な消費者になるように努めなさい。","consumer"];
EXAMPLES[2189]=["You may depend on him to help you.","あなたは彼の助けを当てにしてもよい。","depend"];
EXAMPLES[2190]=["Turn your face this way.","顔をこちらへ向けなさい。","this way"];
EXAMPLES[2191]=["If I were you, I would trust her.","もし私があなたの立場なら、彼女を信用する。","trust"];
EXAMPLES[2192]=["The film was not a success in Japan.","その映画は日本では評判がよくありませんでした。","film"];
EXAMPLES[2193]=["I was at a loss what to do.","私は何をしたらよいか途方にくれた。","loss"];
EXAMPLES[2194]=["In effect, flowers are the creators of honey.","要するに、花がはちみつを作るのだ。","honey"];
EXAMPLES[2195]=["Mary and John quarreled, but made up after a while.","メアリーとジョンは口論したが、しばらくして仲直りした。","after a while"];
EXAMPLES[2196]=["The man suddenly struck me on the head.","男は突然私の頭を殴った。","suddenly"];
EXAMPLES[2197]=["They were calm in the face of disaster.","彼らは災難に遭っても冷静であった。","disaster"];
EXAMPLES[2198]=["I will play Sudoku then instead of continuing to bother you.","君を邪魔するくらいなら私は数独をやってるよ。","instead of"];
EXAMPLES[2200]=["We should check the spread of the disease.","我々は病気の伝染をくいとめなければならない。","disease"];
EXAMPLES[2201]=["Let's pass by the church.","教会のそばを通ろう。","pass by"];
EXAMPLES[2202]=["The birthrate is rapidly declining in this country.","この国では出生率が急速に低下している。","rapidly"];
EXAMPLES[2203]=["Can I speak to the person in charge?","責任者を出して下さい。","charge"];
EXAMPLES[2204]=["That is not what I meant to say.","それは私が言おうとしたことではない。","meant"];
EXAMPLES[2205]=["His behavior, as I remember, was very bad.","私の記憶している限りでは、彼の態度はとても悪かった。","behavior"];
EXAMPLES[2206]=["I feel uncomfortable in this kind of situation.","こういう時って気まずいよな。","uncomfortable"];
EXAMPLES[2207]=["I don't remember the title of that movie.","その映画のタイトルは覚えてないんだ。","title"];
EXAMPLES[2208]=["He had no other resource but to run away.","彼は逃げる以外手だてがなかった。","resource"];
EXAMPLES[2209]=["The police officer on duty sensed an elderly man coming up behind him.","勤務中の警官は、一人のお年寄りが自分の背後に近づいてくるのを感じた。","police officer"];
EXAMPLES[2210]=["It's not something anyone would be ashamed of.","誰も恥を感じるものはいない。","ashamed"];
EXAMPLES[2211]=["He is the very image of his father.","彼は父親に生き写しだ。","image"];
EXAMPLES[2212]=["It was natural for him to be familiar with jazz.","彼がジャズに詳しいのは当然だった。","be familiar with"];
EXAMPLES[2213]=["We'll finish the work even if it takes us all day.","我々は、一日中かかってもその仕事を仕上げてしまうつもりだ。","even if"];
EXAMPLES[2215]=["Fortunately they had no storms on the way.","幸運な事に、彼らは途中で嵐に遭わなかった。","Fortunately"];
EXAMPLES[2216]=["We will make an exception of your case.","君の場合は例外としよう。","exception"];
EXAMPLES[2217]=["Oh yes! I will certainly come with you!","うん！必ず一緒に行くよ！","certainly"];
EXAMPLES[2218]=["He will surely succeed in his new job.","彼は新しい仕事できっと成功するだろう。","surely"];
EXAMPLES[2219]=["The device is attached fast to the ceiling.","その装置は天井にしっかりと固定されている。","device"];
EXAMPLES[2220]=["You should be responsible for your actions.","君は自分の行為に責任を持つべきだ。","be responsible for"];
EXAMPLES[2221]=["This ball is the treasure of that boy.","このボールはあの男の子の宝物です。","treasure"];
EXAMPLES[2222]=["It is up to you to decide whether we will go there or not.","私たちがそこへ行くかどうかを決めるのは君の責任だ。","up to"];
EXAMPLES[2223]=["You should have locked, or at least closed, all the doors.","君は全部のドアを施錠するか、せめて閉じるべきだった。","at least"];
EXAMPLES[2224]=["This bad practice will gradually die out.","この悪習は次第になくなるだろう。","die out"];
EXAMPLES[2225]=["It's hard to get this camera to focus.","このカメラ、ピントが合わせにくいんだ。","focus"];
EXAMPLES[2227]=["With respect to that, I agree with you.","それに関して、私は君に賛成だ。","respect"];
EXAMPLES[2228]=["I must have it done somehow by six.","６時までには何とかそれをやってしまわなければならない。","somehow"];
EXAMPLES[2229]=["I have a good idea in my mind.","私は心によい考えを持っている。","mind"];
EXAMPLES[2230]=["Get it and put it on the fire.","それを取ってきてそして火に入れて下さい。","fire"];
EXAMPLES[2231]=["I will become God of the new world.","僕は新世界の神となる。","God"];
EXAMPLES[2232]=["The old man is blind in one eye.","その老人は片目が見えない。","blind"];
EXAMPLES[2233]=["Drivers should be aware of the traffic rules.","ドライバーは交通規則を知っているべきだ。","be aware of"];
EXAMPLES[2234]=["I saw my sister tear up the letter.","私は姉がその手紙をひきさくのを見た。","tear"];
EXAMPLES[2235]=["She's not a regular employee of this company.","彼女はこの会社の正社員ではありません。","employee"];
EXAMPLES[2236]=["To my surprise, they ate the meat raw.","驚いたことに肉を生で食べた。","raw"];
EXAMPLES[2237]=["Peace is important for the survival of mankind.","平和は人類にとって大事な生存条件です。","survival"];
EXAMPLES[2238]=["Nuclear power plants are dangerous, not to mention nuclear weapons.","核兵器は言うまでもなく、原子力発電所も危険である。","Nuclear power"];
EXAMPLES[2239]=["We came to a turn in the road.","私達は道が曲がったところに来た。","road"];
EXAMPLES[2240]=["I'd never before seen this species of fish.","この手の魚は見たことがなかった。","species"];
EXAMPLES[2241]=["He let on that he was a lawyer.","彼は弁護士のふりをした。","lawyer"];
EXAMPLES[2242]=["There is a large parking lot in front of the station.","駅前に大きな駐車場がある。","parking lot"];
EXAMPLES[2243]=["That is a pretty good thing to say.","なかなかいいこと言うじゃない。","pretty"];
EXAMPLES[2244]=["I wrote the composition in haste, so it must be full of mistakes.","その作文は急いで書いたのできっと間違いだらけでしょう。","be full of"];
EXAMPLES[2245]=["All he can do is to support himself.","彼は自活するだけでせいいっぱいだ。","himself"];
EXAMPLES[2246]=["As I was sleepy, I went to bed.","眠かったので床についた。","sleepy"];
EXAMPLES[2247]=["It is quite natural that he think so.","彼がそう思うのはまったく当然だ。","quite"];
EXAMPLES[2248]=["On the way back, I was very scared.","帰り道、めっちゃ怖かった。","scared"];
EXAMPLES[2249]=["Look at the sign just ahead of you.","あなたの前にある看板をご覧なさい。","ahead"];
EXAMPLES[2250]=["One of my wisdom teeth is coming in.","親知らずがはえてきました。","teeth"];
EXAMPLES[2251]=["The teacher began to shoot questions at me.","先生は私に質問を浴びせ始めた。","shoot"];
EXAMPLES[2252]=["I said hello to her and she smiled.","私が彼女に「ハロー」と挨拶すると彼女は微笑んだ。","hello"];
EXAMPLES[2253]=["A miss is as good as a mile.","一つ間違えば一里も狂う。","mile"];
EXAMPLES[2254]=["My father wants me to be an engineer.","父は私に技師になってほしいと思っている。","engineer"];
EXAMPLES[2255]=["Would you like to become a trusted user?","「信頼できるユーザー」になりたいですか？","user"];
EXAMPLES[2256]=["Could you give me change for a dollar?","１ドルをくずしてくれませんか。","dollar"];
EXAMPLES[2257]=["It turned out to be a lovely day.","良い天気になりました。","lovely"];
EXAMPLES[2258]=["I have to prepare to go to school.","学校に行く仕度しなくっちゃ。","prepare"];
EXAMPLES[2259]=["That company just put up a web page.","あの会社もついにホームページを立ち上げたらしい。","web"];
EXAMPLES[2260]=["I hope the wine is to your taste.","ワインがお気に召すといいのですが。","wine"];
EXAMPLES[2261]=["The bay is full of boats and people.","湾にはたくさんのボートと人がいる。","bay"];
EXAMPLES[2262]=["She understands the core of the problem well.","彼女はその問題の核心をよく理解している。","core"];
EXAMPLES[2263]=["Thank you very much for the excellent coffee.","おいしいコーヒー、どうもありがとう。","excellent"];
EXAMPLES[2264]=["He entered the bank disguised as a guard.","警備員に成りすまして彼は銀行に入った。","guard"];
EXAMPLES[2265]=["The stress began to tell on his heart.","ストレスが心臓に影響し始めた。","stress"];
EXAMPLES[2266]=["He won a narrow victory in the race.","彼はデッドヒートの末そのレースに勝った。","victory"];
EXAMPLES[2267]=["She works as an assistant to the manager.","彼女は支配人の助手として働いている。","assistant"];
EXAMPLES[2268]=["I will get that classic car at all costs.","どんなに高くてもあのクラシックカーを手に入れたい。","classic"];
EXAMPLES[2269]=["He stopped a moment to kick a rock.","彼はちょっと立ち止まって小石を蹴飛ばした。","kick"];
EXAMPLES[2270]=["I have to remember to mail the letter.","私は忘れずに手紙を投函しなければならない。","mail"];
EXAMPLES[2271]=["The man is wearing a pair of glasses.","男は眼鏡をかけている。","pair"];
EXAMPLES[2272]=["The fairy changed the prince into a cat.","妖精は王子を猫に変えた。","prince"];
EXAMPLES[2273]=["They held a special session on trade problems.","彼等は貿易問題について臨時の会合を開いた。","session"];
EXAMPLES[2274]=["How many stars are there in the sky?","空の星って、何個ぐらいあるんだろう？","sky"];
EXAMPLES[2275]=["The people living here belong to the upper class.","ここに住んでいる人達は上流階級に属する。","upper"];
EXAMPLES[2276]=["That is a danger zone; don't go there.","そこは危険地帯である。そこへは行ってはいけない。","zone"];
EXAMPLES[2277]=["Do you want me to pay in advance?","前払いしてほしいですか。","advance"];
EXAMPLES[2278]=["He got in the boat with the horse.","彼は馬とともにそのボートに乗った。","boat"];
EXAMPLES[2279]=["We mix with the good, not with the bad.","私たちはよい人とは一緒につきあうけれど、悪い人とはつき合わないわ。","mix"];
EXAMPLES[2280]=["My secretary has a good command of English.","私の秘書は英語を自由に使える。","command"];
EXAMPLES[2281]=["In the heart of the forest are bears.","森の奥には熊がいる。","forest"];
EXAMPLES[2282]=["There is no limit to the universe.","宇宙には限りはない。","limit"];
EXAMPLES[2283]=["Today is the night of the full moon.","今日は、十五夜です。","moon"];
EXAMPLES[2284]=["My grandfather was a soldier during the war.","私の祖父は戦争中兵士だった。","soldier"];
EXAMPLES[2285]=["Is it possible to forget your native language?","自分の母国語を忘れ去ることは可能なのでしょうか？","native"];
EXAMPLES[2286]=["I feel like it's gotten faster after the update.","バージョンアップして速くなった気がする。","update"];
EXAMPLES[2287]=["He is both a doctor and a writer.","彼は、医者でもあり作家でもあるのです。","writer"];
EXAMPLES[2288]=["What changes the world is communication, not information.","世界を変えるのは情報ではなくコミュニケーションだ。","communication"];
EXAMPLES[2289]=["When can I download the new data?","新しいデータをダウンロードできるのはいつですか？","download"];
EXAMPLES[2290]=["Did you receive the email I sent you?","私が送ったメール、届いた？","email"];
EXAMPLES[2291]=["It is good for you to take exercise.","運動すると身体にいいですよ。","exercise"];
EXAMPLES[2292]=["I don't like a novel without a hero.","私は英雄のいない小説は嫌いだ。","hero"];
EXAMPLES[2293]=["It is true, it is not a joke.","本当で、冗談なんかじゃないよ。","joke"];
EXAMPLES[2294]=["You can get a loan from a bank.","君は銀行から金が借りられるよ。","loan"];
EXAMPLES[2295]=["He had a good time in the restaurant.","彼はそのレストランで楽しい時を過ごした。","restaurant"];
EXAMPLES[2296]=["It says entry is prohibited from this point on.","こっからは立入禁止だって。","entry"];
EXAMPLES[2297]=["The Golden Gate Bridge is made of iron.","金門橋は鉄でできている。","Golden"];
EXAMPLES[2298]=["I do not want to make a mistake.","間違いはしたくない。","mistake"];
EXAMPLES[2299]=["Which is the platform for the London train?","ロンドン行きの列車のプラットホームはどちらですか。","platform"];
EXAMPLES[2300]=["I don't want to go to the pool.","プール行きたくない。","pool"];
EXAMPLES[2301]=["There was a crash on Route 66 today.","今日ルート６６で衝突事故があったんだ。","Route"];
EXAMPLES[2302]=["I made a few changes to the schedule.","スケジュールだけど、少し変えたよ。","schedule"];
EXAMPLES[2303]=["You are not supposed to smoke in here.","ここでは喫煙してはいけないことになっています。","smoke"];
EXAMPLES[2304]=["I think it's a fox, not a dog.","犬じゃなくて狐だと思うよ。","fox"];
EXAMPLES[2305]=["When are you going on holiday this year?","今年はいつ休暇を取りますか。","holiday"];
EXAMPLES[2306]=["There is a little milk in the glass.","コップにはミルクが少しある。","milk"];
EXAMPLES[2307]=["Pack your things and get out of here.","荷物をまとめてここから出て行け。","Pack"];
EXAMPLES[2308]=["We expect rapid growth of the utilities sector.","公益事業部門の急成長を見込んでいます。","sector"];
EXAMPLES[2309]=["This wind is a sign of a storm.","この風は嵐の前兆だ。","storm"];
EXAMPLES[2310]=["The singer was standing by in the studio.","その歌手は放送室でスタンバイしていた。","studio"];
EXAMPLES[2311]=["I gave him the key to the apartment.","アパートの鍵は、渡したよ。","apartment"];
EXAMPLES[2312]=["The dog should be on a chain.","その犬は鎖でつないでおくべきだ。","chain"];
EXAMPLES[2313]=["How hard is it to get a fake passport?","偽造パスポートを手に入れるのって、どれくらい難しいのかな？","fake"];
EXAMPLES[2314]=["You left the light on in the kitchen.","キッチンの電気つけっぱなしだよ。","kitchen"];
EXAMPLES[2315]=["What are you going to do, specifically?","具体的には何すんの。","specifically"];
EXAMPLES[2316]=["Corporate earnings in the first quarter improved sharply.","企業収益は第１四半期に大きく改善した。","Corporate"];
EXAMPLES[2317]=["He lay on his back on the bed.","彼はベッドにあおむけになった。","lay"];
EXAMPLES[2318]=["The air is very pure in the mountains.","山中では空気はとても清浄だ。","pure"];
EXAMPLES[2319]=["That child felt secure in his mother's arms.","その子供は母親の腕の中に抱かれて安心した。","secure"];
EXAMPLES[2320]=["The truck cut in front of my car.","トラックが私の前に割り込んだ。","truck"];
EXAMPLES[2321]=["He is basically a nice man.","彼は本来はいい男だ。","basically"];
EXAMPLES[2322]=["The soup in the bowl was very delicious.","そのお椀のスープはとてもおいしかった。","bowl"];
EXAMPLES[2323]=["There's no cellphone coverage in this area.","この地域は携帯電話の圏外だ。","coverage"];
EXAMPLES[2324]=["Did you set your phone to airplane mode?","携帯は、機内モードにした？","mode"];
EXAMPLES[2325]=["All in all, the novel was a success.","小説はまず成功だった。","novel"];
EXAMPLES[2326]=["Pick out the shirt that you like best.","あなたが一番好きなワイシャツを選んでください。","shirt"];
EXAMPLES[2327]=["There were lots of people in the stadium.","スタジアムには大勢の人がいた。","stadium"];
EXAMPLES[2328]=["We had to start our business from zero.","私たちは商売をゼロから始めなければならなかった。","zero"];
EXAMPLES[2329]=["The champion had the challengers at his mercy.","チャンピオンは挑戦者たちを思うままにあしらった。","champion"];
EXAMPLES[2330]=["Would you like some cream in your coffee?","コーヒーにクリームはいかがですか。","cream"];
EXAMPLES[2331]=["Nancy had never seen a giant panda before.","ナンシーはそれ以前にはパンダを見たことがなかった。","giant"];
EXAMPLES[2332]=["He played a minor part in the play.","彼はその劇でわき役を演じた。","minor"];
EXAMPLES[2333]=["Is it OK is I eat this orange?","このオレンジ食べてもいいですか。","orange"];
EXAMPLES[2334]=["The old selection process for judges was very unfair.","かつての鑑定人の選任は非常に不明朗でした。","selection"];
EXAMPLES[2335]=["What kind of theme are you interested in?","どのようなテーマにご関心がおありですか？","theme"];
EXAMPLES[2336]=["He was driving under the influence of alcohol.","彼は酒気を帯びて運転していた。","alcohol"];
EXAMPLES[2337]=["A combination of parties formed the new government.","党が連合して、新しい政府となった。","combination"];
EXAMPLES[2338]=["The Conservative Party won the election in 1992.","１９９２年の選挙では保守党が勝利を収めた。","Conservative"];
EXAMPLES[2339]=["Thank you for the draft of the Agreement.","契約書のドラフトをありがとうございました。","draft"];
EXAMPLES[2340]=["I am convinced that I understand you perfectly.","君のことは充分理解しているつもりだよ。","perfectly"];
EXAMPLES[2341]=["I plan to play a flute solo.","フルート独奏をやるつもりです。","solo"];
EXAMPLES[2342]=["May I have a look at your ticket?","切符を見せてくれませんか。","ticket"];
EXAMPLES[2343]=["The reason is they immediately wing it.","すぐ知ったかぶりをするんだから。","wing"];
EXAMPLES[2344]=["We're going to cycle to the lake tomorrow.","私たちはあす湖まで自転車で行きます。","cycle"];
EXAMPLES[2345]=["I felt for the switch in the dark.","僕は暗闇の中でスイッチを手探りでさがした。","switch"];
EXAMPLES[2346]=["They controlled a fifth part of the territory.","彼らは領土の５分の１を支配していた。","territory"];
EXAMPLES[2347]=["Aside from this, he was in good health.","このことを除けば、彼は健康であった。","Aside"];
EXAMPLES[2348]=["The question is: Who will bell the cat.","問題は誰が猫に鈴をつけるかだ。","bell"];
EXAMPLES[2349]=["This is why I don't have a boyfriend.","だから、彼氏がいないんです。","boyfriend"];
EXAMPLES[2350]=["That is how he got out of danger.","そのようにして彼は危険を脱したのです。","danger"];
EXAMPLES[2351]=["It was like watching a slow motion movie.","それはまるでスローモーション映画を見ているようだった。","motion"];
EXAMPLES[2352]=["The couple went to the register and paid.","二人はレジへ行き精算した。","register"];
EXAMPLES[2353]=["We need a tool to open it with.","それを開ける道具が必要です。","tool"];
EXAMPLES[2354]=["A flag is a symbol of the people.","旗は国民のシンボルです。","flag"];
EXAMPLES[2355]=["The frame of the building is now complete.","その建物の骨組みは今や完成している。","frame"];
EXAMPLES[2356]=["Is it OK if I bring a guest?","お客さん連れてきていい？","guest"];
EXAMPLES[2357]=["It was only a kiss on the cheek.","ほっぺにキスしただけだろ。","kiss"];
EXAMPLES[2358]=["You had better stop buying things at random.","手当たり次第に買物をするのはやめたほうがいいですよ。","random"];
EXAMPLES[2359]=["The senator remained neutral in the furious controversy.","その上院議員は激しい論争において中立の立場を守った。","senator"];
EXAMPLES[2360]=["His new movie earned him an Academy Award.","新作の映画で彼はアカデミー賞を得た。","Academy"];
EXAMPLES[2361]=["I assume that this idea will work well.","この考えはうまく行くだろう。","assume"];
EXAMPLES[2362]=["There is a little water in the bottle.","瓶の中には少し水がある。","bottle"];
EXAMPLES[2363]=["A bunch of people died in the explosion.","かなりの人が爆発で亡くなった。","bunch"];
EXAMPLES[2364]=["His latest work belongs to a different category.","彼の最新作は趣を異にする。","category"];
EXAMPLES[2365]=["Nancy is having a chat with her friends.","ナンシーは今、友人たちとおしゃべりしている。","chat"];
EXAMPLES[2366]=["Would you teach me how to make cheese?","チーズの製法を教えてください。","cheese"];
EXAMPLES[2367]=["A bulldozer was used to level the lane.","その土地をならすのにブルドーザーが使われた。","lane"];
EXAMPLES[2368]=["I am on shift from 9am till 5pm.","朝9時から夕方5時までのシフトです。","shift"];
EXAMPLES[2369]=["Early in the morning, the tank battle began.","朝早くに、戦車戦は始まった。","tank"];
EXAMPLES[2370]=["There is a yard between the two houses.","二つの家の間に庭がある。","yard"];
EXAMPLES[2371]=["I am a member of the basketball team.","ボクは、そのバスケットボールチームのメンバーだよ。","basketball"];
EXAMPLES[2372]=["Can you tell me which button to press?","どっちのボタンをおしたらいいか教えて下さい。","button"];
EXAMPLES[2373]=["Golf is the sport that I don't like.","ゴルフは僕の嫌いなスポーツです。","Golf"];
EXAMPLES[2374]=["Hopefully you can rest and relax on the flight home.","帰りの機内では、ゆっくりお休みになれるといいですね。","Hopefully"];
EXAMPLES[2375]=["The matter is of great importance to me.","その問題は私にはとても重要である。","importance"];
EXAMPLES[2376]=["The colors of the pattern are very ordinary.","その模様の色は実に平凡なものである。","pattern"];
EXAMPLES[2377]=["Who do you think will win the tournament?","誰がそのトーナメントで優勝するとおもいますか。","tournament"];
EXAMPLES[2378]=["The host cut the turkey for the guests.","主人はお客に七面鳥の肉を切り分けた。","turkey"];
EXAMPLES[2379]=["We sat around the fire in a circle.","私たちは火の周りに円を描いて座った。","circle"];
EXAMPLES[2380]=["Will we be in time for the concert?","コンサートに間に合うでしょうか。","concert"];
EXAMPLES[2381]=["We heard the tree fall with a crash.","木がすさまじい音を立てて倒れるのが聞こえた。","crash"];
EXAMPLES[2382]=["Many a man has made the same error.","多くの人が同じ過ちをおかした。","error"];
EXAMPLES[2383]=["I could not sleep because of the noise.","私はその音のために眠れませんでした。","noise"];
EXAMPLES[2384]=["A panel of experts discussed the plan.","専門家の委員達がその案を討論した。","panel"];
EXAMPLES[2385]=["My sister dropped her plate on the floor.","妹は床の上に皿を落とした。","plate"];
EXAMPLES[2386]=["The boy wants to go to the bathroom.","あの少年はトイレに行きたい。","bathroom"];
EXAMPLES[2387]=["I'd like to send a cable to Japan.","日本へ電報を打ちたいのですが。","cable"];
EXAMPLES[2388]=["My new book is not yet in print.","私の新しい本はまだ出版されていない。","print"];
EXAMPLES[2389]=["He got the first prize in the contest.","彼はそのコンテストで一等になった。","contest"];
EXAMPLES[2390]=["Lobsters belong to a class of marine animals.","ロブスターは海洋動物の一種に属します。","marine"];
EXAMPLES[2391]=["There is nothing the matter with the motor.","モーターについては何も問題がない。","motor"];
EXAMPLES[2392]=["Who will play the role of the princess?","誰がお姫様の役を演じるの。","princess"];
EXAMPLES[2393]=["He tried to reform the party from within.","彼は党を内部から改革しようとした。","reform"];
EXAMPLES[2394]=["We need a sample in addition to materials.","私たちには材料に加えて見本も必要だ。","sample"];
EXAMPLES[2395]=["Must the woman always play the secondary role?","女性は常に第二次的な役割をはたさなければならないのか。","secondary"];
EXAMPLES[2396]=["Solar energy is a new source of energy.","太陽のエネルギーは新しいエネルギー源だ。","Solar"];
EXAMPLES[2397]=["I replied automatically when I heard my name.","私の名前を聞いたとき思わず返事をした。","automatically"];
EXAMPLES[2398]=["The actress made her debut when she was eight.","その女優のデビューは８歳の時でした。","debut"];
EXAMPLES[2399]=["There is no external influence in that.","そのことには外からの影響は何もない。","external"];
EXAMPLES[2400]=["Children often live in a world of fantasy.","子供はよく空想の世界にいる。","fantasy"];
EXAMPLES[2401]=["The man made to grab at me.","その男は私につかみかかった。","grab"];
EXAMPLES[2402]=["In the introduction, the author is stating as follows.","序文で著者は次のように述べている。","introduction"];
EXAMPLES[2403]=["You need a license to drive a car.","車を運転する為には免許証が必要である。","license"];
EXAMPLES[2404]=["There was no need to paint the fence.","塀にペンキを塗る必要はなかった。","paint"];
EXAMPLES[2405]=["I have a friend who is a pilot.","私にはパイロットの友人がいる。","pilot"];
EXAMPLES[2406]=["Who is the girl in the pink dress?","ピンクの服を着ている少女は誰ですか。","pink"];
EXAMPLES[2407]=["We're regularly closed on Monday and 3rd Sunday.","定休日は、毎月曜日・第３日曜日です。","regularly"];
EXAMPLES[2408]=["Romeo and Juliet is on at the theatre.","「ロミオとジュリエット」が劇場で上演されている。","theatre"];
EXAMPLES[2409]=["Our campus festival is to be held next week.","学園祭は来週行われることになっている。","campus"];
EXAMPLES[2410]=["In opening the door, I broke the lock.","ドアを開ける際に、私は鍵を壊してしまった。","lock"];
EXAMPLES[2411]=["The musical was far from being a success.","そのミュージカルはとても成功とは呼べなかった。","musical"];
EXAMPLES[2412]=["Could I have a plastic bag for those?","ビニール袋に入れてください。","plastic"];
EXAMPLES[2413]=["I wonder what the advantage of this technique is.","この技術の利点って何なのかな？","technique"];
EXAMPLES[2414]=["There's a trend these days towards small families.","最近は小家族化の傾向がある。","trend"];
EXAMPLES[2415]=["The two factions gang up with each other.","２つの派閥が手をむすんだ。","gang"];
EXAMPLES[2416]=["Have you read the article about Asia in Time?","タイム誌のアジアについての記事を読んだかい？","Asia"];
EXAMPLES[2417]=["Brazil is the country I was born in.","ブラジルは、私の生まれ故郷です。","Brazil"];
EXAMPLES[2418]=["How did you know that I was Canadian?","どうして私がカナダ人だって分かったの？","Canadian"];
EXAMPLES[2419]=["One is Japanese and the other is Italian.","１人は日本人で、もう１人はイタリア人です。","Italian"];
EXAMPLES[2420]=["He applied himself to the study of Spanish.","彼はスペイン語の研究に専心した。","Spanish"];
EXAMPLES[2421]=["The imports from Asian countries have expanded recently.","アジア諸国からの輸入品は近年増大している。","Asian"];
EXAMPLES[2422]=["Only 30% of the Irish population speaks Irish.","アイルランド語を話す人は、アイルランド人の30%にしか及ばない。","Irish"];
EXAMPLES[2423]=["Social unrest may come about as a result of the endless rising of prices.","間断ない物価上昇の結果、社会不安が起こるかもしれない。","as a result"];
EXAMPLES[2424]=["Look up the words in your dictionary.","君の辞書でその単語を調べてみなさい。","Look up"];
EXAMPLES[2425]=["Will the room be available for the meetings?","その部屋を会議に使うことはできますか。","available"];
EXAMPLES[2426]=["In the past, Fletcher Fuel was approached by Japanese companies.","過去にフレッチャー石油は日本企業から接触を受けた。","In the past"];
EXAMPLES[2427]=["It's not easy to find a job nowadays.","今はね、仕事を見つけるのも楽じゃないよ。","nowadays"];
EXAMPLES[2428]=["I want to know how to gain weight.","どうすれば太れるのか知りたいよ。","gain"];
EXAMPLES[2429]=["This computer is second to none in quality.","このコンピューターは品質ではどれにも劣らない。","quality"];
EXAMPLES[2430]=["The company is trying to improve its image.","その会社はイメージアップをはかっている。","improve"];
EXAMPLES[2431]=["Will there be an extra charge for that?","それには追加料金がかかるんでしょうか。","extra"];
EXAMPLES[2432]=["She provided the traveler with food and clothing.","彼女はその旅行者に食べ物と着るものを与えた。","clothing"];
EXAMPLES[2433]=["I'll try not to disappoint you next time.","今度はがんばります。","disappoint"];
EXAMPLES[2434]=["Originally the meeting was planned for next Saturday.","まず第一に、会は次の土曜日に開くことに取り決められた。","Originally"];
EXAMPLES[2435]=["Americans, in general, don't like to dress up.","アメリカ人は一般に着飾ることを好まない。","dress up"];
EXAMPLES[2436]=["You had better leave the students to find out for themselves.","学生には自分で発見させるようにした方がいい。","find out"];
EXAMPLES[2437]=["How did you come up with this crazy idea?","こんな馬鹿げた考えをどうやって思いついたんだ？","come up with"];
EXAMPLES[2438]=["Please give me the details of the accident.","その事故の一部始終を私に話して下さい。","details"];
EXAMPLES[2439]=["I think that the snow will melt soon.","雪はすぐに解けると思いますよ。","melt"];
EXAMPLES[2440]=["I ran in the direction of the sun.","太陽の方向に走った。","direction"];
EXAMPLES[2441]=["What were you doing to get that injury?","何やっててそんな怪我したの？","injury"];
EXAMPLES[2442]=["All I can do is work in silence.","私のできることはただ黙って仕事をすることだけです。","silence"];
EXAMPLES[2443]=["These shoes are too tight to get into.","この靴はきつすぎてはけない。","tight"];
EXAMPLES[2444]=["He made a sharp turn to the right.","彼は右に急カーブした。","sharp"];
EXAMPLES[2445]=["You have the advantage of a good education.","君にはりっぱな教育を受けたという利点がある。","advantage"];
EXAMPLES[2446]=["I think he will object to our plan.","彼は私たちの計画に反対するだろう。","object"];
EXAMPLES[2447]=["The surface of the earth is 70% water.","地球の表面の７０％は水である。","surface"];
EXAMPLES[2448]=["I am no match for her in knowledge.","知識の点では私は彼女の足元にもおよばない。","knowledge"];
EXAMPLES[2449]=["We need to take care of this immediately.","すぐに治療しなければなりません。","immediately"];
EXAMPLES[2450]=["He is sure of succeeding in the experiment.","彼はその実験に成功することを確信している。","experiment"];
EXAMPLES[2451]=["I want a suit made of this material.","この生地で洋服を作ってください。","material"];
EXAMPLES[2452]=["There is not much traffic on this road.","この道はあまり車が通らないんだ。","traffic"];
EXAMPLES[2453]=["I think that we should reduce the price.","値段を下げるべきだと思います。","reduce"];
EXAMPLES[2454]=["You can see the island in the distance.","はるかその島が見えます。","distance"];
EXAMPLES[2455]=["I will do it at the first opportunity.","機会があり次第、そうしよう。","opportunity"];
EXAMPLES[2456]=["I prefer to do it on my own.","自分でやりたいんです。","prefer"];
EXAMPLES[2457]=["Do not mention the accident before the children.","子供たちの前でその事故の話をするな。","mention"];
EXAMPLES[2458]=["What is your impression of the United States?","アメリカはいかがですか。","impression"];
EXAMPLES[2459]=["The police knew it was a hot item.","警察はそれがやばい品物なのを知ってたんだよ。","item"];
EXAMPLES[2460]=["It was to his profit to do so.","そうするのが彼のためだった。","profit"];
EXAMPLES[2461]=["Would you put the dishes in the sink?","お皿を流しに置いてもらえますか。","sink"];
EXAMPLES[2462]=["The effects of the illness were not serious.","その病気はたいしたことにはならなかった。","illness"];
EXAMPLES[2463]=["He speaks as if he were an expert.","彼はまるで専門家であるかのように話す。","expert"];
EXAMPLES[2464]=["Were I in your position, I would quit.","私があなたの立場だったら、辞めているだろうに。","quit"];
EXAMPLES[2465]=["It was silly of you to trust them.","君がやつらを信じたのはばかだった。","silly"];
EXAMPLES[2466]=["He is a son of a wealthy family.","彼は裕福な家庭の息子だ。","wealthy"];
EXAMPLES[2467]=["If you are a man, behave as such.","男であるならそのように振舞いなさい。","behave"];
EXAMPLES[2468]=["Travel by train has been on the decrease.","列車の旅は減る傾向にある。","decrease"];
EXAMPLES[2469]=["Let's divide this money between you and me.","この金をあなたと私の２人で分けよう。","divide"];
EXAMPLES[2470]=["If I were you, I would ignore it.","もし僕が君ならそんなことは無視するだろう。","ignore"];
EXAMPLES[2471]=["They're trying to organize a new political party.","彼らは新しい政党を作ろうとしている。","organize"];
EXAMPLES[2472]=["He did his best to overcome his enemy.","彼は敵を打ち負かすのに全力を尽くした。","overcome"];
EXAMPLES[2473]=["Words attract people, and sometimes keep them away.","言葉は人を惹きつけ、時として人を遠ざける。","attract"];
EXAMPLES[2474]=["Don't breathe a word of it to anyone.","おくびにも出すな。","breathe"];
EXAMPLES[2475]=["You should not confuse business with personal affairs.","公私を混同してはいけない。","confuse"];
EXAMPLES[2476]=["Did you reserve a room at the hotel?","ホテルの部屋を予約しましたか。","reserve"];
EXAMPLES[2477]=["At that time, I was still not asleep.","その時は、まだ寝付いてなかったよ。","asleep"];
EXAMPLES[2478]=["Living in the country, he rarely had visitors.","田舎で暮らしている彼を、訪ねて来る人はほとんどいなかった。","rarely"];
EXAMPLES[2479]=["Thanks to you I've lost my appetite.","あんたのせいで食欲をなくしたよ。","Thanks to"];
EXAMPLES[2480]=["He will have left here by the time you return.","君が戻るまでには彼はここをたってしまっているだろう。","by the time"];
EXAMPLES[2481]=["Some knowledge of foreign languages, of Spanish in particular, is essential.","外国語、特にスペイン語の知識は不可欠です。","in particular"];
EXAMPLES[2482]=["I'll take over your duties while you are away from Japan.","君が日本を離れている間は、私が君の職務を引き継ぎましょう。","take over"];
EXAMPLES[2483]=["It was cold, and, in addition, it was windy.","寒くておまけに風も強かった。","in addition"];
EXAMPLES[2485]=["Even though he apologized, I'm still furious.","謝罪はあったにせよ、私はまだ彼に腹を立てている。","Even though"];
EXAMPLES[2486]=["Is there anything to drink in the refrigerator?","冷蔵庫に何か飲み物がありますか。","refrigerator"];
EXAMPLES[2487]=["Would you do me a favor?","一つお願いを聞いて頂けませんか。","do me a favor"];
EXAMPLES[2488]=["I'll stay here till you get back.","君が帰ってくるまで僕はここにいるよ。","get back"];
EXAMPLES[2489]=["In spite of the rain, we enjoyed our holiday.","雨は降ったが、私たちは休日を楽しんだ。","In spite of"];
EXAMPLES[2490]=["When you go abroad, you'd better keep in mind that tipping is customary.","海外に行ったときは、チップが必要なことを覚えていたほうがいいですよ。","keep in mind"];
EXAMPLES[2491]=["On the way to London Mr Higgins told Tom and Susie many interesting things.","ロンドンへ行く途中、ヒギンズ氏はトムとスージーにおもしろいことをたくさん話しました。","On the way to"];
EXAMPLES[2492]=["Let me put down your new phone number in my notebook.","君の新しい電話番号を手帳にかきとめさせてくれ。","put down"];
EXAMPLES[2493]=["You can rely on him.","彼に頼っておけばいい。","rely on"];
EXAMPLES[2494]=["The music doesn't appeal to us any longer.","その音楽はもはや我々の心に訴えない。","appeal to"];
EXAMPLES[2495]=["You had better call off your plan.","君は計画を中止したほうがよい。","call off"];
EXAMPLES[2496]=["We thought we would write out the directions, in case you got lost.","君が迷子になるといけないので、地図を書こうと思った。","in case"];
EXAMPLES[2497]=["On average, these packages weigh two pounds.","これらの小包の重さは平均すると２ポンドです。","On average"];
EXAMPLES[2498]=["Do you think he made that mistake on purpose?","君は彼がわざとその間違いをしたと思うかい。","on purpose"];
EXAMPLES[2499]=["Students are expected to stay away from dubious places.","学生たるものはいかがわしい場所にちかづかない方がよい。","stay away from"];
EXAMPLES[2500]=["This city will suffer from an acute water shortage unless it rains soon.","近いうちに雨が降らない限り、この町は深刻な水不足になるだろう。","suffer from"];
EXAMPLES[2501]=["You are to apologize to her for it.","君はその事について彼女に謝るべきだ。","apologize"];
EXAMPLES[2502]=["You are sure to succeed in time.","君はそのうち必ず成功する。","succeed in"];
EXAMPLES[2503]=["A car is convenient, to be sure, but, after all, it will prove expensive.","確かに車は便利だが、結局高いものにつく。","after all"];
EXAMPLES[2505]=["You'll be unlikely to find any rent that's under ₤300 in this area.","この辺りで家賃が５万円を下ることはまずありませんよ。","be unlikely to"];
EXAMPLES[2506]=["You have to study hard to catch up with your class.","君はクラスのみんなに追いつくために、一生懸命勉強しなくてはならない。","catch up with"];
EXAMPLES[2507]=["We differ from them in some respects.","われわれはいくつかの点で彼らと違う。","differ from"];
EXAMPLES[2508]=["Anyone can participate in the game, no matter what nationality they are.","その試合には国籍のいかんを問わず誰でも参加出来る。","participate in"];
EXAMPLES[2509]=["Sooner or later, you will regret your idleness.","君は遅かれ早かれ怠けていたことを後悔するよ。","Sooner or later"];
EXAMPLES[2510]=["Your problem is similar to mine.","君の悩みは僕の悩みと同じだ。","similar to"];
EXAMPLES[2511]=["Don't you think this is a good opportunity to show off your talents?","あなたの才能を示すよい機会だと思いませんか。","show off"];
EXAMPLES[2512]=["Turn down the volume, please.","音量を下げてください。","Turn down"];
EXAMPLES[2513]=["Please fill out this form first.","まず、この書類に必要事項を書き込んでください。","fill out"];
EXAMPLES[2514]=["His success was mostly due to good luck.","彼の成功は大部分幸運によるものだった。","mostly"];
EXAMPLES[2515]=["You have to dig down and pay for it.","自分の責任を認めて自腹をきりなさい。","dig"];
EXAMPLES[2516]=["The heart is made of muscle.","心臓は筋肉でできている。","muscle"];
EXAMPLES[2517]=["I will bite off just a little bit.","一口で食べてみよう。","bite"];
EXAMPLES[2518]=["You never used to treat me like this.","あなたは昔私をこんなふうに扱わなかった。","treat"];
EXAMPLES[2519]=["He is rather hard to get along with.","彼はなかなか折り合ってつきあいにくい人だ。","rather"];
EXAMPLES[2520]=["Apparently there's a cancellation charge of 30 percent.","キャンセル料３割もとられるんだって。","Apparently"];
EXAMPLES[2521]=["I do not make much of that discovery.","私はその発見を大して重視しない。","discovery"];
EXAMPLES[2522]=["The news of her arrival excited the crowd.","彼女の到着のニュースは群集を興奮させた。","arrival"];
EXAMPLES[2523]=["I have a cold and a 38-degree fever.","かぜで熱が三十八度あります。","degree"];
EXAMPLES[2524]=["I found it difficult to achieve my purpose.","目的を遂げるということは難しいということがわかった。","achieve"];
EXAMPLES[2525]=["I don't have a problem with his attitude.","彼の態度に問題はない。","attitude"];
EXAMPLES[2526]=["He had a great belief in the doctor.","彼はその医者を大変信頼していた。","belief"];
EXAMPLES[2527]=["He went on to demonstrate how to use the machine.","続いて彼はその機械の動かし方を実演してくれた。","demonstrate"];
EXAMPLES[2528]=["I wish I could see the ancient world.","古代世界を見ることができればなあ。","ancient"];
EXAMPLES[2529]=["I will send our formal agreement to you.","正式な契約書をお送りします。","formal"];
EXAMPLES[2530]=["You have to allow for the boy's age.","あの子の年を考えてやらなければいけないよ。","allow"];
EXAMPLES[2531]=["I cut the article out of the magazine.","私はその記事を雑誌から切りとった。","article"];
EXAMPLES[2532]=["Can I slap you? I can't contain myself.","引っ叩いていい？腹の虫が治まらないんだけど。","contain"];
EXAMPLES[2533]=["I took my temperature, but it was normal.","体温を計ってみましたが、平熱でした。","temperature"];
EXAMPLES[2534]=["There were hardly any people in the room.","部屋にはほとんど人がいなかった。","hardly"];
EXAMPLES[2535]=["He is unable to provide for his family.","彼は自分の家族を養う事ができない。","unable"];
EXAMPLES[2536]=["There is a good argument for that decision.","その決定を下したことについては十分な理由がある。","argument"];
EXAMPLES[2537]=["English and German share a common ancestor.","英語はドイツ語と同語族である。","ancestor"];
EXAMPLES[2538]=["She and I are about the same height.","私は彼女とほぼ同じ身長です。","height"];
EXAMPLES[2539]=["I know an ideal place for a party.","パーティーのためのうってつけの場所を知ってるよ。","ideal"];
EXAMPLES[2540]=["The actor died at the height of his popularity.","その俳優は人気絶頂の時に死んだ。","popularity"];
EXAMPLES[2541]=["Get in touch with your agent right away.","すぐにあなたの代理人に連絡を取りなさい。","agent"];
EXAMPLES[2542]=["They are unworthy of the praise given them.","彼らは与えられた賞賛に値しない。","praise"];
EXAMPLES[2543]=["In the name of the moon, we'll punish you!","月に代わっておしおきよっ！","punish"];
EXAMPLES[2544]=["I don't like a negative sort of man.","消極的な男は嫌いだ。","negative"];
EXAMPLES[2545]=["Wisdom does not consist only in knowing facts.","知恵というものは単に事実を知っているだけではない。","consist"];
EXAMPLES[2546]=["It is the wrong place to criticize me.","オレを非難するのはお門違いだ。","criticize"];
EXAMPLES[2547]=["The government started a program to promote industry.","政府は工業の振興計画を開始した。","promote"];
EXAMPLES[2548]=["There is little hope that he will recover.","彼が回復する見込みはほとんどない。","recover"];
EXAMPLES[2549]=["Could you translate this into French for me?","これを私のためフランス語へ翻訳してもらえませんか？","translate"];
EXAMPLES[2550]=["He and I have been friends since childhood.","あいつと俺は幼馴染みなんだ。","childhood"];
EXAMPLES[2551]=["This task is impossible for me to accomplish.","その仕事は私には無理だよ。","accomplish"];
EXAMPLES[2552]=["It is hard to combine business with pleasure.","仕事と遊びを結び付けるのは難しい。","combine"];
EXAMPLES[2553]=["I am in need of a responsible person.","私は頼りになる人が欲しいです。","responsible"];
EXAMPLES[2554]=["You shouldn't look down on him.","君は彼を軽蔑するべきではない。","look down on"];
EXAMPLES[2555]=["You had plenty of time.","時間はたっぷりあった。","plenty of"];
EXAMPLES[2556]=["I sometimes have a pain in my stomach.","時々、胃が痛むんだ。","stomach"];
EXAMPLES[2557]=["Do you have a vision of your future?","あなたは自分の将来のビジョンを持っていますか。","vision"];
EXAMPLES[2558]=["Productivity will increase with the expansion of the factory.","工場の拡張で生産力を増強する。","expansion"];
EXAMPLES[2559]=["This kind of thing doesn't occur very often.","こうしたことはそれほどたびたび起こるものではない。","occur"];
EXAMPLES[2560]=["Have you found the solution to the problem?","その問題の答えは見つかりましたか？","solution"];
EXAMPLES[2561]=["I never feel at ease in his company.","私は彼と一緒にいるとくつろげない。","ease"];
EXAMPLES[2562]=["We will elect whoever we believe is worthy.","誰であれ立派だと私たちが信じる人を選びます。","elect"];
EXAMPLES[2563]=["A family is the smallest unit of society.","家族は社会の最小構成単位である。","unit"];
EXAMPLES[2564]=["He proposed a reform in the educational system.","彼は教育制度の改革を提案した。","educational"];
EXAMPLES[2565]=["He did not like her manner of speech.","彼は彼女の話し振りが気に入らなかった。","manner"];
EXAMPLES[2566]=["To some life is pleasure, to others suffering.","人生が楽しい人もいれば、苦しい人もいる。","suffering"];
EXAMPLES[2567]=["My courage failed me at the crucial moment.","いざとなったら勇気が無くなった。","crucial"];
EXAMPLES[2568]=["They that govern the most make the least noise.","最も多くを制する者は、なるべくなりをひそめる。","govern"];
EXAMPLES[2570]=["She is what we call a talented woman.","彼女はいわゆる才女である。","talented"];
EXAMPLES[2571]=["We have little money available for the research.","その研究に使える金はほとんどないんだ。","research"];
EXAMPLES[2572]=["I got a temporary job at the firm.","私はその会社で臨時の仕事を得た。","firm"];
EXAMPLES[2573]=["He contributed to the good of the community.","彼は社会の福利のために貢献してくれた。","community"];
EXAMPLES[2574]=["Nothing can force me to give it up.","何も私にそれをあきらめるように強制することができない。","force"];
EXAMPLES[2575]=["Her eyes, a deep blue, were quite impressive.","彼女の濃いブルーの瞳がとても印象的だった。","impressive"];
EXAMPLES[2576]=["Can I get an advance on my salary?","給料の前借りをお願いできますか。","salary"];
EXAMPLES[2577]=["He is a hard man to deal with.","彼は交わるにはむずかしい人だ。","deal"];
EXAMPLES[2578]=["He wrote a prompt answer to my letter.","彼は私の手紙にすぐさま返事を書いてくれた。","prompt"];
EXAMPLES[2580]=["The vote was 74 to 26 in favor.","採決は７４対２６の賛成多数でした。","vote"];
EXAMPLES[2581]=["We would have a wide range of alternatives.","幅広い選択の余地があったであろうに。","range"];
EXAMPLES[2582]=["Water is a natural resource of vital importance.","水は極めて重要な天然資源の１つだ。","vital"];
EXAMPLES[2583]=["He made over the estate to his children.","彼は不動産を子供達に譲った。","estate"];
EXAMPLES[2584]=["In brief, you should have accepted the responsibility.","つまり君が責任を取るべきだったのだ。","responsibility"];
EXAMPLES[2585]=["This fact is all but unknown to them.","この事実は彼らにほとんど知られていない。","unknown"];
EXAMPLES[2586]=["He will grant permission for you to go out.","彼は、君の外出許可を与えるでしょう。","grant"];
EXAMPLES[2587]=["He could not perceive any difference between the twins.","彼はその双子の違いを何ら気づく事が出来なかった。","perceive"];
EXAMPLES[2588]=["I love this town, especially in the spring.","この町が大好きなんだ。特に春がね。","especially"];
EXAMPLES[2589]=["He tried to imagine what the client was like.","彼は依頼人がどんな人間なのか想像してみた。","client"];
EXAMPLES[2590]=["He was suddenly attacked by a mysterious disease.","その子は突然わけのわからない病気に襲われた。","mysterious"];
EXAMPLES[2591]=["One of the qualities of steel is hardness.","鉄鋼の特性の１つは硬いことだ。","steel"];
EXAMPLES[2592]=["The concept of zero comes from Hindu culture.","ゼロという概念は、ヒンドゥー文化に由来している。","concept"];
EXAMPLES[2593]=["Nevertheless, I want to go there.","それでも、そこに行ってみたい。","Nevertheless"];
EXAMPLES[2594]=["It's not fair to attribute your failure to your parents.","失敗を両親のせいにするのはフェアではありません。","attribute"];
EXAMPLES[2595]=["There is nothing to prevent us from going.","私たちが行くのを妨げるものは何もない。","prevent"];
EXAMPLES[2596]=["The box bears the stamp of the manufacturer.","その箱には製造者の証印が押してある。","manufacturer"];
EXAMPLES[2597]=["The law is not in effect any longer.","その法律は効力が無くなっている。","effect"];
EXAMPLES[2598]=["His encounter with her is enriching his inner life.","彼女との出会いが彼の生活に精神的に潤いをもたらしている。","encounter"];
EXAMPLES[2599]=["Don't accuse others for your own failure.","自分の失敗で他人を非難するな。","accuse"];
EXAMPLES[2600]=["To put it briefly, I do not agree.","簡単に言えば、私は賛成しません。","briefly"];
EXAMPLES[2602]=["Our topic for this week is global warming.","今週の話題は地球温暖化です。","global"];
EXAMPLES[2603]=["Lack of sleep is bad for the body.","寝不足は体に悪い。","Lack"];
EXAMPLES[2604]=["His essay was concise and to the point.","彼の小論文は簡潔で要点をきちんと押さえていた。","essay"];
EXAMPLES[2605]=["That was his nearest approach to a smile.","あれが彼としては精一杯の微笑だった。","approach"];
EXAMPLES[2606]=["He is a natural to win the Presidency.","彼は必ず大統領の椅子につく人物だ。","natural"];
EXAMPLES[2607]=["He's in charge of administration at the hospital.","彼は病院の管理運営に責任がある。","administration"];
EXAMPLES[2608]=["The factory had to cut back its production.","工場は生産を縮小せざるをえなかった。","production"];
EXAMPLES[2609]=["Does my training qualify me to teach?","私の受けた訓練で教師の資格は十分だろうか。","qualify"];
EXAMPLES[2610]=["Apart from the result, your intention was good.","結果はさておき、あなたの意図はよかった。","intention"];
EXAMPLES[2611]=["I recognized him immediately since we had previously met.","以前会った事があったので、すぐに彼がわかった。","previously"];
EXAMPLES[2612]=["Each member has to pay a membership fee.","各会員は会費を払うべし。","fee"];
EXAMPLES[2613]=["You are not to blame, nor is he.","君が悪いのではないし、彼が悪いのでもない。","nor"];
EXAMPLES[2614]=["The negotiation has entered upon a new phase.","交渉は新局面に入った。","negotiation"];
EXAMPLES[2615]=["There is little automobile traffic on this road.","この道路は車の通りが少ない。","automobile"];
EXAMPLES[2616]=["There's a lot of dust in the air.","空気中にはほこりがたくさん舞っています。","dust"];
EXAMPLES[2617]=["I was extremely surprised when I saw this.","これを見たときはびっくり仰天した。","extremely"];
EXAMPLES[2618]=["Her voice echoed through the silent house.","彼女の声は家中に響き渡りました。","echoed"];
EXAMPLES[2619]=["He gave a detailed description of the accident.","彼はその事故のことを詳しく述べた。","detailed"];
EXAMPLES[2620]=["You may spend a maximum of 100 dollars.","最高百ドルまで遣ってよい。","maximum"];
EXAMPLES[2621]=["The handle of this pan is easy to hold.","このフライパンのとっては持ちやすい。","pan"];
EXAMPLES[2622]=["This work is an improvement on your last.","この作品は君の前のに比べて進歩している。","improvement"];
EXAMPLES[2623]=["It is believed that she is a genius.","彼女は天才だと信じられている。","genius"];
EXAMPLES[2624]=["The boy is a credit to our school.","その少年は我が校の名誉だ。","credit"];
EXAMPLES[2625]=["He is up to his ears in debt.","借金で足掻きがとれない。","debt"];
EXAMPLES[2626]=["Will the therapy cause me any pain?","その療法は少し痛むのでしょうか。","therapy"];
EXAMPLES[2627]=["I just want to glance at the paper.","僕はちょっと新聞に目を通したい。","glance"];
EXAMPLES[2628]=["Tom carried two boxes into the storage room.","トムは箱を二つ収納室の中へ運んだ。","storage"];
EXAMPLES[2629]=["He is unable to concentrate on his academic work.","彼は学業に専心できない。","academic"];
EXAMPLES[2630]=["Circumstances did not permit me to help you.","私は事情があってお手伝いできませんでした。","permit"];
EXAMPLES[2631]=["I have a concern in the business.","私はその事業に関係している。","concern"];
EXAMPLES[2632]=["The strain is beginning to tell on him.","無理が彼の体にこたえ始めた。","strain"];
EXAMPLES[2633]=["I was transferred to the middle of nowhere.","辺ぴなところに転勤になった。","nowhere"];
EXAMPLES[2634]=["Do you have a recent photo of yourself?","あなたの最近の写真をお持ちですか。","recent"];
EXAMPLES[2635]=["He was dropped because of his running mate.","彼は組んだ下位候補者が悪かったので落選しました。","mate"];
EXAMPLES[2636]=["He can not distinguish between right and wrong.","彼は正しいことと間違ったことを区別できない。","distinguish"];
EXAMPLES[2637]=["The readers of that book think themselves sophisticated.","あの本の読者たちは自分のことをインテリだと思っている。","sophisticated"];
EXAMPLES[2638]=["She looked upset as she read the letter.","彼女はその手紙を読んでいる時うろたえた様子だった。","upset"];
EXAMPLES[2639]=["It will disturb you in your studies.","それは君の勉強の妨げになるだろう。","disturb"];
EXAMPLES[2640]=["The government should invest more money in industry.","政府は産業にもっと多くの金を投資すべきだ。","invest"];
EXAMPLES[2641]=["I had an intense pain in the head.","頭に激しい痛みがあった。","intense"];
EXAMPLES[2642]=["His decision to retire surprised all of us.","彼が引退を決意したことは私たちみんなを驚かせた。","retire"];
EXAMPLES[2643]=["The area is notable for its scenery and wildlife.","その地域は風景と野生動物で注目に値する。","wildlife"];
EXAMPLES[2644]=["It is not polite to point at others.","他人を指差すのは失礼なことです。","polite"];
EXAMPLES[2645]=["They gave a play to entertain their teachers.","彼らは先生を楽しませるために劇をした。","entertain"];
EXAMPLES[2646]=["Competition in itself is not a bad thing.","競争それ自体は悪くない。","Competition"];
EXAMPLES[2647]=["He gave an expeditious answer to an inquiry.","彼は質問に即答した。","inquiry"];
EXAMPLES[2648]=["You must bind yourself to keep your promise.","君は約束を守ることを誓わなければならない。","bind"];
EXAMPLES[2649]=["A passenger airplane took off for the USA.","旅客機がアメリカに向けて出発した。","passenger"];
EXAMPLES[2650]=["Meanwhile, you can get a little sleep.","それまで少し横になるといいよ。","Meanwhile"];
EXAMPLES[2651]=["The more you earn, the more you spend.","収入が増えれば増えるほど、消費もいっそう多くなる。","earn"];
EXAMPLES[2652]=["In the Russian language, conjugation is very complex.","ロシア語では、動詞の活用がとても複雑です。","complex"];
EXAMPLES[2653]=["Moreover, how much did you pay for that?","それにいくら払ったの？","Moreover"];
EXAMPLES[2654]=["I grasped the entire structure of his argument.","私は彼の議論の全体像を把握した。","structure"];
EXAMPLES[2655]=["He made mistakes on purpose to annoy me.","彼は私を困らせるために間違えた。","annoy"];
EXAMPLES[2656]=["The influence of TV on society is great.","テレビが社会に与える影響は大きい。","influence"];
EXAMPLES[2657]=["Will you explain the last part in detail?","最後の部分を詳しく説明してくれない？","detail"];
EXAMPLES[2658]=["Prior to your arrival, he left for London.","あなたが到着される前に、彼はロンドンへ出発しました。","Prior"];
EXAMPLES[2660]=["He is engaged in the study of energy.","彼はエネルギーの研究に従事している。","engaged"];
EXAMPLES[2661]=["I regret not being able to join you.","参加できなくて残念です。","regret"];
EXAMPLES[2662]=["There is a small pond in the court.","中庭に小さい池がある。","court"];
EXAMPLES[2663]=["Solar energy does not threaten the environment.","太陽エネルギーは環境を脅かさない。","threaten"];
EXAMPLES[2664]=["The scholarship enable her to go to college.","奨学金のおかげで彼女は大学に進学できた。","enable"];
EXAMPLES[2665]=["Unfortunately, I don't have time to do that.","残念ですがそんなことをする暇がありません。","Unfortunately"];
EXAMPLES[2666]=["This painting is a representation of a storm at sea.","この絵は海の嵐を描いたものである。","representation"];
EXAMPLES[2667]=["What is the procedure for getting a visa?","ビザを入手する手続きはどうしたらいいですか。","procedure"];
EXAMPLES[2668]=["It will prove to be up to expectation.","それは期待にそうものであると分かるだろう。","expectation"];
EXAMPLES[2669]=["She will be an asset to the Purchasing Department.","購買部にとって重要な人材になられると思います。","asset"];
EXAMPLES[2670]=["You were about to dump her flat out, weren't you?","カズちゃん、さっき完膚無きまでに振っちゃおうとしたでしょ？","dump"];
EXAMPLES[2671]=["He became a citizen of the United States.","彼は、アメリカ国民になった。","citizen"];
EXAMPLES[2672]=["You must take up a regular occupation.","何か決まった仕事につきなさい。","occupation"];
EXAMPLES[2673]=["How on earth can we restore our youth?","一体どうしたら若さが取り戻せるのだろう。","restore"];
EXAMPLES[2674]=["Your thoughts are of no significance at all.","君の考えなどはどうだっていいことだ。","significance"];
EXAMPLES[2675]=["The flow of this river is fast.","この川は流れが速い。","flow"];
EXAMPLES[2676]=["What is the cause of such a failure?","その失敗の原因は何？","failure"];
EXAMPLES[2677]=["Corporate earnings for the first quarter were disappointing.","第一四半期の企業収益は失望的な結果だった。","earnings"];
EXAMPLES[2678]=["The king created him a peer.","王は彼を貴族に列した。","peer"];
EXAMPLES[2679]=["The threats to this strategy are numerous.","この作戦に対する脅威は数多い。","strategy"];
EXAMPLES[2680]=["It is remarkable for her not to understand.","彼女がわからないことは珍しい事だ。","remarkable"];
EXAMPLES[2681]=["The first baseman is the Achilles heel of our team.","ファーストがうちのチームのアキレスけんだ。","heel"];
EXAMPLES[2682]=["I was urged to self isolate at home today.","今日は自宅待機を促された。","isolate"];
EXAMPLES[2683]=["Japan is highly competitive in high technology industries.","日本はハイテク産業の競争力がある。","competitive"];
EXAMPLES[2684]=["That way of talking is typical of him.","そうしたしゃべりかたはいかにも彼らしい。","typical"];
EXAMPLES[2685]=["I had to compete with him for promotion.","私は昇進をかけて彼と競争しなければならなかった。","compete"];
EXAMPLES[2686]=["The middle aged man was charged with assault.","その中年の男は暴行のかどで訴えられた。","assault"];
EXAMPLES[2687]=["I have a strong conviction that our judgement was right.","我々の判断は正しかったと私は十分確認している。","conviction"];
EXAMPLES[2688]=["Bill is on his way to New York.","ビルはニューヨークへ行く途中だ。","Bill"];
EXAMPLES[2689]=["I want to emphasize this point in particular.","僕はこの点を特に強調したい。","emphasize"];
EXAMPLES[2690]=["Many immigrants to Britain have come from Asia.","英国への多くの移民はアジアからきている。","immigrants"];
EXAMPLES[2691]=["I don't know how to interpret his words.","彼の言葉をどう解釈していいのか分からない。","interpret"];
EXAMPLES[2692]=["The ice is thick enough to walk on.","その上を歩けるほど氷は厚い。","thick"];
EXAMPLES[2693]=["I have to bone up on my physics.","私は一生懸命物理に取り組まなければならない。","physics"];
EXAMPLES[2694]=["We will trigger a revolution in the IT industry.","ITのマーケットプレイスに革命を起こす。","trigger"];
EXAMPLES[2695]=["The status of the project is as follows.","プロジェクトの経過は下記の通りです。","status"];
EXAMPLES[2696]=["He has many enemies in the political world.","彼は政界に敵が多い。","political"];
EXAMPLES[2697]=["The truth is that she was not there.","事実は彼女がそこにいなかったことだ。","truth"];
EXAMPLES[2698]=["The wall is partly covered with ivy.","その壁は部分的につたで覆われている。","partly"];
EXAMPLES[2699]=["You must observe the rules of the club.","クラブの規則を守らねばならない。","observe"];
EXAMPLES[2700]=["He sat at the edge of the stream.","彼は川のふちに腰を下ろした。","stream"];
EXAMPLES[2701]=["You have no right to oppose our plan.","君には、私たちの計画に反対する権利はない。","oppose"];
EXAMPLES[2702]=["They seem to be conscious of the fact.","彼らはその事実に気づいているようだ。","conscious"];
EXAMPLES[2703]=["Do you intend to go to that restaurant?","そのお店に行くつもりなの？","intend"];
EXAMPLES[2704]=["My father is going to have an operation.","父は手術を受ける事になっている。","operation"];
EXAMPLES[2705]=["He will recommend you for a good post.","彼はあなたをよい地位に推薦するだろう。","recommend"];
EXAMPLES[2706]=["Great speed is a feature of the Concorde.","超高速がコンコルド機の特徴だ。","feature"];
EXAMPLES[2707]=["We have to take this problem into consideration.","私たちはこの問題を考慮に入れなくてはならない。","consideration"];
EXAMPLES[2708]=["She is on a diet to lose weight.","彼女はやせるためにダイエットをしています。","diet"];
EXAMPLES[2709]=["The population of the city is about 100,000.","その市の人口は約１０万である。","population"];
EXAMPLES[2710]=["The end does not necessarily justify the means.","目的は必ずしも手段を正当化しない。","necessarily"];
EXAMPLES[2711]=["The problem is whether the plan will work.","問題は計画がうまくいくかどうかだ。","whether"];
EXAMPLES[2712]=["He made a close analysis of the situation.","彼はその状況について綿密な分析をした。","analysis"];
EXAMPLES[2713]=["Your behavior is in conflict with your principles.","君の行動は君の信条と矛盾している。","conflict"];
EXAMPLES[2714]=["His way of thinking is a bit extreme.","彼の考え方は少し極端だ。","extreme"];
EXAMPLES[2715]=["You can go wherever you want to go.","行きたいところへはどこへでも行けます。","wherever"];
EXAMPLES[2716]=["I got the news from a reliable source.","私はそのニュースを確かな筋から得た。","source"];
EXAMPLES[2717]=["His objective is to pass the test.","彼の目的は合格することです。","objective"];
EXAMPLES[2718]=["I want to live in a rural area.","田舎に住みたいな。","rural"];
EXAMPLES[2719]=["The actor's death made big headlines in all the papers.","その俳優の死は各紙で大見出しで報じられた。","headlines"];
EXAMPLES[2721]=["Do you have any clue to the mystery?","その謎を解く何か手がかりがありますか。","clue"];
EXAMPLES[2723]=["The commission concluded that the answer was no.","委員会は反対という結論を出した。","commission"];
EXAMPLES[2724]=["Do you want to play hide and seek?","かくれんぼしようか？","seek"];
EXAMPLES[2725]=["You should have your son independent of you.","あなたの息子さんを親離れさせるべきです。","independent"];
EXAMPLES[2726]=["All of a sudden, he proposed to me.","彼は出し抜けに私に結婚してくれといった。","proposed"];
EXAMPLES[2727]=["I think I have a theory about that.","私にそれに関する理論をもっていると思う。","theory"];
EXAMPLES[2728]=["The fellow standing over there is my friend.","あそこに立っている男は私の友人です。","fellow"];
EXAMPLES[2729]=["We must be kind to the elderly.","われわれは老人に親切にしなければならない。","elderly"];
EXAMPLES[2730]=["The extension of summer vacation delighted the children.","夏休みが延びたので子供達は喜んだ。","extension"];
EXAMPLES[2731]=["Tom is the proper boy for the job.","トムはその仕事に適した少年だ。","proper"];
EXAMPLES[2732]=["If you have a good garden, it will enhance the value of your house.","よい庭がついていれば家の価値を高めるでしょう。","enhance"];
EXAMPLES[2733]=["She is due to speak for the class.","彼女はクラスを代表して演説することになっている。","due"];
EXAMPLES[2734]=["The existing law concerning car accidents requires amending.","車の事故に関する現行の法は手直しが必要である。","existing"];
EXAMPLES[2735]=["There is a scheme to expand the company.","その会社では拡張の計画があります。","expand"];
EXAMPLES[2736]=["The rebel was ultimately captured and confined to jail.","ついに反逆者は捕らえられ、拘置所に入れられた。","rebel"];
EXAMPLES[2737]=["We all suffer from it to some degree.","我々は皆ある程度それに苦しむ。","suffer"];
EXAMPLES[2738]=["He is heart and soul a Democrat.","彼はまったくの民主党員だ。","Democrat"];
EXAMPLES[2739]=["Well, personally, I don't really care for it.","そうですね、私としては、あまり好みません。","personally"];
EXAMPLES[2740]=["He has helped the poor throughout his life.","彼は生涯に渡って貧しい人々を助けた。","throughout"];
EXAMPLES[2741]=["We should preserve the beauties of the countryside.","私達は田舎の美しさを保存するべきだ。","preserve"];
EXAMPLES[2742]=["Who is the most intelligent person you know?","君が知ってる人の中で誰が一番賢い？","intelligent"];
EXAMPLES[2743]=["You are carried along with the slide.","勢いに流されているんですよ。","slide"];
EXAMPLES[2744]=["There is no doubt that he was murdered.","彼が殺されたことは疑いの余地は無い。","murdered"];
EXAMPLES[2745]=["She is constantly in and out of hospital.","彼女は入退院を繰り返している。","constantly"];
EXAMPLES[2746]=["The drift of the current is to the south.","潮の流れは南の方向に向かっている。","drift"];
EXAMPLES[2747]=["You should not make little of the result.","その結果を軽く見てはいけない。","result"];
EXAMPLES[2748]=["This duty has priority over all others.","この任務はすべての任務に優先する。","priority"];
EXAMPLES[2749]=["The two companies combined in a joint corporation.","その二つの会社は合併して合弁会社となった。","joint"];
EXAMPLES[2750]=["Television viewers see only what the camera shows.","テレビ観戦者はカメラが捕らえるものしか見られない。","viewers"];
EXAMPLES[2751]=["The moon is a satellite of the earth.","月は地球の衛星である。","satellite"];
EXAMPLES[2752]=["The sun is so distant from the earth.","太陽は地球からとても遠い。","distant"];
EXAMPLES[2753]=["The article will be sent cash on delivery.","品物は代金引換でお送りいたします。","delivery"];
EXAMPLES[2754]=["People seemed to be anxious about the future.","人々は将来のことを心配しているようだった。","anxious"];
EXAMPLES[2755]=["The ball rolled on the ground towards me.","ボールは地面の上を私に向かってころがった。","towards"];
EXAMPLES[2756]=["The difference in our ages is not significant.","私たちの年齢の差は重要ではない。","significant"];
EXAMPLES[2757]=["Do you have anything to say in particular?","何か特に言う事がありますか。","particular"];
EXAMPLES[2758]=["He was the first man to float in space.","彼は宇宙を遊泳した最初の人間だった。","float"];
EXAMPLES[2759]=["He is reading a book of literary criticism.","彼は文学評論の本を読んでいる。","criticism"];
EXAMPLES[2760]=["It began to appear that she was wrong.","彼女が間違っているように思われはじめた。","appear"];
EXAMPLES[2761]=["I will give you permission to do it.","それをしてもよろしい。","permission"];
EXAMPLES[2762]=["That looks like the work of a virus.","それ、ウィルスの仕業じゃないかな。","virus"];
EXAMPLES[2763]=["I think it impossible to deny the fact.","その事実を否定することは不可能だと思う。","deny"];
EXAMPLES[2764]=["He is a valuable acquisition to our company.","彼は会社にとって重要な人材だ。","valuable"];
EXAMPLES[2765]=["There is no such a thing as a comprehensive textbook.","すべてを網羅した教科書など存在しない。","comprehensive"];
EXAMPLES[2766]=["But you have saved the best till now.","だが、あなたは良いぶどう酒をよくも今までとっておきました。","till"];
EXAMPLES[2767]=["Properly listen to what I'm going to say.","話は最後までちゃんと聞きなさい。","Properly"];
EXAMPLES[2768]=["Mr Smith is vulnerable to this kind of criticism.","スミス氏はこの種の批判に弱い。","vulnerable"];
EXAMPLES[2769]=["Why not talk to her about it directly?","なぜ、彼女に直接言わないの。","directly"];
EXAMPLES[2770]=["Smokers are asked to occupy the rear seats.","たばこをお吸いの方は後部座席にお坐り下さい。","occupy"];
EXAMPLES[2771]=["Tastes in music vary from person to person.","音楽における好みは人によって異なる。","vary"];
EXAMPLES[2772]=["My sister fixed me with an angry stare.","姉は怒った目で僕を睨み付けた。","stare"];
EXAMPLES[2773]=["I lost my son about a decade ago.","私は息子を約十年前に亡くした。","decade"];
EXAMPLES[2774]=["The armed forces occupied the entire territory.","軍部は全領土を占領した。","armed"];
EXAMPLES[2775]=["I was forced to submit to my fate.","私は運命に服従せざるを得なかった。","fate"];
EXAMPLES[2776]=["I could not convince him of his mistake.","わたしは彼に彼の誤りを悟らせる事ができなかった。","convince"];
EXAMPLES[2777]=["The police were able to find the criminal.","警察は犯人を見つけ出す事ができた。","criminal"];
EXAMPLES[2778]=["The government of the country is now stable.","その国の政府は安定している。","stable"];
EXAMPLES[2780]=["Isaac was a leader of the Jewish people.","イサクはユダヤ人の指導者であった。","Jewish"];
EXAMPLES[2781]=["He was elected to the Senate in the last election.","彼は前回の選挙で上院議員に当選した。","Senate"];
EXAMPLES[2782]=["I don't want to hide from you anymore.","もう、君を避けたくないんだ。","hide"];
EXAMPLES[2783]=["He is now on the way to recovery.","彼は今は回復に向かっている。","recovery"];
EXAMPLES[2784]=["There is a strong bond between the brothers.","その兄弟の間には強い絆がある。","bond"];
EXAMPLES[2785]=["The portrait of her was true to life.","彼女の肖像画は本物そっくりだった。","portrait"];
EXAMPLES[2787]=["Your principles are not consistent with your actions.","君の信条は行為と一致していない。","consistent"];
EXAMPLES[2788]=["Tom used to be a private investigator in Boston.","トムは以前、ボストンで私立探偵をしていた。","investigator"];
EXAMPLES[2789]=["This is the time he normally arrives.","この時間にいつも彼はきます。","normally"];
EXAMPLES[2790]=["I thought that meeting would never conclude.","その会合は決して終わらないだろうと私は思った。","conclude"];
EXAMPLES[2791]=["I have a desire to go to England.","わたしはイギリスへ行きたい。","desire"];
EXAMPLES[2792]=["You must respond at once to the letter.","あなたはその手紙にすぐ返事を書く必要がある。","respond"];
EXAMPLES[2793]=["The newspaper alleged his involvement in the crime.","その新聞は彼の犯罪への掛かり合いを主張した。","involvement"];
EXAMPLES[2794]=["He had an interview with the Prime Minister.","彼は首相にインタビューした。","Minister"];
EXAMPLES[2795]=["Apparently, they're trying to patch up their marriage.","見たところ、彼らは結婚の危機を修復しようとしている。","patch"];
EXAMPLES[2796]=["They made him the chairman of a club.","彼らは彼をクラブの会長にした。","chairman"];
EXAMPLES[2797]=["We find diverse ethnic and economic interests here.","ここでは多様な民族的・経済的利害関係がみられる。","ethnic"];
EXAMPLES[2798]=["The child was sleeping on its mothers lap.","子供が母のひざのうえで眠っていた。","lap"];
EXAMPLES[2799]=["Refer to the dictionary as often as possible.","できるだけ頻繁に辞書を引きなさい。","Refer"];
EXAMPLES[2800]=["The roof is really in need of repair.","屋根をぜひ修理する必要がある。","repair"];
EXAMPLES[2801]=["The current king is present at the party.","今の国王が会合に出席されている。","current"];
EXAMPLES[2802]=["Tom is obviously very good with his hands.","トムは言うまでもなくとても手先が器用だ。","obviously"];
EXAMPLES[2803]=["I saw a spider walking on the ceiling.","私は蜘蛛が天井をはっているのを見た。","ceiling"];
EXAMPLES[2804]=["Who was the greatest philosopher that ever lived?","これまでの哲学者で最も偉大な人はだれであったか。","philosopher"];
EXAMPLES[2805]=["I heard there were many double suicides in Sonezaki.","曽根崎には心中が多いと聞きました。","suicides"];
EXAMPLES[2806]=["He is a man of high social status.","彼は身分の高い人です。","social"];
EXAMPLES[2807]=["We will take it to the potential customers.","顧客候補に渡します。","potential"];
EXAMPLES[2808]=["She had only a small sum of money.","彼女は小額の金しか持っていなかった。","sum"];
EXAMPLES[2809]=["I have a rough idea where it is.","それがどこにあるのか、およその見当はついている。","rough"];
EXAMPLES[2810]=["Let us turn now to the fundamental issue.","それでは根本的な問題を見てみることにしましょう。","fundamental"];
EXAMPLES[2811]=["My association with him did not last long.","彼とのつきあいは長く続かなかった。","association"];
EXAMPLES[2812]=["I did not yield to such a rule.","私はそのような規則に従わなかった。","yield"];
EXAMPLES[2813]=["He is not a politician but a lawyer.","彼は政治家でなく弁護士です。","politician"];
EXAMPLES[2814]=["He is the manager of the marketing department.","彼は営業部の部長です。","department"];
EXAMPLES[2815]=["Place a coin in the palm of his hand.","彼の手のひらに硬貨を置く。","palm"];
EXAMPLES[2816]=["The phenomenon is typical of our modern era.","その現象は今の時代に特有のものだ。","phenomenon"];
EXAMPLES[2817]=["He was not about to admit his mistake.","彼は頑として自分の間違いを認めようとしなかった。","admit"];
EXAMPLES[2818]=["The sick boy is in a critical condition.","病気の少年は危篤状態だ。","critical"];
EXAMPLES[2819]=["I have a sore throat from a cold.","風邪でのどが痛い。","throat"];
EXAMPLES[2820]=["Can you adapt yourself to the new job?","新しい仕事に適応できますか。","adapt"];
EXAMPLES[2821]=["My success is largely due to your help.","私の成功はおもにあなたの助力のおかげだ。","largely"];
EXAMPLES[2822]=["He is sure to succeed in the attempt.","彼はきっとその企てに成功するだろう。","attempt"];
EXAMPLES[2823]=["I think Tom was impressed with your work.","トムはあなたの仕事に感銘を受けていたと思いますよ。","impressed"];
EXAMPLES[2824]=["He had to submit himself to their decision.","彼は彼らの決定に従うほかなかった。","submit"];
EXAMPLES[2825]=["I'm bored and I have nothing to do.","退屈で何もすることがない。","bored"];
EXAMPLES[2826]=["The river furnishes electric power to the town.","その川は町に電力を供給する。","electric"];
EXAMPLES[2827]=["You could try and be a bit more civilized.","もうちょっと上品にできないの。","civilized"];
EXAMPLES[2828]=["Combat soldiers during peaceful moments like to reminisce of their halcyon days.","戦闘に携わる兵士たちは戦闘が止んでいるときに好んで、平穏無事な時代を想い返す。","Combat"];
EXAMPLES[2829]=["The world is on the edge of destruction.","世界は破滅の淵に立たされている。","destruction"];
EXAMPLES[2830]=["I'll remain your ally no matter what happens.","私は何が起こっても君の味方だ。","ally"];
EXAMPLES[2832]=["Do you take me for a complete beginner?","あなたは私をまったくの初心者と思っているのか。","complete"];
EXAMPLES[2833]=["That made the problem all the more complicated.","そのために問題はますます複雑になった。","complicated"];
EXAMPLES[2834]=["He was good and mad by that time.","彼はその時までにすっかり頭にきていた。","mad"];
EXAMPLES[2835]=["In a word, you hate me, don't you?","要するに君は私が嫌いなんだね。","hate"];
EXAMPLES[2836]=["The inhabitants are proud of their urban culture.","住民達は彼らの都会的な文化に誇りを持っている。","urban"];
EXAMPLES[2837]=["He has a bad reputation with his students.","彼は生徒に評判が良くない。","reputation"];
EXAMPLES[2838]=["The first phase of construction has been completed.","建設工事の第一段階は終わった。","phase"];
EXAMPLES[2839]=["I give myself to the study of philosophy.","私は哲学の研究に専念する。","philosophy"];
EXAMPLES[2840]=["The picture will finish shooting in three days.","撮影は３日間でクランクアップします。","shooting"];
EXAMPLES[2841]=["The air is a medium for sound.","空気は音の媒体だ。","medium"];
EXAMPLES[2842]=["The professor is familiar with contemporary literature.","その教授は現代文学に詳しい。","contemporary"];
EXAMPLES[2843]=["She stood in the court before judge and jury.","彼女は法廷に判事と陪審員の前にたった。","jury"];
EXAMPLES[2844]=["I was very surprised at the huge fish.","私はそのものすごく大きな魚に大変驚いた。","huge"];
EXAMPLES[2845]=["It was an awful day for me too.","私も最悪な日だった。","awful"];
EXAMPLES[2846]=["I am to examine the papers once more.","私はもう一度その書類を調べなければいけません。","examine"];
EXAMPLES[2847]=["I am out of my element in math.","私は数学は苦手だ。","element"];
EXAMPLES[2848]=["My success was mainly due to your help.","私が成功したのは主にあなたの援助のためであった。","mainly"];
EXAMPLES[2849]=["I was searching for something that didn't exist.","私は、なかった物を探していた。","exist"];
EXAMPLES[2850]=["I never have had occasion to use it.","今までそれを使う機会がなかった。","occasion"];
EXAMPLES[2851]=["The girl begged her mother to accompany her.","娘は母親に同行して欲しいと頼んだ。","accompany"];
EXAMPLES[2852]=["Unemployment in this part of the country is virtually nonexistent.","この地域の失業はほぼないに等しい。","virtually"];
EXAMPLES[2853]=["I have to withdraw some cash from the bank.","銀行でお金をおろさなくちゃ。","withdraw"];
EXAMPLES[2854]=["The more leisure he has, the happier he is.","暇な時間が多ければ多いほど、それだけ彼は楽しい。","leisure"];
EXAMPLES[2855]=["All the students recognized her as their representative.","学生全員が彼女を自分達の代表と認めた。","representative"];
EXAMPLES[2856]=["The mass of people are against the plan.","大多数の人々はその計画に反対である。","mass"];
EXAMPLES[2857]=["What do his words imply?","彼の言葉は何を暗示しているのか。","imply"];
EXAMPLES[2858]=["Mixture of the three primary colors creates black.","三原色を混合すると黒色ができる。","Mixture"];
EXAMPLES[2859]=["He is aware that the work is difficult.","彼はその仕事が困難であることを承知している。","aware"];
EXAMPLES[2860]=["He appointed John to act as his deputy.","彼はジョンにかわりを務めるように命じた。","deputy"];
EXAMPLES[2861]=["Relative to overall sales, that of software is insignificant.","売り上げ全体から見れば、ソフトウェアのは重要でない。","overall"];
EXAMPLES[2862]=["That was the last roll of toilet paper.","最後のトイレットペーパだったのに。","roll"];
EXAMPLES[2863]=["I caught cold from exposure to the night fog.","夜霧に当たって風邪をひいた。","exposure"];
EXAMPLES[2864]=["The new term starts in April in Japan.","日本では新学期は４月から始まる。","term"];
EXAMPLES[2865]=["What is the main industry in this town?","この町の主な産業は何ですか。","industry"];
EXAMPLES[2866]=["Now I am a teacher, I think otherwise.","先生になった今はそう考えない。","otherwise"];
EXAMPLES[2867]=["He is proud that he is an artist.","彼は芸術家であることを自慢している。","proud"];
EXAMPLES[2868]=["The task is of great importance to them.","その仕事は彼らにとってとても重要だ。","task"];
EXAMPLES[2869]=["Even a small sound from the TV interferes with my concentration.","テレビからの小さい音でさえ、私の集中力を妨げる。","concentration"];
EXAMPLES[2870]=["I suggest you keep out of this.","あなたはこのことには興味をもたないようにしてください。","suggest"];
EXAMPLES[2871]=["We derive a lot of pleasure from books.","私達は本から大きな喜びを得る。","derive"];
EXAMPLES[2872]=["My mother told me to mow the lawn.","母は私に芝を刈るように言った。","lawn"];
EXAMPLES[2873]=["Please compose a draft of the proposal idea.","提案書をまとめて下さい。","compose"];
EXAMPLES[2874]=["How did he react to the bad news?","彼はその悪い知らせにどんな反応を示しましたか。","react"];
EXAMPLES[2875]=["You will progress in proportion to your abilities.","君は能力にしたがって上達する。","proportion"];
EXAMPLES[2876]=["I am confident he will keep his promise.","私は彼が約束を守ることを確信している。","confident"];
EXAMPLES[2877]=["They are manufacturing TV sets in this factory.","この工場ではテレビ受像機を製造しています。","manufacturing"];
EXAMPLES[2878]=["There was a multiple collision on the highway.","高速道路では多数の衝突があった。","multiple"];
EXAMPLES[2879]=["I have a sharp pain in my chest.","胸がひどく痛みます。","chest"];
EXAMPLES[2880]=["He is a recognized authority on the subject.","彼はその道の大家です。","authority"];
EXAMPLES[2881]=["I'm just a creature of habit, I guess.","どうしても習慣から抜けきれないんだよなあ。","creature"];
EXAMPLES[2882]=["I swear on my life that it's true!","本当だよ。命をかけて、誓うよ！","swear"];
EXAMPLES[2883]=["The interior of the house was very attractive.","その家の内部はとても魅力的だった。","attractive"];
EXAMPLES[2884]=["They came to terms with the union leaders.","彼らは組合の指導者たちと折り合った。","union"];
EXAMPLES[2885]=["The prisoner asked for a piece of cake.","囚人は一かけらのケーキを乞うた。","prisoner"];
EXAMPLES[2886]=["He had the courage to expose the scandal.","彼は勇敢にもそのスキャンダルを暴露した。","expose"];
EXAMPLES[2887]=["Therefore, it is necessary to reduce the cost.","したがって生産費を削る必要がある。","Therefore"];
EXAMPLES[2888]=["The prosecutor asked me a leading question.","検事は誘導尋問をした。","prosecutor"];
EXAMPLES[2889]=["I have a nice present to give you.","君にいい贈り物をあげましょう。","present"];
EXAMPLES[2890]=["The book is now ready for publication.","本は現在出版の準備が出来ている。","publication"];
EXAMPLES[2891]=["She found it dull living in the country.","彼女は田舎暮らしが退屈だと思った。","dull"];
EXAMPLES[2892]=["The situation has taken on a new aspect.","情勢は新しい局面を呈した。","aspect"];
EXAMPLES[2893]=["The judge in the case was not fair.","その訴訟の判事は公平ではなかった。","fair"];
EXAMPLES[2894]=["I'd like to return to Tokyo via Honolulu.","ホノルル経由で東京に帰りたいのですが。","via"];
EXAMPLES[2895]=["They say that he will run for mayor.","彼は市長に立候補するそうだ。","mayor"];
EXAMPLES[2896]=["The judgement is very fair to both parties.","その判断は双方に対して大変公正なものである。","judgement"];
EXAMPLES[2897]=["The fact is apparent to the most casual observer.","この事実はどんなぼんやり者にも明白だ。","observer"];
EXAMPLES[2898]=["The pen is the tongue of the soul.","ペンは魂の舌である。","tongue"];
EXAMPLES[2899]=["The decision was in favor of the defendant.","判決は被告に有利だった。","defendant"];
EXAMPLES[2900]=["The components obtained by distillation of coal tar are as shown below.","コールタールを蒸留して得られる成分名は下表の通りである。","components"];
EXAMPLES[2901]=["Do you have something to declare?","何か申告するものはありますか。","declare"];
EXAMPLES[2902]=["He is really putting the squeeze on me.","彼は私に猛烈な圧力をかけています。","squeeze"];
EXAMPLES[2903]=["My income is barely enough to maintain living.","私の収入では生きていくのがやっとだ。","maintain"];
EXAMPLES[2904]=["This world is but a place of passage.","この世は仮の宿に過ぎない。","passage"];
EXAMPLES[2905]=["We were all shaking from the bitter cold.","われわれは皆ひどい寒さに震えていた。","bitter"];
EXAMPLES[2906]=["That is the man whom I know well.","あれは私がよく知っている人です。","whom"];
EXAMPLES[2907]=["They split up after a year of marriage.","結婚して一年で別れてしまった。","split"];
EXAMPLES[2908]=["Who do you think is the most capable?","誰が一番有能だと思いますか。","capable"];
EXAMPLES[2909]=["It is said that he also invented concrete.","彼はコンクリートも発明したと言われている。","concrete"];
EXAMPLES[2910]=["She had a choice of going or remaining.","彼女は行くか残るかどちらかだった。","remaining"];
EXAMPLES[2911]=["He was no longer dependent on his parents.","彼はもはや両親には頼っていなかった。","dependent"];
EXAMPLES[2912]=["He knows better than to argue with her.","彼は彼女と論議するほどばかではない。","argue"];
EXAMPLES[2913]=["The consequence was that she lost her job.","その結果、彼女は、職を失うこととなった。","consequence"];
EXAMPLES[2914]=["Whatever the outcome, you must meet the challenge.","どんな結果になろうとも挑戦は受けなければならない。","outcome"];
EXAMPLES[2915]=["A cultural heritage is handed down to posterity.","文化遺産は後世に伝えられる。","heritage"];
EXAMPLES[2916]=["How long adolescence continues is determined by biological factors.","青春期がどのくらい長く続くかは生物学的要因によって決る。","biological"];
EXAMPLES[2917]=["That voter, Mary Johnson, turned out to be a Democrat.","その有権者はメアリー・ジョンソンさんで、民主党員であることが後になってわかりました。","voter"];
EXAMPLES[2918]=["I remarked on the beauty of the landscape.","私は、風景の美しさについて、述べた。","landscape"];
EXAMPLES[2919]=["I am occasionally mistaken for being a woman.","俺たまに女子って勘違いされることあるんだよね。","occasionally"];
EXAMPLES[2920]=["The method was too expensive to be practical.","その方法は高くつきすぎて実用的でなかった。","practical"];
EXAMPLES[2921]=["Would you like me to wipe your body?","体をふいてあげましょうか。","wipe"];
EXAMPLES[2922]=["I have nothing to do with the affair.","私はその事件とは無関係である。","affair"];
EXAMPLES[2923]=["He was too proud to accept any reward.","報酬を受け取るのを彼のプライドが許さなかった。","reward"];
EXAMPLES[2924]=["I gather information about the quality of goods.","私は商品の質についての情報を集めています。","gather"];
EXAMPLES[2925]=["I think I will advertise in the paper.","新聞に広告を出してみよう。","advertise"];
EXAMPLES[2926]=["Eventually, I want to start my own company.","ゆくゆくは自分の会社を立ち上げようと思っています。","Eventually"];
EXAMPLES[2927]=["Being silent is regarded in effect as approval.","黙っていると事実上の承認とみなされます。","approval"];
EXAMPLES[2928]=["There are many commercial firms in New York.","ニューヨークにはたくさんの商社がある。","commercial"];
EXAMPLES[2929]=["This medicine doesn't have any harmful side effects.","この薬には有害な副作用がありません。","harmful"];
EXAMPLES[2930]=["Would you allow me to make a suggestion?","提案させてもらってもいいですか？","suggestion"];
EXAMPLES[2931]=["The picture is colorful in contrast with this one.","その絵はこの絵とは対照的にカラフルだ。","contrast"];
EXAMPLES[2932]=["The general commanded him to report to headquarters.","将軍は彼に司令部へ出頭しろと命じた。","headquarters"];
EXAMPLES[2933]=["My grandfather still endeavors to absorb new ideas.","祖父は今でも新思想を吸収しようと努力しています。","absorb"];
EXAMPLES[2934]=["The committee will be opposed to the proposal.","委員会はその提案に反対するだろう。","proposal"];
EXAMPLES[2935]=["The biologist is proud of his historic discovery.","その生物学者は自分の歴史的な発見を誇りに思っている。","historic"];
EXAMPLES[2936]=["I can not give you an immediate answer.","早速には返事をしかねます。","immediate"];
EXAMPLES[2937]=["Do you believe in the existence of God?","神の存在を信じますか。","existence"];
EXAMPLES[2938]=["First of all, we must dismiss the cook.","まず第一に私たちはその料理人を解雇しなければならない。","dismiss"];
EXAMPLES[2939]=["India has a cuisine rich in regional flavour.","インドは地域色豊かな食文化があります。","regional"];
EXAMPLES[2940]=["Great effort was one factor in his success.","大変な努力が彼の成功の一因であった。","factor"];
EXAMPLES[2941]=["He is a constant torment to me.","彼はいつだって私の悩みの種だ。","constant"];
EXAMPLES[2942]=["Nothing has resulted from her prayer.","彼女の祈りから何も起こらなかった。","prayer"];
EXAMPLES[2943]=["Would you agree to the plan in principle?","その計画に大すじで賛成していただけませんか。","principle"];
EXAMPLES[2944]=["He fought bravely in behalf of a cause.","彼は主義のために勇敢に戦った。","bravely"];
EXAMPLES[2945]=["This is moderately spicy, but it does stimulate the appetite.","この程よい辛さが、食欲を掻き立てる。","stimulate"];
EXAMPLES[2946]=["Remind me that the meeting is on Monday.","忘れないように会合は月曜日であるということを私に言って下さい。","Remind"];
EXAMPLES[2947]=["There is not even a semblance of proof.","証拠らしいものさえない。","proof"];
EXAMPLES[2948]=["That was not at all an appropriate remark.","あれはどうも適切な発言ではなかった。","appropriate"];
EXAMPLES[2949]=["The honor is more than I deserve.","それは身に余る光栄でございます。","deserve"];
EXAMPLES[2950]=["The reformers were subject to every attack from the Establishment.","改革者たちは支配層からのあらゆる非難にさらされた。","Establishment"];
EXAMPLES[2951]=["Can you give me the definition of a cone?","円錐形の定義を教えてくれませんか。","definition"];
EXAMPLES[2952]=["The country is in a bad economic state.","その国の経済状態は悪い。","economic"];
EXAMPLES[2953]=["His words convey nothing at all to me.","彼の言うことは私には何のことかさっぱりわからない。","convey"];
EXAMPLES[2954]=["I went into partnership with him.","私は彼と協力した。","partnership"];
EXAMPLES[2955]=["Why don't you consult an attorney in person?","直接自分で弁護士に相談したほうがいいんではない。","attorney"];
EXAMPLES[2956]=["Is there an index to the book?","その本には索引がついていますか。","index"];
EXAMPLES[2957]=["I cannot come back in the current circumstances.","帰るわけには行かないのです。","circumstances"];
EXAMPLES[2958]=["He has a lot of topics for conversation.","彼は話題の豊富な人だ。","conversation"];
EXAMPLES[2959]=["We must hand down our craft to posterity.","我々は技術を後世に伝えなければならない。","craft"];
EXAMPLES[2960]=["I am afraid he is going to spill the beans.","彼はなんでもしゃべってしまいそうです。","spill"];
EXAMPLES[2961]=["I do not want to reject this claim.","この訴えを退けたくはない。","reject"];
EXAMPLES[2962]=["The province is relatively rich in mineral resources.","その州は鉱物資源が比較的豊富だ。","province"];
EXAMPLES[2963]=["Admission to the show is by ticket only.","芝居にはきっぷを持っている人だけ入れます。","Admission"];
EXAMPLES[2964]=["In general, people were against the consumption tax.","概して人々は消費税に反対だった。","consumption"];
EXAMPLES[2965]=["The bishop took pity on the desperate immigrants.","宗教は、自暴自棄になった移民達を哀れんで助けを与えた。","bishop"];
EXAMPLES[2966]=["What is the fuel mileage of this car?","この車の燃費はどれくらいですか。","fuel"];
EXAMPLES[2967]=["What do you think about the Japanese economy?","日本の経済についてどう思いますか。","economy"];
EXAMPLES[2968]=["I will construct a wooden building.","私は木の建物を造る。","construct"];
EXAMPLES[2969]=["Can I be of any assistance to you?","あなたの助力になれるでしょうか。","assistance"];
EXAMPLES[2970]=["These implements are in common use.","これらの道具は一般に用いられている。","implements"];
EXAMPLES[2971]=["The morning rush is at its peak now.","朝のラッシュは今がピークだ。","peak"];
EXAMPLES[2972]=["The city holds an ice sculpture festival each year.","街では毎年、氷彫刻の祭典が開催されます。","sculpture"];
EXAMPLES[2973]=["We can apply the discovery to various uses.","その発見はいろいろな用途に応用できる。","various"];
EXAMPLES[2974]=["Is this the first time you've had this symptom?","この症状が出たのは初めてですか。","symptom"];
EXAMPLES[2975]=["Members of that tribe settled along the river.","その部族の民はその川沿いに住み着いた。","tribe"];
EXAMPLES[2976]=["The government should invest more money in agriculture.","政府は農業にもっと投資するべきだ。","agriculture"];
EXAMPLES[2977]=["The dealer wants to sell a car.","ディーラーは車を売りたがっている。","dealer"];
EXAMPLES[2978]=["It is unlike him to be late.","遅刻するなんて彼らしくない。","unlike"];
EXAMPLES[2979]=["War broke out when the treaty was ignored.","条約が無視されたときに、戦争が始まった。","treaty"];
EXAMPLES[2980]=["I like to see comedy in the theater.","私は劇場で喜劇を見るのが好きだ。","comedy"];
EXAMPLES[2981]=["I have absolutely nothing to do with that.","それはまったく関係ないです。","absolutely"];
EXAMPLES[2982]=["He argued for our forming the alliance with that nation.","彼は我が国がその国と同盟を結ぶのに賛成すべきだと論じた。","alliance"];
EXAMPLES[2983]=["A baby does not know good or evil.","赤ん坊は善悪について何も知らない。","evil"];
EXAMPLES[2984]=["Under the Constitution, the lower chamber's resolutions override those of the upper chamber.","憲法の規定に従い衆院の議決が参院に優越する。","chamber"];
EXAMPLES[2985]=["Suppose it were true; what would you do?","もしそれが本当ならどうしますか。","Suppose"];
EXAMPLES[2986]=["We need to develop a new kind of energy.","新しいエネルギーを開発しなくてはならない。","develop"];
EXAMPLES[2987]=["I am not entitled to comment on this.","私はこのことにコメントする資格はない。","entitled"];
EXAMPLES[2988]=["However, when droughts arise, lake levels can drop significantly.","ただし、干ばつの時期には湖の水位が大幅に低くなる可能性があります。","significantly"];
EXAMPLES[2989]=["I have confidence in your ability to win.","私はあなたは絶対勝つことができると信じています。","confidence"];
EXAMPLES[2990]=["Come and see me whenever you want to.","いつでも来て下さい。","whenever"];
EXAMPLES[2991]=["He is used to eating in a rush.","彼は急いで食べることに慣れている。","rush"];
EXAMPLES[2992]=["My boyfriend has a lot of female friends.","私の彼ね、女友達が多いのよ。","female"];
EXAMPLES[2993]=["The mayor provided me with an identity card.","市長は私に身分証明書をくれた。","identity"];
EXAMPLES[2994]=["I am studying it in cooperation with them.","私は彼らと共同してそれを研究している。","cooperation"];
EXAMPLES[2995]=["Do you think there'll be a grand coalition?","大連立になると思う？","coalition"];
EXAMPLES[2996]=["The computer can detect 200 types of error.","そのコンピューターは２００種類の間違いを探せる。","detect"];
EXAMPLES[2997]=["He made over the interior of his house.","彼は家の内装を変えた。","interior"];
EXAMPLES[2998]=["How long does it take to alter it?","直すのに、どのくらい時間がかかりますか。","alter"];
EXAMPLES[2999]=["At our company, the retirement age is 60.","私の会社では６０歳が定年である。","retirement"];
EXAMPLES[3000]=["My eyes are very sensitive to the light.","目が光に対してすごく敏感なのです。","sensitive"];
EXAMPLES[3001]=["His reply was short and to the point.","彼の返答は簡単で要領を得ていた。","reply"];
EXAMPLES[3002]=["The government tried to suppress all opposition parties.","政府はすべての野党を抑圧しようとした。","opposition"];
EXAMPLES[3003]=["The export of arms was not allowed.","武器の輸出は禁止されていた。","export"];
EXAMPLES[3004]=["Tom is not an M.D. but a psychologist.","トムは医者じゃなくて心理学者だ。","psychologist"];
EXAMPLES[3005]=["The pension is not sufficient for living expenses.","その年金では生活費に足りない。","pension"];
EXAMPLES[3006]=["He was sent abroad as a correspondent.","彼は特派員として海外に派遣された。","correspondent"];
EXAMPLES[3007]=["I felt it my duty to do so.","私はそうすることが自分の努めだと思った。","duty"];
EXAMPLES[3008]=["You must attach this label to your suitcase.","このステッカーをスーツケースに貼り付けないといけません。","attach"];
EXAMPLES[3009]=["Recognize and respect the personality of a person.","人の人格を認め尊重する。","personality"];
EXAMPLES[3010]=["The Diet is not fully functioning as such.","国会は本来の機能を十分には果たしてはいない。","fully"];
EXAMPLES[3011]=["They were at the bottom of the scheme.","彼らがその陰謀の黒幕であった。","scheme"];
EXAMPLES[3012]=["The man tried to install his own antenna.","その男はアンテナを取り付けようとした。","install"];
EXAMPLES[3013]=["Flour is the main ingredient in cakes.","小麦粉はケーキの主な材料だ。","ingredient"];
EXAMPLES[3014]=["The people were evacuated because of the flood.","大水のため人々は立ち退いた。","flood"];
EXAMPLES[3015]=["I don't like all of these folk songs.","私はこれらのフォークソングすべてが好きというわけではない。","folk"];
EXAMPLES[3016]=["Who did you vote for in the election?","あなたは選挙で誰に投票しましたか。","election"];
EXAMPLES[3017]=["The party set out despite the bad weather.","一行は悪天候にもかかわらず出発した。","despite"];
EXAMPLES[3018]=["He played an active part in the revolution.","彼はその革命で積極的な役割をした。","revolution"];
EXAMPLES[3019]=["You are the next in line for promotion.","君は次の昇任予定者です。","promotion"];
EXAMPLES[3020]=["The Industrial Revolution took place first in England.","産業革命は最初イギリスに起こった。","Industrial"];
EXAMPLES[3021]=["Don't take that dramatic attitude all of a sudden.","急に芝居がかった態度をとるな。","dramatic"];
EXAMPLES[3022]=["He is as lean as a wolf.","彼はオオカミのように痩せている。","lean"];
EXAMPLES[3023]=["The committee picked the site for the exhibition.","委員長は博覧会の会場を見つけた。","exhibition"];
EXAMPLES[3024]=["There seems to be no possibility of compromise.","妥協の可能性はないように思える。","compromise"];
EXAMPLES[3025]=["I am full of anxiety about the future.","将来の事が心配でたまらない。","anxiety"];
EXAMPLES[3026]=["Your question is not relevant to the subject.","君の質問は当面の話題とは関係がない。","relevant"];
EXAMPLES[3027]=["A careful observation will show you the difference.","注意深く観察すれば違いがわかるでしょう。","observation"];
EXAMPLES[3028]=["The chances of victory or defeat are even.","勝ち負けの確率は五分五分だ。","defeat"];
EXAMPLES[3029]=["My father is going to have surgery.","父は手術を受ける事になっている。","surgery"];
EXAMPLES[3030]=["What was her reaction to the news?","このニュースに対する彼女の反応はどうでしたか。","reaction"];
EXAMPLES[3031]=["The crew had to abandon the sinking ship.","乗組員は沈みかけている船を離れなければならなかった。","abandon"];
EXAMPLES[3032]=["People are saying that the crisis is over.","人々が危機は去ったと言っています。","crisis"];
EXAMPLES[3033]=["His salary enables him to live in comfort.","彼は快適な生活のできる給料をもらっている。","comfort"];
EXAMPLES[3034]=["It was wise of you not to go.","行かなくてきみは賢明だった。","wise"];
EXAMPLES[3035]=["Heavy posts are needed to sustain this bridge.","この橋を支えるには重い柱が必要だ。","sustain"];
EXAMPLES[3036]=["If you are honest, I will hire you.","君が正直なら雇おう。","hire"];
EXAMPLES[3037]=["I was guilty of a slip of memory.","私は記憶違いをしていた。","slip"];
EXAMPLES[3038]=["She did it entirely of her own accord.","彼女はそれをまったく自発的にやった。","entirely"];
EXAMPLES[3039]=["I totally agree with you on that point.","その点では、君の意見に100%賛成するよ。","totally"];
EXAMPLES[3040]=["Extensive reading is as important as intensive reading.","多読は精読と同様重要である。","Extensive"];
EXAMPLES[3041]=["What do these dots represent on the map?","地図上のこの点々は何を表しているのですか。","represent"];
EXAMPLES[3042]=["The company has unofficially decided to employ me.","就職が内定した。","employ"];
EXAMPLES[3043]=["I'm getting the hang of this new machine.","この新しい機械の使い方がわかりかけてきたところです。","hang"];
EXAMPLES[3044]=["Get the meaning of a word from its context.","文の前後関係から単語の意味を知る。","context"];
EXAMPLES[3045]=["She put on an assumption of ignorance.","彼女はそ知らぬ顔をした。","assumption"];
EXAMPLES[3046]=["The Middle East is the cradle of civilization.","中東は文明の発祥地である。","civilization"];
EXAMPLES[3047]=["The countries should aid the countries much more.","先進国は発展途上国をもっと援助すべきだ。","aid"];
EXAMPLES[3048]=["The result of the poll will be known soon.","投票結果はもうすぐわかるだろう。","poll"];
EXAMPLES[3049]=["There is no scientific basis for these claims.","これらの主張には科学的な根拠がない。","scientific"];
EXAMPLES[3050]=["Tom was the architect that designed that building.","トムは建築士で、あの建物の設計をした。","architect"];
EXAMPLES[3051]=["The company is located on the West Coast.","その会社は西海岸にあります。","Coast"];
EXAMPLES[3052]=["He wrote on the social evolution of Japan.","彼は日本の社会的発展について書いた。","evolution"];
EXAMPLES[3053]=["I cannot recall the words of the song.","私はその歌の歌詞を思い出すことができない。","recall"];
EXAMPLES[3054]=["Are you in agreement with the new law?","あなたはその新しい法律に賛成ですか。","agreement"];
EXAMPLES[3055]=["One of the areas most vulnerable to sandstorms was Dallam County.","ダラム郡は、砂嵐で最も大きな被害を受けやすい地域の一つでした。","County"];
EXAMPLES[3056]=["A flag is a symbol of the nation.","旗は国民のシンボルです。","nation"];
EXAMPLES[3057]=["His job is to negotiate with foreign buyers.","彼の仕事は外国の買い手と交渉することだ。","negotiate"];
EXAMPLES[3058]=["What is the depth of the lake?","湖の深さはどのくらいですか。","depth"];
EXAMPLES[3059]=["She will be the first Japanese woman astronaut.","彼女は日本初の宇宙飛行士となるだろう。","astronaut"];
EXAMPLES[3060]=["We thought his threat was only a joke.","彼の脅しは単なる冗談かと思った。","threat"];
EXAMPLES[3061]=["When I transform into a rabbit, I mercilessly hug people.","僕がウサギに変身してるときは、容赦なく人にハグするよ。","transform"];
EXAMPLES[3062]=["This is the least expensive method of all.","これがすべての中で一番費用のかからない方法です。","method"];
EXAMPLES[3063]=["Is it true that Tom is in jail?","トムが刑務所に入ってるって、本当なの？","jail"];
EXAMPLES[3064]=["Magic plays an important part in primitive society.","呪術は未開社会においては重要な役割をもつ。","primitive"];
EXAMPLES[3065]=["Japan is still struggling to emerge from recession.","日本は今も景気後退から立ち直ろうと努力を続けている。","emerge"];
EXAMPLES[3066]=["I want to do a little physical exercise.","少し体を動かしたいな。","physical"];
EXAMPLES[3067]=["He made a false statement to the police.","彼は警察に偽りの申し立てをした。","false"];
EXAMPLES[3068]=["Read the highlighted line out loud.","マーカー部分を声に出して読みなさい。","highlighted"];
EXAMPLES[3069]=["The actual cost was higher than the estimate.","実際にかかった費用は見積もりより高かった。","estimate"];
EXAMPLES[3070]=["There must be a rational explanation for this.","これには合理的な説明が必要だ。","rational"];
EXAMPLES[3071]=["She is very efficient in the secretarial work.","彼女は秘書としての仕事に非常に有能である。","efficient"];
EXAMPLES[3072]=["This initiative will be evaluated in the future.","この取り組みについては後年、評価されるだろう。","initiative"];
EXAMPLES[3073]=["The recommendation from my boss made all the difference.","課長からもらった推薦状が物を言った。","recommendation"];
EXAMPLES[3074]=["You will be paid according to your work.","働きに応じて支払われます。","according"];
EXAMPLES[3075]=["What was the implication of his remark?","彼の発言は含みとして何を言いたかったのですか。","implication"];
EXAMPLES[3076]=["She seldom goes to that sort of place.","彼女はめったにそんなところへ行かない。","seldom"];
EXAMPLES[3077]=["Is there a possibility that you are pregnant?","妊娠の可能性はありますか？","pregnant"];
EXAMPLES[3078]=["The impact of science on society is great.","社会に対する科学の影響は大きい。","society"];
EXAMPLES[3079]=["He went to the station out of breath.","彼は息を切らして駅に着いた。","breath"];
EXAMPLES[3080]=["The employer was quite taken by her charm.","雇い主は彼女の魅力に惹かれていた。","employer"];
EXAMPLES[3081]=["Commercial television is an effective medium for advertising.","商業テレビは広告の効果的な手段である。","advertising"];
EXAMPLES[3082]=["This hospital has a lot of new equipment.","この病院には新しい設備がいろいろ備わっている。","equipment"];
EXAMPLES[3083]=["There was a new addition to his family.","彼の家族が一人増えた。","addition"];
EXAMPLES[3084]=["The number of visible stars is very great.","目に見える星の数は無数です。","visible"];
EXAMPLES[3085]=["The decline can be traced to the 1950s.","その衰退はざっと１９５０年代までさかのぼる事が出来る。","decline"];
EXAMPLES[3086]=["A male friend of mine called me yesterday.","昨日、男友達から電話があったのよ。","male"];
EXAMPLES[3087]=["I will make a new suit for you.","お前に新しい洋服を作ってあげよう。","suit"];
EXAMPLES[3088]=["The latter half of the week was fine.","週の後半は天気が良かった。","latter"];
EXAMPLES[3089]=["Merely to breathe does not mean to live.","ただ呼吸しているだけでは生きていることにならない。","Merely"];
EXAMPLES[3090]=["You should not judge people by their appearance.","人を見かけで判断してはいけない。","appearance"];
EXAMPLES[3091]=["It fairly took time to explain the fact.","事実を説明するのにずいぶん時間がかかった。","fairly"];
EXAMPLES[3092]=["We'll deal with this problem in Chapter 3.","この問題は第3章で扱います。","Chapter"];
EXAMPLES[3093]=["I went to the store that was very nearby.","私は、すぐ近くの店に行った。","nearby"];
EXAMPLES[3094]=["I thought I could settle it by phone.","電話で済まそうと思いました。","settle"];
EXAMPLES[3095]=["The robots are sure to contribute to the world.","ロボットは必ずや世界に貢献するでしょう。","contribute"];
EXAMPLES[3096]=["I think that honesty is the best policy.","私は正直は最良の策だと思います。","policy"];
EXAMPLES[3097]=["You have to cope with those difficult problems.","君はそれらの難問題に対処しなくてはならない。","cope"];
EXAMPLES[3098]=["He has a good knowledge of Japanese religion.","彼は日本の宗教に精通している。","religion"];
EXAMPLES[3099]=["I have nothing to complain of the conclusion.","僕はその結論にまったく不満はありません。","conclusion"];
EXAMPLES[3100]=["She was none the better for the treatment.","彼女はその治療にもかかわらず少しも良くならなかった。","treatment"];
EXAMPLES[3101]=["We have the alternative of going or staying.","我々は行くかとどまるか２つに１つだ。","alternative"];
EXAMPLES[3102]=["He did the reverse of what I asked.","彼は私が頼んだことの逆をやった。","reverse"];
EXAMPLES[3103]=["I prefer the former plan to the latter.","はじめの計画のほうが後のより良いと思う。","former"];
EXAMPLES[3104]=["Who is the victim of the accident?","その事故の犠牲者はだれですか。","victim"];
EXAMPLES[3105]=["I can make a distinction between good and bad.","私にだって善悪に区別はつく。","distinction"];
EXAMPLES[3106]=["Tom was wearing a white lab coat.","トム、白衣を着てたよ。","lab"];
EXAMPLES[3107]=["She is a woman of great literary ability.","彼女は大変文才のある女性だ。","literary"];
EXAMPLES[3108]=["How many times do you feed the fish?","魚には何回えさをやっていますか。","feed"];
EXAMPLES[3109]=["The patient was operated on in the morning.","その患者は午前中に手術を受けたんだ。","patient"];
EXAMPLES[3110]=["You must state the fact as it is.","君はその事実をありのまま述べなければならない。","state"];
EXAMPLES[3111]=["A thing of beauty is a joy forever.","美しきものは永遠の喜びなり。","forever"];
EXAMPLES[3112]=["Is there no alternative to what you propose?","君の提案することのほかに方法はないのか。","propose"];
EXAMPLES[3113]=["Is Japan a pleasant place to live in?","日本って、住み心地がいい？","pleasant"];
EXAMPLES[3114]=["They are content with things as they are.","彼らは現状に満足している。","content"];
EXAMPLES[3115]=["He feels the prize to be the superior.","彼はその賞を最高の栄誉だと感じている。","superior"];
EXAMPLES[3116]=["The reason is they immediately pretend to know.","すぐ知ったかぶりをするんだから。","pretend"];
EXAMPLES[3117]=["This is a plant unique to this country.","これはこの国に特有の植物だ。","unique"];
EXAMPLES[3118]=["We failed due to a lack of preparation.","我々は準備不足で失敗した。","preparation"];
EXAMPLES[3119]=["We may not be able to afford it.","その余裕がないかもしれないから。","afford"];
EXAMPLES[3120]=["He came forward as a candidate for Congress.","彼は議員に自分から進んで立候補した。","Congress"];
EXAMPLES[3121]=["Do you have anything to say regarding this?","この件に関して、何か言いたいことはありますか？","regarding"];
EXAMPLES[3122]=["I had a good time at the party.","私はパーティーで楽しんだ。","party"];
EXAMPLES[3123]=["He claimed to be an expert in finance.","彼は財政の専門家であると自称した。","finance"];
EXAMPLES[3124]=["We are counting on you for financial help.","あなたの財政上の援助をあてにしています。","financial"];
EXAMPLES[3126]=["Can you describe the situation you were in?","あなたがいたときの状況を説明してくれませんか。","describe"];
EXAMPLES[3127]=["Do you know how to operate a computer?","コンピューターの操作の仕方を知ってますか。","operate"];
EXAMPLES[3128]=["Shall I stay like this until morning embracing you?","このまま朝までオマエを抱き寄せて過ごそうか。","embracing"];
EXAMPLES[3129]=["Charles always takes the line of least resistance.","チャールズはいつも一番容易な方法をとる。","resistance"];
EXAMPLES[3130]=["I buy the goods at $3 a dozen.","その品物を１ダースにつき３ドルで買う。","dozen"];
EXAMPLES[3131]=["I happened to witness the bullying in the corridor.","偶然、廊下でいじめを目撃した。","corridor"];
EXAMPLES[3132]=["He was determined, and we couldn't bend him.","彼は堅く決心をしていたので我々は彼を従わせることができなかった。","bend"];
EXAMPLES[3133]=["The mail is delayed because of the strike.","郵便がストで遅れているんです。","strike"];
EXAMPLES[3134]=["There were few colleges to educate women.","女性を教育する大学はほとんど無かった。","educate"];
EXAMPLES[3135]=["I reached into the pile and felt soft fabric.","私はその山に手を入れて柔らかい織物に触れた。","fabric"];
EXAMPLES[3136]=["Emma was much in evidence during the party.","パーティーの間中エマの存在は特に人目を引いた。","evidence"];
EXAMPLES[3137]=["We must concentrate our efforts on the desk.","その仕事に全努力を傾注しなければならない。","concentrate"];
EXAMPLES[3138]=["The industry is heavily dependent on government funding.","その産業は政府の資金援助に大きく依存している。","funding"];
EXAMPLES[3139]=["It was extraordinary that he did not come.","彼が来なかったとはとても変だ。","extraordinary"];
EXAMPLES[3140]=["No need for civilians to work hard.","国民が頑張る必要などない。","civilians"];
EXAMPLES[3141]=["His death was broadcast all over the world.","彼の死は世界中に放送された。","broadcast"];
EXAMPLES[3142]=["The maintenance of the house costs a lot.","その家の維持にはずいぶんとお金がかかる。","maintenance"];
EXAMPLES[3143]=["I don't have much faith in his ability.","私は彼の能力を大して信頼していない。","faith"];
EXAMPLES[3144]=["The father and his son were very alike.","その父親と息子は良く似ていた。","alike"];
EXAMPLES[3145]=["Please explain the grammar of'as may be'.","as may beの文法解釈を教えてください。","grammar"];
EXAMPLES[3146]=["Language is a vehicle of human thought.","言語は人間の思想を伝達手段である。","vehicle"];
EXAMPLES[3147]=["I am his friend and will remain so.","私は彼の友人です。そしていつまでもそうでしょう。","remain"];
EXAMPLES[3148]=["The community will benefit from the new industry.","この地方は新しい産業の恩恵を被ることになるだろう。","benefit"];
EXAMPLES[3149]=["The second sentence was about the same length.","２番目の文もちょうど同じくらいの長さだった。","length"];
EXAMPLES[3150]=["He's a carbon copy of his father.","彼は親父とそっくりだ。","carbon"];
EXAMPLES[3151]=["There was a provision in his will for his mistress.","彼の遺言書には、愛人を相続人とした条項が存在していた。","provision"];
EXAMPLES[3152]=["This video is not available in your region.","この動画はお住まいの地域ではご利用いただけません。","region"];
EXAMPLES[3153]=["It is beyond the boundary of human knowledge.","それは人知の範囲を超えている。","boundary"];
EXAMPLES[3154]=["My advice is to adopt a new line.","私の助言は新しい路線を採用することである。","adopt"];
EXAMPLES[3155]=["She had the wisdom to follow the custom.","彼女は賢明にもそこの、風習に従った。","wisdom"];
EXAMPLES[3156]=["Is there a better way to express this?","もっといい表現方法がありますか？","express"];
EXAMPLES[3157]=["One can't see through a brick wall.","煉瓦の壁は透かして見ることはできない。","brick"];
EXAMPLES[3158]=["Man is the lord of all creation.","人間は万物の霊長である。","creation"];
EXAMPLES[3159]=["He rose to his feet to greet me.","彼は私に挨拶するために立ちあがった。","greet"];
EXAMPLES[3160]=["Have you met the new family on the block?","近所に引っ越してきた家族にはもう会った？","block"];
EXAMPLES[3161]=["I will not let her escape this time.","今度こそは彼女を逃がさないぞ。","escape"];
EXAMPLES[3162]=["Where can I obtain a map of Europe?","どこへ行けばヨーロッパの地図が手に入りますか。","obtain"];
EXAMPLES[3163]=["The population of this country is gradually decreasing.","この国の人口はだんだん減っている。","gradually"];
EXAMPLES[3164]=["It is obvious that that is a lie.","嘘に決まってんじゃん。","obvious"];
EXAMPLES[3165]=["As far as I know, he is innocent.","私の知る限り、彼は無罪です。","innocent"];
EXAMPLES[3166]=["There is little, if any, of such distribution of control.","そのような分配された支配はほとんど存在しない。","distribution"];
EXAMPLES[3167]=["The town was exactly the same as before.","町は昔のままだった。","exactly"];
EXAMPLES[3168]=["Australia is the smallest continent in the world.","オーストラリアは世界で最も小さい大陸である。","continent"];
EXAMPLES[3169]=["He had a big box in his arms.","彼は両手に大きな箱を抱えていた。","arms"];
EXAMPLES[3170]=["The pain of the compound fracture was almost unbearable.","複雑骨折の痛みはほとんど耐え難かった。","compound"];
EXAMPLES[3171]=["The event has become known to the public.","その事件は明るみに出た。","public"];
EXAMPLES[3172]=["He has a keen awareness of the problem.","彼は明敏な問題意識をもっている。","awareness"];
EXAMPLES[3173]=["Please remove your shoes before entering the house.","靴を脱いでから家には入ってください。","remove"];
EXAMPLES[3174]=["He had a slight edge on his opponent.","彼は相手より少し優勢だった。","opponent"];
EXAMPLES[3175]=["I just happened to be in the neighborhood.","たまたま、近くにいたんです。","neighborhood"];
EXAMPLES[3176]=["The student council discussed plans for the graduation.","生徒会は卒業式の計画について話し合った。","council"];
EXAMPLES[3177]=["He is far from suitable for that job.","彼はあの仕事にはまったく不向きな人です。","suitable"];
EXAMPLES[3178]=["The secretary is within call all the time.","秘書はいつも声の届くところに待機しています。","secretary"];
EXAMPLES[3179]=["He was wise not to participate in it.","彼がそれに関与していないのは賢明だった。","participate"];
EXAMPLES[3180]=["I am not interested in politics at all.","私は政治には全く興味がありません。","politics"];
EXAMPLES[3181]=["He made an accurate report of the incident.","彼はその事件の正確な報告をした。","accurate"];
EXAMPLES[3182]=["You may as well chew your food well.","食べ物はよくかむほうがよい。","chew"];
EXAMPLES[3183]=["He made a few conventional remarks about the event.","彼はその出来事について型にはまった意見を２、３述べた。","conventional"];
EXAMPLES[3184]=["She has an important role in our organization.","彼女には私たちの団体での重要な役割があります。","organization"];
EXAMPLES[3185]=["He is in desperate search of further evidence.","彼はもっと証拠がないかと、やっきになって捜している。","desperate"];
EXAMPLES[3186]=["Did you understand the moral of this story?","この話の教訓がわかりましたか。","moral"];
EXAMPLES[3187]=["Besides being beautiful, she is kind and intellectual.","彼女は、美しいばかりでなく、心が優しく頭もよい。","intellectual"];
EXAMPLES[3188]=["He put too much emphasis on the matter.","彼はその問題を強調しすぎた。","emphasis"];
EXAMPLES[3189]=["I don't particularly want to see the game.","その試合をとくにみたいとも思わない。","particularly"];
EXAMPLES[3190]=["The hall was built in memory of the founder.","そのホールは創立者を記念して立てられたものだ。","founder"];
EXAMPLES[3191]=["We have to consider the problem more carefully.","この問題をもっと注意深く考えなければならない。","consider"];
EXAMPLES[3192]=["Human beings are emotional creatures, so to speak.","人間はいわば感情に左右される生き物である。","emotional"];
EXAMPLES[3193]=["The spread of the infection is very dangerous.","感染の広がりはとても危ないです。","infection"];
EXAMPLES[3194]=["Can you identify the man in this picture?","この写真の男性が誰だか分かりますか？","identify"];
EXAMPLES[3195]=["We need to reduce the demand for energy.","我々はエネルギーの需要を減らさなくてはならない。","demand"];
EXAMPLES[3196]=["Adolescence is viewed as time of transition.","青年期は移り変わりの時期と見られている。","transition"];
EXAMPLES[3197]=["The author of this book is still young.","この本の著者はまだ若い。","author"];
EXAMPLES[3198]=["He gave her a considerable sum of money.","彼は彼女にかなりの金額を与えた。","considerable"];
EXAMPLES[3199]=["We ask you to account for your conduct.","あなたの行為の責任をもってもらおう。","conduct"];
EXAMPLES[3200]=["I am told he has a broad back.","彼は寛大であると聞いている。","broad"];
EXAMPLES[3201]=["He is the physician I talked about yesterday.","彼はきのう私が話題にした医者です。","physician"];
EXAMPLES[3202]=["It is difficult for us to persuade him.","我々が彼を説得することはむずかしい。","persuade"];
EXAMPLES[3203]=["Great difficulties stand in the way of its achievement.","その達成には非常に困難なものが立ちふさがっている。","achievement"];
EXAMPLES[3204]=["He was the only witness of the accident.","彼はその事故のたった一人の目撃者だった。","witness"];
EXAMPLES[3205]=["The federal budget was narrowly approved by Congress.","連邦予算はかろうじて議会の承認を得た。","federal"];
EXAMPLES[3206]=["You must associate with people of good character.","性格の良い人と付き合うべきです。","associate"];
EXAMPLES[3207]=["What is the chief aim of this society?","この会の主な目的はなんですか。","aim"];
EXAMPLES[3208]=["He made up the deficit with a loan.","不足を借金で補充した。","deficit"];
EXAMPLES[3209]=["Activists are stepping up their protest drive.","活動家たちは反対運動を強めています。","Activists"];
EXAMPLES[3210]=["The disease is still in the primary stage.","病気はまだ初期の段階です。","primary"];
EXAMPLES[3211]=["The suspect told a lie to the inspector.","容疑者は捜査官にうそを言った。","inspector"];
EXAMPLES[3212]=["I feel that the previous one was cheaper.","前の方が安かった気がする。","previous"];
EXAMPLES[3213]=["Obviously there are many variations between these two extremes.","むろん、この両極端の間に多くのバリエーションがある。","variations"];
EXAMPLES[3214]=["The stupider the child, the more lovely.","馬鹿な子ほど可愛い。","stupider"];
EXAMPLES[3215]=["How many people are now living in poverty?","何人ぐらいの人々が、現在、貧困の中で生活しているのか。","poverty"];
EXAMPLES[3216]=["His music and words appeal to young people.","彼の音楽と言葉は若者に受ける。","appeal"];
EXAMPLES[3217]=["Tell me the substance of his speech.","彼のスピーチの主旨を教えてください。","substance"];
EXAMPLES[3218]=["We should do away with this regulation.","こんな規制は廃止すべきです。","regulation"];
EXAMPLES[3219]=["It is difficult to tell the bare facts.","ありのままの事実を伝えることは難しい。","bare"];
EXAMPLES[3220]=["The police arrested the suspect in the case.","警察はその事件の容疑者を逮捕した。","suspect"];
EXAMPLES[3221]=["The next day the battery was flat again.","翌日、またバッテリーが上がってる。","battery"];
EXAMPLES[3222]=["He made the best of his small income.","彼はわずかな収入を精一杯活かした。","income"];
EXAMPLES[3223]=["Are you saying that this is my fault?","私のせいってこと？","fault"];
EXAMPLES[3224]=["I think I'm gonna sneeze. Give me a tissue.","くしゃみが出そう・・・ティッシュちょうだい。","tissue"];
EXAMPLES[3225]=["What percentage of the students are admitted to colleges?","その学生たちの大学合格率はどのくらいですか。","percentage"];
EXAMPLES[3226]=["His speech was brief and to the point.","彼の話は短くて要点のついたものでした。","brief"];
EXAMPLES[3227]=["It is useless to reason with a bigot.","偏屈な奴とまともに話し合っても無駄だ。","useless"];
EXAMPLES[3228]=["Is it really possible to predict an earthquake?","地震を予測することは本当に可能なのだろうか。","predict"];
EXAMPLES[3229]=["The weather bureau stationed personnel on the island.","気象局は、島に、人員を配置した。","personnel"];
EXAMPLES[3230]=["There was a sudden change in the situation.","事態は急変した。","sudden"];
EXAMPLES[3231]=["Whose account should I transfer the money to?","どの口座に振り込めばいいの？","transfer"];
EXAMPLES[3232]=["The common state of this matter is solid.","この物質の普通の状態は固体である。","solid"];
EXAMPLES[3233]=["There's a lot of mess to clear up.","片付けなければならないたくさんのゴミがある。","mess"];
EXAMPLES[3234]=["I had a bad feeling, so I tried to flee.","居心地が悪かったから、とんずらしてみた。","flee"];
EXAMPLES[3235]=["The water will soon drain away.","水はすぐにはけるだろう。","drain"];
EXAMPLES[3236]=["His remark seems to be off the point.","彼の言うことは見当違いのようです。","remark"];
EXAMPLES[3237]=["A lot of people came to the lecture.","講演には多数の出席者があった。","lecture"];
EXAMPLES[3238]=["The resolution to the problem was close at hand.","その問題を解決するのはもうすぐだった。","resolution"];
EXAMPLES[3239]=["He advocated to us that the changes be made.","彼はその改革を実行すべきだと主張した。","advocated"];
EXAMPLES[3240]=["I bet the teacher's going to get mad!","きっと先生は怒るぞ！","bet"];
EXAMPLES[3241]=["Such a custom is characteristic of the British.","そういう習慣は英国人独特のものである。","characteristic"];
EXAMPLES[3242]=["He has the advantage of a good education.","彼は立派な教育を受けたという強みがある。","education"];
EXAMPLES[3243]=["You can do whatever you want to do.","君がやりたいようにやっていいよ。","whatever"];
EXAMPLES[3244]=["The cause of the fire is not known.","火事の原因は不明である。","cause"];
EXAMPLES[3245]=["You've got to carry out your commitment at all costs.","自分が堅く誓ったことは、どんなことがあっても実行しなければいけないよ。","commitment"];
EXAMPLES[3246]=["You must be the temporary we asked for.","私たちが探していたバイトの方ね。","temporary"];
EXAMPLES[3247]=["This project will involve 50 trained staff members.","この計画は５０人の訓練されたスタッフを必要とする。","involve"];
EXAMPLES[3248]=["After the meal, I asked for the Bill.","食事の後、私は勘定書をくれるように言った。","meal"];
EXAMPLES[3249]=["We will replace the current version with the upgrade.","現在のバージョンは、アップグレード版で置き換えます。","replace"];
EXAMPLES[3250]=["He looked at me with a strange expression.","彼は妙な顔つきで私を見た。","expression"];
EXAMPLES[3251]=["The big investor bought up the stocks.","大投資かは株を買い占めた。","investor"];
EXAMPLES[3252]=["I will labor in the cause of humanity.","人類のために働くつもりだ。","humanity"];
EXAMPLES[3253]=["We have a majority interest in the company.","私達は５０％以上の出資をしている。","majority"];
EXAMPLES[3254]=["Happiness does not consist of how much you possess.","幸福とは、どれだけのものを所有しているのかにあるのではありません。","possess"];
EXAMPLES[3255]=["He made a voluntary contribution to the school.","彼はその学校に自発的に寄付した。","contribution"];
EXAMPLES[3256]=["In the last few years it happened frequently.","ここ数年、ちょくちょくありましたね。","frequently"];
EXAMPLES[3257]=["She gave a shrug of the shoulders.","彼女は肩をすくめた。","shrug"];
EXAMPLES[3258]=["The operator put me through to New York.","交換手が電話をニューヨークへつないでくれた。","operator"];
EXAMPLES[3259]=["But his name is slightly familiar to me.","でも名前くらいは知っている。","slightly"];
EXAMPLES[3260]=["His interpretation of this matter is too one-sided.","この件に関する彼の解釈はあまりにも一方的だ。","interpretation"];
EXAMPLES[3261]=["He is not a man to rely on.","彼は信頼できる人ではない。","rely"];
EXAMPLES[3262]=["A further reduction would make us go into the red.","これ以上の値引きは、私どもを赤字に追いやるでしょう。","reduction"];
EXAMPLES[3263]=["We will purchase a new car next week.","我が家では来週、新車を購入するつもりだ。","purchase"];
EXAMPLES[3264]=["The view from the summit is very nice.","頂上からの景色は最高だね。","summit"];
EXAMPLES[3266]=["What examples of behaviour would you consider typically masculine?","あなたは一般的にどのような言動を男性的であると考えますか？","typically"];
EXAMPLES[3267]=["He is the novelist whom I admire most.","彼は私が最も尊敬している小説家だ。","admire"];
EXAMPLES[3268]=["I'm not as interested in literature as you.","私は君ほど文学に興味はない。","literature"];
EXAMPLES[3269]=["This is the biggest issue in this matter.","これがこの件に関する最大の問題点です。","issue"];
EXAMPLES[3270]=["How much is the rent for this room?","この部屋の家賃はいくらですか。","rent"];
EXAMPLES[3271]=["An old belief is sometimes still widely current.","古い信仰が今だに広く行われていることがある。","widely"];
EXAMPLES[3272]=["I had the satisfaction of finishing the work.","私はその仕事をやり終えて満足です。","satisfaction"];
EXAMPLES[3273]=["Do you want me to rub your shoulders?","肩を揉もうか？","rub"];
EXAMPLES[3274]=["He was completely taken in by the story.","彼はその話にすっかりだまされた。","completely"];
EXAMPLES[3275]=["After 6 p.m. the employees began to disappear.","６時を過ぎると従業員は帰り始めた。","disappear"];
EXAMPLES[3276]=["The government is desperate to keep inflation down.","政府はインフレを押え込もうと躍起になっている。","inflation"];
EXAMPLES[3277]=["I calculate he will be late coming home.","彼の帰りは遅いと思う。","calculate"];
EXAMPLES[3278]=["We should determine what is to be done first.","まず最初に何がなされるべきか決めなければならない。","determine"];
EXAMPLES[3279]=["Next time, let's eat at a Mexican restaurant.","次は、メキシコ料理を食べに行こうよ。","Mexican"];
EXAMPLES[3280]=["The land is out of crop this year.","その土地は今年は作付けしていない。","crop"];
EXAMPLES[3281]=["The prosecution condemned the defendant for kidnapping a child.","検察側は被告が子供を誘拐したと激しく非難した。","prosecution"];
EXAMPLES[3282]=["I have a pain in my little toe.","足の小指が痛むんだ。","toe"];
EXAMPLES[3283]=["I seize the moment and turn it to my advantage.","機会を捕らえてそれを有利に利用する。","seize"];
EXAMPLES[3284]=["The exhibition was a product of his imagination.","その展覧会は彼の想像力の産物だった。","imagination"];
EXAMPLES[3285]=["The governor was surprised by the commission's response.","知事は委員会の反応に驚いた。","governor"];
EXAMPLES[3286]=["You are really full of curiosity, aren't you?","君は好奇心が旺盛だね。","curiosity"];
EXAMPLES[3287]=["The dog bit the cat on the tail.","犬が猫の尻尾に噛み付いた。","tail"];
EXAMPLES[3288]=["I can except no one from the rules.","この規則から誰も除外できない。","except"];
EXAMPLES[3289]=["He bound the clothes together with a string.","彼は衣服を紐で束ねた。","string"];
EXAMPLES[3290]=["We have no call to appoint him to the post.","彼をその職に任ずる必要はない。","appoint"];
EXAMPLES[3291]=["His bearing announced him as a military man.","物腰から彼が軍人であることは歴然としていた。","military"];
EXAMPLES[3292]=["The conference is to be held in Tokyo.","会議を東京ですることになっている。","conference"];
EXAMPLES[3293]=["The same explanation is true of that case.","同じ説明がその場合にもあてはまる。","explanation"];
EXAMPLES[3294]=["I don't like the atmosphere of that school.","僕はあの学校のスクールカラーがすきではない。","atmosphere"];
EXAMPLES[3295]=["The boy ran and ran toward the goal.","少年はゴールに向かって走りまくった。","toward"];
EXAMPLES[3296]=["The examination was not difficult in the least.","その試験は少しも難しくなかった。","examination"];
EXAMPLES[3297]=["He is a tall and strongly built man.","彼は背が高く骨組みのがっちりした人だ。","strongly"];
EXAMPLES[3298]=["I could not say a word for fear.","私は恐怖のためにひと言も話せなかった。","fear"];
EXAMPLES[3299]=["He has the ability to do the work.","彼にはその仕事をこなす能力がある。","ability"];
EXAMPLES[3300]=["May I ask you what your weight is?","体重をおうかがいしてもよろしいですか。","weight"];
EXAMPLES[3301]=["They decided to exclude him from their circle.","彼らは彼を仲間からはずすことに決めた。","exclude"];
EXAMPLES[3302]=["School discipline is not as it should be.","学校の規律が乱れている。","discipline"];
EXAMPLES[3303]=["Our words are potentially ambiguous.","私たちの話す言葉は潜在的にあいまいである。","potentially"];
EXAMPLES[3304]=["I agree with you to a certain extent.","ある程度まで君に賛成だ。","extent"];
EXAMPLES[3305]=["The settlement is a matter of time.","解決は時間の問題だ。","settlement"];
EXAMPLES[3306]=["The damage of the disaster has been enormous.","その災害の被害はべらぼうに大きかった。","enormous"];
EXAMPLES[3307]=["He was calm in the presence of danger.","彼は危険に直面しても冷静だった。","presence"];
EXAMPLES[3308]=["The rapid growth of the city surprised us.","その都市の急速な発展に私たちは驚いた。","rapid"];
EXAMPLES[3309]=["This idea is the basis of my argument.","この考えが私の議論の基礎である。","basis"];
EXAMPLES[3310]=["The commander was roaring at his soldiers.","隊長は兵士を怒鳴りつけていた。","commander"];
EXAMPLES[3311]=["She has a very radical opinion about the problem.","彼女はその問題についてとても過激な意見を持っている。","radical"];
EXAMPLES[3312]=["We must respect the will of the individual.","個人の意志は尊重しなければならない。","individual"];
EXAMPLES[3313]=["This technical journal is above me.","この専門紙は私には理解できない。","journal"];
EXAMPLES[3314]=["We have to avoid war at any cost.","戦争は何としても避けなければならない。","avoid"];
EXAMPLES[3315]=["We have a substantial stake in the venture.","我々は、その事業にかなりの金をつぎ込んでいる。","stake"];
EXAMPLES[3316]=["Get up as early as you possibly can.","何とかして出来るだけ早く起きなさい。","possibly"];
EXAMPLES[3317]=["He is likely to be late for school.","彼は学校に遅刻しそうだ。","likely"];
EXAMPLES[3318]=["There was very little in the way of entertainment.","娯楽という点ではほとんど何もありませんでした。","entertainment"];
EXAMPLES[3319]=["It's always the opposite of what I expect.","自分の予想とはいつも反対になる。","opposite"];
EXAMPLES[3320]=["He lives in a poor district of London.","彼はロンドンの貧しい地区に住んでいる。","district"];
EXAMPLES[3321]=["I wish you could have seen him pitch.","彼の投球を見せたかったよ。","pitch"];
EXAMPLES[3322]=["The historical novel was a very popular genre.","歴史小説はとても人気の高いジャンルでした。","historical"];
EXAMPLES[3323]=["The bullet got the policeman in the leg.","弾丸は警官の脚に当たった。","bullet"];
EXAMPLES[3324]=["The administration cannot but look for alternative sources of revenue.","政府は他の歳入源を考え出すほかない。","revenue"];
EXAMPLES[3325]=["Freedom is the very essence of our democracy.","自由こそまさに我々の民主主義の神髄だ。","democracy"];
EXAMPLES[3326]=["The government has the power of legislation.","政府は立法権を持っている。","legislation"];
EXAMPLES[3327]=["The mother clasped her baby to her breast.","母親は赤ん坊を抱きしめた。","breast"];
EXAMPLES[3328]=["They shot the film in an actual desert.","彼等は実際の砂漠で映画を撮影した。","actual"];
EXAMPLES[3329]=["He is eager to go to the hospital.","彼はしきりに病院へ行きたがっている。","eager"];
EXAMPLES[3330]=["This is a proverb that I don't understand.","これは私がその意味が分からないことわざです。","proverb"];
EXAMPLES[3331]=["This problem bristles with difficulties both psychological and economical.","この問題には心理的なまた経済的な難問がいっぱいだ。","psychological"];
EXAMPLES[3332]=["He donated $10000 to the refugee fund.","彼は難民救済基金に１万ドルを寄付した。","refugee"];
EXAMPLES[3333]=["The origin of the fire in not obvious.","火元は明らかでない。","origin"];
EXAMPLES[3334]=["I had no notion that you were coming.","君がくるとは思わなかった。","notion"];
EXAMPLES[3335]=["How did you meet Tom initially?","トムとはどうやって知り合ったの？","initially"];
EXAMPLES[3336]=["I do not doubt it in the least.","私は少しもそれを疑わない。","doubt"];
EXAMPLES[3337]=["With a sigh, the boys left one another.","ため息をつくと、男子たちは散っていった。","sigh"];
EXAMPLES[3338]=["This laboratory is where we study every day.","この研究所は私達が毎日勉強しているところです。","laboratory"];
EXAMPLES[3339]=["To her delight, she got through the examination.","うれしいことに彼女は試験にパスした。","delight"];
EXAMPLES[3340]=["It is rumored that he will shortly resign.","彼は近く辞任するといううわさだ。","shortly"];
EXAMPLES[3341]=["This is a universal truth that transcends time.","これは古今東西に通ずる真理である。","universal"];
EXAMPLES[3342]=["It will end in a waste of labor.","それは骨折り損だ。","labor"];
EXAMPLES[3343]=["I spent the entire day on the beach.","私は一日中海辺で過ごした。","entire"];
EXAMPLES[3344]=["When we think this way, many problems arise.","このように考えると多くの問題が起きてくる。","arise"];
EXAMPLES[3345]=["Tom's company is incorporated in the Cayman Islands.","トムの会社はケイマン諸島で設立されました。","incorporated"];
EXAMPLES[3346]=["It was a mere chance that I found it.","私がそれを見つけたのは全くの偶然であった。","mere"];
EXAMPLES[3347]=["The agenda for the meeting has been distributed.","会議の議題が配布された。","agenda"];
EXAMPLES[3348]=["The frightened boy's voice was shaking with terror.","おびえた少年の声は恐怖で震えていた。","terror"];
EXAMPLES[3349]=["It is truly said that time is money.","時は金なりとは至言である。","truly"];
EXAMPLES[3350]=["I have a favor to ask of you.","一つお願いがあります。","favor"];
EXAMPLES[3351]=["A recession is bound to come next year.","来年は不況が避けられませんよ。","recession"];
EXAMPLES[3352]=["That aircraft company deals in freight only.","その航空会社は貨物のみを扱っている。","aircraft"];
EXAMPLES[3353]=["This was before John was put in prison.","ヨハネはまだ投獄されていなかったからである。","prison"];
EXAMPLES[3354]=["Let's go somewhere nice for our wedding anniversary.","結婚記念日のお祝いに、どこかおしゃれなとこに行こうよ。","anniversary"];
EXAMPLES[3355]=["There is no possibility of our finding him.","彼を探し出す可能性はない。","possibility"];
EXAMPLES[3356]=["Nobody could remember the sequence of events.","誰も事件の順序を思い出すことができなかった。","sequence"];
EXAMPLES[3357]=["I have a slight pain in my side.","脇腹が少し痛い。","slight"];
EXAMPLES[3358]=["I wrote to inform him of my decision.","私は自分の決定を知らせる手紙を彼に出した。","inform"];
EXAMPLES[3359]=["The students assisted the professor in the investigation.","学生たちは教授の調査の助手を務めた。","investigation"];
EXAMPLES[3360]=["She sometimes goes into a mood of depression.","彼女は憂鬱状態になることがある。","depression"];
EXAMPLES[3361]=["You won't be in time unless you run.","走らなければ間に合わない。","unless"];
EXAMPLES[3362]=["The necessity of education came home to me.","私は教育の必要性をしみじみと感じた。","necessity"];
EXAMPLES[3363]=["That matter was decided by the Supreme Court.","その事件は最高裁判所で解決された。","Supreme"];
EXAMPLES[3364]=["He had a severe look on his face.","彼の表情は厳しかった。","severe"];
EXAMPLES[3365]=["I'd like a Bloody Mary.","ブラッディーマリーをください。","Bloody"];
EXAMPLES[3366]=["He is a teacher apart from the rest.","彼は他の教師とは別だ。","apart"];
EXAMPLES[3367]=["The research cast new light on the issue.","その研究は問題に新たな光を投げかけた。","cast"];
EXAMPLES[3368]=["She is a clerk of the trading company.","彼女は貿易会社の事務員です。","trading"];
EXAMPLES[3369]=["This project is on a path to failure.","このプロジェクトは破綻に向かうだろう。","path"];
EXAMPLES[3370]=["I'd appreciate it if you could do that.","そうしてもらえると助かります。","appreciate"];
EXAMPLES[3371]=["There is a crack in the glass.","そのコップにはひびが入っている。","crack"];
EXAMPLES[3372]=["Don't hesitate to ask if you want anything.","欲しいものがあれば遠慮なく言いなさい。","hesitate"];
EXAMPLES[3373]=["I had a contrary opinion to the plan.","私はその計画に対して反対の意見を持っていた。","contrary"];
EXAMPLES[3374]=["Depending on your location, there's a chance of snow.","所によって、雪が降るかもしれません。","Depending"];
EXAMPLES[3375]=["How many people are there in this household?","この家族は何人家族ですか。","household"];
EXAMPLES[3376]=["Their home is abundant in love and laughter.","彼らの家庭は愛情と笑いにあふれている。","laughter"];
EXAMPLES[3377]=["A teenager sometimes acts like a baby.","ティーンエイジャーはたまに赤ん坊のような行動をとる。","teenager"];
EXAMPLES[3378]=["I have nothing to do with the crime.","私はその犯罪と何の関係もない。","crime"];
EXAMPLES[3379]=["I am frightened of walking in the darkness.","私は怖くて暗闇を歩けない。","frightened"];
EXAMPLES[3380]=["The bank holds a mortgage on his building.","銀行は彼のビルを抵当に取っている。","mortgage"];
EXAMPLES[3381]=["Tone of voice can indicate anger and irony.","声の調子は怒りや皮肉を示すことがある。","indicate"];
EXAMPLES[3382]=["I had a stroke last year.","去年脳卒中を起こしました。","stroke"];
EXAMPLES[3383]=["The water shortage is due to the weather.","水が足りないのは天候のためです。","shortage"];
EXAMPLES[3384]=["We want to explore an underwater oil field.","海底油田の開発をしたい。","explore"];
EXAMPLES[3385]=["All the property will go to his daughter.","その財産はすべて彼の娘のものになるだろう。","property"];
EXAMPLES[3386]=["The villagers tried to freeze us out.","村人たちは我々を仲間に入れまいとした。","freeze"];
EXAMPLES[3387]=["This question is closely related to that one.","この問題はあの問題と密接に関連している。","closely"];
EXAMPLES[3388]=["The company bought shares in the venture.","会社はその事業に資本参加した。","venture"];
EXAMPLES[3389]=["You need not take account of the fact.","君はその事実を考慮に入れる必要はない。","account"];
EXAMPLES[3390]=["The stomach is one of the internal organs.","胃は内臓の一つである。","internal"];
EXAMPLES[3391]=["He stood on the edge of the cliff.","彼はがけっぷちに立っていた。","edge"];
EXAMPLES[3392]=["That paper of his deal with environmental problems.","彼のその論文は環境問題を扱っている。","environmental"];
EXAMPLES[3393]=["I have plenty of time to do that.","私はそれをやるための多くの時間がある。","plenty"];
EXAMPLES[3395]=["You need to eat more fiber.","もっと繊維質を取りなさい。","fiber"];
EXAMPLES[3396]=["He was somewhat disappointed to hear the news.","彼はその知らせを聞いて少しがっかりした。","somewhat"];
EXAMPLES[3397]=["They decided to abolish the old restriction.","彼らは古い規制を廃止することを決めた。","restriction"];
EXAMPLES[3398]=["In order to do that, you have to take risks.","それをするためには危険を冒さなければならない。","In order to"];
EXAMPLES[3400]=["It is so good to be able to speak a number of foreign languages.","外国語がいくつも話せるというのは本当によい。","a number of"];
EXAMPLES[3401]=["If I happen to end up going abroad, I'd probably go for France.","もし万一外国へ行くとすれば、フランスにするでしょう。","end up"];
EXAMPLES[3402]=["He wanted to publish his photographs in the newspapers.","彼は新聞に自分の写真を発表したかった。","publish"];
EXAMPLES[3403]=["He traveled at the expense of the company.","彼は会社の費用で旅行した。","expense"];
EXAMPLES[3404]=["She was similar to me in many ways.","彼女はいろいろの点で私に似ていた。","similar"];
EXAMPLES[3405]=["The pollution of our coasts is very serious.","我が国の海岸汚染はとても深刻なものである。","pollution"];
EXAMPLES[3406]=["She lives at the Gorilla Foundation in California.","彼女はカリフォルニアのゴリラ財団研究所にいる。","Foundation"];
EXAMPLES[3407]=["There is nothing to compare with her beauty.","彼女の美しさに太刀打ちできるものはない。","compare"];
EXAMPLES[3408]=["The fiscal austerity may lead to an overkill of the economy.","緊縮財政政策は経済を冷やし過ぎることになるかもしれない。","lead to"];
EXAMPLES[3409]=["They rob, and furthermore cheat each other.","彼らは互いに盗み合いをする、だまし合うくらいは、なおさらのことだ。","furthermore"];
EXAMPLES[3410]=["Please consume within one to two days of opening.","開封後は一両日中にお召し上がり下さい。","consume"];
EXAMPLES[3411]=["He has been without employment for a month.","彼はこの１カ月仕事がない。","employment"];
EXAMPLES[3412]=["By chance we saw him as he came out of the shop.","偶然にも私たちは彼がその店から出てくるのを見ました。","By chance"];
EXAMPLES[3413]=["John is not a man to betray you.","ジョンはあなたを裏切るような人ではない。","betray"];
EXAMPLES[3414]=["I buy a portable music player.","ポータブルな音楽プレイヤーを買う。","portable"];
EXAMPLES[3415]=["At that time, my house was under construction.","あの頃は私の家は建築中だった。","construction"];
EXAMPLES[3416]=["It takes a long time to convert.","変換にはかなりの時間がかかる。","convert"];
EXAMPLES[3417]=["I have a large family to provide for.","私は大家族を養っています。","provide"];
EXAMPLES[3418]=["You must convert dollars into the local currency.","ドルは現地通貨に交換しなければなりません。","currency"];
EXAMPLES[3419]=["The picture is colorful in contrast with this one.","その絵はこの絵とは対照的にカラフルだ。","in contrast"];
EXAMPLES[3420]=["Additionally Tom and Mary both have ample personality.","トムもメアリーも個性豊かです。","Additionally"];
EXAMPLES[3421]=["I have come in response to your ad in the paper.","新聞広告を見て来ました。","in response to"];
EXAMPLES[3422]=["We were all shouting at the same time.","我々はみな同時に叫んでいた。","at the same time"];
EXAMPLES[3423]=["Nothing can be preserved that is not good.","善ならざるものは何であれ存続しえない。","preserved"];
EXAMPLES[3424]=["How would you analyze the situation?","状況をどう分析しますか。","analyze"];
EXAMPLES[3425]=["You must adapt to a variety of conditions.","君は様々な状況に適応しなければならない。","a variety of"];
EXAMPLES[3426]=["I feel sympathy for people with that disease.","私はその病気にかかった人に同情する。","sympathy"];
EXAMPLES[3427]=["Lack of flexibility is an obstacle to progress.","柔軟性の欠如は進歩の障害となる。","flexibility"];
EXAMPLES[3428]=["He has the ability to manage a business.","彼には事業を経営する能力がある。","manage"];
EXAMPLES[3429]=["In the darkness, I frantically reach out towards the receding figure.","暗闇の中、俺は遠ざかる後姿に必死に手を伸ばす。","reach out"];
EXAMPLES[3430]=["I quickly laugh at everything, for fear of having to cry.","泣き出さなければならないことを恐れて、私は素早く何ものをも笑ってしまう。","for fear of"];
EXAMPLES[3431]=["On behalf of the company, I welcome you.","一同を代表して、歓迎の意を表します。","On behalf of"];
EXAMPLES[3432]=["We came on account of your sick mother.","君のお母さんの病気をきづかってやって来ました。","on account of"];
EXAMPLES[3433]=["I found them lying on the artificial grass.","彼らは人工芝の上に横たわっていた。","artificial"];
EXAMPLES[3435]=["I will measure the weight of the horse.","馬の斤量を測る。","measure"];
EXAMPLES[3437]=["By the way, have you heard from her since then?","ところで、その後彼女から便りがありましたか。","since then"];
EXAMPLES[3439]=["It is cheaper than chemical fertilizers.","それは化学肥料よりも安い。","fertilizers"];
EXAMPLES[3440]=["Do you know what this box is made of?","君はこの箱が何で作られているかを知っていますか。","made of"];
EXAMPLES[3441]=["You should make sure of the fact without hesitation.","君はためらわずに事実を確かめるべきだ。","make sure"];
EXAMPLES[3442]=["There was nothing for it but to tolerate it.","我々はそれを我慢するほか仕方がなかった。","tolerate"];
EXAMPLES[3443]=["We are going on a journey next month.","私達は来月旅行にいくつもりです。","journey"];
EXAMPLES[3444]=["He left his team as he could not get along with the manager.","監督と仲良くやれなかったので彼はチームをやめた。","get along"];
EXAMPLES[3445]=["I can't keep up with you.","あなたにはついていけません。","keep up with"];
EXAMPLES[3446]=["Do you have a cell phone with you?","今携帯持ってる？","cell"];
EXAMPLES[3447]=["About two million pounds of flour are exported annually.","毎年200万ポンドの小麦粉が輸出されている。","annually"];
EXAMPLES[3448]=["Our advice is that the company invest in new equipment.","会社は新しい設備に投資すべきだというのが私たちの助言です。","invest in"];
EXAMPLES[3449]=["I didn't mean to embarrass you.","あなたに恥をかかせるつもりはありませんでした。","embarrass"];
EXAMPLES[3450]=["He tried to enlarge his sphere of influence.","彼は勢力範囲を広げようとした。","enlarge"];
EXAMPLES[3451]=["The snow was brilliant in the morning sun.","雪が朝日を受けて光り輝いていた。","brilliant"];
EXAMPLES[3452]=["For whom will you vote for president?","会長選挙でだれに投票しますか。","vote for"];
EXAMPLES[3453]=["The trains are less frequent at night time.","夜間、電車は本数が減ります。","frequent"];
EXAMPLES[3454]=["I wonder if fish can swim without gravity?","無重力で魚って泳げるのかな？","gravity"];
EXAMPLES[3455]=["It is rare for him to get angry.","彼が怒るのは珍しい。","rare"];
EXAMPLES[3456]=["There is a shortage of money in Brian's wallet and bank account.","ブライアンは、財布にも銀行にもあまりお金が残っていません。","bank account"];
EXAMPLES[3457]=["It took one week to locate their hiding place.","彼らの隠れ家を突き止めるのに１週間かかった。","locate"];
EXAMPLES[3458]=["What you have said doesn't apply to you.","君の今言ったことは、君にあてはまらない。","apply to"];
EXAMPLES[3459]=["Of the three boys, Bill behaves most politely.","三人の中で、ビルが最も行儀が良い。","politely"];
EXAMPLES[3460]=["I accidentally forgot to bring the house key.","家の鍵、持ってくるの忘れちゃった。","accidentally"];
EXAMPLES[3461]=["The fact is that I have another appointment.","実は別の約束がある。","appointment"];
EXAMPLES[3462]=["A television set used to be a luxury.","テレビは、昔ぜいたく品だった。","luxury"];
EXAMPLES[3463]=["He demanded a replacement for the broken part.","彼は壊れた所をとりかえてくれと要求した。","replacement"];
EXAMPLES[3464]=["You can get in touch with him at his home tonight.","あなたは今夜彼の家で、彼と連絡をとることができます。","in touch"];
EXAMPLES[3465]=["He can imitate the rest of the family.","彼は家族のまねが出来る。","imitate"];
EXAMPLES[3466]=["I was out of town on an assignment.","私は仕事で出かけていました。","assignment"];
EXAMPLES[3467]=["He was the instrument of his father's crimes.","彼は父親の犯罪の手先であった。","instrument"];
EXAMPLES[3468]=["The chimpanzee is an intelligent creature, capable of solving simple problems.","チンパンジーは簡単な問題なら解く事ができる知的な動物である。","capable of"];
EXAMPLES[3469]=["Could you arrange to be here at five?","５時にここに来るようにしていただけませんか。","arrange"];
EXAMPLES[3470]=["Which of your parents do you take after?","君はどちらの両親に似ていますか。","take after"];
EXAMPLES[3471]=["I believe he is not guilty of the crime.","私は、彼がその事件について無罪だと信じています。","guilty of"];
EXAMPLES[3472]=["Stop your grumbling and get the work out of the way.","ブーブー文句ばかり言ってないで、サッサと仕事を片付けろよ。","work out"];
EXAMPLES[3473]=["The composer is wrestling with the new music.","その作曲家は新しい曲に取り組んでいる。","composer"];
EXAMPLES[3474]=["I have to part with my old furniture.","古い家具を手放さないといけないんです。","furniture"];
EXAMPLES[3475]=["It's not particularly wonderful, but it is sufficient.","取り立ててすばらしいわけではないが満足できる。","sufficient"];
EXAMPLES[3476]=["I just barely managed to pass the test.","私は、かろうじて試験に合格した。","barely"];
EXAMPLES[3477]=["Is it okay if I delete this sentence?","こちらの文ですが、削除してもいいですか？","delete"];
EXAMPLES[3478]=["I have an urgent matter to attend to.","急いでする事がある。","urgent"];
EXAMPLES[3479]=["I always say to myself to be generous.","私はいつも寛大であれと自分に言い聞かせている。","generous"];
EXAMPLES[3480]=["You ought not to be cruel to animals.","動物に対してむごいことをしてはいけない。","cruel"];
EXAMPLES[3481]=["Please accept this gift for the celebration on your wedding.","結婚のお祝いに、これをお贈りします。","celebration"];
EXAMPLES[3482]=["A garden is the reflection of the gardener.","庭は庭師を映す鏡だ。","reflection"];
EXAMPLES[3483]=["She spoke to me in a whisper.","彼女は私に小声で話した。","whisper"];
EXAMPLES[3484]=["I made a deposit of $1,000 at the bank.","銀行に１０００ドル貯金した。","deposit"];
EXAMPLES[3485]=["I wish to say a word of apology.","お詫びとして一言言わせていただきたいと思います。","apology"];
EXAMPLES[3486]=["He would be the last to deceive you.","彼はあなたをだますような人ではありません。","deceive"];
EXAMPLES[3487]=["The cottage will not endure a strong wind.","小屋は強風に持ちこたえられまい。","endure"];
EXAMPLES[3488]=["I have my friend's car at my disposal.","私は友人の車を自由に使える。","disposal"];
EXAMPLES[3489]=["According to statistics, world population is on the rise.","統計によれば世界の人口は増加している。","statistics"];
EXAMPLES[3490]=["Go out of the terminal and turn right.","ターミナルの所を右に曲がったところです。","terminal"];
EXAMPLES[3492]=["The paper is too big for the envelope.","この紙は大きすぎて封筒に入らない。","envelope"];
EXAMPLES[3493]=["I know better than to quarrel with her.","私は彼女とけんかをするようなばかではない。","quarrel"];
EXAMPLES[3494]=["Yes, it happens from time to time.","はい、それは時々起こります。","from time to time"];
EXAMPLES[3495]=["Services of better quality are in demand.","質の良いサービスが求められている。","in demand"];
EXAMPLES[3496]=["The lack of harmony between colors makes this painting stand out.","各色間の調和に欠けているのでこの絵は目立つ。","stand out"];
EXAMPLES[3497]=["In the meantime, she began to cry.","そうしている間に彼女は泣き出した。","In the meantime"];
EXAMPLES[3498]=["I accept what you say to some extent.","君の言ったことをある程度まで受け入れます。","to some extent"];
EXAMPLES[3499]=["We must prevent war at any cost.","何としても戦争は防がねばならない。","at any cost"];
EXAMPLES[3500]=["You are young. I, on the contrary, am very old.","君は若い、それに反し私はかなり年をとっている。","on the contrary"];
EXAMPLES[3501]=["To lose face means to be humiliated.","顔を失うとは恥をかかされるという意味である。","lose face"];
EXAMPLES[3502]=["You'll have to answer for your behavior.","君は自分の行動に対して責任を取りなさい。","answer for"];
EXAMPLES[3503]=["It will make most Americans uncomfortable if you insist on their accepting expensive gifts.","ほとんどのアメリカ人は、高価な贈り物を受け取るように要求されれば、不快な気がするだろう。","insist on"];
EXAMPLES[3504]=["You and I are good friends, but we have little in common.","君とぼくは仲がよいが、共通するものはほとんどない。","in common"];
EXAMPLES[3506]=["Luckily, he was on time for the train.","運良く彼は汽車に間に合った。","Luckily"];
EXAMPLES[3507]=["Our plans are not yet concrete.","我々の計画はまだ固まってない。","not yet"];
EXAMPLES[3508]=["I have come in response to your ad in the paper.","新聞広告を見て来ました。","in response"];
EXAMPLES[3510]=["Sight is one of the five senses.","視覚は五感の１つである。","five senses"];
EXAMPLES[3511]=["I tripped on a stone, twisting my ankle.","私は石につまずいて、足首をひねってしまった。","ankle"];
EXAMPLES[3512]=["None of us are related to the problem.","我々は誰もその問題には関係ない。","related to"];
EXAMPLES[3513]=["He is active although he is very old.","彼は非常に年をとっているが元気だ。","active"];
EXAMPLES[3515]=["This vitamin boosts your immune system from diseases.","このビタミンは病気に対する抵抗力を強めます。","immune"];
EXAMPLES[3516]=["The enemy fled in disorder from the battlefield.","敵は戦場からちりぢりに逃げ去った。","disorder"];
EXAMPLES[3517]=["I had a mental blow at that time.","私はそのとき精神的なショックを受けた。","mental"];
EXAMPLES[3518]=["I don't intend to be selfish.","自分勝手にするつもりはない。","intend to"];
EXAMPLES[3519]=["Interest on loans is high at present.","ローンの金利は現在高い。","at present"];
EXAMPLES[3520]=["I came to the realization too late to make a difference.","違いが分かるには遅すぎた。","make a difference"];
EXAMPLES[3521]=["A very handsome prince met an exceptionally beautiful princess.","とてもハンサムな王子が世にも美しい王女に出会った。","exceptionally"];
EXAMPLES[3522]=["May I make so bold as to request your assistance?","恐縮ですがお手伝い願えませんか。","as to"];
EXAMPLES[3523]=["The house was on the verge of collapse.","その家は倒れかかっていた。","collapse"];
EXAMPLES[3524]=["She could not put up with the insult.","彼女はその侮辱には耐えられなかった。","insult"];
EXAMPLES[3525]=["We have isolated one patient from the rest.","私たちは、一人の患者を残りの患者から隔離した。","isolated"];
EXAMPLES[3526]=["In the first place, you should be punctual.","まず、第一に、君は時間を守らなければならない。","punctual"];
EXAMPLES[3527]=["She was frightened to see the black cat.","彼女は黒猫を見て驚いた。","frightened"];
EXAMPLES[3528]=["I guarantee this watch to keep perfect time.","この時計は絶対に狂わないこと請け合いだ。","guarantee"];
EXAMPLES[3529]=["You are not to blame for the accident.","あなたはその事故に責任はありませんよ。","blame"];
EXAMPLES[3530]=["Those who violate the rules will be punished.","規則違反をする者は罰せられるだろう。","violate"];
EXAMPLES[3531]=["We ask you to account for your delay.","遅れたわけを説明してもらいたい。","delay"];
EXAMPLES[3532]=["I immigrated to America when I was little.","幼い頃、アメリカに移住しました。","immigrated"];
EXAMPLES[3533]=["He is possessed of a strong fighting instinct.","彼は闘争本能が強い。","instinct"];
EXAMPLES[3534]=["Strangely enough, I felt no pain at all.","不思議なことに、全く痛みを感じなかった。","Strangely"];
EXAMPLES[3535]=["Chase the cat out of the kitchen.","台所からその猫を追い出してくれ。","Chase"];
EXAMPLES[3536]=["Shall I pour some beer for you?","ビールお注ぎしましょうか？","pour"];
EXAMPLES[3537]=["We had been rival lovers at one time.","我々はかつて、恋敵だった。","at one time"];
EXAMPLES[3538]=["To my surprise, the child came here by himself all the way from Yokohama.","驚いた事に、その子供は横浜からはるばる一人でここにやってきた。","all the way"];
EXAMPLES[3540]=["I hope to try out for cheerleader.","チアリーダーの選抜テストを受けたいのです。","try out"];
EXAMPLES[3541]=["For what purpose did you break into the house?","どんな目的で君はその家に侵入したのですか。","break into"];
EXAMPLES[3542]=["Let's call it a day today.","今日は終わりにしましょう。","call it a day"];
EXAMPLES[3543]=["To be awake is to be alive.","目が覚めているということは、生きているということである。","be awake"];
EXAMPLES[3544]=["The brightness of her smile always makes me feel better.","彼女の笑顔の明るさがいつも私の気分をよくしてくれる。","brightness"];
EXAMPLES[3545]=["Liquor will have an effect on a person.","お酒を飲むと影響が出るものだ。","have an effect on"];
EXAMPLES[3546]=["The world's largest indoor beach is located in Brandenburg, Germany.","世界一の大きさを誇る室内ビーチは、ドイツのブランデンブルクにあります。","indoor"];
EXAMPLES[3548]=["In American football the defense has a specific job.","アメリカンフットボールではディフェンスは特別な仕事だ。","specific"];
EXAMPLES[3549]=["When you run, your heart rate increases.","走ると心拍数が上がります。","heart rate"];
EXAMPLES[3550]=["Ultimately, space flight will be beneficial to all mankind.","究極的には宇宙飛行は全人類に有益なものとなろう。","be beneficial to"];
EXAMPLES[3551]=["Mr Ford is what is called a self-made man.","フォード氏はいわゆる自力の成功者だ。","what is called"];
EXAMPLES[3552]=["By architectural symmetry, Emmet means geometric symmetry combined with aesthetic uniformity.","建築のシンメトリーで、エメットは美的統一性をもった幾何学的な対称性を意味している。","symmetry"];
EXAMPLES[3553]=["Can you cash this check for me?","この小切手を現金にしてくれますか。","check for"];
EXAMPLES[3554]=["Don't worry. You'll get used to it over time.","心配いらないよ。そのうち慣れるよ。","over time"];
EXAMPLES[3555]=["The rules must be few, and what is more important, simple.","規則は少なくなければならない。さらに重要なことには、簡単なものでなければならない。","what is more"];
EXAMPLES[3556]=["The fire went on for some time before it was brought under control.","火事は鎮火するまでかなりの間燃え続けていた。","for some time"];
EXAMPLES[3557]=["Don't attempt two projects at a time.","一度に二つの計画を試みてはいけない。","at a time"];
EXAMPLES[3559]=["If talking about copyright, I guess we need Tom!","著作権と言えば、トムでしょ！","copyright"];
EXAMPLES[3560]=["I want to see the director of the company.","私は社長に会いたいのです。","director"];
EXAMPLES[3561]=["John is brave in appearance, but is in reality a coward.","ジョンは見たところ勇敢そうだが、実際は臆病者だ。","in reality"];
EXAMPLES[3564]=["Throw away the chairs whose legs are broken.","脚の壊れている椅子は捨てなさい。","Throw away"];
EXAMPLES[3565]=["Germans are very environmentally conscious.","ドイツ人は環境に対する意識が非常に高い。","environmentally"];
EXAMPLES[3566]=["The new bridge is in process of construction.","新しい橋の建設が進行中だ。","process"];
EXAMPLES[3567]=["The rain began to turn into snow.","雨が雪に変わり始めた。","turn into"];
EXAMPLES[3568]=["You must cut down on extra expenses in order to live within your means.","君は自分の収入の範囲内で生活するように、余分な支出は切りつめなければならない。","cut down on"];
EXAMPLES[3569]=["Smoking will do you a lot of harm.","喫煙は君に大いに害になる。","harm"];
EXAMPLES[3570]=["This story might sound unbelievable but it is true.","この話は信じられないように思われるかもしれないが、本当の話だ。","unbelievable"];
EXAMPLES[3571]=["No woman is as arrogant as she is.","彼女ほど傲慢な女性はいない。","arrogant"];
EXAMPLES[3572]=["The ship is at anchor in the harbor.","その船は港に停泊している。","harbor"];
EXAMPLES[3573]=["She is a person with a strong temper.","彼女は癇癖の強い人です。","temper"];
EXAMPLES[3574]=["The legend gave the name to the place.","その地名は伝説に由来する。","legend"];
EXAMPLES[3575]=["He put me off with a vague answer.","彼はいい加減な返事で言い逃れた。","vague"];
EXAMPLES[3576]=["A festival is held at the rice harvest.","稲の収穫期にはお祭りをする。","harvest"];
EXAMPLES[3577]=["It was gambling that brought about his ruin.","彼を破滅させたのはばくちであった。","ruin"];
EXAMPLES[3578]=["He is planning to launch his business.","彼は自分の事業を始めようとしている。","launch"];
EXAMPLES[3579]=["I think it would be rude to refuse.","断るのは失礼なんじゃないかな。","refuse"];
EXAMPLES[3580]=["If you hurry, you will soon overtake her.","もし君が急げば、すぐに彼女に追いつくでしょう。","overtake"];
EXAMPLES[3581]=["He feels this new law will restrict his freedom.","彼はこの新しい法律によって自由が制約を受けると感じている。","restrict"];
EXAMPLES[3582]=["He lost a fortune in the stock market.","彼は株式市場で大損をした。","stock"];
EXAMPLES[3583]=["He is superior to his competitors in everything.","彼は競争相手よりもあらゆる点で優っている。","competitors"];
EXAMPLES[3584]=["There were more spectators than I had expected.","予想以上に多くの観客が来ていました。","spectators"];
EXAMPLES[3585]=["The explorer bartered with the natives for food.","探検家は現地人たちと物々交換をして食料を手に入れた。","explorer"];
EXAMPLES[3587]=["You should concentrate on the road when you're driving.","運転している時は、道路に集中すべきだ。","concentrate on"];
EXAMPLES[3588]=["You may laugh at me.","君は私を笑うかもしれない。","laugh at"];
EXAMPLES[3589]=["In the matter of food and clothing, we are pretty well off.","衣食に関しては我々はかなり豊かである。","well off"];
EXAMPLES[3590]=["Go straight on, and you will find the store.","まっすぐ行きなさい。そうすれば店が見えます。","straight on"];
EXAMPLES[3591]=["The raft has drifted far off from the shore.","いかだは岸からずっと遠くへ漂流した。","far off"];
EXAMPLES[3592]=["He is not equal to the important job.","彼はあの大切な仕事には不適格だ。","equal"];
EXAMPLES[3593]=["Can I drop off the car?","乗り捨てる事ができますか。","drop off"];
EXAMPLES[3594]=["Why did you leave out the first question on the exam?","どうして試験で最初の問題を抜かしたの？","leave out"];
EXAMPLES[3595]=["Are your opinions representative of those of the other students?","君の意見が他の生徒の意見を代表しているのかね。","the other"];
EXAMPLES[3596]=["Take the leftover food home with you.","食べ残しはお持ち帰りください。","leftover"];
EXAMPLES[3597]=["There were hundreds of taxis at the airport, all touting for business.","空港には数百台のタクシーがいて、皆客引きしていた。","hundreds of"];
EXAMPLES[3598]=["Efficiency is the dominant idea in business.","商売では能率のよさということが最も重要な考えである。","Efficiency"];
EXAMPLES[3599]=["Flower arrangement is a part of Japanese culture.","生け花は日本の文化です。","arrangement"];
EXAMPLES[3600]=["To get a prescription, go to a doctor.","処方箋をもらうために医者に行きなさい。","prescription"];
EXAMPLES[3602]=["You will do well to leave him.","君は彼と別れるのが賢明だろう。","do well"];
EXAMPLES[3603]=["The deadline for the reports is next Monday.","レポートは来週の月曜日が〆切です。","deadline"];
EXAMPLES[3604]=["Due to the fog, traffic is temporarily suspended.","霧のために、交通は一時不通になっている。","temporarily"];
EXAMPLES[3606]=["The fund was set up to help orphans.","孤児を助けるために基金が設立された。","fund"];
EXAMPLES[3607]=["Your effort will be rewarded in the long run.","君の努力はいずれ報われるだろう。","in the long run"];
EXAMPLES[3608]=["When inserting the budwood into the root stock, make the cambium layers overlap.","穂木を台木に差し込む際、形成層を重ね合わせるようにします。","overlap"];
EXAMPLES[3609]=["Collaboration has apparently paid off for both of them.","両者にとって協力が実を結んだようだ。","Collaboration"];
EXAMPLES[3610]=["The detective surprised the truth from the waitress.","刑事はウエイトレスの不意をついて真相を聞き出した。","detective"];
EXAMPLES[3611]=["We want to modify the regulations of our school.","私達は校則を修正したい。","modify"];
EXAMPLES[3612]=["Stir, and you are a dead man.","動いてみろ。命はないぞ。","Stir"];
EXAMPLES[3613]=["The satellite is in orbit around the moon.","衛星は月の周りの軌道に乗っている。","orbit"];
EXAMPLES[3615]=["The teacher had to evaluate all the students.","教師は学生全員に評価をつけなければならなかった。","evaluate"];
EXAMPLES[3616]=["I am excited at the prospect of seeing her.","彼女に会えると思うとわくわくする。","prospect"];
EXAMPLES[3617]=["I want to marry a girl like her.","彼女のような女性と結婚したいね。","marry"];
EXAMPLES[3618]=["My health makes me a very slow worker.","健康のせいで仕事がいっこうにはかどらない。","worker"];
EXAMPLES[3619]=["The girl has to match me in skill.","私と互角で渡り合える女の子でなければだめだ。","skill"];
EXAMPLES[3620]=["So friendship is also a requirement for happiness.","友情も幸せに必要だってことでしょうか。","requirement"];
EXAMPLES[3621]=["I will define happiness as this.","私は幸福を次のように定義しよう。","define"];
EXAMPLES[3622]=["In for a penny, in for a pound.","一度始めたことは、最後までやり通せ。","pound"];
EXAMPLES[3623]=["We will be willing to make a deal with you after the auction.","競売の後で喜んで取り引きしましょう。","deal with"];
EXAMPLES[3624]=["I'm sure your efforts will result in success.","君の努力はきっと成功をおさめるだろう。","result in"];
EXAMPLES[3625]=["You had better take into consideration that you are no longer young.","君は自分がもはや若くないことを考慮に入れたほうがいい。","no longer"];
EXAMPLES[3626]=["People shouldn't stare at foreigners.","外人をじっと見るべきではない。","stare at"];
EXAMPLES[3627]=["Mr White is in charge of our class.","ホワイト先生が我々の組を受け持っています。","in charge of"];
EXAMPLES[3628]=["The factory will begin to produce next year.","その工場は来年から製造をはじめる。","produce"];
EXAMPLES[3629]=["You have to cope with those difficult problems.","君はそれらの難問題に対処しなくてはならない。","cope with"];
EXAMPLES[3630]=["I was wondering if you were going to show up today.","今日君は来るのかなと思っていたところだよ。","show up"];
EXAMPLES[3631]=["Mahjong is a game well-known all around the world.","麻雀は世界でとても有名な、ゲームのひとつです。","all around the world"];
EXAMPLES[3632]=["You should carry out his offer.","君は最初の計画を実行すべきだ。","carry out"];
EXAMPLES[3633]=["Your poor memory is due to poor listening habits.","君の記憶力が悪いのは人の話を聞く習慣がちゃんとできていないからだ。","due to"];
EXAMPLES[3634]=["Every person has a right to defend themselves.","誰にも自分を守る権利がある。","defend"];
EXAMPLES[3635]=["Let's approach this problem from a different angle.","この問題を別の面から取り組んでみよう。","angle"];
EXAMPLES[3636]=["We asked for the payment of his debt.","われわれは彼の借金の支払いを請求した。","payment"];
EXAMPLES[3637]=["We must look into the matter at once.","我々はそのことをすぐに調査しなければならない。","look into"];
EXAMPLES[3638]=["Our plan didn't work in practice.","私たちの計画は実際にはうまく行かなかった。","in practice"];
EXAMPLES[3639]=["You should carry out the plan on schedule.","君はその計画を予定通り実行すべきだ。","on schedule"];
EXAMPLES[3640]=["The editor and the publisher are both my cousins.","その編集者と発行者はふたりとも私のいとこです。","publisher"];
EXAMPLES[3641]=["Have you ever felt dizzy on a plane?","飛行機でめまいを感じたことはありますか？","dizzy"];
EXAMPLES[3642]=["You look as though nothing has happened to you.","君はまるで何も起こらなかったような顔をしている。","as though"];
EXAMPLES[3643]=["I hope you will be pleased with this present.","この贈り物を気に入ってくださればと思います。","be pleased with"];
EXAMPLES[3644]=["We will have to postpone the game.","私たちはその試合を延期しなければならないだろう。","postpone"];
EXAMPLES[3645]=["The end does not always justify the means.","目的さえよければどんな手段をとってもよいわけではない。","justify"];
EXAMPLES[3646]=["I want to help you fulfill your dreams.","あなたの夢を叶える手助けをしたい。","fulfill"];
EXAMPLES[3647]=["He has no capacity to be a teacher.","彼には教師たる才能がない。","capacity"];
EXAMPLES[3649]=["I've had my hair removed permanently, so my skin is smooth.","私は今は永久脱毛で肌がツルツルです。","permanently"];
EXAMPLES[3650]=["I want to work in the medical field.","医療の分野で働きたいです。","medical"];
EXAMPLES[3651]=["Regard all art critics as useless and dangerous.","あらゆる芸術評論家達は無能であり危険な存在である。","critics"];
EXAMPLES[3652]=["The explorers discovered a skeleton in the cave.","探検家達は洞穴の中で骸骨を発見した。","explorers"];
EXAMPLES[3653]=["They had cleared the obstacle from the road.","道路からその障害物が取り除いてあった。","obstacle"];
EXAMPLES[3655]=["Tom was very squeamish and would pass out at the sight of blood.","トムは血を見て吐き気に襲われ、気絶しました。","pass out"];
EXAMPLES[3656]=["You ought to think over whether the premise is valid or not.","その前提が妥当かどうかよく考えるべきだ。","think over"];
EXAMPLES[3657]=["I was asked to put away all the papers we used at the meeting.","私たちが会議で使用した書類をすべてかたづけるように頼まれた。","put away"];
EXAMPLES[3658]=["The letter sounds forced, what is worse, insincere.","その手紙には強制的なひびきがあるし、さらに悪いことには、思いやりがない。","what is worse"];
EXAMPLES[3659]=["He was a neutral participant at the discussion.","彼は話し合いでは中立の立場をとった。","participant"];
EXAMPLES[3660]=["People react to the frustration in much the same way.","人は欲求不満に対してほとんど同じように反応する。","react to"];
EXAMPLES[3663]=["I believe that he is a reliable man.","彼は信頼できる人物だと思う。","reliable"];
EXAMPLES[3664]=["Money and I are strangers; in other words, I am poor.","金と私とは他人同士だ。つまり、貧しいのだ。","in other words"];
EXAMPLES[3665]=["The chairperson has been associated with the organization for ten years.","議長はその団体に１０年間加入しています。","associated with"];
EXAMPLES[3666]=["To start with, I must thank you for your help.","まず第一にあなたの援助にお礼を申し上げます。","To start with"];
EXAMPLES[3667]=["First of all, he went to the station.","まず彼は駅へ行った。","First of all"];
EXAMPLES[3668]=["Congratulations on coming first in the competition.","その競技で優勝したそうで、おめでとうございます。","Congratulations on"];
EXAMPLES[3669]=["Time is the most precious thing of all.","時間は最も貴重なものだ。","precious"];
EXAMPLES[3670]=["The number of students who specialize in biology will increase from now on.","今後、生物学を専攻する学生の数は増加するであろう。","specialize in"];
EXAMPLES[3671]=["I will not take the Corona vaccine.","コロナワクチンは受けないよ。","vaccine"];
EXAMPLES[3672]=["I want to congratulate you on your graduation.","ご卒業おめでとうございます。","congratulate"];
EXAMPLES[3673]=["I recommend a thorough checkup for your husband.","ご主人の健康診断を徹底的に行うことを勧めます。","checkup"];
EXAMPLES[3674]=["Let me see your health insurance certificate.","保険証を出してください。","health insurance"];
EXAMPLES[3676]=["It is no inconvenience to drive you home.","家まで車でお送りしてもいいですよ。","inconvenience"];
EXAMPLES[3677]=["We're in for an unusually hot summer this year.","私たちは今年は例年になく暑い夏を経験しそうだ。","unusually"];
EXAMPLES[3679]=["Our total debts amount to ten thousand dollars.","我々の負債の合計は１万ドルに達している。","amount to"];
EXAMPLES[3680]=["You had better apologize to him for that failure in some way or other.","なんとかしてその失敗のことで彼に謝ったほうがいいよ。","in some way"];
EXAMPLES[3682]=["We are here because we have a right to be involved in these decisions.","私たちがこの会議にまいりましたのは、私たちにもこの会議の諸決定に関わり合う権利があるからです。","be involved in"];
EXAMPLES[3683]=["Do you think it's dangerous to eat genetically modified food?","遺伝子組み換え食品を食べるのは危険だと思いますか？","genetically"];
EXAMPLES[3684]=["Did you know that vinegar can be made from dates?","デーツからお酢ができるって、知ってた？","be made from"];
EXAMPLES[3685]=["I plan to major in engineering in college.","僕は大学で工学を専攻するつもりだ。","major"];
EXAMPLES[3688]=["I hear a noise offensive to the ear.","耳障りな音が聞こえる。","offensive"];
EXAMPLES[3689]=["The car came to an abrupt stop.","その車は急停車した。","abrupt"];
EXAMPLES[3690]=["The song is now very familiar to us.","その歌は今では私達によく知られている。","familiar"];
EXAMPLES[3691]=["Do you have any sales distributors in Japan?","日本に販売代理店をお持ちですか。","distributors"];
EXAMPLES[3692]=["This event was good publicity for the company.","この事件は会社のいい宣伝になった。","publicity"];
EXAMPLES[3693]=["The separation of gold from sand is problematic.","砂から金をより分けるのは難問だ。","separation"];
EXAMPLES[3695]=["The teacher will illustrate how to do it.","先生がそのやり方を説明するだろう。","illustrate"];
EXAMPLES[3696]=["He is voluntarily supporting you.","彼はあなたをすすんでサポートします。","voluntarily"];
EXAMPLES[3698]=["Approximately what number of kanji do you know?","漢字って、何個ぐらい知ってる？","Approximately"];
EXAMPLES[3699]=["I think it is important to live peacefully.","平和な暮らしが大事だと思う。","peacefully"];
EXAMPLES[3700]=["When the whistle blows, the race will start.","笛が鳴るとレースが始まります。","whistle"];
EXAMPLES[3701]=["The long voyage was a trial for us.","長い船旅は私たちにとって試練であった。","voyage"];
EXAMPLES[3702]=["Anne is the envy of all her friends.","アンは友人みんなの羨望の的である。","envy"];
EXAMPLES[3703]=["It is impossible to exaggerate the importance of education.","教育の重要性はいくら強調してもしすぎることはない。","exaggerate"];
EXAMPLES[3704]=["Please refer to the tourist information office.","観光案内所に問い合わせてください。","refer to"];
EXAMPLES[3705]=["Whom are you speaking of?","君は誰のことを言っているのか。","speaking of"];
EXAMPLES[3706]=["With a little more wisdom, he would not have got in trouble.","もう少し知恵があったら、彼は面倒な目にあわずにすんだのに。","in trouble"];
EXAMPLES[3707]=["At best we can only hope for a small profit.","われわれはせいぜいわずかな利益しか望めない。","At best"];
EXAMPLES[3708]=["Your composition was good except for the spelling.","君の作文は綴り字以外はよく書けていた。","except for"];
EXAMPLES[3709]=["The law is not in effect any longer.","その法律は効力が無くなっている。","in effect"];
EXAMPLES[3710]=["You may think those shoes are in fashion, but they aren't.","君はそんな靴が流行していると思っているかもしれないが、そうじゃないんだ。","in fashion"];
EXAMPLES[3711]=["Our catalog will be sent on demand.","ご請求次第カタログをお送りします。","on demand"];
EXAMPLES[3712]=["The transportation in this city is very convenient.","この町は交通の便がすごくいい。","transportation"];
EXAMPLES[3713]=["In general, people were against the consumption tax.","概して人々は消費税に反対だった。","In general"];
EXAMPLES[3714]=["I can recognize him even in a crowd.","私は人ごみの中でも彼を見分けることができる。","recognize"];
EXAMPLES[3715]=["Sorry, sir, but this coupon is expired.","お客様、申し訳ございませんが、こちらのクーポンは有効期限が切れております。","expired"];
EXAMPLES[3716]=["He asked me to renew the bond.","彼は私に証書を書き換えるよう要求した。","renew"];
EXAMPLES[3718]=["Careful as he was he made unexpected mistakes.","注意深かったのに彼は思いがけない間違いをした。","unexpected"];
EXAMPLES[3719]=["In Japan, the humidity is high in the summer.","日本の夏は、湿度が高い。","humidity"];
EXAMPLES[3720]=["You had better not smoke while on duty.","勤務中はタバコを吸わない方がいいよ。","on duty"];
EXAMPLES[3721]=["That bridge has been out of use for a long time.","その橋は長い間使われていない。","out of use"];
EXAMPLES[3722]=["I know the exact time when that happened.","それが起こった正確な時間を知っています。","exact"];
EXAMPLES[3723]=["Nuclear weapons will bring about nothing but the ruin of mankind.","核兵器は人類の破滅以外の何ももたらさないだろう。","bring about"];
EXAMPLES[3724]=["She has been ill for three weeks.","彼女が病気になってから３週間だ。","ill"];
EXAMPLES[3725]=["Your behavior is quite out of place.","君の行動はまったく当をえていない。","out of place"];
EXAMPLES[3726]=["Listen to the facts relative to the issue.","その問題に関する事実をよく聞きなさい。","relative"];
EXAMPLES[3727]=["This medicine is not a poison in itself.","この薬はそれ自体では毒ではない。","poison"];
EXAMPLES[3729]=["I need one container of eggs, you see.","１パック卵がいるんだ。","container"];
EXAMPLES[3731]=["I'd like to dedicate this song to my mother.","この歌を母に送ろうと思います。","dedicate"];
EXAMPLES[3732]=["The parents try to amuse their baby with a toy.","両親は赤ん坊をおもちゃであやそうとした。","amuse"];
EXAMPLES[3733]=["Everyone admitted that the earth is a sphere.","誰もが地球は球体だと認めていた。","sphere"];
EXAMPLES[3734]=["They harbor thoughts of taking revenge on you.","彼らはあなたに仕返ししようと思っている。","revenge"];
EXAMPLES[3735]=["The police are suspicious of the old man.","警察はその老人を疑っている。","suspicious"];
EXAMPLES[3736]=["The negotiations are at a very delicate stage.","交渉はとても微妙な段階にさしかかっている。","delicate"];
EXAMPLES[3737]=["I think welfare isn't enough to go around.","福祉は十分に行き渡っていないように思うんですけど。","welfare"];
EXAMPLES[3738]=["As long as it doesn't interrupt the game!","ゲームを中断しさえしなければいいですよ。","interrupt"];
EXAMPLES[3739]=["In the morning, I just want to have a leisurely start.","やっぱり朝はこのくらいゆっくり出発したいものです。","leisurely"];
EXAMPLES[3740]=["It is impossible to substitute machines for people.","機械を人の代わりにするのは不可能だ。","substitute"];
EXAMPLES[3741]=["Peel the apple before you eat it.","リンゴを食べる前に皮をむきなさい。","Peel"];
EXAMPLES[3742]=["Thank you very much for your hospitality today.","今日はいろいろとありがとうございました。","hospitality"];
EXAMPLES[3743]=["He means the play to be a tragedy.","彼はその芝居を悲劇にするつもりだ。","tragedy"];
EXAMPLES[3744]=["A lot of students struggle with math in school.","学校の数学で悪戦苦闘する生徒も多いです。","struggle with"];
EXAMPLES[3745]=["He instructed me to go to bed early.","彼は私に早く寝るように命じた。","instructed"];
EXAMPLES[3746]=["You will soon get used to speaking in public.","すぐに人前で話すことに慣れますよ。","get used to"];
EXAMPLES[3747]=["Miniskirts have been out of date for some time.","ミニスカートがすたれてもうしばらくになる。","out of date"];
EXAMPLES[3748]=["I think that, in tough times, you can cry as much as you want.","つらいときは泣きたいだけ泣けばいいと思うよ。","in tough"];
EXAMPLES[3749]=["The investigation is under way.","その調査は進行中です。","under way"];
EXAMPLES[3750]=["When did the world come into being?","世界はいつ誕生したのだろうか。","come into being"];
EXAMPLES[3751]=["You are in need of a holiday.","君は休暇が必要だ。","in need of"];
EXAMPLES[3752]=["I'm at a loss for words.","何と言ったら良いか分かりません。","at a loss"];
EXAMPLES[3753]=["The children were told to stay within reach of their mother's voice.","子供達は母親の声の届くところにいるよういわれた。","within reach"];
EXAMPLES[3754]=["Yes! I won twice in a row!","やった！2回続けて勝っちゃった！","in a row"];
EXAMPLES[3755]=["Everyone seems to be short of money these days.","この頃は、誰もがお金に困っているようです。","be short of"];
EXAMPLES[3757]=["Brian repeatedly told Chris that he owed him a pretty large amount of money.","君は僕に多額の借金があるのだと、ブライアンはくり返しクリスに言いました。","large amount of"];
EXAMPLES[3758]=["I put down a rug under my desk.","机のしたにカーペットを敷いた。","rug"];
EXAMPLES[3759]=["She read the digest of War and Peace.","彼女は「戦争と平和」のダイジェストを読んだ。","digest"];
EXAMPLES[3760]=["This chapter will focus on the concepts of geometry.","この章では幾何学の概念に焦点をあてます。","focus on"];
EXAMPLES[3761]=["What that fortuneteller said yesterday is nothing to be concerned about.","昨日の易者の占いなんか気にすることないよ。","be concerned about"];
EXAMPLES[3762]=["First you have to build up your vocabulary.","まず君は単語能力をつけなければならない。","vocabulary"];
EXAMPLES[3763]=["It is important to strengthen the basis.","基礎を固めることは大切です。","strengthen"];
EXAMPLES[3764]=["He ought to be ashamed of his ignorance.","彼は自分の無知を恥ずかしいと思うべきだ。","ignorance"];
EXAMPLES[3765]=["I would like to improve my English pronunciation.","私は英語の発音をもっとよくしたい。","pronunciation"];
EXAMPLES[3766]=["This is a great invention in a way.","これはある意味偉大な発明だ。","invention"];
EXAMPLES[3767]=["I commute to work for an hour.","私は１時間通勤する。","commute"];
EXAMPLES[3768]=["I had nothing to do with that incident.","私はその事件になんの関係もなかった。","incident"];
EXAMPLES[3769]=["She yelled at the children to be quiet.","彼女は子供たちに静かにと叫んだ。","yelled"];
EXAMPLES[3770]=["Cover your mouth when you cough or sneeze.","咳やくしゃみをする時は、口元を覆いましょう。","sneeze"];
EXAMPLES[3771]=["Dickens was the author of'Oliver Twist'.","ディケンズは『オリバー・ツイスト』の著者です。","Twist"];
EXAMPLES[3772]=["The Romans tried to civilize the ancient Britons.","ローマ人は古代ブリトン人の文明化を試みた。","civilize"];
EXAMPLES[3773]=["We shouldn't impose our opinions on other people.","私たちは、自分の意見を他に人に押し付けてはいけない。","impose"];
EXAMPLES[3774]=["The government undertook a drastic reform of parliament.","政府は議会の抜本的な改革に着手した。","parliament"];
EXAMPLES[3775]=["It looks like Yokkun's dad ran off with his nursery school teacher.","よっくんのおとうさんね、幼稚園の若い先生とかけおちしたらしいわよ。","nursery school"];
EXAMPLES[3776]=["You should acquaint yourself with the local customs.","あなたはその地方の習慣を良く知るべきだ。","acquaint"];
EXAMPLES[3777]=["You must be mindful of your family responsibilities.","君は家族扶養の責任を忘れてはならない。","mindful"];
EXAMPLES[3778]=["Stand still and keep silent.","じっと立っていて、だまっていなさい。","Stand still"];
EXAMPLES[3779]=["The waste of time and money is incredible.","時間とお金の浪費はとてつもない。","incredible"];
EXAMPLES[3780]=["In terms of the pay you will get, is this a good job?","君がもらう給料の点からこれはいい仕事かね。","In terms of"];
EXAMPLES[3781]=["He said he would give us his decision for sure by Friday.","金曜日までには間違いなく自分の決定を私たちに伝えてくれると彼は言った。","for sure"];
EXAMPLES[3782]=["You won't be in time for school.","君は授業に間に合いませんよ。","in time"];
EXAMPLES[3783]=["Do you have any objection to this plan?","この計画に異議はありますか。","objection"];
EXAMPLES[3784]=["I have a lot of work still outstanding.","私には未処理の仕事がまだたくさんある。","outstanding"];
EXAMPLES[3785]=["Do you have adequate money for the trip?","旅行に十分なお金がありますか。","adequate"];
EXAMPLES[3786]=["He has too many interests, to put it mildly.","控え目に言っても彼は関心事が多すぎる。","mildly"];
EXAMPLES[3787]=["The wound in the arm left a scar.","腕の傷は跡を残した。","scar"];
EXAMPLES[3789]=["The chimney began to give out smoke.","煙突は煙を出し始めた。","give out"];
EXAMPLES[3790]=["It is difficult to prove that ghosts exist.","幽霊が存在することを証明するのは難しい。","prove"];
EXAMPLES[3791]=["How much is it including insurance and tax?","保険、税金を含めて、合計金額はいくらになりますか。","insurance"];
EXAMPLES[3792]=["Our generation has seen a lot of changes.","われわれの世代の人々はいろいろな変化を見てきた。","generation"];
EXAMPLES[3793]=["Take down the book from the shelf.","その本を棚から下ろしなさい。","Take down"];
EXAMPLES[3794]=["The fact seemed to irritate her husband.","その事実は彼女の夫をいらいらさせるようだった。","irritate"];
EXAMPLES[3795]=["Some furniture is put together with glue.","家具の中には、にかわづけで組み立てられているものもある。","put together"];
EXAMPLES[3796]=["How do you account for your being late?","君は遅刻した理由をどう説明するのかね。","account for"];
EXAMPLES[3797]=["Tourism is important to the economy of my country.","観光は私の国の経済にとって重要です。","Tourism"];
EXAMPLES[3798]=["I didn't commit myself to attend the meeting.","その会に出席するとは約束しなかった。","commit"];
EXAMPLES[3799]=["The meeting was put off until next Friday.","会合は次の金曜日まで延期された。","put off"];
EXAMPLES[3800]=["Your question is not relevant to the subject.","君の質問は当面の話題とは関係がない。","relevant to"];
EXAMPLES[3801]=["The two countries differ in religion and culture.","その両国は宗教と文化が違っている。","differ"];
EXAMPLES[3802]=["I can't keep up with you.","あなたにはついていけません。","keep up"];
EXAMPLES[3803]=["Be sure to look over your paper again before you hand it in.","レポートを提出する前に必ずもう一度目を通しなさい。","look over"];
EXAMPLES[3804]=["I don't want to go out on a limb.","危ない橋は渡りたくないんだ。","limb"];
EXAMPLES[3806]=["Psychology is the scientific study of the mind.","心理学は心を科学研究する学問である。","Psychology"];
EXAMPLES[3807]=["I have a cough and a little fever.","咳とちょっと熱がある。","cough"];
EXAMPLES[3808]=["His employer was sincerely grateful for his cooperation.","雇用主は彼の協力に心から感謝した。","sincerely"];
EXAMPLES[3811]=["Nor am I ashamed to confess my ignorance.","それに知らないことは知らないと認めたって恥とは思わない。","confess"];
EXAMPLES[3812]=["At which window can I make a reservation?","予約はどの窓口でできますか。","reservation"];
EXAMPLES[3813]=["The translation is quite true to the original.","その翻訳は原文に極めて忠実である。","translation"];
EXAMPLES[3814]=["The comparison between the two was to his disadvantage.","２人を比較すると彼の方が形勢不利だった。","disadvantage"];
EXAMPLES[3815]=["He tried to look at his situation objectively.","彼は自分の状況を客観的に見てみたのね。","objectively"];
EXAMPLES[3817]=["She asked about the location of the house.","彼女はその家のある場所を尋ねた。","location"];
EXAMPLES[3818]=["Lack of oxygen is fatal to most animals.","酸素が不足することは大部分の動物にとって命にかかわることである。","oxygen"];
EXAMPLES[3819]=["Our school administration decided to do away with that school rule.","学校当局はその校則を廃止することに決定した。","do away with"];
EXAMPLES[3820]=["The room was in a state of neglect.","部屋はほったらかしのままだった。","neglect"];
EXAMPLES[3822]=["Thank you very much for your generous donation.","多額の寄付をありがとうございました。","donation"];
EXAMPLES[3823]=["He hopes to exhibit his paintings in Japan.","彼は日本で自分の絵を展示したいと望んでいる。","exhibit"];
EXAMPLES[3824]=["He is the principal of the high school.","彼はその高校の校長です。","principal"];
EXAMPLES[3825]=["A young man came for the new product.","若者が新製品を引き取りにきた。","product"];
EXAMPLES[3826]=["We were financially troubled, in short, we were bankrupt.","我々は財政的に困窮していた。要するに破産したのだ。","in short"];
EXAMPLES[3827]=["Finally, he gave in to my persuasion.","ついに、彼は私の説得に成功した。","persuasion"];
EXAMPLES[3828]=["Why do birds migrate in the first place?","そもそもなぜ鳥は移動するのだろうか。","migrate"];
EXAMPLES[3829]=["That's reversing the logical order of things.","それでは本末転倒だ。","logical"];
EXAMPLES[3830]=["You cannot be rude to everyone and expect to get away with it forever.","みんなに無礼な振舞をして、そのとがめを受けないでいられるとは考え。","get away with"];
EXAMPLES[3831]=["Check up on the accuracy of this article.","この記事が何処まで本当か調べてくれ。","accuracy"];
EXAMPLES[3832]=["Thank you for doing the laundry for me.","洗濯してくれてるんだ。ありがとう。","laundry"];
EXAMPLES[3833]=["You've got nothing to complain of.","君には不満が全くない。","complain of"];
EXAMPLES[3834]=["The intensive course did wonders for my French.","集中講習で私のフランス語は驚くほど上達した。","intensive"];
EXAMPLES[3835]=["Please look through these papers at your leisure.","あなたが暇な時にこの書類に目を通してください。","look through"];
EXAMPLES[3836]=["The House cut the budget for foreign aid.","下院は外国援助の予算を削減した。","budget"];
EXAMPLES[3837]=["Mummy has to do the washing this afternoon.","ママは午後洗濯をしなくてはいけない。","Mummy"];
EXAMPLES[3838]=["Cephadol is a medicine to control dizziness.","セファドールはめまいを抑える薬です。","dizziness"];
EXAMPLES[3839]=["You should not drink a lot of liquid.","水分を控えてください。","liquid"];
EXAMPLES[3840]=["We gave the performer a round of applause.","我々はその演奏者に拍手をおくった。","applause"];
EXAMPLES[3841]=["It's ridiculous and I can't help but laugh.","バカバカしくてつい笑ってしまう。","ridiculous"];
EXAMPLES[3842]=["The whale is not a fish but a mammal.","鯨は魚ではなくて、哺乳類です。","mammal"];
EXAMPLES[3843]=["The drivers began arguing about who was to blame for the accident.","運転手たちはその事故でだれが悪いのかについて議論を始めた。","blame for"];
EXAMPLES[3844]=["This vast continent is abundant in fossil fuels.","この広大な大陸は化石燃料が豊富だ。","fossil"];
EXAMPLES[3845]=["What is the precise meaning of the word?","その語の正確な意味は何ですか。","precise"];
EXAMPLES[3846]=["There are many places to see in Kyoto.","京都には見るべきところが多くある。","see in"];
EXAMPLES[3848]=["He was terribly poor when he was young.","彼は若い頃、ひどい貧乏だった。","terribly"];
EXAMPLES[3849]=["Where do I go after I pick up my baggage?","手荷物を受け取ったら、次にどこへ行けばいいのですか。","go after"];
EXAMPLES[3850]=["Competition is not by nature evil.","競争は本来悪いものではない。","by nature"];
EXAMPLES[3851]=["We were all astonished to hear the news.","私達は皆そのニュースを聞いてびっくりぎょうてんした。","astonished"];
EXAMPLES[3852]=["Please don't distract me from my work.","仕事の邪魔をしないでください。","distract"];
EXAMPLES[3853]=["The eldest sister acted in place of the mother.","一番上の姉が母の代わりをした。","in place"];
EXAMPLES[3854]=["The boss seemed to frown on my method.","主人は私のやり方に眉をひそめたようだった。","frown"];
EXAMPLES[3855]=["We have to figure out what to do.","何をすべきか、考えなければならない。","figure"];
EXAMPLES[3856]=["Asian religions inspire him to create splendid sculptures.","アジアの宗教から閃きを得て、彼は複数の素晴らしい彫刻を生み出した。","inspire"];
EXAMPLES[3857]=["The accomplishment of the task took several years.","その仕事の完成するには数年を要した。","accomplishment"];
EXAMPLES[3858]=["They decided to settle in a suburb of London.","彼らはロンドン郊外に居を構えることに決めた。","suburb"];
EXAMPLES[3859]=["I dragged the heavy baggage to the airport.","私は重い荷物を空港まで引きずって行った。","dragged"];
EXAMPLES[3860]=["The region is relatively rich in mineral resources.","その地域は鉱物資源が比較的豊かだ。","mineral"];
EXAMPLES[3861]=["Blossoms have come out on the embankment.","花々が土手に咲いた。","come out"];
EXAMPLES[3862]=["The terrible scene made him tremble in fear.","恐ろしい光景に彼は戦慄した。","tremble"];
EXAMPLES[3863]=["This might not be a genuine diamond.","これは本物のダイヤではないかもしれない。","genuine"];
EXAMPLES[3864]=["Where did you come across the rare stamps?","その珍しい切手はどこでみつけたのですか。","come across"];
EXAMPLES[3866]=["I'll give you my typewriter in exchange for that radio.","そのラジオの代わりにタイプライターをあげよう。","in exchange"];
EXAMPLES[3867]=["She goes to a school for the deaf.","彼女は耳の不自由な人々のための学校に通っている。","deaf"];
EXAMPLES[3868]=["The lecture you gave yesterday was a masterpiece.","昨日のあなたの講演はとてもすばらしかった。","masterpiece"];
EXAMPLES[3869]=["The train is bound for Niigata.","その列車は新潟行きです。","bound for"];
EXAMPLES[3870]=["There was a rapid decline in stock prices.","株価の急激な下落があった。","in stock"];
EXAMPLES[3871]=["We are able to deliver within a week.","1週間以内にお届けします。","deliver"];
EXAMPLES[3872]=["Can we create something out of nothing?","我々は、無から有を作り出すことができるだろうか。","create"];
EXAMPLES[3873]=["What kinds of tropical drinks do you have?","どんなトロピカルドリンクがありますか。","tropical"];
EXAMPLES[3874]=["I'll act on your advice.","ご忠告に従います。","act on"];
EXAMPLES[3875]=["Global agricultural output was expanding.","世界的な農業生産高は伸びていた。","agricultural"];
EXAMPLES[3876]=["The house was altogether destroyed by the fire.","その家は火事で完全に焼けた。","altogether"];
EXAMPLES[3877]=["Today, paper is used in quantity every day.","今日では大量の紙が毎日消費されている。","quantity"];
EXAMPLES[3878]=["We communicate by means of language.","私たちは、言語という手段を使って意思の疎通をします。","by means of"];
EXAMPLES[3879]=["I insist that he should go with us.","彼は私たちと一緒にいくべきです。","insist"];
EXAMPLES[3880]=["I have no hesitation in telling the truth.","真実を語ることに私は何のためらいもない。","hesitation"];
EXAMPLES[3881]=["You should persist in your efforts to learn English.","英語を習得する努力を続けるべきだ。","persist in"];
EXAMPLES[3882]=["All my haste was in vain.","急いだことが水の泡だった。","in vain"];
EXAMPLES[3883]=["It chances that he is off duty today.","たまたま彼は今日は非番だ。","off duty"];
EXAMPLES[3884]=["If it were not for air, we could not live on the earth.","空気が無ければ、我々は地球上で生きられないだろう。","live on"];
EXAMPLES[3885]=["Here's an illustration at the top of this page.","このページの上に挿し絵が有ります。","illustration"];
EXAMPLES[3886]=["I expect you all to do your best.","私は君たちみなが最善を尽くすことを期待する。","expect"];
EXAMPLES[3887]=["The nurse took his temperature with a thermometer.","看護婦は体温計で彼の体温を計った。","thermometer"];
EXAMPLES[3888]=["He cut the advertisement out of the newspaper.","彼は新聞から広告を切り抜いた。","advertisement"];
EXAMPLES[3889]=["They decided to pull down the old building.","古い建物を取り壊すことに決めた。","pull down"];
EXAMPLES[3890]=["The police are going to investigate the crime.","警察はその犯罪を調査しようとしている。","investigate"];
EXAMPLES[3891]=["He answers to the description of the criminal.","彼は犯人の人相書きと一致している。","description"];
EXAMPLES[3892]=["Please change your database to reflect the new address as follows.","貴社のデータベースにある私どもの住所を、下記新住所に変更してください。","as follows"];
EXAMPLES[3893]=["The punishment should be in proportion to the crime.","罪に比例して罰するべきだ。","punishment"];
EXAMPLES[3894]=["I would love to see my old flame again.","昔の恋人に再会してみたい。","flame"];
EXAMPLES[3895]=["Don't worry. The ambulance will be here soon.","大丈夫ですよ。もうすぐ救急車がここに来ますからね。","ambulance"];
EXAMPLES[3896]=["It is impossible for you to do so.","君はそんなことはできない。","impossible"];
EXAMPLES[3898]=["Those animals were in danger of dying out.","それらの動物は絶滅の危機にさらされていた。","in danger of"];
EXAMPLES[3899]=["Each student received his diploma in turn.","学生は各々順番に卒業証書を受け取った。","in turn"];
EXAMPLES[3900]=["Rome is worthy of a visit.","ローマは行ってみるだけの価値がある。","worthy of"];
EXAMPLES[3901]=["We look up to him as our leader.","僕たちは彼をリーダーとして尊敬しています。","look up to"];
EXAMPLES[3902]=["This will add to our troubles.","これでさらに困ったことになるだろう。","add to"];
EXAMPLES[3903]=["This is the central problem of postwar immigration.","これが戦後移民に関する中心的問題である。","immigration"];
EXAMPLES[3904]=["I tried to get it, but in vain.","手に入れようとしたが、無駄だった。","vain"];
EXAMPLES[3905]=["You must make up your mind, and that at once.","君は決心しなければならない。しかも今すぐにだ。","make up"];
EXAMPLES[3906]=["She has a great affection for her parents.","彼女は両親をとても愛してる。","affection"];
EXAMPLES[3907]=["All you have to do is to learn this sentence by heart.","君たちはこの文を暗記しさえすればよい。","by heart"];
EXAMPLES[3908]=["I think that I'm not academically oriented.","僕は学問には向いていないと思うんだ。","academically"];
EXAMPLES[3909]=["I go to the dentist every other day.","１日おきに歯医者に通っています。","dentist"];
EXAMPLES[3910]=["How long are you going to cling to past glory?","いつまで過去の栄光にしがみついてんだよ。","cling"];
EXAMPLES[3911]=["Do they clip the sheep every year?","彼らは毎年羊の毛を刈るのですか。","clip"];
EXAMPLES[3912]=["Do you have anything to relieve a headache?","何か頭痛をやわらげるものを持っていますか。","relieve"];
EXAMPLES[3913]=["He's a historian. He's now studying the structure of war.","彼は歴史学者だ。今は戦争の構造を研究している。","historian"];
EXAMPLES[3914]=["I wanted to meet a really mature woman.","私は真の大人の女性に会いたいと思った。","mature"];
EXAMPLES[3915]=["The United States of America is a democratic country.","米国は民主国家である。","democratic"];
EXAMPLES[3916]=["I made an abstract of a book.","本の要点を抜粋した。","abstract"];
EXAMPLES[3917]=["He tends to do everything to excess.","彼は何でもやりすぎる傾向がある。","excess"];
EXAMPLES[3918]=["The victims of the earthquake disaster are numerous.","大震災被災者が大勢います。","numerous"];
EXAMPLES[3919]=["He is in harmony with all his classmates.","彼はクラスメートみんなと仲良くしている。","harmony"];
EXAMPLES[3920]=["Woman's intuition is clearly a valuable trait.","女性の直感が価値ある特質であることは明らかだ。","trait"];
EXAMPLES[3921]=["You must assess the situation and act accordingly.","状況を判断してそれに応じて行動しなければならない。","assess"];
EXAMPLES[3922]=["The membership of the Boy Scout troop swelled.","ボーイスカウトの団員が増えた。","troop"];
EXAMPLES[3923]=["The output is way below last year's level.","生産高は昨年の水準よりはるかに落ちこんでいる。","output"];
EXAMPLES[3924]=["He will assist us in changing the tire.","彼は私たちがタイヤの交換をするのを助けてくれるだろう。","assist"];
EXAMPLES[3925]=["I can ensure a job for you.","私はあなたに仕事を確保できる。","ensure"];
EXAMPLES[3926]=["He is a man with a classical education.","彼は古典の教育を受けている。","classical"];
EXAMPLES[3927]=["He got out of the room in anger.","彼は怒って部屋から出て行った。","anger"];
EXAMPLES[3928]=["Your plan has the virtue of being practical.","あなたの計画は実際的だという長所がある。","virtue"];
EXAMPLES[3929]=["I want you to return to your seat.","お座席にお戻りください。","seat"];
EXAMPLES[3930]=["It's better not to drink the tap water.","水道水は飲まないほうがいいよ。","tap"];
EXAMPLES[3931]=["I urinate a tremendous amount at a time.","尿量がとても多いです。","tremendous"];
EXAMPLES[3932]=["The members of the committee are all men.","委員会の委員は全員男性だ。","committee"];
EXAMPLES[3933]=["Could you take me to the Grand Hotel?","グランドホテルまで、行ってください。","Grand"];
EXAMPLES[3934]=["This book is a good guide for beginners.","この本は初心者にとって良い手本となる。","guide"];
EXAMPLES[3935]=["A blood vessel broke in my eye.","目の血管が切れてしまった。","vessel"];
EXAMPLES[3936]=["Examinations interfere with the real purpose of education.","試験は教育の本当の目的を妨げる。","interfere"];
EXAMPLES[3937]=["What you need is, in a word, patience.","君に必要なものは、ひと言で言えば、忍耐力だ。","patience"];
EXAMPLES[3938]=["I am planning to attend the annual meeting.","年次会議に行く予定です。","annual"];
EXAMPLES[3939]=["The mountain is famous in myth and legend.","その山は神話や伝説でよく知られている。","myth"];
EXAMPLES[3940]=["The plan was supported by practically all the attendants.","その計画はほとんどすべての出席者に支持された。","practically"];
EXAMPLES[3941]=["Let's take time out to elaborate a strategy.","タイムをとって作戦を練ろう。","elaborate"];
EXAMPLES[3942]=["What was his motive for doing it?","彼はそれをした動機は何だったのだろう。","motive"];
EXAMPLES[3943]=["We have to reduce the cost to a minimum.","我々は原価を最小限に下げないといけない。","minimum"];
EXAMPLES[3944]=["It wasn't me, commissioner!","それは私じゃないよ、理事長！","commissioner"];
EXAMPLES[3945]=["You should go on to a technical college.","あなたは理科系の大学に進んだほうがいいよ。","technical"];
EXAMPLES[3947]=["Some people in the world suffer from hunger.","世界には飢えに苦しむ人々も居る。","hunger"];
EXAMPLES[3948]=["The perception of beauty is a moral test.","美の認識は倫理の検査となり得る。","perception"];
EXAMPLES[3949]=["How many days does a leap year have?","閏年って、何日あるんだっけ？","leap"];
EXAMPLES[3950]=["He was the strongest candidate for the position.","彼はその職の最も有力な候補者だった。","candidate"];
EXAMPLES[3951]=["This is the key to the whole mystery.","これが謎の全てを解く鍵だ。","mystery"];
EXAMPLES[3952]=["It is beneath my dignity to ask a favor.","恩恵を請うのは私の威厳に関わる。","dignity"];
EXAMPLES[3953]=["It is rude of you to say so.","そんなことを言うのは失礼よ。","rude"];
EXAMPLES[3954]=["Some people dislike the traditional New Year's ritual.","正月の伝統的な行事が嫌いな人もある。","ritual"];
EXAMPLES[3955]=["It is on the tip of my tongue.","言葉はのどまで出かかってるんだけど。","tip"];
EXAMPLES[3956]=["Why did you use up all the money?","君はなぜお金を使い果たしたのか。","use up"];
EXAMPLES[3957]=["She asked him to adjust the TV set.","彼女はテレビの調節を彼に頼んだ。","adjust"];
EXAMPLES[3958]=["My surname is Wan.","私の苗字はワンです。","Wan"];
EXAMPLES[3959]=["As long as it doesn't spoil the weekend!","週末が台無しになりさえしなければいいですよ。","spoil"];
EXAMPLES[3960]=["The English of this composition is too good.","この英作文はよくできすぎている。","composition"];
EXAMPLES[3961]=["There is no question as to her talent.","彼女の才能に関しては疑問の余地が無い。","talent"];
EXAMPLES[3962]=["This is the beginning of a new era.","これは新時代の幕開けです。","era"];
EXAMPLES[3963]=["What is your ultimate goal in your life?","あなたの人生の最終目的は何ですか。","ultimate"];
EXAMPLES[3964]=["The girl had a telescope in her hand.","その女の子は手に望遠鏡を持っていた。","telescope"];
EXAMPLES[3965]=["I must know where these quotations originate.","私はこれらの引用句の出典をどうしても知る必要がある。","originate"];
EXAMPLES[3966]=["Inhaling diesel exhaust is bad for our health.","ディーゼルの排気ガスは体に悪い。","exhaust"];
EXAMPLES[3967]=["Is it true that Tom has a twin?","トムに双子のきょうだいがいるって本当？","twin"];
EXAMPLES[3968]=["I knew her the instant I saw her.","私は彼女に会ったとたん誰だか分かった。","instant"];
EXAMPLES[3969]=["Do you have rain gear with you?","雨具をお持ちになりましたか。","gear"];
EXAMPLES[3970]=["They are willing to do it for you.","彼らはあなたのために快くそれをするでしょう。","willing"];
EXAMPLES[3971]=["The union was modest in its wage demands.","その組合の賃上げ要求は穏当だった。","wage"];
EXAMPLES[3972]=["People are taking sides on the abortion issue.","中絶問題で議論が二分しています。","abortion"];
EXAMPLES[3973]=["He is too smart not to know it.","彼はとても賢いのでそれを知らないはずはない。","smart"];
EXAMPLES[3974]=["I asked Mary what she'd like to do.","メアリーに何がしたいか聞いてみました。","she"];
EXAMPLES[3975]=["He dwelt on the complexities of modern life.","彼は現代生活の複雑性について長々と話した。","complexities"];
EXAMPLES[3976]=["He is a critic rather than a novelist.","彼は小説家というよりもむしろ評論家です。","critic"];
EXAMPLES[3977]=["There is a friendly atmosphere in the office.","オフィスにはなごやかな雰囲気がある。","friendly"];
EXAMPLES[3978]=["I overslept and consequently couldn't join them.","寝坊したため彼らと一緒に行けなかった。","consequently"];
EXAMPLES[3979]=["There is a fault in the electrical system.","電気系統に欠点があります。","electrical"];
EXAMPLES[3980]=["Will you please connect me with Mr Smith?","スミスさんにつないでくださいませんか。","connect"];
EXAMPLES[3981]=["His colleague was transferred to an overseas branch.","彼の同僚は海外の支店に転勤になった。","colleague"];
EXAMPLES[3982]=["He is rich enough to keep a servant.","彼は召し使いをおけるほど金持ちだ。","servant"];
EXAMPLES[3983]=["He was born and raised as a Muslim.","彼は、ムスリムとして生まれ育った。","Muslim"];
EXAMPLES[3984]=["The seeds of plants breathe all the time.","植物の種子は始終呼吸している。","seeds"];
EXAMPLES[3985]=["Picture books will cultivate the minds of children.","絵本は子供たちの頭を啓発する。","cultivate"];
EXAMPLES[3986]=["That man died of lung cancer a week ago.","あの男は一週間前に肺ガンで死んだ。","lung"];
EXAMPLES[3987]=["Please refrain from smoking, while the non-smoking signs are on.","禁煙サインがついているときは、おタバコはひかえて下さい。","refrain from"];
EXAMPLES[3988]=["The lord held absolute power over his subjects.","その君主は臣民に対して絶対の支配権を持っていた。","lord"];
EXAMPLES[3989]=["Do you want your permanent to look natural?","パーマは自然な感じにしますか。","permanent"];
EXAMPLES[3990]=["Red shows up well against a white background.","赤は白をバックにするとよく目立つ。","background"];
EXAMPLES[3991]=["I beg your pardon. What did you say?","すみません、何とおっしゃいましたか？","beg"];
EXAMPLES[3992]=["I was surprised at her immediate recognition of me.","私であることが彼女にすぐに分かったのには驚いた。","recognition"];
EXAMPLES[3993]=["I went to the lawyer for legal help.","法律上の援助を求めてその弁護士のところへ行った。","legal"];
EXAMPLES[3994]=["You are at liberty to leave any time.","君はいつ帰ってもいいよ。","liberty"];
EXAMPLES[3995]=["The writer is living in a log cabin.","その作家は丸太小屋に住んでいる。","log"];
EXAMPLES[3996]=["This new camera is a snap to use.","このカメラは使いやすい。","snap"];
EXAMPLES[3997]=["Steve told me the tale of his travels.","スティーブは私に旅行の話をしてくれた。","tale"];
EXAMPLES[3998]=["I am poor, whereas my brothers are very rich.","私は貧しい、それに対して私の兄弟たちはとても裕福だ。","whereas"];
EXAMPLES[3999]=["Confine your remarks to the matter we are discussing.","今話し合っている問題だけに発言を限定して下さい。","Confine"];
EXAMPLES[4000]=["It is beneath you to say such a thing.","そういうことを言うのは君らしくない。","beneath"];
EXAMPLES[4001]=["The picture has a charm of its own.","その絵には独特の魅力がある。","charm"];
EXAMPLES[4002]=["The excessive use of salt should be taboo.","塩を過剰に使うのは避けるべきだ。","excessive"];
EXAMPLES[4003]=["He is, on the whole, a satisfactory student.","彼は概して申し分のない学生である。","satisfactory"];
EXAMPLES[4004]=["We are in the era of atomic energy.","我々は今や原子力時代にある。","atomic"];
EXAMPLES[4005]=["The farmer is scattering seeds over the field.","農夫が畑に種を蒔いている。","scattering"];
EXAMPLES[4006]=["Please move to the rear of the bus.","バスの後方へお詰め願います。","rear"];
EXAMPLES[4007]=["Our party will resist to the bitter end.","わが党はこれに飽くまで反対します。","resist"];
EXAMPLES[4008]=["It is impossible to resolve the conflict.","その紛争を解決するのは不可能だ。","resolve"];
EXAMPLES[4009]=["Her air of innocence is apparent, not real.","彼女の純真げなそぶりは見せかけで本物ではない。","apparent"];
EXAMPLES[4010]=["It is important to eliminate the social unrest.","社会的不安を取り除くことが大切です。","eliminate"];
EXAMPLES[4012]=["Will you pray for me to be happy?","俺の幸せを祈ってくれてるの？","pray"];
EXAMPLES[4013]=["There is not a ray of truth in it.","それには真実のかけらもない。","ray"];
EXAMPLES[4014]=["I want to become a bisque doll maker.","私は将来ビスクドール作家になりたい。","maker"];
EXAMPLES[4015]=["My father serves in the Foreign Ministry.","私の父は外務省に勤めている。","Ministry"];
EXAMPLES[4016]=["The roof was blown off by the explosion.","屋根は爆発で吹き飛ばされた。","explosion"];
EXAMPLES[4017]=["There is no cure for the common cold.","ふつうのかぜに治療法はない。","cure"];
EXAMPLES[4018]=["The news had a great impact on us.","そのニュースは我々に大きな衝撃を与えた。","impact"];
EXAMPLES[4019]=["He is specializing in the study of economics.","彼が専攻している学問は経済学である。","economics"];
EXAMPLES[4020]=["The teacher acknowledged the pupil with a smile.","先生は生徒に気づいてにっこりと答えた。","pupil"];
EXAMPLES[4021]=["It's unusual for him to get up early.","彼が早起きするなんて珍しい。","unusual"];
EXAMPLES[4022]=["The novel is centered on the Civil War.","その小説は南北戦争を軸にしている。","Civil"];
EXAMPLES[4023]=["Where is the counter to pay my Bill?","会計の窓口はどこですか。","counter"];
EXAMPLES[4024]=["Are eggs a good source of protein?","卵にはタンパク質が豊富に含まれているんですか？","protein"];
EXAMPLES[4025]=["It's necessary that we come to a mutual understanding.","我々の相互理解が必要である。","mutual"];
EXAMPLES[4026]=["He refused to believe that she was guilty.","彼女の有罪を彼は信じようとはしなかった。","guilty"];
EXAMPLES[4027]=["It's impossible not to be fascinated by her beauty.","彼女の美しさに魅了されずにいることは不可能だ。","fascinated"];
EXAMPLES[4028]=["It is plain that you are to blame.","君が悪いことははっきりしている。","plain"];
EXAMPLES[4029]=["Janet sure knows how to stretch a dollar.","ジャネットは確かにどうやってやりくりするか知っている。","stretch"];
EXAMPLES[4030]=["He is what we call a pioneer.","彼はいわゆる先駆者だ。","pioneer"];
EXAMPLES[4031]=["The sweep of the times is changing rapidly.","時代の潮流が急速に変化している。","sweep"];
EXAMPLES[4032]=["He never made a display of his learning.","彼は決して自分の学問を誇示することは無かった。","display"];
EXAMPLES[4033]=["He is so aggressive that others avoid him.","彼はあまりにも性格が攻撃的で、人に避けられている。","aggressive"];
EXAMPLES[4034]=["The young woman was carrying an infant in her arms.","その若い女は腕に幼児を抱いていた。","infant"];
EXAMPLES[4035]=["I want to see her by any means.","私は何とかして彼女に会いたい。","means"];
EXAMPLES[4036]=["This is a poem written in Scottish dialect.","これはスコットランドの方言で書かれた詩です。","dialect"];
EXAMPLES[4037]=["What do you call this insect in English?","英語でこの昆虫を何といいますか。","insect"];
EXAMPLES[4038]=["The sunlight is painful in this time period.","この時間帯の日差しは痛いね。","painful"];
EXAMPLES[4039]=["The protection circuit is built into the system.","そのシステム中には保護回路が組み込まれています。","circuit"];
EXAMPLES[4040]=["The rebel concealed his ambition to destroy the regime.","反乱軍の兵士が政権を打倒する野望を隠していた。","regime"];
EXAMPLES[4041]=["I have made great sacrifices to come this far.","多大な犠牲を払って、ここまで来た。","sacrifices"];
EXAMPLES[4042]=["We must devise some means of escape.","何か逃げる手だてを考えねばならない。","devise"];
EXAMPLES[4043]=["My acquaintance introduced me to his intimate fellows.","私の知人が私を彼の親しい友人達に紹介した。","intimate"];
EXAMPLES[4044]=["Against the snow, the white rabbit was invisible.","雪の中で、その白兎の姿は見えなかった。","invisible"];
EXAMPLES[4045]=["Modern finance is becoming increasingly complicated and sophisticated.","現代の金融は一段と複雑かつ高度になってきている。","increasingly"];
EXAMPLES[4046]=["It was a relief to hear the news.","その知らせを聞いて安心した。","relief"];
EXAMPLES[4047]=["I can tell virtue and vice apart.","私には美徳と悪徳との区別がつく。","vice"];
EXAMPLES[4048]=["I travel to all parts of the globe.","私は世界中を旅行する。","globe"];
EXAMPLES[4049]=["We are subject to the Constitution of Japan.","我々は日本国憲法に従わないといけない。","Constitution"];
EXAMPLES[4050]=["It is essentially a question of time.","それは本質的に時間の問題だ。","essentially"];
EXAMPLES[4051]=["We must select one from among these applicants.","この応募の中から一人を選ばなくてはなりません。","select"];
EXAMPLES[4052]=["She deliberately ignored me on the street.","彼女はわざと通りで私のことを無視した。","deliberately"];
EXAMPLES[4053]=["The tide carried the boat out to sea.","潮流がその船を外海へと漂流させた。","tide"];
EXAMPLES[4054]=["Apart from the plot, the book interested me.","筋書きは別として、その本は私をひきつけた。","plot"];
EXAMPLES[4056]=["The country was industrialized very quickly.","その国は急速に工業化された。","industrialized"];
EXAMPLES[4057]=["He has a wealthy supporter behind him.","彼の背後には資産家が控えている。","supporter"];
EXAMPLES[4058]=["She had to part with her fur coat.","彼女は毛皮のコートを手放さなければならなかった。","fur"];
EXAMPLES[4059]=["People who are prone to aggression can be dangerous.","攻撃的な行動に出やすい人は、危険な人間になり得る。","aggression"];
EXAMPLES[4060]=["I'd like to confirm the hour of departure.","出発時刻を確認したいのですが。","confirm"];
EXAMPLES[4061]=["In Hawaii, you can cruise all year round.","ハワイで通年航行中できます。","cruise"];
EXAMPLES[4062]=["We have to stand up for minority rights.","我々は少数民族の権利を守らなければならない。","minority"];
EXAMPLES[4063]=["It is odd that he is so late.","彼がこんなに遅いのは変だ。","odd"];
EXAMPLES[4064]=["He dominates his family and makes all the decisions.","彼はその家を支配し、すべての決断をする。","dominates"];
EXAMPLES[4065]=["You have no obligation to help us.","あなたは我々を援助する必要はない。","obligation"];
EXAMPLES[4066]=["You have to blast your way out.","人垣をかき分けて出なくちゃね。","blast"];
EXAMPLES[4067]=["The assembly consisted of people concerned about human rights.","その集会は人権に関心を持つ人々の集まりだった。","assembly"];
EXAMPLES[4068]=["He had the nerve to ask for money.","彼はずうずうしくも金を貸せといった。","nerve"];
EXAMPLES[4069]=["We could not resist the force of his logic.","彼の理論だった説得力にはかなわなかった。","logic"];
EXAMPLES[4070]=["Rain doesn't depress people who like reading.","雨が降っても読書の好きな人は気がめいらない。","depress"];
EXAMPLES[4071]=["This is a weakness peculiar to young people.","これが若者特有の欠点だ。","peculiar"];
EXAMPLES[4072]=["I urge you to tell him the truth.","彼に対して本当のことを言うように強くお勧めします。","urge"];
EXAMPLES[4073]=["The institution was established in the late 1960s.","その機関は１９６０年代後半に設立された。","institution"];
EXAMPLES[4074]=["He wrote a letter with great facility.","彼はたやすく手紙を書いた。","facility"];
EXAMPLES[4075]=["The crew were all waiting for the news.","乗務員はみんなその知らせを待っていた。","crew"];
EXAMPLES[4076]=["He has an unpleasant look in his eyes.","あの男は目つきが悪い。","unpleasant"];
EXAMPLES[4077]=["Two, four, six, etc. are even numbers.","２、４、６などは偶数です。","etc"];
EXAMPLES[4078]=["There used to be an elementary school here.","ここにもとは小学校があった。","elementary"];
EXAMPLES[4079]=["They gave him both material and spiritual support.","彼らは物質的にも精神的にも彼を支えた。","spiritual"];
EXAMPLES[4080]=["The swallow is a sign of summer.","ツバメは夏の前触れだ。","swallow"];
EXAMPLES[4081]=["May I have the honor of asking you?","お尋ねしてもよろしいでしょうか。","honor"];
EXAMPLES[4082]=["There was an enormous traffic jam in downtown Kyoto.","京都の繁華街は交通渋滞がすごかった。","traffic jam"];
EXAMPLES[4083]=["We are inclined to stand up for him.","われわれは彼を支持したい気がする。","inclined"];
EXAMPLES[4084]=["I owe what I am today to you.","私の今日あるのは貴方のお陰です。","owe"];
EXAMPLES[4085]=["The people here are accustomed to the cold.","当地の人々は寒さに慣れている。","accustomed"];
EXAMPLES[4086]=["A large portion of the picture got wet.","絵の大部分が水に濡れてしまったな。","portion"];
EXAMPLES[4087]=["They still haven't found a buyer for that house.","あの家はまだ買い手がつかない。","buyer"];
EXAMPLES[4088]=["In a sense, I can understand his confusion.","ある程度は彼の困惑も理解できる。","confusion"];
EXAMPLES[4089]=["She will be a good companion for you.","彼女は君のよい話し相手になるだろう。","companion"];
EXAMPLES[4090]=["A soldier often has to confront danger.","兵士はしばしば危険に直面しなければならない。","confront"];
EXAMPLES[4091]=["The army was called to suppress the revolt.","その反乱を鎮圧するために軍隊の出動が要請された。","suppress"];
EXAMPLES[4092]=["You will soon cease to think of her.","まもなく彼女のことを思わなくなるでしょう。","cease"];
EXAMPLES[4093]=["There's a pile of letters on the table.","テーブルには手紙の山がある。","pile"];
EXAMPLES[4094]=["I read the book from cover to cover.","私はその本を全編残らず読んだ。","cover"];
EXAMPLES[4095]=["We are distinct from each other in taste.","私達は趣味がまったく違うのだ。","distinct"];
EXAMPLES[4096]=["This has been designated a conservation area.","この地域は保全地域に指定されています。","conservation"];
EXAMPLES[4097]=["On behalf of the company, I welcome you.","一同を代表して、歓迎の意を表します。","behalf"];
EXAMPLES[4098]=["We must see the matter in its proper perspective.","私たちは正しい見方でその問題を見なくてはならない。","perspective"];
EXAMPLES[4099]=["No two words are identical in meaning.","全く意味の等しい言葉はない。","identical"];
EXAMPLES[4100]=["He is an executive in an insurance company.","彼は保険会社の重役である。","executive"];
EXAMPLES[4101]=["Who was the last to reach the goal?","最後にゴールに入ったのは誰ですか。","goal"];
EXAMPLES[4102]=["Do you know if he has a girlfriend?","あの人に彼女がいるかどうか知ってる？","girlfriend"];
EXAMPLES[4103]=["It takes time to get over a divorce.","離婚から立ち直るには時間がかかる。","divorce"];
EXAMPLES[4104]=["The plan met with opposition from the inhabitants.","その計画は住民の反対にあった。","inhabitants"];
EXAMPLES[4105]=["The passive man seldom, if ever, expresses himself.","消極的なその男はめったに自己表現しない。","passive"];
EXAMPLES[4106]=["This word has a subtle nuance to it.","その言葉には微妙なニュアンスがある。","subtle"];
EXAMPLES[4107]=["The police are in pursuit of the runaway.","警察は、逃亡者を追跡している。","pursuit"];
EXAMPLES[4108]=["He refused to get involved in the dispute.","彼はそのもめごとに関わり合いを持つ事を拒んだ。","dispute"];
EXAMPLES[4109]=["He is not equal to her in intelligence.","彼は知力では彼女に及ばない。","intelligence"];
EXAMPLES[4110]=["This is a bow for a strong person.","これは強い人が使う弓です。","bow"];
EXAMPLES[4111]=["I firmly believe that your time will come.","私はあなたの番が来ると確信しているよ。","firmly"];
EXAMPLES[4112]=["Try not to buy anything on impulse today.","今日は衝動買いしないように気を付けなくちゃ。","impulse"];
EXAMPLES[4113]=["I thought you were going steady with Tom.","トムと付き合っているんだと思ってた。","steady"];
EXAMPLES[4114]=["In comparison with this, that is far better.","これと比較すると、あのほうがはるかによい。","comparison"];
EXAMPLES[4115]=["The communist got his dependable supporter at last.","ついに、その共産主義者は手づよい味方を得た。","communist"];
EXAMPLES[4116]=["The colony declared independence and became a republic.","その植民地は独立を宣言し、共和国となった。","republic"];
EXAMPLES[4117]=["Let's proceed with the items on the agenda.","議題に上っている項目の議論を続けましょう。","proceed"];
EXAMPLES[4118]=["It is said that he is still alive.","彼はまだ生きているそうだ。","alive"];
EXAMPLES[4119]=["How dare you talk to me like that!","よくもまあそんな口のきき方ができるな。","dare"];
EXAMPLES[4120]=["Effectively dealing with competition is an important part of life.","競争に効果的に対処するのは、人生の重要な部分である。","Effectively"];
EXAMPLES[4121]=["He is dead to all sense of shame.","彼はまったくの恥知らずだ。","shame"];
EXAMPLES[4122]=["This store is operated on a cash basis.","この店は現金取り引きが原則です。","cash"];
EXAMPLES[4123]=["To say so should not diminish his importance.","そう言ったからといって彼の重要性が低下するわけではない。","diminish"];
EXAMPLES[4124]=["I try to be positive all the time.","常に前向きでいようと心掛けているんだ。","positive"];
EXAMPLES[4125]=["The TV remote control is under the couch.","テレビのリモコンがソファーの下にある。","remote"];
EXAMPLES[4126]=["That Japanese word has no equivalent in English.","その日本語に対応する英語はない。","equivalent"];
EXAMPLES[4127]=["He was the ruler of the Inca Empire.","インカ帝国の支配者でした。","Empire"];
EXAMPLES[4128]=["They made the pilot fly the Navy helicopter.","彼らはパイロットに海軍のヘリコプターを操縦させた。","Navy"];
EXAMPLES[4129]=["The street was empty of people and traffic.","その通りは人や車の往来がなかった。","empty"];
EXAMPLES[4130]=["He gave them the benefit of his insight.","彼は自分の洞察力という利益を彼らに与えてやった。","insight"];
EXAMPLES[4131]=["Our society is held up by verbal communication.","私たちの社会は、言葉によるコミュニケーションによって、支えられている。","verbal"];
EXAMPLES[4132]=["The newly married couple walked hand in hand.","その新婚夫婦は手をつないで歩いた。","newly"];
EXAMPLES[4133]=["The cop was shot on his beat.","その警察は巡回中に撃たれた。","cop"];
EXAMPLES[4134]=["You have to have a new crown.","新しいクラウンをかぶせる必要があります。","crown"];
EXAMPLES[4135]=["Sometimes it's enough simply to nod in response.","返事は、頷くだけで事足りる時もあります。","nod"];
EXAMPLES[4136]=["The return on the investment will be high.","投資の収益は高いだろう。","investment"];
EXAMPLES[4137]=["These things constitute a balanced meal.","これらのものがバランスのとれた食事を構成する。","constitute"];
EXAMPLES[4138]=["He put all his fortune in the enterprise.","彼は全財産をその事業につぎ込んだ。","enterprise"];
EXAMPLES[4139]=["Please initial and send back to us.","イニシャルをサインしてご返送ください。","initial"];
EXAMPLES[4140]=["I am working in the Overseas Operations Division.","私は海外事業部で働いています。","Division"];
EXAMPLES[4141]=["The two streets run parallel to one another.","２本の道路は平行に走っている。","parallel"];
EXAMPLES[4142]=["He should be given preference over the others.","彼は他の人より優先されるべきだ。","preference"];
EXAMPLES[4143]=["Don't take it literally. He is inclined to exaggerate.","そんなこと真に受けちゃだめだよ。彼は大袈裟に言う傾向があるから。","literally"];
EXAMPLES[4144]=["The room was as still as the grave.","部屋は墓場のように静かだった。","grave"];
EXAMPLES[4145]=["I want to look at the reference books.","参考書を見たいのですが。","reference"];
EXAMPLES[4146]=["It's going to get steadily hotter from now.","これから段々暖かくなって行くでしょう。","steadily"];
EXAMPLES[4147]=["It was a profession of his own choosing.","それは彼が自分で選んだ職業だった。","profession"];
EXAMPLES[4148]=["My father is going to undergo an operation.","父は手術を受ける事になっている。","undergo"];
EXAMPLES[4149]=["This is what I found in the cave.","これは私が洞窟の中で見つけたものです。","cave"];
EXAMPLES[4150]=["The boy took a fancy to the dog.","その少年はその犬が大好きになった。","fancy"];
EXAMPLES[4151]=["He left in the blink of an eye.","彼があっと言う間に飛び出しました。","blink"];
EXAMPLES[4152]=["We think little of him as a scholar.","私たちは彼を学者としてたいした物とは思わない。","scholar"];
EXAMPLES[4153]=["We can never get rid of the past.","私達は過去から逃れることはできない。","rid"];
EXAMPLES[4154]=["It was a great privilege working with you.","あなたと仕事ができて光栄でした。","privilege"];
EXAMPLES[4155]=["Reading aloud was a great effort for him.","音読は彼にとってたいへん骨の折れる仕事であった。","aloud"];
EXAMPLES[4156]=["Is the master of the house at home?","ご主人はご在宅ですか。","master"];
EXAMPLES[4157]=["Every rating is always a five.","全ての評価がいつも五だ。","rating"];
EXAMPLES[4158]=["It's a living being, so of course it shits.","生き物なんだからウンコするに決まってんだろ。","shits"];
EXAMPLES[4159]=["You can weigh your baggage in this balance.","このはかりであなたの荷物を量っていいですよ。","weigh"];
EXAMPLES[4160]=["The jewel was found in an unlikely place.","宝石は思いがけない場所で見つかった。","unlikely"];
EXAMPLES[4161]=["If you use a computer, you can retain information.","コンピューターを使えば情報を保持することができる。","retain"];
EXAMPLES[4162]=["The Bill was passed by an overwhelming majority.","議案は圧倒的多数で可決された。","overwhelming"];
EXAMPLES[4163]=["The massive flood paralyzed the local transportation network.","大洪水で現地の交通網が麻痺した。","massive"];
EXAMPLES[4164]=["It is desirable that nobody should be hurt.","誰もけがをしないことが望ましい。","desirable"];
EXAMPLES[4165]=["He sent in his application to the office.","彼は事務所に願書を提出した。","application"];
EXAMPLES[4166]=["The country is in the grasp of the enemy.","その国は敵の支配下にある。","grasp"];
EXAMPLES[4167]=["Some diseases are caused by a defective gene.","一部の疾患の原因は欠陥遺伝子です。","gene"];
EXAMPLES[4168]=["The pupils of the eyes contract in sunlight.","瞳は日のあたる所では収縮する。","contract"];
EXAMPLES[4169]=["Nuclear power is used to generate electricity.","原子力が発電に使われている。","generate"];
EXAMPLES[4170]=["Regardless what he does, he does it well.","彼は何をやっても上手くやる。","Regardless"];
EXAMPLES[4171]=["Bury your face into the soft fur.","フワフワの毛皮に顔を埋めるんだ。","Bury"];
EXAMPLES[4172]=["Not many people actually fall into the pit.","実際に落とし穴に落ちる人なんてそうそういない。","pit"];
EXAMPLES[4173]=["He is not a friend, but an acquaintance.","友達というほどではないが知り合いだ。","acquaintance"];
EXAMPLES[4174]=["The rumor proved to be an absolute lie.","うわさは全くのうそであることがわかった。","absolute"];
EXAMPLES[4175]=["Sorrow exists precisely because there is happiness.","悲しみあってこその幸せだ。","precisely"];
EXAMPLES[4176]=["He ran an ad in the paper.","彼は新聞に広告を載せた。","ad"];
EXAMPLES[4177]=["She is made to be an editor.","彼女は編集の仕事にむいている。","editor"];
EXAMPLES[4178]=["You can stay with us for the time being.","とりあえず君は私たちのところにいてもいいよ。","for the time being"];
EXAMPLES[4179]=["I have no appetite at all this summer.","今年の夏は全く食欲がない。","appetite"];
EXAMPLES[4180]=["Racial problems are often the cause of social unrest.","人種問題はしばしば社会不安のもとになる。","Racial"];
EXAMPLES[4181]=["I am not gay, but my boyfriend is.","私はゲイじゃないけど、私の彼はゲイだよ。","gay"];
EXAMPLES[4182]=["I cannot give you a definite answer today.","きょうは明確な答えを出すことはできません。","definite"];
EXAMPLES[4183]=["This generous offer may be a mere pose.","この寛大な申し出は単なる見せかけかもしれない。","pose"];
EXAMPLES[4184]=["I got a bang out of her party.","彼女のパーティーは実に楽しかった。","bang"];
EXAMPLES[4185]=["They burst out into a storm of abuse.","彼らは激しくののしり始めた。","burst"];
EXAMPLES[4186]=["I know the real reason for his absence.","私は彼が欠席した本当の理由を知っている。","absence"];
EXAMPLES[4187]=["He is much inferior to me in English.","彼は英語ではわたしよりずっと劣っている。","inferior"];
EXAMPLES[4188]=["It is evident that the man is wrong.","その男が間違っているのは明らかだ。","evident"];
EXAMPLES[4189]=["The audience was impressed by his profound lecture.","聴衆は彼の意味深い講演に感銘を受けた。","profound"];
EXAMPLES[4190]=["You have to turn in the reports on Monday.","君は月曜日に報告書を提出しなければならない。","turn in"];
EXAMPLES[4191]=["I assure you that I won't be late.","遅刻しない事、うけあい。","assure"];
EXAMPLES[4192]=["Yes, sorry, I forgot to acknowledge it.","ええ、届いたのをお知らせするのを忘れてしまってすみません。","acknowledge"];
EXAMPLES[4193]=["I want to gaze at this scenery forever.","私はこの景色をずっと眺めていたい。","gaze"];
EXAMPLES[4194]=["That is really a load off my mind.","それが私の心からなくなった重圧だ。","load"];
EXAMPLES[4195]=["It is inevitable even if he is criticized.","彼を非難しても仕方のないことだ。","inevitable"];
EXAMPLES[4196]=["I saw her at it with great enthusiasm.","私は彼女が熱心にやっているところを見た。","enthusiasm"];
EXAMPLES[4197]=["What kinds of animals will evolve from us?","私たちが進化したらどんな種の動物になるだろうか。","evolve"];
EXAMPLES[4198]=["Tom is not a lazy boy. As a matter of fact, he works hard.","トムは怠け者の少年ではありません。それどころかよく働きます。","As a matter of fact"];
EXAMPLES[4199]=["Commodity tax is not included in the price.","この価格には、物品税は含まれていません。","Commodity"];
EXAMPLES[4200]=["Do you know if Grace is at home?","グレースが家にいるかどうか知っていますか。","Grace"];
EXAMPLES[4201]=["A true scientist would not distort facts.","真の科学者なら、事実をゆがめるようなことはしないだろう。","distort"];
EXAMPLES[4202]=["The Arctic is the area around the North Pole.","北極圏とは北極周辺の地域の事である。","Arctic"];
EXAMPLES[4203]=["I can't understand his obsession with baseball.","なぜ彼があんなに野球に夢中になれるのか理解できない。","obsession"];
EXAMPLES[4204]=["There is nothing for it but to obey.","従うよりほかしかたない。","obey"];
EXAMPLES[4205]=["The chairman did not rule out the possibility of a disagreement.","議長は意見が不一致に終る可能性を排除しなかった。","rule out"];
EXAMPLES[4206]=["Tom doesn't like people who manipulate others.","トムは他人を操る癖のある者が気に食わない。","manipulate"];
EXAMPLES[4207]=["Sue and I have always got on well.","スーと私はいつも仲良くやってきた。","Sue"];
EXAMPLES[4208]=["He used to be a man of fortune.","彼は昔大金持ちだった。","fortune"];
EXAMPLES[4209]=["He carved a Buddhist image out of wood.","彼は木から仏像を彫った。","Buddhist"];
EXAMPLES[4210]=["The rumor is not true as far as I know.","噂は僕の知る限り本当ではない。","as far as I know"];
EXAMPLES[4211]=["Extract an essence from the bark of a tree.","樹皮からエキスを抽出する。","Extract"];
EXAMPLES[4212]=["You look as if it were none of your business.","君はまるで人ごとみたいな顔をしているね。","as if"];
EXAMPLES[4214]=["No one shall be held in slavery.","何びとも奴隷の状態に留め置かれてはならない。","slavery"];
EXAMPLES[4215]=["This avenue is wide but not very long.","この通りは広いが、あまり長くない。","avenue"];
EXAMPLES[4216]=["I reached my destination in a week.","私は１週間で目的地についた。","destination"];
EXAMPLES[4217]=["Blue lines on the map designate rivers.","地図上の青い線は川を示す。","designate"];
EXAMPLES[4218]=["The first of January is Public Domain Day.","1月1日はパブリックドメインの日です。","Domain"];
EXAMPLES[4219]=["The toothache made his face swell up.","歯痛のために彼の顔ははれあがった。","swell"];
EXAMPLES[4220]=["This blog covers topics that centre on information infrastructure.","このブログは情報インフラを中心としたトピックを取り上げています。","infrastructure"];
EXAMPLES[4221]=["I thought you were going to provoke Tom.","あなたはトムを挑発するつもりなのだと思っていました。","provoke"];
EXAMPLES[4222]=["Serving people is his sole purpose in life.","人々に奉仕することが、彼の人生の唯一の目的だ。","sole"];
EXAMPLES[4223]=["The convict was pardoned after serving his sentence.","その囚人は刑期に服した後赦免された。","convict"];
EXAMPLES[4224]=["You should apply for that post.","君はその職に応募すべきだ。","apply for"];
EXAMPLES[4225]=["What with fatigue and hunger, he was faint.","疲労やら飢えやらで彼は目眩を感じた。","fatigue"];
EXAMPLES[4226]=["The index rose 4% from the preceding month.","指標は前月比４％上昇した。","preceding"];
EXAMPLES[4227]=["It's very decent of you to help me.","お手伝いくださってどうもありがとう。","decent"];
EXAMPLES[4228]=["She is now an utter stranger to me.","彼女は今では私には全くの他人です。","utter"];
EXAMPLES[4229]=["Our teacher is at once stern and kindly.","我々の先生は厳しくもあり、かつ優しくもある。","stern"];
EXAMPLES[4230]=["I got him to polish my shoes.","私は彼に靴を磨いてもらった。","polish"];
EXAMPLES[4231]=["I will accept the work, provided that you help me.","あなたが私を助けてくださるならば、その仕事を引き受けます。","provided that"];
EXAMPLES[4232]=["The weather forecast is not reliable at all.","天気予報はまったく当てにならない。","forecast"];
EXAMPLES[4233]=["People tend to look at others with bias.","人々は他人を偏見で見がちだ。","tend"];
EXAMPLES[4234]=["The rules require us all to be present.","規則で私達は全員出席しなくてはならない。","require"];
EXAMPLES[4235]=["The pain has lessened a little.","痛みが少し減りました。","lessened"];
EXAMPLES[4236]=["I have a tumor.","私、腫瘍があるんだ。","tumor"];
EXAMPLES[4237]=["You must observe the rules of the dormitory.","寮の規則は守らなければならない。","dormitory"];
EXAMPLES[4238]=["Do you know how to pronounce this word?","この単語の発音の仕方を知っていますか。","pronounce"];
EXAMPLES[4239]=["He thrust the door open and marched in.","彼はドアをぐいと押し開けて入ってきた。","thrust"];
EXAMPLES[4240]=["The teacher distributed the handouts to the students.","先生は生徒たちにプリントを配布した。","handouts"];
EXAMPLES[4241]=["A person who is addicted to work is called a workaholic.","仕事中毒にかかっている人はワーカホリックと呼ばれている。","addicted"];
EXAMPLES[4242]=["I learned that when I was in kindergarten.","それ習ったの、私が幼稚園の時だよ。","kindergarten"];
EXAMPLES[4243]=["The price of this used car is reasonable.","この中古車の価格は手ごろだ。","reasonable"];
EXAMPLES[4244]=["It can accommodate as many as ten people.","１０人も泊まることができる。","accommodate"];
EXAMPLES[4245]=["The cause of the accident is still obscure.","事故原因はまだはっきりしていない。","obscure"];
EXAMPLES[4246]=["His seat in the plane was on the aisle.","機内での彼の席は通路側だった。","aisle"];
EXAMPLES[4247]=["There is no reason why he should resign.","彼が辞職しなければならない理由はない。","resign"];
EXAMPLES[4248]=["His acquaintance runs a grocery in the country.","彼の知人が田舎で雑貨屋を経営している。","grocery"];
EXAMPLES[4249]=["It has taken a toll on his body.","それは彼の身に応えだした。","toll"];
EXAMPLES[4250]=["Do you wish to make any other transaction?","続けてお取り引きなさいますか。","transaction"];
EXAMPLES[4251]=["Shoes are stiff when they are new.","靴は新しい間は硬い。","stiff"];
EXAMPLES[4252]=["You have to put up with all these noises.","君はこれらすべての騒音を我慢しなくてはならない。","put up with"];
EXAMPLES[4253]=["Nothing could induce him to change his mind.","彼に決心を変える気にさせる事はできなかった。","induce"];
EXAMPLES[4254]=["My house is designed to withstand an earthquake.","私の家は地震に堪えるように設計されている。","withstand"];
EXAMPLES[4256]=["He did it in only a fraction of a second.","彼は１秒のほんの何分の１かでそれをした。","fraction"];
EXAMPLES[4257]=["I would rather die than conceal my belief.","自分の信念を隠すくらいなら死んだほうがましだ。","conceal"];
EXAMPLES[4258]=["The new model will retail for 30,000 yen.","新型は小売価格３万円で販売される。","retail"];
EXAMPLES[4259]=["Isolation is the common lot of man.","孤独は人間共通の運命だ。","Isolation"];
EXAMPLES[4260]=["I'm looking forward to seeing you again before long.","近々またお会いできるのを楽しみに待ってます。","before long"];
EXAMPLES[4261]=["He is working in the field of biology.","彼は生物学の分野で研究している。","biology"];
EXAMPLES[4262]=["For all his wealth, he is not happy.","あれほど金を持ちながら彼は幸福でない。","wealth"];
EXAMPLES[4263]=["The bridge will be completed by the end of this year.","橋は今年末までには完成されるだろう。","by the end of"];
EXAMPLES[4264]=["I don't have a prejudice against foreign workers.","外国人労働者に偏見は持っていません。","prejudice"];
EXAMPLES[4265]=["Is there a souvenir shop in the hotel?","ホテルの中に土産品店はありますか？","souvenir"];
EXAMPLES[4266]=["It is quite a hard thing to bring up a child.","子供を育てることはかなり難しいことだ。","bring up"];
EXAMPLES[4267]=["If it gets that bad, replace the supervisor.","ほんとにまずいなら監督交代だよ。","supervisor"];
EXAMPLES[4268]=["A lot of students struggle with math in school.","学校の数学で悪戦苦闘する生徒も多いです。","struggle"];
EXAMPLES[4269]=["I want quick action subsequent to the decision.","決定の後すみやかに実行に移して欲しい。","subsequent"];
EXAMPLES[4270]=["Japanese love to soak in a hot tub before bed.","日本人は寝る前に熱い湯につかるのが好きです。","soak"];
EXAMPLES[4271]=["You had better supplement your diet with vitamins.","あなたの食事にはビタミンを補うほうがよい。","supplement"];
EXAMPLES[4272]=["Because of the drought, the grass has withered.","日でりのために草が枯れた。","drought"];
EXAMPLES[4273]=["The company was forced to lay off many employees.","その会社は多くの従業員を解雇せざるをえなかった。","lay off"];
EXAMPLES[4274]=["Microwaves penetrate the food in the oven.","マイクロ波はオーブンの中の食物を突き抜ける。","penetrate"];
EXAMPLES[4275]=["We should conform to the customs of society.","私たちは社会の習慣に従わなければならない。","conform"];
EXAMPLES[4276]=["When goods are scarce, sellers have the advantage.","品物が少ないときには売り手が有利だ。","scarce"];
EXAMPLES[4277]=["Such a trivial thing is out of the question.","そんな些細な事は問題外だ。","trivial"];
EXAMPLES[4278]=["He made a thorough analysis of the problem.","彼はその問題を徹底的に分析した。","thorough"];
EXAMPLES[4279]=["The most visible forms of aggression are often seen between prey and predator.","攻撃性のもっとも顕著なタイプは捕食者と被食者間によく見られる。","predator"];
EXAMPLES[4280]=["The meal includes dessert as well as beverage.","その食事には飲み物だけでなくデザートも含まれています。","beverage"];
EXAMPLES[4281]=["The Emperor shall be the symbol of the State.","天皇は国家の象徴である。","Emperor"];
EXAMPLES[4282]=["The value of the yen has soared.","円の価値が急騰した。","soared"];
EXAMPLES[4283]=["I was embarrassed when he talked to me.","彼に話し掛けられたときまごついてしまった。","embarrassed"];
EXAMPLES[4284]=["Because of the famine, the cattle starved to death.","食糧不足のため、家畜が餓死した。","famine"];
EXAMPLES[4285]=["I found this book in a secondhand bookstore.","ぼくはこの本を古本屋で見つけた。","secondhand"];
EXAMPLES[4286]=["The college has a placement bureau for students.","その大学には学生のための就職課がある。","bureau"];
EXAMPLES[4287]=["This custom became extinct a long time ago.","この習慣は絶えて久しい。","extinct"];
EXAMPLES[4288]=["This shows his loyalty to his friends.","このことは友人に対する彼の誠実さを示すものだ。","loyalty"];
EXAMPLES[4289]=["Roast chicken is one of my favorite dishes.","ローストチキンは大好きな料理の１つです。","Roast"];
EXAMPLES[4290]=["I will go along with your plan.","私はあなたの計画に同調します。","along with"];
EXAMPLES[4291]=["A teacher should never make fun of a pupil who makes a mistake.","教師は、間違いをする生徒を決してからかってはならない。","make fun of"];
EXAMPLES[4292]=["You must conquer your fear of the dark.","君は暗闇の恐怖を克服しなければならない。","conquer"];
EXAMPLES[4293]=["Deaf people can converse in sign language.","聾者は手話で会話ができる。","converse"];
EXAMPLES[4294]=["You'd better revise history for the exam.","試験に備えて歴史を復習しなさい。","revise"];
EXAMPLES[4295]=["I never dip my sushi in soy sauce.","寿司に醤油なんてつけないわ。","dip"];
EXAMPLES[4296]=["I think Tom is a little too optimistic.","トムはちょっと楽観的過ぎると思う。","optimistic"];
EXAMPLES[4297]=["Keep your room as neat as you can.","自分の部屋は出来るだけきちんとしておきなさい。","neat"];
EXAMPLES[4298]=["My driver's license will expire next week.","私の運転免許証は来週、期限が切れる。","expire"];
EXAMPLES[4299]=["I have two passes to the Imperial Theater.","私は帝国劇場の無料入場券を２枚持っている。","Imperial"];
EXAMPLES[4300]=["The hierarchy of rank has long been fixed.","階級組織は長い間固定されてきた。","hierarchy"];
EXAMPLES[4301]=["If the trees on that hill are cut down, you'll see erosion pretty quickly.","もしあの丘の木々が切り倒されたら、急速に浸食を見ることになるだろう。","erosion"];
EXAMPLES[4302]=["This cuisine is seasoned to evoke the esprit of Paris.","このお料理は、パリのエスプリを意識して、味付けしてみました。","evoke"];
EXAMPLES[4303]=["If it's a chemistry, leave it to me!","化学のことなら任せて！","chemistry"];
EXAMPLES[4304]=["All her imaginary happiness vanished in a moment.","彼女が心に描いていた幸せのすべてが一瞬のうちに消えてしまった。","vanished"];
EXAMPLES[4305]=["I was deeply impressed with the medieval music.","私はその中世の音楽に深い感銘を受けた。","medieval"];
EXAMPLES[4306]=["You must set about your business in earnest.","あなたは真剣に自分の仕事にとりかからねばならない。","earnest"];
EXAMPLES[4307]=["Can you get by on your wages?","今の給料でやっていけるのか？","get by"];
EXAMPLES[4308]=["The savage in man is never quite eradicated.","人間の野蛮性は決して根絶できない。","savage"];
EXAMPLES[4309]=["He says things on the spur of the moment.","その場限りのことを言う。","spur"];
EXAMPLES[4310]=["With a weak beat, it continues to bleed.","臆病な鼓動とともに血はにじみ続ける。","bleed"];
EXAMPLES[4311]=["Poor eyesight is a handicap to a sportsman.","スポーツマンにとって視力が悪いのは不利だ。","eyesight"];
EXAMPLES[4312]=["Try to utilize your leisure for reading.","余暇を読書に利用するように努めなさい。","utilize"];
EXAMPLES[4313]=["It is wrong to aim at fame only.","名声だけを目的にするのは間違っている。","fame"];
EXAMPLES[4314]=["Is there any student accommodation with meals included?","食事付きの学生マンションってありますか？","accommodation"];
EXAMPLES[4315]=["Millions of people starve to death every year.","毎年何百万という人が飢えで死んでいる。","starve"];
EXAMPLES[4316]=["There is usually an organ in a church.","教会には普通オルガンがあります。","organ"];
EXAMPLES[4317]=["Pick on somebody your own size, you bully.","弱いものいじめはよせ、このごろつきめが！","bully"];
EXAMPLES[4318]=["He may well just say something ambiguous again.","彼はまた曖昧な事を言うかも知れない。","ambiguous"];
EXAMPLES[4319]=["This product is an intelligent integrated information system.","このプロダクトはインテリジェント総合情報システムです。","integrated"];
EXAMPLES[4320]=["He does not have a particle of honesty in him.","彼には正直のかけらもない。","particle"];
EXAMPLES[4321]=["The queen was wearing a magnificent silver dress.","女王は華麗な銀色のドレスを着ていた。","magnificent"];
EXAMPLES[4322]=["My favorite pastime is strolling along the shore.","私の一番の気晴らしは海岸を散歩することです。","pastime"];
EXAMPLES[4323]=["You should enrich your mind when young.","若い時に心を豊かにするべきだ。","enrich"];
EXAMPLES[4324]=["Please cancel my order and refund the money.","注文をキャンセルしますので、返金してください。","refund"];
EXAMPLES[4325]=["Germs are too tiny for our eyes to see.","細菌は小さすぎて我々の眼には見えない。","Germs"];
EXAMPLES[4326]=["I don't know the origin of the rumor.","私はその噂の元は知りません。","rumor"];
EXAMPLES[4327]=["He is descended from a musical family.","彼は、音楽的家系の出である。","descended"];
EXAMPLES[4328]=["What he said is irrelevant to the matter.","彼の言ったことはその問題に関係ない。","irrelevant"];
EXAMPLES[4329]=["He is endowed with a sense of humor.","彼は生来ユーモアの感覚に恵まれている。","endowed"];
EXAMPLES[4330]=["The police said they found Tom's fingerprints there.","警察が言うには、トムの指紋をそこで見つけたんだって。","fingerprints"];
EXAMPLES[4331]=["This vending machine takes only hundred-yen coins.","この販売機は百円硬貨しか使えない。","vending machine"];
EXAMPLES[4332]=["Compile an essay on that topic within a fixed number of letters.","それについて、決められた字数以内に作文を纏める。","Compile"];
EXAMPLES[4333]=["Compassion is the basis of all morality.","あらゆる道徳の基礎は同情である。","Compassion"];
EXAMPLES[4334]=["He went red in the face with rage.","満面朱をそそいで怒った。","rage"];
EXAMPLES[4335]=["Tom seems to be unable to interact normally with other people.","トムは、他の人と普通に付き合うことができないようです。","interact"];
EXAMPLES[4336]=["This song was written by Foster.","この歌はフォスターが作ったものだ。","Foster"];
EXAMPLES[4337]=["Work hard, and your salary will be raised by degrees.","一生懸命働きなさい、そうすれば君の給料はだんだん上がるだろう。","by degrees"];
EXAMPLES[4338]=["Where there is happiness there must be sorrow.","悲しみあってこその幸せだ。","sorrow"];
EXAMPLES[4339]=["He could not approve of my going there.","彼は私がそこへ行くのを許すわけにはいかなかった。","approve"];
EXAMPLES[4340]=["I have a mind to undertake the work.","その仕事を引き受けようと思っている。","undertake"];
EXAMPLES[4341]=["They paid a high compliment to the speaker.","彼らは、弁士を大いにほめた。","compliment"];
EXAMPLES[4342]=["I've got to hang up now. Someone is waiting to use the phone.","もう電話を切らなくてはなりません。電話が空くのを待っている人がいるのです。","hang up"];
EXAMPLES[4343]=["An overwhelming part of our behavior is learned.","私たちの行動の圧倒的な部分は学んで身についたものだ。","overwhelming"];
EXAMPLES[4344]=["The police forced a confession from her.","警察は彼女を無理やり白状させた。","confession"];
EXAMPLES[4345]=["We've got to break out tonight or I'll go crazy!","何としても今晩脱獄するんだ。さもなきゃ気が狂ってしまう。","break out"];
EXAMPLES[4346]=["How did you pull off that agreement?","どうやってあの契約を成立させたんですか。","pull off"];
EXAMPLES[4347]=["He used the chopsticks in an awkward way.","彼は不器用な手つきではしをつかっていた。","awkward"];
EXAMPLES[4348]=["The bear is quite tame and doesn't bite.","その熊はとても飼い慣らされていて噛みついたりしない。","tame"];
EXAMPLES[4349]=["It is said that adolescent friendships do not often last.","青年期友情は長続きしないことが多いと言われる。","adolescent"];
EXAMPLES[4350]=["They climbed to the top of a cliff.","彼らは、崖のてっぺんまで登った。","cliff"];
EXAMPLES[4351]=["He had the ambition to be prime minister.","彼には総理大臣になりたいという野心があった。","ambition"];
EXAMPLES[4352]=["I am going to apply for a scholarship.","奨学金を申し込むつもりだよ。","scholarship"];
EXAMPLES[4353]=["She was angry, but she spoke with restraint.","彼女は怒っていたが、それをおさえて話をした。","restraint"];
EXAMPLES[4354]=["After running up the hill, I was completely out of breath.","丘を駆け登った後、私は完全に息切れしていた。","out of breath"];
EXAMPLES[4355]=["That ugly butcher's spouse resembles that one imaginary monster.","その醜い肉屋の旦那はあの想像上の怪物に似ている。","spouse"];
EXAMPLES[4356]=["We will be willing to make a deal with you after the auction.","競売の後で喜んで取り引きしましょう。","be willing to"];
EXAMPLES[4357]=["Rapid industrialization could shrink our rivers even further.","急激な工業化により、河川はさらに縮小する可能性がある。","shrink"];
EXAMPLES[4358]=["A water molecule has two hydrogen atoms and one oxygen atom.","水分子は、２個の水素原子と１個の酸素原子からなる。","molecule"];
EXAMPLES[4359]=["The next step was to sign the document.","次の段階は、その書類に署名することだった。","document"];
EXAMPLES[4360]=["He is taking a nap half the time.","彼はたいていうたた寝をしている。","nap"];
EXAMPLES[4361]=["Every one of us is more or less interested in art.","私たちは誰でも、多かれ少なかれ芸術に興味を持っている。","more or less"];
EXAMPLES[4362]=["It is rather difficult to assemble a watch.","時計を組み立てるのはちょっと難しい。","assemble"];
EXAMPLES[4363]=["He had an injection prior to the operation.","手術の前に彼は注射をされた。","injection"];
EXAMPLES[4364]=["A fund was set up to preserve endangered marine life.","絶滅の危機に瀕した海洋生物を保護する為に募金が設立された。","endangered"];
EXAMPLES[4365]=["The water in the basin has frozen solid.","洗面器の水がかちかちに凍った。","basin"];
EXAMPLES[4366]=["Suspending the trial is out of the question.","裁判を中断するのは不可能だ。","Suspending"];
EXAMPLES[4367]=["He dropped his wineglass and broke its stem.","彼はワイングラスを落として、その足を折ってしまった。","stem"];
EXAMPLES[4368]=["You are to hand in your assignments by Monday.","君たちは月曜日までに宿題を提出しなければいけませんよ。","hand in"];
EXAMPLES[4369]=["I hope to be engaged in the export business after graduating from college.","大学を卒業したら、輸出業に従事したいと思っています。","be engaged in"];
EXAMPLES[4370]=["Did you try to review the English lessons?","君は英語の復習をしようとしましたか。","review"];
EXAMPLES[4371]=["Could you lend me your bicycle for a couple of days?","君の自転車を２、３日貸してくれませんか。","a couple of"];
EXAMPLES[4373]=["Your attempt to retrieve your password was not successful. Please try again.","パスワードを復旧する事はできませんでした。再試行してください。","retrieve"];
EXAMPLES[4374]=["Your watch is similar to mine in shape and color.","君の時計は形も色も私のに似ている。","in shape"];
EXAMPLES[4375]=["Can you make sense of this poem?","君はこの詩が理解できるかい。","make sense"];
EXAMPLES[4376]=["She always keeps her room neat and tidy.","彼女は部屋をいつもきれいにしている。","tidy"];
EXAMPLES[4377]=["I want to reveal my secret to you.","君に僕の秘密を打ち明けたいな。","reveal"];
EXAMPLES[4378]=["Education doesn't consist of learning a lot of facts.","教育とは多くの事柄を覚えることにあるのではない。","consist of"];
EXAMPLES[4379]=["I felt very light on my feet afterwards.","終わったあとも足が軽い感じがしました。","afterwards"];
EXAMPLES[4380]=["The sewage pipe is obstructed.","下水管がつまっている。","sewage"];
EXAMPLES[4381]=["An overwhelming majority voted to abolish the brutal punishment.","圧倒的多数がその残酷な刑罰を廃止することに票を投じた。","abolish"];
EXAMPLES[4382]=["Some parts of this city are very ugly.","この町には非常に醜いところがいくつかある。","ugly"];
EXAMPLES[4383]=["How can I say things to sound modest?","どう言えば、おしとやかに聞こえる？","modest"];
EXAMPLES[4384]=["The flowers in the garden bloom in spring.","庭の花は春に咲きます。","bloom"];
EXAMPLES[4385]=["I have to assign more men to that work.","ぼくはその仕事にもっと人数をふやさなければならない。","assign"];
EXAMPLES[4386]=["The architecture in this part of the city is ugly.","市のこの地区の建物は皆醜悪だ。","architecture"];
EXAMPLES[4387]=["The icy road sparkled in the sunlight.","凍結した道路が日光を浴びてまばゆく光った。","sparkled"];
EXAMPLES[4388]=["How come you know so much about Japanese history?","どうしてそんなに日本の歴史に詳しいの？","How come"];
EXAMPLES[4389]=["We all make fools of ourselves at times.","わたしたちはみな、時折ばかな真似をする。","at times"];
EXAMPLES[4390]=["It looks like your hard disk is fragmented.","ハードが断片化を起こしてるみたい。","fragmented"];
EXAMPLES[4391]=["How much is the fare on the bus?","このバスの料金はいくらですか。","fare"];
EXAMPLES[4392]=["He fell prey to an impulse to steal.","彼は出来心で盗みをした。","prey"];
EXAMPLES[4393]=["The country had been devastated by long war.","その国は長い戦争によって荒らされていた。","devastated"];
EXAMPLES[4394]=["You have to study hard to catch up with your class.","君はクラスのみんなに追いつくために、一生懸命勉強しなくてはならない。","catch up"];
EXAMPLES[4395]=["In contrast to the dog, the cat has become domesticated only in recent times.","イヌとは対照的に、ネコはごく最近になって飼いならされたものである。","In contrast to"];
EXAMPLES[4396]=["Good nutrition is vital for an infant's growth.","十分な栄養摂取は幼児の発育にとって極めて重要です。","nutrition"];
EXAMPLES[4398]=["Tom is taking a leak behind the house.","トムは家の後ろでおしっこしてるんだ。","leak"];
EXAMPLES[4399]=["You should exert yourself to get better results.","もっといい成績を得るように努力しなさい。","exert"];
EXAMPLES[4400]=["Just stick to the protocol, would you?","プロトコルだけに固執すればいい、分かった？","protocol"];
EXAMPLES[4401]=["Burning plastic can release toxic gases.","プラスチックを燃やすと有毒ガスが発生する場合があります。","toxic"];
EXAMPLES[4402]=["I saw a documentary about that.","それに関するドキュメンタリーを見たわ。","documentary"];
EXAMPLES[4403]=["A dog has an acute sense of smell.","イヌは鋭い嗅覚を持っている。","acute"];
EXAMPLES[4404]=["Eating and drinking are prohibited in the library.","図書館内は飲食禁止です。","prohibited"];
EXAMPLES[4405]=["He was in favor of equality for all.","彼は全ての人が平等であることに賛成した。","equality"];
EXAMPLES[4406]=["Tom says that he only eats organic food.","トムはオーガニックなものしか食べないそうよ。","organic"];
EXAMPLES[4407]=["This formula is the basis of the theory.","これは理論の根幹となる数式である。","formula"];
EXAMPLES[4408]=["We have the exclusive right to sell them.","私たちはそれらを売る独占権がある。","exclusive"];
EXAMPLES[4409]=["I do not doubt that he is sincere.","私は彼が誠実であることを疑わない。","sincere"];
EXAMPLES[4410]=["I vowed that I would never speak to her again.","彼女には二度と話しかけないと誓った。","vowed"];
EXAMPLES[4411]=["The lamp was swinging back and forth.","ランプが前後にゆれていた。","back and forth"];
EXAMPLES[4412]=["By intuition he knew she was lying.","彼は直感で彼女の嘘をついているとわかった。","intuition"];
EXAMPLES[4413]=["Can I use my laptop in the bath?","お風呂でパソコンって、使えますか？","laptop"];
EXAMPLES[4415]=["This chart illustrates the function of ozone layer.","この図はオゾン層の機能を説明している。","layer"];
EXAMPLES[4416]=["We would often sit up all night discussing politics.","一晩中政治の話をしてよく夜をあかしたものだ。","sit up"];
EXAMPLES[4417]=["He was about to explode, but checked himself.","怒鳴りつけたかったが思いとどまった。","explode"];
EXAMPLES[4419]=["Years ago, she used to hang around with a bunch of bikers.","何年か前、彼女は暴走族の連中と付き合っていた。","a bunch of"];
EXAMPLES[4420]=["This mountain has an altitude of 3,000 meters.","この山は、高さ３，０００メートルです。","altitude"];
EXAMPLES[4421]=["Japan is hot and humid in the summer.","日本の夏は蒸し暑い。","humid"];
EXAMPLES[4422]=["The United States is in the Northern Hemisphere.","合衆国は北半球にある。","Hemisphere"];
EXAMPLES[4423]=["This is too sweet and that is too salty.","これは甘すぎるし、あれは塩辛すぎる。","salty"];
EXAMPLES[4424]=["There will be long lines at the Customs.","税関では長い列が出来ているだろう。","Customs"];
EXAMPLES[4425]=["The abolition of slavery in Europe eventually reached America.","ヨーロッパでの奴隷制度の廃止は、やがてアメリカにも波及しました。","abolition"];
EXAMPLES[4426]=["The public is requested not to litter in these woods.","当森林内でごみを捨てないで下さい。","litter"];
EXAMPLES[4427]=["Hatred is the flip side of cuteness.","憎い憎いは可愛いの裏。","flip"];
EXAMPLES[4428]=["You must not invade the privacy of others.","あなたは他人の私事を侵害してはならない。","invade"];
EXAMPLES[4429]=["Our team beat the Lions 3 to 0.","我がチームは３対０でライオンズに勝った。","beat"];
EXAMPLES[4430]=["I never thought he was all that stubborn.","彼はああ強情だとは思わなかった。","stubborn"];
EXAMPLES[4431]=["We moved into this house last month. We will settle down soon.","われわれは先月この家に引っ越しました。もうすぐ落ちつくでしょう。","settle down"];
EXAMPLES[4432]=["Traffic noise is very harsh to the ear.","車の騒音はとても耳障りだ。","harsh"];
EXAMPLES[4433]=["I'd like to prolong my stay in America.","私はアメリカ滞在の期間を延長したい。","prolong"];
EXAMPLES[4434]=["Be it ever so humble, home is home.","どんなに粗末でも、我が家は我が家である。","humble"];
EXAMPLES[4435]=["Concrete can be reinforced by putting steel bars inside it.","コンクリートは中に鋼鉄の棒を入れる事で補強される。","reinforced"];
EXAMPLES[4436]=["Please put a fragile sticker on this box.","この箱に「割れ物注意」のシールを貼ってください。","fragile"];
EXAMPLES[4437]=["Idleness is only the refuge of weak minds.","怠惰は弱気精神の避難場にすぎない。","refuge"];
EXAMPLES[4438]=["You must cut down on extra expenses in order to live within your means.","君は自分の収入の範囲内で生活するように、余分な支出は切りつめなければならない。","cut down"];
EXAMPLES[4439]=["I make so bold as to ask you.","失礼ながらお尋ねいたします。","bold"];
EXAMPLES[4440]=["Stop shooting the breeze and get to work!","ダベってないで仕事しろ。","breeze"];
EXAMPLES[4441]=["By the way, have you seen him lately?","ところで、最近彼に会いましたか。","lately"];
EXAMPLES[4442]=["My allowance does not pay for my tuition.","もらう金では授業料にはたりない。","tuition"];
EXAMPLES[4443]=["The accident is still vivid in his memory.","その事故はまだありありと彼の記憶に残っている。","vivid"];
EXAMPLES[4444]=["It's out of stock, but I can give you a rain check.","もう売り切れてしまったのですが、次回有効券をお渡しいたします。","out of stock"];
EXAMPLES[4445]=["They couldn't comprehend the seriousness of the matter.","彼らはその事故の深刻さを理解できなかった。","comprehend"];
EXAMPLES[4446]=["He has accumulated quite a collection of books.","彼は相当数の蔵書を集めた。","accumulated"];
EXAMPLES[4447]=["Summon up your courage and tell the truth.","勇気を奮い起こして本当のことを言いなさい。","Summon"];
EXAMPLES[4448]=["I managed to acquire two tickets for the concert.","そのコンサートのチケットをやっとのことで２枚手に入れた。","acquire"];
EXAMPLES[4449]=["This cross street is busy with pedestrian traffic.","この横町は人の通りが多い。","pedestrian"];
EXAMPLES[4450]=["We tried to restrain him from his reckless action.","私達は彼に向こう見ずな行動をさせないようにした。","restrain"];
EXAMPLES[4452]=["My comment sparked off an argument in the group.","私の意見がそのグループでの議論のきっかけになった。","sparked"];
EXAMPLES[4453]=["I do think that it is a pity.","本当に残念だと思う。","pity"];
EXAMPLES[4454]=["Strictly speaking, they are not the same variety.","厳密に言えば、それらは同じ種類ではない。","Strictly"];
EXAMPLES[4455]=["We were looking at the fire burning brightly.","私達は赤々と燃えている火を見つめていた。","brightly"];
EXAMPLES[4456]=["Hang on a minute. I'll call Jimmy.","ちょっと待って、ジミーを呼ぶから。","Hang on"];
EXAMPLES[4457]=["The girl and her parents were very sympathetic.","少女と両親はとても思いやりがあった。","sympathetic"];
EXAMPLES[4458]=["The smoke poured out of the chimney.","煙突から煙がもくもくと出ていた。","chimney"];
EXAMPLES[4459]=["The boy stripped a tree of the bark.","少年は木の皮を剥いだ。","bark"];
EXAMPLES[4460]=["My eyes were intent on the scene.","私の目はその光景に吸い付けられた。","intent"];
EXAMPLES[4461]=["The petals of this rose are very tender.","このバラの花びらはとても柔らかい。","tender"];
EXAMPLES[4463]=["We had a lot of spontaneous offers from them.","彼らから自発的な申し出がたくさんあった。","spontaneous"];
EXAMPLES[4464]=["Are you really not able to forgive Tom?","トムのこと、許してあげてくれない？","forgive"];
EXAMPLES[4465]=["The glove has a hole in the thumb.","その手袋は親指に穴があいている。","thumb"];
EXAMPLES[4466]=["The robber attacked her on a back street.","強盗は裏通りで彼女を襲った。","robber"];
EXAMPLES[4467]=["He fished in the drawer for the key.","彼は鍵はないかと引き出しの中を探した。","drawer"];
EXAMPLES[4468]=["It was only an informal party.","ほんの気楽なパーティーだった。","informal"];
EXAMPLES[4471]=["I saw him pat her on the shoulder.","私は彼が彼女の肩をたたくのを見た。","pat"];
EXAMPLES[4472]=["He got his wife to mend his shirt.","彼は奥さんにシャツを縫ってもらった。","mend"];
EXAMPLES[4473]=["The twins have come down with measles.","その双子ははしかにかかっていた。","come down with"];
EXAMPLES[4474]=["You can't afford to neglect your health.","君は自分の健康を度外視するわけにはいかない。","afford to"];
EXAMPLES[4475]=["The slave was anxious to alter his destiny.","その奴隷は自分の運命を変えたいと強く思っていた。","slave"];
EXAMPLES[4476]=["My memory is blank on the subject.","その問題では記憶がぜんぜんない。","blank"];
EXAMPLES[4477]=["That teacher sexually harassed me. He's totally gross.","あの先生、セクハラしてきてマジキモい。","gross"];
EXAMPLES[4478]=["In the meantime, he went to sleep.","そうしているうちに彼は眠ってしまった。","meantime"];
EXAMPLES[4479]=["We all consider your idea to be impractical.","君の考えは非現実的だと皆思っている。","impractical"];
EXAMPLES[4480]=["This is a very sturdy chair to sit in.","これは掛けるのにたいそう頑丈ないすだ。","sturdy"];
EXAMPLES[4481]=["I can't get rid of a nasty cold.","私はしつこい風邪が抜けない。","nasty"];
EXAMPLES[4482]=["It was horrible to hear about the crime.","その犯罪は聞くも恐ろしいものだった。","horrible"];
EXAMPLES[4483]=["I am about to take my last voyage, a great leap in the dark.","私は今まさに最後の旅路につき、暗黒へと一大飛躍しようとしている。","leap in"];
EXAMPLES[4484]=["Wash your hands with a bar of soap.","石鹸で手を洗いなさい。","soap"];
EXAMPLES[4485]=["In spite of the rain, I went out.","雨にもかかわらず、私は外出した。","spite"];
EXAMPLES[4486]=["There was a big reception after the wedding.","結婚式の後で盛大な披露宴が催された。","reception"];
EXAMPLES[4487]=["I am certain that you have noble thoughts.","私はあなたが気高い心の持ち主だと確信している。","noble"];
EXAMPLES[4488]=["The sky seemed to blend with the sea.","空が海と一つに溶け込むように見えた。","blend"];
EXAMPLES[4490]=["Full religious freedom is assured to all people.","完全な宗教の自由が万人に保証されている。","religious"];
EXAMPLES[4491]=["There was a long interval before he answered.","彼が答えるまでに長い間があった。","interval"];
EXAMPLES[4492]=["The man robbed him of all his money.","男は彼から有り金を残らず奪い取った。","robbed"];
EXAMPLES[4493]=["The vast majority of children love ice cream.","大多数の子供はアイスが大好きだ。","vast"];
EXAMPLES[4494]=["This essay is about a piece of luggage.","この随筆は一個の旅行かばんについてのものです。","luggage"];
EXAMPLES[4495]=["On the wings of Time grief flies away.","時の翼に乗って悲しみは飛び去る。","grief"];
EXAMPLES[4496]=["She left the kitchen with the kettle boiling.","彼女はやかんを沸騰させたまま台所を出た。","kettle"];
EXAMPLES[4497]=["There is a black sheep in every flock.","厄介者はどこにでもいるものだ。","flock"];
EXAMPLES[4498]=["Don't fall for his sugar-coated words.","彼の甘い口車にのるな。","fall for"];
EXAMPLES[4499]=["He told us a very exciting adventure story.","彼はわくわくするような冒険談をしてくれた。","adventure"];
EXAMPLES[4500]=["He gave me a lift in his cart.","彼は私を彼の荷車に乗せてくれた。","cart"];
EXAMPLES[4501]=["Yes, she'll be with you in a minute.","すぐに行かせます。","she"];
EXAMPLES[4502]=["Spiders always weave their webs in three dimensions.","クモはいつも自分たちの巣を３次元に織る。","weave"];
EXAMPLES[4503]=["If not a lie, close to a boast.","嘘ではないにしろ、ホラに近い。","boast"];
EXAMPLES[4504]=["Could you knock down the price if I buy two?","まとめて２個買いますから値引きしてください。","knock down"];
EXAMPLES[4505]=["The nurse wound my leg with a bandage.","看護婦さんが私の足に包帯を巻いてくれた。","bandage"];
EXAMPLES[4506]=["Can we play now and study afterward?","今遊んで、後で勉強していい？","afterward"];
EXAMPLES[4507]=["Is that university a prestigious one?","その大学って、名門なの？","prestigious"];
EXAMPLES[4508]=["He is at home with the geography of Tokyo.","彼は東京の地理に精通している。","geography"];
EXAMPLES[4509]=["How much do you get paid per month?","月収っていくら？","per"];
EXAMPLES[4510]=["Don't take gossip at face value.","噂話を鵜呑みにするんじゃない。","at face value"];
EXAMPLES[4512]=["He is no better than a beggar is.","彼はこじき同然だ。","beggar"];
EXAMPLES[4513]=["I can remember the warmth of his hands.","彼の手のぬくもりが思い出されます。","warmth"];
EXAMPLES[4514]=["The authorities managed to stabilize the currency.","当局は自国の通貨を何とか安定させた。","stabilize"];
EXAMPLES[4515]=["The sheep were grazing in the meadow.","羊が牧草地で草をはんでいた。","meadow"];
EXAMPLES[4516]=["The dam gave way and sent a great flush of water down the valley.","ダムが切れて流域に大水が押し寄せた。","water down"];
EXAMPLES[4517]=["Do you have a fountain pen with you?","万年筆を持っていますか。","fountain"];
EXAMPLES[4519]=["The ice is too thin to skate on.","氷が薄すぎてスケートができません。","thin"];
EXAMPLES[4520]=["The girl released the birds from the cage.","その女の子は鳥をかごから逃がしてやった。","cage"];
EXAMPLES[4521]=["Excuse me, could I get past?","ちょっと失礼、通していただけますか。","get past"];
EXAMPLES[4522]=["You have a standing invitation to join us.","いつおいでくださっても歓迎いたします。","invitation"];
EXAMPLES[4523]=["That girl is jealous of her little brother.","あの子は弟のことが羨ましいんだ。","jealous"];
EXAMPLES[4524]=["They are chiseling a statue out of marble.","彼らは大理石で像を彫っている。","marble"];
EXAMPLES[4525]=["I found a tutor through a newspaper ad.","新聞の広告で、家庭教師を見つけました。","tutor"];
EXAMPLES[4526]=["It's important to unite as many workers as possible.","できるだけ多くの労働者を団結させることが大切だ。","unite"];
EXAMPLES[4528]=["Do you want me to comb your hair?","髪を梳かしましょうか？","comb"];
EXAMPLES[4529]=["He expressed it in the form of fiction.","彼はそれを小説の形式で表した。","fiction"];
EXAMPLES[4530]=["The company was in the red and went under.","会社は赤字経営で倒産した。","in the red"];
EXAMPLES[4531]=["He is quite frank with me about everything.","彼はどんなことでも私に全く隠しだてしない。","frank"];
EXAMPLES[4532]=["The royal wedding was a great spectacle.","王室の結婚式は大変な壮観だった。","spectacle"];
EXAMPLES[4533]=["Our staff is eager to help you.","我々のスタッフがあなたを是非助けたいと思っています。","eager to"];
EXAMPLES[4535]=["They are fanatical in their beliefs.","彼らは自分たちの信仰に熱狂している。","fanatical"];
EXAMPLES[4536]=["This sticky liquid can be substituted for glue.","このねばねばした流動体は接着剤の代わりになる。","glue"];
EXAMPLES[4537]=["The rebel was ultimately captured and confined to prison.","反逆者はついに捕まり牢獄に監禁された。","ultimately"];
EXAMPLES[4538]=["My backyard can hold more than ten people.","家の裏庭なら１０人以上入れるわよ。","backyard"];
EXAMPLES[4539]=["We put up at a lakeside hotel for the night.","我々はその夜湖畔のホテルに宿泊した。","put up at"];
EXAMPLES[4540]=["If we do this, it'll set a precedent.","こんなことしたら、前例になっちゃうよ。","set a precedent"];
EXAMPLES[4541]=["Is it all right to use a flash here?","フラッシュを使ってもいいですか。","flash"];
EXAMPLES[4542]=["London is the capital of the United Kingdom.","ロンドンは英国の首都である。","Kingdom"];
EXAMPLES[4545]=["He is a man of striking individuality.","あの人ははっきりした個性を持った人だ。","striking"];
EXAMPLES[4547]=["This, in essence, is the secret of science.","実はこれこそが科学の神髄なのである。","essence"];
EXAMPLES[4548]=["Pull over right here.","ここで車を止めてください。","Pull over"];
EXAMPLES[4549]=["Walk calmly to the door.","ドアまでゆっくり歩きなさい。","calmly"];
EXAMPLES[4551]=["Iron Arm Atom protected the country from danger.","鉄腕アトムが国を危険から守った。","Atom"];
EXAMPLES[4552]=["The company is managed by my elder brother.","同社は私の兄が経営している。","elder"];
EXAMPLES[4553]=["Either he or I have to attend the convention.","彼か私のどちらかが大会に出席しなければならない。","convention"];
EXAMPLES[4556]=["In case of a fire, use the stairs.","火事の場合、階段を使いなさい。","stairs"];
EXAMPLES[4557]=["Open your atlas of Japan to page 3.","日本地図の３ページを開けなさい。","atlas"];
EXAMPLES[4559]=["I am delighted to have met you today.","今日、あなたとあえて、とっても嬉しいな。","delighted"];
EXAMPLES[4560]=["The little girl will go astray if no one cares much about her.","誰もがあまり構ってくれないとその少女はぐれるだろう。","go astray"];
EXAMPLES[4561]=["This part of the lake is very shallow.","湖のこの部分なんだけど、とっても浅いんだ。","shallow"];
EXAMPLES[4562]=["We found the stolen bag in this bush.","我々は盗まれたバッグをこの茂みで見つけた。","bush"];
EXAMPLES[4563]=["It is hard to discern between true and false.","ホントかウソかを見抜くのは難しい。","discern"];
EXAMPLES[4564]=["She lives in rural seclusion.","彼女は人里離れたところに住んでいます。","seclusion"];
EXAMPLES[4565]=["I have a discharge from my left ear.","左耳から耳だれが出ます。","discharge"];
EXAMPLES[4566]=["Demo's progression was being reported by the participants through SNS.","デモの様子は参加者によってSNSを通じて実況された。","progression"];
EXAMPLES[4567]=["The wheat is coming very well this year.","今年は小麦がよく育っている。","wheat"];
EXAMPLES[4568]=["He will soon be weary of the task.","彼はすぐその仕事に飽きるだろう。","weary"];
EXAMPLES[4569]=["I picked up a purse in the street.","私は往来で財布を拾った。","purse"];
EXAMPLES[4570]=["The inside of the venue was silent.","会場内は、シーンと静まり返っていました。","venue"];
EXAMPLES[4573]=["There is a slight chill on the party.","ちょっと座が白けている。","chill"];
EXAMPLES[4574]=["How to distribute abundance is a great problem.","豊かさの配分は大問題だね。","distribute"];
EXAMPLES[4575]=["I want to send a parcel to Japan.","日本に小包を送りたいのですが。","parcel"];
EXAMPLES[4576]=["Ask her if she'll sew up the hole in your jeans.","おまえのジーンズの綻びを彼女に繕ってもらいなさい。","sew up"];
EXAMPLES[4577]=["He fetched a few cushions to prop up her head.","彼は頭をのせるため二三のクッションを持ってきた。","prop up"];
EXAMPLES[4578]=["Teachers shouldn't fall back on their authority.","教師は自らの権威を頼みとしてはならない。","fall back on"];
EXAMPLES[4579]=["This weed killer does not harm human beings.","この除草剤は人間には無害だ。","weed"];
EXAMPLES[4580]=["He prayed that God would bless me.","彼は私に「神の祝福がありますように」と言った。","bless"];
EXAMPLES[4581]=["Take care when you climb up the ladder.","はしごを登るときは注意しなさい。","ladder"];
EXAMPLES[4583]=["The night is darkest just before the dawn.","夜明け前が一番暗い。","dawn"];
EXAMPLES[4586]=["If you try to have it both ways, you'll end up with neither.","両天秤をかけると失敗する。","end up with"];
EXAMPLES[4587]=["She did nothing but weep at the news.","彼女はその知らせを聞いてただ泣くばかりだった。","weep"];
EXAMPLES[4588]=["I am nothing but a poor peasant.","私は貧しい農民に過ぎない。","peasant"];
EXAMPLES[4589]=["She took a lot of baggage with her.","彼女は手荷物をたくさん持って行った。","baggage"];
EXAMPLES[4590]=["You must be deliberate in selecting a partner.","相手を選ぶときは慎重でなければならない。","deliberate"];
EXAMPLES[4591]=["When does your school break up?","学校はいつ休暇になりますか。","break up"];
EXAMPLES[4592]=["The article's tone was one of pessimism.","記事の論調は一種の悲観論だった。","pessimism"];
EXAMPLES[4593]=["The flowers give off a very pleasant scent.","花は大変心地良い香りを発する。","give off"];
EXAMPLES[4594]=["Besides those serious problems, he had to contend with all sorts of people.","彼は深刻な問題がある上に、ありとあらゆる型の人間を相手にしなければならなかった。","contend with"];
EXAMPLES[4595]=["She bore the air of a lady.","彼女は貴婦人の風格を備えていた。","bore"];
EXAMPLES[4596]=["This is an instance of modern British life.","これは英国の現代生活のほんの一例だ。","instance"];
EXAMPLES[4599]=["I have been a disappointment to my parents.","私は両親の期待を裏切ってきた。","disappointment"];
EXAMPLES[4601]=["This revision of Darwin's ideas came under fire from academic positions.","ダーウィンの考えをこのように改訂したことは学問的立場からの攻撃対象となった。","under fire"];
EXAMPLES[4602]=["The man caught the girl by the wrist.","その男は少女の手首をつかんだ。","wrist"];
EXAMPLES[4603]=["We must pay regard to other cultures like ours.","私たちは他の文化も自分の文化同様に尊重しなければならない。","pay regard to"];
EXAMPLES[4604]=["If you want to be fluent in English, you've got to keep at it.","英会話に堪能になりたかったら、根気よく続けてやらないと駄目だ。","keep at"];
EXAMPLES[4605]=["You can't teach your grandmother to suck eggs.","釈迦に経。","suck"];
EXAMPLES[4606]=["We were cut off while talking on the telephone.","我々は話し中の電話を切られた。","cut off"];
EXAMPLES[4607]=["I was just about to get started any-how.","いまやろうと思ったのに。","any"];
EXAMPLES[4608]=["Monks used to play tennis in monasteries.","当時は修道僧達が修道院でよくテニスをしていた。","monasteries"];
EXAMPLES[4609]=["This is closely bound up with the question.","これはその問題と密接な関係がある。","bound"];
EXAMPLES[4611]=["Please turn over the page.","ページをめくりなさい。","turn over"];
EXAMPLES[4612]=["You have a tendency to talk too fast.","君には早口でしゃべる癖がある。","tendency"];
EXAMPLES[4613]=["Her behavior was a departure from the normal.","彼女の行動は常軌を逸したものだ。","departure"];
EXAMPLES[4614]=["I want to devote my life to education.","私は人生を教育に捧げたい。","devote"];
EXAMPLES[4616]=["I know that German with a long beard.","私は長いあごひげを生やしたあのドイツ人を知っています。","beard"];
EXAMPLES[4618]=["Their intimacy grew with the years.","彼らの親密さは年月とともに深まった。","intimacy"];
EXAMPLES[4620]=["It is fortunate that you have such parents.","そんな両親をもって君は幸せだ。","fortunate"];
EXAMPLES[4621]=["He came at an inopportune time.","彼はまずい時にやってきた。","inopportune"];
EXAMPLES[4625]=["From this point the climb suddenly became steep.","この地点から登りが急に険しくなった。","steep"];
EXAMPLES[4626]=["When I turned the screw, water burst out.","僕がネジを回すと水が吹き出してきた。","screw"];
EXAMPLES[4628]=["Tom grew a moustache.","トムは口ひげを生やした。","moustache"];
EXAMPLES[4629]=["We must be loyal to our principles.","私たちは主義に忠実でなければならない。","loyal"];
EXAMPLES[4630]=["Take a break, or you'll fall apart.","休め。ボロボロになるぞ。","fall apart"];
EXAMPLES[4631]=["He bought a lot of flour and oil.","彼はたくさんの小麦粉と油を買い込んだ。","flour"];
EXAMPLES[4632]=["There is a red rose in the vase.","赤いバラが花瓶にある。","vase"];
EXAMPLES[4633]=["It goes against the grain with me.","僕はそれが気にいらない。","grain"];
EXAMPLES[4634]=["I used to have a little crush on you.","君のことが少し好きだったよ。","crush"];
EXAMPLES[4635]=["Have you tried taking a sleeping pill?","睡眠薬を飲んでみたことある？","pill"];
EXAMPLES[4636]=["He fell a victim to a deadly disease.","彼は恐ろしい病気にとりつかれた。","deadly"];
EXAMPLES[4637]=["He flung a stream of abuse at me.","彼は私に悪態を浴びせかけた。","abuse"];
EXAMPLES[4638]=["What is your current place of residence?","現在はどちらにお住まいですか？","residence"];
EXAMPLES[4640]=["To her embarrassment, her baby never stopped crying.","彼女が当惑したことに赤ん坊はとうとう泣きやまなかった。","embarrassment"];
EXAMPLES[4641]=["We were all ears.","私たちは全身を耳にしていた。","all ears"];
EXAMPLES[4642]=["Remember that we will inherit the results of your decisions.","心に留めてください、私たちが皆さんの決定の結果を見に受けるのです。","inherit"];
EXAMPLES[4643]=["I am uncertain when he will come next.","彼が今度いつ来るかはっきりとは知らない。","uncertain"];
EXAMPLES[4644]=["There are scarcely any flowers in our garden.","家の庭に花はほとんど見られません。","scarcely"];
EXAMPLES[4645]=["This is a small token of my gratitude.","これはほんの些細な感謝の印です。","token"];
EXAMPLES[4646]=["Japan is hot and sticky in summer.","日本の夏は蒸し暑い。","sticky"];
EXAMPLES[4647]=["I don't want you to do things halfway.","中途半端なことはしないで欲しい。","halfway"];
EXAMPLES[4648]=["There is only one pass over the mountain.","その山を越える山道は一つしかない。","pass over"];
EXAMPLES[4649]=["We yawn when we are short of oxygen.","我々は酸素が不足するとあくびをする。","yawn"];
EXAMPLES[4650]=["I am going to assert his guilt.","私は彼の有罪を主張するつもりです。","assert"];
EXAMPLES[4651]=["He lacks consciousness that he is a member of society.","彼は社会人としての自覚に欠ける。","consciousness"];
EXAMPLES[4652]=["Light escaped from the apartment complex surrounding the park.","公園を囲む団地からは明かりが漏れている。","surrounding"];
EXAMPLES[4653]=["She knows how to do the crawl.","彼女はクロールの泳ぎ方を知っている。","crawl"];
EXAMPLES[4654]=["The garden is turning into a wilderness.","その庭園は荒れ地に変わりつつある。","wilderness"];
EXAMPLES[4655]=["Please be sure to sign and seal the form.","書式に必ず署名押印してください。","seal"];
EXAMPLES[4656]=["Precision in measurement is a necessity.","測定においては正確さは欠かせないものである。","measurement"];
EXAMPLES[4657]=["He told us to depart at once.","彼は私たちに「すぐ出発しなさい」と言った。","depart"];
EXAMPLES[4658]=["He made a determination to be a doctor.","彼は医者になる決心をした。","determination"];
EXAMPLES[4660]=["To preach is easier than to practice.","説教することは実行することよりやさしい。","preach"];
EXAMPLES[4661]=["He was excited to see the beautiful scenery.","彼はその美しい光景を見てわくわくした。","scenery"];
EXAMPLES[4662]=["We have discussed the problem several times but to no avail.","我々はその問題を数回話し合いしましたが、無駄でした。","to no avail"];
EXAMPLES[4665]=["Man is indeed at the mercy of nature.","人間は実際自然のなすがままである。","mercy"];
EXAMPLES[4667]=["Formerly this building was a hospital.","昔はこの建物は病院だった。","Formerly"];
EXAMPLES[4668]=["The weather seemed favorable for the test flight.","天気はテスト飛行にとって好条件のように思えた。","favorable"];
EXAMPLES[4669]=["Would you sew a button on my shirt?","ワイシャツにボタンをつけて。","sew"];
EXAMPLES[4671]=["I got a nasty sting from a wasp.","スズメバチにこっぴどく刺された。","sting"];
EXAMPLES[4672]=["Lie on your right side.","右わき腹を下にして横になってください。","Lie on"];
EXAMPLES[4673]=["The decline isn't so sharp after seasonal adjustment.","落ち込みは季節調整すればそれほど大きくない。","adjustment"];
EXAMPLES[4675]=["There was a fine scent in the room.","部屋の中は良い香りがしていた。","scent"];
EXAMPLES[4676]=["It is wicked of you to do such things.","そんなことをするなんてひどい人ですね。","wicked"];
EXAMPLES[4677]=["A man's life has its ups and downs.","栄枯盛衰は世の習い。","ups and downs"];
EXAMPLES[4678]=["It was the triumph of civilization over force.","それは暴力に対する文明の勝利であった。","triumph"];
EXAMPLES[4680]=["In spring, I await many meetings!","春には、たくさんの出会いが待っている！","await"];
EXAMPLES[4681]=["I have a guilty conscience about that.","私はその事ではやましく思っている。","conscience"];
EXAMPLES[4682]=["The cut will heal in a few days.","その切り傷は2、3日したら完全に治るでしょう。","heal"];
EXAMPLES[4683]=["The opinions were divided on which one is profitable.","どちらが得かは、意見が分かれるとこだ。","profitable"];
EXAMPLES[4684]=["Make haste, and you will be in time.","急ぎなさい、そうすれば間に合いますよ。","haste"];
EXAMPLES[4685]=["Passions weaken, but habits strengthen, with age.","年をとると共に、情熱は薄れるが、身についた習慣は強まるものだ。","weaken"];
EXAMPLES[4686]=["I think that you resemble your mother.","私はあなたは母親似だと思う。","resemble"];
EXAMPLES[4687]=["He set up as a butcher.","彼は肉屋を開業した。","butcher"];
EXAMPLES[4688]=["I'm sorry, but I have a prior engagement.","残念ながら先約があります。","engagement"];
EXAMPLES[4689]=["You always take the lion's share!","いつも一番いい取り分を得やがって！","the lion's share"];
EXAMPLES[4690]=["The building doesn't blend in with its surroundings.","その建物は周りの風景と調和しない。","blend in"];
EXAMPLES[4692]=["Osaka is the center of commerce in Japan.","大阪は日本の商業の中心地です。","commerce"];
EXAMPLES[4693]=["Suddenly I heard a loud clap of thunder.","突然のおおきな雷鳴が聞こえた。","clap"];
EXAMPLES[4694]=["The road is dusty. It cannot have rained yesterday.","道路がほこりっぽい。昨日雨が降ったはずがない。","dusty"];
EXAMPLES[4695]=["Some people were kind and others were unkind.","親切な人もいたし不親切な人もいた。","unkind"];
EXAMPLES[4696]=["One shouldn't ride a bicycle on the pavement.","歩道で自転車に乗ってはいけません。","pavement"];
EXAMPLES[4701]=["I called him a coward to his face.","私は彼に面と向かって臆病者といってやった。","coward"];
EXAMPLES[4702]=["The boy is obedient to his parents.","その少年は両親の言うことを聞く。","obedient"];
EXAMPLES[4703]=["That child may have been kidnapped on his way home.","その子は帰宅の途中で誘拐されたのかもしれない。","kidnapped"];
EXAMPLES[4704]=["The can will do for an ashtray.","その缶は灰皿の代わりになる。","ashtray"];
EXAMPLES[4705]=["This painting will pass for genuine.","この絵は本物で通るだろう。","pass for"];
EXAMPLES[4706]=["I had the porter carry my suitcase.","私は赤帽にスーツケースを運んでもらった。","porter"];
EXAMPLES[4707]=["You must be faithful to your word.","約束には忠実でなくてはいけない。","faithful"];
EXAMPLES[4708]=["The fox hid in the hollow of a tree.","キツネは木のうろの中に隠れました。","hollow"];
EXAMPLES[4709]=["He could not find what I had hidden.","彼は私が隠したものを見つけることが出来なかった。","hidden"];
EXAMPLES[4710]=["I am filled with admiration for your bravery.","あなたの勇敢な行動には感嘆しています。","admiration"];
EXAMPLES[4711]=["It will threaten the prosperity of the town.","それは町の繁栄を脅かすだろう。","prosperity"];
EXAMPLES[4712]=["George is very enthusiastic about his new job.","今度の新しい仕事にジョージはとても熱中している。","enthusiastic"];
EXAMPLES[4713]=["The pirates had no choice but to surrender.","海賊達には降参する以外に道はなかった。","surrender"];
EXAMPLES[4714]=["The sight was too miserable to look at.","その光景は目も当てられなかった。","miserable"];
EXAMPLES[4715]=["There is nothing that does not decay.","朽ちない物は何もない。","decay"];
EXAMPLES[4716]=["Her house is enclosed with a white fence.","彼女の家は白い垣根で囲まれている。","enclosed"];
EXAMPLES[4717]=["They say that he was ambitious when young.","彼は若いころ野心家だったそうだ。","ambitious"];
EXAMPLES[4719]=["All the evidence points to his guilt.","すべての証拠は彼の有罪を示している。","guilt"];
EXAMPLES[4720]=["I have occasional pains in the stomach.","時々、胃が痛むんだ。","occasional"];
EXAMPLES[4722]=["Mary was the one who named this puppy.","この子犬の名付け親は、メアリーです。","puppy"];
EXAMPLES[4723]=["The greedy little child ate all the food.","食い意地のはった少年は料理を全部たいらげた。","greedy"];
EXAMPLES[4726]=["She is in partial agreement with this decision.","彼女はこの決定に部分的に同意している。","partial"];
EXAMPLES[4727]=["Your new car looks awfully expensive to me.","あなたの新車はずいぶん高そうですね。","awfully"];
EXAMPLES[4728]=["He is guilty and by the same token so are you.","彼は有罪であり君も同様に有罪である。","by the same token"];
EXAMPLES[4729]=["I cut my finger with a razor blade.","かみそりの刃で指を切りました。","razor"];
EXAMPLES[4730]=["They rejoiced over the news of our success.","彼らは我々の成功の知らせを喜んだ。","rejoiced"];
EXAMPLES[4731]=["It was heroic of them to oppose the enemy.","彼等が敵に向かうとはあっぱれであった。","heroic"];
EXAMPLES[4732]=["This new investment will multiply our profit.","この新たな投資が利益増につながるだろう。","multiply"];
EXAMPLES[4733]=["Make haste, and you will be in time.","急ぎなさい、そうすれば間に合いますよ。","Make haste"];
EXAMPLES[4735]=["It was due a week ago, namely on April second.","それは１週間前、すなわち４月２日に行われた。","namely"];
EXAMPLES[4736]=["I don't like people who act all high and mighty.","威張る人って、好きじゃないのよね。","mighty"];
EXAMPLES[4738]=["Only a handful of people know the fact.","ほんの少数の人しかその事実を知らない。","handful"];
EXAMPLES[4740]=["We believed it to be a flying saucer.","空飛ぶ円盤だと思った。","saucer"];
EXAMPLES[4741]=["How do you find food in outer space?","宇宙でどうやって食べ物をみつけるの？","outer"];
EXAMPLES[4742]=["The leader gave up the plan in despair.","リーダーは絶望して計画を断念した。","despair"];
EXAMPLES[4743]=["She has a great love for antique goods.","彼女は骨董品がとても好きだ。","antique"];
EXAMPLES[4744]=["We ran for the glory of the school.","私達は学校の名誉のために走った。","glory"];
EXAMPLES[4745]=["He left an immense fortune to his children.","彼は子供に莫大な財産を残した。","immense"];
EXAMPLES[4746]=["I think that Tom is going to faint.","トムは気絶すると思うよ。","faint"];
EXAMPLES[4747]=["The details of the agreement are set forth in the contract.","契約の詳細は契約書に示されている。","set forth"];
EXAMPLES[4748]=["The scandal was fatal to his political future.","そのスキャンダルは彼の政治的将来に致命的であった。","fatal"];
EXAMPLES[4749]=["I would like to repay him for his kindness.","私は彼の親切にこたえたい。","repay"];
EXAMPLES[4750]=["Never halloo till you are out of the woods.","困難が完全に去るまでは喜ぶな。","out of the woods"];
EXAMPLES[4751]=["To speak frankly, I don't like the idea.","率直に言って、その考えは気に入らない。","frankly"];
EXAMPLES[4753]=["I ache for a sight of the sea.","何としても海をひと目みたいものだ。","ache"];
EXAMPLES[4754]=["Please activate your new password via email verification.","新パスワードはメール認証で有効化してください。","activate"];
EXAMPLES[4756]=["That poor family lives from hand to mouth every month.","その貧しい一家は毎月その日暮らしで生活している。","from hand to mouth"];
EXAMPLES[4757]=["The monument was set up in the park.","記念碑が公園に建てられた。","monument"];
EXAMPLES[4758]=["They condemned him for his cruelty to animals.","彼らは動物を虐待したと彼を強く責めた。","cruelty"];
EXAMPLES[4760]=["The canal connects the Atlantic with the Pacific.","その運河は大西洋と太平洋をつないでいる。","canal"];
EXAMPLES[4761]=["Today the new leaf sent out a bud.","今日新しい葉が芽を出した。","bud"];
EXAMPLES[4762]=["I do not know the meaning of hatred.","俺には憎しみの意味が分からない。","hatred"];
EXAMPLES[4763]=["The king was famous for his splendid palace.","王は壮麗な宮殿で有名だった。","splendid"];
EXAMPLES[4764]=["This fruit's not ripe enough to pick yet.","この果物は摘み取られるほどのは成長していない。","ripe"];
EXAMPLES[4765]=["The earthquake caused the house to rattle.","地震で家ががたがたと音をたてた。","rattle"];
EXAMPLES[4766]=["The athletic meet took place on October 15.","運動会は１０月１５日に行われた。","athletic"];
EXAMPLES[4767]=["He tried to fasten his attention on the letter.","彼は、その手紙に注意を集中しようと努めた。","fasten"];
EXAMPLES[4769]=["That interpreter is a master of five languages.","あの通訳は５か国語を自由に操る。","interpreter"];
EXAMPLES[4770]=["Children like those who scold them with love.","子供達は愛情をもって自分を叱ってくれる人を好む。","scold"];
EXAMPLES[4771]=["The person ruling from the shadows was Mary.","影の支配者はメアリーだった。","ruling"];
EXAMPLES[4772]=["He is thoroughly familiar with the business.","彼はその仕事に精通している。","thoroughly"];
EXAMPLES[4773]=["Can you understand the meaning of this paragraph?","この段落の意味分かる？","paragraph"];
EXAMPLES[4774]=["A huge tanker cast off just now.","巨大なタンカーがついに今し方出港した。","cast off"];
EXAMPLES[4775]=["The castle was transformed into a marvelous museum.","その城は素晴らしい博物館に変わった。","marvelous"];
EXAMPLES[4776]=["The rainbow forms an arc in the sky.","虹は空に弓じょうにかかる。","arc"];
EXAMPLES[4777]=["Pass on, please, and do not obstruct the way.","どうか先に進んで道をふさがないで下さい。","Pass on"];
EXAMPLES[4778]=["You're not supposed to wear lipstick at school.","学校で口紅を付けちゃいけないよ。","lipstick"];
EXAMPLES[4779]=["The birds in the cage are singing merrily.","カゴの中の鳥が楽しそうに歌っている。","merrily"];
EXAMPLES[4780]=["I'm planning to stay at the Hillside Hotel.","ヒルサイドホテルに滞在する予定です。","Hillside"];
EXAMPLES[4781]=["I had a hasty breakfast and left home.","私は急いで朝食を食べて、家を出た。","hasty"];
EXAMPLES[4782]=["I allowed a margin of ten minutes.","私は１０分の余裕を見ておいた。","margin"];
EXAMPLES[4783]=["The eldest sister acted in place of the mother.","一番上の姉が母の代わりをした。","in place of"];
EXAMPLES[4784]=["The race is not to the swift.","速い者が競争に勝つとは限らない。","swift"];
EXAMPLES[4785]=["She gave an oral report to her boss.","彼女は上司に口頭で報告をした。","oral"];
EXAMPLES[4786]=["Don't carry anything to excess.","何事もやりすぎてはいけない。","to excess"];
EXAMPLES[4787]=["The American Ambassador was invited to the gathering.","アメリカ大使がその集まりに招待された。","Ambassador"];
EXAMPLES[4788]=["He concentrated his attention on what she said.","彼は彼女の言葉に注意を傾けた。","concentrated"];
EXAMPLES[4789]=["I was in bed with the flu.","私はインフルエンザで寝てたんです。","flu"];
EXAMPLES[4790]=["The company is located in the suburbs of Osaka.","その会社は大阪の郊外にある。","in the suburbs of"];
EXAMPLES[4791]=["The key of the symphony is G minor.","その交響曲はト短調である。","symphony"];
EXAMPLES[4792]=["Fools rush in where angels fear to tread.","盲ヘビに怖じず。","tread"];
EXAMPLES[4793]=["The medicine hastened the process of growth.","その薬が成長の過程を早めた。","hastened"];
EXAMPLES[4794]=["I have an errand to do in town.","私は街に用事がある。","errand"];
EXAMPLES[4795]=["Didn't you see a dog pass through the yard?","君は犬が庭を通り抜けて行くのを見なかったかい。","pass through"];
EXAMPLES[4796]=["In all fairness, he did do his best.","公平に評すれば、彼は最善を尽くした。","fairness"];
EXAMPLES[4797]=["You must make allowance for his lack of experience.","君は彼の経験不足を考慮しなければならない。","make allowance for"];
EXAMPLES[4798]=["The cat got through the hedge.","猫は生け垣を通り抜けた。","hedge"];
EXAMPLES[4799]=["I was left out in the cold by everyone.","みんなが私をのけ者にしたの。","out in the cold"];
EXAMPLES[4800]=["He was angry, but he listened to me patiently.","彼は怒っていたが、私のいうことをがまんして聞いた。","patiently"];
EXAMPLES[4801]=["The cowboys rounded up the herd of cattle.","牧童たちは牛の群れを駆り集めた。","herd"];
EXAMPLES[4802]=["He hit the ball out of bounds.","彼は場外にボールを飛ばした。","out of bounds"];
EXAMPLES[4803]=["I have a history of liver trouble.","私は肝臓の病歴がある。","liver"];
EXAMPLES[4805]=["The human race is dominant on earth.","人類は地球上で最も優勢である。","dominant"];
EXAMPLES[4806]=["He was hit by a car and died instantly.","彼は車に轢かれて即死した。","instantly"];
EXAMPLES[4807]=["Cattle feed on grass.","牛は草を常食とする。","feed on"];
EXAMPLES[4809]=["The statesman is now in full vigor.","その政治家は今元気いっぱいだ。","vigor"];
EXAMPLES[4810]=["They ended capitalism and built a socialist society.","彼らは資本主義にピリオドを打ち社会主義社会を建設した。","capitalism"];
EXAMPLES[4811]=["This is what is called the Norman Conquest.","これが、いわゆるノルマン征服である。","Conquest"];
EXAMPLES[4813]=["This will come in handy in a pinch.","いざという時役に立つよ。","pinch"];
EXAMPLES[4815]=["I have to attain my purpose at all costs.","是非とも目標を達成せねばならない。","attain"];
EXAMPLES[4816]=["You are too ready to speak ill of others.","君はよく人の悪口を言う。","speak ill of"];
EXAMPLES[4817]=["Without enough wood on the fire, the flames are already beginning to die down.","暖炉には薪が足りず、早くも火勢が衰え始めている。","die down"];
EXAMPLES[4818]=["The members numbered thirty, all told.","会員は全部で３０名だった。","all told"];
EXAMPLES[4819]=["I have a feeling that Masao may blow in sometime soon.","正夫が近いうちにひょっこり訪ねてくるかもしれない気がする。","blow in"];
EXAMPLES[4820]=["Please grind your teeth from left to right.","歯を左右にすり合わせてください。","grind"];
EXAMPLES[4821]=["At that time the snow plow was certainly our hero.","このとき除雪車は確かに私たちの英雄でした。","plow"];
EXAMPLES[4822]=["I can't conceive of living without him.","彼無しで生きていくなんて私には考えられない。","conceive"];
EXAMPLES[4824]=["The very idea of it is disgusting.","それを思うだけでも気持ちが悪い。","disgusting"];
EXAMPLES[4825]=["We are having fish for our main course.","メインディッシュを魚にしましたよ。","fish for"];
EXAMPLES[4826]=["There I met a very fascinating lady.","そこで私は、とても魅力的な女性に会った。","fascinating"];
EXAMPLES[4827]=["The huge tanker has just left the dock.","巨大なタンカーがついに今し方出港した。","dock"];
EXAMPLES[4828]=["When you take shelter, make sure you go under a big tree.","寄らば大樹の陰。","go under"];
EXAMPLES[4829]=["He decided neither to advance nor to retreat.","彼は前進も後退もすまいと決めた。","retreat"];
EXAMPLES[4830]=["We'll employ a new tool to increase productivity.","生産性をあげるため新たなツールを探してます。","productivity"];
EXAMPLES[4832]=["The waiting car was big and black and shiny.","待っていたのは黒光りのする大型車だった。","shiny"];
EXAMPLES[4833]=["Man is a complex organism.","人間は複雑な有機体だ。","organism"];
EXAMPLES[4834]=["We must sow the seeds of mutual understanding.","我々は相互理解の種をまかねばならない。","sow"];
EXAMPLES[4836]=["To pick a fight with her, that's courageous.","彼女に張り合おうとは、いい度胸ね。","courageous"];
EXAMPLES[4838]=["The mayor walked at the head of the procession.","市長は行列の先頭に立って歩いた。","procession"];
EXAMPLES[4840]=["He carries himself with the majesty of a king.","彼は王者の風格を備えている。","majesty"];
EXAMPLES[4841]=["He fell under the suspicion of the police.","彼は警察の嫌疑を受けた。","suspicion"];
EXAMPLES[4842]=["He's desperately trying to make up for the delay.","彼は遅れを取り戻そうと焦っている。","desperately"];
EXAMPLES[4843]=["I didn't mean to startle you.","びっくりさせるつもりじゃなかった。","startle"];
EXAMPLES[4844]=["Tom is the heir to the Japanese ryokan.","トムは老舗旅館の跡取り息子だよ。","heir"];
EXAMPLES[4845]=["He had the illusion that he was a genius.","彼は自分が天才だと錯覚していた。","illusion"];
EXAMPLES[4846]=["He is very progressive, not to say radical.","彼は過激とは言わないまでも非常に進歩的だ。","progressive"];
EXAMPLES[4847]=["She mourned the death of her only son.","彼女は一人息子の死をいたみ悲しんだ。","mourned"];
EXAMPLES[4848]=["The skater spun round and round on the ice.","そのスケーターは氷の上でぐるぐる回った。","round and round"];
EXAMPLES[4849]=["I owe what I am solely to both my parents.","今日のあたしがあるのはひとえに両親のお陰です。","solely"];
EXAMPLES[4850]=["The students were ill at ease before the exam.","学生たちは試験を前にして落ち着かなかった。","ill at ease"];
EXAMPLES[4851]=["They had to strive against natural calamities for ages.","彼らは長い間天災と闘わねばならなかった。","strive"];
EXAMPLES[4852]=["You have to snatch at happiness when you can.","幸福は掴めるときに掴まなければならない。","snatch"];
EXAMPLES[4853]=["You should omit this word from the sentence.","その文からこの言葉を省略すべきです。","omit"];
EXAMPLES[4854]=["Don't despise a man because he is poor.","貧しいからといって人を軽蔑してはならない。","despise"];
EXAMPLES[4855]=["The duty of a daughter is in obedience.","娘のつとめは従うことにある。","obedience"];
EXAMPLES[4856]=["One will come to find boredom in anything no matter what.","何にだって飽きは来る。","boredom"];
EXAMPLES[4857]=["We should furnish enough food for sufferers.","私たちは罹災者たちに十分な食料を供給すべきだ。","furnish"];
EXAMPLES[4858]=["It says girls born under Cancer are'daring'.","蟹座の女の子って『だいたん』なんだって。","daring"];
EXAMPLES[4859]=["I have some appreciation of your problems.","貴方が困っているのは少しは解っている。","appreciation"];
EXAMPLES[4860]=["The good will not necessarily prosper.","善人が必ずしも成功するとは限らない。","prosper"];
EXAMPLES[4861]=["His prospects are not so rosy as you suppose.","彼の前途は君が思うほど有望ではない。","rosy"];
EXAMPLES[4862]=["The taste of sugar is too noticeable.","この味は砂糖が勝ち過ぎている。","noticeable"];
EXAMPLES[4864]=["I like carrots least of all.","私はとりわけニンジンがきらいだ。","least of all"];
EXAMPLES[4865]=["The city was ruined by the brutal force of nature.","この町は自然の残忍な力によって破壊された。","brutal"];
EXAMPLES[4866]=["I'm planning to disguise myself as a doctor.","医者に変装するつもりです。","disguise"];
EXAMPLES[4867]=["Please consult with your parents about the trip.","旅行についてはご両親と相談してください。","consult"];
EXAMPLES[4868]=["People react to the frustration in much the same way.","人は欲求不満に対してほとんど同じように反応する。","frustration"];
EXAMPLES[4869]=["I see Tom as cunning rather than clever.","トムは賢いというよりずる賢いイメージだな。","cunning"];
EXAMPLES[4870]=["Don't make a fuss about trifles.","つまらないことで騒ぎ立てるな。","make a fuss"];
EXAMPLES[4871]=["He let on that he was a lawyer.","彼は弁護士のふりをした。","let on"];
EXAMPLES[4872]=["Come here and let me hug you.","こっち来てハグさせて。","hug"];
EXAMPLES[4873]=["It is absurd of you to do that.","君がそんなことをするなんてばかげている。","absurd"];
EXAMPLES[4874]=["Will you run down to the corner and buy me a paper?","角までひとっ走りして新聞を買ってきてくれよ。","run down"];
EXAMPLES[4876]=["She gave a flat refusal to my offer.","彼女は私の申し出を素っ気なく断った。","refusal"];
EXAMPLES[4877]=["Last year was a period of economic uncertainty.","昨年は経済的に不確実な時代でした。","uncertainty"];
EXAMPLES[4878]=["He was the leader of the great expedition.","彼はその大遠征のリーダーだった。","expedition"];
EXAMPLES[4879]=["Women have been resigned to unjust treatment for too long.","女性は余りにも長い間不公平な待遇に甘んじてきた。","unjust"];
EXAMPLES[4880]=["I was moved to tears by the tragic story.","悲しい物語に涙を催した。","tragic"];
EXAMPLES[4881]=["He has some knowledge of editing.","彼は多少編集の知識がある。","editing"];
EXAMPLES[4882]=["Please fill out the Customs Declaration Form.","税関申告書に記入してください。","Declaration"];
EXAMPLES[4883]=["Let's tighten our stomachs and try to sing.","お腹にぐっと力を入れて、歌うようにしてみましょう。","tighten"];
EXAMPLES[4885]=["I got gloomy and thought of giving up.","私は落ち込んでしまいあきらめようかと思った。","gloomy"];
EXAMPLES[4886]=["He compared the imitation with the original.","彼はその模造品を本物と比較した。","imitation"];
EXAMPLES[4887]=["This is the latest acquisition to my library.","これがごく最近私の蔵書に加わった本です。","acquisition"];
EXAMPLES[4888]=["As a starter job, I think the warrior is good.","最初のジョブはウォーリアがいいと思います。","warrior"];
EXAMPLES[4889]=["A sentence normally has a subject and a verb.","文には普通、主語と動詞がある。","verb"];
EXAMPLES[4890]=["He was there physically, but not mentally.","彼は心ここにあらずという感じだった。","physically"];
EXAMPLES[4892]=["You should do the honorable thing and resign.","君は潔く辞任すべきだ。","honorable"];
EXAMPLES[4893]=["We didn't anticipate their buying a new car.","私たちは彼らが新車を買うなんて予想もしなかった。","anticipate"];
EXAMPLES[4895]=["We sat, as it were, on a volcano.","われわれは、いわば、火山の上に座っているようなものだった。","volcano"];
EXAMPLES[4896]=["She is a girl full of sentiment.","彼女は気持ちのやさしい女の子だ。","sentiment"];
EXAMPLES[4898]=["Since then, his faith has been severely shaken.","その時いらい彼の信念はひどくぐらついている。","severely"];
EXAMPLES[4899]=["The education system needs to be more flexible.","もっとゆとりのある教育が必要だ。","flexible"];
EXAMPLES[4900]=["He made a speech at the wedding feast.","彼は結婚披露宴でスピーチをした。","feast"];
EXAMPLES[4901]=["It would be good for you to study eagerly.","あなたは懸命に勉強をすればよい。","eagerly"];
EXAMPLES[4902]=["The land on his farm is very fertile.","彼の農場の土はとても肥えている。","fertile"];
EXAMPLES[4903]=["Should I put this bag in the overhead compartment?","このバッグは上の棚に入れた方がいいですか。","overhead"];
EXAMPLES[4905]=["Why he did it is beyond my comprehension.","なぜ彼がそれをやったかがわからない。","comprehension"];
EXAMPLES[4906]=["There was a touch of irony in his speech.","彼の演説には少し皮肉っぽいところがあった。","irony"];
EXAMPLES[4907]=["The surgeon operated on her for lung cancer.","医者は彼女の肺がんの手術をした。","surgeon"];
EXAMPLES[4908]=["I had a lick at the jam.","そのジャムをちょっとなめてみた。","lick"];
EXAMPLES[4910]=["You can get anything less expensive in bulk.","物はすべて一括して買うとやすい。","bulk"];
EXAMPLES[4911]=["Do you know what the spikes on a cactus are for?","サボテンのトゲって何のためにあるか知ってる？","cactus"];
EXAMPLES[4912]=["We cannot grieve over his death too deeply.","彼の死は惜しんでも余りあるものだ。","grieve"];
EXAMPLES[4914]=["Tom gave Mary a kiss on the forehead.","トムはメアリーの額にキスをした。","forehead"];
EXAMPLES[4915]=["In terms of development, the site was productive.","現場は開発に積極的だった。","productive"];
EXAMPLES[4916]=["This room is noisy. The sound bounces right off the walls.","話し声が壁に反響してうるさいな、この部屋。","right off"];
EXAMPLES[4917]=["I'd like to insure this, please.","これに保険をかけたいのですが。","insure"];
EXAMPLES[4918]=["The man was hiding in a dense forest.","男はこんもりした森に隠れていた。","dense"];
EXAMPLES[4919]=["Many people were plunged into distress by the news.","その知らせは多くの人々を苦悩におとしいれた。","distress"];
EXAMPLES[4920]=["He occupies a prominent position in the firm.","彼は会社で重要な地位を占めている。","prominent"];
EXAMPLES[4921]=["He is as great a statesman as any.","彼は世にもまれな大政治家である。","statesman"];
EXAMPLES[4923]=["Our experimental results left something to be desired.","実験の結果は今ひとつぱっとしなかった。","experimental"];
EXAMPLES[4925]=["Likewise, it was nice to meet you.","こちらこそ、私もお会いできてよかったです。","Likewise"];
EXAMPLES[4926]=["You can bank on that.","君はそれを当てにできる。","bank on"];
EXAMPLES[4927]=["Your only remedy is to go to the law.","唯一の解決法は法に訴えることだ。","remedy"];
EXAMPLES[4928]=["I used to work in an electronics store.","以前は電器店に勤めていました。","electronics"];
EXAMPLES[4929]=["My dream is to be fluent in French.","僕の夢は、フランス語がペラペラになることなんだ。","fluent"];
EXAMPLES[4930]=["The farewell party will take place next week.","送別会は来週行われるでしょう。","farewell"];
EXAMPLES[4931]=["May I present this to you in token of my appreciation?","感謝のしるしにこれをさし上げたいと存じます。","in token of"];
EXAMPLES[4932]=["She is a person with a fierce temper.","彼女は癇癖の強い人です。","fierce"];
EXAMPLES[4933]=["It's like sprinkling water on a desert.","砂漠に水をまくようなものだ。","sprinkling"];
EXAMPLES[4934]=["No matter what it takes we must prevail.","何としても勝たなければ。","prevail"];
EXAMPLES[4935]=["I snapped the thread on my canine.","プチッ、と糸を犬歯で噛み切った。","canine"];
EXAMPLES[4936]=["He's been a patron of this store for many years.","あの人はこの店の長年の馴染み客です。","patron"];
EXAMPLES[4937]=["He trained his dog to fetch the newspaper.","彼は自分の犬に新聞を取ってくるように訓練した。","fetch"];
EXAMPLES[4938]=["She pleaded with him not to disturb her.","彼女は彼に邪魔しないようにと嘆願した。","pleaded"];
EXAMPLES[4939]=["Can we reach a consensus on this issue?","私たちはこの問題に関して合意に達することが出来るだろうか。","consensus"];
EXAMPLES[4940]=["I don't remember my father's face accurately.","僕は父の顔を正確には覚えていない。","accurately"];
EXAMPLES[4942]=["On his shirt there was a sauce stain.","彼のシャツにはソースのしみがついていた。","stain"];
EXAMPLES[4944]=["She plans to stay at the Oriental Hotel.","彼女はオリエンタルホテルに泊まるつもりです。","Oriental"];
EXAMPLES[4946]=["Dissolve the tablet in a glass of water.","カップにピルを溶かし入れてください。","Dissolve"];
EXAMPLES[4947]=["Taking moderate exercise is good for the health.","適度な運動することは体によい。","moderate"];
EXAMPLES[4948]=["Zap it in the microwave for thirty seconds.","30秒、レンジでチンして。","microwave"];
EXAMPLES[4949]=["Everyone is imperfect, and that's OK.","誰にでも欠点はある。それでいいのよ。","imperfect"];
EXAMPLES[4950]=["It was identified by telescope as a torch.","望遠鏡で見ると、それはたいまつであることがわかった。","torch"];
EXAMPLES[4951]=["A boy stood by to run errands for her.","彼女の使い走りをしようと一人の少年が待機した。","run errands"];
EXAMPLES[4952]=["I thought I told you to trim your beard.","ひげを整えるようにあなたに言ったはずですが。","trim"];
EXAMPLES[4953]=["We recognize that this is a serious defect.","重大な瑕疵があると認識している。","defect"];
EXAMPLES[4954]=["He has not taken the highest level evaluation, but he is good at mathematics.","彼は数学が得意なのだが最高の判定を取ったことがない。","evaluation"];
EXAMPLES[4955]=["A flight attendant walks up to the boys.","客室乗務員が少年達の方にやって来ます。","attendant"];
EXAMPLES[4956]=["She used a damp rag to wipe off the dust.","彼女はほこりを拭うのに湿った布を使った。","rag"];
EXAMPLES[4957]=["He elbowed me in the ribs.","彼はひじで私の脇腹をつついた。","ribs"];
EXAMPLES[4959]=["That's it in a nutshell.","早い話が、そういうことですな。","in a nutshell"];
EXAMPLES[4960]=["When the wine is in, the wit is out.","酒が入れば知恵が出ていく。","wit"];
EXAMPLES[4962]=["He seems to be unaware of his mistake.","彼は自分の誤りに気づいていないようだ。","unaware"];
EXAMPLES[4963]=["In India, the cow is a sacred animal.","インドでは牛は神聖な動物です。","sacred"];
EXAMPLES[4964]=["Take this medicine faithfully, and you will feel better.","この薬を正確に飲みなさい。そうすれば気分がよくなるでしょう。","faithfully"];
EXAMPLES[4965]=["For how long did the Maya culture flourish?","マヤ文明はどのくらいの間に繁栄したのだろうか。","flourish"];
EXAMPLES[4966]=["Your estimation of him is a little high, to say the least.","君の彼に対する評価は、ひかえ目に言っても、少し高いよ。","to say the least"];
EXAMPLES[4967]=["He is the more diligent of the two.","２人のうちでは彼の方が勤勉です。","diligent"];
EXAMPLES[4968]=["He fashioned an elegant pot out of clay.","彼は、粘土で優雅な壷を形作った。","clay"];
EXAMPLES[4969]=["Traffic lights are used to regulate traffic.","交通信号は交通の流れを規制するために使われている。","regulate"];
EXAMPLES[4970]=["He had the misfortune to lose his son.","彼は不幸にも息子を失った。","misfortune"];
EXAMPLES[4971]=["I forbid smoking in my room.","私の部屋での喫煙を禁ずる。","forbid"];
EXAMPLES[4972]=["Where do you get your inspiration from?","その発想力はどこから来てるの？","inspiration"];
EXAMPLES[4973]=["We saw the gleam of a distant lighthouse.","遠い灯台のかすかな光を見た。","gleam"];
EXAMPLES[4974]=["Birds, for instance, have a special protective device.","例えば、小鳥は特別な防御装置を備えている。","protective"];
EXAMPLES[4975]=["From this point onward outdoor footwear is prohibited.","ここから先は、土足禁止です。","onward"];
EXAMPLES[4976]=["I went to the hospital to inquire after his health.","私は彼の安否を尋ねに病院へ行った。","inquire after"];
EXAMPLES[4977]=["Traveling will immensely enrich our minds.","旅は私たちの心を大いに豊かにするだろう。","immensely"];
EXAMPLES[4978]=["It's money down the drain.","金をどぶに捨てるようなものである。","down the drain"];
EXAMPLES[4979]=["Would you please replace the broken one promptly?","壊れていたものを早急に交換していただけますか。","promptly"];
EXAMPLES[4980]=["The plane landed with a bump.","飛行機はどすんと着陸した。","bump"];
EXAMPLES[4981]=["Please cover for me at the reception desk for about one hour.","一時間ぐらいの間、私の代わりに受付をやってください。","cover for"];
EXAMPLES[4982]=["We sprinkle salt to ward off bad luck.","縁起に塩をまいて清める。","ward"];
EXAMPLES[4983]=["I was a freshman last year.","去年の新人です。","freshman"];
EXAMPLES[4984]=["She is a very refined lady.","彼女は非常に上品な女性です。","refined"];
EXAMPLES[4985]=["I saw his face in the dim light.","薄暗い光の中で彼の顔を見た。","dim"];
EXAMPLES[4986]=["Thank you for helping me write my resume.","履歴書を書くの手伝ってくれてありがとう。","resume"];
EXAMPLES[4987]=["Keep in mind that youth is not eternal.","若さは永遠ではないということを忘れてはならない。","eternal"];
EXAMPLES[4988]=["Brush off the dust from your shoes.","靴のほこりをはけではらいなさい。","Brush off"];
EXAMPLES[4990]=["He dates the custom from the colonial days.","その習慣を彼は植民地時代から始まると推定している。","colonial"];
EXAMPLES[4991]=["The boy can solve any problem in arithmetic.","その子は算数ならどんな問題でも解ける。","arithmetic"];
EXAMPLES[4992]=["I have a great esteem for you.","あなたにはとても頭が上がりません。","esteem"];
EXAMPLES[4993]=["I have gone astray somewhere in my calculation.","僕の計算がどこかで間違ってしまった。","calculation"];
EXAMPLES[4994]=["The performance received terrific applause from the audience.","その演奏は聴衆からすばらしい拍手を得た。","terrific"];
EXAMPLES[4995]=["I know how to stitch a wound.","傷口の縫い方は知ってますよ。","stitch"];
EXAMPLES[4996]=["The pasture has an area of 10 acres.","その牧場は１０エーカーの広さだ。","pasture"];
EXAMPLES[4997]=["I didn't bargain for Mary's coming so soon.","メアリーがそんなに早く来るとは思いもかけなかった。","bargain for"];
EXAMPLES[4999]=["Just as a thorn stuck in one's throat.","喉に刺さった棘の如く。","thorn"];
EXAMPLES[5000]=["There was eternal twilight in the place.","そこには消えることのない薄明かりがあった。","twilight"];
EXAMPLES[5001]=["For a while now I've heard them moan all day.","何日も、朝から晩まで彼らのうめき声が聞こえる。","moan"];
EXAMPLES[5002]=["Now the President is nothing but a lame duck.","今や大統領はレイム・ダックにすぎません。","lame"];
EXAMPLES[5003]=["In Japan, people become legally of age at twenty.","日本では、法的には２０歳で成人になる。","legally"];
EXAMPLES[5006]=["He is a boy of singular intelligence.","彼は並はずれた知能の持ち主である。","singular"];
EXAMPLES[5007]=["The doctors were wrong to condemn the couple.","その夫婦を責めるなんて、医師達は間違っていた。","condemn"];
EXAMPLES[5009]=["It was a great presentation and it felt passionate.","熱意が感じられる良いプレゼンだった。","passionate"];
EXAMPLES[5010]=["Because of his determination, he was able to tide over the crisis.","彼の決断力のおかげで、彼はその危機を乗り切ることが出来た。","tide over"];
EXAMPLES[5011]=["The two countries do not have diplomatic relations.","その両国は外交関係がない。","diplomatic"];
EXAMPLES[5012]=["She is what is called a baseball widow.","彼女はいわゆる野球後家だ。","widow"];
EXAMPLES[5015]=["His manners proclaim him a gentleman.","彼の礼儀作法を見れば彼が紳士であることが分かる。","proclaim"];
EXAMPLES[5017]=["He carved designs in ivory.","彼は象牙に図案を彫った。","ivory"];
EXAMPLES[5018]=["Playing baseball is an outlet for energy.","野球は精力のはけ口になる。","outlet"];
EXAMPLES[5020]=["You must steer clear of that gang.","あの連中には近づいてはいけないよ。","steer"];
EXAMPLES[5021]=["The farmer pitched the hay onto the wagon.","農夫は荷馬車の上へ干し草を放り上げた。","hay"];
EXAMPLES[5022]=["They erected a statue in memory of Gandhi.","ガンジーの記念像が建てられた。","erected"];
EXAMPLES[5023]=["Why do I always stumble through life like this?","どうして僕はこんな不器用な生き方しかできないんだろう。","stumble"];
EXAMPLES[5024]=["It's not a bug, it's an undocumented feature.","それはバグじゃなくて、ドキュメント化されてない仕様です。","bug"];
EXAMPLES[5025]=["Marcia looked grim when I told her the story.","マーシャにその話をしたとき、いかめしい顔つきをした。","grim"];
EXAMPLES[5026]=["The cathedral dates back to the Middle Ages.","その大聖堂の建立は中世にまでさかのぼる。","cathedral"];
EXAMPLES[5027]=["He has something to do with the robbery.","彼はその強盗事件と関係がある。","robbery"];
EXAMPLES[5028]=["She gave him a slap in the face.","彼女は彼の顔に平手打ちを食らわせた。","slap"];
EXAMPLES[5029]=["Don't come to school to lark around.","遊び半分に学校へ来るな。","lark"];
EXAMPLES[5030]=["My mother put on makeup before going out.","母は出かける前に化粧をした。","makeup"];
EXAMPLES[5031]=["I can't remove the indigo dye in my hair!","髪に藍染めがついてとれないよ！","dye"];
EXAMPLES[5032]=["He doesn't mingle with the villagers.","彼は村人たちと交際しない。","mingle with"];
EXAMPLES[5034]=["He works for the good of the country.","彼は国のために働いている。","for the good of"];
EXAMPLES[5035]=["He is in constant dread of his father.","彼は父親を絶えず恐れている。","dread"];
EXAMPLES[5036]=["The laws oblige all citizens to pay taxes.","法律はすべての市民に税を払うように義務づけている。","oblige"];
EXAMPLES[5037]=["If the hunted should perish, the hunter would, too.","万一獲物が死に絶えれば、狩人いなくなるだろう。","perish"];
EXAMPLES[5038]=["The barn was small, but it was strong.","その納屋は小さかったが頑丈だった。","barn"];
EXAMPLES[5039]=["The economist instinctively anticipated the current depression.","その経済学者は現在の不況を本能的に予期していた。","economist"];
EXAMPLES[5040]=["Nothing is more delightful to me than travelling.","旅ほど楽しいものはありません。","delightful"];
EXAMPLES[5041]=["Young people know the disasters of war only in the abstract.","若者は戦火というものを頭でしか知らない。","in the abstract"];
EXAMPLES[5042]=["We must not give way to their demands.","我々は彼らの要求に屈するわけにはいかない。","give way"];
EXAMPLES[5043]=["A function that is differentiable everywhere is continuous.","あらゆる点で微分可能な関数は連続関数です。","continuous"];
EXAMPLES[5044]=["In due time, his innocence will be proven.","時が来れば彼の無罪が証明されるだろう。","proven"];
EXAMPLES[5045]=["The Emperor is the symbol of the unity of the people.","天皇は国民の統合の象徴である。","unity"];
EXAMPLES[5046]=["You are the master of your own destiny.","君は君自身の運命の主でもあります。","destiny"];
EXAMPLES[5047]=["The Diet is now in recess in session.","国会は現在閉会中である。","recess"];
EXAMPLES[5049]=["At the party there was food in abundance.","パーティーでは食べきれないほど食べ物が出た。","abundance"];
EXAMPLES[5051]=["The strange-looking woman was thought to be a witch.","その怪しい女性は、魔女と考えられた。","witch"];
EXAMPLES[5053]=["We had a glorious time at the seaside.","私達は海岸ですばらしいひとときを過ごした。","glorious"];
EXAMPLES[5054]=["It is damp and cold today, isn't it?","今日は、じめじめして寒いですね。","damp"];
EXAMPLES[5055]=["Where should we dispose of the waste?","その廃棄物はどこに処分したらいいのか。","dispose of"];
EXAMPLES[5056]=["Today was a day filled with commotion.","今日もバタバタした一日だった。","commotion"];
EXAMPLES[5057]=["An old oak is groaning in the storm.","樫の老木が嵐にうめいている。","groaning"];
EXAMPLES[5058]=["The recent frequency of earthquakes makes us nervous.","近頃は地震が頻繁で不気味だ。","frequency"];
EXAMPLES[5059]=["The soldier lay in agony on the bed.","その兵士はベッドに横たわってもだえ苦しんでいた。","agony"];
EXAMPLES[5060]=["Don't trifle with such serious matters.","そんな重要な問題をいいかげんに扱ってはいけない。","trifle with"];
EXAMPLES[5061]=["Trying to tempt her, I gazed into her face.","彼女を誘惑しようとして、私は彼女の顔をじっとみつめた。","tempt"];
EXAMPLES[5062]=["Such a case is not uncommon today.","そんな例は今日では珍しいことではありません。","uncommon"];
EXAMPLES[5063]=["The fields abound in wild flowers.","野原には野生の花がたくさんある。","abound in"];
EXAMPLES[5064]=["There was a happy twinkle in her eyes.","彼女は幸福そうに目を輝かせていた。","twinkle"];
EXAMPLES[5066]=["I heard the howl of a wolf.","オオカミの遠吠えを聞きました。","howl"];
EXAMPLES[5067]=["Don't translate English into Japanese word for word.","英語を逐語的に日本語訳してはいけない。","word for word"];
EXAMPLES[5068]=["I think I will take a detour to return home.","今日は遠回りをして帰ろっと。","detour"];
EXAMPLES[5070]=["You don't need to flatter your boss.","あなたはボスにへつらわなくてもよい。","flatter"];
EXAMPLES[5071]=["Those tribes inhabit the desert all year round.","その部族は年中砂漠に住んでいる。","inhabit"];
EXAMPLES[5072]=["You must build up your courage.","君は胆力を練る必要がある。","build up"];
EXAMPLES[5073]=["It was prudent of you to save money.","貯金をしておくとはあなたは慎重でしたね。","prudent"];
EXAMPLES[5074]=["Let this smoky air out of the room and let some fresh air in.","タバコで煙った空気を部屋から出して、新鮮な空気を入れてちょうだい。","air out"];
EXAMPLES[5075]=["You shall want for nothing.","君には不自由させない。","want for"];
EXAMPLES[5076]=["The conductor of this orchestra is a fine musician.","このオーケストラの指揮者は優れた音楽家です。","conductor"];
EXAMPLES[5077]=["That's not absolutely certain.","それは絶対確実とは言えない。","not absolutely"];
EXAMPLES[5078]=["The drawer is stuffed full of odds and ends.","引き出しはがらくたでぎっしり詰まっている。","odds and ends"];
EXAMPLES[5079]=["If he carries on like this, he's going to wind up in prison.","もしこんなことを続けていたら、彼は刑務所に入るはめになるぞ。","wind up"];
EXAMPLES[5080]=["The monarch is supposed to attend the funeral.","君主はその葬儀に出席することになっている。","monarch"];
EXAMPLES[5081]=["A fire was seen to blaze up far away.","遠くに火が燃え上がるのが見えた。","blaze"];
EXAMPLES[5082]=["She fell in a heap to the floor.","彼女は床に崩れるようにして倒れた。","heap"];
EXAMPLES[5083]=["He exclaimed that she was beautiful.","彼女が美しいので彼は感嘆の声をあげた。","exclaimed"];
EXAMPLES[5084]=["The movie is a stereotyped sob story.","その映画はお涙頂戴ものだ。","sob"];
EXAMPLES[5085]=["The irresponsible remark has sent the scene into chaos.","無責任な発言で現場は大混乱。","chaos"];
EXAMPLES[5086]=["He likes to go on explorations to Africa.","彼はアフリカへ探検旅行に行くのが好きだ。","explorations"];
EXAMPLES[5087]=["Building up too much stress has a detrimental effect on your health.","ストレスを溜めすぎると健康に悪影響を及ぼす。","detrimental"];
EXAMPLES[5088]=["The prevention of forest fires is everyone's responsibility.","森林火災の防止はすべての人が負う義務です。","prevention"];
EXAMPLES[5089]=["She was not in the mood for serious books.","彼女は肩が凝る本を読む気にはなれなかった。","in the mood for"];
EXAMPLES[5091]=["By dint of long practice he became most skillful.","長く練習したおかげで彼はとても熟達した。","By dint of"];
EXAMPLES[5092]=["He is reluctant to go to the college.","彼は大学へ行きたがらない。","reluctant"];
EXAMPLES[5093]=["That country remained neutral throughout World War II.","その国は第二次世界大戦中は中立を保っていた。","neutral"];
EXAMPLES[5094]=["We can have that for you by tomorrow; no sweat.","それなら明日までに用意できるよ。おやすい御用だ。","no sweat"];
EXAMPLES[5095]=["I'm not as influential as you think I am.","あなたが思っているほど私は影響力がない。","influential"];
EXAMPLES[5096]=["Although Bob was in disguise, I recognized him at a glance.","ボブは変装していたけれども、一目で彼と分かった。","in disguise"];
EXAMPLES[5097]=["The very thought of snakes makes her turn pale.","ヘビのことを考えるだけで彼女の顔は青くなる。","turn pale"];
EXAMPLES[5098]=["They will contact us before midday today.","彼らは昼前に連絡します。","midday"];
EXAMPLES[5099]=["An exhibition was given in anticipation of the Queen's visit.","女王の訪問を見越して展示会が開催された。","in anticipation of"];
EXAMPLES[5100]=["Something is wrong with the experimental apparatus.","実験用器具が故障している。","apparatus"];
EXAMPLES[5101]=["The baby in the cradle is very pretty.","ゆりかごの中の赤ん坊はとてもかわいい。","cradle"];
EXAMPLES[5102]=["Things that modify nouns (adjective, or adjectival equivalent).","名詞を修飾するもの（形容詞、または形容詞相当語句）。","nouns"];
EXAMPLES[5103]=["It's not a toothpaste, it's a face-cleansing foam!","それ歯磨き粉じゃなくて洗顔フォームだよ！","foam"];
EXAMPLES[5104]=["My grandmother is very forgetful of things nowadays.","祖母は最近とても物事を忘れるようになりました。","forgetful"];
EXAMPLES[5105]=["These slums are a disgrace to the city.","このようなスラム街は市の恥だ。","disgrace"];
EXAMPLES[5106]=["We were not a little disappointed with you.","少なからず君には失望したよ。","disappointed"];
EXAMPLES[5107]=["The police managed to track down the owner of the car.","警察は車の持ち主を何とか突きとめることができた。","track down"];
EXAMPLES[5108]=["He was to succeed to the throne.","彼は王位を継承することになっていた。","throne"];
EXAMPLES[5109]=["I love my yellow pullover very much.","私は自分の黄色いプルオーバーが大好きだ。","pullover"];
EXAMPLES[5110]=["He took it in his stride.","彼はそのことに関して平然としていた。","stride"];
EXAMPLES[5111]=["I was impatient for the game to start.","試合が始まるのが待ちきれなかった。","impatient"];
EXAMPLES[5112]=["He says he will inquire into the matter.","彼は問題を調査するといっている。","inquire"];
EXAMPLES[5113]=["There was a murmur when she entered the room.","彼女が部屋にはいったとき、ささやきが聞こえた。","murmur"];
EXAMPLES[5114]=["He is an undergraduate in the law department.","彼は法科の学生だ。","undergraduate"];
EXAMPLES[5115]=["I rest on your promise.","君の約束を当てにしている。","rest on"];
EXAMPLES[5116]=["Taiwan is preparing itself for a Chinese invasion.","台湾は中国の侵攻に備えている。","invasion"];
EXAMPLES[5117]=["Sue and John decided to take the plunge.","スーとジョンは結婚することに決めた。","plunge"];
EXAMPLES[5118]=["The smell of the perfume is excessively harsh.","香水の匂いがきつ過ぎだよ。","perfume"];
EXAMPLES[5119]=["The train was brought to a sudden halt.","汽車は突然止まった。","halt"];
EXAMPLES[5120]=["My husband isn't quite the provider he should be.","うちの亭主は甲斐性がない。","provider"];
EXAMPLES[5121]=["He must have done it out of mischief.","彼はいたずら半分にそれをしたにちがいない。","mischief"];
EXAMPLES[5122]=["Did you hear the roar of the lions?","ライオンの吠える声を聞きましたか。","roar"];
EXAMPLES[5123]=["We must keep down expenses.","我々は費用を切り下げなければならない。","keep down"];
EXAMPLES[5124]=["She plainly interpreted Picasso's paintings to me.","彼女は私にピカソの絵をやさしく説明してくれた。","plainly"];
EXAMPLES[5126]=["It must have been broken during shipping.","船積みの時壊れたに違いない。","shipping"];
EXAMPLES[5128]=["How many new sites were uncovered?","新しい遺跡で未発掘はいくつだったのですか。","uncovered"];
EXAMPLES[5129]=["He is a diplomat at the American Embassy.","彼はアメリカ大使館の外交官である。","Embassy"];
EXAMPLES[5130]=["He is extremely pessimistic and has no aspirations.","彼は非常に悲観的で希望を持っていない。","pessimistic"];
EXAMPLES[5131]=["She answered all the questions with assurance.","彼女は全ての問題に自信を持って答えた。","assurance"];
EXAMPLES[5132]=["In spite of their tiny restaurant they managed to pull through the recession.","小さなレストランにもかかわらず、彼らは何とか不況を通りぬけた。","pull through"];
EXAMPLES[5133]=["How can I say things to sound graceful?","どう言えば、おしとやかに聞こえる？","graceful"];
EXAMPLES[5134]=["At times I confuse curve with carve.","私は時々ＣｕｒｖｅとＣａｒｖｅを混同してしまう。","carve"];
EXAMPLES[5135]=["Don't miss out on this opportunity.","この機会を逃すんじゃない。","miss out"];
EXAMPLES[5138]=["She is remarkably attractive.","彼女は並外れて魅力的だ。","remarkably"];
EXAMPLES[5139]=["Benefits of course should exceed the costs.","もちろん利潤は生産費を上回るべきです。","exceed"];
EXAMPLES[5140]=["That rose will revive if you water it.","水をやればそのバラは生き返るでしょう。","revive"];
EXAMPLES[5141]=["No one can deprive of your human rights.","誰もあなたの人権を奪うことはできない。","deprive"];
EXAMPLES[5142]=["The association is still a far cry from being well organized.","協会は十分に組織されているとはいえない。","far cry from"];
EXAMPLES[5143]=["Most snakes on this island are harmless.","この島ではたいていのヘビは無害である。","harmless"];
EXAMPLES[5144]=["He did not consent to his daughter's marriage.","彼は娘の結婚に同意しなかった。","consent"];
EXAMPLES[5145]=["It is merely an ornament.","それは飾りにすぎない。","ornament"];
EXAMPLES[5146]=["Please send in your summary by Tuesday.","要約を火曜日までに提出しなさい。","send in"];
EXAMPLES[5147]=["Just you wait and see, idiots.","待ってろよ、馬鹿ども。","idiots"];
EXAMPLES[5148]=["The plural of horse is horses.","\"horse\"の複数形は\"horses\"です。","plural"];
EXAMPLES[5149]=["His manner marks him as a provincial.","彼の態度から彼が地方出身なことは明らかだ。","provincial"];
EXAMPLES[5150]=["This is the payment for the project's waste removal transport cost.","これはプロジェクトの廃物撤去輸送支払いです。","removal"];
EXAMPLES[5151]=["I have a touch of diarrhea.","下痢気味です。","diarrhea"];
EXAMPLES[5152]=["Didn't you have work off today?","今日は休みじゃなかったの？","work off"];
EXAMPLES[5153]=["The waiter filled our glasses to the brim.","ウエイターは私たちのグラスになみなみと注いだ。","brim"];
EXAMPLES[5154]=["He is always dwelling on the pleasures of the past.","彼はいつも過去の楽しい思い出にふけっている。","dwelling"];
EXAMPLES[5155]=["The vigorous man is engaged in diverse activities.","その精力的な男は様々な活動に加わっている。","diverse"];
EXAMPLES[5156]=["It was told me under pledge of secrecy.","それは秘密を守るという約束で私に話された。","pledge"];
EXAMPLES[5157]=["We wait in anticipation of meeting.","お待ちしております。","anticipation"];
EXAMPLES[5158]=["The summit talks are to be broadcast simultaneously throughout the world.","首脳会談は世界中で同時に放送される予定だ。","simultaneously"];
EXAMPLES[5159]=["In addition, coincidences inevitably come in threes.","偶然も３度重なれば必然になる。","inevitably"];
EXAMPLES[5160]=["Mrs. Crouch, do you have a job?","クラウチ夫人、仕事はお持ちですか。","Crouch"];
EXAMPLES[5161]=["We decided to branch out into selling some foodstuffs.","業務を拡張して食料品を少し売ることに決めた。","branch out"];
EXAMPLES[5162]=["At the party there was food in abundance.","パーティーでは食べきれないほど食べ物が出た。","in abundance"];
EXAMPLES[5163]=["Don't pull like that! You'll rip my clothes.","そんなに引っ張らないで、服が破れるでしょ！","rip"];
EXAMPLES[5164]=["The shop is kept under police supervision.","その店は警察の監督のもとにある。","supervision"];
EXAMPLES[5166]=["He makes himself accessible to all who seek his counsel.","彼は自分の助言を求める人にはみんな面会できるようにしている。","counsel"];
EXAMPLES[5167]=["You ought to be ashamed to cheat on exams.","あなたはカンニングをすることを恥と思うことである。","cheat on"];
EXAMPLES[5168]=["It's apparently a metaphor for something uncatchable, light of body and fleet of foot.","捕らえることのできないもの、身軽で素早いもののたとえ、だそうです。","metaphor"];
EXAMPLES[5169]=["The victims are entitled to compensation for their injuries.","被害者たちにはけがの補償を受ける権利がある。","compensation"];
EXAMPLES[5170]=["It was impolite of him to do so.","彼がそうしたのは無作法であった。","impolite"];
EXAMPLES[5171]=["From childhood I dreamed of being a pastry cook.","ケーキ職人は小さい頃からの夢でした。","pastry"];
EXAMPLES[5172]=["He was excused from the remainder of the work.","彼は残りの仕事を免除された。","remainder"];
EXAMPLES[5173]=["Have you finished reading the biography of Jobs?","ジョブズの伝記読み終わったかい？","biography"];
EXAMPLES[5174]=["Be patient and persistent. These things take time.","石の上にも三年、というじゃない。もう少し辛抱しなさいよ。","persistent"];
EXAMPLES[5175]=["Get the rubbish out of the building.","この建物からガラクタを運び出してくれ。","rubbish"];
EXAMPLES[5176]=["Don't do such a shameful thing in public.","人前でああいうみっともないことはするな。","shameful"];
EXAMPLES[5178]=["Tom was a ball of vanity.","トムは虚栄心の塊のような人だった。","vanity"];
EXAMPLES[5179]=["The umpire said that he was out.","審判は彼にアウトを宣した。","umpire"];
EXAMPLES[5180]=["He was overwhelmed by the intensity of her love.","彼は彼女の愛情の強さに圧倒された。","intensity"];
EXAMPLES[5181]=["He is not a businessman but a diplomat.","彼はビジネスマンではなく外交官だ。","diplomat"];
EXAMPLES[5183]=["He has received a commission as a naval officer.","彼は海軍士官の任務を受けた。","naval"];
EXAMPLES[5184]=["Tall buildings may sway in a strong wind.","強風が吹けば高層ビルは揺れるだろう。","sway"];
EXAMPLES[5185]=["He looked at the slide under the microscope.","彼はそのスライドを顕微鏡で見た。","microscope"];
EXAMPLES[5186]=["Investigators are running a probe into what caused the crash.","調査団は墜落の原因について綿密な調査を行っています。","probe"];
EXAMPLES[5187]=["The bright boy comprehended the concept of geometry.","頭の良いその少年は幾何学の概念を理解した。","geometry"];
EXAMPLES[5188]=["He is absorbed in the study of the Fuzzy Theory.","彼はファジィ理論の研究に没頭しています。","Fuzzy"];
EXAMPLES[5189]=["The skyscraper rose above the other buildings around.","その摩天楼はまわりの他の建物の上方にそびえていた。","skyscraper"];
EXAMPLES[5190]=["She is incapable of deceit.","彼女は嘘のつけない人だ。","deceit"];
EXAMPLES[5191]=["He put down the rebellion in India.","彼はインドの反乱を鎮めた。","rebellion"];
EXAMPLES[5192]=["Lay down all arms.","すべての武器を捨てよう。","Lay down"];
EXAMPLES[5194]=["A gentleman would not spit on the street.","紳士なら、道につばなど吐かないだろう。","spit"];
EXAMPLES[5195]=["Let's think out another way.","別の方法を考え出そう。","think out"];
EXAMPLES[5196]=["Mike acted as chairperson of the meeting.","マイクは会議で議長として振舞った。","chairperson"];
EXAMPLES[5197]=["Wolves live in areas where game is plentiful.","オオカミは獲物が豊富な地域に住んでいる。","plentiful"];
EXAMPLES[5198]=["His brother is all thumbs, but he is a skillful surgeon.","兄は全く不器用なのに、彼は優秀な外科医だ。","all thumbs"];
EXAMPLES[5199]=["I caught him stealing pears in the orchard.","私は彼が果樹園でナシを盗んでいるところを見つけた。","orchard"];
EXAMPLES[5200]=["His mother is in attendance on him.","母親が、彼の看護にあたってる。","attendance"];
EXAMPLES[5201]=["Easter will soon come around.","間もなくイースターがめぐってきます。","come around"];
EXAMPLES[5202]=["In all probability, we'll arrive before they do.","きっと私たちの方が彼らよりも前に到着するだろう。","probability"];
EXAMPLES[5203]=["Strange to say, his prediction has come true.","不思議な話だが、彼の予言は当たった。","prediction"];
EXAMPLES[5204]=["Our ownership in the company is 60%.","我々の同社における持分は、６０％です。","ownership"];
EXAMPLES[5205]=["Find the solution to the following equation.","以下の方程式の解を求めよ。","equation"];
EXAMPLES[5206]=["On the left is reception, and to the right is accounting.","左が受付で、右が会計です。","accounting"];
EXAMPLES[5207]=["The vase fell to the floor and shattered.","花瓶は床に落ちて粉々になった。","shattered"];
EXAMPLES[5208]=["Regretfully, the Japanese representative was eliminated at the preliminary stage.","日本代表は惜しくも予選敗退となりました。","preliminary"];
EXAMPLES[5209]=["His laziness is past the margin of endurance.","彼の怠け癖は我慢の限界を越える。","endurance"];
EXAMPLES[5210]=["Our combined fleet broke through the enemy's defense zone.","わが連合艦隊は敵の防衛海域を突破した。","fleet"];
EXAMPLES[5211]=["You don't have to stand over me.","見てなくったっていいよ。","stand over"];
EXAMPLES[5212]=["He claimed that he had discovered a new comet.","彼は新しい彗星を発見したと主張した。","comet"];
EXAMPLES[5213]=["He lives in a little cozy house.","彼は住み心地がよい小さな家に住んでいます。","cozy"];
EXAMPLES[5214]=["No speculation has taken place concerning the motives.","動機についてはまったく考察されていない。","speculation"];
EXAMPLES[5215]=["He asked his brother to execute his will.","彼は弟に遺言を実行してくれと頼んだ。","execute"];
EXAMPLES[5216]=["I have a flat tire.","パンクしている。","have a flat tire"];
EXAMPLES[5217]=["The nun prayed and crossed herself.","尼僧はお祈りをして十字を切った。","nun"];
EXAMPLES[5220]=["Hit the ball after the bounce.","ボールがバウンドして上がってくるところを打つ。","bounce"];
EXAMPLES[5221]=["The spokesman explained the blueprint of the scheme to the press.","報道担当官がその計画の青写真を報道陣に説明した。","blueprint"];
EXAMPLES[5222]=["I have no intention whatever of disturbing you.","私はあなたの邪魔をするつもりは全くありません。","disturbing"];
EXAMPLES[5223]=["They were most attentive to his speech.","みんなは彼の話を注意深く聞いた。","attentive"];
EXAMPLES[5225]=["It is cruel to mock a blind man.","目の不自由な人をばかにするのは残酷なことである。","mock"];
EXAMPLES[5227]=["The receptionist said to come right in.","受け付け係は、すぐさま来るようにと言った。","receptionist"];
EXAMPLES[5228]=["May I see two pieces of identification?","身分証明書を二枚拝見できますか。","identification"];
EXAMPLES[5229]=["This path will lead you to the shrine.","この道は神社へ通じていますよ。","shrine"];
EXAMPLES[5230]=["He likes to take a solitary walk.","彼は一人で散歩をするのが好きだ。","solitary"];
EXAMPLES[5232]=["The men are smiling on cue.","男性たちは合図に合わせて微笑んでいる。","cue"];
EXAMPLES[5233]=["They scrambled for the penny in the street.","彼らは路上で１ペニー硬貨を奪い合った。","scrambled"];
EXAMPLES[5236]=["Astronomers inferred the existence of a local supercluster.","天文学者が局部超銀河団の存在を推定しました。","Astronomers"];
EXAMPLES[5237]=["They are faced with a multitude of stresses.","彼らは多くのストレスに直面している。","multitude"];
EXAMPLES[5238]=["Good lumber is hard to find these days.","近頃はよい材木を見つけるのが難しいですね。","lumber"];
EXAMPLES[5239]=["We got a hostile reception from the villagers.","私たちは村人から敵意を持って迎えられた。","hostile"];
EXAMPLES[5240]=["We created a freely available English-Japanese bilingual corpus.","一般に利用できる英日2言語コーパスを作成した。","bilingual"];
EXAMPLES[5241]=["Her insistence was right. She did not need to feel ashamed.","彼女の主張は正しかった。彼女が肩身の狭い思いをする必要などなかったのだ。","insistence"];
EXAMPLES[5242]=["Please forward the document to the administrative office for review.","その文書を経営管理部に送って検討してもらって下さい。","administrative"];
EXAMPLES[5243]=["How many steps does this staircase have?","この階段は何段あるの？","staircase"];
EXAMPLES[5244]=["I really wonder how much the inheritance tax will amount to.","いったいどれくらいの相続税を払うことになるんだろう。","inheritance"];
EXAMPLES[5245]=["The gods have decreed that man is mortal.","神々は人間はみな死ぬものと定めた。","mortal"];
EXAMPLES[5246]=["The liner will call at Kobe on Tuesday.","定期船は、火曜日に神戸港に寄港するでしょう。","liner"];
EXAMPLES[5247]=["I forgot to bring my medical registration ticket.","診察券を持って来るのを忘れてしまいました。","registration"];
EXAMPLES[5248]=["That is, total exhaustion. Body and soul completely knackered.","つまり疲労困憊、心も体もクタクタです。","exhaustion"];
EXAMPLES[5250]=["They clustered around the fire.","彼らは火の周りに集まった。","clustered"];
EXAMPLES[5251]=["The Arabic script was replaced by the Roman alphabet.","アラビア文字はローマ式アルファベットにとって変わられた。","script"];
EXAMPLES[5252]=["The infectious case was isolated from other patients.","その伝染病患者は他の患者から隔離された。","infectious"];
EXAMPLES[5253]=["He's in good odor with the chief.","彼は上司に受けがいい。","odor"];
EXAMPLES[5254]=["He was given ample payment for the work.","彼はその仕事に対し十二分の報酬をもらった。","ample"];
EXAMPLES[5257]=["The resignations would have little or no effect on upcoming indications.","辞任劇は来るべき徴兵事務にはさして影響はないであろう。","indications"];
EXAMPLES[5258]=["If you have a medical certificate, bring it.","もし診断書があったらお待ちください。","certificate"];
EXAMPLES[5259]=["I have no remembrance of it now.","私は今ではそれについてなにも覚えていません。","remembrance"];
EXAMPLES[5260]=["Suppose there's some jerk you just can't get on with.","自分と気があわない、いけ好かない、人がいるとします。","jerk"];
EXAMPLES[5261]=["He was interested in the mysteries of the Orient.","彼は東洋の神秘に興味を持っていた。","Orient"];
EXAMPLES[5262]=["These legends should be handed down to our offspring.","これらの伝説は私達の子孫に語り継がれるべきだ。","offspring"];
EXAMPLES[5263]=["The Indonesian sentence is a perfect side by side translation of its English counterpart.","インドネシア語の文は英文の対訳としては完璧です。","counterpart"];
EXAMPLES[5264]=["I managed to get out of the scrape.","私は何とかその場を切り抜けた。","scrape"];
EXAMPLES[5265]=["He was naughty when he was a boy.","彼は少年時代わんぱくだった。","naughty"];
EXAMPLES[5266]=["I had an ectopic pregnancy two years ago.","２年前に子宮外妊娠をしました。","pregnancy"];
EXAMPLES[5267]=["This metal is comparable to iron in strength.","この金属は強度では鉄に匹敵する。","comparable"];
EXAMPLES[5268]=["My past indiscretions are coming back to haunt me.","過去の過ちが迫ってくる。","haunt"];
EXAMPLES[5269]=["My house is on the outskirts of town.","私の家はその町の郊外にあります。","outskirts"];
EXAMPLES[5270]=["The court adjudged that the will was valid.","法廷は遺言状が有効であるとの判決を下した。","valid"];
EXAMPLES[5271]=["Who's pulling the strings behind the scenes?","黒幕的な存在は誰だ。","behind the scenes"];
EXAMPLES[5273]=["I saw a dog with one paw bandaged.","私は片足に包帯を巻いた犬を見た。","paw"];
EXAMPLES[5274]=["There seems to be some genetic problem with this animal.","この動物には何か遺伝的な問題があるようだ。","genetic"];
EXAMPLES[5275]=["The doctor says stimulus is needed for appetite.","食欲には刺激が必要だと医者は言う。","stimulus"];
EXAMPLES[5276]=["The view from the mountain top was spectacular.","山頂からの眺めは壮観だった。","spectacular"];
EXAMPLES[5277]=["His villa on the hill commands the sea.","彼の丘の上の別荘は、海を見渡している。","villa"];
EXAMPLES[5278]=["The homeless sought shelter from the chilly shower.","家のない人たちは冷たいにわか雨をよける場所を探した。","chilly"];
EXAMPLES[5279]=["My son's front teeth have come in crooked.","息子の前歯が曲がってはえてきました。","crooked"];
EXAMPLES[5280]=["Why did you get such a costly dictionary?","どうしてそんなに高い辞書を買いましたか。","costly"];
EXAMPLES[5281]=["Her skin is coarse from years of working outdoors.","彼女の肌は長年戸外で働いたのできめが粗くなっている。","coarse"];
EXAMPLES[5283]=["He is under a false accusation.","彼は無実の罪で告発されている。","accusation"];
EXAMPLES[5284]=["Thanks to your stupidity, we lost the game.","君が間抜けだったおかげで、僕たちはその試合に負けたんだ。","stupidity"];
EXAMPLES[5285]=["He tucked the handkerchief in his pocket.","彼はそのハンカチをポケットに押し込んだ。","tucked"];
EXAMPLES[5286]=["The man passed by without so much as glancing at her.","その人は彼女をちらりとも見ないで通り過ぎた。","without so much as"];
EXAMPLES[5287]=["That car has a roof rack.","その車には屋根に荷台がついています。","rack"];
EXAMPLES[5289]=["Public utility charges will go up next April.","４月から公共料金が値上げになる。","utility"];
EXAMPLES[5290]=["What you think doesn't signify at all.","君の考えなどはどうだっていいことだ。","signify"];
EXAMPLES[5292]=["The privilege is reserved exclusively for women.","その特権はもっぱらご婦人だけに限られている。","exclusively"];
EXAMPLES[5293]=["This forest is full of diversity.","この森は、多様性に富んでいます。","diversity"];
EXAMPLES[5294]=["Public feeling against air pollution has at last become vocal.","大気汚染に対しての世論がついにやかましくなった。","vocal"];
EXAMPLES[5295]=["He is good, not to say exceptional.","彼は並外れて優秀とは言わないでも優れている。","exceptional"];
EXAMPLES[5296]=["In all likelihood, you will pass the entrance exam if you use this textbook.","この参考書を使えば、十中八九入試に合格するだろう。","In all likelihood"];
EXAMPLES[5297]=["It is irresponsible of you to break your promise.","約束を破るなんて無責任だ。","irresponsible"];
EXAMPLES[5298]=["Tom has a distinctive scar under his right eye.","トムは右目の下に独特の傷がある。","distinctive"];
EXAMPLES[5299]=["One can see faraway objects with a telescope.","遠くの物が望遠鏡で見える。","faraway"];
EXAMPLES[5300]=["The man puffed smoke into her face.","その男は彼女の顔に煙をぷっと吹きかけた。","puffed"];
EXAMPLES[5301]=["You have my word on her sincerity.","彼女の誠実さは私が保証します。","sincerity"];
EXAMPLES[5302]=["Barbara's success is beyond question.","バーバラの成功は疑いがない。","beyond question"];
EXAMPLES[5303]=["He gave the barking dog a vicious kick.","彼は吠える犬を激しく蹴った。","vicious"];
EXAMPLES[5304]=["They are on the border of starvation.","彼らは餓死しそうだ。","starvation"];
EXAMPLES[5305]=["I'm sorry. It was just a slip of the tongue.","すいません。私の言い間違いでした。","slip of the tongue"];
EXAMPLES[5306]=["There is a stack of letters on the table.","テーブルの上に手紙が山積みになっている。","stack"];
EXAMPLES[5307]=["The two houses stand alongside of each other.","２軒の家が並んでたっている。","alongside"];
EXAMPLES[5308]=["Failures often spring from ignorance.","失敗は無知から生じることがよくある。","spring from"];
EXAMPLES[5309]=["Our store has a monopoly on this item.","これは当店の専売です。","monopoly"];
EXAMPLES[5310]=["He gets a kick out of reckless driving.","彼は無謀運転にスリルを感じる。","reckless"];
EXAMPLES[5312]=["Sue and John decided to take the plunge.","スーとジョンは結婚することに決めた。","take the plunge"];
EXAMPLES[5313]=["If Tom cuts out caffeine he gets withdrawal symptoms.","トムはカフェインが切れると禁断症状が出てしまいます。","withdrawal"];
EXAMPLES[5314]=["He should disclose everything and face the music.","彼はすべてを明らかにして潔く責任を取るべきです。","disclose"];
EXAMPLES[5315]=["Our English teacher put emphasis on pronunciation.","私たちの英語の先生は発音を強調した。","put emphasis on"];
EXAMPLES[5316]=["Do you happen to think that I'm your puppet?","ひょっとして私はあなたの操り人形だと思うの？","puppet"];
EXAMPLES[5317]=["Our professor promised to hold off on the final exam for another week.","教授は期末試験を一週間延期すると約束した。","hold off"];
EXAMPLES[5319]=["The paper discusses the problem in terms of ethics.","この論文は倫理学の面からその問題を論じている。","ethics"];
EXAMPLES[5321]=["I had to stoop to go into the room.","その部屋に入るのに身をかがめなくてはならなかった。","stoop"];
EXAMPLES[5322]=["I hope your mother will regain her health soon.","お母さま、早く健康を取り戻されるといいですね。","regain"];
EXAMPLES[5323]=["It is right up his alley.","彼にはそんなことはお手の物だ。","alley"];
EXAMPLES[5324]=["The mere thought of a snake makes me shiver.","ヘビのことを考えただけでもぞっとするよ。","shiver"];
EXAMPLES[5325]=["The chief pronounced that the technique was inadequate.","所長はその方法は不適当だと断言した。","inadequate"];
EXAMPLES[5327]=["I wonder what materials the garment is made of.","衣装の素材はなんでしょう？","garment"];
EXAMPLES[5328]=["The company exploited its workers through low wages.","会社は従業員を低賃金で不当に利用した。","exploited"];
EXAMPLES[5329]=["She's a typical feminist.","彼女はティピカルなフェミニストです。","feminist"];
EXAMPLES[5330]=["But I have nothing left. I am just an old stump.","でも、私には何も残ってない、ただの古い切り株です。","stump"];
EXAMPLES[5332]=["Let's unfold the map on the table and discuss it.","地図をテーブルに広げて話し合おう。","unfold"];
EXAMPLES[5333]=["Diplomatic dialogue helped put an end to the conflict.","外交的な対話によって、その紛争に終止符を打つことができた。","dialogue"];
EXAMPLES[5334]=["He was standing there with a vacant look.","彼はぽかんとした顔つきでそこに立っていた。","vacant"];
EXAMPLES[5335]=["This residential area is comfortable to live in.","この住宅地域は住み心地がよい。","residential"];
EXAMPLES[5336]=["Investigators are trying to pin down the cause of today's fire.","鑑識班は今日の火事の原因を特定しようとしている。","pin down"];
EXAMPLES[5337]=["He has the capacity to become an accountant.","彼には会計士になる能力がある。","accountant"];
EXAMPLES[5338]=["I was compelled to do the work alone.","私は一人でその仕事を無理矢理させられた。","compelled"];
EXAMPLES[5339]=["Many architectural monstrosities are seen in Tokyo.","東京には醜悪な建築物がたくさん見られる。","architectural"];
EXAMPLES[5340]=["The building did not pass a fire inspection.","その建物は火災の検査にとおらなかった。","inspection"];
EXAMPLES[5341]=["A patent right is an important property right.","特許権は重要な財産権である。","patent"];
EXAMPLES[5342]=["Bear down in one's studies.","勉強に身を入れる。","Bear down"];
EXAMPLES[5343]=["Language in particular is the most fluid of mediums.","特に言語は最も流動的な媒体である。","fluid"];
EXAMPLES[5344]=["He is proficient in both Spanish and Italian.","彼はスペイン語、イタリア語ともに堪能だ。","proficient"];
EXAMPLES[5345]=["When is the pep rally?","壮行式は何時からですか。","rally"];
EXAMPLES[5346]=["Two thousand people fit into this hall.","このホールには人が二千人入れる。","fit into"];
EXAMPLES[5347]=["Those records are not accessible to the public.","その記録は一般に公開されていない。","accessible"];
EXAMPLES[5348]=["The USSR will only use air strikes in the country as a last resort.","ソ連は最後の手段としてしかその国を空爆しないだろう。","as a last resort"];
EXAMPLES[5349]=["The driver was thrown from his seat head over heels.","運転手は運転台からもんどり打って投げ出された。","head over heels"];
EXAMPLES[5350]=["He gave her a peck on the cheek.","彼は彼女の頬にキスをした。","peck"];
EXAMPLES[5351]=["Seen from a spacecraft, the earth looks blue.","宇宙船からながめると、地球は青く見える。","spacecraft"];
EXAMPLES[5352]=["He will soon be weary of the task.","彼はすぐその仕事に飽きるだろう。","be weary of"];
EXAMPLES[5353]=["This area has been considerably built up of late.","この地区は最近家がかなり建て込んできた。","considerably"];
EXAMPLES[5354]=["He is, as it were, a stray sheep.","彼は、いわば迷える子羊だ。","stray"];
EXAMPLES[5355]=["The resemblance between Sean and Conner is striking!","ショーンはコナーに激似なんだぜ。","resemblance"];
EXAMPLES[5356]=["Institutionally, a major restraint is the copyright problem.","制度的に大きな枷となるのは、著作権の問題である。","Institutionally"];
EXAMPLES[5357]=["Thousands of people died during the plague.","その疫病が流行して何千人もの人々が死んだ。","plague"];
EXAMPLES[5358]=["I only got a glimpse of the thief.","私は、その泥棒をほんのちらっと見ただけです。","glimpse"];
EXAMPLES[5359]=["What are you making all the fuss about?","なんでそんなに騒いでいるのか。","fuss"];
EXAMPLES[5362]=["The secretary inserted the letter in the envelope.","秘書は手紙を封筒の中に差し込んだ。","inserted"];
EXAMPLES[5363]=["He made a pretense of knowing my father.","彼は私の父を知っているふりをした。","pretense"];
EXAMPLES[5364]=["Her success was due to sheer hard work.","彼女の成功は全くの熱心な努力のおかげであった。","sheer"];
EXAMPLES[5365]=["To begin with, the funds are not sufficient for running a grocery.","まず第一に、雑貨店を運営するには資金が不十分だ。","To begin with"];
EXAMPLES[5366]=["The crowd gave the pair's coordinated performance lavish applause.","ふたりの息の合った演奏に、観客は惜しみない拍手を送った。","coordinated"];
EXAMPLES[5367]=["The whole audience got up and started to applaud.","全部観客が立ち上がって拍手し始めた。","applaud"];
EXAMPLES[5368]=["It is not ethical for a doctor to reveal confidences.","医師が患者の秘密を漏らすのは道義にもとる。","ethical"];
EXAMPLES[5369]=["This place is too shady for taking photos.","ここは、写真を撮るのには暗すぎる。","shady"];
EXAMPLES[5370]=["Sleep is essential for the preservation of life.","生きていくのにはどうしても眠ることが不可欠だ。","preservation"];
EXAMPLES[5371]=["He rubbed the rust off with a file.","彼はやすりで錆を落とした。","rust"];
EXAMPLES[5373]=["As I thought, she's a virgin!","やっぱり、おばこなんだ！","virgin"];
EXAMPLES[5374]=["The clause provides that all decisions shall be made by majority vote.","その条項は、議決はすべて過半数をもって成立すると規定している。","clause"];
EXAMPLES[5375]=["We have to transmit our culture to the next generation.","我々は自らの文化を次の世代に伝えていかなければならない。","transmit"];
EXAMPLES[5377]=["The police didn't believe his denial.","警察は彼が否定したのを真に受けなかった。","denial"];
EXAMPLES[5379]=["I don't want to eat this stale bread.","こんな硬くなったパンは食べたくないよ。","stale"];
EXAMPLES[5380]=["You always talk back to me, don't you?","君はいつも言い返す。","talk back to"];
EXAMPLES[5381]=["I can't believe that he is that depressed.","彼がそれほど落ち込んでいるとは思えないな。","depressed"];
EXAMPLES[5382]=["And just like that, the quest began.","いきなりクエストが始まった。","quest"];
EXAMPLES[5383]=["I will overthrow the dictator.","独裁者を倒すのだ！","overthrow"];
EXAMPLES[5384]=["All in all, the excursion was pleasant.","全体として、遠足は楽しかった。","excursion"];
EXAMPLES[5385]=["My watchdog is alert to the slightest sound and movement.","うちの番犬はどんな小さな音や動きにも油断がない。","watchdog"];
EXAMPLES[5386]=["He gave a bald statement of the facts.","彼は事実をありのままに述べた。","bald"];
EXAMPLES[5387]=["He muttered complaints against the school.","彼は学校に対する不満をつぶやいた。","muttered"];
EXAMPLES[5388]=["Tell those people to back off so that the helicopter can land.","ヘリコプターが着陸できるようあの人達に後ろに下がるように言って下さい。","back off"];
EXAMPLES[5389]=["Is this the bus for Park Ridge?","このバスは、パークリッジ行きですか。","Ridge"];
EXAMPLES[5390]=["In Italian, unlike English, adjective placement can vary.","イタリア語では、英語と異なり、形容詞の配置を変えることができる。","adjective"];
EXAMPLES[5391]=["Let's classify the names of the students alphabetically.","生徒の名前をアルファベット順に分けよう。","classify"];
EXAMPLES[5393]=["Cooperate with your friends in doing the work.","その仕事をするの友人と協力しなさい。","Cooperate"];
EXAMPLES[5394]=["He drinks a lot but always seems sober.","彼はずいぶんと酒を飲むが、いつも酔っていないように見える。","sober"];
EXAMPLES[5395]=["Illness frustrated his plans for the trip.","病気で彼の旅行の計画は挫折した。","frustrated"];
EXAMPLES[5396]=["He was envious of her way of living.","彼は彼女の生き方がうらやましかった。","envious"];
EXAMPLES[5397]=["He finally had to step down.","彼は結局あきらめざるを得なかった。","step down"];
EXAMPLES[5398]=["My mother attached herself to a cooperative society.","母は生協に入っていました。","cooperative"];
EXAMPLES[5399]=["The structural formula for water is H-O-H.","水の構造式はH-O-Hである。","structural"];
EXAMPLES[5400]=["The librarian classified the books according to subject.","司書は主題によって本を分類した。","librarian"];
EXAMPLES[5401]=["The frame of the machine should be rigid.","その機械の骨組みは堅くなければならない。","rigid"];
EXAMPLES[5402]=["Entry is prohibited to anyone other than authorized personnel.","関係者以外、立入禁止だ。","authorized"];
EXAMPLES[5403]=["It is a marvel that he should say so.","彼がそう言うなんて不思議だ。","marvel"];
EXAMPLES[5404]=["He gave the stone a fling.","彼はその石をぽいとなげた。","fling"];
EXAMPLES[5405]=["Can you drive a car with manual transmission?","マニュアル車の運転はできる？","transmission"];
EXAMPLES[5406]=["The cat peeped its head out the window.","猫が窓からにょきっと顔を出してきた。","peeped"];
EXAMPLES[5407]=["He made an endeavor to improve the situation.","彼は事態を改善しようと努力した。","endeavor"];
EXAMPLES[5408]=["Years ago, she used to hang around with a bunch of bikers.","何年か前、彼女は暴走族の連中と付き合っていた。","hang around"];
EXAMPLES[5409]=["He is as great a physicist as ever lived.","彼はいまだかつてないぐらい偉大な物理学者である。","physicist"];
EXAMPLES[5411]=["A chain of events led to the outbreak of the war.","一連の出来事が戦争の勃発を引き起こした。","outbreak"];
EXAMPLES[5412]=["The manuscript had been written out by hand.","その原稿は手で清書されていた。","manuscript"];
EXAMPLES[5413]=["The company is attempting to stagger work hours.","会社は時差通勤を導入しようとしています。","stagger"];
EXAMPLES[5414]=["I heard the front door slam.","玄関のドアがバタンと閉まるのが聞こえた。","slam"];
EXAMPLES[5415]=["He tried to banish his anxiety.","彼は不安を払いのけようとした。","banish"];
EXAMPLES[5416]=["Twelve percent of Russia's territory is covered in swamps.","ロシアの領土の12%は、湿地に覆われています。","swamps"];
EXAMPLES[5417]=["You should conform to the rules.","君は規則に従うべきだ。","conform to"];
EXAMPLES[5418]=["The new team has the capability to win.","新しいチームには優勝する力がある。","capability"];
EXAMPLES[5419]=["What if you gave a speech and nobody came?","君が演説をして誰も来なかったらどうするの？","What if"];
EXAMPLES[5420]=["We encourage your participation.","あなたの参加をお待ちしています。","participation"];
EXAMPLES[5421]=["He has the faculty to learn languages easily.","彼は言葉を簡単に学ぶ能力をもっている。","faculty"];
EXAMPLES[5423]=["The English are known for their courtesy.","イギリス人は礼儀正しいことで知られている。","courtesy"];
EXAMPLES[5424]=["He fainted in the midst of his speech.","彼はスピーチの最中に気を失った。","midst"];
EXAMPLES[5425]=["I resent the way he treated me.","私は彼の私に対するやり方に憤慨している。","resent"];
EXAMPLES[5426]=["You cannot undo what has already been done.","やってしまったことを取り消すことはできないんだよ。","undo"];
EXAMPLES[5427]=["He is as honest a lad as any.","彼は誰にも負けず劣らず正直な少年だ。","lad"];
EXAMPLES[5428]=["Loosen the screws and remove the lamp cover.","ねじを緩めて、ランプ・カバーを取り外します。","Loosen"];
EXAMPLES[5429]=["I finally penetrated the meaning of the riddle.","ついにそのなぞの意味が解けた。","riddle"];
EXAMPLES[5430]=["We are sick and tired of political corruption.","政治の腐敗にはうんざりですね。","corruption"];
EXAMPLES[5432]=["He has been unconscious for three days.","彼は三日間無意識の状態だ。","unconscious"];
EXAMPLES[5435]=["The family seemed to be under a curse.","その家族には呪いがかけられているようだった。","curse"];
EXAMPLES[5436]=["With the appearance of a promising new writer, the aging novelist fell from prominence.","新進作家の登場でその老作家は影の薄い存在となった。","prominence"];
EXAMPLES[5437]=["The following passage was quoted from a well-known fable.","次の一節はある有名な寓話から引用したものです。","fable"];
EXAMPLES[5439]=["He isn't a man to take a bribe.","彼はわいろを取るような人ではない。","bribe"];
EXAMPLES[5440]=["He is careless and untidy in his work.","彼は仕事が雑だ。","untidy"];
EXAMPLES[5441]=["Don't go against the rules.","規則に逆らうな。","go against"];
EXAMPLES[5442]=["This transparent liquid contains a kind of poison.","この透明な液体は毒のようなものを含んでいる。","transparent"];
EXAMPLES[5443]=["Roll up your sleeves and get busy.","気合いを入れて頑張れ。","Roll up"];
EXAMPLES[5444]=["Man is not as almighty as God.","人間は神ほど万能ではない。","almighty"];
EXAMPLES[5445]=["When one has a wonderful dream, one doesn't wish to come down to earth.","すばらしい夢をみると、現実にもどりたくなくなるものだ。","come down to"];
EXAMPLES[5446]=["The matter of his successor is still under debate.","彼の後継者についての問題はまだ論争中だ。","successor"];
EXAMPLES[5447]=["Don't look to me for any help except in case of emergency.","緊急の場合以外は私の援助をあてにしてはいけません。","look to"];
EXAMPLES[5448]=["What will become of the world thirty years hence?","今から３０年後に世界はどうなるだろう？","hence"];
EXAMPLES[5449]=["I had a stool examination at the hospital.","病院で大便の検査をした。","stool"];
EXAMPLES[5450]=["The latest exam was difficult and its questions misleading.","今回の試験は、難しかった上に質問も紛らわしかった。","misleading"];
EXAMPLES[5451]=["The next sentence has adjectives and adverbs.","次の文には形容詞と副詞が含まれています。","adverbs"];
EXAMPLES[5452]=["This house will not sell as it stands.","この家は今のままでは売れないだろう。","as it stands"];
EXAMPLES[5453]=["That organization is corrupt to the core.","あの組織は芯まで、腐っている。","corrupt"];
EXAMPLES[5454]=["Charlie decided to cross out the last word.","チャーリーは最後の語を抹消することに決めた。","cross out"];
EXAMPLES[5456]=["Do you really want to be immortal?","本当に不死身になりたいか？","immortal"];
EXAMPLES[5457]=["At last, the gem was in his hands.","ついに彼はその宝石を手に入れた。","gem"];
EXAMPLES[5458]=["I ironed out the wrinkles in my pants.","私はズボンのしわをアイロンで伸ばした。","wrinkles"];
EXAMPLES[5459]=["I did not think he was so timid.","彼がああ臆病だとは思わなかった。","timid"];
EXAMPLES[5460]=["The applicant impressed the examiner favorably.","その志望者は試験官に好ましい印象を与えた。","examiner"];
EXAMPLES[5461]=["I'll give him a buzz.","彼に電話してみよう。","buzz"];
EXAMPLES[5462]=["Are we humans alone in this infinite universe?","この果てしない宇宙にいるのは、私たち人類だけですか？","infinite"];
EXAMPLES[5463]=["The artist is eternally a boy.","その画家は、いわば永遠の少年だ。","eternally"];
EXAMPLES[5464]=["You should live up to your principles.","君は自分の主義に従って行動すべきである。","live up to"];
EXAMPLES[5465]=["Woodpeckers peck tree trunks with their long pointed beaks and eat insects found there.","きつつきは、長く尖ったくちばしで、木の幹をつついて、中にいる虫を食べます。","beaks"];
EXAMPLES[5466]=["I lost my balance on the muddy road.","ぬかるみに足を取られた。","muddy"];
EXAMPLES[5467]=["I foolishly interpreted the idiom according to its literal sense.","私はおろかにもその慣用語句を文字通りの意味で解釈してしまった。","idiom"];
EXAMPLES[5468]=["I was annoyed with him for his interruptions.","彼が度々口をはさむので腹がたった。","interruptions"];
EXAMPLES[5469]=["The accent of the word is on the second syllable.","その語のアクセントは第二音節にある。","syllable"];
EXAMPLES[5470]=["The world doesn't revolve around you.","世界は君を中心に回っているわけではないんだよ。","revolve"];
EXAMPLES[5471]=["You ought to think over whether the premise is valid or not.","その前提が妥当かどうかよく考えるべきだ。","premise"];
EXAMPLES[5472]=["We sided with him in the controversy.","その論争で我々は彼に味方した。","controversy"];
EXAMPLES[5473]=["She is delicately constituted.","彼女は華奢な体格だ。","delicately"];
EXAMPLES[5474]=["It is beyond the boundaries of human intellect.","それは人知の限界を越えている。","intellect"];
EXAMPLES[5475]=["I can only speak for myself.","私は自分に関してのことだけしかいえない。","speak for"];
EXAMPLES[5476]=["Tom has no conception of what it's like to be in love.","トムは、恋愛をするということがどんな感じなのか全くわかってない。","conception"];
EXAMPLES[5477]=["What is the average rainfall for July here?","ここの７月の平均降雨量はどのくらいですか。","rainfall"];
EXAMPLES[5478]=["The framework of the new building is slowly taking form.","新しい建物の骨組みが徐々に姿を見せてきている。","framework"];
EXAMPLES[5480]=["I'm Miles, Prince of the Furry Realm!","僕はケモナー界のプリンスマイルズだよ！","Realm"];
EXAMPLES[5482]=["An egg is not round but oval.","卵は、真ん丸ではなく楕円です。","oval"];
EXAMPLES[5483]=["Outside the mainstream of orthodox Judaism, apocalypticism was more successful with certain movements.","ユダヤ正統派の主流から外れた部分においては、黙示録はある種の運動に対して、より成功を収めたのである。","orthodox"];
EXAMPLES[5484]=["French has many more vowels than Japanese.","フランス語には日本語よりずっと多くの母音がある。","vowels"];
EXAMPLES[5485]=["A man cannot be made in a mold.","人間は鋳型に入れて作るわけにはいかない。","mold"];
EXAMPLES[5486]=["It is no exaggeration to call him a genius.","彼を天才と呼んでも誇張ではない。","exaggeration"];
EXAMPLES[5487]=["The implications of this did not at first sink in.","この事が暗に意味することは最初は理解されなかった。","sink in"];
EXAMPLES[5488]=["Japanese food terms are difficult to render into other languages.","日本料理の用語はほかの言語に訳すのが難しい。","render"];
EXAMPLES[5489]=["She won an Oscar nomination for best supporting actress.","彼女はアカデミー賞の最優秀助演女優にノミネートされた。","nomination"];
EXAMPLES[5490]=["Do you have a search warrant?","捜索令状は持っているのですか。","warrant"];
EXAMPLES[5491]=["The Titanic's maiden voyage didn't go so well.","タイタニックの処女航海はあまり良くなかったです。","maiden"];
EXAMPLES[5493]=["We were filled with anger against the murderer.","我々は殺人者に対する怒りで胸一杯になった。","murderer"];
EXAMPLES[5494]=["The problem is that he is penniless.","問題は彼が文無しであるということだ。","penniless"];
EXAMPLES[5495]=["Your composition is free from all grammatical mistakes.","君の作文には文法の間違いは１つもない。","grammatical"];
EXAMPLES[5496]=["The doctor reassured me about my father's condition.","医師は父の健康状態のことで私を安心させた。","reassured"];
EXAMPLES[5497]=["More haste, less speed is a paradox.","「急げば急ぐほど遅くなる」は逆説である。","paradox"];
EXAMPLES[5498]=["The morning service began with a hymn.","朝の礼拝は賛美歌ではじまった。","hymn"];
EXAMPLES[5499]=["That adds a new dimension to our problem.","そのことが我々が抱える問題に新しい面を加える。","dimension"];
EXAMPLES[5501]=["This is a matter of the utmost importance.","これは最も重要な問題だ。","utmost"];
EXAMPLES[5502]=["They made first ascent of Mount Everest.","彼らはエベレストに初登頂した。","ascent"];
EXAMPLES[5503]=["The Grand Canyon is the number one tourist attraction in America.","グランド・キャニオンはアメリカで一番人気のある観光スポットです。","Canyon"];
EXAMPLES[5504]=["Don't bring on any more shame.","恥の上塗りはよせ。","bring on"];
EXAMPLES[5506]=["I defy you to make it public.","できるというならそれを表沙汰にするがよい。","defy"];
EXAMPLES[5507]=["The dog pricked up his ears at the sound.","その犬はその音を聞いて耳をピンと立てた。","pricked"];
EXAMPLES[5508]=["Every time I saw him, I was overcome with his brilliance.","彼に会うたびごとに、彼の頭の良さに圧倒された。","brilliance"];
EXAMPLES[5509]=["I sympathize with you from the bottom of my heart.","心からきみに同情する。","sympathize"];
EXAMPLES[5510]=["They confirmed the importance of strengthening global precautions in order to prevent devastating losses.","壊滅的な被害を防ぐために世界的な警戒を強化していく重要性を確認した。","precautions"];
EXAMPLES[5512]=["She boiled over with rage at his betrayal.","彼女は彼の裏切りに激怒した。","betrayal"];
EXAMPLES[5513]=["I like to roam about the fields.","私は野原を歩き回るのが好きだ。","roam"];
EXAMPLES[5514]=["He's to stay here for a fortnight.","彼は当地に二週間滞在する予定です。","fortnight"];
EXAMPLES[5516]=["Today is my second day of my side job.","アルバイトを始めて今日で２日目です。","side job"];
EXAMPLES[5517]=["He was subjected to torture by the police.","彼は警察で拷問を受けた。","torture"];
EXAMPLES[5519]=["That is not what the narrative is about.","それはその物語の述べるところではない。","narrative"];
EXAMPLES[5520]=["He was the scorn of the other boys.","彼は他の男の子達の物笑いの種だった。","scorn"];
EXAMPLES[5521]=["The orphan was fostered by the wealthy man.","その孤児は金持ちに育てられた。","orphan"];
EXAMPLES[5523]=["I want stability in my life.","生活を安定させたい。","stability"];
EXAMPLES[5524]=["Bacteria will not breed in alcohol.","バクテリアはアルコールの中では繁殖しない。","Bacteria"];
EXAMPLES[5525]=["Did you listen to the parliamentary debate?","国会討論の放送を聞きましたか。","parliamentary"];
EXAMPLES[5526]=["We agreed to the plan without qualification.","無条件でその計画に同意した。","qualification"];
EXAMPLES[5527]=["The male ape is intelligent by nature.","そのオスざるは生まれつき頭が良い。","ape"];
EXAMPLES[5528]=["Tenderness is an important element in a person's character.","やさしさは人の性格の中で重要な要素だ。","Tenderness"];
EXAMPLES[5529]=["This is moderately spicy but stimulates the appetite.","この程よい辛さが、食欲を掻き立てる。","moderately"];
EXAMPLES[5530]=["She was jolly well made to pay.","彼女はまさしく支払わされたのだ。","jolly"];
EXAMPLES[5531]=["You should persist in your efforts to learn English.","英語を習得する努力を続けるべきだ。","persist"];
EXAMPLES[5532]=["Do you know a good specialty store dealing in herbs?","ハーブの専門店を聞いたことがありませんか。","herbs"];
EXAMPLES[5533]=["I experience nausea when I go on too many rides.","あまり多くの乗り物に乗ると酔います。","nausea"];
EXAMPLES[5534]=["He's here trying to stir up trouble.","彼はここでもめ事を起こそうとしているんだ。","stir up"];
EXAMPLES[5535]=["Can you make out the meaning easily?","君はその意味が容易に理解できますか。","make out"];
EXAMPLES[5536]=["He tends to consider things too much earnestly.","彼は物事を真剣に考え過ぎる傾向にある。","earnestly"];
EXAMPLES[5537]=["I don't agree with violation of human rights.","私は人権侵害に反対だ。","violation"];
EXAMPLES[5539]=["I borrowed this cartoon from his older sister.","この漫画は彼の姉から借りました。","cartoon"];
EXAMPLES[5540]=["He was too feeble to do manual labor.","彼は非常に身体が弱くて力仕事はできなかった。","feeble"];
EXAMPLES[5541]=["The scholar regards so-called compulsory education as useless.","その学者は、いわゆる義務教育は役に立たないものだと考えている。","compulsory"];
EXAMPLES[5542]=["Are you aware that you're being a nuisance?","周りに迷惑かけてる自覚はある？","nuisance"];
EXAMPLES[5543]=["The police intervened in the disturbance.","警察が騒動に介入した。","disturbance"];
EXAMPLES[5544]=["Is Japan a good place to reside?","日本って、住み心地がいい？","reside"];
EXAMPLES[5546]=["You will be more vigorous if you exercise.","運動すればもっと丈夫になるよ。","vigorous"];
EXAMPLES[5547]=["I always find contentment in a good book.","良書を読むといつも幸せだと感じる。","contentment"];
EXAMPLES[5548]=["We aim to please.","お客様にご満足いただけるように努力しております。","aim to"];
EXAMPLES[5549]=["A natural diet is suitable for human digestion.","自然食は人間の消化に合っている。","digestion"];
EXAMPLES[5550]=["He is a very irritating critic of others.","他人のあらばかり探す嫌な人である。","irritating"];
EXAMPLES[5551]=["We could not play owing to the rain.","僕らは雨のために遊べなかった。","owing"];
EXAMPLES[5552]=["It seems that he is interested in astronomy.","彼は天文学に興味があるようだ。","astronomy"];
EXAMPLES[5553]=["These trees shut out the view.","これらの木で景色が見えない。","shut out"];
EXAMPLES[5554]=["An electron is an elementary particle.","電子とは素粒子の一種である。","electron"];
EXAMPLES[5555]=["Go and sit by your father.","お父さんのそばに座りなさい。","sit by"];
EXAMPLES[5556]=["He ran away lest he should be seen.","彼は見みられないように逃げた。","lest"];
EXAMPLES[5557]=["I would like to engage in foreign trade in the future.","私は将来、外国貿易をやりたい。","trade in"];
EXAMPLES[5558]=["Measure the length of the stick with a ruler.","ものさしでその棒の長さを測りなさい。","stick with"];
EXAMPLES[5559]=["Tyrannical governments frequently imprison their political opponents.","圧政的な政府はしばしば政敵を投獄する。","imprison"];
EXAMPLES[5560]=["Let's go through the cemetery. It's closer that way.","墓地を抜けよう。その方が近いよ。","cemetery"];
EXAMPLES[5561]=["These factories are a blot on the landscape.","工場はこの風景の汚点となっている。","blot"];
EXAMPLES[5562]=["I have a graze here.","ここにすり傷があります。","graze"];
EXAMPLES[5563]=["She could scarcely gasp the words.","息が苦しくて満足にその言葉を言えなかった。","gasp"];
EXAMPLES[5564]=["The army had the revolt well in hand.","軍隊は反乱を制圧した。","revolt"];
EXAMPLES[5565]=["Strife is the rock on which the party split.","内紛が党の分裂したもとです。","Strife"];
EXAMPLES[5566]=["They faced the peril of falling rocks.","彼らは落石の危険にさらされた。","peril"];
EXAMPLES[5567]=["As a man sows, so he shall reap.","まいた種は自分で刈り取らなければならない。","reap"];
EXAMPLES[5568]=["This level is intermediate. It isn't hard.","このレベルは中級だよ。難しくないよ。","intermediate"];
EXAMPLES[5569]=["To err is human, to forgive divine.","間違いをするのが人間で、許すのは神だ。","divine"];
EXAMPLES[5570]=["I need to get my hair bleached at the salon.","サロンで髪を脱色してもらわないとな。","bleached"];
EXAMPLES[5572]=["A mysterious message came from the administrator.","管理者から、謎のメッセージが届いた。","administrator"];
EXAMPLES[5573]=["Mingle your joys sometimes with your earnest occupation.","ときに君の喜びと君の真剣な職業とを交流せしめよ。","Mingle"];
EXAMPLES[5574]=["This is the first time I've had seaweed.","海草を食べたのは初めてです。","seaweed"];
EXAMPLES[5575]=["Your essay is admirable in regard to style.","君のエッセイは文体に関してはすばらしい。","admirable"];
EXAMPLES[5576]=["There's always a good part in human folly.","人間の愚かさには必ず何か良い部分もあります。","folly"];
EXAMPLES[5577]=["The color white is a symbol of purity.","白は純潔の象徴である。","purity"];
EXAMPLES[5578]=["Grandfather sat in his habitual place near the fire.","おじいさんは火の近くでいつもの場所に座った。","habitual"];
EXAMPLES[5579]=["This new plan may bring a lasting peace.","この新しい計画によって永続する平和が生まれるかもしれない。","lasting"];
EXAMPLES[5580]=["She sweeps the room with a broom.","彼女はほうきで部屋を掃除する。","broom"];
EXAMPLES[5581]=["I had a feeling that something dreadful was happening.","何か恐ろしいことが起こりそうな気がした。","dreadful"];
EXAMPLES[5582]=["He is a silent, manly boy.","彼は無口で男らしい少年だ。","manly"];
EXAMPLES[5583]=["I salute both of you for your professionalism.","お二人のプロ意識に敬意を表します。","salute"];
EXAMPLES[5584]=["The tourist asked for lodging for the night.","旅行者は一夜の宿を求めた。","lodging"];
EXAMPLES[5585]=["The reign of Philip II lasted forty years.","フィリップ2世による統治は40年間続いた。","reign"];
EXAMPLES[5587]=["I have an inclination for poetry.","私は詩がすきです。","inclination"];
EXAMPLES[5588]=["The children were insistent about our taking them to the movies.","子供たちは映画に連れていってくれと言ってきかなかった。","insistent"];
EXAMPLES[5589]=["Was it necessary to inflict such a punishment on him?","そのような罰を彼に与える必要があったのか。","inflict"];
EXAMPLES[5590]=["I have no words to express my gratitude.","何ともお礼の言葉もございません。","gratitude"];
EXAMPLES[5591]=["I was pleased no end by the cordial welcome.","暖かい歓迎を受けて大変喜んだ。","cordial"];
EXAMPLES[5592]=["The word is expressive of my feelings.","その語は私の気持ちをよく表している。","expressive"];
EXAMPLES[5593]=["Sanitary conditions in the refugee camps were terrible.","難民キャンプの衛生状態はひどいものだった。","Sanitary"];
EXAMPLES[5595]=["He is not a man to trifle with.","彼はいいかげんにあしらえない人である。","trifle"];
EXAMPLES[5597]=["The principal presented each of the graduates with diploma.","校長は卒業生ひとりひとりに卒業証書を授与した。","diploma"];
EXAMPLES[5600]=["The patriot sticks to his moral principles.","その愛国者は自分の道徳的な信条を曲げない。","patriot"];
EXAMPLES[5601]=["Such conduct doesn't fit in with your reputation.","そのような行動は、あんたの評判とは一致していない。","fit in"];
EXAMPLES[5602]=["My comrades encouraged me to fulfill my ambitions.","仲間達が私に野望を果たすよう励ましてくれた。","comrades"];
EXAMPLES[5603]=["The viola is a plant resistant to the cold.","ビオラは耐寒性植物だよ。","resistant"];
EXAMPLES[5604]=["You are the wickedest witty person I know.","君は私の知っている中で憎たらしいほど機知に富んだ人だよ。","witty"];
EXAMPLES[5605]=["That doctrine will no doubt lead to serious consequences.","その主義はおそらく重大な結果を招くだろう。","doctrine"];
EXAMPLES[5606]=["In a few seconds I would have overcome the desperation threshold.","後数秒で私は絶望の分岐点を越えるのだ。","threshold"];
EXAMPLES[5607]=["The doctor thought the patient's pulse was rather rapid.","医者はその患者の脈は少し速いと思った。","pulse"];
EXAMPLES[5608]=["I am not in a position to testify.","私は証言する立場ではない。","testify"];
EXAMPLES[5609]=["She choked her utterance with sobs.","彼女は泣きじゃくって口がきけなかった。","utterance"];
EXAMPLES[5610]=["It is improper to impose sanctions upon the union.","組合に制裁を加えることは妥当ではない。","improper"];
EXAMPLES[5611]=["The girl, closing her eyes, listened to the pastor.","その少女は、目を閉じて牧師の話を聞いた。","pastor"];
EXAMPLES[5613]=["The seasoning is just right.","いい塩梅だ。","seasoning"];
EXAMPLES[5615]=["He is very blunt in his manner.","彼の態度はすこぶる無骨だ。","blunt"];
EXAMPLES[5616]=["I don't think that it's weird at all.","全然変だと思わないんだけど。","weird"];
EXAMPLES[5617]=["This is a crude material imported from Malaysia.","これはマレーシアから輸入した原料です。","crude"];
EXAMPLES[5618]=["The value of this book has been halved.","この本の価値は半減した。","halved"];
EXAMPLES[5619]=["I like him all the better for his diligence.","彼は勤勉なのでいっそう好感が持てる。","diligence"];
EXAMPLES[5620]=["We would appreciate it if you grant us this concession.","この件を、ご承認いただけますよう、お願いいたします。","concession"];
EXAMPLES[5622]=["The company is our wholly-owned subsidiary.","その会社は我々の１００％子会社である。","subsidiary"];
EXAMPLES[5623]=["Tom and Mary met at the botanical garden.","トムとメアリーは植物園で会った。","botanical"];
EXAMPLES[5624]=["He soon became confidential with the man.","じきに彼はその男と打ち明けた。","confidential"];
EXAMPLES[5626]=["He was caught in the clutches of the law.","彼は法律の網にかかった。","clutches"];
EXAMPLES[5627]=["His business has begun to thrive at last.","彼の事業もやっと萌芽の兆しを見せた。","thrive"];
EXAMPLES[5628]=["He resolved to embark on a once-in-a-lifetime enterprise.","彼は臍を固めて一世一代の大事業に乗り出した。","embark"];
EXAMPLES[5629]=["He had a queer expression on his face.","彼は奇妙な表情を浮かべていた。","queer"];
EXAMPLES[5630]=["The government of that country oppresses its people.","その国の政府は国民を圧迫している。","oppresses"];
EXAMPLES[5631]=["The aide suggested a change in tactics to him.","副官は戦術の変更を彼に提案した。","aide"];
EXAMPLES[5632]=["Without a moment's hesitation, they took drastic action against the conspiracy.","ためらうことなく、その陰謀にたいする徹底した対抗処置をとった。","conspiracy"];
EXAMPLES[5633]=["Disarmament is in practice difficult in many countries.","多くの国において軍備縮小は実際には難しい。","Disarmament"];
EXAMPLES[5635]=["The children are learning to add and subtract.","子供達は、足し算と引き算を習っている。","subtract"];
EXAMPLES[5637]=["Tom and Mary live a harmonious life together.","トムとメアリーは仲睦まじく暮らしている。","harmonious"];
EXAMPLES[5638]=["The villagers were displaced by the construction of a dam.","ダムの建設のため村民は立ち退かされた。","displaced"];
EXAMPLES[5639]=["Strictly speaking, it was not a vertical line.","厳密に言えば、それは垂直線ではなかった。","vertical"];
EXAMPLES[5640]=["The mayor administers the affairs of the city.","市長は市政を司る。","administers"];
EXAMPLES[5641]=["The fury of the storm frightened the children.","嵐の激しさに子供たちは恐れおののいた。","fury"];
EXAMPLES[5642]=["The problem affects the prestige of our school.","これは我が校の名誉にかかわる問題だ。","prestige"];
EXAMPLES[5643]=["My memory was at fault.","私の記憶は間違っていた。","at fault"];
EXAMPLES[5644]=["My house is comprised of these four rooms.","私の家はこの４つの部屋から成っている。","comprised"];
EXAMPLES[5645]=["They are of kin to each other.","彼らは互いに親類関係にある。","kin"];
EXAMPLES[5646]=["I hadn't realized the magnitude of the problems.","私はその問題の重要さがわかっていなかった。","magnitude"];
EXAMPLES[5647]=["You can see that mountain's perpetual snow from here.","ここからはあの山の万年雪が見えます。","perpetual"];
EXAMPLES[5648]=["The hat got wet and went limp.","帽子がぬれてふにゃふにゃになった。","limp"];
EXAMPLES[5649]=["An exclamation mark is a punctuation mark.","感嘆符は句読点です。","exclamation"];
EXAMPLES[5650]=["I have no faith in a silly superstition.","私は愚かな迷信など信じない。","superstition"];
EXAMPLES[5651]=["Many scientists have the reputation of being eccentric.","多くの科学者は世間に変人呼ばわりされている。","eccentric"];
EXAMPLES[5652]=["He cut a twig from the tree with his knife.","彼はナイフでその木の小枝を切り取った。","twig"];
EXAMPLES[5653]=["His comment was concise and to the point.","彼の評論は簡潔で要点を押さえたものだった。","concise"];
EXAMPLES[5654]=["Do you have a home newspaper subscription?","家で新聞って、取ってる？","subscription"];
EXAMPLES[5655]=["He was charged with the crime of abusive language.","彼は暴言罪で告発された。","abusive"];
EXAMPLES[5657]=["There is nothing to be gained by flattery.","お世辞を言っても無駄だ。","flattery"];
EXAMPLES[5658]=["He remained steadfast to his principles.","彼はずっと自分の主義に忠実であった。","steadfast"];
EXAMPLES[5659]=["This swimming suit is made of elastic material.","この水着は伸縮性のある素材でできている。","elastic"];
EXAMPLES[5660]=["The station is situated between the two towns.","駅はその二つの町の中間にある。","situated"];
EXAMPLES[5661]=["The tolerance of ambiguities is necessary in learning a language.","言語を学ぶには曖昧さに対する寛容性が必要である。","tolerance"];
EXAMPLES[5663]=["He could recite the poem at age 5.","彼は５歳でその詩を暗唱することができた。","recite"];
EXAMPLES[5664]=["The freight on the ship got soaked.","船上の荷物はずぶぬれになった。","freight"];
EXAMPLES[5665]=["His proposal is out of the question.","彼の提案は問題にならない。","out of the question"];
EXAMPLES[5667]=["Do I snore a lot when I sleep?","僕ってさぁ、寝てる時、よくいびきかいてる？","snore"];
EXAMPLES[5668]=["The world is a den of crazies.","世界は奇人の巣だ。","den"];
EXAMPLES[5669]=["You had better go by tram.","電車で行った方がいいよ。","tram"];
EXAMPLES[5670]=["The rain never let up all night.","雨は一晩中やまなかった。","let up"];
EXAMPLES[5671]=["He professed to know nothing about it.","彼はそのことについて何も知らないと公言した。","professed"];
EXAMPLES[5672]=["Make sure to thaw the chicken before cooking.","鶏肉は調理前に必ず解凍してください。","thaw"];
EXAMPLES[5673]=["Years later, Europeans established colonies in the coastal areas.","数年後、ヨーロッパ人たちは沿岸の植民地に住み着いた。","coastal"];
EXAMPLES[5674]=["Ken will grow into his brother's clothes by the end of the year.","ケンは年末ごろには大きくなって兄さんの服が着られるでしょう。","grow into"];
EXAMPLES[5675]=["Chemistry has made notable progress in recent years.","近年、化学は驚くべき進歩を遂げてきた。","notable"];
EXAMPLES[5677]=["The public school system is coming apart at the seams.","公立学校制度はこわれかかっています。","seams"];
EXAMPLES[5678]=["Duty should come before anything else.","何よりも義務を優先すべきだ。","come before"];
EXAMPLES[5679]=["She implored mercy with tears running down her cheeks.","彼女は涙を頬に伝わせながら情けを請うた。","implored"];
EXAMPLES[5680]=["For heavens sake, stop your pathetic excuses!","見苦しい言い訳はよせよ。","pathetic"];
EXAMPLES[5681]=["He had to contend against physical suffering.","彼は肉体の苦痛と闘わねばならなかった。","contend"];
EXAMPLES[5682]=["The criminal was sent into exile.","犯人は国外に追放された。","exile"];
EXAMPLES[5683]=["Japan has a high population density.","日本は人口密度が高い国である。","density"];
EXAMPLES[5684]=["The problems are inherent in this system.","その問題はこのシステムに固有のものだ。","inherent"];
EXAMPLES[5685]=["Please drive off as soon as your child has left the car.","お子さんが車をおりたらすぐに車を出してください。","drive off"];
EXAMPLES[5686]=["He was perplexed at the unexpected result.","彼は予想外の結果にまごついた。","perplexed"];
EXAMPLES[5687]=["He appears sly on the surface.","彼は表面上は陰険そうに見える。","sly"];
EXAMPLES[5688]=["In Japan, a census is taken every five years.","日本では５年に一度国勢調査が行われます。","census"];
EXAMPLES[5689]=["How do I put staples into a stapler?","ホチキスの針って、どうやって入れればいいの？","stapler"];
EXAMPLES[5690]=["Next year, this gravel road will be paved.","この砂利道は来年舗装されるだろう。","paved"];
EXAMPLES[5691]=["Radioactive contamination was detected in spinach and edible chrysanthemum.","ホウレンソウと春菊から放射性物質が検出されました。","edible"];
EXAMPLES[5692]=["The hotel room where we stayed was shabby.","私たちが宿泊したホテルの部屋はみすぼらしかった。","shabby"];
EXAMPLES[5693]=["It was a revelation to me.","それは私にとって意外な話だった。","revelation"];
EXAMPLES[5694]=["Thereafter we heard no more from him.","その後彼からは便りが無かった。","Thereafter"];
EXAMPLES[5695]=["Our teacher dwelt on the importance of punctuality.","先生は時間を守ることの大切さについて長々と述べた。","punctuality"];
EXAMPLES[5696]=["Bill is on the editorial staff.","ビルは編集部員です。","editorial"];
EXAMPLES[5697]=["You must give him up for dead.","君は彼を死んだものとしてあきらめなければなりません。","up for"];
EXAMPLES[5698]=["The supermarket has a large stock of merchandise.","そのスーパーマーケットは大量の商品在庫を持っている。","merchandise"];
EXAMPLES[5699]=["The pharmacist made up the prescription for me.","薬剤師は処方どおりに調合してくれた。","pharmacist"];
EXAMPLES[5700]=["The baby tangled the ball of yarn.","赤ん坊が毛糸の玉をもつれさせた。","yarn"];
EXAMPLES[5701]=["New truth and knowledge always elevate human life and most usually find practical application.","新しい心理と知識は、常に人間生活を向上させ、たいてい実際に利用されるようになる。","elevate"];
EXAMPLES[5702]=["Gargling with salt water helps stop coughing.","せきには塩水のうがいが効く。","Gargling"];
EXAMPLES[5703]=["The tourists were fascinated with the exquisite scenery.","観光客達はその素晴らしい風景にうっとりした。","exquisite"];
EXAMPLES[5705]=["Children have a tendency to become rebellious.","子供は反抗期になる傾向がある。","rebellious"];
EXAMPLES[5706]=["I like this detergent because it lathers well.","この洗剤、泡立ちがいいから気に入ってる。","detergent"];
EXAMPLES[5707]=["The bank has raised its dividend by 20%.","その銀行は二割増配ですよ。","dividend"];
EXAMPLES[5708]=["He wrote a fine preface to the play.","彼はその戯曲にすばらしい序文を書いた。","preface"];
EXAMPLES[5710]=["The typhoon caused a tree to tumble on my yard.","台風で中庭の木が倒れたんだ。","tumble"];
EXAMPLES[5711]=["The man was no better than a horse.","その男は、馬同然であった。","no better than"];
EXAMPLES[5712]=["When I contemplate the sea, I feel calm.","海をじっと眺めていると私は気が静まる感じがする。","contemplate"];
EXAMPLES[5713]=["He was devoured by a tiger.","彼はトラに食われてしまった。","devoured"];
EXAMPLES[5714]=["The traitor betrayed his country to the enemy.","裏切り者は国を敵に売った。","traitor"];
EXAMPLES[5715]=["The earth is not symmetrical about the equator.","地球は赤道に関して対称ではない。","equator"];
EXAMPLES[5716]=["A strong wind began to set in.","強風が陸の方へ吹き始めた。","set in"];
EXAMPLES[5717]=["The scholar is an authority on fiscal policy.","その学者は財政政策の権威である。","fiscal"];
EXAMPLES[5718]=["I plan to get a nice tan this summer.","この夏はこんがり焼こうと思います。","tan"];
EXAMPLES[5719]=["His work was supervising the labourers on the site.","彼の仕事は現場の労働者を監督することだった。","supervising"];
EXAMPLES[5720]=["I can provide you with some statistical predictions of expected revenues.","統計的に予測した歳入見込み額ならお知らせできます。","statistical"];
EXAMPLES[5721]=["We have a cat, and we all adore him.","私たちは猫を飼っています。私たちはみなその猫が好きです。","adore"];
EXAMPLES[5722]=["Excuse me; allow me to point out three errors in the above article.","失礼だが、上記の記事にある３つの誤りを指摘しておきたい。","point out"];
EXAMPLES[5723]=["A vein of poetry exists in the hearts of all men.","誰の心にも詩情ごころはある。","vein"];
EXAMPLES[5725]=["The island was enveloped in a thick fog.","島は濃い霧に包まれていた。","enveloped"];
EXAMPLES[5726]=["The diameter of the hole was slightly larger.","その穴の直径のほうがわずかに大きかった。","diameter"];
EXAMPLES[5728]=["She flapped at the fly with a newspaper.","彼女は新聞でハエをピシャっとたたいた。","flapped"];
EXAMPLES[5729]=["Please give it a quick skim.","適当に読み流してください。","skim"];
EXAMPLES[5730]=["The Tokaido Line was crippled by the typhoon.","東海道線は台風で麻痺状態になった。","crippled"];
EXAMPLES[5731]=["I decided to make medicine my vocation.","私は医者を職業とすることに決めた。","vocation"];
EXAMPLES[5733]=["He rose to the rank of sergeant.","彼は巡査部長の地位に昇った。","sergeant"];
EXAMPLES[5734]=["It's time you had a dose of your medicine.","もう薬を一服飲む時間ですよ。","dose"];
EXAMPLES[5735]=["Do you have a sightseeing brochure for this town?","この町の観光パンフレットはありますか。","brochure"];
EXAMPLES[5736]=["Please refrain from posts that might encourage conflict.","サイトの空気を悪くする書き込みを控えてください。","refrain"];
EXAMPLES[5738]=["You have to judge the case without bias.","君はその問題を公正に判断しなければならない。","bias"];
EXAMPLES[5739]=["The play is a satire on the political world.","その劇は政界を風刺したものだ。","satire"];
EXAMPLES[5740]=["Her dream is to become a simultaneous interpreter.","同時通訳が彼女の憧れだ。","simultaneous"];
EXAMPLES[5741]=["Conversion therapy is torture.","転換療法は拷問です。","Conversion"];
EXAMPLES[5744]=["The fish swam up for crumbs.","パンくずを食べに魚が浮き上がってきた。","crumbs"];
EXAMPLES[5746]=["This is outside my area of expertise.","これは、私の専門外だ。","expertise"];
EXAMPLES[5747]=["You must allow for his youth.","君は彼の若さを考慮に入れなければならない。","allow for"];
EXAMPLES[5748]=["I felt everyone's glare land on me all at once.","一斉にいやな視線が降りかかって来た。","glare"];
EXAMPLES[5750]=["The beauty of the sunset surpassed description.","日没は言葉では表現できないほど美しかった。","surpassed"];
EXAMPLES[5751]=["The time will come when she will repent of it.","彼女がそれを後悔する時が来るだろう。","repent"];
EXAMPLES[5752]=["Giggling with embarrassment, she held out the condom.","彼女はうふふと照れながらコンドームを差し出した。","Giggling"];
EXAMPLES[5753]=["Thank you so much for the punctual confirmation.","早々のご確認、誠に有難うございました。","confirmation"];
EXAMPLES[5755]=["No one shall dictate to me.","私は誰の指図も受けない。","dictate"];
EXAMPLES[5756]=["Pretty soon we'd better wrap up this break and get back to work.","休憩はこれくらいにして、ボチボチ仕事を始めますか。","wrap up"];
EXAMPLES[5757]=["The loud noise gave me a terrible fright.","大きな物音で私は肝をつぶした。","fright"];
EXAMPLES[5758]=["The mouth is the executioner and the doctor of the body.","口は体の死刑執行人であり医者である。","executioner"];
EXAMPLES[5759]=["Newton saw an apple fall off a tree.","ニュートンはりんごが木から落ちるのを見た。","fall off"];
EXAMPLES[5760]=["Circumstances surrounding the textile industry have changed.","繊維産業をとりまく状況は変化した。","textile"];
EXAMPLES[5761]=["This store enjoys a geographical advantage.","この店は地の利をえている。","geographical"];
EXAMPLES[5762]=["I said nothing, which made him more furious.","私は何も言わなかった、そしてそのことで彼は一層激怒した。","furious"];
EXAMPLES[5763]=["It already appears to be dusk.","もう、夕暮れのようである。","dusk"];
EXAMPLES[5765]=["He let his greed get the better of him.","彼は自らの強欲に負けてしまった。","greed"];
EXAMPLES[5766]=["He was overcome by a feeling of melancholy.","彼は憂うつな感情に打ちのめされた。","melancholy"];
EXAMPLES[5767]=["The verdict is a tribute to their fairness.","評決は公平な審議の証拠である。","tribute"];
EXAMPLES[5768]=["It is carried away by tidal waves.","津波で流されてしまったのです。","tidal"];
EXAMPLES[5771]=["I really like the crisp texture of gizzards.","砂肝のコリコリした食感が大好き。","texture"];
EXAMPLES[5772]=["There is a bookstore just around the corner.","角を曲がったところに本屋がある。","just around the corner"];
EXAMPLES[5773]=["The long wait at the airport was tedious.","空港で長く待たされたのは退屈だった。","tedious"];
EXAMPLES[5774]=["The time is ripe for a drastic reform.","今こそ思い切った改革に手を付けるべき好機である。","drastic"];
EXAMPLES[5776]=["We may well take pride in our old temples.","我々が自国の古い寺院を自慢に思うのは当然のことだ。","take pride in"];
EXAMPLES[5778]=["Tom was attacked by a swarm of bees.","トムがハチの群れに襲われたんだ。","swarm"];
EXAMPLES[5779]=["I seem to have caught cold. I'm a little feverish.","風邪を引いたらしい。少し熱がある。","feverish"];
EXAMPLES[5780]=["Once in a while, the prophet indulges in fantasy.","たまに、その預言者は空想にふける。","prophet"];
EXAMPLES[5781]=["I addressed a petition to the mayor.","私は市長に請願を出した。","petition"];
EXAMPLES[5782]=["I wouldn't contradict Tom if I were you.","私だったら、トムには逆らわないけどな。","contradict"];
EXAMPLES[5783]=["You must stick to your promise.","君はあくまでも約束を守らなければならない。","stick to"];
EXAMPLES[5784]=["Clay is the essential ingredient in making pottery.","泥は陶器を作るのに必要な材料です。","pottery"];
EXAMPLES[5785]=["The pitiful tale fetched tears from the girl.","その哀れな話を聞いて少女は涙を浮かべた。","pitiful"];
EXAMPLES[5786]=["I roomed with a delegate from Algeria.","私はアルジェリアからの代表と部屋を共にした。","delegate"];
EXAMPLES[5787]=["You need to have strong thigh muscles to skate.","スケートをするには強い腿の筋肉が必要である。","thigh"];
EXAMPLES[5788]=["You can make it! Go for it. I'll stand by you.","君なら成功できるよ、がんばって。僕は見捨てない。","make it"];
EXAMPLES[5789]=["I have no one to confide in.","私には秘密を打ち明けて相談できる人がいない。","confide"];
EXAMPLES[5792]=["We must be able to differentiate between objects and situations.","我々は物事と状況を区別する事ができないといけない。","differentiate"];
EXAMPLES[5793]=["My left eyelid is twitching.","左のまぶたがぴくぴくする。","eyelid"];
EXAMPLES[5795]=["You'll get into trouble if your girlfriend finds out the truth.","君のガールフレンドが本当のことを知ったら面倒なことになるよ。","get into"];
EXAMPLES[5796]=["Pollution has a disastrous effect on the ecology of a region.","汚染公害は地域の生態環境に壊滅的な影響を与える。","disastrous"];
EXAMPLES[5797]=["He's a nice guy – that's unanimous.","「あいつはいい奴だ」と皆が異口同音に言う。","unanimous"];
EXAMPLES[5798]=["In addition, there were two other deficiencies in that system.","そのうえあのシステムは他にも二つ欠点があった。","deficiencies"];
EXAMPLES[5800]=["Success is due less to ability than to zeal.","成功は能力によるよりむしろ熱心さによる。","zeal"];
EXAMPLES[5801]=["Here, let me take a stab at it.","ほら、俺にもやらせてくれ。","stab"];
EXAMPLES[5803]=["Events of that type generally arouse suspicion.","この種の事件はよく疑惑を生む。","arouse"];
EXAMPLES[5804]=["Recently juvenile delinquency has been on the rise.","近ごろ、少年犯罪が増えた。","on the rise"];
EXAMPLES[5805]=["His accent sounds a little quaint.","彼の口調は少しおかしい。","quaint"];
EXAMPLES[5806]=["I want to pluck your facial hair.","あなたの髭を抜きたいです。","pluck"];
EXAMPLES[5807]=["His death was a sublime self-sacrifice.","彼の死は崇高な自己犠牲だった。","sublime"];
EXAMPLES[5808]=["I like to adorn my room with flowers.","私は部屋を花で飾るのが好きだ。","adorn"];
EXAMPLES[5809]=["The Board of Trustees voted to divest the organization's overseas holdings.","理事会は海外の持ち株を放棄することを議決しました。","Trustees"];
EXAMPLES[5812]=["In the name of God, Most Gracious, Most Merciful.","慈悲深く慈悲あまねき神の御名において。","Merciful"];
EXAMPLES[5813]=["What do you think of this outfit?","この衣装どう思う？","outfit"];
EXAMPLES[5814]=["I moved the forum to a new server.","掲示板を新しいサーバーに移転しました。","forum"];
EXAMPLES[5815]=["I have to submit sales projections twice a quarter.","四半期に２度、販売計画書を提出しなければならない。","projections"];
EXAMPLES[5816]=["The town was desolate after the flood.","洪水の後町は住む人がいなくなった。","desolate"];
EXAMPLES[5818]=["If you don't water the plants, they will wither.","植物は水をやらないと枯れてしまう。","wither"];
EXAMPLES[5819]=["I was enchanted by the performance of the group.","僕はそのグループの演技にうっとりしたよ。","enchanted"];
EXAMPLES[5820]=["The poem was composed by an anonymous author.","その詩は無名の著者が詠んだ。","anonymous"];
EXAMPLES[5821]=["The manager threatened him with dismissal.","支配人は彼を解雇するぞと脅した。","dismissal"];
EXAMPLES[5822]=["His plan has both virtues and liabilities.","彼の計画には長所も欠点もある。","liabilities"];
EXAMPLES[5823]=["The eyes are as eloquent as the tongue.","目は口ほどに物を言う。","eloquent"];
EXAMPLES[5824]=["I often meditate on the meaning of life.","私はしばしば人生の意義について深く考えることがある。","meditate"];
EXAMPLES[5825]=["Water changes into vapor when it is heated.","水は熱せられると蒸気になる。","vapor"];
EXAMPLES[5826]=["I asked him to reconcile them with each other.","僕は彼らを和解させてくれるように彼に頼んだ。","reconcile"];
EXAMPLES[5827]=["A submarine cable was laid between the two countries.","海底ケーブルが両国の間に引かれた。","submarine"];
EXAMPLES[5828]=["I cut the crust off the bread.","パンの耳を切りました。","crust"];
EXAMPLES[5829]=["The glaring headlights dazzled us for a moment.","ヘッドライトがまぶしくて一瞬目がくらんだ。","dazzled"];
EXAMPLES[5830]=["Regardless of the amount, Brian wants the correct, entire amount by next week.","金額にもかかわらず、ブライアンは来週までに間違いなく全額返してもらいたがっています。","Regardless of"];
EXAMPLES[5831]=["He believes in the supernatural.","彼は超自然的なものが有ると信じる。","supernatural"];
EXAMPLES[5832]=["She expends her energy on parties.","彼女はパーティーに精力を使う。","expends"];
EXAMPLES[5833]=["However, the preposition+relative pronoun (which) part becomes a relative adverb (where).","しかしながら、前置詞+関係代名詞whichの部分が関係副詞whereとなっています。","pronoun"];
EXAMPLES[5835]=["I will not presume to give an opinion.","あえて意見を述べることはよしておこう。","presume"];
EXAMPLES[5836]=["One should not lament over past mistakes too long.","人は過去の失敗のことをあまり長い間くよくよすべきではない。","lament"];
EXAMPLES[5837]=["He who gives to another bestows on himself.","情けは人のためならず。","bestows"];
EXAMPLES[5838]=["The divers found a wreck on the sea-bed.","ダイバー達は海底に難破船を見つけた。","wreck"];
EXAMPLES[5839]=["Your answer is to the point.","君の答えは適切である。","to the point"];
EXAMPLES[5840]=["However the disciples awoke to that danger.","しかし、使徒たちはその危険に気付いた。","disciples"];
EXAMPLES[5841]=["International observers counted up the ballot.","国際監視団は投票の集計をしました。","ballot"];
EXAMPLES[5842]=["Large amounts of timber are used in paper making.","大量の材木が紙の製造に使われている。","timber"];
EXAMPLES[5843]=["Pipe down, otherwise you will be hauled out.","だまれ、さもないとほうり出されるぞ。","hauled"];
EXAMPLES[5844]=["I was filled with frightful sorrow for her.","彼女を思う激しい気持ちで胸が一杯だった。","frightful"];
EXAMPLES[5845]=["That makes me disgusted just to think of it.","考えただけで虫唾が走るわ。","disgusted"];
EXAMPLES[5846]=["I have attached a Microsoft Excel file.","マイクロソフトエクセルのファイルを添付しました。","Excel"];
EXAMPLES[5847]=["There are about 500 cattle on the ranch.","その牧場には牛が５００頭ばかりいる。","ranch"];
EXAMPLES[5848]=["Yes, it's an appetizer.","はい、お通しです。","appetizer"];
EXAMPLES[5849]=["The harassed mule got his back up and began kicking up dust.","いじめられたラバは、怒って地面を蹴り上げ砂ぼこりを立て始めた。","back up"];
EXAMPLES[5850]=["He is eminent both as a teacher and writer.","彼は教師としても作家としても著名である。","eminent"];
EXAMPLES[5851]=["I worked hard to compensate for the loss.","私は損害を埋め合わせするために一生懸命働いた。","compensate"];
EXAMPLES[5852]=["The mortality rate per 1000 live births are set out in figure 13.1.","出生数１０００に対する死亡率が図１３．１に示されている。","mortality"];
EXAMPLES[5853]=["He exhaled a deep breath in discouragement.","彼はがっかりして深いため息をついた。","discouragement"];
EXAMPLES[5854]=["Island folklore still recounts the story of the raft.","島の民間伝承はいまだにそのいかだの話を伝えている。","folklore"];
EXAMPLES[5855]=["Rumor of a riot was in the air.","暴動の噂が広まっていた。","riot"];
EXAMPLES[5856]=["The glacier moves but by inches.","氷河はゆっくり動いている。","glacier"];
EXAMPLES[5857]=["I felt as though there were no higher bliss.","これ以上の幸せはないと思った。","bliss"];
EXAMPLES[5858]=["We must concede that we committed an error.","間違いを犯したということは我々は認めねばならない。","concede"];
EXAMPLES[5859]=["Tom is a very outgoing person.","トムはとても社交的な人だ。","outgoing"];
EXAMPLES[5860]=["A wreath was bound around his head.","花環が彼の頭に巻かれた。","wreath"];
EXAMPLES[5862]=["Tasmania is on the 40 degrees South latitude.","タスマニアは南緯４０度のところにあります。","latitude"];
EXAMPLES[5863]=["She has been a wonderful role model for us.","彼女は私たちにとって素晴らしいお手本でした。","role model"];
EXAMPLES[5865]=["When the years pile up, the more things you see.","歳を重ねると見えてくるものがある。","pile up"];
EXAMPLES[5866]=["He behaves as if he were insane.","彼はまるで狂っているかのように振舞っている。","insane"];
EXAMPLES[5867]=["The outraged employee resigned at once.","かんかんに怒った社員は、即刻会社を辞めた。","outraged"];
EXAMPLES[5869]=["The workers have no incentive to work harder.","労働者たちにはもっと働こうとする刺激がなにもない。","incentive"];
EXAMPLES[5870]=["Education shouldn't be aimed at passing a test.","教育はテストに合格することを目指すべきでない。","be aimed at"];
EXAMPLES[5871]=["The judge sentenced him to one year's imprisonment.","判事は彼に禁固１年を宣告した。","imprisonment"];
EXAMPLES[5872]=["You have been beaten. Give in!","君の負けだ、降参しろ。","Give in"];
EXAMPLES[5873]=["His humble background parallels that of his predecessor.","彼の庶民的な経歴は前任者のそれと似ている。","predecessor"];
EXAMPLES[5874]=["She gave her oath that she would not drink.","彼女は酒をやめると誓った。","oath"];
EXAMPLES[5875]=["This remark is not applicable to you.","この意見は貴方に当てはまらない。","applicable"];
EXAMPLES[5876]=["Experience, when it is dearly bought, is never discarded.","経験というものは、大きな犠牲を払って得た場合は、決して忘れてしまうことはないものだ。","discarded"];
EXAMPLES[5877]=["A rustling sound came from upstairs where nobody should've been.","誰もいないはずの二階からガサガサと音がする。","rustling"];
EXAMPLES[5878]=["Your efforts will soon pay off.","君の努力はもうじき実るだろう。","pay off"];
EXAMPLES[5879]=["The doctor's warning stiffened my resolve to stop drinking.","医師の警告で禁酒の決意が固くなった。","stiffened"];
EXAMPLES[5880]=["The secretary took dictation from her boss.","秘書はボスが口述するのを受けた。","dictation"];
EXAMPLES[5881]=["This manual is too theoretical and not very practical.","このマニュアルは理論的すぎて、あまり実用的ではない。","theoretical"];
EXAMPLES[5882]=["What is this the abbreviation for?","何の略字ですか。","abbreviation"];
EXAMPLES[5883]=["A strange man menaced her with a knife.","見知らぬ男が彼女をナイフで脅した。","menaced"];
EXAMPLES[5884]=["I put a bait on a hook.","私は釣り針にえさを付けた。","bait"];
EXAMPLES[5885]=["A complete intransitive verb takes neither complement nor object.","完全自動詞は補語も目的語もとらない。","complement"];
EXAMPLES[5886]=["You have to put up with all these noises.","君はこれらすべての騒音を我慢しなくてはならない。","with all"];
EXAMPLES[5887]=["It was under these circumstances that the constitutional crisis began.","憲政の危機が始まったのは、このような状況のもとであった。","constitutional"];
EXAMPLES[5888]=["Algebra is a branch of mathematics.","代数は数学の１部門です。","Algebra"];
EXAMPLES[5889]=["The traitor was deprived of his citizenship.","その反逆者は市民権を剥奪された。","citizenship"];
EXAMPLES[5890]=["Whenever I'm in trouble, I confer with him.","私は困った時はいつでも彼に相談する。","confer"];
EXAMPLES[5892]=["They can be found around the world in temperate and tropical oceans.","それらは、世界中の温帯、熱帯の海洋で見られます。","temperate"];
EXAMPLES[5893]=["Don't let this chance slip by.","この好機を逃すな。","slip by"];
EXAMPLES[5894]=["The master carpenter is accompanied by three apprentices.","その棟梁は３人の弟子を従えている。","apprentices"];
EXAMPLES[5896]=["He lapsed into despair after that accident.","彼はその事故のあと自暴自棄に陥った。","lapsed"];
EXAMPLES[5897]=["Formidable looking spiders do not attack people.","見かけの恐ろしいクモは人を攻撃することはない。","Formidable"];
EXAMPLES[5898]=["He deemed it wise to accept the offer.","彼は申し出を受諾することが賢明だと考えた。","deemed"];
EXAMPLES[5899]=["Don't say it in a roundabout way.","回りくどい言い方はしないでくれ。","roundabout"];
EXAMPLES[5900]=["All the students will partake in the play.","学生全員が劇に参加しています。","partake"];
EXAMPLES[5901]=["He found all his efforts of no avail.","彼は自分のやったことがすべて水の泡になったことに気づいた。","avail"];
EXAMPLES[5902]=["Mary and Alice are having a slumber party.","メアリーとアリスはお泊まり会をしています。","slumber"];
EXAMPLES[5903]=["We consider public libraries a legitimate citizen's right.","我々は公立図書館を持つことを市民の当然の権利と考えている。","legitimate"];
EXAMPLES[5905]=["People in the country were living under a tyranny.","その国の人々は暴政下で暮らしていた。","tyranny"];
EXAMPLES[5907]=["He sank the deal without batting an eyelash.","彼は平然と取引をつぶしました。","eyelash"];
EXAMPLES[5908]=["I just cleaned my room today. Why is it so messy?","今日部屋の掃除したばかりなのに、なんでこんなに散らかってるの？","messy"];
EXAMPLES[5909]=["May I have a sip of your coffee?","コーヒー、一口いただいてもいいかしら？","sip"];
EXAMPLES[5910]=["The fact has come home to my bosom.","私はその事実を痛感した。","bosom"];
EXAMPLES[5911]=["Article 6. The president shall preside at all meetings.","第６条議長は全会議を主宰するものとする。","preside"];
EXAMPLES[5912]=["Beware of one who praises you to your face.","面と向かって誉める人は用心しなさい。","Beware"];
EXAMPLES[5913]=["I reckon he will be back soon.","彼はすぐ帰ってくると思う。","reckon"];
EXAMPLES[5916]=["He looked small beside my father's stout body.","がっしりした私の父の隣にいて、彼は小さく見えた。","stout"];
EXAMPLES[5917]=["Can you save enough money for the down payment?","お金を貯めて頭金を作れますか。","down payment"];
EXAMPLES[5918]=["Right on schedule, that contractor came around today, begging for more time.","予定通りに、その業者は、時間がもう少し欲しい、と言ってきた。","contractor"];
EXAMPLES[5920]=["His witness is approximate to the truth.","彼の証言は真相に近い。","approximate"];
EXAMPLES[5923]=["Two can play at that game.","そのゲームなら相手になろう。","play at"];
EXAMPLES[5924]=["The municipal council should concentrate more on specific issues.","市議会は具体的な問題にもっと焦点をあてるべきだ。","municipal"];
EXAMPLES[5925]=["I am fed up with his vulgar jokes.","僕は彼の下品な冗談にはうんざりする。","vulgar"];
EXAMPLES[5926]=["Flawless precision is required in the measurements.","測定には寸分の狂いもない精度が要求される。","precision"];
EXAMPLES[5927]=["Have you decided the subject of your thesis?","論文のテーマはもう決まったの？","thesis"];
EXAMPLES[5928]=["I sometimes feel drowsy in the early afternoon.","昼過ぎになると時々眠たくなる。","drowsy"];
EXAMPLES[5929]=["They stood against the picturesque scenery.","彼らは絶景を背にして立った。","picturesque"];
EXAMPLES[5931]=["They have cherished the child as their own.","彼等はその子を自分たちの子としてかわいがってきた。","cherished"];
EXAMPLES[5932]=["Needless to say, Norway has become the world's second largest oil supplier.","言うまでもないが、ノルウェーは世界第二の原油供給国となっている。","supplier"];
EXAMPLES[5933]=["I could not subdue the desire to laugh.","私は笑いたいのを抑えられなかった。","subdue"];
EXAMPLES[5934]=["The load of the truck was in excess of three tons.","そのトラックの積み荷は三トンを超えていた。","in excess"];
EXAMPLES[5935]=["I took a picture at the decisive moment.","私は決定的瞬間を写真に撮った。","decisive"];
EXAMPLES[5936]=["Look under the skin of a civilized man and you will find a barbarian.","文明人も一皮むけば野蛮人。","barbarian"];
EXAMPLES[5937]=["His taste in music is superb.","彼の音楽の好みは素晴らしい。","superb"];
EXAMPLES[5938]=["The government must enforce the law immediately.","政府は法律を施行しなければならない。","enforce"];
EXAMPLES[5939]=["He has a great knowledge of the linguistic field.","彼は言語学の分野にはよく通じている。","linguistic"];
EXAMPLES[5940]=["His resignation left a vacancy in the cabinet.","彼の辞職で官僚の席に空きができた。","vacancy"];
EXAMPLES[5942]=["The outlook for the defense program is dismal.","その防衛計画に関する見通しは暗い。","dismal"];
EXAMPLES[5943]=["She had a sullen look on her face.","彼女はむっつりとした表情を浮かべていた。","sullen"];
EXAMPLES[5945]=["He is the proper person for the job.","その仕事には彼が適任だ。","proper"];
EXAMPLES[5946]=["The money will probably be split evenly between those two.","そのお金は彼ら二人で平等に分けられるでしょう。","evenly"];
EXAMPLES[5947]=["He could not forsake his friend in trouble.","彼は困っている友人を見捨てることは出来なかった。","forsake"];
EXAMPLES[5948]=["What he did is, in plain language, fraud.","彼のしたことは手っ取り早く言えば詐欺だ。","fraud"];
EXAMPLES[5950]=["She had an itch to see her child.","彼女は子供に会いたくてたまらなかった。","itch"];
EXAMPLES[5951]=["Mom applied the plaster to the cut.","母は傷口にばんそうこうをつけてくれた。","plaster"];
EXAMPLES[5952]=["Nobody can foresee when the war will end.","いつ戦争が終わるかだれにも予見できない。","foresee"];
EXAMPLES[5953]=["The plan was doomed to failure from the start.","この計画は初めから失敗する事に運命付けられていた。","doomed"];
EXAMPLES[5954]=["The government dispatched missions abroad.","政府は外国へ使節を派遣した。","dispatched"];
EXAMPLES[5955]=["Mercury is the closest planet to the sun.","水星は太陽に一番近い惑星です。","Mercury"];
EXAMPLES[5956]=["The thief is certain to be caught eventually.","泥棒はきっとそのうちに捕まります。","eventually"];
EXAMPLES[5957]=["A vampire can paralyze people just by looking at them.","吸血鬼は睨むだけで人を金縛りにする。","paralyze"];
EXAMPLES[5958]=["Put the meat in the refrigerator, or it will rot.","肉を冷蔵庫に入れなさい。さもないと腐るよ。","rot"];
EXAMPLES[5960]=["All the trainees share the burden of toil.","全ての研修生はつらい仕事の苦労を分かち合っている。","toil"];
EXAMPLES[5961]=["He is alleged to have been a thief.","彼は泥棒だったそうだ。","alleged"];
EXAMPLES[5962]=["Needless to say, it was a rare occurrence.","言うまでもありませんが、それは滅多にないことでした。","occurrence"];
EXAMPLES[5963]=["The landlord used to be quite well off.","その地主は以前かなり裕福な暮らしをしていた。","landlord"];
EXAMPLES[5964]=["We have just cleaned the lavatory.","ちょうど今トイレの掃除が終わったところです。","lavatory"];
EXAMPLES[5965]=["She kept a tight rein on the purse strings.","彼女は財布のひもをしっかり締めていた。","rein"];
EXAMPLES[5966]=["He was scornful of the danger.","彼は危険を侮った。","scornful"];
EXAMPLES[5967]=["Life in the country is not always tranquil.","田舎での生活がいつも平穏であるとは限らない。","tranquil"];
EXAMPLES[5968]=["Since it was rotten, it was thrown away.","腐ってたから捨てたよ。","rotten"];
EXAMPLES[5969]=["Those boys are in the first flush of youth.","あの少年たちは若さがあふれんばかりだ。","flush"];
EXAMPLES[5970]=["Will you take on the job?","君はその仕事を引き受けますか。","take on"];
EXAMPLES[5971]=["The aurora is a phenomenon characteristic of the polar regions.","オーロラは極地に特有の現象です。","polar"];
EXAMPLES[5972]=["Our army staged a night raid against the enemy.","わが軍は敵に夜襲をかけた。","raid"];
EXAMPLES[5973]=["The sky was fiery with the setting sun.","空は夕日で燃えているようだった。","fiery"];
EXAMPLES[5974]=["The queen was gracious enough to invite us.","女王は寛大にも我々を招待してくださった。","gracious"];
EXAMPLES[5975]=["There will be a surplus of personnel.","人員に余剰が出る","surplus"];
EXAMPLES[5976]=["It took quite a while to sort out all our luggage.","荷物を全部選り分けるのにかなり時間がかかった。","sort out"];
EXAMPLES[5977]=["She slowly disappeared into the foggy forest.","彼女はゆっくりと霧のかかった森の中へ消えていった。","foggy"];
EXAMPLES[5978]=["The company invited their prospective customers to the party.","その会社は将来お得意先になりそうな人々をパーティーに招待した。","prospective"];
EXAMPLES[5980]=["Can you sit through the duration?","その間、ずっと座っとける？","duration"];
EXAMPLES[5981]=["There is a statue of Admiral Nelson in Trafalgar Square.","トラファルガー広場にはネルソン提督の彫像がある。","Admiral"];
EXAMPLES[5982]=["Tom is a self-employed plumber.","トムは自営の配管工だ。","plumber"];
EXAMPLES[5983]=["Don't shriek in my ear like that!","そんなに耳元でギャーギャーわめくなよ。","shriek"];
EXAMPLES[5984]=["I will carry through the work.","私は、その仕事をやり遂げるでしょう。","carry through"];
EXAMPLES[5985]=["There is a political party in Japan that would sell out its own country.","日本には売国奴政党がいます。","sell out"];
EXAMPLES[5986]=["A fox was caught in the snare.","狐がわなにかかった。","snare"];
EXAMPLES[5987]=["But it's the rhetoric of failure.","そいつは衰退のレトリックというものだ。","rhetoric"];
EXAMPLES[5988]=["My father chose not to disturb my optimism.","父は私の楽観を乱さないことにした。","optimism"];
EXAMPLES[5990]=["The pupils are looking forward to the forthcoming excursion.","児童たちは、もうすぐやって来る遠足を楽しみにしている。","forthcoming"];
EXAMPLES[5991]=["I'm the last sane man in the world.","世界に正気な人は僕だけです。","sane"];
EXAMPLES[5992]=["Her movements were awkward and her gesture clumsy.","彼女の動作はぎこちなくしぐさも不器用だった。","clumsy"];
EXAMPLES[5993]=["Hydrogen does not exist as such in nature.","水素はそれ自体としては自然界に存在しない。","Hydrogen"];
EXAMPLES[5994]=["Friction between the Americans and the British mounted.","米国人とイギリス人との間の摩擦が高まった。","Friction"];
EXAMPLES[5995]=["A female kangaroo carries its young in the pouch.","カンガルーの雌は子供を腹の袋に入れて動く。","pouch"];
EXAMPLES[5996]=["There have always been fashionable faces and expressions which marked an epoch.","ある時代の特徴となる流行の顔と表情というものが、常に存在した。","epoch"];
EXAMPLES[5997]=["We hope to lower the tariff.","関税を下げることを望む。","tariff"];
EXAMPLES[5998]=["The dog growled at a little boy.","その犬は小さな男の子に向かって唸った。","growled"];
EXAMPLES[5999]=["His story of the collision agrees with mine.","その衝突について彼が言う事はぼくのと一致する。","collision"];
EXAMPLES[6000]=["My son thinks that bats are reptiles because they're like pteranodons.","息子は、コウモリはプテラノドンの仲間で爬虫類だと思っている。","reptiles"];
EXAMPLES[6001]=["I read many books, and attained refinement.","本をたくさん読んで、教養を付ける。","refinement"];
EXAMPLES[6002]=["The king will appear in person tomorrow evening.","王様は明日の晩自らお出ましになる。","in person"];
EXAMPLES[6004]=["Some people want to amend the constitution.","憲法を改正したいと考えている人たちがいる。","amend"];
EXAMPLES[6005]=["The news gratified us.","その知らせを聞いて私たちは喜んだ。","gratified"];
EXAMPLES[6006]=["At this shop, they deal in kitchen utensils.","その店では、台所用品を扱っている。","utensils"];
EXAMPLES[6007]=["He holds the rank of colonel.","彼は陸軍大佐の位を持っている。","colonel"];
EXAMPLES[6008]=["Lots of herons live in the marsh.","その沼にはサギがたくさん住んでいる。","marsh"];
EXAMPLES[6009]=["The apartment was furnished in the Victorian style.","そのアパートはビクトリア朝風の家具を揃えてあった。","furnished"];
EXAMPLES[6010]=["There was no malice in what he did.","悪意でしたのではない。","malice"];
EXAMPLES[6011]=["The crew is now opening the hatch.","乗務員がただいま出入り口を開けております。","hatch"];
EXAMPLES[6012]=["Have you ever been to the Korean Peninsula?","朝鮮半島を訪れたことがありますか。","Peninsula"];
EXAMPLES[6013]=["The hypothesis is based on the thorough experiments.","その仮説は徹底的な実験に基づいている。","hypothesis"];
EXAMPLES[6014]=["The rice crop was scanty this year.","今年は米作は不作だった。","scanty"];
EXAMPLES[6016]=["Tom happened to let out the secret to his friends.","トムはたまたま友人たちにその秘密を漏らしてしまった。","let out"];
EXAMPLES[6017]=["The plane will get in on time.","飛行機は定刻に到着するでしょう。","get in on"];
EXAMPLES[6018]=["Tom majored in geology.","トムは地質学を専攻してた。","geology"];
EXAMPLES[6019]=["Hero as he was, he was not boastful.","彼は英雄だったが、威張ってなかった。","boastful"];
EXAMPLES[6020]=["In order to do that, you have to take risks.","それをするためには危険を冒さなければならない。","In order"];
EXAMPLES[6021]=["It is not good to ridicule him in public.","公衆の面前で彼を嘲笑するのはよくない。","ridicule"];
EXAMPLES[6022]=["Do you know your forefather?","あなたの祖先をご存知ですか。","forefather"];
EXAMPLES[6023]=["This material will stand up to lots of washings.","この布地は洗濯に強い。","stand up to"];
EXAMPLES[6024]=["We have the alternative of death and submission.","我々には死か降伏かのどちらかしかない。","submission"];
EXAMPLES[6025]=["The minister inspired us with a marvelous sermon.","牧師さんは素晴らしい説教でわたしたちを感動させた。","sermon"];
EXAMPLES[6026]=["He is not the only pebble on the beach.","あの男しかいないわけではないよ。","pebble"];
EXAMPLES[6027]=["The mayor prescribed to the citizens how to act.","市長は市民にどう行動すべきかを指示した。","prescribed"];
EXAMPLES[6028]=["The police are looking into his disappearance.","警察は彼の失踪を調査している。","disappearance"];
EXAMPLES[6030]=["She reproached me for not answering the letter.","彼女は手紙の返事をくれないと私を非難した。","reproached"];
EXAMPLES[6032]=["Business is brisk now and we are up to the elbows in orders.","今は商売の景気が良くて、注文に忙殺されている。","brisk"];
EXAMPLES[6033]=["If you work too long without a rest, it begins to tell on you.","休憩もしないで長時間働けば、体にこたえてくるよ。","tell on"];
EXAMPLES[6034]=["You must heed the advice of your teacher.","先生のおっしゃることを注意して聞かなければなりません。","heed"];
EXAMPLES[6035]=["His mobile phone produced radio emissions that interfered with other phones.","彼の携帯電話は他の電話を妨害する電波を出した。","emissions"];
EXAMPLES[6036]=["It's more polite to say thin than skinny.","「痩せている」と言うよりも「細い」と言った方が失礼に当たりません。","skinny"];
EXAMPLES[6037]=["A good mediator can make a deal go smoothly.","仲介役がしっかりしていると取り引きがスムーズに行く。","mediator"];
EXAMPLES[6038]=["Presumably there will also be school tomorrow?","明日も学校だろ。","Presumably"];
EXAMPLES[6040]=["A good specimen might weigh up to a kilo.","いいものになると１キロにもなるものがありますよ。","specimen"];
EXAMPLES[6041]=["There is a suspension bridge ahead of us.","私たちの目の前に吊り橋がある。","suspension"];
EXAMPLES[6042]=["You must leave diagnosis to your doctor.","診断は医者に任せなければなりません。","diagnosis"];
EXAMPLES[6043]=["Being a foreigner, I couldn't catch on to the joke.","私は外国人なのでその冗談の意味が分からなかった。","catch on"];
EXAMPLES[6044]=["This is a hazard to your health.","これはあなたの健康にとって危険なものだ。","hazard"];
EXAMPLES[6045]=["He's raking it in on the stock market.","彼は株でかなり儲けている。","raking"];
EXAMPLES[6046]=["The bough bent under the weight of the snow.","枝は雪の重みで曲がった。","bough"];
EXAMPLES[6047]=["I've really got to buckle down and study for our final exams.","期末試験に備えて本当に気合いを入れて勉強しなきゃ。","buckle down"];
EXAMPLES[6048]=["He worships money to exclusion of everything else.","彼は他のものが目に入らないほどお金を崇拝している。","exclusion"];
EXAMPLES[6051]=["So characteristic of what a pious Christian would say, this courteous phrase.","いかにも敬虔なるクリスチャンが送る、礼節重き言葉です。","pious"];
EXAMPLES[6052]=["The average life span of the Japanese has lengthened to a great extent.","日本人の平均寿命は大いに伸びた。","lengthened"];
EXAMPLES[6054]=["Jane affirmed that she was telling the truth.","ジェーンは本当のことを言っているのだと断言した。","affirmed"];
EXAMPLES[6055]=["The blue, blue ocean has a feminine beauty.","青い青い海は、女性の美しさをもっている。","feminine"];
EXAMPLES[6057]=["Now the company can justify such expenditure.","最近会社はこの様な支出を正当化できる。","expenditure"];
EXAMPLES[6058]=["I can't run away from the fascination of music.","私は音楽の魅力から逃れることはできない。","fascination"];
EXAMPLES[6059]=["The two parties allied to defeat the Bill.","二つの政党は提携してその法案をつぶした。","allied"];
EXAMPLES[6060]=["Tom was a bachelor all his life.","トムは生涯独身を貫いた。","bachelor"];
EXAMPLES[6062]=["He deliberately kept on provoking a confrontation.","彼は対立を引き起こそうと、わざとしつこくした。","confrontation"];
EXAMPLES[6063]=["She began to grumble and then to weep.","彼女は不平不満をこぼし、泣き始めた。","grumble"];
EXAMPLES[6064]=["Then interaction with others becomes important.","そこで他人との相互作用が大切になる。","interaction"];
EXAMPLES[6065]=["He sent me an affectionate letter.","彼は私に愛情のこもった手紙をくれた。","affectionate"];
EXAMPLES[6066]=["Nancy has a very lively and sweet temperament.","ナンシーはとても陽気でかわいらしい性格だ。","temperament"];
EXAMPLES[6067]=["The atmosphere in a large city is polluted.","大都会の大気は汚染されている。","polluted"];
EXAMPLES[6068]=["This box is too bulky to carry.","この箱はかさばりすぎて運べない。","bulky"];
EXAMPLES[6069]=["A novelty wears off in time.","新しいものはやがてすたれる。","novelty"];
EXAMPLES[6070]=["The visitor sat across from me.","客は私の真向かいに座っていた。","across from"];
EXAMPLES[6071]=["When you travel, you've got to try the local brew.","旅に出たら地酒を飲まなきゃ。","brew"];
EXAMPLES[6072]=["I'd like to have a consultation about getting braces.","歯列矯正についてご相談したいのですが。","braces"];
EXAMPLES[6073]=["The velocity of light is about 186,000 miles per second.","光の速度は秒速およそ186、000マイルである。","velocity"];
EXAMPLES[6074]=["I need to call a tow truck.","レッカー車を呼ばなきゃいけないな。","tow"];
EXAMPLES[6076]=["He is in anguish over her child.","彼は子供のことでひどく悩んでいる。","anguish"];
EXAMPLES[6077]=["We should try to be philosophical about life; wealth gained could also vanish.","人生はあきらめが肝心。設けた財産も消えさることがありうるのだから。","philosophical"];
EXAMPLES[6078]=["The doctor advised me to leave off jogging because it was excessive exercise.","過度の運動なのでジョギングをやめるように医者が私に言った。","leave off"];
EXAMPLES[6079]=["The people could repel the invasion.","人々は侵略を撃退することができた。","repel"];
EXAMPLES[6080]=["We shall be pleased to comply with your request.","ご要望の通りにいたします。","comply"];
EXAMPLES[6081]=["Their habitat is threatened by deforestation.","彼らの生息地は、森林破壊に脅かされています。","habitat"];
EXAMPLES[6082]=["Didn't you lock up your car?","車に鍵をかけておかなかったの？","lock up"];
EXAMPLES[6083]=["The bribery scandal cast doubts on the government.","収賄事件は政府に疑惑を投げかけた。","bribery"];
EXAMPLES[6084]=["You'd better set off at once.","君はすぐ出発した方がよい。","set off"];
EXAMPLES[6085]=["Famine followed upon the eruption of the volcano.","火山の噴火に続いて飢饉が訪れた。","eruption"];
EXAMPLES[6087]=["She embroidered her initials on a white handkerchief.","彼女は白いハンカチに自分のイニシャルを刺繍した。","embroidered"];
EXAMPLES[6088]=["He is pleased when we are bewildered.","彼は私たちが戸惑うと喜ぶ。","bewildered"];
EXAMPLES[6089]=["The terrible scene sent shivers down his spine.","恐ろしい光景に彼は戦慄した。","spine"];
EXAMPLES[6090]=["I would prefer any alternative to a lawsuit.","私は訴訟に変わるものがあればなんでもいい。","lawsuit"];
EXAMPLES[6091]=["She led a group of nuns called the Missionaries of Charity.","彼女は慈善伝導団と呼ばれる修道女達の集団を指導していた。","Missionaries"];
EXAMPLES[6092]=["Critique of Pure Reason is German philosopher Immanuel Kant's chief literary work.","「純粋理性批判」はドイツの哲学者エマニュエル・カントの主著である。","Critique"];
EXAMPLES[6093]=["He is able to subordinate passion to reason.","彼は理性で情欲を制することが出来る。","subordinate"];
EXAMPLES[6098]=["She laughed and gave me a playful shove.","彼女は笑い、私をいたずらっぽく小突いた。","shove"];
EXAMPLES[6100]=["A sprained ankle disabled him from walking for a month.","足首のねんざで彼は一ヶ月歩けなかった。","disabled"];
EXAMPLES[6101]=["No man can resist the lure of a woman.","女の髪の毛には大象もつながる。","lure"];
EXAMPLES[6103]=["The police arrested him for smuggling.","警察は密輸のかどで彼を捕縛した。","smuggling"];
EXAMPLES[6104]=["I will endorse it.","俺が保証するよ。","endorse"];
EXAMPLES[6105]=["I am still a novice, but I look forward to working with you all.","まだまだ未熟者ですが、皆さんよろしくお願いします。","novice"];
EXAMPLES[6106]=["The war ushered in a period of shortages and deprivation.","戦争は不足と欠乏の時代を招いた。","deprivation"];
EXAMPLES[6107]=["I used to read novels at random.","手当たり次第に小説を読んだものだ。","at random"];
EXAMPLES[6108]=["Mr Smith is accused of breach of contract.","スミス氏は契約違反で告訴されている。","breach"];
EXAMPLES[6110]=["The scar on his forehead is conspicuous.","彼の額の傷痕は目立つ。","conspicuous"];
EXAMPLES[6112]=["The boy trotted to his father's side.","その男の子は父親のそばへちょこちょこ走って行った。","trotted"];
EXAMPLES[6113]=["Supposedly, Tom is a good cook.","おそらくトムは良いコックだ。","Supposedly"];
EXAMPLES[6115]=["He was too frail to play games outdoors.","彼はあまりにもひ弱で戸外でゲームをする事はなかった。","frail"];
EXAMPLES[6116]=["I think she is withholding information from the police.","彼女は警察に情報を提供するのを見合わせていると思います。","withholding"];
EXAMPLES[6118]=["Debate is an academic game between the affirmative and the negative.","ディベートとは肯定側と否定側で交わされる知的ゲームである。","affirmative"];
EXAMPLES[6119]=["Push through the crowds and proceed to the target area.","人垣をかきわけて目的の場所へと進む。","Push through"];
EXAMPLES[6120]=["The two banks consolidated and formed a single large bank.","二つの銀行が合併して一つの大銀行を作った。","consolidated"];
EXAMPLES[6121]=["Is it still up in the attic?","それって、まだ屋根裏部屋にあるの？","attic"];
EXAMPLES[6122]=["He hung the gate on hinges.","彼は門をちょうつがいで取り付けた。","hinges"];
EXAMPLES[6123]=["How can I meet this quota?","どうやってこのノルマを達成すればいいんだ？","quota"];
EXAMPLES[6125]=["The laws apply to everyone irrespective of race, creed or color.","その法律は人種宗教肌の色に関わらずすべての人に適用される。","creed"];
EXAMPLES[6126]=["The new boy had a nervous stammer.","その来たばかりの子はおどおどして口ごもった。","stammer"];
EXAMPLES[6128]=["It is difficult to determine the state and safety of the radiation leakage.","放射能漏れの実態や安全確認することは難しいのです。","radiation"];
EXAMPLES[6129]=["I'll mail this questionnaire as soon as I finish.","終わり次第すぐにこの質問用紙を送ります。","questionnaire"];
EXAMPLES[6132]=["Is there any adverse reaction?","副作用はありませんか。","adverse"];
EXAMPLES[6133]=["Please tell me how the theft was done.","その盗難がどのようにして行われたか教えてください。","theft"];
EXAMPLES[6134]=["The lunar month is shorter than the calendar month.","太陰月はカレンダーのひと月より短い。","lunar"];
EXAMPLES[6135]=["He had to spend many barren days.","彼は多くの日々をむなしく過ごさなければならなかった。","barren"];
EXAMPLES[6137]=["Such men count for much in the society.","そのような人が社会で重要なのだ。","count for"];
EXAMPLES[6138]=["The entire crew was afflicted with food poisoning.","乗務員全員が食中毒で苦しんだ。","afflicted"];
EXAMPLES[6139]=["Those people appreciate clarity.","その人たちは明瞭さをよしとする。","clarity"];
EXAMPLES[6140]=["December 3 is the International Day of Persons with Disabilities.","12月3日は国際障害者デーです。","Disabilities"];
EXAMPLES[6141]=["He was deaf to my pleas.","彼は僕の訴えを聞こうとしなかった。","pleas"];
EXAMPLES[6142]=["The man was on the brink of death.","その男は死にかけていた。","brink"];
EXAMPLES[6144]=["He gave my hand a firm clasp.","彼は私の手をしっかりと握った。","clasp"];
EXAMPLES[6146]=["Listen to those whom you think to be honest.","あなたが正直だと思う人の言う事を聞きなさい。","to be honest"];
EXAMPLES[6147]=["Scott is an entrepreneur with much spirit of enterprise.","スコットさんは企業家精神に富む経営者なんです。","entrepreneur"];
EXAMPLES[6149]=["He is what is called a walking encyclopedia.","彼はいわゆる歩く百科事典だ。","encyclopedia"];
EXAMPLES[6151]=["Her request never reached its intended recipient.","彼女の願いは届かなかった。","recipient"];
EXAMPLES[6152]=["He aspired to the position of Prime Minister.","彼は総理大臣になりたいという野心を抱いた。","aspired"];
EXAMPLES[6153]=["The class was too big so we split up into two smaller groups.","クラスが大きすぎるので二つのより小さなグループに分割した。","split up"];
EXAMPLES[6154]=["You know nothing about the Andromeda galaxy.","あなたはアンドロメダ銀河のことを全然分かってないね。","galaxy"];
EXAMPLES[6155]=["The horse snorted impatiently.","馬はじれったそうに鼻を鳴らした。","snorted"];
EXAMPLES[6156]=["I think you had better call on him.","君は彼を訪問した方がよいと思う。","call on"];
EXAMPLES[6157]=["She was standing amid the ruins of the castle.","彼女は城の廃墟の中にたたずんでいた。","amid"];
EXAMPLES[6159]=["The dictator arrogated judicial powers to himself.","独裁者は司法権を自分のものとした。","judicial"];
EXAMPLES[6160]=["Clench your teeth together, please.","歯をかみ合わせてみてください。","Clench"];
EXAMPLES[6161]=["I think it is a mere coincidence.","私はそれは単なる偶然だと思う。","coincidence"];
EXAMPLES[6163]=["Can you get by on your wages?","今の給料でやっていけるのか？","wages"];
EXAMPLES[6166]=["Add water and mix to a firm dough.","水を加え、練り粉がどろどろしない程度に混ぜなさい。","dough"];
EXAMPLES[6167]=["The congregation was moved by the fine sermon.","会衆は素晴らしい説教に感動した。","congregation"];
EXAMPLES[6168]=["Her only interest is the accumulation of money.","彼女のたった一つの関心事は金をためることだ。","accumulation"];
EXAMPLES[6169]=["He did not relish this simple family life.","彼にはこの単調な家庭生活がおもしろくなかった。","relish"];
EXAMPLES[6170]=["This species holds the record for long-distance migration.","この種は長距離移動の記録を持っています。","migration"];
EXAMPLES[6171]=["He sprawled out on the sofa next to me.","彼は私の横でソファーにゆったりと座った。","sprawled"];
EXAMPLES[6172]=["Apply a compress to the affected part every two hours.","２時間毎に局部を湿布しなさい。","compress"];
EXAMPLES[6173]=["All inventions grow out of necessity.","あらゆる発明は必要から生じる。","grow out of"];
EXAMPLES[6174]=["She was superstitious, as the people of that period usually were.","その時代の人の常として彼女もまた迷信深かった。","superstitious"];
EXAMPLES[6175]=["This is a condition caused by aging.","老化現象の一種です。","aging"];
EXAMPLES[6176]=["The irrational conversation continued.","非合理的な会話が続いた。","irrational"];
EXAMPLES[6177]=["Spaniards love to stroll around in the evening cool.","スペイン人は夜の涼しさの中を散歩するのが大好きだ。","stroll"];
EXAMPLES[6178]=["The sculptor belongs to the Renaissance school.","その彫刻家はルネサンス派に属する。","sculptor"];
EXAMPLES[6180]=["We have to bring our teaching methods up to date.","我々は教育の方法を時代に呼応させなくてはならない。","to date"];
EXAMPLES[6182]=["Will humanity be able to prevent the degradation of ecosystems?","人類は生態系の退化を防ぐことができるだろうか？","degradation"];
EXAMPLES[6183]=["I grew to want to eat an authentic pretzel!","本場のプレッツェルが食べてみたくなった！","authentic"];
EXAMPLES[6184]=["He was not allowed to enroll in the college.","彼はその大学に入学を許可されなかった。","enroll"];
EXAMPLES[6185]=["Is it really possible to do a brain transplant?","脳移植は本当に可能なのでしょうか？","transplant"];
EXAMPLES[6186]=["The police arrested the pickpocket in the act.","警察はすりを現行犯で取り押さえた。","pickpocket"];
EXAMPLES[6187]=["I hope you become an advanced contributor.","上級ユーザーになってくれたらいいのにな。","contributor"];
EXAMPLES[6188]=["On his deathbed he asked me to continue writing to you.","彼は死ぬ間際にあなたに手紙を書き続けるように頼みました。","deathbed"];
EXAMPLES[6189]=["Zoology and botany deal with the study of life.","動物学と植物学は生命の研究を取り扱っている。","botany"];
EXAMPLES[6190]=["We need to scrub the floor.","僕らはその床を洗う必要がある。","scrub"];
EXAMPLES[6191]=["In the first place we have to decide on the name.","まず第一に名前を決めなくちゃ。","In the first place"];
EXAMPLES[6192]=["A serious epidemic has broken out in Beijing.","深刻な伝染病が北京で発生した。","epidemic"];
EXAMPLES[6193]=["This financial audit also includes an evaluation of the company's assets.","この財務調査は会社の資産を評価することも含みます。","audit"];
EXAMPLES[6195]=["This rite is part of their religion.","その儀式は彼らの宗教の一部である。","rite"];
EXAMPLES[6196]=["A thing you should have is friends, buddy!","持つべきものは友よ友！","buddy"];
EXAMPLES[6197]=["A blood vessel burst inside his brain.","彼の脳内で血管が破裂した。","blood vessel"];
EXAMPLES[6198]=["Tom is yearning to live in the country.","トムは田舎暮らしに憧れてるんだ。","yearning"];
EXAMPLES[6199]=["The flood began to subside.","洪水がおさまり始めた。","subside"];
EXAMPLES[6200]=["There was a special sneak preview last night.","昨日の夜、特別試写会があった。","sneak"];
EXAMPLES[6201]=["But custody of the children was a problem.","問題は子供の引き取り権だった。","custody"];
EXAMPLES[6203]=["I decided to go away with the pilgrims.","遍路さんたちと一緒に去る事に決めた。","pilgrims"];
EXAMPLES[6204]=["Japan is made up of volcanic islands.","日本は火山列島だ。","volcanic"];
EXAMPLES[6205]=["Will you notify me in three minutes?","３分たったら教えてもらえますか。","notify"];
EXAMPLES[6206]=["Are you going to mow the lawn today?","今日は芝刈りする予定なの？","mow"];
EXAMPLES[6207]=["The dismissal of foreign minister Tanaka is symbolic of the continuing political turmoil.","田中前外相の更迭に続く政治混乱がその象徴である。","turmoil"];
EXAMPLES[6208]=["A button has come off my raincoat.","レーンコートのボタンがとれた。","come off"];
EXAMPLES[6209]=["This diamond ring is too extravagant for me.","このダイヤの指輪は私にはぜいたくすぎる。","extravagant"];
EXAMPLES[6211]=["The troops were in battle array.","軍隊は戦闘の配置で整列していた。","array"];
EXAMPLES[6212]=["The roof was torn off by the gale.","屋根は強風に飛ばされた。","gale"];
EXAMPLES[6213]=["The dog was sniffing a stick.","犬は棒の匂いを嗅いでいた。","sniffing"];
EXAMPLES[6214]=["In all likelihood, it will rain this afternoon.","おそらく今日の午後は雨が降るだろう。","likelihood"];
EXAMPLES[6216]=["Boston Dynamics created a robot that can even run.","ボストンダイナミクスは走ることさえ出来るロボットを造りましたよ。","Dynamics"];
EXAMPLES[6218]=["Greta chugged the beer in one gulp.","グレタ君がビールを一口で飲み干した。","gulp"];
EXAMPLES[6219]=["Tom was made redundant.","トムはリストラされた。","redundant"];
EXAMPLES[6221]=["We marveled at the little boy's eloquence.","我々はその小さな男の子の雄弁さに驚いた。","eloquence"];
EXAMPLES[6222]=["The main thing that dreams lack is consistency.","夢に欠けている主な事は首尾一貫性である。","consistency"];
EXAMPLES[6223]=["Her exotic perfume has a subtle scent.","彼女の外国製の香水はほのかな香りがする。","exotic"];
EXAMPLES[6224]=["He is apt to give vent to his feelings.","彼は感情を表わしがちだ。","vent"];
EXAMPLES[6225]=["Casualties are said to total up to 1,000.","死傷者は合計1000名となったということだ。","Casualties"];
EXAMPLES[6226]=["The judge decided against the plaintiff.","裁判官は原告に不利な判決を下した。","plaintiff"];
EXAMPLES[6227]=["Shareholders with questions, please raise your hands.","ご質問のある株主の方は、挙手をお願いいたします。","Shareholders"];
EXAMPLES[6228]=["He defies the present government which is no less oppressive than its predecessor.","彼は、前の政府に劣らず圧制的な現政府に公然と反抗している。","oppressive"];
EXAMPLES[6229]=["The saleswoman queried as she wrapped the gloves.","美人店員は手袋を袋に包みながら尋ねた。","queried"];
EXAMPLES[6230]=["The players marched triumphantly across the field.","選手達は意気揚々と競技場を行進した。","triumphantly"];
EXAMPLES[6231]=["It is money that many people worship most.","多くの人が最も崇拝するものはお金である。","worship"];
EXAMPLES[6232]=["I can't hold up my head before him.","あの人の前では頭が上がらない。","hold up"];
EXAMPLES[6234]=["This product is an intelligent integrated information system.","このプロダクトはインテリジェント総合情報システムです。","integrated"];
EXAMPLES[6235]=["This ghost photo is well made, but it's just a composite.","この心霊写真、よくできているけど、ただの合成写真だよ。","composite"];
EXAMPLES[6236]=["City dwellers have a higher death rate than country people do.","都会人は田舎の人よりも死亡率が高い。","dwellers"];
EXAMPLES[6237]=["I gave you explicit instructions not to touch anything.","私はあなたに何にも触るなとはっきりと指示しました。","explicit"];
EXAMPLES[6238]=["Tom appeared from out of nowhere.","トムはどこからともなく現れた。","out of nowhere"];
EXAMPLES[6239]=["Cultures have a coherent view of the world.","それぞれの文化には首尾一貫した世界観がある。","coherent"];
EXAMPLES[6240]=["He is alleged to have stolen the jewelry.","彼は宝石を盗んだといわれている。","alleged"];
EXAMPLES[6241]=["His dress somehow gives an aristocratic impression.","出で立ちが何となく貴族っぽいような気がする。","aristocratic"];
EXAMPLES[6242]=["I bought it at a thrift shop.","リサイクルショップで買ったんです。","thrift"];
EXAMPLES[6243]=["The views of the two politicians collide violently.","二人の政治家の見解は激しく激突している。","collide"];
EXAMPLES[6246]=["Janet and Bill are going to get hitched in June.","ジャネットとビルは６月に結婚する。","hitched"];
EXAMPLES[6249]=["He curled his lip in a sneer.","彼は軽蔑したように唇をゆがめた。","sneer"];
EXAMPLES[6251]=["I am in a terrible dilemma.","これは困ったことになった。","dilemma"];
EXAMPLES[6252]=["Maybe the impulse was working upon her subconscious.","たぶん彼女の潜在意識の中にそういう衝動があったんでしょうね。","subconscious"];
EXAMPLES[6253]=["The company is open for equity participation by anybody.","その会社には誰でも資本参加できる。","equity"];
EXAMPLES[6255]=["The statute of limitations has already passed for this crime.","この犯罪については時効が成立している。","statute"];
EXAMPLES[6256]=["The small retail outlet is only a front for a much larger entity.","あの小売店のバックにはもっと大きな会社がひかえています。","entity"];
EXAMPLES[6257]=["The policy will only accelerate inflation.","その政策は、インフレを加速させるだけだ。","accelerate"];
EXAMPLES[6259]=["I am speculating that he may win the game.","僕は彼が試合に勝つのではないかと推測している。","speculating"];
EXAMPLES[6260]=["He sat down to recover from his agitation.","彼は興奮を静めるために座った。","agitation"];
EXAMPLES[6261]=["This case is outside my jurisdiction.","この件は私の管轄外だ。","jurisdiction"];
EXAMPLES[6262]=["He is allegedly the murderer.","伝えられる所では彼がその殺人犯だと言われている。","allegedly"];
EXAMPLES[6263]=["Apart from earning money, I have no interest in real estate.","金儲けのことを除けば、私は不動産のことには興味はない。","real estate"];
EXAMPLES[6264]=["Hundreds of fields were submerged in the flood.","洪水で何百という畑が冠水した。","submerged"];
EXAMPLES[6267]=["My artisan pride cannot tolerate such sloppiness.","そんないい加減なことはわしの職人気質が許さない。","artisan"];
EXAMPLES[6268]=["The hero, as a child, suffered from parental neglect.","主人公は、子供の頃、親にほったらかしにされて苦しんだ。","parental"];
EXAMPLES[6269]=["Suffice to say, Edna gets no work done.","言うまでもなく、エドナはなにもできない。","Suffice"];
EXAMPLES[6270]=["He was arrested on the charge of burglary.","彼は強盗のかどで逮捕された。","burglary"];
EXAMPLES[6272]=["This segment is brought to you by the Ford Motor Company.","この部品はフォード社から君に届いたものだ。","segment"];
EXAMPLES[6273]=["My fingers have gone numb from the cold.","指が寒さでかじかんじゃったよ。","numb"];
EXAMPLES[6274]=["A thief lurked in the dark doorway.","盗賊が暗い戸口に潜んでいた。","lurked"];
EXAMPLES[6275]=["I'd like a quote for the following.","下記に対して価格を提示してください。","quote"];
EXAMPLES[6277]=["He is working as a security guard at a warehouse.","彼は倉庫の警備員として仕事をしている。","warehouse"];
EXAMPLES[6278]=["You should be more considerate of your parents.","君は両親に対してもっと思いやりの心を持つべきです。","considerate"];
EXAMPLES[6279]=["He expelled the students from the room.","彼は学生を部屋から出した。","expelled"];
EXAMPLES[6280]=["I had never seen a windmill until I visited the Netherlands.","オランダを訪問するまで、風車を見たことがなかった。","windmill"];
EXAMPLES[6281]=["He had been a practitioner of Aikido for seven years.","彼は７年間、合気道をやっていた。","practitioner"];
EXAMPLES[6282]=["As depicted, he was about thirty years old.","イメージどおり、三十路くらいの人だったよ。","depicted"];
EXAMPLES[6283]=["What is it that satisfies your aesthetic sense?","あなたの美意識を満足させるものは何ですか？","aesthetic"];
EXAMPLES[6284]=["There are few legal constraints on the sale of firearms in the U.S.","合衆国には小火器の販売に関する法律上の制約はほとんどない。","constraints"];
EXAMPLES[6285]=["There's a volcano emitting masses of smoke in Iceland.","アイスランドには大量の煙を吐き出している火山があります。","emitting"];
EXAMPLES[6286]=["Rumors that Tom and Mary are dating have been swirling for weeks.","トムとメリーがデートしているという噂が数週間渦巻いている。","swirling"];
EXAMPLES[6287]=["The net got entangled in the propeller.","網がスクリューに絡まった。","propeller"];
EXAMPLES[6290]=["You look very dignified.","貫禄がついたね。","dignified"];
EXAMPLES[6292]=["He once belonged to the Fukuda faction.","彼は福田派に属していました。","faction"];
EXAMPLES[6293]=["The net got entangled in the screw.","網がスクリューに絡まった。","entangled"];
EXAMPLES[6295]=["Cars are indispensable to suburban life.","車は郊外の生活に欠くことが出来ないものである。","suburban"];
EXAMPLES[6296]=["This restaurant lives up to all the rave reviews it got.","このレストラン、評判通りのおいしさだね。","rave"];
EXAMPLES[6297]=["Tom went down the river on a raft.","トムは、いかだで川を下った。","raft"];
EXAMPLES[6298]=["Please extinguish cigarettes before entering the museum.","美術館に入る前には、煙草を消してください。","extinguish"];
EXAMPLES[6301]=["Tom disappeared while out on bail.","トムは保釈中に行方をくらました。","bail"];
EXAMPLES[6303]=["Do you take in students?","学生でも下宿させてもらえますか。","take in"];
EXAMPLES[6304]=["In the distance the thunder is rumbling.","遠くで雷がゴロゴロいってるよ。","rumbling"];
EXAMPLES[6305]=["That very tune reminded me of my adolescence.","まさにあの曲が私に若い頃のことを思い出させた。","adolescence"];
EXAMPLES[6306]=["I feel so bad I want to vomit...","気持ち悪くて吐きたい・・・。","vomit"];
EXAMPLES[6307]=["Why are you so obsessed with her?","どうしてそんなに彼女にこだわるの？","obsessed"];
EXAMPLES[6308]=["What do your words add up to?","結局お言葉はどういう意味になるのですか。","add up to"];
EXAMPLES[6309]=["Her eyes gushed with tears.","彼女の目には涙が湧きあふれていた。","gushed"];
EXAMPLES[6310]=["You are too negligent of those around you.","君は周囲の人に無関心すぎるよ。","negligent"];
EXAMPLES[6311]=["He tried to unify the various groups.","彼は様々のグループを統一しようとした。","unify"];
EXAMPLES[6313]=["Are you currently taking any kind of medication?","今現在、何か飲んでいる薬はありますか？","medication"];
EXAMPLES[6314]=["For instance, gauges, such as thermometers and barometers, are instruments.","例えば、温度計や気圧計などの計器は器具です。","gauges"];
EXAMPLES[6315]=["The slaughter of the prisoners was a barbarous act.","捕虜を虐殺したのは残忍な行為だ。","slaughter"];
EXAMPLES[6316]=["The train traversed a tunnel.","汽車はトンネルを通り抜けた。","traversed"];
EXAMPLES[6317]=["He would often go to that tavern.","彼はその居酒屋によく出かける。","tavern"];
EXAMPLES[6318]=["I found an old rusty key in that room.","その部屋で古びた錆だらけの鍵を見つけました。","rusty"];
EXAMPLES[6320]=["You just messed up once. You don't need to agonize over it.","たった１回失敗したぐらいでクヨクヨするなよ！","agonize"];
EXAMPLES[6321]=["He is going to run for the Presidency.","彼は大統領に立候補するだろう。","Presidency"];
EXAMPLES[6322]=["This morning was tough because of my hangover.","今朝は二日酔いで辛かったです。","hangover"];
EXAMPLES[6323]=["I go to the pharmacy and buy medicine.","薬局へ行って薬を買う。","pharmacy"];
EXAMPLES[6327]=["To some extent, you can control the car in a skid.","その車はスリップしてもある程度はコントロールできます。","skid"];
EXAMPLES[6328]=["He was ignorant of the plot to assassinate him.","彼は自分を暗殺しようという陰謀を知らなかった。","assassinate"];
EXAMPLES[6329]=["Students have access to the library.","学生は図書館を利用できます。","have access to"];
EXAMPLES[6330]=["Love is merely a lyrical way of referring to lust.","恋愛はただ性欲の詩的表現をうけたものである。","lust"];
EXAMPLES[6331]=["Most people live in pursuit of happiness.","たいていの人々は幸福を求めて生きている。","in pursuit of"];
EXAMPLES[6332]=["Game birds abound in the area.","その地区には猟鳥が多い。","abound"];
EXAMPLES[6333]=["The police had all the prostitutes line up in a straight line.","警察は、娼婦全員を一列に並べさせた。","prostitutes"];
EXAMPLES[6334]=["The site was productive in development.","現場は開発に積極的だった。","in development"];
EXAMPLES[6335]=["These infections were caused by contaminated milk.","これらの感染病はミルクの汚染が原因だった。","contaminated"];
EXAMPLES[6336]=["The weather in April is unstable.","4月の天気は不安定です。","unstable"];
EXAMPLES[6339]=["These trousers are made of durable cloth.","このズボンは長もちする布地でできている。","durable"];
EXAMPLES[6340]=["He was tempted to retort, but thought better of it.","彼は反発したいという気になったが、思い直してやめた。","retort"];
EXAMPLES[6341]=["Discrimination on the basis of gender is prohibited.","性別による差別は禁じられています。","gender"];
EXAMPLES[6342]=["Two global studies in children with hemophilia A are ongoing.","A型血友病の小児患者を対象とした国際的な研究が2本走っている。","ongoing"];
EXAMPLES[6343]=["Yeah, but I'll have to take the rap if they slip up.","ええ、でも大きなミスがあったら、私の責任になってしまうもの。","slip up"];
EXAMPLES[6344]=["That might come off as sarcastic.","それは皮肉に聞こえちゃうかもね。","sarcastic"];
EXAMPLES[6345]=["When we arrived, the crowd had faded away.","着いてみると群衆はいなくなっていた。","faded"];
EXAMPLES[6346]=["I see no analogy between your problem and mine.","君の問題と僕の問題との間には類似点はない。","analogy"];
EXAMPLES[6348]=["We must register for the courses that we're going to take by tomorrow.","明日までに履修する科目の登録をしなければなりまれん。","register for"];
EXAMPLES[6349]=["The medieval church despised the body and exalted the spirit.","中世の教会は肉体をさげすみ霊をたたえた。","exalted"];
EXAMPLES[6350]=["He has integrity, so he has many friends.","彼は正直なのでたくさん友達がいる。","integrity"];
EXAMPLES[6351]=["They replaced the defective TV with a new one.","彼らは欠陥テレビを新しいのと取りかえた。","defective"];
EXAMPLES[6352]=["The reformers were subject to every attack from the Establishment.","改革者たちは支配層からのあらゆる非難にさらされた。","subject to"];
EXAMPLES[6354]=["We worked hard to make ends meet.","やりくりするために一生懸命働いた。","make ends meet"];
EXAMPLES[6355]=["Just to think about the accident makes me shudder.","その事故のことを考えただけで、私は身が震える。","shudder"];
EXAMPLES[6356]=["I feel for you.","君に同情するよ。","feel for"];
EXAMPLES[6358]=["I got a cramp in my leg while swimming.","水泳中に足がつった。","cramp"];
EXAMPLES[6359]=["You did a lot of work in frantic haste.","あなたはたくさんの仕事を狂わんばかりに急いで片づけた。","frantic"];
EXAMPLES[6360]=["I was tickled by her breath against my hair.","彼女の息が髪に当たってくすぐったかった。","tickled"];
EXAMPLES[6362]=["I regard crab as a great delicacy.","私はカニを大ごちそうだと思っている。","delicacy"];
EXAMPLES[6363]=["Thomas Edison invented the light bulb.","トマス・エジソンが電球を発明した。","light bulb"];
EXAMPLES[6366]=["The angler felt a strong tug on the line.","その釣り人は釣り糸に強い引きを感じた。","tug"];
EXAMPLES[6368]=["The lyrics are good, but the voice is quiet.","歌詞はいいけど声が小さい。","lyrics"];
EXAMPLES[6369]=["Expressions and smiles change like that just from applying rouge and lipstick.","ほお紅や口紅を差すだけで表情や笑顔がどんどん変わってくるんです。","rouge"];
EXAMPLES[6370]=["Sulfur is used to make matches.","硫黄はマッチを作るのに使われる。","Sulfur"];
EXAMPLES[6371]=["You need to tie up your shoe laces when they come undone.","靴の紐がほどけたら、結ばないといけません。","tie up"];
EXAMPLES[6372]=["The wind rippled the surface of the water.","風の水の面が波だった。","rippled"];
EXAMPLES[6373]=["His testimony is close to the truth.","彼の証言は真相に近い。","testimony"];
EXAMPLES[6374]=["My memory of her has begun to recede.","彼女は私の記憶からしだいに薄れている。","recede"];
EXAMPLES[6375]=["It is difficult to ascertain what really happened.","ことの真相は突き止めがたい。","ascertain"];
EXAMPLES[6376]=["The damage from the flood was negligible.","洪水の被害はごくわずかだった。","negligible"];
EXAMPLES[6377]=["My tape recorder is compatible with your amplifier.","私のテープレコーダーは君のアンプにもつなげられる。","compatible"];
EXAMPLES[6379]=["The soldier disdained shooting an unarmed enemy.","その兵士は丸腰の兵士を撃つことを潔しとしなかった。","disdained"];
EXAMPLES[6380]=["Death ends man's finite existence.","死によって人間の限りある人生は終わる。","finite"];
EXAMPLES[6381]=["He was poached by a rival company.","彼はライバル会社に引き抜かれました。","poached"];
EXAMPLES[6383]=["In an earthquake, the ground can shake up and down, or back and forth.","地震では地面は上下、そして横に揺れる。","shake up"];
EXAMPLES[6384]=["The mountain was blurred by fog.","霧のため山の輪郭がぼんやりしていた。","blurred"];
EXAMPLES[6385]=["Experience is the only prophecy of wise men.","経験は賢明な人の唯一の予言である。","prophecy"];
EXAMPLES[6386]=["This is a decimal number.","これは十進数表記です。","decimal"];
EXAMPLES[6387]=["I am not feeling quite up to par.","どうも気分がすぐれない。","par"];
EXAMPLES[6388]=["The aviation expert analyzed the statistics in detail.","その航空専門家は統計を詳細に分析した。","aviation"];
EXAMPLES[6389]=["He was held in captivity.","彼は捕虜になった。","captivity"];
EXAMPLES[6391]=["Representatives made a major breakthrough in the trade talks.","代表団は貿易交渉を大きく前進させました。","breakthrough"];
EXAMPLES[6392]=["We used the transcripts of the recordings of telephone conversations.","電話での会話の録音を文学化した資料を用いた。","transcripts"];
EXAMPLES[6393]=["You should use a deodorant.","デオドラント使ったほうがいいよ。","deodorant"];
EXAMPLES[6394]=["To tell the truth, she gave away all her money to others in desperation.","実のところ、彼女はやけになって、有り金をみんな人にやってしまったのだ。","desperation"];
EXAMPLES[6395]=["All at once, I heard a shrill cry.","突然鋭い叫び声が聞こえた。","shrill"];
EXAMPLES[6396]=["A contagious disease descended on the town.","伝染病が不意にその町を襲った。","contagious"];
EXAMPLES[6397]=["Russia expresses regret for those lost in the hostage incident.","ロシア：人質事件の犠牲となった方々に哀悼の意を表す。","hostage"];
EXAMPLES[6398]=["We have established the institute with a view to facilitating the research.","われわれは研究を促進するために、この協会を設立した。","facilitating"];
EXAMPLES[6399]=["Queen Victoria was the sovereign of Great Britain.","ビクトリア女王は英国の君主だった。","sovereign"];
EXAMPLES[6400]=["There really is such a thing as Internet addiction.","インターネット中毒って、本当にあるみたいね。","addiction"];
EXAMPLES[6402]=["The history of all hitherto existing societies is the history of class struggles.","昔から今に至るまで存在する、あらゆる社会の歴史は階級闘争の歴史である。","hitherto"];
EXAMPLES[6403]=["The postmortem showed that she had been strangled.","死体解剖の結果、絞殺と判明しました。","strangled"];
EXAMPLES[6404]=["This maze is very hard to get out of.","この迷路は抜け出すのがとても難しい。","maze"];
EXAMPLES[6405]=["His hands quivered when he began to speak.","しゃべり出した時彼の両手はぶるぶる震えた。","quivered"];
EXAMPLES[6406]=["We must try to conserve our natural resources.","我々は天然の資源を保存するように勤めなければならない。","conserve"];
EXAMPLES[6408]=["I tilt my head. Not the pawn, but the knight?","僕は首をひねる。このポーンではなくて、こっちのナイトを・・・。","tilt"];
EXAMPLES[6409]=["What do you need to make gin and tonic?","ジントニックを作るには何がいるの？","tonic"];
EXAMPLES[6411]=["Justice without mercy is cruelty; mercy without justice is the mother of dissolution.","哀れみのない正義は冷酷である。しかし、正義のない哀れみは解体の母である。","dissolution"];
EXAMPLES[6412]=["I cannot put up with his arrogance.","私は彼の傲慢な態度が我慢できない。","arrogance"];
EXAMPLES[6413]=["The guards rotated in making their rounds every hour.","警備員たちは１時間ごとに輪番で見回った。","rotated"];
EXAMPLES[6415]=["I am still keeping up my tennis craze.","まだテニスに夢中です。","craze"];
EXAMPLES[6416]=["All at once the ship left the pier.","突然船は埠頭を離れた。","pier"];
EXAMPLES[6417]=["We discovered relics of an ancient civilization.","我々は古代文明の遺跡を発見した。","relics"];
EXAMPLES[6420]=["Recently juvenile delinquency has been on the rise.","近ごろ、少年犯罪が増えた。","juvenile"];
EXAMPLES[6422]=["He resolutely pushed forward from the start, overwhelming and pushing out his off-balance opponent.","初めから果敢に前へ出て圧倒し、体勢を崩した相手を押し出した。","resolutely"];
EXAMPLES[6423]=["What with overwork and lack of nourishment, he became very ill.","過労や栄養不足で彼は重病になった。","nourishment"];
EXAMPLES[6424]=["Tom has an organ donor card in his wallet.","トムは財布にドナーカードを入れている。","donor"];
EXAMPLES[6425]=["We only have secondhand information of the coup.","そのクーデターの間接的な情報しか得ていない。","coup"];
EXAMPLES[6427]=["I don't want the investigation to burn out.","捜査を立ち消えにしてほしくない。","burn out"];
EXAMPLES[6428]=["I was never so humiliated in my life.","今までこんなに恥をかかされたことは一度もなかった。","humiliated"];
EXAMPLES[6430]=["The building with the reddish brown roof is a church.","赤茶色の屋根の建物は、教会だよ。","reddish"];
EXAMPLES[6432]=["The Mitsubishi Bank merged with the Bank of Tokyo.","三菱銀行は東京銀行を吸収合併した。","merged"];
EXAMPLES[6433]=["They are shrewd in trade.","彼らは商売に抜け目がない。","shrewd"];
EXAMPLES[6437]=["The Tokyo stock market recorded an unprecedented loss.","東京市場は空前の損失を記録しました。","unprecedented"];
EXAMPLES[6438]=["In the opening paragraphs I query the validity of so-called supply-side economic strategies.","最初のパラグラフでは、いわゆるサプライサイドの経済戦略というものの妥当性について疑問を呈する。","validity"];
EXAMPLES[6439]=["Her behaviour towards me was a departure from the norm.","彼女は私に対する態度がいつもと違っていた。","norm"];
EXAMPLES[6440]=["There are also vendors who support Linux.","リナックスをサポートしているベンダーもいます。","vendors"];
EXAMPLES[6441]=["The enemy can't close in on us so they can't do anything.","敵はこちらに近づけないのでなにもできません。","close in"];
EXAMPLES[6442]=["World Diabetes Day is on the 14th November.","11月14日は世界糖尿病デーです。","Diabetes"];
EXAMPLES[6443]=["As the days passed, our campaign grew in momentum.","日がたつにつれて我々の運動ははずみがついた。","momentum"];
EXAMPLES[6445]=["I was hit by a huge chunk of meat.","巨大な肉の塊が当たった。","chunk"];
EXAMPLES[6447]=["That requires the sanction of the government.","それは政府の認可が必要です。","sanction"];
EXAMPLES[6449]=["I bought a pig in a poke yesterday.","昨日は無分別に買い物をしてしまった。","poke"];
EXAMPLES[6452]=["We have adequate inventories of the product to meet local demand.","地方の需要に応えるのに十分な製品の在庫がある。","inventories"];
EXAMPLES[6453]=["They made huge, grotesque, yet beautiful poles of red cedar.","ベイスギを材料に巨大でグロテスクな、しかし美しい円柱を作った。","grotesque"];
EXAMPLES[6454]=["In their discourse after dinner, they talked about politics.","夕食後の談話で彼らは政治について話し合った。","discourse"];
EXAMPLES[6455]=["A reminder from the library has arrived.","図書館から督促状が届いた。","reminder"];
EXAMPLES[6456]=["Willingness to take responsibility is a sign of maturity.","進んで責任を取るということは成熟の印である。","Willingness"];
EXAMPLES[6457]=["The jury has returned a verdict of guilty.","陪審員は有罪の判決を答申した。","verdict"];
EXAMPLES[6458]=["The avocado is rich in nutrients.","アボカドは栄養豊富です。","nutrients"];
EXAMPLES[6460]=["My brother is a member of the rescue squad.","兄はレスキュー隊のメンバーだ。","squad"];
EXAMPLES[6461]=["He lost his credibility because he betrayed a friend.","彼は友人を裏切って信用を落とした。","credibility"];
EXAMPLES[6462]=["The Bill was eviscerated before being passed by the legislature.","議会を通過しないうちにその法案は骨抜きにされた。","legislature"];
EXAMPLES[6463]=["I asked him to slowly read off the numbers on the meter.","メーターの数字をゆっくりと読んでくれるよう頼んだ。","read off"];
EXAMPLES[6465]=["You could always hand off some of the work to the junior staff.","ある部分は部下にやらせばいいんだよ。","hand off"];
EXAMPLES[6467]=["Sovereignty resides in the people.","主権は人民にある。","Sovereignty"];
EXAMPLES[6469]=["I have a sibling in Algeria.","アルジェリアに兄弟がいるんだ。","sibling"];
EXAMPLES[6470]=["Is there another word for synonym?","「類義語」という意味の言葉は他にありますか？","synonym"];
EXAMPLES[6471]=["He was kind enough to tie my shoelaces.","彼は親切にも私の靴の紐を結んでくれた。","shoelaces"];
EXAMPLES[6472]=["Could you verify that your computer is plugged in?","お客様のパソコンのプラグが電源に差し込まれているか確認してくださいませんか？","verify"];
EXAMPLES[6474]=["Is it true that Tom joined a cult?","トムがカルト集団に入ったって、本当？","cult"];
EXAMPLES[6475]=["He has a remarkable aptitude for music.","彼は音楽の素晴らしい才能をもっている。","aptitude"];
EXAMPLES[6476]=["The miser opened the box to find his money stolen.","そのけちん坊は箱を開けるとお金が盗まれているのに気付いた。","miser"];
EXAMPLES[6477]=["I'm near the on ramp to 25 north.","２５号線北方面の入り口付近にいます。","ramp"];
EXAMPLES[6478]=["Treat the men well and the ore will come.","人間を大切にすれば石が出る。","ore"];
EXAMPLES[6479]=["Put the words in parentheses into abbreviated form.","カッコ内の言葉を短縮形にしなさい。","abbreviated"];
EXAMPLES[6481]=["With which things do you want to swap?","どれとどれを交換する？","swap"];
EXAMPLES[6482]=["If you look from afar, most things will look nice.","遠くから見れば、大抵のものは綺麗に見える。","afar"];
EXAMPLES[6483]=["The human heart is analogous to a pump.","心臓とポンプは似かよっている。","analogous"];
EXAMPLES[6484]=["The teacher allotted the longest chapter to me.","先生は私に一番長い章を割り当てた。","allotted"];
EXAMPLES[6485]=["I dissent from what he said.","私は彼の言ったことに反対する。","dissent"];
EXAMPLES[6489]=["Bob has to get through this ordeal on his own.","ボブは自分の力でこの厳しい試練を乗り切らねばいけない。","ordeal"];
EXAMPLES[6490]=["May 8 is World Red Cross Red Crescent Day.","5月8日は世界赤十字デーです。","Crescent"];
EXAMPLES[6491]=["Why do men behave like apes, and vice versa?","なぜ人間はサルのように、またなぜサルは人間のように振舞うのか。","vice versa"];
EXAMPLES[6494]=["The EC countries are working out a new security pact.","ＥＣ諸国は新たな安全保障条約を検討中です。","pact"];
EXAMPLES[6495]=["I didn't win, but at least I got a consolation prize.","僕は勝ちはしなかったけど、少なくとも残念賞は貰ったよ。","consolation"];
EXAMPLES[6496]=["He was purged of all suspicion.","彼のすべての疑いは晴れた。","purged"];
EXAMPLES[6498]=["He exhibited no remorse for his crime.","彼は自分の罪に対して後悔の気持ちをまったく示さなかった。","remorse"];
EXAMPLES[6499]=["Politicians are cashing in on public apathy.","政治家は国民の無関心に付け込んで利得に走っています。","apathy"];
EXAMPLES[6500]=["The robot was so lifelike that it was creepy.","そのロボットはあまりにも真に迫りすぎて気持ち悪かった。","lifelike"];
EXAMPLES[6501]=["The electrical appliance must have been damaged in transit.","その電気器具は輸送中にこわれたのにちがいない。","transit"];
EXAMPLES[6503]=["Don't you know he is enraged at your insult?","彼が君の侮辱を受けて怒っているのをしらないのか。","enraged"];
EXAMPLES[6504]=["Just stick around a few days and you'll come to love this place.","ちょっと数日ブラブラしたら、この場所が好きになるよ。","stick around"];
EXAMPLES[6510]=["Rie has erroneous ideas.","理恵は間違った考えを持っている。","erroneous"];
EXAMPLES[6515]=["You must bind yourself to keep the promise.","約束を守ることを誓わなければいけない。","bind"];
EXAMPLES[6516]=["It is inconceivable to me that he would do such a thing.","彼がそんなことをするなんて私には考えられない。","inconceivable"];
EXAMPLES[6519]=["I'll set aside next Sunday for a picnic with my family.","今度の日曜日は家族ピクニックのために空けよう。","set aside"];
EXAMPLES[6522]=["It is quite natural for young people to rebel against their parents.","若者達は本来、親の考えに対して反発するものだ。","rebel against"];
EXAMPLES[6523]=["By love alone is enmity allayed.","忍を行じてのみ、よく怨みを解くことを得る。","enmity"];
EXAMPLES[6524]=["There is a chronic oversupply of rice in Japan.","日本では米が恒常的に供給過剰である。","chronic"];
EXAMPLES[6525]=["The elbow is a joint that connects the forearm and the upper arm.","肘は上腕と前腕をつなぐ関節だ。","forearm"];
EXAMPLES[6527]=["It's tax exempt if it's less than ¥50,000.","５万円未満の場合は、非課税になります。","exempt"];
EXAMPLES[6528]=["Don't let the children monopolize the television.","子供たちにテレビを独占させるな。","monopolize"];
EXAMPLES[6529]=["The torture made him confess to crimes he had not committed.","拷問にかけられて彼は犯していない罪を認めた。","confess to"];
EXAMPLES[6530]=["The weak easily assimilate the opinions of the strong.","弱者の意見は簡単に強者の意見に同化されてしまう。","assimilate"];
EXAMPLES[6532]=["The French style of dress is in vogue now.","今、フランス風のドレスが流行している。","vogue"];
EXAMPLES[6533]=["The dog nipped at me.","その犬は私に噛み付こうとした。","nipped"];
EXAMPLES[6535]=["Sit back down, please.","席にお戻りください。","back down"];
EXAMPLES[6536]=["The room was pervaded with the scent of perfume.","部屋は香水のにおいでぷんぷんしていた。","pervaded"];
EXAMPLES[6537]=["The top engineer put the car through a series of rigorous tests.","トップエンジニアが、その車に一連の厳重な検査を加えた。","rigorous"];
EXAMPLES[6538]=["Have you ever had a blood transfusion?","輸血をしたことはありますか？","transfusion"];
EXAMPLES[6539]=["She studies hygiene as part of her domestic science course.","彼女は家政学の一部として衛生学を学んでいる。","hygiene"];
EXAMPLES[6540]=["Can I hang out here till seven?","７時までここにお邪魔していていいかい？","hang out"];
EXAMPLES[6541]=["He had a duplicate key made from that one.","彼はその鍵で合鍵を作らせた。","duplicate"];
EXAMPLES[6543]=["Tom himself was ecstatic.","トムは有頂天になっていた。","ecstatic"];
EXAMPLES[6545]=["They were erected to commemorate a certain event or to tell an ancestral legend.","ある出来事を記念したり先祖の伝説を伝えるために建てられたものであった。","commemorate"];
EXAMPLES[6547]=["He is reputed the best lawyer in this city.","彼はこの都市でもっともすぐれた弁護士だと考えられている。","reputed"];
EXAMPLES[6548]=["He has the subject at his fingertips.","彼はその問題に精通している。","fingertips"];
EXAMPLES[6549]=["I will become god of the celestial world.","僕は神世界の神になる。","celestial"];
EXAMPLES[6550]=["I have a craving for fresh fruit.","新鮮な果物が食べたいんだ。","craving"];
EXAMPLES[6551]=["We were bogged down in a morass of paperwork.","私たちは書類事務の泥沼に陥っていた。","bogged"];
EXAMPLES[6552]=["He began his lecture with a humorous anecdote.","彼はまずユーモアのある逸話を話して講義を始めた。","anecdote"];
EXAMPLES[6553]=["She is not only beautiful but also amiable.","彼女は美人であるばかりか気立てもいい。","amiable"];
EXAMPLES[6554]=["This soap is infused with natural fragrances.","この石けんには天然香料が入っている。","infused"];
EXAMPLES[6555]=["There is no precedent for such a case.","このような問題の前例はない。","precedent"];
EXAMPLES[6559]=["Spread the table, and contention will cease.","テーブルを広げれば争いはやむ。","contention"];
EXAMPLES[6560]=["I enjoy reading, cuddling by the fireplace and slow dancing.","読書と暖炉の側で抱き合うのとスローダンスが好き。","cuddling"];
EXAMPLES[6561]=["You must take up a regular occupation.","何か決まった仕事につきなさい。","take up"];
EXAMPLES[6563]=["I think I have a lot of plaque build up.","歯垢がずいぶん付いていると思いますが。","plaque"];
EXAMPLES[6564]=["Please tell me how to deal with malicious comments.","陰湿な嫌がらせを受けた場合の対処法について教えてください。","malicious"];
EXAMPLES[6565]=["The Lions had an easy win over the Hawks.","ライオンズはホークスに楽勝した。","win over"];
EXAMPLES[6566]=["There is a metro in Kazan.","カザンに地下鉄がある。","metro"];
EXAMPLES[6567]=["The temperature of the human body hovers around 37°C.","人間の体温は37度付近で上下している。","hovers"];
EXAMPLES[6568]=["He is contemptuous of his boss's narrow mind.","彼の上役は狭量さを軽蔑している。","contemptuous"];
EXAMPLES[6569]=["The Dodgers went on winning with irresistible force.","ドジャースは破竹の勢いで勝ち進んだ。","irresistible"];
EXAMPLES[6570]=["The physicist was aware of the potential danger of nuclear fusion.","その物理学者は核融合の潜在的な危険性に気づいていた。","fusion"];
EXAMPLES[6571]=["My advice is predicated on my experience.","私の忠告は、私の経験に基づいている。","predicated"];
EXAMPLES[6572]=["Eat up the steak and then you can have a candy.","ステーキを全部食べてしまいなさい、そしたらキャンディーを食べていいよ。","Eat up"];
EXAMPLES[6574]=["And thus his attention was distracted from the sight.","そのために彼の注意がその光景からそれた。","distracted"];
EXAMPLES[6575]=["Please cut me some slack this time.","今回だけ大目に見てください。","slack"];
EXAMPLES[6576]=["His extravagance is out of proportion to his wage.","彼のぜいたくぶりは収入と不釣り合いである。","extravagance"];
EXAMPLES[6579]=["Tom pestered his mother for money.","トムはお母さんにお金をねだった。","pestered"];
EXAMPLES[6582]=["He felt the pangs of conscience.","彼は良心のとがめを感じた。","pangs"];
EXAMPLES[6585]=["I need to escape from this decree.","この定めから逃れないといけない。","decree"];
EXAMPLES[6586]=["I wonder which country will be the first to censor Tatoeba.","最初にTatoebaを検閲する国はどこかな。","censor"];
EXAMPLES[6587]=["You can see the colors of the spectrum in a rainbow.","虹の中にスペクトルの色を見る事が出来る。","spectrum"];
EXAMPLES[6590]=["Resolving a differential equation means finding the functions that satisfy it.","微分方程式を解くというのは、それを満足するような関数を見つけ出すということだ。","differential"];
EXAMPLES[6591]=["In any case, you are wrong in your conjecture.","いずれにしてもあなたの推測は間違っている。","conjecture"];
EXAMPLES[6592]=["The lake is notorious for its contamination.","その湖は水質汚染で悪名高い。","contamination"];
EXAMPLES[6597]=["It's simple and intuitive.","簡単でわかりやすいよ。","intuitive"];
EXAMPLES[6598]=["They joined in the temperance movement.","彼らは禁酒運動に参加した。","temperance"];
EXAMPLES[6599]=["The project was aborted.","その計画は取りやめになった。","aborted"];
EXAMPLES[6601]=["It's warm enough today to bring out a slight sweat.","今日は汗ばむような陽気だ。","bring out"];
EXAMPLES[6604]=["We haven't seen her of late.","最近彼女を見かけない。","haven"];
EXAMPLES[6607]=["The lotus is an aquatic plant with very large leaves and flowers.","蓮は、水生植物でとても大きな葉と花をつけます。","aquatic"];
EXAMPLES[6609]=["That observatory stands in a good location.","その天文台はよい位置にある。","observatory"];
EXAMPLES[6610]=["No city in Europe is as populous as Tokyo.","ヨーロッパのどの都市も、東京ほど人口が多くはない。","populous"];
EXAMPLES[6611]=["The airplane is capable of supersonic speeds.","その飛行機は超音速で飛べる。","supersonic"];
EXAMPLES[6613]=["I'll keep your problems in mind.","君の問題は心にとめておくよ。","in mind"];
EXAMPLES[6614]=["He keeps a small poultry yard.","彼は小さな鶏舎を持っている。","poultry"];
EXAMPLES[6615]=["It is hard, perhaps even impossible, to define normal sensory perception.","正常な感覚的知識を定義するのは困難であるし、おそらく、不可能でさえあるだろう。","sensory"];
EXAMPLES[6616]=["Those guys are ruthless, covering up their tracks like that after all their wrongdoing.","自分たちの悪事がばれないようにするなんて、なんて悪どい奴等！","ruthless"];
EXAMPLES[6617]=["His sudden illness deterred us from traveling.","彼の急病で旅行は取りやめになった。","deterred"];
EXAMPLES[6619]=["He seems cheery but, on the contrary, he is sad.","彼は陽気そうに見えるが、本当はそれに反して悲しんでいるのだ。","cheery"];
EXAMPLES[6620]=["Don't cut in line.","割り込んではいけません。","cut in"];
EXAMPLES[6621]=["Vocational schools were set up one after another.","職業専門学校が次々創設された。","Vocational"];
EXAMPLES[6622]=["His voice was heard above the din.","彼の声が騒音にも負けずに聞こえた。","din"];
EXAMPLES[6624]=["The letter sounds forced, what is worse, insincere.","その手紙には強制的なひびきがあるし、さらに悪いことには、思いやりがない。","insincere"];
EXAMPLES[6625]=["Pass on, please, and do not obstruct the way.","どうか先に進んで道をふさがないで下さい。","obstruct"];
EXAMPLES[6626]=["I have gone astray somewhere in my calculations.","ぼくは計算のどこかで間違ってしまった。","astray"];
EXAMPLES[6627]=["I think I have to go back on a diet after Christmas.","クリスマスが終わったらまたダイエットをしなくてはならないみたい。","go back on"];
EXAMPLES[6628]=["The obsolete regime is about to collapse.","時代遅れのその政権は崩壊寸前だ。","obsolete"];
EXAMPLES[6629]=["A police car chases after the criminal with its siren wailing.","パトカーが犯人の車をけたたましいサイレンを鳴らしながら追跡する。","wailing"];
EXAMPLES[6630]=["As is often the case with teenagers, she's conceited.","１３歳から１９歳の少年少女によくあることだが彼女はうぬぼれている。","conceited"];
EXAMPLES[6631]=["Relations between us seem to be on the ebb.","我々の関係は徐々に冷えていくようだ。","ebb"];
EXAMPLES[6632]=["Their morale is high.","彼らはやる気がある。","morale"];
EXAMPLES[6633]=["Grandmother died, leaving the whole family stunned.","おばあちゃんが突然死んで家族一同驚いた。","stunned"];
EXAMPLES[6634]=["I transcribed the original mimeographed edition into LATEX.","ガリ版刷りの原書をLATEXで清書した。","transcribed"];
EXAMPLES[6637]=["What do you infer from her strange behavior?","彼女の異常なふるまいから何を推測しますか。","infer"];
EXAMPLES[6639]=["This criminal is a victim of his heredity.","この犯罪者は遺伝の犠牲者だ。","heredity"];
EXAMPLES[6640]=["In primitive societies barter was used.","原始社会では、物々交換が行われた。","barter"];
EXAMPLES[6641]=["The old man stands aloof from this world.","その老人は俗世界から超然としている。","aloof"];
EXAMPLES[6642]=["He has given us indecent wages.","彼はわたしらに少ない賃金しかくれなかった。","indecent"];
EXAMPLES[6644]=["We could hear footsteps crunching through the gravel.","私たちには砂利を踏みしめる足音が聞こえた。","gravel"];
EXAMPLES[6647]=["He always makes cynical remarks to me.","彼はいつも私に皮肉を言う。","cynical"];
EXAMPLES[6648]=["See the footnote on page 5.","５ページ脚注を参照してください。","footnote"];
EXAMPLES[6649]=["All of the rules must be in line with company policy.","規則は全て会社の方針と一致していなければならない。","in line with"];
EXAMPLES[6650]=["It is outrageous that you should spend so much money.","君がそんなにお金を使うとはあきれるばかりだ。","outrageous"];
EXAMPLES[6651]=["Chance is a nickname for Providence.","機会とは神意を表す一つのあだ名である。","Providence"];
EXAMPLES[6652]=["His statement sounds correct at first, but upon thinking carefully, you realize it's contradictory.","彼の発言一見正しいように聞こえるが、よく考えると矛盾していることに気づく。","contradictory"];
EXAMPLES[6653]=["Your behavior is in conflict with your principles.","君の行動は君の信条と矛盾している。","conflict with"];
EXAMPLES[6654]=["She had escaped detection somehow.","彼女はどうにか見つけ出されずにすんだ。","detection"];
EXAMPLES[6655]=["He was hospitalized for a surgical operation.","彼は外科手術の為入院した。","surgical"];
EXAMPLES[6656]=["I'm afraid I have an inflammation in my eyes.","目が炎症を起こしているようですが。","inflammation"];
EXAMPLES[6658]=["There is no odor so bad as that which arises from goodness tainted.","善いものでも汚れてしまったものが発する臭いくらい、ひどい悪臭はない。","tainted"];
EXAMPLES[6659]=["He was assertive by nature.","彼は生まれつき積極性に乏しかった。","assertive"];
EXAMPLES[6660]=["He has her on a pedestal.","彼は彼女をあがめたてています。","pedestal"];
EXAMPLES[6662]=["Much legal language is obscure to a layman.","法律用語の大半は素人にはわかりにくい。","layman"];
EXAMPLES[6664]=["New Year shrine visit; which shrines are potent?","初詣、ご利益があるのはどこの神社？","potent"];
EXAMPLES[6665]=["Heavy smoking impaired his health.","彼はたばこの吸いすぎで体を壊した。","impaired"];
EXAMPLES[6666]=["A gust of wind swelled the sails.","一陣の風をうけて帆がふくらんだ。","gust"];
EXAMPLES[6667]=["The radius of Earth is about 6,000 kilometers.","地球の半径は、約6、000キロです。","radius"];
EXAMPLES[6668]=["The Tudor Dynasty fell in the year 1603.","チューダー朝は１６０３年に崩壊した。","Dynasty"];
EXAMPLES[6669]=["Why don't you stop by for a little while?","ちょっと寄ってかない？","stop by"];
EXAMPLES[6670]=["The house was undermined by the flood.","洪水で家の土台が削り取られた。","undermined"];
EXAMPLES[6671]=["It's been overcast for the past few days.","ここ数日空は厚い雲に覆われている。","overcast"];
EXAMPLES[6673]=["It was raining all day long without intermission.","雨は途切れることなく一日中ふりつづいた。","intermission"];
EXAMPLES[6674]=["I don't know what to do about his shoplifting.","彼の万引きはどうしたものかわからない。","shoplifting"];
EXAMPLES[6675]=["Is this the right bus for Pacific Boulevard?","パシフィック通りに行くには、このバスでいいんでしょうか。","Boulevard"];
EXAMPLES[6678]=["Shun will take over my job while I'm away.","私が不在の間は俊が私の仕事を引き継ぎます。","Shun"];
EXAMPLES[6679]=["For all man's sins damned we shall be.","全人類の罪のために俺達は呪われる。","damned"];
EXAMPLES[6680]=["Are you going to pull curfew on me?","外出の時間制限をするつもりですか。","curfew"];
EXAMPLES[6681]=["The whole town was in an uproar.","町中が大騒ぎをしていた。","uproar"];
EXAMPLES[6683]=["Break the eggs and separate the yolk from the whites.","卵を割って、黄身と白身に分けて。","yolk"];
EXAMPLES[6684]=["The Tokaido line terminates at Tokyo.","東海道線は東京が終点だ。","terminates"];
EXAMPLES[6685]=["The present world owes its convenient life to petroleum.","今日の世界が便利な生活ができるのは石油のおかげだ。","petroleum"];
EXAMPLES[6686]=["I was bored with the monotony of daily life.","変化のない毎日の生活に飽きていた。","monotony"];
EXAMPLES[6687]=["He is absorbed in the study of linguistics.","彼は言語学の研究に没頭している。","linguistics"];
EXAMPLES[6688]=["His eyes redeem his face from sternness.","彼の眼が表情のきびしさをやわらげている。","redeem"];
EXAMPLES[6690]=["It is important that you attach your photo to the application form.","君の写真を申込書に添付することを忘れないでね。","application form"];
EXAMPLES[6691]=["The post office is adjacent to the library.","郵便局は図書館の隣にある。","adjacent"];
EXAMPLES[6692]=["He's biased against Christianity.","彼はキリスト教に偏見を抱いている。","biased against"];
EXAMPLES[6693]=["I guess she's into bondage and domination.","彼女のフェチが緊縛と支配でしょう。","bondage"];
EXAMPLES[6698]=["No matter what it is, we must persevere.","何事であろうとも、忍耐しなくてはならない。","persevere"];
EXAMPLES[6699]=["This is the best amplifier on the market.","これは今売っている中で最高のアンプです。","amplifier"];
EXAMPLES[6701]=["Lately that student has been disruptive in class. Honestly it's beginning to worry me.","その子最近授業中遊び倒しているので、正直今後が心配。","disruptive"];
EXAMPLES[6702]=["I impeached his motives.","私は彼の動機を疑った。","impeached"];
EXAMPLES[6703]=["Poetry is a search for the inexplicable.","詩は説明し難いものへの探索である。","inexplicable"];
EXAMPLES[6705]=["He went as far as to call you a hypocrite.","彼は君のことを偽善者とまで言った。","hypocrite"];
EXAMPLES[6706]=["We had a terrible time in the blizzard.","吹雪でえらい目に遭った。","blizzard"];
EXAMPLES[6708]=["The will was declared void by the court.","その遺言は法廷で無効と宣告された。","void"];
EXAMPLES[6709]=["The workers do not have a fatherland.","労働者は祖国をもたない。","fatherland"];
EXAMPLES[6712]=["Does depreciation of the yen give rise to inflation?","円安は物価高のもとになりますか。","give rise to"];
EXAMPLES[6713]=["I see a surge in loan growth.","ローンがふくらみそうな気配を見せていますね。","surge"];
EXAMPLES[6715]=["The scandal was an obstacle to his promotion.","そのスキャンダルは彼の出世の障害だった。","obstacle to"];
EXAMPLES[6716]=["Near where I live is a reservoir.","住んでるところの近くにため池があるんだ。","reservoir"];
EXAMPLES[6718]=["We must evacuate the people in the hall!","広間の人を避難させる必要があります！","evacuate"];
EXAMPLES[6719]=["A trickle of blood ran down his neck.","彼の首筋を血がすっと伝った。","trickle"];
EXAMPLES[6720]=["I've forgotten. Was House Lancaster's family crest a red rose, or a white rose?","ランカスター家の紋章が赤バラだったか、白バラだったか忘れてしまった。","crest"];
EXAMPLES[6721]=["We can conclude that this phenomenon is not related to either pollutant.","この現象は、いずれの汚染物質とも無関係であると結論づけることができる。","pollutant"];
EXAMPLES[6723]=["Please sum up your idea.","君の考えを要約して下さい。","sum up"];
EXAMPLES[6725]=["The garden is fragrant with the smell of roses.","庭には薔薇の花が香っている。","fragrant"];
EXAMPLES[6726]=["Are you familiar with the periodic table of chemical elements?","元素周期表に詳しかったりする？","periodic"];
EXAMPLES[6727]=["Attached is the tentative agenda.","仮の議事内容を送付しました。","tentative"];
EXAMPLES[6728]=["The crimson flowers will bloom in January.","その紅の花は一月に咲きます。","crimson"];
EXAMPLES[6729]=["The butler announced Mr. and Mrs. Smith.","使用人がしらは声を上げて「スミスご夫妻がおいでになりました」と告げた。","butler"];
EXAMPLES[6732]=["Sound absorbing material is called acoustic material.","音を吸収する素材のことを吸音材といいます。","acoustic"];
EXAMPLES[6733]=["I like lighthearted works of art.","ゆるい雰囲気の作品が好きです。","lighthearted"];
EXAMPLES[6734]=["Finally, the discord between them came to an end.","ついに両者の間の不和は終わりになった。","discord"];
EXAMPLES[6735]=["The problem has come to the fore again.","その問題が再燃した。","fore"];
EXAMPLES[6736]=["People thronged the theater to see the star.","人々はそのスターを見ようと劇場に群がった。","thronged"];
EXAMPLES[6737]=["The chauffeur will be on duty after 3 o'clock.","運転手は３時から職務につきます。","chauffeur"];
EXAMPLES[6739]=["Tom is psychic, but Mary isn't.","トムは超能力者なんだけど、メアリーは違うよ。","psychic"];
EXAMPLES[6740]=["Bids were solicited for the building of the bridge.","橋の建設の入札が募られた。","solicited"];
EXAMPLES[6743]=["It was really painstaking work.","本当に骨の折れる仕事だった。","painstaking"];
EXAMPLES[6744]=["No, for me, lukewarm milk.","ううん。僕のは、ぬるめの牛乳にして。","lukewarm"];
EXAMPLES[6745]=["My technique is without flaw.","わたしのテクに抜かりはないわ。","flaw"];
EXAMPLES[6746]=["I'm putting my ass in a sling for you.","馬鹿を承知で一肌脱ぎましょう。","sling"];
EXAMPLES[6747]=["He has no legitimacy.","彼にはまったく正当性がない。","legitimacy"];
EXAMPLES[6748]=["Let me go over the accounts again.","もう一度、その計算をやり直させてください。","go over"];
EXAMPLES[6749]=["I can't understand how your father managed to see through that man.","どうして君のお父さんはあの男の正体を見抜いたのかわからない。","see through"];
EXAMPLES[6752]=["These paintings will be left here for posterity.","これらの絵は後世の人々のためにここに残される。","posterity"];
EXAMPLES[6753]=["Corporate political donations are coming under heavy scrutiny.","企業の政治献金は厳しい検査の対象になっています。","scrutiny"];
EXAMPLES[6754]=["Your payment is now two months overdue.","お支払いが２ヶ月遅れています。","overdue"];
EXAMPLES[6755]=["A great light was diffused over the baseball stadium.","凄い明かりが野球場にあたっていた。","diffused"];
EXAMPLES[6756]=["It seems to me that the weather will deteriorate.","天気が崩れそうだね。","deteriorate"];
EXAMPLES[6759]=["He renounced the ownership of the land.","彼はその土地の所有権を放棄した。","renounced"];
EXAMPLES[6761]=["You arrived at the moment I left.","あなたは私が出発してから到着した。","at the moment"];
EXAMPLES[6762]=["He took a slide down the hill on his sled.","彼はそりで丘を滑り降りた。","sled"];
EXAMPLES[6763]=["In the end, entice someone with food to win.","結局、胃袋を掴んだもの勝ちだよね。","entice"];
EXAMPLES[6765]=["It will surely by useful for your future to put forth this much effort.","これだけ努力することは将来必ず役立つはずです。","put forth"];
EXAMPLES[6766]=["The ship was wrecked on a sunken reef.","船は暗礁に乗り上げて難破した。","sunken"];
EXAMPLES[6767]=["There is big oversight in that plan.","その計画には大きな見落としがある。","oversight"];
EXAMPLES[6768]=["The typhoon caused immeasurable damage.","台風は計りきれないほどの損害をもたらした。","immeasurable"];
EXAMPLES[6772]=["I'm going to sign up for a German class right now.","すぐにドイツ語のクラスに登録する。","sign up"];
EXAMPLES[6773]=["The show was an electrifying hit.","そのショーは電撃的ヒットだった。","electrifying"];
EXAMPLES[6774]=["An eclipse of the sun is a rare appearance.","日食はまれにしか起こらない。","eclipse"];
EXAMPLES[6776]=["This dictionary is great boon up to us.","この辞書は私たちにとってありがたいものだ。","boon"];
EXAMPLES[6777]=["I like lyric better than epic.","私は叙事詩よりも叙情詩の方が好きだ。","epic"];
EXAMPLES[6778]=["Many a true word is spoken in jest.","嘘から出た誠。","jest"];
EXAMPLES[6779]=["Can you read phonetic signs?","発音記号が読めますか？","phonetic"];
EXAMPLES[6780]=["My upper right wisdom tooth hurts.","右上の親知らずが痛みます。","wisdom tooth"];
EXAMPLES[6782]=["The rain beats against the window pane.","雨は窓ガラスを叩く。","pane"];
EXAMPLES[6783]=["My muscular strength has weakened from lack of exercise.","運動不足で筋肉が弱くなった。","muscular"];
EXAMPLES[6784]=["There's a slight possibility of a recurrence.","再発の可能性が少しあります。","recurrence"];
EXAMPLES[6785]=["He is more skeptical than I am.","あいつ俺より疑い深いからな。","skeptical"];
EXAMPLES[6786]=["He is frugal, to say the least of it.","彼は控え目に言っても倹約家だ。","frugal"];
EXAMPLES[6787]=["When I first got to New York, I was in a daze.","初めてニューヨークに着いたときは、全く西も東も分からなかった。","daze"];
EXAMPLES[6788]=["It is not mine to foretell the future.","将来を予見するのは私の責任ではない。","foretell"];
EXAMPLES[6789]=["The emigrants have endured physical and mental pain.","移民達は肉体的、精神的苦痛に耐えてきた。","emigrants"];
EXAMPLES[6791]=["Don't be so cheeky.","生意気を言うんじゃない。","cheeky"];
EXAMPLES[6792]=["At first I thought it was a prank.","最初、いたずらかと思った。","prank"];
EXAMPLES[6793]=["He has a fabulous reputation for his high integrity.","彼は高潔なことで非常に評判が高い。","fabulous"];
EXAMPLES[6794]=["The buses in Montgomery were segregated.","モントゴメリーのバスは人種隔離が行われていた。","segregated"];
EXAMPLES[6795]=["This restaurant is famous for its excellent cuisine.","このレストランは料理がおいしいので有名だ。","cuisine"];
EXAMPLES[6800]=["Can a body, hand, or finger enter the safety partition?","安全用パーテーションに体・手・指が入れるか？","partition"];
EXAMPLES[6801]=["He also brought out one more dubious conclusion.","そしてもう一つは疑わしい結論を出した。","dubious"];
EXAMPLES[6802]=["He watches for an opportunity to intrigue against his rival.","彼は競争相手を落とし入れようと虎視眈々としている。","intrigue"];
EXAMPLES[6803]=["He knows how to captivate his audience.","彼はこの聴衆をどう魅了するか知っている。","captivate"];
EXAMPLES[6805]=["The volcano may erupt at any moment.","その火山はいつなんどき爆発するかもしれない。","erupt"];
EXAMPLES[6806]=["Young people are prone to fall into temptation.","若い人たちは誘惑に陥りやすい。","prone"];
EXAMPLES[6807]=["Level off the sugar when measuring out.","計量する前にすりきりしなさい。","Level off"];
EXAMPLES[6809]=["It won't do you any good to talk up your own work like that.","自分の作品を自画自賛してどうするの。","talk up"];
EXAMPLES[6810]=["The construction of a highway will contribute to the growth of the suburbs.","幹線道路の建設は郊外の発展に寄与するだろう。","contribute to"];
EXAMPLES[6812]=["No one can avert death.","人間は誰しも死を避けられない。","avert"];
EXAMPLES[6813]=["What makes life dreary is the want of motivation.","人生を退屈にするのは動機の欠如である。","dreary"];
EXAMPLES[6814]=["Our journey by camel was quite an experience.","ラクダの旅は全く素晴らしい体験だった。","camel"];
EXAMPLES[6815]=["However the fact is that the cigarettes and tobacco stink.","タバコ臭いんですけど。","stink"];
EXAMPLES[6817]=["We all thought she was devoid of sense.","彼女には分別がない、と私達はみんな思った。","devoid"];
EXAMPLES[6818]=["They had been thumping the drum all along.","彼らは太鼓をずっとたたき続けた。","thumping"];
EXAMPLES[6819]=["A parrot can mimic a person's voice.","オウムは人の声を真似ることができる。","mimic"];
EXAMPLES[6821]=["It was difficult to live on his meager earnings.","彼のわずかな稼ぎで暮らしていくのは困難だった。","meager"];
EXAMPLES[6823]=["Down came the rain in torrents.","雨が滝のように降ってきた。","torrents"];
EXAMPLES[6824]=["The merger created the largest bank in Japan.","合併の結果、日本で第一位の銀行が誕生した。","merger"];
EXAMPLES[6827]=["He took it for an implied rebuke.","彼はそれを叱責の意味にとった。","rebuke"];
EXAMPLES[6830]=["He leads a hectic life.","彼は慌ただしい毎日を送っています。","hectic"];
EXAMPLES[6831]=["Last night I began to nod off in front of the TV.","昨夜、私はテレビの前で居眠りをしてしまった。","nod off"];
EXAMPLES[6832]=["White was denounced to the police as a spy.","ホワイトはスパイだとして警察に告発された。","denounced"];
EXAMPLES[6833]=["My act incurred a blame.","僕の行動は非難を招いた。","incurred"];
EXAMPLES[6836]=["It was only supposed to be an interim solution.","それはただの臨時の解決策だった。","interim"];
EXAMPLES[6837]=["The Van Horn family was affluent.","ヴァンホーン家は裕福だった。","affluent"];
EXAMPLES[6839]=["It's time to hit the books.","さあ、そろそろ本気で勉強を始めなくちゃ。","hit the books"];
EXAMPLES[6840]=["He delayed payment on some pretext or other.","彼は、なんだかんだ言って支払いを延期した。","pretext"];
EXAMPLES[6841]=["She was idly looking out of the window.","彼女はぼんやりと窓の外を眺めていた。","idly"];
EXAMPLES[6842]=["Short pleasure, long repentance.","喜びは短く、後悔は長し。","repentance"];
EXAMPLES[6844]=["I wonder who this bizarre law is for.","こんな変な法律誰のためにあるんだろう。","bizarre"];
EXAMPLES[6845]=["That job gave him little gratification.","その仕事をしても彼はほとんど満足感が得られなかった。","gratification"];
EXAMPLES[6846]=["There was a class reunion after 30 years.","３０年ぶりにクラス会があった。","reunion"];
EXAMPLES[6847]=["The infant has been exposed to radioactive rays.","その幼児は放射線にさらされていた。","radioactive"];
EXAMPLES[6848]=["A buffalo is akin to an ox.","水牛は牛に似ている。","akin"];
EXAMPLES[6849]=["They subjugate the meek.","奴らは弱者を服従させて喜んでいるが。","meek"];
EXAMPLES[6850]=["I was bought a new water purifier.","新しい整水器、買ってもらったんだ。","purifier"];
EXAMPLES[6851]=["Research in Motion announced the layoff of 2000 employees and a restructuring of the company.","リサーチ・イン・モーションが約２千人の従業員解雇と組織再編を発表した。","layoff"];
EXAMPLES[6853]=["Slapped in the face, I didn't fight back.","顔に平手打ちされたけれども、私は抵抗しなかった。","fight back"];
EXAMPLES[6854]=["For a start, he was the illegitimate son of an unmarried mother.","まず彼は未婚の母から生まれた私生児である。","illegitimate"];
EXAMPLES[6855]=["Success depends on your own exertions.","成功はあなた自身の努力しだいである。","exertions"];
EXAMPLES[6857]=["The town was exactly the same as before.","町は昔のままだった。","as before"];
EXAMPLES[6859]=["His remarks added up to a condemnation of my plan.","彼の意見は結局私の計画はだめだという非難であった。","condemnation"];
EXAMPLES[6860]=["One step further, and you will fall into an abyss.","一歩誤るとせんじんの谷だ。","fall into"];
EXAMPLES[6861]=["It was his lengthy narrative that bored me to death.","私を死ぬほど退屈させたのは、彼の長ったらしい話だった。","lengthy"];
EXAMPLES[6862]=["Stop spending money on frivolous things.","くだらないことにお金を使うのはやめろ。","frivolous"];
EXAMPLES[6864]=["Mr Sato was standing on top of a boulder.","里さんは岩の上に立っていました。","boulder"];
EXAMPLES[6865]=["Each sequel of this game contains fewer and fewer characters.","このゲーム、続編が出るたびにキャラが減ってるな。","sequel"];
EXAMPLES[6866]=["They sent agents to agitate the local people.","土地の人々を扇動するためにスパイを送り込んだ。","agitate"];
EXAMPLES[6867]=["I thought you'd jump at the chance.","喜んでとびつくかと思ったけど。","jump at"];
EXAMPLES[6868]=["Show me tangible data.","具体的なデータを示しなさい。","tangible"];
EXAMPLES[6869]=["We won't be able to evade punishment this time.","今度は罰をまぬがれまい。","evade"];
EXAMPLES[6871]=["I tried in vain to seduce her.","彼女を誘惑しようとしたがむだだった。","seduce"];
EXAMPLES[6872]=["Man is born a sinner.","人間は生来罪人である。","sinner"];
EXAMPLES[6873]=["The general ordered the massacre of all war prisoners.","将軍は捕虜全員の虐殺を命じた。","massacre"];
EXAMPLES[6874]=["My mind was in a haze after drinking so much.","私は飲みすぎて頭がもうろうとしていた。","haze"];
EXAMPLES[6875]=["A woman is the woe of man.","女は男の災いである。","woe"];
EXAMPLES[6876]=["We all pondered over what had taken place.","我々は皆、起こったことについて深く考えた。","pondered"];
EXAMPLES[6878]=["It would be illogical.","筋が通ってないだろう。","illogical"];
EXAMPLES[6879]=["Her face was radiant with happiness.","彼女の顔は幸せで輝いていた。","radiant"];
EXAMPLES[6880]=["Linguistic competence is inborn, not acquired.","言語能力は後天的ではなく、生まれつきです。","inborn"];
EXAMPLES[6881]=["I took a doze after coming home.","私は家に帰ってからうたた寝した。","doze"];
EXAMPLES[6883]=["What is the altitude of the plateau?","その台地は標高どのくらいですか。","plateau"];
EXAMPLES[6884]=["My boss detained me more than 30 minutes.","上司は、私を３０分以上も引き留めた。","detained"];
EXAMPLES[6886]=["I was involved in a petty argument.","私はくだらない議論に巻き込まれた。","petty"];
EXAMPLES[6887]=["He is a sage.","彼は賢者だ。","sage"];
EXAMPLES[6888]=["I promise not to peek.","のぞき見しないって約束するよ。","peek"];
EXAMPLES[6889]=["I've become impotent.","不能になりました。","impotent"];
EXAMPLES[6890]=["We have to somehow come through this troublesome situation.","我々はこの難局を何とかして切り抜けなければならない。","come through"];
EXAMPLES[6891]=["Tom listened to some sad music while watching the rain fall through the window.","トムは雨が落ちるのを窓越しに眺めながら、切ない曲を聴いた。","fall through"];
EXAMPLES[6892]=["Myanmar is ruled by a military dictatorship.","ミャンマーは軍事独裁政権に支配されている。","dictatorship"];
EXAMPLES[6893]=["He was confounded at the sight of the teacher.","先生の姿を見て彼は仰天してしまった。","confounded"];
EXAMPLES[6894]=["The country was in a state of anarchy at that time.","その国は当時無政府状態だった。","anarchy"];
EXAMPLES[6895]=["Don't put your head out of the window.","窓から顔を出すな。","head out"];
EXAMPLES[6897]=["Tom was chewing on a toothpick.","トムは爪楊枝をくわえていた。","toothpick"];
EXAMPLES[6898]=["The road was blocked by an avalanche.","雪崩で道路がふさがった。","avalanche"];
EXAMPLES[6900]=["Canals have been built to irrigate the desert.","砂漠に水を引くために運河が建設されている。","irrigate"];
EXAMPLES[6901]=["It is very imprudent to swim in the rapids.","この急流で泳ぐのはとても無謀なことだ。","imprudent"];
EXAMPLES[6906]=["To do him justice, he is a discreet man.","公平に評価すれば、彼は慎重な人だ。","discreet"];
EXAMPLES[6907]=["Nothing is as great as maternal love.","母の愛ほど偉大なものはない。","maternal"];
EXAMPLES[6909]=["We know how to get around traffic congestion.","私たちは交通渋滞をうまく避ける方法を知っている。","congestion"];
EXAMPLES[6910]=["The milk was diluted with water.","牛乳には水が混ぜてあった。","diluted"];
EXAMPLES[6911]=["The building crumbled to pieces three years ago.","その建物は三年前に崩壊した。","crumbled"];
EXAMPLES[6915]=["Her skating performance was a regular feat.","彼女のスケート演技は全くの離れ技であった。","feat"];
EXAMPLES[6917]=["Carbon dioxide is not a poison in itself.","二酸化炭素はそれ自体は毒ではない。","dioxide"];
EXAMPLES[6918]=["I'm glad we didn't go there because there were some localized heavy rain showers.","局地的な大雨だったらしいけど、行かなくて正解だったよ。","localized"];
EXAMPLES[6919]=["He deposited 100 dollars in his saving account.","彼は口座に１００ドル預けた。","saving account"];
EXAMPLES[6921]=["I just bet you were thinking something perverse just now.","今の、ゼッタイなんか邪なこと考えてたでしょ。","perverse"];
EXAMPLES[6922]=["Be careful not to tip over that box.","その箱をひっくりかえさないように注意してくれ。","tip over"];
EXAMPLES[6923]=["Last time it was a natural childbirth.","先回は自然分娩でした。","childbirth"];
EXAMPLES[6924]=["Toil and worry caused his health to break down.","労苦と心配で彼の健康はそこなわれることになった。","break down"];
EXAMPLES[6926]=["My stepfather treats me better than my real father did.","継父は、実父より良くしてくれます。","stepfather"];
EXAMPLES[6929]=["He made a premature decision on the matter.","彼はその件について早まった決定をした。","premature"];
EXAMPLES[6930]=["The policeman beckoned to me with his forefinger.","警官は人差し指で僕を招いた。","forefinger"];
EXAMPLES[6931]=["We use only the best brand of wine.","私たちはワインは最優良品のみ使っている。","brand"];
EXAMPLES[6932]=["In Greek mythology, Ares was the god of war.","ギリシャ神話では、アレスは戦争の神でした。","mythology"];
EXAMPLES[6934]=["Skip the pleasantries and get down to business.","挨拶抜きでいきなり用件を切り出す。","get down to"];
EXAMPLES[6935]=["Tom's kidneys and liver are in bad shape.","トムは腎臓と肝臓が悪い。","kidneys"];
EXAMPLES[6937]=["Tom has no interest whatsoever in being fashionably dressed.","トムはおしゃれに全く関心がない。","whatsoever"];
EXAMPLES[6938]=["Come along with me and go fishing.","一緒に釣りに行こう。","Come along"];
EXAMPLES[6939]=["Slow economic recovery has sent auto sales plummeting.","経済回復の遅れは自動車の売り上げを急落させました。","plummeting"];
EXAMPLES[6941]=["The city is notorious for its polluted air.","その都市は大気汚染がひどいことで有名だ。","notorious"];
EXAMPLES[6942]=["How long have you been alienated from your family?","君はいつから家族と疎遠になっているのか。","alienated"];
EXAMPLES[6944]=["You must put an end to your foolish behavior.","君はばかげた行為をやめなければいけない。","put an end to"];
EXAMPLES[6945]=["They made a great tumult last night.","彼らは昨夜大騒ぎをした。","tumult"];
EXAMPLES[6946]=["Play out of doors on a fine day.","天気の良い日には外で遊びなさい。","Play out"];
EXAMPLES[6948]=["Will you help me pack up my suitcase?","私がスーツケースに荷物を詰めるのを手伝ってくれませんか。","pack up"];
EXAMPLES[6950]=["Let's stop wasting time and get on with this work.","時間をむだにしないで、この仕事を進めよう。","get on with"];
EXAMPLES[6951]=["To become popular, you need to be mediocre.","人気者になるためには、凡庸でなくてはならない。","mediocre"];
EXAMPLES[6952]=["She has international renown as a painter.","彼女は国際的に著名な画家です。","renown"];
EXAMPLES[6954]=["I would love to be able to read French effortlessly.","フランス語すらすら読めるようになりたいなあ。","effortlessly"];
EXAMPLES[6955]=["It isn't futile to go to university.","大学へ行くことは無駄ではない。","futile"];
EXAMPLES[6956]=["But Jesus would not entrust himself to them.","しかし、イエスは、御自身を彼らにお任せにならなかった。","entrust"];
EXAMPLES[6957]=["A big man is not always robust.","大男が必ずしも頑強だとは限らない。","robust"];
EXAMPLES[6958]=["If you do that again, I'll spank you.","次やったら、お尻ペンペンしますよ。","spank"];
EXAMPLES[6960]=["The fingerprints on the knife attest to her guilt.","ナイフの指紋が彼女の有罪の証拠である。","attest"];
EXAMPLES[6961]=["The dew evaporated when the sun rose.","露は太陽が昇ると蒸発した。","evaporated"];
EXAMPLES[6962]=["Man, I hate the sound of glass squeaking!","ああ、そのガラスがキュッキュッとなる音、大嫌い！","squeaking"];
EXAMPLES[6964]=["Do you think his silence denotes guilt?","彼が黙っているのは罪を犯している事を意味していると思いますか。","denotes"];
EXAMPLES[6965]=["It will aggravate the wound.","そうするとよけい傷をとがめるよ。","aggravate"];
EXAMPLES[6966]=["Isn't that the most humane punishment for criminals?","それは罪人に対する最も人道的な刑罰ではないか。","humane"];
EXAMPLES[6967]=["When it came to the crunch she just gave in.","彼女はいよいよとなったら，あっけなく降参した。","crunch"];
EXAMPLES[6969]=["Nick doesn't need to come to my office.","ニックは私の会社に来る必要はない。","Nick"];
EXAMPLES[6971]=["I sometimes apprehend that there will be some difficulty.","困ったことがおきるのではないかと気をもむことがある。","apprehend"];
EXAMPLES[6974]=["We must prevent this type of incident from recurring.","このようなことが二度と起こらないようにしなければならない。","recurring"];
EXAMPLES[6976]=["Why did you decide to affiliate yourself with Company A?","なぜ、Ａ社の傘下に入ることを選んだのか。","affiliate"];
EXAMPLES[6978]=["He is exempt from the military service.","彼は兵役を免除されている。","military service"];
EXAMPLES[6979]=["He often takes a defiant attitude toward us.","彼はしばしば挑戦的態度に出る。","defiant"];
EXAMPLES[6981]=["I hate to improvise.","即興でやるのは苦手だ。","improvise"];
EXAMPLES[6982]=["Mr. Smith ran his sluggish horse along the country roads.","スミスさんは自分のマイペースな馬を田舎道で走らせた。","sluggish"];
EXAMPLES[6983]=["The rice grain has a glossy shine, doesn't it?","お米、つやっつやだね。","glossy"];
EXAMPLES[6984]=["The player was acclaimed by the fans.","その選手はファンに歓呼して迎えられた。","acclaimed"];
EXAMPLES[6986]=["The patient is in a deep coma.","患者は深い昏睡状態にあります。","coma"];
EXAMPLES[6987]=["It was foolish of him to trespass against the law.","その法を犯したとは彼は馬鹿なことをしたものだ。","trespass"];
EXAMPLES[6988]=["The Diet session convened at 2pm.","国会は午後二時に開会されました。","convened"];
EXAMPLES[6991]=["That can diagnose anything, quicker and cheaper than a doctor.","どんな診断も出来て、病院よりも速いし、安いんだぜ。","diagnose"];
EXAMPLES[6993]=["I'm on a paid vacation.","今、有給休暇中なの。","paid vacation"];
EXAMPLES[6994]=["I jumped into the water as in a trance.","私は夢中で水の中に飛び込んだ。","trance"];
EXAMPLES[6995]=["Steel output set a record for two consecutive years.","鉄鋼生産は２年連続して最高を記録した。","consecutive"];
EXAMPLES[6996]=["A devastating earthquake hit the state capital.","破壊的な被害をもたらす規模の地震が州都を襲った。","devastating"];
EXAMPLES[6997]=["The inmate was doing time for a burglary conviction.","囚人は強盗罪により服役していた。","inmate"];
EXAMPLES[6998]=["Corporate governance and accountability are being strengthened.","コーポレートガバナンスや説明責任を強化している。","accountability"];
EXAMPLES[6999]=["Do you know anything about complex carbohydrates?","複雑炭水化物って何か知ってますか。","carbohydrates"];
EXAMPLES[7000]=["The Prime Minister postponed the legislator's punishment.","首相は議員の処分を棚上げにしました。","legislator"];
EXAMPLES[7003]=["I can't understand why you are so critical of him.","なぜあなたは彼にそんなに批判的なのか、私には理解できない。","critical of"];
EXAMPLES[7005]=["There was a flare-up between local residents and state regulators.","地元住民と政府調査官の間に折衝がありました。","regulators"];
EXAMPLES[7006]=["We'd better try to sell or give away all these white elephants we've collected.","せっかく集めたものだけど、邪魔になるばかりだから、売るなり誰かにあげた方がいい。","give away"];
EXAMPLES[7007]=["You have been a great mentor to me.","貴殿には、いろいろ御指導いただきました。","mentor"];
EXAMPLES[7008]=["We should adopt flexible tactics for the moment.","当分の間は柔軟な戦術を取るべきだ。","tactics"];
EXAMPLES[7010]=["The law was enacted in the Meiji era.","その法律は明治時代に制定された。","enacted"];
EXAMPLES[7011]=["Our baby is not yet articulate.","うちの赤ん坊はまだちゃんとしゃべれない。","articulate"];
EXAMPLES[7012]=["Closer examination revealed that the skull had been crushed by some heavy blow.","調べを進めるうちに、頭蓋骨が、何か重い一撃を受けて打ち砕かれているのが明らかになった。","skull"];
EXAMPLES[7014]=["We are building your house in compliance with your wishes.","私達はご希望通りにお宅を建てております。","compliance"];
EXAMPLES[7015]=["The influx of foreign workers has caused a serious housing problem in this area.","外国人労働者の流入が、この地域で深刻な住宅難を引き起こした。","influx"];
EXAMPLES[7017]=["I plan to major in cognitive science in college.","大学では、認知科学を専攻するつもりです。","cognitive"];
EXAMPLES[7020]=["They will figure out the location from the surveillance footage.","監視カメラの映像から位置を割り出す。","surveillance"];
EXAMPLES[7021]=["I have to give a testimony in the courtroom tomorrow.","あした裁判所で証言しなければならない。","courtroom"];
EXAMPLES[7022]=["Tom says that he isn't eligible to vote.","トムは彼には投票権がないと言う。","eligible"];
EXAMPLES[7023]=["My eyes narrowed into slits in the strong sunlight.","私の目は強い日光を浴びて細くなった。","slits"];
EXAMPLES[7026]=["The photograph is a little blurry.","写真、ちょっとボケてるよ。","blurry"];
EXAMPLES[7027]=["I hear that popular group will be disbanded.","あの人気グループが解散するそうだ。","disbanded"];
EXAMPLES[7028]=["He was impeded in his work.","彼は仕事の邪魔をされた。","impeded"];
EXAMPLES[7029]=["Kate's father is in the vicinity of the house.","ケイトのお父さんは家の周辺にいる。","vicinity"];
EXAMPLES[7030]=["That's a squiggle, not legible handwriting.","そのミミズが這ったような字、読み難いんだけど。","legible"];
EXAMPLES[7031]=["She went out of the room with downcast eyes.","彼女は伏し目がちに部屋から出ていった。","downcast"];
EXAMPLES[7032]=["Don't scratch your mosquito bite. It'll get inflamed.","蚊に刺されたところをかいちゃだめだよ。はれちゃうから。","inflamed"];
EXAMPLES[7033]=["You will benefit from a trip abroad.","海外旅行をすれば得るところがありますよ。","benefit from"];
EXAMPLES[7035]=["Several of them are opposed to the Bill.","彼らのうち数人がその法案に反対である。","opposed"];
EXAMPLES[7036]=["The situation, I am sure, will be improved.","きっと事態は改善されるであろうと思います。","improved"];
EXAMPLES[7037]=["There's a bird atop that tree.","あそこの木の上に鳥がいます。","atop"];
EXAMPLES[7038]=["How did you sprain your ankle?","どうやって足首を捻挫したの？","sprain"];
EXAMPLES[7039]=["You do that routinely on Monday, don't you?","月曜日の日課なんだよね？","routinely"];
EXAMPLES[7042]=["Only Japan has an older demographic than Italy among advanced countries.","先進国の中では日本だけがイタリアよりも高齢者の人口比率が高い。","demographic"];
EXAMPLES[7043]=["The country is isolated economically and politically.","その国は経済的にも政治的にも孤立している。","politically"];
EXAMPLES[7045]=["The rash is, um, also incredibly contagious.","湿疹も伝染性だって。","incredibly"];
EXAMPLES[7047]=["Whether he has the operation depends upon the availability of the organ.","彼が手術するかどうかは、移植する臓器の提供次第だ。","availability"];
EXAMPLES[7049]=["All he has going for him is his reliability.","誠実さだけが彼の取り柄だね。","reliability"];
EXAMPLES[7050]=["This building is extremely innovative.","この建物、すごく斬新的ね。","innovative"];
EXAMPLES[7052]=["Ironically it is war that has brought a great many useful inventions into being.","皮肉なことに戦争が数多くの有用な発明を生み出した。","Ironically"];
EXAMPLES[7053]=["The pain will wear off.","痛みはだんだん無くなっていくだろう。","wear off"];
EXAMPLES[7054]=["A loophole in the law allowed him to escape prosecution.","法律に抜け穴があるために彼は起訴を逃れることができた。","loophole"];
EXAMPLES[7055]=["I'm worried she'll dehydrate.","脱水症状を起こすのではないかと心配です。","dehydrate"];
EXAMPLES[7056]=["Some lectures are not wholesome for children.","子供のためにならない説教もある。","wholesome"];
EXAMPLES[7057]=["The doctor advised him to abstain from drinking.","医者は彼に酒を止めるように忠告した。","abstain"];
EXAMPLES[7060]=["We must tear down this house.","私たちはこの家を壊さないといけない。","tear down"];
EXAMPLES[7061]=["I really hate people that tease newcomers.","私、新人いじめする人が大っ嫌いなのよ。","tease"];
EXAMPLES[7063]=["Is nicotine as addictive as heroin?","ニコチンはヘロインと同様に中毒性があるのですか？","addictive"];
EXAMPLES[7064]=["She will start her maternity leave next week.","彼女は来週から産休に入る。","maternity"];
EXAMPLES[7065]=["The eerie silence struck terror into their hearts.","無気味な静けさが彼らの心胆を寒からしめた。","eerie"];
EXAMPLES[7066]=["There will be chaos unless we all adhere to the rules.","みんなが規則に忠実でないと無秩序になる。","adhere to"];
EXAMPLES[7068]=["Tom instigated the whole thing.","トムがすべてを扇動した。","instigated"];
EXAMPLES[7069]=["He is not eager to unveil his main argument.","彼は主たる論点を明らかにすることに気乗り薄である。","unveil"];
EXAMPLES[7070]=["Thank you for your referral.","紹介ありがとう。","referral"];
EXAMPLES[7071]=["He makes no friend who never made a foe.","敵を持ったことのないものには友はできない。","foe"];
EXAMPLES[7072]=["The sales plan allows of no alteration.","販売計画は変更の余地が無い。","alteration"];
EXAMPLES[7073]=["People love to inspect each other's houses.","人は互いの家を詳しく調べるのが大好きだ。","inspect"];
EXAMPLES[7075]=["This magnifying glass magnifies objects by 200 times.","この虫めがねが物を２００倍に拡大します。","magnifying"];
EXAMPLES[7076]=["The fighter toughened up for the bout.","ボクサーは試合を前にして体を鍛えていた。","bout"];
EXAMPLES[7077]=["He was careful not to disrupt the meeting.","彼は会議を混乱させないように気をつけた。","disrupt"];
EXAMPLES[7078]=["We must maintain the amicable relations between Japan and the U.S.","我々は日米間の友好関係を維持しなければならない。","amicable"];
EXAMPLES[7079]=["Professor Sprout acclimated the plant to a new environment.","スポロアウト先生が植物を新しい風土に馴染ませた。","Sprout"];
EXAMPLES[7080]=["I'm feeling really grumpy. I guess it's PMS.","なんかすごいイライラする。生理前だからかな。","grumpy"];
EXAMPLES[7081]=["The teacher told us to stop chattering.","先生は私たちにおしゃべりするのをやめるよう言った。","chattering"];
EXAMPLES[7082]=["Why is Tom always so grouchy?","どうしてトムっていつもあんなに不機嫌なの？","grouchy"];
EXAMPLES[7084]=["Two children are perched on a fence.","二人の子どもが塀の上に腰掛けている。","perched"];
EXAMPLES[7085]=["Price increases explain the difference between the real and nominal growth rates.","実質成長と名目成長率の差は物価上昇を意味する。","nominal"];
EXAMPLES[7088]=["He played an important part like an axis.","彼は軸のような重要な役割を演じた。","axis"];
EXAMPLES[7089]=["We couldn't figure out what Paul wanted to do.","ポールが何をやりたかったのか理解できなかった。","figure out"];
EXAMPLES[7090]=["He tried to soothe the angry man.","彼は怒っている男をなだめようとした。","soothe"];
EXAMPLES[7091]=["The program will finish with the national anthem.","番組は国歌で終了する。","anthem"];
EXAMPLES[7092]=["He has only a superficial knowledge of Japanese.","彼は日本語のうわべだけの知識しかない。","superficial"];
EXAMPLES[7095]=["It's about time we did away with this outdated law.","こんな時代遅れの法律は廃止してもいいころだ。","outdated"];
EXAMPLES[7096]=["He was arrested on charges of tax evasion.","彼は脱税容疑で逮捕された。","evasion"];
EXAMPLES[7097]=["At present, trust in school education is wavering.","現在、学校教育への信頼が揺らいでいます。","wavering"];
EXAMPLES[7098]=["He surmounted the obstacles with great effort.","彼は大変な努力をして障害を乗り越えた。","surmounted"];
EXAMPLES[7100]=["She was so preoccupied that she was oblivious of her surroundings.","彼女はあまり夢中になっていて周囲のことなど念頭になかった。","oblivious"];
EXAMPLES[7101]=["The English are a hardy people.","イギリス人は我慢強い国民だ。","hardy"];
EXAMPLES[7102]=["Nelson Mandela was courteous and polite to all.","ネルソン・マンデラは誰に対しても礼儀正しく丁寧でした。","courteous"];
EXAMPLES[7103]=["We had an implicit agreement that we would support each other.","我々には互いに支持しあおうという暗黙の了解があった。","implicit"];
EXAMPLES[7105]=["I'd like to reserve a private compartment.","個室を予約したいのですが？","compartment"];
EXAMPLES[7106]=["She admonished the child to be more careful.","彼女はもっとよく注意するように子供に言い聞かせた。","admonished"];
EXAMPLES[7107]=["We ascribe his success to hard work.","我々は彼の成功は、勤勉のためであると思う。","ascribe"];
EXAMPLES[7108]=["You have to be up-front and candid at interviews.","面接では、虚心坦懐に話すことが必要だ。","candid"];
EXAMPLES[7109]=["The GOP accused the Democrats of pork barrel politics.","共和党は民主党の地方人気とり補助金政策を非難しました。","barrel"];
EXAMPLES[7112]=["His business has come to a standstill.","彼は商売に行き詰まった。","standstill"];
EXAMPLES[7113]=["Praise the Lord and pass the ammunition.","神を称え、武器を配置せよ。","ammunition"];
EXAMPLES[7115]=["He tried to certify the matter as correct.","彼は事態が正しいものだと証明しようとした。","certify"];
EXAMPLES[7116]=["Children are so innocent and adorable, aren't they?","子供って、ホント純粋でかわいいね。","adorable"];
EXAMPLES[7117]=["We commended him for his good work.","立派な仕事をしたと彼を誉めた。","commended"];
EXAMPLES[7119]=["The way tourists dress offends local standards of propriety.","観光客の服装は地元の礼儀正しさの基準にかなっていない。","propriety"];
EXAMPLES[7122]=["Mary enlisted in the army when she was eighteen.","メアリーは18の時、軍隊に入隊しました。","enlisted"];
EXAMPLES[7123]=["I went over the itinerary with my co-workers.","私は旅行計画書を同僚達と入念にチェックした。","itinerary"];
EXAMPLES[7124]=["Let me explain it with a diagram.","図で説明しましょう。","diagram"];
EXAMPLES[7125]=["There are pictures on alternate pages of the book.","その本は１ページおきに絵が載っている。","alternate"];
EXAMPLES[7126]=["This game is so nostalgic.","このゲーム、めっちゃ懐かしい。","nostalgic"];
EXAMPLES[7128]=["The sky looks ominous. I wonder if it will rain.","空が怪しい。雨が降るかな。","ominous"];
EXAMPLES[7129]=["It is worthwhile to have a try at it.","それは一度やってみる価値がある。","worthwhile"];
EXAMPLES[7130]=["When pressed it makes a crunchy sound.","押すとジャリジャリする。","crunchy"];
EXAMPLES[7132]=["We will tidy up our room so that Mom is satisfied.","部屋を片付けよう。ママが喜ぶから。","tidy up"];
EXAMPLES[7133]=["You should abide by the consequences.","君はその結果を甘受すべきだ。","abide by"];
EXAMPLES[7134]=["I can't believe you're so clueless. You're like a babe in the woods.","世間知らずにもほどがある。井の中の蛙大海を知らず、ということかね。","clueless"];
EXAMPLES[7135]=["I keep all my miscellaneous files in this folder.","このフォルダーに、「その他」に分類される全てのファイルを入れて保管しています。","miscellaneous"];
EXAMPLES[7136]=["Stop the flow of blood from the wound.","傷から流れる血を止めなさい。","wound"];
EXAMPLES[7137]=["Mr Jones reprimanded me for taking a spot of shut-eye during class.","ジョーンズ先生は授業中、いねむりをしたかどで私を叱った。","reprimanded"];
EXAMPLES[7141]=["He didn't come to help, but to hinder us.","彼は助けに来たというより邪魔しに来た。","hinder"];
EXAMPLES[7142]=["Those books look as if they're going to topple over any minute.","本の山は今にも崩れそうに見える。","topple"];
EXAMPLES[7143]=["It's a chore, but I have no other choice.","力業ですが、他に選択肢がありません。","chore"];
EXAMPLES[7144]=["I heard him mumble to himself.","私は彼がぶつぶつ独り言をいうのを聞いた。","mumble"];
EXAMPLES[7146]=["I have a blister on my foot.","足にまめができたんだ。","blister"];
EXAMPLES[7147]=["The world is on the verge of destruction.","世界は破滅の淵に立たされている。","verge"];
EXAMPLES[7150]=["That girl is under the delusion that she is a princess.","あの少女は自分が王女様だという妄想にとらわれている。","delusion"];
EXAMPLES[7151]=["To my dismay, my wallet was gone.","驚いたことに、私の財布がなくなっていた。","dismay"];
EXAMPLES[7152]=["The prediction was falsified by the result.","その予言は結果によって誤りとわかった。","falsified"];
EXAMPLES[7154]=["You got any more of that blue thread?","その青い糸はもっとありますか。","thread"];
EXAMPLES[7155]=["The aristocrat clings to the glory of his past.","その貴族は過去の光栄にしがみついている。","aristocrat"];
EXAMPLES[7156]=["The white yacht was gliding over the sea.","白いヨットが海面を滑るように走っていた。","gliding"];
EXAMPLES[7160]=["Tom didn't think his boss's plan was a viable one.","トムには、上司の計画がうまくいくとは思えなかった。","viable"];
EXAMPLES[7161]=["The life of a person is a transient thing.","人の人生は、はかないものだ。","transient"];
EXAMPLES[7164]=["The assembly voted to protest against any nuclear armament.","その集会はいかなる核武装にも抗議することを決議した。","armament"];
EXAMPLES[7165]=["A bad smell permeated the room.","悪臭が部屋中にびまんした。","permeated"];
EXAMPLES[7166]=["He's quite philosophical about his demotion.","彼は降格されたことを達観している。","demotion"];
EXAMPLES[7167]=["Airplanes are audible long before they are visible.","飛行機は姿の見えるずっと前から音が聞こえる。","audible"];
EXAMPLES[7168]=["We want you to take command of this unified force.","貴君に、この統合軍の指揮をとってもらいたい。","unified"];
EXAMPLES[7170]=["From here, you can look down the elevator shaft.","ここから、エレベーターシャフトを見下ろせます。","shaft"];
EXAMPLES[7173]=["We must cling to our faith.","私たちは自分の信仰に固守しなければならない。","cling to"];
EXAMPLES[7174]=["The hospital patient dropped off shortly after the doctor injected him with anesthesia.","入院患者は医者に麻酔を注射されてすぐに眠りに落ちた。","injected"];
EXAMPLES[7175]=["The merger was implemented on a 50-50 ratio.","その合併は１対１で行われた。","ratio"];
EXAMPLES[7178]=["The cows looked big and docile.","牛は大きくて、おとなしく見えました。","docile"];
EXAMPLES[7180]=["Our views on the matter are in accord.","その件についての我々の見解は一致している。","accord"];
EXAMPLES[7181]=["I cannot dispense with a coat in winter.","私は冬にコートなしではやっていけない。","dispense"];
EXAMPLES[7182]=["Could I have your autograph on this book?","この本にサインしてもらえませんか。","autograph"];
EXAMPLES[7183]=["I have to go to cram school.","塾に行かなきゃ。","cram"];
EXAMPLES[7185]=["The hijacker demanded a ransom of two million dollars.","乗っ取り犯人は２００万ドルの身の代金を要求した。","ransom"];
EXAMPLES[7189]=["The previous tenant took excellent care of her apartment.","前の借家人は、アパートの雑用を抜群によくやっていた。","tenant"];
EXAMPLES[7190]=["Tom bought a pair of polarized sunglasses.","トムは偏光サングラスを買った。","polarized"];
EXAMPLES[7191]=["Stick to jackets that aren't too gaudy.","けばけばしくない上着を必ず選びましょう。","gaudy"];
EXAMPLES[7197]=["He detected in her voice a note of apprehension.","彼は彼女の声に不安げな様子を感じ取った。","apprehension"];
EXAMPLES[7198]=["Is that a veiled threat?","それはいわゆる脅しですか？","veiled"];
EXAMPLES[7200]=["The electrical appliance must have been damaged in transit.","その電気器具は輸送中にこわれたのにちがいない。","appliance"];
EXAMPLES[7201]=["We must instill patriotism into the young people of today.","我々は愛国心を今日の青年の心にうえつけなければならない。","instill"];
EXAMPLES[7204]=["The weather outlook for tomorrow is not good.","明日の天気は良くなるだろう。","outlook"];
EXAMPLES[7205]=["He is thrifty, not to say stingy.","彼はけちとは言わないまでも倹約家だ。","thrifty"];
EXAMPLES[7207]=["The training there includes emergency procedures and tactical firearm handling.","そこでの訓練には、緊急時の手順や戦術的な銃器の扱い方が含まれる。","tactical"];
EXAMPLES[7209]=["It's essential for you to practice every day.","毎日練習することが極めて重要です。","essential"];
EXAMPLES[7211]=["Unfortunately, few passengers survived the catastrophe.","不幸にも、その大惨事で生き残った乗客はほとんどいなかった。","catastrophe"];
EXAMPLES[7213]=["My head has become a tangle of confusion.","頭がこんがらがってきた。","tangle"];
EXAMPLES[7214]=["Financial reforms may ameliorate the current economic difficulties.","財政改革は今の財政難を改善するかもしれません。","ameliorate"];
EXAMPLES[7215]=["Mackerel tastes good whether you simmer it or grill it.","鯖は煮ても焼いても美味しい。","simmer"];
EXAMPLES[7217]=["The soft, gentle sunlight beckoned me to sleep.","ウラウラとした日差しに誘われて、眠りに落ちた。","beckoned"];
EXAMPLES[7218]=["This ring is a memento from grandma.","この指輪ね、祖母の形見なの。","memento"];
EXAMPLES[7220]=["I can't tell if it's kindness or audacity.","親切なんだか押しつけがましいんだかわからん。","audacity"];
EXAMPLES[7221]=["I have a phobia for that.","そういうのって恐いですね。","phobia"];
EXAMPLES[7222]=["It was proved that he was a thief.","彼が泥棒と言うことが判明した。","thief"];
EXAMPLES[7223]=["His synchronizing rate left nothing to be desired.","シンジのシンクロ率は申し分なかった。","synchronizing"];
EXAMPLES[7224]=["I feel very sick. I want to throw up.","私は大変気分が悪い。ゲロをはきたいです。","throw up"];
EXAMPLES[7226]=["Bruce chuckled to himself as he read the letter.","その手紙を読みながら、ブルースはひとりでくすくす笑っていた。","chuckled"];
EXAMPLES[7227]=["It is necessary to look more carefully into the demographic configuration of this region.","この地域の人口構成をもっと注意深く見ていく必要がある。","configuration"];
EXAMPLES[7228]=["Good advice grates on the ear.","忠言耳に逆らう。","grates"];
EXAMPLES[7229]=["Can I stop over in Chicago?","シカゴで途中下車できますか。","stop over"];
EXAMPLES[7230]=["His work shows nothing to brag about.","彼の仕事は自慢するほどのものではない。","brag"];
EXAMPLES[7231]=["He is not the idle boy he was.","彼は、昔の怠惰な少年ではありません。","idle"];
EXAMPLES[7233]=["She's small in stature, but immense in intellect.","彼女は背が低いが、知的だ。","stature"];
EXAMPLES[7234]=["Just looking at a picture of food makes me feel nauseous.","食べ物の写真を見るだけでも吐き気がします。","nauseous"];
EXAMPLES[7236]=["The teacher tried to accustom the children to school.","先生は子供らを学校に慣らすように努力した。","accustom"];
EXAMPLES[7237]=["It's cold. I want to hibernate.","寒い。冬眠したい。","hibernate"];
EXAMPLES[7238]=["I bid ten dollars for the old stove.","私は古いストーブに１０ドルの値をつけた。","bid"];
EXAMPLES[7239]=["Allocate a room for research purposes.","研究用として一部屋取っておいて。","Allocate"];
EXAMPLES[7241]=["Ancient astronomers noticed constellations and gave them names.","古代の天文学者は、星座を見つけ、名前をつけた。","constellations"];
EXAMPLES[7242]=["My neighbor is what we call a nosy person.","私の隣人はいわゆる詮索好きなのです。","nosy"];
EXAMPLES[7243]=["I had to part with my competent secretary.","私は有能な秘書を手放さなくてはならなかった。","competent"];
EXAMPLES[7245]=["Please be careful in regard to scam email.","詐欺メールにはご注意ください。","scam"];
EXAMPLES[7246]=["They should be pardoned by the amnesty law.","彼らは恩赦法によって許されるはずだ。","amnesty"];
EXAMPLES[7247]=["He likes to spend some time in solitude every day.","彼は毎日好んで独りで過ごす時間を持つ。","solitude"];
EXAMPLES[7248]=["Tom caught an intruder in his house.","トムは空き巣を捕まえた。","intruder"];
EXAMPLES[7249]=["Maybe I'll just wander off on my own.","ぶらりと一人旅でもしてくるかな。","wander"];
EXAMPLES[7250]=["I have tried to discourage him from going abroad.","私は彼に海外へ行くのをやめさせようとした。","discourage"];
EXAMPLES[7252]=["The objective of Minesweeper is to clear the minefield without detonating the mines.","マインスイーパの目的は地雷原から地雷を取り除くことである。","detonating"];
EXAMPLES[7253]=["I walked about aimlessly on the street.","街を当てもなく歩いた。","aimlessly"];
EXAMPLES[7254]=["Does ALC's web site include an archive of English expressions?","アルクのホームページには英語表現のアーカイブがありますか。","archive"];
EXAMPLES[7255]=["What do you think about the Gulf War?","湾岸戦争についてどう思いますか。","Gulf"];
EXAMPLES[7257]=["It'll take a few days to break in these shoes.","この靴を履き慣らすには数日かかるだろう。","break in"];
EXAMPLES[7259]=["The museum has a fascinating collection of Celtic artifacts.","その博物館にはケルト時代の文化遺産のすばらしいコレクションがある。","artifacts"];
EXAMPLES[7261]=["If you want to become thin, you should cut back on the between-meal snacks.","痩せたいなら間食は控えるべきだ。","cut back on"];
EXAMPLES[7262]=["I was somehow able to dodge the attack with ease.","なんとか上手く攻撃をかわした。","dodge"];
EXAMPLES[7263]=["It is rumored that he has gone bankrupt.","彼は破産したという噂だ。","bankrupt"];
EXAMPLES[7265]=["The athlete caught his foot on the hurdle.","その選手はハードルに足を引っ掛けたんだ。","hurdle"];
EXAMPLES[7266]=["It's important to nourish your children with good food.","良い食事で子どもたちを育てることが大切だ。","nourish"];
EXAMPLES[7267]=["Tension is a major cause of heart disease.","緊張が心臓病の主な原因だ。","Tension"];
EXAMPLES[7268]=["His actions do not correspond with his words.","彼は言葉と行動が一致していない。","correspond"];
EXAMPLES[7269]=["The Incas had a wide range of interests.","インカ族は幅広い興味を持っていた。","a wide range of"];
EXAMPLES[7270]=["He got the section chief's daughter pregnant and was demoted.","彼は部長の娘さんを妊娠させて、左遷されました。","demoted"];
EXAMPLES[7271]=["The coup attempt was foiled at the last moment.","クーデター計画はぎりぎりのところで阻止されました。","foiled"];
EXAMPLES[7273]=["The groom is thirty years old.","花婿は30歳です。","groom"];
EXAMPLES[7274]=["Players must adhere to the rules of the game.","選手は試合の規則を断固守らなければならない。","adhere"];
EXAMPLES[7275]=["This auditorium can seat up to 300 people.","この講堂は300人まで入れる。","auditorium"];
EXAMPLES[7276]=["Don't be a fussy eater; let's eat everything.","好き嫌いせず、残さず食べましょう。","fussy"];
EXAMPLES[7277]=["I was immersed in the happy atmosphere of the occasion.","私はその場の幸福な雰囲気に浸っていた。","immersed"];
EXAMPLES[7278]=["Athletes usually abstain from smoking.","運動選手は普通禁煙する。","abstain from"];
EXAMPLES[7279]=["Where do I swipe my card?","カードはどこで通せばいいのかしら？","swipe"];
EXAMPLES[7280]=["I glared at him with a blatant look of disapproval on my face.","露骨に嫌な顔をして、彼を睨みつけた。","blatant"];
EXAMPLES[7282]=["I'll choke the life out of him.","あいつの息の根を止めてやる。","choke"];
EXAMPLES[7283]=["You have a very crisp way of speaking.","あなたの話し方はなかなか歯切れがいいですね。","crisp"];
EXAMPLES[7284]=["Is this too sloppy?","これがぐちゃぐちゃすぎてますか？","sloppy"];
EXAMPLES[7286]=["The autumn sky is clear and serene.","秋の空は澄み渡っている。","serene"];
EXAMPLES[7287]=["That kid is a little bundle of energy.","その子どもは元気そのものです。","bundle"];
EXAMPLES[7290]=["He spoke with a suggestion of sarcasm in his voice.","彼は少しばかり皮肉っぽく話した。","sarcasm"];
EXAMPLES[7291]=["We should not use foreign workers as a buffer against Japan's economic slowdown.","外国人労働者は日本経済のバッファーであってはならない。","buffer"];
EXAMPLES[7292]=["There is too much acid in this orange.","このオレンジは酸っぱすぎる。","acid"];
EXAMPLES[7293]=["We must be able to discriminate between objects and situations.","我々は物事と状況を区別する事ができないといけない。","discriminate"];
EXAMPLES[7294]=["While taking a walk, Tom enjoyed the autumn leaves in vibrant red and orange.","散歩をしながら、トムは鮮やかな赤とオレンジ色の紅葉を堪能しました。","vibrant"];
EXAMPLES[7295]=["You ought to face the stark reality.","あなたは赤裸々な現実を直視すべきだ。","stark"];
EXAMPLES[7297]=["I broke a sweat running on the treadmill.","私はトレッドミル上を走って汗をかいた。","treadmill"];
EXAMPLES[7300]=["Nationalism is not to be confused with patriotism.","国家主義と愛国心とを混同してはならない。","patriotism"];
EXAMPLES[7301]=["The cochlea implant is a technically ingenious device.","人工内耳は技術的に巧妙な機器です。","implant"];
EXAMPLES[7302]=["What are you going to take this semester?","今学期はどんな教科を選択しますか。","semester"];
EXAMPLES[7303]=["She prodded him to work harder.","彼女は、もっと働くよう、彼を促した。","prodded"];
EXAMPLES[7304]=["This system is bristling with defects and drawbacks.","この制度は欠陥だらけだ。","drawbacks"];
EXAMPLES[7305]=["What is the maximum dosage for an adult?","大人への一回分の最大の投薬量はどのくらいですか。","dosage"];
EXAMPLES[7306]=["He has consistently endeavored to help the poor.","彼は一貫して貧しい人たちを助ける努力をしてきた。","consistently"];
EXAMPLES[7311]=["The law is meant to be circumvented.","法は脱法されるために作られる。","circumvented"];
EXAMPLES[7312]=["Don't worry. The blood will clot soon.","心配すんな。血はすぐ止まるよ。","clot"];
EXAMPLES[7313]=["He is the foremost authority on heart surgery.","彼は心臓外科の第一人者だ。","foremost"];
EXAMPLES[7314]=["First, I'd like to examine the catalyst used in this experiment.","最初に、この実験で使用された触媒について吟味したい。","catalyst"];
EXAMPLES[7316]=["The counterfeit Bills flooded the market over the weekend.","週末に偽札が市場にあふれた。","counterfeit"];
EXAMPLES[7323]=["There is a communal kitchen in the dormitory.","寮には共用のキッチンがある。","communal"];
EXAMPLES[7326]=["They were erected to commemorate a certain event or to tell an ancestral legend.","ある出来事を記念したり先祖の伝説を伝えるために建てられたものであった。","ancestral"];
EXAMPLES[7327]=["Expedited delivery will cost an additional ten dollars.","緊急配送には、１０ドル追加料金がかかります。","Expedited"];
EXAMPLES[7329]=["The devastation in Kobe was as terrible as I had imagined.","神戸の荒廃は、私が想像していたとおり酷いものであった。","devastation"];
EXAMPLES[7332]=["It is paramount to all the others.","それは他のいっさいに勝っている。","paramount"];
EXAMPLES[7333]=["There is a continuation.","続きがあるのだ。","continuation"];
EXAMPLES[7334]=["The air we breathe consists of oxygen and nitrogen.","私達の吸っている空気は酸素と窒素からできている。","nitrogen"];
EXAMPLES[7335]=["The story is at once interesting and instructive.","その物語は面白くもありまたためにもなる。","instructive"];
EXAMPLES[7338]=["He is tolerant in religious belief of others.","彼はほかの人の宗教心には寛大だ。","tolerant"];
EXAMPLES[7340]=["That patient cannot hold out through the summer.","その病人は夏中はもたないだろう。","hold out"];
EXAMPLES[7342]=["The police arrested the burglar on the spot.","警察は強盗犯を即座に逮捕しました。","burglar"];
EXAMPLES[7344]=["My house is small and cramped.","私のうちは小さくて、狭いです。","cramped"];
EXAMPLES[7346]=["It is aptly said that illness starts from the mind.","病は気からとはうまく言ったものですね。","aptly"];
EXAMPLES[7347]=["I'd like to have a Pap smear done.","子宮癌の検査をしていただきたいのです。","smear"];
EXAMPLES[7348]=["Would you like another wedge of pie?","パイをもう一ついかがですか。","wedge"];
EXAMPLES[7349]=["I am ashamed of your despicable deed.","きみの言語道断な行いを恥ずかしいと思う。","despicable"];
EXAMPLES[7352]=["The destruction of the environment is appalling.","環境破壊は驚くほどすすんでいる。","appalling"];
EXAMPLES[7353]=["He is a member of the fraternity.","彼は友愛会の会員だ。","fraternity"];
EXAMPLES[7355]=["I have a hunch that it will rain.","雨が降るような気がする。","hunch"];
EXAMPLES[7357]=["The Forensic Investigation Unit is trying to determine the cause of today's fire.","鑑識班は今日の火事の原因を特定しようとしている。","Forensic"];
EXAMPLES[7361]=["This seasoning is so versatile that you can put it on anything.","この調味料、万能すぎて何にでもかけてる。","versatile"];
EXAMPLES[7363]=["The wooden pieces are fastened with a peg.","木片は１本の留め木で留めてある。","peg"];
EXAMPLES[7365]=["Age discrimination is illegal and retirement is mandatory in only a few occupations.","年齢による差別は法律違反であり、退職が強制されるのは、ほんの少数の職業においてである。","mandatory"];
EXAMPLES[7366]=["The police brutality incidents nearly set off a riot.","警官による暴行事件はあやうく暴動に火をつけるところでした。","brutality"];
EXAMPLES[7367]=["It is hard to win four successive games.","試合に４連勝するのは難しい。","successive"];
EXAMPLES[7369]=["The girl was not downright homely.","その女の子はひどく不美人というほどではなかった。","downright"];
EXAMPLES[7371]=["His work is a synthesis of several ideas.","彼の作品はいくつかのアイデアの統合体である。","synthesis"];
EXAMPLES[7372]=["His calm words allayed my fear.","彼の冷静な言葉で私の恐怖は和らいだ。","allayed"];
EXAMPLES[7373]=["We shall continue our efforts to eradicate racial discrimination.","我々は人種差別を完全に無くす努力を必ず続けて行く。","eradicate"];
EXAMPLES[7375]=["I want to become both physically and mentally stronger.","体力的にも精神的にももっと強くなりたい。","mentally"];
EXAMPLES[7376]=["They had a dent in the rear door.","後ろのドアにへこみができた。","dent"];
EXAMPLES[7377]=["Now that I'm older, I see things differently.","年をとったので、物事が違って見えるようになりました。","differently"];
EXAMPLES[7378]=["Mary is studying to become a midwife.","メアリーは助産婦を目指して勉強しています。","midwife"];
EXAMPLES[7379]=["After seeing her provocative body, he became obsessed with her.","彼女の悩ましげな姿を見て、彼はすっかり夢中になってしまいました。","provocative"];
EXAMPLES[7380]=["We plan to elicit opinions from the public.","市民の皆様の御意見をちょうだいする予定です。","elicit"];
EXAMPLES[7383]=["There must have been a tacit understanding between them.","二人の間には暗黙の了解があったに違いない。","tacit"];
EXAMPLES[7384]=["He was coerced into helping the thieves.","彼は無理矢理泥棒たちの手助けをさせられた。","coerced"];
EXAMPLES[7388]=["You are a dire part of this.","君は必要な人間なのだ。","dire"];
EXAMPLES[7389]=["It's unethical to own a cat as a pet.","猫を飼うのは不倫理的だよ。","unethical"];
EXAMPLES[7390]=["The Abominable Snowman is a Himalayan monster.","雪男はヒマラヤの怪物だ。","Abominable"];
EXAMPLES[7393]=["Do I have to fix up to go to their house?","あの家には清爽で行かねばならないですか。","fix up"];
EXAMPLES[7395]=["This paper has very good absorption.","この紙は吸収力が高い。","absorption"];
EXAMPLES[7396]=["Don't fritter away your allowance.","こづかいをあまり無駄づかいしないように。","fritter away"];
EXAMPLES[7399]=["He wanted to be on equal footing with his mother.","お母さんと対等になりたかった。","footing"];
EXAMPLES[7400]=["What do you need to build a nether portal?","ネザーポータルを構築するには何が必要ですか？","portal"];
EXAMPLES[7401]=["He repeatedly checked the mountain of related documents.","彼は関連書類の山を何度も繰り返し調べた。","repeatedly"];
EXAMPLES[7402]=["I already read all the Harry Potter books.","ハリポタは前に全部読んだよ。","Harry"];
EXAMPLES[7403]=["It is forbidden for you to touch that switch.","絶対にそのスイッチに触ってはいけない。","forbidden"];
EXAMPLES[7404]=["The digression is escalating more and more.","脱線がどんどんエスカレートしていく。","digression"];
EXAMPLES[7405]=["The tumor is malignant.","腫瘍は悪性です。","malignant"];
EXAMPLES[7406]=["Certain artificial sweeteners are known to be carcinogens.","ある種の人工甘味料には発癌性があることが知られている。","carcinogens"];
EXAMPLES[7407]=["The Internet is an invaluable source of information.","インターネットはこの上なく貴重な情報の宝庫だ。","invaluable"];
EXAMPLES[7409]=["Then that animosity is being passed on down to us?","じゃあ僕らはその腹いせ受け続けるんですか？","animosity"];
EXAMPLES[7412]=["Can you give me a geological explanation of lava?","溶岩を地理学的に説明してくれませんか。","lava"];
EXAMPLES[7413]=["He was duped by being fed false information.","彼は、嘘の情報をあたえられて、一杯くわされた。","duped"];
EXAMPLES[7414]=["Bill was adamant that she should obey him.","ビルは絶対に彼女が彼に従うべきだと譲らなかった。","adamant"];
EXAMPLES[7417]=["A long discussion boiled down to a realistic conclusion.","長い議論は現実的な結論に煮詰まった。","realistic"];
EXAMPLES[7418]=["I have a bad sunburn.","日焼けし過ぎました。","sunburn"];
EXAMPLES[7421]=["A high forehead is indicative of great mental power.","額が広いのは頭がとてもいいことを表している。","indicative"];
EXAMPLES[7422]=["She accepted him her suitor.","彼女は彼に結婚の承諾を与えた。","suitor"];
EXAMPLES[7423]=["It's the way that she laughs at herself that endears her to me.","彼女が自分で自分を嘲笑うのがわたしには魅力的だ。","endears"];
EXAMPLES[7424]=["You have come at an opportune time.","あなたはちょうどよい折に来た。","opportune"];
EXAMPLES[7428]=["It is imperative for you to act at once.","君たちがすぐに行動する事が絶対に必要だ。","imperative"];
EXAMPLES[7431]=["Boeing developed a flying boat for the Maritime Self-Defense Force.","ボーイング社は海上自衛隊用の飛行艇を開発しました。","Maritime"];
EXAMPLES[7432]=["This mountain path ascends to the beautiful lake.","この山道を登ると美しい湖に出る。","ascends"];
EXAMPLES[7433]=["I ranted over something that was besides the point.","的外れなことを熱弁してしまった。","ranted"];
EXAMPLES[7434]=["Your explanation sounds plausible, but it just doesn't hold water.","君の説明はもっともらしいが、筋がちっとも通ってない。","plausible"];
EXAMPLES[7438]=["He amassed a large fortune before he died.","彼は死ぬ前に大財産を蓄えた。","amassed"];
EXAMPLES[7440]=["Bread is made from flour, water and yeast.","パンは粉と水とイーストから作られる。","yeast"];
EXAMPLES[7443]=["The discovery will have a momentous effect on the treatment of cancer.","その発見は癌の治療に重大な影響を及ぼすことになるだろう。","momentous"];
EXAMPLES[7448]=["The debate has been interesting, confusing, and sometimes horrifying.","ここでの討論はおもしろいものでしたし、困惑させるもの、ときにはぞっとする内容のものもありました。","horrifying"];
EXAMPLES[7452]=["We had a rough flight because of turbulence.","乱気流のために飛行機が揺れた。","turbulence"];
EXAMPLES[7453]=["The street, lined with trees, provided a vista of the sea.","街路樹のある通りの向こうに海が見えた。","vista"];
EXAMPLES[7454]=["I needed you to be more reliant on me.","もっと頼って欲しかった。","reliant"];
EXAMPLES[7455]=["The number 2015 is represented as 11111011111 in binary.","2015という数は二進法で表すと11111011111となる。","binary"];
EXAMPLES[7456]=["My mother says that the child's illnesses are phony.","その子の病気はいつも仮病であると母親は言っている。","phony"];
EXAMPLES[7457]=["Hoist your sail when the wind is fair.","得手に帆を揚げる。","Hoist"];
EXAMPLES[7458]=["He has an innate love of adventure.","彼は生まれつき冒険家だ。","innate"];
EXAMPLES[7459]=["These stories are told in colloquial and everyday language.","これらの話は口語体の日常の言葉で語られる。","colloquial"];
EXAMPLES[7460]=["She was abducted by aliens from the planet Tatoeba.","彼女はタトエバ星から来た宇宙人に拉致された。","abducted"];
EXAMPLES[7462]=["The view is stunning.","見事な景色だ。","stunning"];
EXAMPLES[7463]=["I've got a bad case of jet lag.","時差ボケで辛い。","lag"];
EXAMPLES[7464]=["We said in unison that we didn't agree to the suggestion.","その提案に口をそろえて反対を唱えた。","unison"];
EXAMPLES[7466]=["The property was purchased with laundered political money.","その土地はローンダリングした政治資金で購入されました。","laundered"];
EXAMPLES[7468]=["Will you impart the secret to me?","私にその秘密を知らせてくれませんか。","impart"];
EXAMPLES[7472]=["My new Alfa Romeo convertible is light red.","私の新しいアルファ・ロメオのオープンカーは明るい赤色だ。","convertible"];
EXAMPLES[7473]=["There are colossal mountains in the north.","北部には巨大な山々がある。","colossal"];
EXAMPLES[7474]=["But he said: I beseech thee, Lord, send whom thou wilt send.","モーセは言った、「ああ、主よ、どうか、ほかの適当な人をおつかわしください」。","thee"];
EXAMPLES[7475]=["He stubbed out his cigar in the ashtray and stood up to leave.","彼はシガーを灰皿で押しつぶして消し、立って行こうとした。","stubbed"];
EXAMPLES[7476]=["I have an ulcer in my mouth.","口内炎ができているのです。","ulcer"];
EXAMPLES[7481]=["What are you insinuating?","何が言いたいわけ？","insinuating"];
EXAMPLES[7489]=["Mr. President, what you are doing is treason!","大統領さん、あなたのしていることは反逆です！","treason"];
EXAMPLES[7490]=["Few boys are dainty about their food.","男の子で食べ物にうるさいのは少ない。","dainty"];
EXAMPLES[7491]=["I concocted an excuse for missing the party.","パーティーを欠席した言い訳に作り話をこねあげた。","concocted"];
EXAMPLES[7492]=["Crawl forward is done much more agilely – scuttle like a cockroach!","ほふく前進はもっと素早くゴキブリのように這え！","scuttle"];
EXAMPLES[7493]=["We look on her as a loose woman.","われわれは、彼女を尻軽女と見ているんだ。","loose"];
EXAMPLES[7494]=["There are many questionable points in this ledger.","この帳簿には不明朗な点がたくさんある。","questionable"];
EXAMPLES[7495]=["That lady is haughty to a great degree.","あの婦人はひどく傲慢だ。","haughty"];
EXAMPLES[7497]=["I often listen to soothing music in order to relax.","リラックスできる癒し系の音楽をよく聞いている。","soothing"];
EXAMPLES[7501]=["The first word of every sentence should be capitalized.","文の最初の語はすべて大文字ではじめなければならない。","capitalized"];
EXAMPLES[7502]=["It was just a fender bender.","軽い接触事故だったんだ。","fender"];
EXAMPLES[7504]=["This medicine will alleviate the pain.","この薬は痛みを和らげてくれるよ。","alleviate"];
EXAMPLES[7505]=["He exhaled a deep breath in discouragement.","彼はがっかりして深いため息をついた。","exhaled"];
EXAMPLES[7507]=["Rats have gnawed holes in the door.","ネズミがドアに穴をあけた。","gnawed"];
EXAMPLES[7508]=["We have a 50% interest in the company.","私達は同社に５０％出資している。","interest"];
EXAMPLES[7511]=["I expect it's his lousy personality that drives off the ladies.","こいつの性根が悪いから非モテなんだろ。","lousy"];
EXAMPLES[7512]=["He was PK'ed, I resurrected him.","ＰＫされたの、蘇生しました。","resurrected"];
EXAMPLES[7513]=["The baby nestled in his mother's arms.","赤ん坊は気持ちよさそうに母親に抱かれていた。","nestled"];
EXAMPLES[7515]=["Do you think real neurotics really go and call themselves such?","本物のノイローゼの奴がノイローゼだなんて自称するのかね？","neurotics"];
EXAMPLES[7517]=["The idea that he is going to make a speech is laughable.","あいつが演説するなんて片腹痛い。","laughable"];
EXAMPLES[7518]=["Statistics indicate that our living standards have risen.","統計は我々の生活水準が向上したことを示している。","Statistics"];
EXAMPLES[7519]=["The top part is turning clockwise.","上部は時計回りに回ってます。","clockwise"];
EXAMPLES[7522]=["The argument that smoking is injurious has become accepted.","たばこは健康に害であるという主張は容認されてきた。","injurious"];
EXAMPLES[7523]=["It is likely that these two consonants are in complementary distribution.","この２つの子音は相補分布をなしていそうである。","complementary"];
EXAMPLES[7524]=["I've had a nasal voice for two weeks.","ここ２週間鼻声が抜けません。","nasal"];
EXAMPLES[7526]=["Dietary fibre is good for losing weight.","食物繊維はダイエットに効果的だ。","Dietary"];
EXAMPLES[7529]=["The Christmas market was heaving.","クリスマス・マーケットは、人で溢れかえっていた。","heaving"];
EXAMPLES[7532]=["The children are giddy with excitement on Christmas morning.","クリスマスの朝は、子供たちはハイテンションです。","giddy"];
EXAMPLES[7535]=["She is a strenuous supporter of women's rights.","彼女は女性の権利擁護の熱心な支持者である。","strenuous"];
EXAMPLES[7536]=["I watched them demolish that old building.","あの古い建物が解体されるのを見てたんだ。","demolish"];
EXAMPLES[7537]=["It is not necessary to be meticulous.","こせこせする必要はない。","meticulous"];
EXAMPLES[7538]=["Tom's treatise is beyond reproach.","トムの論文は、非の打ち所がない。","treatise"];
EXAMPLES[7541]=["My license was confiscated.","私の免許は没収になった。","confiscated"];
EXAMPLES[7542]=["Doctors have discovered some startling facts.","医師達はいくつかの驚くべき事実を発見した。","startling"];
EXAMPLES[7544]=["I need time to mull things over before I decide what to do.","私は行動の決断をする前によく考える時間が欲しい。","mull"];
EXAMPLES[7546]=["What now, you wretch? You thinking of protecting her?","何だ、貴様は。庇い立てする気か。","wretch"];
EXAMPLES[7547]=["He went abroad in opposition to her ardent wishes.","彼女の熱心な希望に逆らって彼は外国へ行った。","ardent"];
EXAMPLES[7550]=["The man beguiled me of my money.","その男はだまして私のお金を巻き上げた。","beguiled"];
EXAMPLES[7552]=["The President vetoed the Bill, but Congress overrode his veto.","大統領はその法案に対して拒否権を行使しましたが、議会が再度それを無効にしました。","vetoed"];
EXAMPLES[7553]=["He is more crafty than wise.","彼は賢いと言うよりはずるがしこい。","crafty"];
EXAMPLES[7554]=["In fact, this is a major means of bureaucratic control.","実際のところ、これは官僚支配の有力な手段なのである。","bureaucratic"];
EXAMPLES[7558]=["I was keyed up over her impending operation.","私は彼女の間近に近付いた手術のことで緊張していた。","impending"];
EXAMPLES[7559]=["All the soldiers were gallant.","兵士は皆勇敢だった。","gallant"];
EXAMPLES[7560]=["Only a sincere apology will appease my anger.","私の怒りを静めるのは心からの謝罪しかない。","appease"];
EXAMPLES[7562]=["The fact is that the rumor is groundless.","実はそのうわさは根拠がない。","groundless"];
EXAMPLES[7563]=["We are an invincible team.","私たちは無敵のチームです。","invincible"];
EXAMPLES[7564]=["The young engineer was deficient in experience.","その若い技師は経験が不足していた。","deficient"];
EXAMPLES[7565]=["He is indifferent to the suffering of others.","彼は他人の苦しみに対して淡淡だ。","indifferent"];
EXAMPLES[7570]=["Happening in wartime, this would amount to disaster.","戦時に起こったとしたなら、これは災難になるだろう。","wartime"];
EXAMPLES[7572]=["The world is full of incompetent doctors.","世の中は藪医者だらけ。","incompetent"];
EXAMPLES[7573]=["The girl basks in the love of her family.","その少女は家族の愛に包まれている。","basks"];
EXAMPLES[7575]=["He is capable of treachery.","あの男は裏切りもしかねない。","treachery"];
EXAMPLES[7576]=["Some people listen to music when writing, but others say it hampers their productivity.","音楽を聞きながら書き物をする人もいるが、音楽を聞きながらだと能率が下がるという人もいる。","hampers"];
EXAMPLES[7577]=["She chided her child for cutting in.","彼女は子供が話に割り込むのをしかった。","chided"];
EXAMPLES[7578]=["That's funny. The speaker is crackling.","おかしいな、スピーカーがガーガーいってるよ。","crackling"];
EXAMPLES[7580]=["He may be rich, but he is stingy.","金持ちかもしれないがけちだ。","stingy"];
EXAMPLES[7585]=["Tom used to wear a wig.","トムは昔、かつらをつけていた。","wig"];
EXAMPLES[7588]=["In Japan it is not customary to tip for good service.","日本には良いサービスに対してチップを払う習慣はない。","customary"];
EXAMPLES[7589]=["The drawer is stuffed full of odds and ends.","引き出しはがらくたでぎっしり詰まっている。","stuffed"];
EXAMPLES[7590]=["How much mince did you buy?","ひき肉はどれぐらい買ったの？","mince"];
EXAMPLES[7592]=["We must prevent this type of incident from recurring.","このようなことが二度と起こらないようにしなければならない。","recurring"];
EXAMPLES[7594]=["If you keep trying, you will make progress.","あきらめずに歩き続ければ、進歩するでしょう。","make progress"];
EXAMPLES[7596]=["The vicar often refers to the Bible in his sermon.","教区牧師は法話の時しばしば聖書に言及する。","vicar"];
EXAMPLES[7597]=["We'll use the house as collateral so we can borrow some money.","家を担保にお金を借りよう。","collateral"];
EXAMPLES[7601]=["I mused on the meaning of his painting.","私は彼の絵の意味をじっと考えた。","mused"];
EXAMPLES[7602]=["Russia and China have many autonomous regions.","ロシアや中国は多くの自治区を持ちます。","autonomous"];
EXAMPLES[7604]=["How can you be so passive? Why don't you retaliate?","どうしてそんなに受け身的なのか。仕返ししてはどうだ。","retaliate"];
EXAMPLES[7606]=["Jim made a superfluous remark.","ジムはよけいな発言をした。","superfluous"];
EXAMPLES[7608]=["To our surprise, he scoffed the lot.","驚いたことに彼は料理を全部平らげてしまった。","scoffed"];
EXAMPLES[7609]=["Why don't you calm down? You're really making me cringe.","もうちょっと落ち着いたらどうなの？まったく危なっかしいんだから。","cringe"];
EXAMPLES[7610]=["Do you sometimes get pissed off for no reason?","たまに訳もなくイライラすることってない？","pissed"];
EXAMPLES[7611]=["The tumor was benign.","腫瘍は良性でした。","benign"];
EXAMPLES[7613]=["The ship sounded its whistle and pulled away from the wharf.","船は汽笛を鳴らして、埠頭を離れました。","wharf"];
EXAMPLES[7615]=["Their job is to shear the sheep.","彼らの仕事は羊の毛を刈ることだ。","shear"];
EXAMPLES[7616]=["It is incumbent on you to do so.","そうするのはあなたの責任だ。","incumbent"];
EXAMPLES[7617]=["He has a wistful look on his face.","彼は悲しそうな顔つきをしている。","wistful"];
EXAMPLES[7618]=["She was too proud to do anything disgraceful.","彼女はプライドが高いので恥ずべきことはしなかった。","disgraceful"];
EXAMPLES[7619]=["Please beware of fraudulent emails.","騙りメールにご注意ください。","fraudulent"];
EXAMPLES[7620]=["Any turnaround of the economy is not expected this year.","今年は景気回復の見込みはない。","turnaround"];
EXAMPLES[7622]=["His shoulders sagged when he heard the news.","その知らせを聞いて彼はがっくりと肩を落とした。","sagged"];
EXAMPLES[7624]=["I entreat you to go and see him.","どうか彼に会いに行ってください。","entreat"];
EXAMPLES[7625]=["Too much alcohol may result in gastric disease.","飲みすぎると胃の病気になるかもしれません。","gastric"];
EXAMPLES[7626]=["She coaxed the letter out of her brother.","彼女はうまく弟からその手紙を取り上げた。","coaxed"];
EXAMPLES[7628]=["The man proceeded briskly across fields and mountains.","その男は野を越え山を越えずんずん進んでいきました。","briskly"];
EXAMPLES[7630]=["He will avenge the people on their oppressor.","彼は迫害者を懲らしめて人民たちのあだを討つだろう。","avenge"];
EXAMPLES[7633]=["His name eludes me.","その人の名を思い出せない。","eludes"];
EXAMPLES[7635]=["According to the radio, a storm is imminent in the North.","ラジオによると、北海で嵐が起こるとのことだ。","imminent"];
EXAMPLES[7637]=["How can I get my toddler to eat vegetables?","どうすれば小さな子供に野菜を食べさせることができるでしょうか。","toddler"];
EXAMPLES[7638]=["You're not just peddling stuff!","物売るっていうレベルじゃねぇぞ。","peddling"];
EXAMPLES[7639]=["The valley echoes the sound of the waterfall.","谷は滝の音を反響する。","waterfall"];
EXAMPLES[7640]=["There was only one warden on duty when the riot started.","暴動が起こったとき、当直の監視員はたった１人だった。","warden"];
EXAMPLES[7641]=["The train was derailed, and panic ensued.","列車が脱線すると、たちまちパニック状態になった。","derailed"];
EXAMPLES[7642]=["Please leave a urine sample in this cup.","このカップに尿をとってください。","urine"];
EXAMPLES[7645]=["Ultraviolet rays are harmful to us.","紫外線は私たちにとって有害だ。","Ultraviolet"];
EXAMPLES[7646]=["He seems to be wary of us.","彼は我々を警戒しているようだ。","wary"];
EXAMPLES[7647]=["He walked vigorously ahead of us.","彼はわれわれの先をどんどん歩いて行った。","vigorously"];
EXAMPLES[7648]=["At dusk, the sky is tinted with purple light.","夕暮れ時、空は紫色の光に染まっています。","tinted"];
EXAMPLES[7649]=["He nudged me to go ahead.","彼は私をつついて先に行けと合図した。","nudged"];
EXAMPLES[7651]=["Don't burst out laughing like that. It's creepy.","急に笑い出さないでよ。不気味だから。","creepy"];
EXAMPLES[7655]=["The revolution ushered in a new era.","革命は新たな時代をもたらした。","ushered"];
EXAMPLES[7656]=["Broken glass lay scattered all over the road.","ガラスの破片が、道路一面に散らばってたよ。","scattered"];
EXAMPLES[7657]=["Mt. Asama is now dormant.","浅間山は今静止している。","dormant"];
EXAMPLES[7658]=["The police began a crackdown on illegal parking.","警察は違法駐車の取り締まりを始めた。","crackdown"];
EXAMPLES[7661]=["He is a fanatic for taking long trips.","彼は大の旅行好きだ。","fanatic"];
EXAMPLES[7662]=["Tom ate all the food I had stashed.","トムがね、私が隠してた物、全部食べたのよ。","stashed"];
EXAMPLES[7665]=["Antibiotics are commonly enzymatic inhibitors.","抗生物質は一般的に酵素の阻害剤である。","inhibitors"];
EXAMPLES[7668]=["This edifice is a mosque.","この建物はモスクです。","edifice"];
EXAMPLES[7670]=["After the rain, there were puddles on the street.","雨のあと、道路に水溜まりができた。","puddles"];
EXAMPLES[7671]=["Everyone hoped for a snow flurry for Christmas.","みんなクリスマスに小雪がちらつくのを望んでいた。","flurry"];
EXAMPLES[7674]=["They came early so they wouldn't miss the prelude.","彼らは前奏曲を聞き漏らさないように早く来た。","prelude"];
EXAMPLES[7677]=["I play bass guitar in a guitar ensemble.","わたしはギターアンサンブルでバスギターを弾いている。","ensemble"];
EXAMPLES[7678]=["Do you know the admin password for the router?","このルーターの管理者パスワードって、わかる？","router"];
EXAMPLES[7680]=["The ground was covered with frost this morning.","今朝、地面は霜で覆われていた。","frost"];
EXAMPLES[7684]=["Let's give it a whirl.","やってみようよ。","whirl"];
EXAMPLES[7687]=["The band is on hiatus.","そのバンドはただいまお休みです。","hiatus"];
EXAMPLES[7690]=["The government coffers are replete with funds.","国庫は資金が潤沢である。","coffers"];
EXAMPLES[7692]=["Threats of retaliation are blocking negotiations.","報復のおどかしが交渉を妨げています。","retaliation"];
EXAMPLES[7695]=["Politicians from many countries made pilgrimages to the White House.","各国の政治家がホワイトハウス詣でをした。","pilgrimages"];
EXAMPLES[7696]=["You don't have to wince like that. I'll fix it so it doesn't hurt.","そんな痛そうな顔しないで。痛くないようにするからさ。","wince"];
EXAMPLES[7698]=["Atoms are composed of protons, neutrons, and electrons.","原子は陽子・中性子・電子で構成されている。","neutrons"];
EXAMPLES[7702]=["There are clumps of daisies here and there.","あちこちにヒナギクが群生している。","clumps"];
EXAMPLES[7706]=["Let's shackle your feet with silver fetters.","あなたの足に銀の足かせをはめましょう。","shackle"];
EXAMPLES[7707]=["I experienced a feeling of antipathy towards the speaker.","私は話し手に対して反感を持った。","antipathy"];
EXAMPLES[7709]=["The actress sued the magazine for libel.","その女優は雑誌を名誉き損で訴えた。","libel"];
EXAMPLES[7712]=["The country fell into the invader's hand.","その国は侵略者の手に落ちた。","invader"];
EXAMPLES[7714]=["Anyway, if aiming then aim at the lighthouse.","どうせ、狙うなら灯台よ。","lighthouse"];
EXAMPLES[7715]=["I hear that it has quite the reputation with coffee connoisseurs.","コーヒー通の人達に結構評判がいいそうです。","connoisseurs"];
EXAMPLES[7716]=["Masculinity has to do with supporting women and children.","男らしさとは、女性と子供を養うことだ。","Masculinity"];
EXAMPLES[7717]=["Are you going to join the glee club?","グリークラブに入るつもりなの？","glee"];
EXAMPLES[7722]=["The table is wobbling.","テーブルがぐらついてるよ。","wobbling"];
EXAMPLES[7725]=["I don’t want a nurse who swoons at the sight of blood.","血を見て失神しちゃうような看護師はいらないわ。","swoons"];
EXAMPLES[7726]=["If you combine them in this way, you get a 14 port USB hub.","こういう風に合体すれば、１４ポートのＵＳＢハブになります。","hub"];
EXAMPLES[7727]=["Our feud traces back to our childhood.","私達の不和は子供時代にまでさかのぼる。","feud"];
EXAMPLES[7729]=["Petals lie on the surface of the water.","花びらが水面に浮かんでいる。","Petals"];
EXAMPLES[7730]=["Then, the train screeched to a halt.","そして、電車はキーッという音を立てて止まった。","screeched"];
EXAMPLES[7731]=["The left eyelid is twitching.","左のまぶたがぴくぴくする。","twitching"];
EXAMPLES[7735]=["The president and his entourage were injured.","社長とその取り巻きが怪我をした。","entourage"];
EXAMPLES[7736]=["As for the accusations of heresy, here the evidence is much weaker.","異端という非難に関しては、ここでの証拠ははるかに弱いものである。","heresy"];
EXAMPLES[7740]=["I would like to sit in the non-smoking section.","禁煙席をお願いします。","sit in"];
EXAMPLES[7742]=["My lower abdomen feels bloated.","下腹部が張ります。","abdomen"];
EXAMPLES[7743]=["The doctor analyzed the blood sample for anemia.","医者は貧血の検査をするためサンプルを分析した。","anemia"];
EXAMPLES[7744]=["Clean out the room in the morning.","午前中に部屋をきれいに掃除しなさい。","Clean out"];
EXAMPLES[7749]=["One day in 1906, a newspaper cartoonist named Tad Dorgan went to a baseball game.","１９０６年のある日、タッド・ドーガンという名の新聞漫画家が野球の試合を見に行った。","Tad"];
EXAMPLES[7750]=["For gall bladder surgery, go down this hall and take a right.","胆のうの手術でしたら、この廊下をずっと行って右に曲がってください。","gall"];
EXAMPLES[7753]=["That man is Perry Mason, the lawyer.","あの男は弁護士のペリー・メースンだ。","Mason"];
EXAMPLES[7755]=["He was weak enough to succumb to temptation.","彼はもろくも誘惑に負けた。","succumb"];
EXAMPLES[7756]=["The Japanese archipelago is struck by a terrible heat wave.","日本列島は酷暑に苛まれている。","archipelago"];
EXAMPLES[7758]=["Is his failure ascribable to incompetence or to bad luck?","彼の失敗は無能によるものかそれとも不運によるものか。","incompetence"];
EXAMPLES[7759]=["The Imari porcelain plate that my father cherished was quite heavy.","祖父が大事にしていた伊万里焼の皿は、ずっしりと重かった。","porcelain"];
EXAMPLES[7760]=["Between the head and the torso is the neck.","頭と胴体の間に首がある。","torso"];
EXAMPLES[7765]=["Many men went west in search of gold.","金を探し求めて大勢の人々が西にむかった。","in search of"];
EXAMPLES[7766]=["Hypocrisy is the homage that vice pays to virtue.","偽善とは悪徳が徳に対して払う忠順の誓いである。","homage"];
EXAMPLES[7767]=["This job gives me the hump.","この仕事には憂鬱になる。","hump"];
EXAMPLES[7768]=["He showed me the way to the ballpark.","彼は私に球場への道を教えてくれた。","ballpark"];
EXAMPLES[7769]=["There were several hundred people in the plaza.","広場には数百人の人がいた。","plaza"];
EXAMPLES[7771]=["My grandpa believes that the moon landing was a hoax.","私の祖父は月面着陸のことが信じられない。","hoax"];
EXAMPLES[7773]=["He vindicated his honor.","彼は汚名をそそいだ。","vindicated"];
EXAMPLES[7774]=["He was put under anesthesia.","彼は麻酔をかけられた。","anesthesia"];
EXAMPLES[7775]=["Is it possible to send mourning clothes to the cleaner?","喪服をクリーニングに出せますか？","mourning"];
EXAMPLES[7777]=["It is dangerous to wield an edged tool in such a way.","そのように刃物を振り回すことは危険だ。","wield"];
EXAMPLES[7780]=["They sabotaged my effort to make our class enjoyable.","みんなはクラスを楽しくするための私の努力をけなした。","sabotaged"];
EXAMPLES[7785]=["A mirage is said to be an illusion.","蜃気楼は幻影だと言われている。","mirage"];
EXAMPLES[7786]=["It was ordered that the classroom be put in order.","教室を整理整頓するようにと命じられた。","put in"];
EXAMPLES[7788]=["He is a psycho.","彼はサイコだ。","psycho"];
EXAMPLES[7789]=["They look up to him as their benefactor.","彼らは彼を恩人として尊敬している。","benefactor"];
EXAMPLES[7790]=["His study of optics led him to the invention of the magnifying glass.","光学の研究で彼は拡大鏡の発明をした。","optics"];
EXAMPLES[7794]=["She rides to the black sabbath.","女は悪魔の宴へと向かう。","sabbath"];
EXAMPLES[7796]=["The oracle was fulfilled.","神託は実現した。","oracle"];
EXAMPLES[7797]=["What is there a corpus maintainer for?","コーパス整備員って、何のためにいるんですか？","corpus"];
EXAMPLES[7800]=["Leadership by coercion would not produce the results we see.","脅しによるリーダーシップは、いまぼくたちが目にするような結果を生み出しはしない。","coercion"];
EXAMPLES[7801]=["What are you smirking at? Did something good happen?","なにニヤニヤしてるんだよ。何かいいことあったのか。","smirking"];
EXAMPLES[7802]=["Get your carcass out of here!","出ていけ。","carcass"];
EXAMPLES[7803]=["Let's stop the deterioration of the natural environment.","自然環境の悪化を阻止しましょう。","deterioration"];
EXAMPLES[7804]=["Do you know Noah's ark?","あなたはノアの箱舟を知っていますか。","ark"];
EXAMPLES[7805]=["The cast was given a standing ovation.","出演者一同は観客からたちあがっての大かっさいを受けた。","ovation"];
EXAMPLES[7810]=["The law enables us to receive an annuity.","その法律は我々に年金を受け取る権利を与えている。","annuity"];
EXAMPLES[7812]=["True bravery is quite another thing from bravado.","本当の自信と空威張りは別問題だ。","bravado"];
EXAMPLES[7813]=["We all grew up in the same orphanage.","僕たちはみんな、同じ孤児院で育ったんだ。","orphanage"];
EXAMPLES[7818]=["They beat the dog to a pulp.","彼らはその犬をめったうちにした。","pulp"];
EXAMPLES[7819]=["That man is a heavy debtor.","あの男の人は多重債務者である。","debtor"];
EXAMPLES[7820]=["He mentioned the matter of the banquet.","彼は宴会の事について触れた。","banquet"];
EXAMPLES[7821]=["She had the decency to apologize.","謝るぐらいの礼儀は彼女も心得ていた。","decency"];
EXAMPLES[7822]=["The storm caused a power outage.","嵐で停電した。","outage"];
EXAMPLES[7825]=["Money does not grow on trees.","金は木に生えない。","grow on"];
EXAMPLES[7826]=["She received a doctorate.","彼女は博士号を取得した。","doctorate"];
EXAMPLES[7829]=["The end of my probation period is nearing.","私の試用期間は終わりに近づいてきている。","probation"];
EXAMPLES[7833]=["The speaker swaggered into the lecture hall.","演説者はふんぞり返って講堂に入っていった。","swaggered"];
EXAMPLES[7834]=["Put out the candle. The blackout is over.","ろうそくを消して下さい。停電は終わりました。","blackout"];
EXAMPLES[7835]=["They buried him in the graveyard by the church.","彼らは彼を教会の近くの墓地に埋葬した。","graveyard"];
EXAMPLES[7837]=["There was a tense atmosphere in the room.","部屋には切迫した空気がみなぎっていた。","tense"];
EXAMPLES[7838]=["However the protagonist is aware of his own mistakes.","しかし、主人公は自らの誤りに気づいている。","protagonist"];
EXAMPLES[7839]=["The orchardist grafted an apple bud onto the rootstock.","果樹栽培者がリンゴの接ぎ穂を台木に接ぎ木しました。","grafted"];
EXAMPLES[7840]=["These small rodents store up nuts in the winter.","この齧歯動物は冬に木の実を貯える。","rodents"];
EXAMPLES[7844]=["I caught a glimpse of the phantom sitting behind the wheel.","車を運転している幽霊を見た。","phantom"];
EXAMPLES[7848]=["Schrodinger's equation describes the time evolution of quantum mechanics.","シュレーディンガー方程式は量子力学系の時間発展を記述する。","quantum"];
EXAMPLES[7849]=["Is it a butterfly or a moth?","それは蝶ですか、それとも蛾ですか。","moth"];
EXAMPLES[7855]=["Notwithstanding their own repeated scandals, the police continue to nonchalantly issue infringement tickets.","相次ぐ不祥事にも関わらず、警察はオメオメ違反切符を切っている。","infringement"];
EXAMPLES[7858]=["A clever rabbit has three burrows.","賢いウサギは、３つの住処を持っている。","burrows"];
EXAMPLES[7859]=["My sons are in the heyday of youth.","息子たちは若い盛りだ。","heyday"];
EXAMPLES[7861]=["They were on the lookout for a storm.","彼らは嵐を警戒していた。","lookout"];
EXAMPLES[7866]=["The boy has good reflexes.","その少年は運動神経が発達している。","reflexes"];
EXAMPLES[7867]=["Signs of social unrest are mounting.","社会不安の兆候が高まりつつある。","mounting"];
EXAMPLES[7868]=["Tracing a renegade's family background, you'll find him the black sheep.","裏切り者の素性を追ってみれば、その裏切り者が家族の厄介者だとわかるでしょう。","renegade"];
EXAMPLES[7870]=["Incest is a taboo found in almost all cultures.","近親相姦はほとんど全ての文化において禁忌とされている。","Incest"];
EXAMPLES[7874]=["What is the breadth of this road?","この道の幅はどれくらいですか。","breadth"];
EXAMPLES[7875]=["Tom got a firearm.","トムは銃を手に入れた。","firearm"];
EXAMPLES[7876]=["The couch is in the foreground next to the table.","ソファーは写真前方にあってテーブルの脇にある。","foreground"];
EXAMPLES[7877]=["By definition the fact it’s depression means it’ll be an acquittal.","うつ病だから，何を言っても無罪放免さ。","acquittal"];
EXAMPLES[7878]=["The crime of adultery was abolished in 1947.","昭和２２年に姦通罪は廃止されました。","adultery"];
EXAMPLES[7881]=["They filled the jug to the brim.","彼らは水瓶を縁まで一杯にした。","jug"];
EXAMPLES[7882]=["Our topic of the week is intolerance.","今週の話題は「不寛容さ」についてです。","intolerance"];
EXAMPLES[7883]=["She always has some axe to grind.","彼女はいつも人に対してやいばをといでいます。","axe"];
EXAMPLES[7885]=["In spring, I look forward to rendezvous with many people!","春には、たくさんの出会いが待っている！","rendezvous"];
EXAMPLES[7886]=["Dogs bark when the caravan passes by.","犬は吠えても隊商は進む。","caravan"];
EXAMPLES[7887]=["The small thug beat up the convenience store employee.","チンピラがコンビニの店員をぶちのめした。","thug"];
EXAMPLES[7888]=["According to the Opium Control Act, the cultivation or possession of opium is prohibited.","あへん法により、ケシの栽培や所持等は禁止されています。","cultivation"];
EXAMPLES[7889]=["That village is the enemy's last stronghold.","あの村が敵の最後の牙城です。","stronghold"];
EXAMPLES[7890]=["Tom keeps Mary on a short leash.","トムはメアリーを束縛してるんだ。","leash"];
EXAMPLES[7891]=["Socrates was accused of atheism because he did not believe in Zeus.","ソクラテスは主神ゼウスを信じなかったので無神論の罪に問われた。","atheism"];
EXAMPLES[7895]=["A black limo rounded the corner with a squeal of tires.","黒塗りのリムジンがキーというタイヤの音と共に角を曲がった。","squeal"];
EXAMPLES[7896]=["Tom was a homicide detective before he retired.","トムさんが退職するまで、殺人担当刑事でした。","homicide"];
EXAMPLES[7897]=["The new machine will be in use.","その新しい機械が用いられるようになるだろう。","in use"];
EXAMPLES[7901]=["Good health is inseparable from exercise and moderation.","健康は運動と節制と不可分の関係にある。","moderation"];
EXAMPLES[7902]=["You should stockpile necessary supplies in case of a big earthquake.","大地震にそなえて必要なものを用意しておかなければならない。","stockpile"];
EXAMPLES[7903]=["This school is the flagship of the university.","この学部は大学の主力学部です。","flagship"];
EXAMPLES[7905]=["A burning meteoroid produces a meteor.","隕石が燃えて、流星となる。","meteor"];
EXAMPLES[7906]=["The informants we used consisted of twenty Americans and twenty-one British.","インフォーマントはアメリカ人２０人、イギリス人２１人という構成である。","informants"];
EXAMPLES[7911]=["The dog snarled at the salesman.","犬はセールスマンに噛み付いた。","snarled"];
EXAMPLES[7912]=["Those gloom and doom economists aren't worth their salt.","あんな悲観的な経済学者たちの言うことなんか、全然当てにならないよ。","gloom"];
EXAMPLES[7915]=["I am allergic to pollen.","私は花粉アレルギーだ。","pollen"];
EXAMPLES[7918]=["All of the money in the cupboard was stolen.","戸棚の中の金はみんな盗まれた。","cupboard"];
EXAMPLES[7919]=["You should go about your business.","君は仕事に精を出すべきだ。","go about"];
EXAMPLES[7921]=["Add water and stir to a paste.","水を加えてペースト状になるまでかき回しなさい。","paste"];
EXAMPLES[7923]=["It's the tip of the iceberg.","氷山の一角だよ。","iceberg"];
EXAMPLES[7924]=["He saw himself as the savior of the world.","彼は自分が救世主だとかんがえた。","savior"];
EXAMPLES[7926]=["I cook, but I'm really crap at it.","私は料理をしますが、とんでもなく下手くそです。","crap"];
EXAMPLES[7927]=["I get hives when I eat eggs.","卵を食べるとじんましんが出ます。","hives"];
EXAMPLES[7928]=["Tom isn't a pediatrician.","トムは小児科の先生じゃないよ。","pediatrician"];
EXAMPLES[7930]=["The teacher exhorted his pupils to do well.","教師は生徒に善行をするように説き勧めた。","exhorted"];
EXAMPLES[7932]=["My French is shitty.","フランス語がうまく話せません。","shitty"];
EXAMPLES[7935]=["This was faulty information.","その情報には誤りがあった。","faulty"];
EXAMPLES[7936]=["The water in the lake is murky.","湖の水は濁っている。","murky"];
EXAMPLES[7940]=["The Japanese are highly receptive to new ideas.","日本人は新しい思想を非常に良く取り入れる。","receptive"];
EXAMPLES[7942]=["Lilies are perennial plants.","ユリは多年草です。","perennial"];
EXAMPLES[7944]=["She's a precocious one eh?","彼女はちょっとおませさんだね。","precocious"];
EXAMPLES[7946]=["This word conjures up a new way of life.","この言葉は新しい生活様式を想定させる。","conjures"];
EXAMPLES[7947]=["He has galvanized back to life.","彼は元気を取り戻した。","galvanized"];
EXAMPLES[7950]=["She wanted desperately to get her vengeance.","彼女はなんとかして復讐しようと焦っていた。","vengeance"];
EXAMPLES[7952]=["It sounds a bit goofy.","ちょっとお間抜けな感じね。","goofy"];
EXAMPLES[7956]=["Computer technology is indispensable to access many pertinent items of data.","データの多数の関係項目にアクセスするにはコンピューター・テクノロジーが不可欠である。","pertinent"];
EXAMPLES[7958]=["That's to me like a flower on lofty heights.","そんなことは私には高嶺の花です。","lofty"];
EXAMPLES[7959]=["A red light was glowing in the dark.","暗闇で赤いライトが光っていた。","glowing"];
EXAMPLES[7960]=["Therein lies the problem.","そこに問題がある。","Therein"];
EXAMPLES[7961]=["I had a cerebral contusion.","私は脳挫傷を起こした。","cerebral"];
EXAMPLES[7962]=["She abetted him in escaping from prison.","彼女は彼をそそのかして刑務所から脱走させた。","abetted"];
EXAMPLES[7964]=["There is an anteroom adjoining the library.","書斎の隣に控えの間がある。","adjoining"];
EXAMPLES[7965]=["Our departure tomorrow is contingent on fair weather.","我々が明日出発するかどうかは天候次第です。","contingent"];
EXAMPLES[7967]=["Please take all of your medicine as prescribed.","お薬は処方された通りに飲みきってくださいね。","prescribed"];
EXAMPLES[7969]=["A flight attendant was rescued from the wreckage of the passenger plane.","スチュワーデスが旅客機の残骸から救出された。","wreckage"];
EXAMPLES[7970]=["Tom flopped down on his bed.","トムはベッドにごろりと寝転がった。","flopped"];
EXAMPLES[7971]=["The speaker tried to incite the people to rebellion.","演説者は民衆をそそのかして反乱を起こさせようとした。","incite"];
EXAMPLES[7976]=["Thus, the tyrant succeeded in conquering the kingdom.","このようにして、暴君はその王国の征服に成功した。","tyrant"];
EXAMPLES[7980]=["She fumbled with a piece of paper.","あやふやな手つきで一枚の紙を動かした。","fumbled"];
EXAMPLES[7985]=["I've spoken amply about the project.","その企画については詳しく話した。","amply"];
EXAMPLES[7987]=["We need example sentences that include slang, casual conversation, and unconventional inflectional endings.","スラングやフランクな会話、独特な短縮語尾まで含めた例文が必要です。","unconventional"];
EXAMPLES[7988]=["He is writing to some friends of his.","彼は何人かの友人に手紙を書いています。","writing"];
EXAMPLES[7989]=["I'm rather hesitant about asking him a favor.","あの人に頼むのはちょっと気が進まない。","hesitant"];
EXAMPLES[7991]=["Or are there photographs so obscene that you can't publish them?","それとも、あまりに猥褻な写真があるから出版できないということか？","obscene"];
EXAMPLES[7992]=["With JAL tickets so expensive, expatriates flew Air Iraq.","日航のチケットがあまりにも高いので、国外在住者たちはイラク航空をつかった。","expatriates"];
EXAMPLES[7994]=["They exulted over the defeat of their enemies.","彼らは敵を破って大喜びした。","exulted"];
EXAMPLES[7995]=["She is coy with everyone.","彼女は誰の前でもうぶなまねをする。","coy"];
EXAMPLES[7997]=["They did not wish to become embroiled in the dispute.","彼らはその紛争に巻き込まれたくないと思った。","embroiled"];
EXAMPLES[8001]=["The mast broke and our ship went adrift.","マストが折れて僕たちの船は漂流し始めた。","adrift"];
EXAMPLES[8004]=["He has gleaned knowledge from various books.","彼はいろいろな本から知識を拾い集めた。","gleaned"];
EXAMPLES[8005]=["While she was screaming, she brandished the knife.","彼女は叫びながら、ナイフを振り回しました。","brandished"];
EXAMPLES[8006]=["That exercise is good for the abdominal muscles.","その運動は腹筋に良い。","abdominal"];
EXAMPLES[8007]=["He gave me a curt answer.","彼はけんもほろろな返事をした。","curt"];
EXAMPLES[8008]=["Let's have a talk over a couple of drinks.","ちょっといっぱいやりながら話そう。","talk over"];
EXAMPLES[8011]=["The annex is on the north of the original building.","別館は本館の北側にある。","annex"];
EXAMPLES[8014]=["Father was generous enough to indulge my every whim.","父は寛大だったので、私の気まぐれもすべて満たしてくれた。","whim"];
EXAMPLES[8015]=["The fresh leaves are rampant.","若葉が茂る。","rampant"];
EXAMPLES[8019]=["Your story doesn't corroborate what I've heard before.","君の話は前に聞いた話と矛盾している。","corroborate"];
EXAMPLES[8022]=["Skinflicks usually play in old theaters in a sleazy part of town.","ポルノ映画はたいてい町のみすぼらしい所にある古びた映画館で上映される。","sleazy"];
EXAMPLES[8023]=["He forestalled everybody in accomplishing.","彼は抜けがけの功名をたてた。","forestalled"];
EXAMPLES[8028]=["I must replace that fluorescent lamp.","そこの蛍光灯を交換しないといけない。","fluorescent"];
EXAMPLES[8029]=["We have completely outstripped the other companies.","私どもは完全に他社を引き離していますよ。","outstripped"];
EXAMPLES[8030]=["I hum a tune as I clean up.","歌を口ずさみながら掃除をする。","hum"];
EXAMPLES[8033]=["It began to drizzle.","小雨が降り始めました。","drizzle"];
EXAMPLES[8039]=["The priest pretends to be solemn in public.","その聖職者は人前では真面目なふりをする。","solemn"];
EXAMPLES[8042]=["In the end, he also faltered in the face of great adversity.","ついに彼も強い反対に折れた。","faltered"];
EXAMPLES[8043]=["His brazen act of defiance almost cost him his life.","その恥知らずな抵抗活動のために、彼は危うく命を失いかけた。","brazen"];
EXAMPLES[8044]=["I bury my face in the fluffy belly.","フワフワしたお腹に顔を埋める。","fluffy"];
EXAMPLES[8045]=["As the sun rose, the stars faded away.","日が昇るのにつれて星は消えていった。","faded"];
EXAMPLES[8048]=["The Amazon River meanders through northern Brazil.","アマゾン川は延々と北ブラジルを流れている。","meanders"];
EXAMPLES[8049]=["I can not feel at home in a luxurious hotel.","私は豪華なホテルでは落ち着かない。","luxurious"];
EXAMPLES[8051]=["I am not sanguine that the negotiations will succeed.","交渉がうまくいくだろうとは楽観していない。","sanguine"];
EXAMPLES[8052]=["The enemy was entrenched all around the capital.","敵軍は首都の周囲を塹壕で固めていた。","entrenched"];
EXAMPLES[8054]=["These solvents, due to their volatility, evaporate into the atmosphere when used.","これらの溶剤は、揮発性のため、使用時に蒸発し大気に放出されている。","volatility"];
EXAMPLES[8055]=["He is not such a man as to flinch from danger.","彼は危険から尻込みするような人ではない。","flinch"];
EXAMPLES[8057]=["Have you had a thorough medical checkup within the last year?","昨年のうちに、徹底的な健康診断をしてもらいましたか。","medical checkup"];
EXAMPLES[8063]=["Tom is scrupulous in matters of business.","トムは仕事のことでは真っ正直だ。","scrupulous"];
EXAMPLES[8064]=["Stop listening to this crappy music.","こんなくだらない曲を聴くのは、止せ。","crappy"];
EXAMPLES[8065]=["Tom was drenched from head to toe.","トムは全身ずぶ濡れだった。","drenched"];
EXAMPLES[8068]=["The mountains are a lush green in summer.","夏の山では目に見えるものはすべて緑一色です。","lush"];
EXAMPLES[8071]=["Keiko deftly piles up the dishes and takes them to the sink.","恵子が手際よく食器を重ねて、シンクへ運んでゆく。","deftly"];
EXAMPLES[8072]=["He has a nimble mind.","彼は頭の働きが早い。","nimble"];
EXAMPLES[8074]=["Benefits accrue to the community from reconstruction.","再開発によって地域に便益が生ずる。","accrue"];
EXAMPLES[8075]=["Love your parents as dearly as your parents love you.","親があなたを思うのと同じように親を思いなさい。","dearly"];
EXAMPLES[8077]=["Our managing director is incompatible with the president.","専務は社長とうまくいっていない。","incompatible"];
EXAMPLES[8078]=["This problem is the clash of the idol's and obsessive fan's egos.","この問題は、アイドルのエゴとヲタのエゴの衝突だ。","obsessive"];
EXAMPLES[8080]=["Man is as fickle as autumn weather.","男心と秋の空。","fickle"];
EXAMPLES[8081]=["The stone was inscribed with the date of his death.","その石には彼の命日が刻まれていた。","inscribed"];
EXAMPLES[8085]=["These charred bits are tasty.","この焦げ目が美味しいんだよね。","charred"];
EXAMPLES[8087]=["Fully booked for the night, the hotel had to turn away some late guests.","ホテルはその夜、満員だったので、遅い客は何人か断らざるをえなかった。","turn away"];
EXAMPLES[8088]=["A hideous monster used to live there.","以前恐ろしい怪物が住んでいた。","hideous"];
EXAMPLES[8093]=["Try not to speak on speculative things.","臆測でものを言わないようにしないとね。","speculative"];
EXAMPLES[8094]=["As a child, Tom dreamt of being a vet.","トムは子どもの頃、獣医になるのが夢だった。","vet"];
EXAMPLES[8095]=["I'm afraid I'm frigid.","不感症のようです。","frigid"];
EXAMPLES[8097]=["An adult flounder has both eyes on the same side of its face.","ヒラメの成魚は、顔の片側に両目があります。","flounder"];
EXAMPLES[8098]=["They aligned themselves with the Liberals.","彼らは自由党員たちと同盟した。","aligned"];
EXAMPLES[8099]=["Our club is affiliated with an international organization.","我々のクラブは国際的な組織に加入した。","affiliated"];
EXAMPLES[8105]=["Concerning the characteristics of respiratory function in swimmers.","泳者の呼吸機能の特性について。","respiratory"];
EXAMPLES[8110]=["My wrath shall far exceed the love I ever bore.","私の怒りは私がいだき続けた愛を遥かに上回るだろう。","wrath"];
EXAMPLES[8111]=["Your eyes are like corals, dazzling and very pretty.","君の目はまるでサンゴのよう。ギラギラしていて、とてもきれい。","dazzling"];
EXAMPLES[8112]=["His knee turned a ghastly blackish purple from the swelling.","彼の膝は腫れてぞっとするような黒紫色になってしまった。","ghastly"];
EXAMPLES[8113]=["I have known intimately a great many persons who were absorbed in the arts.","芸術に没頭しているとてもたくさんの人たちとも懇意にしてきた。","intimately"];
EXAMPLES[8114]=["Tajima ... can't you talk a little bit more genteelly?","田島くん・・・。君はもう少し品のいい話はできないのか？","genteelly"];
EXAMPLES[8115]=["If you get bit by a rabid dog, you'll need a tetanus shot.","あなたは病犬に噛まれたら、破傷風の予防注射が必要となってしまいます。","rabid"];
EXAMPLES[8116]=["Now is the time to clinch the deal.","今こそ一気に取引をまとめるときだ。","clinch"];
EXAMPLES[8117]=["George III has been unfairly maligned by historians.","ジョージ３世は歴史家によって不当に悪し様に言われてきた。","maligned"];
EXAMPLES[8118]=["Light is quintessential. Light is life.","一番大切なのは光である。光は命。","quintessential"];
EXAMPLES[8119]=["The thief outwitted the police and got away with his loot.","泥棒は警官の裏をかいて盗品を持って逃げた。","loot"];
EXAMPLES[8120]=["Do Martians speak English?","火星人は英語をしゃべるんですか？","Martians"];
EXAMPLES[8121]=["Babies grow up inside the amniotic fluid in the womb.","赤ちゃんは子宮内の羊水で発育します。","womb"];
EXAMPLES[8122]=["You need not fret over such trifles.","そんなささいなことでクヨクヨするな。","fret"];
EXAMPLES[8123]=["His tone became more and more fervent.","彼の語調はますます熱気を帯びてきた。","fervent"];
EXAMPLES[8126]=["He is lavish with his money.","彼は金を惜しみなく使う。","lavish"];
EXAMPLES[8127]=["Disposable income is what counts for the level of personal consumption.","個人消費の水準にとって大きな意味を持つのは可処分所得である。","Disposable"];
EXAMPLES[8128]=["He groped for the doorknob in the dark.","彼は暗闇の中でドアの取っ手を手探りでさがした。","groped"];
EXAMPLES[8131]=["I prefer to err on the side of caution.","慎重にやって失敗するくらいのほうがいい。","err"];
EXAMPLES[8135]=["Take care not to intrude upon her privacy.","彼女のプライバシーに立ち入らないように注意しなさい。","intrude"];
EXAMPLES[8136]=["Parliament members had a raucous argument over the Wiretapping Law.","国会は、盗聴法案を巡ってまさに侃々諤々の体であった。","raucous"];
EXAMPLES[8137]=["He was mortified at his failure in business.","彼は事業の失敗を悔しがった。","mortified"];
EXAMPLES[8138]=["That is the park infested with perverts.","あそこは痴漢がよく出没する公園だ。","infested"];
EXAMPLES[8139]=["These days few people suffer from tuberculosis.","最近、肺結核を患う人はほとんどいない。","tuberculosis"];
EXAMPLES[8142]=["During his illness, he fell away horribly.","病気の間に彼はひどくやせた。","horribly"];
EXAMPLES[8143]=["We will be landing at Tokyo International Airport momentarily.","当機はまもなく東京国際空港に到着いたします。","momentarily"];
EXAMPLES[8144]=["I perceived an object looming through the mist.","ある物が霧の中にぼおっと見えるのに気づいた。","looming"];
EXAMPLES[8145]=["He managed to cure himself of his habit of nibbling his nails.","彼は爪を噛む癖をやっと直した。","nibbling"];
EXAMPLES[8146]=["Please activate your new password via email verification.","新パスワードはメール認証で有効化してください。","verification"];
EXAMPLES[8149]=["Insofar as we know, he is guilty.","我々の知る限りでは彼は有罪だ。","Insofar"];
EXAMPLES[8150]=["The wound is still oozing.","傷口はまだグジュグジュしています。","oozing"];
EXAMPLES[8152]=["What is that greasy stuff on your shirt?","シャツについている、べとべとしたものは何ですか。","greasy"];
EXAMPLES[8154]=["I drank ceremonial sake with gold leaf in it at the new year.","お正月には金箔入りのお神酒を頂きました。","ceremonial"];
EXAMPLES[8155]=["He truly is a prodigy.","彼は本当に神童である。","prodigy"];
EXAMPLES[8156]=["We'll have our firm's attorneys look through the provisional agreement.","社の弁護士に暫定合意の内容を吟味してもらおう。","provisional"];
EXAMPLES[8157]=["Tom is an extremist.","トムは過激な思想の持ち主だ。","extremist"];
EXAMPLES[8158]=["He pulled up the weed and threw it away.","彼は雑草をぬいて捨てた。","weed"];
EXAMPLES[8159]=["He is a poet worthy of the name.","彼はその名にふさわしい詩人だ。","worthy"];
EXAMPLES[8161]=["The policeman was on his usual nightly round.","巡査はいつものように夜間の巡回中だった。","nightly"];
EXAMPLES[8162]=["She was overshadowed by her sister's reputation.","彼女は妹の名声のために影がうすくなった。","overshadowed"];
EXAMPLES[8164]=["His backache left him lurching along with leaden legs.","腰の痛みから足が鉛のように重く引きずるように歩いていました。","lurching"];
EXAMPLES[8165]=["When there are no men around, the night is somewhat spooky.","全くオトコッケがないと夜なんぞは何だか気味が悪くってね。","spooky"];
EXAMPLES[8166]=["She is apprehensive of failure in the finals.","彼女は学年末試験に落ちたのではないかと心配している。","apprehensive"];
EXAMPLES[8168]=["Miss, that dress is splendid, it has a sheer silhouette and is very classy.","お客さま、そちらのドレスはすとんとしたシルエットがとても上品で素敵なんです。","classy"];
EXAMPLES[8169]=["Marriages are made in heaven and consummated on earth.","結婚は天上において行われ、床入りは地上において行われる。","consummated"];
EXAMPLES[8171]=["The employees demurred at working overtime.","従業員たちは超過勤務をするのに異議を唱えた。","demurred"];
EXAMPLES[8172]=["He fell into a slumber inadvertently.","彼はついうとうととした。","inadvertently"];
EXAMPLES[8174]=["A ragged coat may cover an honest man.","ぼろ服が正直者を包んでいるかもしれない。","ragged"];
EXAMPLES[8178]=["Will you please use indelible ink so the phrase won't rub out?","文句が消えないように、消えないインクを使ってくれませんか。","indelible"];
EXAMPLES[8179]=["I've come here today to talk about the dangers of proprietary software.","今回はプロプライエタリソフトウェアの危険性について話すべくに参りました。","proprietary"];
EXAMPLES[8180]=["He is an indispensable member for the staff.","そのスタッフにとって彼はなくてはならぬ存在だ。","indispensable"];
EXAMPLES[8181]=["Over time, the memories have leached from my mind.","時がたつにつれて、その記憶は私の心から溶け出していった。","leached"];
EXAMPLES[8184]=["Cheap imports will glut the market.","安い輸入品で市場が供給過剰になるだろう。","glut"];
EXAMPLES[8186]=["The claim from the employee about wages may be abrasive to the employer.","賃金に対する従業員の不満は、経営者には耳が痛かろう。","abrasive"];
EXAMPLES[8187]=["You will debase yourself with such behavior.","そんなふるまいをすると安く見られますよ。","debase"];
EXAMPLES[8188]=["They were stunned after finding out about his resignation.","彼の辞任を知って、彼らは呆然とした。","stunned"];
EXAMPLES[8189]=["They argue that the distribution of wealth should be equitable.","富の分配は公平でなければならないと彼らは言う。","equitable"];
EXAMPLES[8196]=["The boomerang hurtled whistling through the air.","ブーメランは音を立てて空中を飛んだ。","hurtled"];
EXAMPLES[8197]=["His study of optics led him to the invention of the magnifying glass.","光学の研究で彼は拡大鏡の発明をした。","optics"];
EXAMPLES[8200]=["The garrison was forced to surrender.","守備隊は降伏を強いられた。","garrison"];
EXAMPLES[8205]=["Tom didn't use a cake mix. He made it from scratch.","トムはケーキミックスを使ってないんだ。一から作ったんだよ。","from scratch"];
EXAMPLES[8208]=["The minister had to face a barrage of questions from the press.","大臣は新聞記者たちからの矢継ぎ早の質問に直面しなくてはならなかった。","barrage"];
EXAMPLES[8212]=["The room is cluttered with newspapers.","部屋には新聞がいっぱい散らかっている。","cluttered"];
EXAMPLES[8214]=["A rolling stone gathers no moss.","転石苔を生ぜず。","moss"];
EXAMPLES[8216]=["Auctions are annoying, so I bought it instantly with a buyout.","オクは面倒なので即決で一回買っただけ。","buyout"];
EXAMPLES[8217]=["He died from acute lymphoblastic leukemia.","彼は急性リンパ性白血病で死亡しました。","leukemia"];
EXAMPLES[8218]=["Nitrous oxide stopped being used as an anaesthetic a long time ago.","亜酸化窒素は麻酔としてもはや使用されていない。","oxide"];
EXAMPLES[8220]=["Witch hazel tightens pores without drying skin.","ウィッチヘーゼルは、乾燥させずに毛穴を引き締めます。","pores"];
EXAMPLES[8221]=["The accident happened because of the driver's negligence.","その事故は運転手の不注意から起きた。","negligence"];
EXAMPLES[8222]=["Books written in braille are very important for people with visual impairments.","点字で書かれた本は、目の不自由な人にとってとても大切です。","braille"];
EXAMPLES[8224]=["The documents were tampered with.","書類は勝手にいじられた形跡があった。","tampered"];
EXAMPLES[8226]=["More women than men commit perjury.","男性よりも女性のほうが偽証罪を犯す。","perjury"];
EXAMPLES[8227]=["Frankly speaking, he is wrong.","はっきり言って、彼は間違っている。","Frankly speaking"];
EXAMPLES[8228]=["I'd like to reserve a sleeping berth.","寝台車を予約したいのですが。","berth"];
EXAMPLES[8230]=["This letter purports to be his resignation.","この手紙で彼は辞意を表明している。","purports"];
EXAMPLES[8231]=["It was a good luncheon, as hotels go.","世間一般のホテルなみにいえば良い昼食会だった。","luncheon"];
EXAMPLES[8232]=["A brilliant, seductive chef turns to espionage in Napoleon-era France.","ナポレオン時代のフランス、卓越した才能で魅了するシェフがスパイに転じる。","espionage"];
EXAMPLES[8235]=["You are truly an antidote for my melancholy.","本当に君のおかげで僕の憂うつは消し飛んでしまう。","antidote"];
EXAMPLES[8237]=["They say it's on the wane, but it's still got something, hasn't it?","落ち目って言うけど、まだイケるよね。","wane"];
EXAMPLES[8239]=["She was in an abyss of despair.","彼女は絶望のどん底にあった。","abyss"];
EXAMPLES[8245]=["At this time, we should wipe out crime and collusion.","この際、犯罪と癒着を一掃すべきです。","collusion"];
EXAMPLES[8246]=["The gradient of this hill is steep.","この坂の勾配が大きい。","gradient"];
EXAMPLES[8248]=["I have a stutter.","僕は吃音を持ってるんだ。","stutter"];
EXAMPLES[8253]=["This is a building used for combustion testing.","これは燃焼試験用の建物です。","combustion"];
EXAMPLES[8254]=["He is raising a big stink over a minor glitch.","彼はささいな故障に大騒ぎをしています。","glitch"];
EXAMPLES[8255]=["The levee kept the floodwater back.","堤防が洪水を防いだ。","levee"];
EXAMPLES[8257]=["An enormous number of insects hatched this year, wreaking havoc on crops.","今年は、おびただしい数の害虫が発生して、農作物に多大な被害が起きた。","wreaking"];
EXAMPLES[8258]=["There was no water and the flowers wilted.","水がなくて、花がしおれちゃった。","wilted"];
EXAMPLES[8260]=["It's just too good to pass up.","これは絶対見逃せないよ。","pass up"];
EXAMPLES[8264]=["Did you search every nook and cranny?","隅から隅まで探したの？","nook"];
EXAMPLES[8267]=["Peter applied to his boss for a raise.","ピーターは、昇給を願い出た。","Peter"];
EXAMPLES[8269]=["If you've got the time help out with our relative's work.","暇なら分家の仕事を手伝って来い。","help out"];
EXAMPLES[8270]=["A mouse scurried out of the hole.","ねずみが一匹、穴からちょこちょこ出てきた。","scurried"];
EXAMPLES[8271]=["I felt profound reverence for the courageous mother.","その勇敢な母親に私は深い崇敬の念をいだいた。","reverence"];
EXAMPLES[8272]=["A budget deficit will occur because of a revenue shortfall.","赤字が発生するのは歳入不足の結果です。","shortfall"];
EXAMPLES[8274]=["Setting a new record added luster to his name.","新記録を立てたことが彼の名声をさらに高めた。","luster"];
EXAMPLES[8275]=["We really thank you for your patronage.","日頃のご愛顧にお礼申し上げます。","patronage"];
EXAMPLES[8276]=["Please sponge the mess up off the table.","テーブルの汚れをスポンジでふき取って下さい。","mess up"];
EXAMPLES[8278]=["The proprietor of the store worked at the head of his employees.","店主は従業員の先頭に立ってはたらいた。","proprietor"];
EXAMPLES[8279]=["I have sinus trouble.","蓄膿症です。","sinus"];
EXAMPLES[8280]=["The children are clamoring to go to the zoo.","子供らは動物園に行きたいと言って騒いでいる。","clamoring"];
EXAMPLES[8283]=["The bandits made a raid on the village.","山賊がその村を襲った。","bandits"];
EXAMPLES[8284]=["No medicine can cure a man of discontent.","不平不満を治す薬はない。","discontent"];
EXAMPLES[8285]=["Why did you call me at this unearthly hour?","どうしてこんなとんでもない時間に電話をするのだ。","unearthly"];
EXAMPLES[8287]=["As yet he has not succeeded.","まだ彼は成功していない。","As yet"];
EXAMPLES[8288]=["The primates include not only the apes, but also man.","霊長類は尾の無いサルだけでなく人間も含む。","primates"];
EXAMPLES[8289]=["I put handcuffs on him.","私は彼に手錠をかけた。","handcuffs"];
EXAMPLES[8290]=["I am so exhausted because I have padded the hoof for 4 hours.","かなり疲れたよ、４時間も歩いたからさ。","hoof"];
EXAMPLES[8291]=["They reveled in the success of their sales.","彼らの販売の成功に大喜びした。","reveled"];
EXAMPLES[8292]=["It puts a different complexion on the situation.","それにより状況が変る。","complexion"];
EXAMPLES[8293]=["There were hundreds of taxis at the airport, all touting for business.","空港には数百台のタクシーがいて、皆客引きしていた。","touting"];
EXAMPLES[8295]=["The authorities sent in troops to quell the riot.","政府当局は暴動を鎮圧するために軍を出動させました。","quell"];
EXAMPLES[8299]=["The old man's narrative was punctuated by coughs.","おじいさんは、咳で何度も話を中断した。","punctuated"];
EXAMPLES[8301]=["Peter may need a new diaper.","ピーターは新しいオムツを必要としているのかもしれない。","diaper"];
EXAMPLES[8302]=["The whole town was in a ferment.","町中が大騒ぎをしていた。","ferment"];
EXAMPLES[8303]=["It's no use pleading because they'll never give in.","彼らは決して折れないだろうから弁解しても無駄だ。","pleading"];
EXAMPLES[8305]=["A nail punctured the tire.","釘が車のタイヤに刺さった。","punctured"];
EXAMPLES[8306]=["There was a fledgling bird there.","そこに羽の生えたばかりの小鳥がありました。","fledgling"];
EXAMPLES[8308]=["He had an old pickup truck and a big, battered mower.","彼は小型トラックとよれよれの大きな芝刈り機をもっていた。","mower"];
EXAMPLES[8313]=["The opposite sides of a rectangle are parallel.","長方形の対辺は平行である。","rectangle"];
EXAMPLES[8315]=["She got married in defiance of her father.","彼女は父の意に逆らって結婚した。","defiance"];
EXAMPLES[8316]=["A small forest fire quickly spread and became a huge conflagration.","小規模の森林火災はみるみる広がり大火災となった。","conflagration"];
EXAMPLES[8317]=["This is not a sham.","これはインチキじゃないよ。","sham"];
EXAMPLES[8318]=["The light of the lamp glimmered in the fog.","ランプの火が霧の中で瞬いた。","glimmered"];
EXAMPLES[8320]=["The fire that broke out last night was judged to be caused by arson.","昨晩の火事は放火と断定された。","arson"];
EXAMPLES[8327]=["The note is embossed with the school emblem.","その便せんには校章が打ち出しにされている。","emblem"];
EXAMPLES[8328]=["Even before Reagan and the Supreme Court stifled it, OSHA was a farce.","だが、レーガン政権と最高裁判所に潰される前でさえ、ＯＳＨＡは茶番であった。","farce"];
EXAMPLES[8331]=["Don't just sit there and fume. Tell me what's wrong.","ムスッとして座ってないで、何がいけないのか言えよ。","fume"];
EXAMPLES[8332]=["He has squandered every opportunity I've given him.","彼は私が与えてきたチャンスを全てふいにしてしまった。","squandered"];
EXAMPLES[8334]=["Though the enemy's defenses were strong, we tried to break through.","敵の防御は強力だったが我々は突破しようと試みた。","break through"];
EXAMPLES[8335]=["They say the gods smite evil with thunderbolts.","諸神は悪を雷で打つという。","smite"];
EXAMPLES[8336]=["I wonder what ear lobes are for.","耳たぶは何のためにあるのだろう？","lobes"];
EXAMPLES[8337]=["There were scribbles all along the wall.","その壁には一面に落書きがあった。","scribbles"];
EXAMPLES[8339]=["The embassy denied political asylum to foreign refugees.","大使館は外国人難民の政治亡命を拒否しました。","asylum"];
EXAMPLES[8340]=["Tom isn't the type to hold a grudge.","トムは根に持つタイプではない。","grudge"];
EXAMPLES[8341]=["Don't swallow that slick propaganda.","そのうまい宣伝に乗るな。","slick"];
EXAMPLES[8343]=["This is the perfect place for an ambush.","ここは待ち伏せするには、もってこいの場所だよ。","ambush"];
EXAMPLES[8348]=["We deal in silk goods.","我々は絹織物を商っている。","deal in"];
EXAMPLES[8351]=["The police brawled with the demonstrators.","警官隊はデモ隊と乱闘になった。","brawled"];
EXAMPLES[8355]=["She hasn't got the knack of cooking yet.","彼女はまだ料理のコツを覚えていない。","knack"];
EXAMPLES[8360]=["She is a lady of business acumen.","彼女は鋭い商才の持ち主だ。","acumen"];
EXAMPLES[8362]=["Rock breaks scissors. Scissors cut paper. Paper smothers rock.","グーがチョキに、チョキがパーに、パーはグーに勝つ。","smothers"];
EXAMPLES[8367]=["Leaders are trying to do away with impediments to economic growth.","首脳たちは経済成長に障害となるものを排除しようとしています。","impediments"];
EXAMPLES[8368]=["I pawned my guitar to pay the rent.","私は家賃を払うために、ギターを質にいれた。","pawned"];
EXAMPLES[8369]=["How many people are there on the payroll?","何人の従業員が雇用されていますか。","payroll"];
EXAMPLES[8370]=["Tom has his quirks.","トムは一癖ある。","quirks"];
EXAMPLES[8371]=["She makes me melt when she pampers me.","彼女に甘えられると弱いんだ。","pampers"];
EXAMPLES[8373]=["The airport is close at hand.","空港はすぐ近くにあります。","at hand"];
EXAMPLES[8375]=["Here contemporary particle physics is pretty much at an impasse.","ここにきて、現代素粒子物理学の先行きがかなり怪しくなった。","impasse"];
EXAMPLES[8377]=["Some early religion's leaders were persecuted by their enemies.","初期の宗教指導者の中には敵対する人々に迫害されたものもいる。","persecuted"];
EXAMPLES[8378]=["Tom always dreamed of becoming a bounty hunter.","トムは常々、賞金稼ぎになりたいと夢見ていた。","bounty"];
EXAMPLES[8379]=["With 20/20 hindsight, he could tell why they lost the game.","今となっては後の祭りだったが、彼はどうして自分達が試合に負けたのかよくわかった。","hindsight"];
EXAMPLES[8380]=["Do you know the movie Avatar?","『アバター』って映画知ってる？","Avatar"];
EXAMPLES[8381]=["For a brat, you've said something very mature.","がきにしては、随分大人びたことを言ったな。","brat"];
EXAMPLES[8384]=["Can you wiggle your ears?","耳を自力で動かすことはできますか？","wiggle"];
EXAMPLES[8385]=["The allusion was not lost on me.","何のことをいっているのか私にはピンときた。","allusion"];
EXAMPLES[8386]=["We are trying to clarify your future procurement requirements.","お客様の今後の購買需要を明らかにしようとしています。","procurement"];
EXAMPLES[8388]=["The bribery scandal created a backlash overseas.","収賄スキャンダルは海外で激しい反発を生みました。","backlash"];
EXAMPLES[8390]=["Upon receiving your Certificate of Eligibility, please come to the Japanese Embassy in London.","在留資格認定証明書を貰って、ロンドンの日本大使館に来てください。","Eligibility"];
EXAMPLES[8392]=["Knowledge is like manure, it's only good when spread.","知識というものは肥料と同じで、広まってこそ良いのである。","manure"];
EXAMPLES[8394]=["Love is the bedrock of my life.","愛を基盤に生きている。","bedrock"];
EXAMPLES[8397]=["I always thought that suffering a heart attack was an omen of death.","私はいつも思っていた、心筋梗塞を患うことは死期を知らせる前兆だと。","omen"];
EXAMPLES[8398]=["The forest is teeming with monkeys.","猿がその森にはたくさんいる。","teeming"];
EXAMPLES[8400]=["This is a small acknowledgement of your kindness.","これはあなたの親切に対するささやかなお礼の印です。","acknowledgement"];
EXAMPLES[8404]=["Adversity makes a man wise, not rich.","艱難汝を玉にす。","Adversity"];
EXAMPLES[8409]=["The doctor sent the live patient to the morgue.","医者は患者を生きたまま霊安室へ送った。","morgue"];
EXAMPLES[8410]=["Tom and Ken are like peas in a pod.","トムとケンは瓜二つだ。","pod"];
EXAMPLES[8412]=["The trend of public opinion is against corporal punishment.","世論の趨勢は体罰反対の方向である。","corporal"];
EXAMPLES[8414]=["The town was deluged with tourists in summer.","夏には観光客がその町へどっと押し寄せた。","deluged"];
EXAMPLES[8415]=["The small intestine is about seven meters long.","小腸は７メートルくらいだ。","intestine"];
EXAMPLES[8424]=["The wholesalers might try to back out of the deal.","卸売り業者は取引から手を引こうとするかもしれません。","back out"];
EXAMPLES[8426]=["He devoted his whole life to compilation of the dictionary.","彼は生涯を辞書の編さんに費やした。","compilation"];
EXAMPLES[8428]=["It takes real guts to start a fight.","手ェ出すたぁ、いい度胸だ。","guts"];
EXAMPLES[8429]=["Love is like measles – everyone should experience it.","恋愛は、はしかのようなものだ。みんな一度はかからなければならない。","measles"];
EXAMPLES[8430]=["The townspeople were astonishingly naive about what the smugglers were.","町の人たちは密輸業者がしようと試みていたことに驚くほど無知だった。","smugglers"];
EXAMPLES[8431]=["I had a miscarriage last year.","去年流産しました。","miscarriage"];
EXAMPLES[8433]=["Can all university music students do things like sight reading and improvisation?","音大生はみんな初見とか即興とか得意なの？","improvisation"];
EXAMPLES[8435]=["They had no other recourse but to apologize.","彼らは謝るほかに方法がなかった。","recourse"];
EXAMPLES[8438]=["Becoming rivals in love caused the rupture of friendship.","恋愛が入ると、友情に亀裂が入ってしまうんだ。","rupture"];
EXAMPLES[8439]=["The more she spurns my love, the more it grows.","撥ね付けられるほどに増すわが思い。","spurns"];
EXAMPLES[8440]=["A new treatment for hepatitis is being studied.","肝炎の新しい治療法が研究されている。","hepatitis"];
EXAMPLES[8441]=["This is a pun.","これは駄洒落です。","pun"];
EXAMPLES[8444]=["That's just a cheap publicity stunt.","それは売名行為だ。","stunt"];
EXAMPLES[8446]=["Tom is truly free from inhibition.","トムって、本当に自由奔放ね。","inhibition"];
EXAMPLES[8449]=["The exposition will be held for six months.","博覧会の開催期間は６ヶ月です。","exposition"];
EXAMPLES[8451]=["He acted like a lunatic.","彼は狂人のように振る舞った。","lunatic"];
EXAMPLES[8458]=["There are many kinds of animals inside this enclosure.","この囲いの中には何種類もの動物がいます。","enclosure"];
EXAMPLES[8459]=["Don't think you'll always be able to placate me with food!","い、いっつも食べ物で懐柔されるとは、限りませんからねっ。","placate"];
EXAMPLES[8460]=["Lobbyists for the Bill funneled bribes into a campaign fund.","法案通過を推進しているロビイストは、運動資金に賄賂の金をまぎれこませました。","funneled"];
EXAMPLES[8461]=["A reward has been offered for information pertaining to the incident.","その事件に関する情報には賞金が出されている。","pertaining"];
EXAMPLES[8464]=["Japan seceded from the League of Nations in 1933.","日本は国際連盟から１９３３年に脱退した。","seceded"];
EXAMPLES[8466]=["I'll pay you back with my calculus notes.","お返しに微積分のノートを貸してあげるわ。","calculus"];
EXAMPLES[8468]=["Movie theaters are losing more and more revenue due to internet piracy.","映画館は、インターネット上に出回る違法コピーのせいで、収益をますます失いつつある。","piracy"];
EXAMPLES[8470]=["My kid is aggressive and is always making a ruckus.","うちの子はアグレッシブな子で、いつも騒音問題を起こすんですよ。","ruckus"];
EXAMPLES[8471]=["Lungs, heart, veins, arteries and capillaries form the cardiovascular system.","肺、心臓、静脈、動脈、毛細血管により循環器系が形成されています。","cardiovascular"];
EXAMPLES[8477]=["The Dodgers were annihilated by the Giants.","ドジャースはジャイアンツに完敗した。","annihilated"];
EXAMPLES[8480]=["Pay your dues to the treasurer.","料金は会計係へ払って下さい。","treasurer"];
EXAMPLES[8481]=["She consecrated her life to the work.","彼女はその仕事に一生を捧げた。","consecrated"];
EXAMPLES[8482]=["The bloated profits of farmers at the time were something again.","当時の農家の暴利はすさまじかった。","bloated"];
EXAMPLES[8484]=["First class plane flights come with complimentary alcohol.","飛行機のファーストクラスにはアルコールの無料サービスが含まれている。","complimentary"];
EXAMPLES[8489]=["There is a tinge of red in the eastern sky.","東の空が赤みを帯びている。","tinge"];
EXAMPLES[8493]=["I'm thinking about which college might be best for me.","どの大学が私にもっとも適しているかよく考えているところです。","best for"];
EXAMPLES[8495]=["Heavy smoking impaired his health.","彼はたばこの吸いすぎで体を壊した。","impaired"];
EXAMPLES[8498]=["I'm speechless before such a beautiful and stately palace.","きらびやかでいて重厚な宮殿を前に言葉も出ない。","stately"];
EXAMPLES[8499]=["I've never seen this shoddy of an excuse in my life.","こんな下手な言いわけ初めて見た。","shoddy"];
EXAMPLES[8501]=["Our eyes can't see infrared light.","私達の目は赤外線を見ることはできません。","infrared"];
EXAMPLES[8503]=["Autistic children don't know what boredom is.","自閉症の子供は飽きることを知らない。","Autistic"];
EXAMPLES[8506]=["It's easy to see the area's majestic topography from the cockpit of a helicopter.","ヘリコプターの運転席からなら、その地の素晴らしい地形を見渡すのは容易い。","majestic"];
EXAMPLES[8507]=["Those children are in exuberant spirits.","その子供たちは活気にあふれている。","exuberant"];
EXAMPLES[8515]=["We used emergency measures to revive the cardiac arrest patient.","心停止の患者を応急処置で生かした。","cardiac"];
EXAMPLES[8516]=["Her disappearance gave zest to the mystery.","彼女の失踪で謎が一段と面白くなった。","zest"];
EXAMPLES[8519]=["She boldly went up to the king.","彼女は臆することなく王の面前に出た。","boldly"];
EXAMPLES[8520]=["I wish for once I could be something.","一度でいい意味のある存在になりたいと願う。","for once"];
EXAMPLES[8523]=["The consumer price index has been fluctuating wildly.","消費者物価指数は激しく変動しています。","fluctuating"];
EXAMPLES[8526]=["Better short and sweet, than long and lax.","長くてだらしがないより短くて簡潔のほうがよい。","lax"];
EXAMPLES[8527]=["The luggage was very heavy, so the way back was grueling.","荷物があまりに重くて帰りがつらかった。","grueling"];
EXAMPLES[8529]=["Tom is very idiosyncratic.","トムは一癖も二癖もあるからな。","idiosyncratic"];
EXAMPLES[8531]=["What's New Zealand like? Is it as sparsely populated as Australia?","ニュージーランドはどんな所ですか。オーストラリアと同じように人口が散在していますか。","sparsely"];
EXAMPLES[8533]=["Relations are tenuous as peace talks resume between warring factions.","敵対勢力間の和平交渉再開だけに、関係は危うい。","tenuous"];
EXAMPLES[8535]=["The whereabouts of the suspect is still unknown.","容疑者の行方はまだ分からない。","whereabouts"];
EXAMPLES[8537]=["The tramp gobbled down the Thanksgiving dinner served at the church.","浮浪者は教会での感謝祭の夕食をがつがつ食べた。","gobbled"];
EXAMPLES[8539]=["Tea is like the lubricating oil of work to allow it to proceed smoothly.","お茶は仕事をスムーズに運ばせるための潤滑油のようなもの。","lubricating"];
EXAMPLES[8540]=["I am vigilant about things like that.","私、そういうところ目ざといのよ。","vigilant"];
EXAMPLES[8541]=["I was distraught over what to do because everything was going poorly.","何もかもうまくいかず、どうしていいか迷って苦悶した。","distraught"];
EXAMPLES[8543]=["England is synonymous with football, fish & chips, and the Queen.","英国と云えばサッカー、フィッシュアンドチップス、そして女王です。","synonymous"];
EXAMPLES[8545]=["His laziness boded ill for the future.","彼の怠惰は将来に対する悪い前兆だった。","boded"];
EXAMPLES[8546]=["Brass is an alloy of copper and zinc.","真鍮は銅と亜鉛の合金である。","zinc"];
EXAMPLES[8547]=["She is dogged by misfortune.","彼女には不幸が絶えない。","dogged"];
EXAMPLES[8549]=["This room has fine ventilation.","この部屋は風通しがよい。","ventilation"];
EXAMPLES[8551]=["My friend and I were separated in the jostle of the surging crowd.","人波にもまれて友人とはぐれた。","jostle"];
EXAMPLES[8553]=["This is a house that exudes an air of elegance.","これは上品な佇まいを漂わせた家だ。","exudes"];
EXAMPLES[8554]=["I was outwitted by Tom.","トムにしてやられたよ。","outwitted"];
EXAMPLES[8555]=["I'm not going to carelessly blurt out something that would cause trouble!","波紋を広げるようなことを安易に口走らないの！","blurt"];
EXAMPLES[8556]=["A good salesman will not encroach on his customer's time.","熟練したサラリーマンは時間をとらせないものだ。","encroach"];
EXAMPLES[8557]=["It is not white hair that engenders wisdom.","白髪が知恵を生み出すわけではない。","engenders"];
EXAMPLES[8561]=["The scandal detracted from his reputation.","そのスキャンダルが彼の評判を落とした。","detracted"];
EXAMPLES[8563]=["Today's trivia corner! Today it's about the origin of Calpis.","今日の豆知識コーナー！今日は「カルピス」の由来について。","trivia"];
EXAMPLES[8565]=["You are wearing your socks inside out.","靴下を裏返しにはいてるよ。","inside out"];
EXAMPLES[8568]=["Art is long, time is fleeting.","少年老い易く学成り難し。","fleeting"];
EXAMPLES[8573]=["Her striped dress accentuates her slimness.","縞柄の服で彼女のほっそりした姿が目立つ。","accentuates"];
EXAMPLES[8576]=["They assailed the new teacher with questions.","彼らは新しい教師を質問ぜめにした。","assailed"];
EXAMPLES[8581]=["The balcony juts out over the street.","そのバルコニーは通りに突き出している。","juts"];
EXAMPLES[8582]=["The rain fell relentlessly all day long.","雨が一日中絶え間なく降っていた。","relentlessly"];
EXAMPLES[8584]=["The senator charged that I had distorted the data.","上院議員は私がデータをゆがめたと告発した。","distorted"];
EXAMPLES[8586]=["He acceded to the office.","彼はその会社を継いだ。","acceded"];
EXAMPLES[8592]=["Have you ever done lewd things at a park?","公園でエッチなことしたことある？","lewd"];
EXAMPLES[8594]=["She kept an all-night vigil over her sick child.","彼女は病気の子供を徹夜で看病した。","vigil"];
EXAMPLES[8596]=["An eagle was soaring high up in the air.","鷲が一羽空高く飛んでいた。","soaring"];
EXAMPLES[8597]=["Her English was impeccable, I didn't think she was a foreigner.","彼女の英語は非の打ち所がなくて、まさか外国人だと思わなかった。","impeccable"];
EXAMPLES[8599]=["Tom believes in a patriarchal society.","トムは男尊女卑思想の持ち主だ。","patriarchal"];
EXAMPLES[8601]=["A long piece of thread easily becomes tangled up.","長い糸はからまりやすい。","tangled"];
EXAMPLES[8603]=["His honor was corroded by greed.","彼の名誉は貪欲によってむしばまれた。","corroded"];
EXAMPLES[8606]=["Berlin is located on the Spree river.","ベルリンは、シュプレー川沿いにあります。","Spree"];
EXAMPLES[8607]=["She's an outspoken person.","思ったことをズバズバ言うタイプだよ。","outspoken"];
EXAMPLES[8612]=["They are scant of money.","彼らは金が不足している。","scant"];
EXAMPLES[8613]=["As soon as he entered the classroom, our teacher burst into angry speech.","教室に入るなり、先生は突然怒ったような口調で話しはじめた。","burst into"];
EXAMPLES[8615]=["Transferring to the Keiyō Line from other lines at Tokyo Station is extremely cumbersome.","東京駅で他の路線から京葉線に乗り換えるのは非常に面倒くさい。","cumbersome"];
EXAMPLES[8618]=["Your English is flawless.","君の英語は完璧だ。","flawless"];
EXAMPLES[8619]=["He is adept at telling lies.","彼はうそつきの名人だ。","adept"];
EXAMPLES[8620]=["All that glitters is not gold.","光るものすべてが金ではない。","glitters"];
EXAMPLES[8623]=["He speaks with a lisp.","その子は舌足らずに話す。","lisp"];
EXAMPLES[8626]=["I will begin anew.","新たに始める。","anew"];
EXAMPLES[8627]=["It is conceivable that he knows the rumor.","おそらく彼はその噂を知っているだろう。","conceivable"];
EXAMPLES[8628]=["The sisters dueled with each other verbally.","姉妹はやっきになって言い争った。","verbally"];
EXAMPLES[8629]=["Where did we leave Tom's pacifier?","トムのおしゃぶり、どこやったっけ？","pacifier"];
EXAMPLES[8633]=["His smug behavior is offensive.","彼のきざな態度は頭にくる。","smug"];
EXAMPLES[8636]=["It was a manifest error of judgement.","それは明らかに判断の誤りだった。","manifest"];
EXAMPLES[8637]=["I abhor killing animals.","動物を殺すのはまっぴらだ。","abhor"];
EXAMPLES[8641]=["We can't wander around the park at night.","私たちは夜中に公園を散策するなんてできません。","wander"];
EXAMPLES[8643]=["Salt water is more buoyant than fresh water.","塩水の方が淡水よりも浮力が大きい。","buoyant"];
EXAMPLES[8644]=["We dissected a frog to examine its internal organs.","私たちは内臓器官を調べるためにカエルを解剖した。","dissected"];
EXAMPLES[8645]=["She looked at me seductively.","彼女は悩ましい目つきで僕を見た。","seductively"];
EXAMPLES[8647]=["The house was ablaze when the fire engine arrived.","消防車が到着したときには家は燃え上がっていた。","ablaze"];
EXAMPLES[8648]=["It aggrieved her much that she could not go.","彼女は自分が行けないことでたいそう悩んでいた。","aggrieved"];
EXAMPLES[8649]=["The jagged edge ripped a hole in his trousers.","ぎざぎざのかどが彼のズボンに引っかかって穴を空けた。","jagged"];
EXAMPLES[8650]=["My eyes feel gritty.","目がゴロゴロします。","gritty"];
EXAMPLES[8653]=["She refused to put up with her boisterous nephews anymore.","彼女はがさつな甥たちにこれ以上我慢しようとは思わなかった。","boisterous"];
EXAMPLES[8654]=["These girls, who're my pupils, have come to see me.","この少女たちは私の生徒なのですが、私に会いに来たのです。","who"];
EXAMPLES[8659]=["His boat was washed ashore on a desert island.","彼の船は無人島に漂流した。","ashore"];
EXAMPLES[8660]=["The village is insulated from the world.","その村は世間から孤立している。","insulated"];
EXAMPLES[8663]=["I'd like to have something to munch on with my beer.","ビールの摘まみがほしい。","munch"];
EXAMPLES[8666]=["By studying overseas, students can come into contact with other manners and customs.","海外で勉強することによって、学生は別の風俗習慣に触れることができる。","come into"];
EXAMPLES[8669]=["He is working intently.","彼は熱心に仕事をしている。","intently"];
EXAMPLES[8673]=["His foolish proposal was approved unanimously.","彼のばかげた提案が満場一致で承認された。","unanimously"];
EXAMPLES[8679]=["I had an intravenous drip in hospital.","私は病院で点滴を受けた。","intravenous"];
EXAMPLES[8680]=["How about consulting a doctor and getting sedatives prescribed?","医者に相談して鎮静剤を処方してもらうのはどうでしょうか。","sedatives"];
EXAMPLES[8682]=["The next discussion concerns the transplantation of prenatal tissues.","次の議論は出生前の組織移植に関するものである。","prenatal"];
EXAMPLES[8685]=["Don't be so glum about it. Life has its ups and downs.","人生沈む瀬あれば浮かぶ瀬あるわけだから、あまりくよくよしないように。","glum"];
EXAMPLES[8686]=["Girl as she was, Joan was not daunted at all.","女の子であったが、ジョーンは少しもおびえなかった。","daunted"];
EXAMPLES[8691]=["The game was full of suspense.","試合は、ハラハラドキドキだった。","suspense"];
EXAMPLES[8694]=["He bequeathed a considerable fortune to his son.","彼は息子に相当の財産を残した。","bequeathed"];
EXAMPLES[8695]=["Please ensure the genitals are obscured by a mosaic effect.","局部には必ずモザイクをかけて下さい。","genitals"];
EXAMPLES[8697]=["The troops fought with Grant against the Confederates.","軍隊はグラント総司令官のもとで南部軍と戦った。","Confederates"];
EXAMPLES[8703]=["The man extricated Ellie from a dangerous situation.","その人はエリーを危険な状況から救った。","extricated"];
EXAMPLES[8705]=["All political dissidents were purged under the former regime.","反体制派はすべて旧体制のもとで粛清されました。","dissidents"];
EXAMPLES[8709]=["My brother has been much too rowdy lately.","弟の乱暴はこのごろ目に余る。","rowdy"];
EXAMPLES[8711]=["The sudden glare impinged painfully on his eyes.","突然の強い光を受けて彼の目は痛いほどだった。","impinged"];
EXAMPLES[8712]=["He is on the varsity in tennis and in debating.","彼はテニスと弁論の代表チームの一員である。","varsity"];
EXAMPLES[8713]=["This church has beautiful stained glass windows.","この教会には、きれいなステンドグラスがあるんだよ。","stained"];
EXAMPLES[8716]=["Your explanation won't wash; it's too improbable to be true.","君の説明は見えすいている。とても本当とは思えないよ。","improbable"];
EXAMPLES[8717]=["It's not illegal, but it's pernicious.","違法ではないが悪質だ。","pernicious"];
EXAMPLES[8719]=["That child's free time is circumscribed.","その子供の自由時間は制限されている。","circumscribed"];
EXAMPLES[8720]=["I drank too much. My face is swollen!","飲み過ぎた！顔がむくんでる！","swollen"];
EXAMPLES[8721]=["The blare of the radio burst upon our ears.","ラジオの騒音が我々を襲った。","blare"];
EXAMPLES[8722]=["Some member countries have been lax in abiding by G-7 agreements.","加盟国中数カ国は、Ｇ７の協定に従うことにあいまいな態度を見せています。","abiding"];
EXAMPLES[8724]=["They regaled me on a Chinese banquet.","彼らは私を豪華な中華料理でもてなした。","regaled"];
EXAMPLES[8725]=["The man died of thirst in a dry country.","その男はある乾燥した国で水が飲めずに死んだ。","thirst"];
EXAMPLES[8726]=["Keep a tally of what you owe.","いくら借りているか記録をつけておきなさい。","tally"];
EXAMPLES[8732]=["Tom acknowledges he is a devout Christian.","トムは敬虔なクリスチャンを自認している。","devout"];
EXAMPLES[8734]=["How is Null expressed as a regular expression?","正規表現でヌルはどのように表されるのでしょうか？","Null"];
EXAMPLES[8736]=["He was declared insolvent.","彼は返済能力がないと宣告された。","insolvent"];
EXAMPLES[8737]=["I don't like my cousin. All he does is whine.","いとこが好きじゃない。いつも駄々をこねるから。","whine"];
EXAMPLES[8740]=["This big gate is disproportionate to the small garden.","この大きな門は小さな庭に不釣り合いだ。","disproportionate"];
EXAMPLES[8742]=["I tried to efface the memory of her tears.","私は彼女が涙を流した思い出を忘れようと努めた。","efface"];
EXAMPLES[8743]=["I may be plump, but I'm vigorous.","私は太り気味かもしれないが、すこぶる健康だよ。","plump"];
EXAMPLES[8744]=["Mother had a large lung hemorrhage and died.","母は夥しい喀血をして死にました。","hemorrhage"];
EXAMPLES[8746]=["The coin's face depicts a javelin thrower.","コインの表には槍投げ選手が描かれている。","javelin"];
EXAMPLES[8755]=["Kudos for your outstanding achievement!","素晴らしい業績に拍手を送ります。","Kudos"];
EXAMPLES[8759]=["Don’t ruffle any feathers.","寝た子を起こすんじゃない。","ruffle"];
EXAMPLES[8764]=["We'll never live this fiasco down.","この失敗、きっと一生、言われつづけるなあ。","fiasco"];
EXAMPLES[8769]=["An old man came tottering along.","老人がたどたどしい足取りで歩いてきた。","tottering"];
EXAMPLES[8770]=["He avowed himself an atheist.","彼は自分が無神論者だと告白した。","atheist"];
EXAMPLES[8775]=["The children are riding the carousel.","子供たちはメリーゴーランドに乗ってるよ。","carousel"];
EXAMPLES[8782]=["Brevity is the soul of wit.","簡潔は機知の精髄。","Brevity"];
EXAMPLES[8783]=["My mouth forms a lot of saliva.","唾液が多く出ます。","saliva"];
EXAMPLES[8784]=["If a woman masturbates, she will secrete female hormones and become more feminine.","女性が自慰をすれば女性ホルモンが分泌され、女性らしさが出てきます。","secrete"];
EXAMPLES[8785]=["The brunt of criticism was borne by the chairmen.","議長が批判の矢面に立った。","brunt"];
EXAMPLES[8786]=["On an island in the Seine, there is a big church called Notre Dame.","セーヌ川の中の島にノートルダムと呼ばれる大きな教会がある。","Dame"];
EXAMPLES[8787]=["He ruminated over his misfortunes.","彼は自分の不運についてじっくり考えた。","ruminated"];
EXAMPLES[8789]=["My father aged remarkably during his convalescence.","父は病後、めっきり老け込んでしまった。","convalescence"];
EXAMPLES[8791]=["Distance per degree of longitude at equator.","赤道における経度1度当たりの長さ。","longitude"];
EXAMPLES[8792]=["Insecticides are agricultural chemicals that exterminate insects harmful to plants.","殺虫剤とは、植物に害を与える害虫を防除する農薬のこと。","Insecticides"];
EXAMPLES[8793]=["Human physiology is a three-credit course.","生理学は３単位です。","physiology"];
EXAMPLES[8795]=["Oliver has an acne problem.","オリヴァーはにきびに悩んでいる。","acne"];
EXAMPLES[8797]=["Curses, like chickens, come home to roost.","呪いはひな鳥のようにねぐらに戻ってくる。","roost"];
EXAMPLES[8798]=["There is an anteroom adjoining the library.","書斎の隣に控えの間がある。","anteroom"];
EXAMPLES[8801]=["You should not trample on other people's rights.","他人の権利を踏みにじってはいけない。","trample"];
EXAMPLES[8802]=["Women have two ovaries.","女性には卵巣が2つあります。","ovaries"];
EXAMPLES[8803]=["The sniper is driving a white van.","狙撃兵は白いヴァンを運転している。","sniper"];
EXAMPLES[8805]=["I have a touch of diarrhea.","下痢気味です。","a touch of"];
EXAMPLES[8808]=["A good result is in prospect.","良い結果が予想される。","in prospect"];
EXAMPLES[8809]=["Therefore it will be closed for the rest of the year.","それゆえに一年の残りの期間は閉鎖される事になるだろう。","for the rest"];
EXAMPLES[8810]=["Cherry blossom is wafting down from the trees.","桜が舞い散っている。","wafting"];
EXAMPLES[8811]=["Please accept my condolences on the death of your father.","ご尊父のご逝去に対し、謹んで哀悼の意を表します。","condolences"];
EXAMPLES[8812]=["I'm itching from mosquito bites. Do you have any ointment?","蚊にかまれて、痒くて痒くて。ぬり薬ある？","ointment"];
EXAMPLES[8813]=["I was a constant torment to my parents.","私は両親の耐えない苦労の種だった。","torment"];
EXAMPLES[8815]=["I want to do it, but I can't.","やりたいけど、できないの。","can"];
EXAMPLES[8817]=["By virtue of frugality he has made a fortune.","彼は節約によってひと財産作った。","frugality"];
EXAMPLES[8820]=["Do you have any insect repellent spray?","虫よけスプレーありますか？","repellent"];
EXAMPLES[8821]=["We got thrashed at the match today.","今日の試合はぼろ負けだった。","thrashed"];
EXAMPLES[8822]=["I vouch for his sincerity.","彼が誠実なことは私が責任を持ちます。","vouch"];
EXAMPLES[8823]=["To be badly off makes life hard to bear.","暮らし向きが悪いと人生は耐え難いものとなる。","be badly off"];
EXAMPLES[8825]=["The shape of an egg is like the shape of a naught (0).","卵の形が「ゼロ」（０）の形に似ているからであろう。","naught"];
EXAMPLES[8826]=["The boat moved slowly away from the quay.","船は岸壁からしだいに遠ざかって行った。","quay"];
EXAMPLES[8828]=["He prophesied that a dreadful calamity would happen.","彼は恐ろしい災害が起こると予言した。","calamity"];
EXAMPLES[8834]=["How do I get reimbursed?","払い戻しはどうしたらいいのですか。","reimbursed"];
EXAMPLES[8836]=["It's raining. You might just as well stay home.","雨が降っている。今日は家にいたら。","just as well"];
EXAMPLES[8838]=["Suddenly Nancy screamed in the midst of silence.","静けさの中、ナンシーは突然叫び声をあげた。","in the midst of"];
EXAMPLES[8839]=["Please tell me how I can cure my insomnia.","どうしたら不眠症を治せるのか教えてください。","insomnia"];
EXAMPLES[8841]=["Somebody should tell off that rude man.","あの無礼な男を誰かが叱り付けなければならない。","tell off"];
EXAMPLES[8843]=["As it happens, I have left the book at home.","たまたま私はその本を家に忘れてきた。","As it happens"];
EXAMPLES[8845]=["Can't you bring down the price a bit?","もう少し安くならない？","bring down"];
EXAMPLES[8847]=["And yet, the contrary is always true as well.","しかし、逆もまた真である。","And yet"];
EXAMPLES[8848]=["Moreover, when viewed from the side, the front teeth are protruding.","さらに、横から見ると、前歯は出っ歯の状態にあります。","protruding"];
EXAMPLES[8849]=["The best bet on a rainy day is to remain indoors.","雨の日は外に出ないに限る。","bet on"];
EXAMPLES[8854]=["My premonition turned out to be right.","嫌な予感が的中した。","premonition"];
EXAMPLES[8855]=["How did you get that bruise on your leg?","足のあざどうしたの？","bruise"];
EXAMPLES[8860]=["The company moved its corporate domicile to Hong Kong for tax purposes.","会社は税金上の目的で本社所在地を香港に移した。","domicile"];
EXAMPLES[8863]=["We must beef up our organization.","我々は組織を強化しなくてはならん。","beef up"];
EXAMPLES[8864]=["When she catches a cold, she often develops bronchitis.","風邪をひくとよく気管支炎になります。","bronchitis"];
EXAMPLES[8865]=["My grandmother suffers from osteoporosis.","私の祖母は骨粗鬆症を患っている。","osteoporosis"];
EXAMPLES[8869]=["Stow away carefully the clothes you removed.","脱いだ服はちゃんと片付けてよね。","Stow"];
EXAMPLES[8870]=["I forgot my debit card at home.","デビットカードを家に忘れてきちゃった。","debit"];
EXAMPLES[8871]=["Let's split the Bill.","支払いは割り勘にしよう。","split the Bill"];
EXAMPLES[8875]=["You really are the chaff of humanity.","ほんとお前人間のクズだな。","chaff"];
EXAMPLES[8878]=["You must not lack decorum dealing with your benefactors.","恩人に礼節を欠いてはなりませんよ。","decorum"];
EXAMPLES[8879]=["You're certainly looking fit as a fiddle today.","今日はとても元気そうだね。","fiddle"];
EXAMPLES[8880]=["Having been written in haste, his letter was hard to read.","急いで書かれたので、彼の手紙は読みづらかった。","in haste"];
EXAMPLES[8882]=["The submarine's periscope was sticking out of the water.","潜水艦の潜望鏡が水面から突き出ていた。","periscope"];
EXAMPLES[8883]=["The old man was plodding along.","老人がとぼとぼ歩いていた。","plodding"];
EXAMPLES[8884]=["There is a plethora of adverbs of frequency in my language.","私の言語は頻度を表す副詞の種類が豊富です。","plethora"];
EXAMPLES[8886]=["You will be delayed for only thirty minutes at worst.","君はせいぜい３０分しか遅れないだろう。","at worst"];
EXAMPLES[8887]=["The name Edwin doesn't ring a bell.","エドウィンと言う名前を聞いてもピンとこない。","ring a bell"];
EXAMPLES[8891]=["How much will you pay me if I fix the plumbing?","僕が配管を直したら、幾らくれる？","plumbing"];
EXAMPLES[8893]=["Blossoms have come out on the embankment.","花々が土手に咲いた。","embankment"];
EXAMPLES[8894]=["Yesterday I ran into Yamada, whom I hadn't seen in years.","ぼくは昨日何年もあったことのなかった山田君に出会った。","in years"];
EXAMPLES[8895]=["The park was built for the benefit of the public.","その公園は一般の人々のために作られた。","for the benefit of"];
EXAMPLES[8896]=["Tom disappeared while out on bail.","トムは保釈中に行方をくらました。","on bail"];
EXAMPLES[8897]=["I can sleep in peace after this.","これからは安心して眠れます。","sleep in"];
EXAMPLES[8901]=["There is little water left in the canteen.","水筒にはほとんど水が残っていない。","canteen"];
EXAMPLES[8903]=["Watch your step in dark alleys.","暗い道では足元に気をつけなさい。","step in"];
EXAMPLES[8905]=["That's not likely in so far as I can see.","私が分かっている限りではそんなことはありそうにない。","in so far as"];
EXAMPLES[8906]=["They are filibustering to prevent the Bill from passing.","彼らは法案の通過を阻止しようと、合法的な議事妨害をしています。","filibustering"];
EXAMPLES[8907]=["I found this in the cavern.","これは私が洞窟の中で見つけたものです。","cavern"];
EXAMPLES[8913]=["They subjugate the meek.","奴らは弱者を服従させて喜んでいるが。","subjugate"];
EXAMPLES[8914]=["When men go to the gym it seems they really work their biceps.","男性はフィットネスセンターへ行くと二頭筋をよく鍛えるみたいだ。","biceps"];
EXAMPLES[8916]=["He was weak enough to succumb to temptation.","彼はもろくも誘惑に負けた。","succumb to"];
EXAMPLES[8918]=["Tom welcomed Mary with open arms.","トムはメアリーを温かく迎え入れた。","with open arms"];
EXAMPLES[8919]=["Our new school building is under construction.","我々の新校舎は目下建設中である。","under construction"];
EXAMPLES[8920]=["The interpretation of this data, however, is very much in dispute.","しかしながら、これらのデータの解釈は大いに議論の対象となっている。","in dispute"];
EXAMPLES[8923]=["Encryption technology has advanced to the point where it's pretty reliable.","暗号技術も、かなり信頼のおけるものに進んでいます。","Encryption"];
EXAMPLES[8924]=["The picture is true to life.","その絵は本物そっくりだ。","true to life"];
EXAMPLES[8927]=["Have you decided on the subject of your thesis?","卒論のテーマは決めましたか。","on the subject of"];
EXAMPLES[8929]=["The boat sailed around the promontory.","船は岬に沿って回った。","promontory"];
EXAMPLES[8931]=["Tom has good diction.","トムは滑舌がいい。","diction"];
EXAMPLES[8933]=["The matter is now under consideration.","その件は検討中だ。","under consideration"];
EXAMPLES[8935]=["Speak well of the dead.","死者はほめよ。","Speak well of"];
EXAMPLES[8937]=["The hermit lived in a wooden hut.","隠者は木造の小屋に住んでいた。","hermit"];
EXAMPLES[8939]=["Another step, and you will fall down the precipice.","もう一歩進めばあなたはがけから落ちるでしょう。","precipice"];
EXAMPLES[8940]=["My contemporaries are, working, shopping, out and about, all the time.","同世代の人は、仕事とか、買い物で留守ばかりです。","out and about"];
EXAMPLES[8941]=["The old man is the epitome of kindness.","その老人は非常に親切だ。","epitome"];
EXAMPLES[8942]=["My gait is unsteady from lack of sleep.","寝不足で足元がふわふわしています。","gait"];
EXAMPLES[8943]=["Sometimes I feel like kicking my own rump.","時々、自分のけつを思いきり蹴りあげてやりたくなる。","rump"];
EXAMPLES[8944]=["He was considered to be an accomplice.","彼は共犯者とみなされた。","accomplice"];
EXAMPLES[8949]=["Owing to the rain, the athletic meeting was put off.","雨のために運動会は延期になった。","Owing to"];
EXAMPLES[8950]=["The minister appointed one of his cronies to a key position.","その大臣は気心の知れた仲間を重要な地位につけました。","cronies"];
EXAMPLES[8953]=["I sleep on my side.","横向きに寝る。","sleep on"];
EXAMPLES[8954]=["There's no doubt that it'll fade away.","自然消滅することは目に見えてるじゃん。","fade away"];
EXAMPLES[8958]=["Are you still in doubt about what I have said?","僕の言葉をまだ疑っているんですか。","in doubt"];
EXAMPLES[8959]=["Steve had to shell out $50.00 for the speeding ticket he got last week.","スティーブは先週したスピード違反に５０ドルも払わなければならなかった。","shell out"];
EXAMPLES[8962]=["At last, a chance in a million arrived.","いよいよ千載一遇のチャンスがめぐってきた。","in a million"];
EXAMPLES[8963]=["The cat retracted its claws.","猫はつめを引っ込めた。","retracted"];
EXAMPLES[8964]=["That'll make for a memorable time.","貴重な思い出料としては安いものですよ。","make for"];
EXAMPLES[8965]=["Nearly all men die of their remedies, and not of their illness.","ほとんど全ての人は治療で死に、病のゆえではない。","die of"];
EXAMPLES[8966]=["Elation and despair ebbed and flowed in her.","彼女は得意になったと思ったら絶望したりした。","Elation"];
EXAMPLES[8967]=["To make a long story short, we buried the hatchet.","手短にいえば、我々は仲直りをした。","hatchet"];
EXAMPLES[8968]=["Female hormone imbalance is a major cause of infertility.","女性ホルモン分泌の乱れが不妊症の大きな原因です。","infertility"];
EXAMPLES[8969]=["She lost her temper at the slightest provocation.","彼女はごくささいなことでカッとなった。","provocation"];
EXAMPLES[8970]=["We looked for it high and low.","我々はあちこちそれを探した。","high and low"];
EXAMPLES[8973]=["Is it possible to determine the diameter from the circumference?","円周から直径を求めることは可能ですか？","circumference"];
EXAMPLES[8974]=["I awoke with a start because of the fire.","火事があったので、私はびっくりして目を覚ました。","with a start"];
EXAMPLES[8977]=["Both air and water are indispensable for life.","空気と水は両方とも生命にとって欠くことができない。","for life"];
EXAMPLES[8979]=["She suffers from a chronic malady.","彼女は慢性の病気にかかっている。","malady"];
EXAMPLES[8981]=["Oddly enough, he insisted on his innocence.","奇妙な話だが、彼は自分の無罪を主張した。","Oddly enough"];
EXAMPLES[8982]=["There is nothing new transpired since I wrote you last.","この前手紙を書いた時以来別に新しい事は何も起こっていない。","transpired"];
EXAMPLES[8985]=["I'll be with you in a second.","すぐそちらへまいります。","in a second"];
EXAMPLES[8989]=["The daughters recuperated from the shock of the death of their father.","娘達は父親の死のショックから元気を取り戻した。","recuperated"];
EXAMPLES[8991]=["How can you break the news to her?","どうやって彼女に打ち明けろというんだい。","break the news"];
EXAMPLES[8999]=["She winked at me, as much as to say, I love you.","「あなたを愛しているのよ」と言わんばかりに彼女は僕にウィンクした。","as much as to say"];
EXAMPLES[9001]=["Half-hearted cutbacks that can't save money leave JAL's rehabilitation in doubt.","コストダウンもできない生ぬるいリストラがJAL再建を危うくする。","cutbacks"];
EXAMPLES[9002]=["His health was the forfeit of heavy drinking.","大酒を飲んだ報いで彼は健康を害した。","forfeit"];
EXAMPLES[9003]=["She suffered from anorexia as a teenager.","彼女は10代のころ拒食症になった。","anorexia"];
EXAMPLES[9005]=["Tom suffered from migraine headaches for years.","トムは何年も偏頭痛に苦しんだ。","migraine"];
EXAMPLES[9007]=["The hospital quarantined the infected patients to avoid cross infection.","病院は院内感染を防ぐため、感染患者を隔離した。","quarantined"];
EXAMPLES[9016]=["The rummage sale netted me a profit.","見切り売りでたくさんもうけた。","rummage"];
EXAMPLES[9017]=["What is the correct aperture in this light?","この明るさで絞りはどのくらいですか。","aperture"];
EXAMPLES[9018]=["In addition to English, he can speak French.","英語の他に、彼はフランス語も話せる。","In addition to"];
EXAMPLES[9020]=["How many followers do you have on Twitter?","Twitterのフォロワーって何人ぐらいいるの？","Twitter"];
EXAMPLES[9022]=["He will make amends for the damage.","彼は損害の償いをするだろう。","amends"];
EXAMPLES[9023]=["Smoke was billowing from the engine.","エンジンから、煙がもくもく出てたよ。","billowing"];
EXAMPLES[9026]=["The final exams will probably carry over into next month.","最後の試験は来月にまたがるだろう。","carry over"];
EXAMPLES[9027]=["There are various expressions that indicate something is hearsay.","伝聞であることを示す表現はいろいろある。","hearsay"];
EXAMPLES[9031]=["We advanced under cover of darkness.","我々は夜陰に乗じて進んだ。","under cover"];
EXAMPLES[9032]=["A baby is sleeping in the cot.","赤ちゃんがベビーベッドで寝てるよ。","cot"];
EXAMPLES[9036]=["Hold still a moment while I fix your tie.","ネクタイを締める間、ちょっとじっとしてね。","Hold still"];
EXAMPLES[9038]=["Can you tell barley from wheat at first sight?","大麦と小麦を一目見て見分けられますか。","barley"];
EXAMPLES[9041]=["The hotel has a swimming pool, tennis courts and the like.","そのホテルにはプールやテニスコート等がある。","and the like"];
EXAMPLES[9042]=["The clerk made an entry in his ledger.","事務員は原簿に記入した。","ledger"];
EXAMPLES[9049]=["Let me hear from you now and again, will you?","ときどき手紙を下さい。","now and again"];
EXAMPLES[9051]=["It's brute force, but that's the only way.","力業ですが、他に選択肢がありません。","brute"];
EXAMPLES[9054]=["The teacher called the roll in class.","先生は出席を取った。","roll in"];
EXAMPLES[9059]=["We tend to welcome only proof of what we already know.","既に知っていることを証明してくれるものしか受け入れたがらない傾向が私たちにはあるのである。","tend to"];
EXAMPLES[9060]=["The Tokyo Stock Exchange rallied at the end of the day.","東京証券取引所は後場の終わり値になって持ち直しました。","at the end of the day"];
EXAMPLES[9062]=["I fall behind him in this respect.","この点で私は彼に劣る。","fall behind"];
EXAMPLES[9068]=["The prisoner was set at liberty yesterday.","その囚人は昨日釈放された。","set at"];
EXAMPLES[9071]=["The guards must keep watch over the jewels.","そのガードマンたちは宝石の見張りをしなければならない。","watch over"];
EXAMPLES[9075]=["There's a chance that tap water may contain harmful substances like chlorine and lead.","水道水には塩素、鉛などの有害物質が含まれている可能性がある。","chlorine"];
EXAMPLES[9077]=["If she's not careful she'll tear a ligament doing that.","もし気を付けなければ彼女はそんなことをしているうちに靭帯を切ってしまうだろう。","ligament"];
EXAMPLES[9081]=["The sugar canister is empty.","砂糖入れがからっぽだ。","canister"];
EXAMPLES[9083]=["I don't have a clue how to play golf.","私はゴルフのやり方はさっぱりわからない。","have a clue"];
EXAMPLES[9084]=["Young men are apt to fall a victim to their own avarice.","若者は己の貪欲の犠牲になりがちである。","avarice"];
EXAMPLES[9085]=["There was a sharp peal of thunder.","激しい雷鳴がした。","peal"];
EXAMPLES[9086]=["Clear away the table things.","テーブルの上を片づけなさい。","Clear away"];
EXAMPLES[9087]=["Water is running from the faucet into the sink.","水が蛇口からシンクへと流れゆく。","faucet"];
EXAMPLES[9088]=["Brave man as he was, he recoiled at the sight.","彼は勇敢な男だったが、その光景にはたじろいだ。","recoiled"];
EXAMPLES[9089]=["Take a look at this beautiful embroidery made with great effort.","丹精をこめてつくったこの美しい織物をごらんください。","embroidery"];
EXAMPLES[9090]=["The nurses were run off their feet every day.","看護婦たちは毎日へとへとになるまで働かされた。","run off"];
EXAMPLES[9091]=["The pond is 100 meters in diameter.","その池は直径１００メートルある。","in diameter"];
EXAMPLES[9092]=["A bear spends the winter in its lair.","クマは冬は穴の中で過ごします。","lair"];
EXAMPLES[9093]=["Don't poke fun at foreigners.","外人をからかうな。","poke fun at"];
EXAMPLES[9096]=["Bob told Jane not to interfere in his personal affairs.","ボブはジェーンに自分の個人的な事を干渉しないよう言った。","interfere in"];
EXAMPLES[9098]=["I sterilize with utmost care.","殺菌処理を徹底します。","sterilize"];
EXAMPLES[9099]=["What kind of women's attire does Tom like?","トムは女性のどんなファッションが好き？","attire"];
EXAMPLES[9100]=["The slogan was designed to rouse the people.","このスローガンは国民を奮い立たせる意図で作られた。","rouse"];
EXAMPLES[9101]=["She scowled at the rude salesman.","彼女は失礼なセールスマンをにらみつけた。","scowled"];
EXAMPLES[9102]=["The new title has good connotations.","その新しい題名はいい意味を持っている。","connotations"];
EXAMPLES[9105]=["Conformity is an essential element of our homogeneous community.","同じような人々からなる私たちの地域社会では、体裁に従おうとする意識は不可欠な要素である。","Conformity"];
EXAMPLES[9107]=["Iris, what do you usually eat for breakfast?","アイリス、君は普段朝食は何を食べているの？","Iris"];
EXAMPLES[9108]=["Pull into shape after washing.","洗ったあと引っ張って形にして。","Pull into"];
EXAMPLES[9111]=["As he stood there he might have been a fiend.","そこに立った彼はあたかも悪鬼のようだった。","fiend"];
EXAMPLES[9113]=["Why doesn't your dog wear a muzzle?","なぜ君の犬は口輪を付けていないの？","muzzle"];
EXAMPLES[9115]=["It's a hassle to take the husks off of chestnuts.","栗を剥くのって、めんどくさっ。","husks"];
EXAMPLES[9116]=["The picture is colorful in contrast with this one.","その絵はこの絵とは対照的にカラフルだ。","in contrast with"];
EXAMPLES[9117]=["The critical period in matrimony is breakfast time.","結婚の危険な時期は朝食の時である。","matrimony"];
EXAMPLES[9118]=["He lay prostrate, ready to ambush the invaders.","彼はうつ伏せになって侵入者を待ちかまえた。","prostrate"];
EXAMPLES[9119]=["Company attorneys are working around the clock to complete the merger.","企業の顧問弁護士団は合併手続きを完了するために、２４時間通しで働いています。","around the clock"];
EXAMPLES[9120]=["You can't wring any more money from me.","わたしからはこれ以上お金は絞り取れませんよ。","wring"];
EXAMPLES[9123]=["Everything will turn out for the best.","結局万事旨く行くだろう。","turn out for"];
EXAMPLES[9126]=["Six months ago I had an operation for the cataract in my right eye.","半年前に右目の白内障の手術をしました。","cataract"];
EXAMPLES[9127]=["The country seethed over the issue of national defense.","国内は防衛問題で沸騰した。","seethed"];
EXAMPLES[9128]=["This morning, I woke up yet again to the sound of crying children.","今日の朝も子供の泣き声で目が覚めた。","yet again"];
EXAMPLES[9133]=["This athlete is strong and agile.","このアスリートは、力もあるし機敏だ。","agile"];
EXAMPLES[9142]=["The new model car was put through several tests.","その新型車は何度か厳しいテストを受けた。","put through"];
EXAMPLES[9143]=["Cut the cloth in a diagonal direction.","布を斜めに裁ちなさい。","diagonal"];
EXAMPLES[9144]=["Ever since we've been wearing clothes, we haven't known one another.","我々は衣服を着るようになって以来、お互いが分からなくなった。","Ever since"];
EXAMPLES[9145]=["Let's have a gander at this insolent man.","その不届きな野郎の顔を、拝ませてもらうか。","insolent"];
EXAMPLES[9146]=["The inspection was quite perfunctory.","検査は全くおざなりなものだった。","perfunctory"];
EXAMPLES[9148]=["He can't be smart if he can screw up something like that.","それを失敗するなんて、彼が賢いはずがない。","screw up"];
EXAMPLES[9150]=["If you're not careful, you might slip and fall on the icy steps.","気を付けないと凍った階段で滑って転ぶよ。","fall on"];
EXAMPLES[9152]=["The cow missed being hit by a gnat's whisker.","牛は間一髪のところで衝突をまぬがれた。","whisker"];
EXAMPLES[9156]=["If you can do it on your own, do it without reserve.","独力でそれがやれるなら、遠慮せずにやりなさい。","without reserve"];
EXAMPLES[9159]=["He tried to be less obtrusive.","彼はでしゃばらないようにしようとした。","obtrusive"];
EXAMPLES[9161]=["Tom kicked Mary in the shin.","トムはメアリーのすねを蹴った。","shin"];
EXAMPLES[9163]=["The cabin was torn asunder by the storm.","小屋は嵐でばらばらになった。","asunder"];
EXAMPLES[9164]=["Metals can become brittle at low temperatures.","金属は低温になると脆くなることがあります。","brittle"];
EXAMPLES[9166]=["Eventually, he returned the sword to its sheath.","やがて彼は白刃を鞘に収めた。","sheath"];
EXAMPLES[9168]=["We thought we would write out the directions, in case you got lost.","君が迷子になるといけないので、地図を書こうと思った。","write out"];
EXAMPLES[9169]=["To tell you the truth, I'm a furry.","何を隠そう、俺はケモナーなんだ。","furry"];
EXAMPLES[9175]=["The child threw a tantrum because he wanted the toy.","子供がおもちゃを買って欲しいと駄々をこねていた。","tantrum"];
EXAMPLES[9176]=["An eye for an eye, a tooth for a tooth.","目には目を、歯には歯を。","An eye for an eye"];
EXAMPLES[9177]=["Huh? Could it be that we are being slandered?","あれ？私たちって、もしかして誹謗中傷されてる？","slandered"];
EXAMPLES[9183]=["This small house has a thatched roof.","この小さなお家は、かやぶき屋根なんですよ。","thatched"];
EXAMPLES[9184]=["I have no time to engage in gossip.","噂話のお相手をしている暇はない。","engage in"];
EXAMPLES[9185]=["Yecch. This rice cracker is soggy.","あらやだ、このお煎餅もう湿気ってる。","soggy"];
EXAMPLES[9188]=["Stay put. I'll come and get you.","そこにいて下さい。迎えに行きますから。","Stay put"];
EXAMPLES[9192]=["He was impertinent to his father.","彼は父親に生意気な事を言った。","impertinent"];
EXAMPLES[9194]=["Those two really hit it off.","あの２人はとてもうまが合います。","hit it off"];
EXAMPLES[9196]=["A smart falcon hides its talons.","能ある鷹は爪を隠す。","talons"];
EXAMPLES[9197]=["Now, the situation is out of hand.","既に手に負えない状態だ。","out of hand"];
EXAMPLES[9198]=["He was so cranky last night.","昨夜彼は怒りっぽかったな。","cranky"];
EXAMPLES[9199]=["Go and help wash up, will you?","洗い物を手伝いに行って下さい。","wash up"];
EXAMPLES[9200]=["The ingenious boy won a prize for his invention.","利口なその少年は自分の発明品で賞を得た。","ingenious"];
EXAMPLES[9203]=["Support vector machines are supervised learning models used for classification and regression analysis.","サポートベクターマシンとは、教師あり学習モデルであり、判別分析や回帰分析に用いられる。","vector"];
EXAMPLES[9205]=["Don't go to extremes.","極端に走ってはならない。","go to extremes"];
EXAMPLES[9206]=["Pagans have deified life and Christians have deified death.","自然崇拝者は生命を、キリスト教徒は死を崇めてきました。","Pagans"];
EXAMPLES[9209]=["I hope you'll think better of it.","あなたがそれを考え直して止めてもらえればと思います。","think better of"];
EXAMPLES[9210]=["The glaring light is hurtful to the eyes.","そのどぎつい光は目に悪い。","glaring"];
EXAMPLES[9215]=["This stew tastes acrid.","この鍋物はえぐいよ。","acrid"];
EXAMPLES[9216]=["A Persian cat was sleeping under the table.","ペルシャ猫がテーブルの下で眠っていた。","under the table"];
EXAMPLES[9219]=["We had to write off the debt.","負債は帳消しにするしかなかった。","write off"];
EXAMPLES[9222]=["The wolverine is omnivorous.","クズリは雑食だ。","omnivorous"];
EXAMPLES[9224]=["His great oration was like pearls before swine.","彼の立派な演説も豚に真珠に等しかった。","swine"];
EXAMPLES[9228]=["She was rapt in prayer.","彼女は一心に祈っていた。","rapt"];
EXAMPLES[9231]=["His fame was at its zenith at that time.","当時の彼は絶頂にあった。","zenith"];
EXAMPLES[9232]=["Well, to be frank, I don't like it at all.","そうですね、正直に言うと全然気に入りません。","to be frank"];
EXAMPLES[9233]=["My house is old and dilapidated.","うちの家は古くてボロボロなんだ。","dilapidated"];
EXAMPLES[9238]=["A lot of problems derive from a lack of reading in the home.","家庭で読書が行われない事から多くの問題が生じる。","derive from"];
EXAMPLES[9244]=["Willie accidentally let off his father's shotgun and made a hole in the wall.","ウィリーは誤って父親の猟銃を発砲し、壁に穴を開けた。","let off"];
EXAMPLES[9248]=["The very thought is abhorrent to me.","考えるだけでも忌まわしい。","abhorrent"];
EXAMPLES[9250]=["A good lawyer will always zero in on a key piece of evidence.","上手な弁護士はひとつの鍵となる証拠に的を絞る。","zero in on"];
EXAMPLES[9254]=["Don't bite on the right side.","右側では噛まないでくださいね。","bite on"];
EXAMPLES[9255]=["Exhaust gases of a car are noxious.","車の排ガスは有毒である。","noxious"];
EXAMPLES[9256]=["We are not supposed to drink in this theater.","この劇場では酒は飲めないことになっている。","drink in"];
EXAMPLES[9258]=["It is deplorable that she is so selfish.","彼女がこれほど自分勝手なのは嘆かわしい。","deplorable"];
EXAMPLES[9260]=["I'll smack the living daylights out of you!","ぶっ飛ばしてやる！","smack"];
EXAMPLES[9261]=["Do you really think that I'm that gullible?","僕は騙されやすいと本当に思う？","gullible"];
EXAMPLES[9265]=["The revised timetable will go into effect on the 5th of this month.","今月５日から時間表が改正される。","go into effect"];
EXAMPLES[9266]=["Walk fast so as to be in time.","間に合うように速く歩きなさい。","so as to"];
EXAMPLES[9267]=["They went on an expedition to the Antarctic.","彼らは南極探検に行った。","Antarctic"];
EXAMPLES[9274]=["It wasn't simply by coincidence that Tom and Mary both happened to be there.","トムとメアリーの二人がそこに居合わせたのは単なる偶然ではなかった。","by coincidence"];
EXAMPLES[9275]=["Equestrian is the only mixed-gender Olympic event.","馬術競技は男女混合で行われる唯一のオリンピック競技です。","Equestrian"];
EXAMPLES[9277]=["My responsibility is to keep the company solvent.","会社の債務返済能力を維持するのが私の責任だ。","solvent"];
EXAMPLES[9278]=["It's easy to see the area's majestic topography from the cockpit of a helicopter.","ヘリコプターの運転席からなら、その地の素晴らしい地形を見渡すのは容易い。","topography"];
EXAMPLES[9280]=["I get a kick out of life.","人生から非常な喜びを感ずる。","kick out"];
EXAMPLES[9285]=["We must make do with what we have got.","我々は、手持ちのもので間に合わせなければならない。","make do with"];
EXAMPLES[9286]=["She has waded into one controversy after another.","彼女は次々と論戦に挑んでいる。","waded"];
EXAMPLES[9289]=["We heard somber hollow sounds from the cave.","洞窟からうつろに反響する音を耳にした。","somber"];
EXAMPLES[9291]=["I had a quarrel with him over money.","金銭のことで彼と争いになった。","quarrel with"];
EXAMPLES[9292]=["No scruple held him back from making this attempt.","彼は平気でこの企てを試みた。","scruple"];
EXAMPLES[9296]=["This data is immaterial to the argument.","このデータはその議論にとって重要だ。","immaterial"];
EXAMPLES[9297]=["By means of a super high-pressure water spray practically all the sediment is removed.","超高圧水の噴射により、ほとんどの詰まりが排除される。","sediment"];
EXAMPLES[9298]=["The deterioration of corporate earnings has yet to bottom out.","企業収益の悪化はまだ底を打っていない。","bottom out"];
EXAMPLES[9302]=["Do you always have such a hoarse voice?","いつもそんなだみ声なの？","hoarse"];
EXAMPLES[9307]=["What happened in consequence?","その結果何が起こったのか。","in consequence"];
EXAMPLES[9309]=["He had grown senile recently.","彼はこのごろ頭がぼけてきた。","senile"];
EXAMPLES[9312]=["I know a woman whose first and last names are the same as mine.","私は自分と同姓同名の女性を知っている。","first and last"];
EXAMPLES[9313]=["Tom has a tummy ache.","トムは、ポンポンが痛いんだよ。","tummy"];
EXAMPLES[9318]=["He was incredulous of the story.","彼はその話を信じなかった。","incredulous"];
EXAMPLES[9321]=["At that time, I thought that I was going to die for real.","あのときはリアルに死ぬかと思った。","for real"];
EXAMPLES[9322]=["The government promised to wipe out poverty.","政府は貧困を一掃することを約束した。","wipe out"];
EXAMPLES[9323]=["Let's drink to absent friends.","欠席された友人たちのために、乾杯しましょう。","drink to"];
EXAMPLES[9328]=["You just can't let things slip around this nonchalantly smart girl.","さりげなく聡いこの子にはうかつな事はとても言えない。","nonchalantly"];
EXAMPLES[9329]=["The boy is bashful and doesn't talk much.","少年は内気であまりしゃべらない。","bashful"];
EXAMPLES[9331]=["Come on, spit it out!","さあ、吐いちまえ！","spit it out"];
EXAMPLES[9333]=["I have a friend whose father is a veterinarian.","私には父親が獣医の友達がいる。","veterinarian"];
EXAMPLES[9335]=["The sky is a hazy shade of winter.","空はどんよりとした冬の陰にかすんでいる。","hazy"];
EXAMPLES[9336]=["The rise and fall of the sea is governed by the moon.","潮の満ち干は月の運行に左右される。","rise and fall"];
EXAMPLES[9342]=["Please cut perpendicular to the fibers.","繊維に対して直角に切ってください。","perpendicular"];
EXAMPLES[9343]=["Girls think much of fashion.","女の子はファッションを重んじる。","think much of"];
EXAMPLES[9347]=["I don't happen to have your application on hand at the moment.","あいにく私はあなたの申込書を今持ち合わせていない。","on hand"];
EXAMPLES[9348]=["To put it briefly, I do not agree.","簡単に言えば、私は賛成しません。","put it briefly"];
EXAMPLES[9351]=["A church spire could be seen in the distance.","遠くに教会の尖塔が見えた。","spire"];
EXAMPLES[9354]=["You had better not associate with those men.","君はああいった男たちと交際しないほうがいい。","associate with"];
EXAMPLES[9355]=["How do babies breathe when they're in the uterus?","赤ちゃんは子宮内で呼吸はどうしてるのですか？","uterus"];
EXAMPLES[9356]=["As to his daily life, he is very slovenly.","日常生活について言えば彼はとてもだらしない。","slovenly"];
EXAMPLES[9359]=["Everybody is immune to smallpox nowadays.","今ではみんな天然痘には免疫になっている。","smallpox"];
EXAMPLES[9360]=["It was a close call when the little girl almost drowned in the lake.","危ういところで少女は湖でおぼれそうになった。","close call"];
EXAMPLES[9365]=["You must, above all, be faithful to your friends.","何よりもまず友人に誠実でなければならない。","be faithful to"];
EXAMPLES[9368]=["I hope I can hold on to my job.","会社をクビにならなきゃいいけどね。","hold on to"];
EXAMPLES[9373]=["Grandmother's ashes are in an urn at the temple.","祖母の遺灰は寺院に置かれた骨壷に入っている。","urn"];
EXAMPLES[9374]=["You must not come in contact with him.","彼と接触してはいけない。","come in contact with"];
EXAMPLES[9375]=["Our holiday plans are still up in the air.","我々の休暇の計画はまだ未定だ。","up in the air"];
EXAMPLES[9380]=["He struck me in a passion.","彼はかっとなって私を殴った。","in a passion"];
EXAMPLES[9383]=["Could you elaborate on your new theory?","あなたの新しい理論について詳しく話していただけますか。","elaborate on"];
EXAMPLES[9385]=["He emphasized that tens of thousands of people would come to that concert.","何万人もの人々がそのコンサートにやってくると彼は強調した。","tens of thousands"];
EXAMPLES[9386]=["The doctor advised him to ease up on alcohol.","医師は彼にアルコールの量を減らすようにいった。","ease up"];
EXAMPLES[9388]=["It's been intermittent for 2 or 3 months.","断続的ですが、もう２、３ヶ月になります。","intermittent"];
EXAMPLES[9389]=["The ship Tom's grandfather was on was sunk by a torpedo.","トムの祖父が乗っていた船は、魚雷により沈没した。","torpedo"];
EXAMPLES[9390]=["I have no one to confide in.","私には秘密を打ち明けて相談できる人がいない。","confide in"];
EXAMPLES[9391]=["You look very dignified.","貫禄がついたね。","dignified"];
EXAMPLES[9396]=["My sleigh is white.","僕のソリは白だよ。","sleigh"];
EXAMPLES[9397]=["I'm troubled by this wart.","このいぼに悩まされています。","wart"];
EXAMPLES[9398]=["This kind of case is amenable to statistical treatment.","この種の事例は統計的処理が適応できる。","amenable"];
EXAMPLES[9401]=["You should seclude him from temptation.","彼を誘惑から引き離すべきだ。","seclude"];
EXAMPLES[9406]=["The vagabond, when rich, is called a tourist.","放浪者は、金持ちならば観光客と称せられる。","vagabond"];
EXAMPLES[9411]=["The patient is in a state of profound stupor.","患者は深い昏睡状態にあります。","stupor"];
EXAMPLES[9412]=["Should the word processor go wrong, we guarantee to replace it free of charge.","ワープロが万一故障したら、無料でお取り替えすることを保証します。","free of charge"];
EXAMPLES[9413]=["Seedlings are young plants.","苗とは若い植物体のことです。","Seedlings"];
EXAMPLES[9415]=["Tom resisted the temptation to lean over and kiss Mary.","トムはメアリーに顔を近づけキスをしたい気持ちを抑えた。","lean over"];
EXAMPLES[9417]=["I feel lethargic when I diet, what should I do?","ダイエット中脱力感がでます、どうすればよい？","lethargic"];
EXAMPLES[9421]=["Typhoid is a scary disease.","腸チフスは怖い病気。","Typhoid"];
EXAMPLES[9422]=["I was calm until I saw the syringe!","私は注射器を見るまでは平気だった。","syringe"];
EXAMPLES[9424]=["Your stubble suits you.","その無精ひげ、似合ってるよ。","stubble"];
EXAMPLES[9425]=["We received an eviction notice.","立ち退きの予告を受けた。","eviction"];
EXAMPLES[9427]=["Mary was called the diva of the century.","メアリーは世紀の歌姫と呼ばれていた。","diva"];
EXAMPLES[9428]=["Fan letters lay in a heap on the desk.","机の上にファンレターが山と積まれていた。","lay in"];
EXAMPLES[9429]=["His career culminated in the presidency.","彼は出世して最後には大統領になった。","culminated"];
EXAMPLES[9430]=["Be sure to fill in the blanks from top to bottom beforehand.","必ず、事前に全ての空欄部分を記入しておいて下さい。","from top to bottom"];
EXAMPLES[9431]=["It's time to pay up all your debts and close out your loan.","借金をきれいに返済してもらいましょうか。","close out"];
EXAMPLES[9434]=["I should stop procrastinating.","先延ばしにするのをやめなければ。","procrastinating"];
EXAMPLES[9438]=["The sight of you is an abomination to me.","おまえなんか見るのも嫌だ。","abomination"];
EXAMPLES[9442]=["We must hand down our craft to posterity.","我々は技術を後世に伝えなければならない。","hand down"];
EXAMPLES[9443]=["I'm suffering from chronic constipation.","慢性的な便秘で苦しんでいます。","constipation"];
EXAMPLES[9444]=["I want to get a fix on local culture.","私はこの地域の文化を味わいたいの。","fix on"];
EXAMPLES[9445]=["Lack of sleep whittled away her energy.","寝不足で彼女は元気がなかった。","whittled"];
EXAMPLES[9446]=["I vouch for his sincerity.","彼が誠実なことは私が責任を持ちます。","vouch for"];
EXAMPLES[9448]=["There's no room for excuses when it comes to your negligence, is there?","君の怠慢には釈明の余地がありませんね。","when it comes to"];
EXAMPLES[9449]=["The wounded man writhed.","負傷者は痛みでもだえ苦しんだ。","writhed"];
EXAMPLES[9450]=["It's the best score up to now.","それが今迄のところ一番いいスコアだ。","up to now"];
EXAMPLES[9453]=["What should I do to stop hiccups?","しゃっくりを止めるにはどうすればいいんだろうか。","hiccups"];
EXAMPLES[9454]=["Please add up the Bill.","勘定書を合計して下さい。","add up"];
EXAMPLES[9459]=["I am not responsible to you for my blunder.","僕の大失敗について君に弁明する義務はない。","blunder"];
EXAMPLES[9461]=["It's a cinch to learn to swim.","泳ぎを身につけるのは簡単なことだ。","cinch"];
EXAMPLES[9462]=["What kinds of sports do you go in for these days?","近頃どんなスポーツをやっていますか。","go in for"];
EXAMPLES[9464]=["I told it to my mother first and foremost.","私は真っ先に母にそれを告げた。","first and foremost"];
EXAMPLES[9467]=["They lugged the refrigerator up the stairs.","彼らは冷蔵庫を階段の上まで運び上げた。","lugged"];
EXAMPLES[9468]=["I would not meddle in such a thing.","私ならそんなことに口出しをしないだろう。","meddle"];
EXAMPLES[9469]=["John knows English history from A to Z.","ジョンは英国史を隅から隅まで知っている。","from A to Z"];
EXAMPLES[9472]=["I wouldn't like to cash in on other people's misfortunes.","人の好意に付け込むのはいやだね。","cash in"];
EXAMPLES[9473]=["When do cats make that purring noise in their throats?","猫はどんな時に喉をゴロゴロと鳴らすのだろう。","purring"];
EXAMPLES[9476]=["These facts will bear out his story.","これらの事実は彼の話が正しいことの裏付けとなるだろう。","bear out"];
EXAMPLES[9481]=["You must go through with your plan.","君は計画を遣り通さなければならない。","go through with"];
EXAMPLES[9486]=["She pouted when she was told to wash the dishes.","皿洗いを命じられて彼女は口をとがらせた。","pouted"];
EXAMPLES[9488]=["I feel happiest when I am at home with my family.","私は家族といっしょに家にいるときがいちばん幸せを感じる。","at home with"];
EXAMPLES[9490]=["She coaxed and wheedled her unwilling child into going to the dentist with her.","彼女は嫌がる子供を宥め賺して歯医者に連れて行った。","wheedled"];
EXAMPLES[9491]=["To my amazement, it disappeared in an instant.","驚いたことにそれは一瞬にして姿を消した。","in an instant"];
EXAMPLES[9497]=["He kept his tongue under a bridle.","彼は口を謹んで何も語らなかった。","bridle"];
EXAMPLES[9499]=["I've been on edge recently.","近頃いらいらしています。","on edge"];
EXAMPLES[9501]=["She is an appalling cook.","彼女は料理が恐ろしく下手だ。","appalling"];
EXAMPLES[9502]=["We need to postulate a completely different paradigm to explain all these phenomena.","これらのすべての現象を説明するにはまったくの異なるパラダイムを立てる必要がある。","postulate"];
EXAMPLES[9505]=["Mr Wright speaks Japanese as if it were his mother tongue.","ライトさんは、まるで母国語の様に日本語を話します。","mother tongue"];
EXAMPLES[9506]=["You can't feel at ease with a headache.","君は頭痛がしていてはくつろげるはずが無い。","at ease"];
EXAMPLES[9508]=["No offense was meant.","悪気はなかったのです。","No offense"];
EXAMPLES[9511]=["Convulsions can occur when they run a fever.","熱が出るとひきつけを起こすことがあります。","Convulsions"];
EXAMPLES[9513]=["I feel like puking. Do you have any medicine?","なんだか胸がムカムカするんだ。薬もってる？","puking"];
EXAMPLES[9514]=["As is often the case with foreigners, John dislikes nattou.","外人にはよくあることだが、ジョンは納豆が好きではない。","As is"];
EXAMPLES[9516]=["In due time, his innocence will be proved.","時が来れば彼の無罪が証明されるだろう。","In due time"];
EXAMPLES[9517]=["Let's not deviate from the subject.","本題からそれないようにしましょう。","deviate"];
EXAMPLES[9519]=["Did you lose your lip balm again?","リップクリームまた失くしちゃったの？","balm"];
EXAMPLES[9520]=["You lean on your parents too much. You must be more independent.","君は両親に頼りすぎだよ。もっと自立しなくちゃ。","lean on"];
EXAMPLES[9523]=["It was hunger that impelled him to crime.","飢えのために彼はやむなく罪を犯した。","impelled"];
EXAMPLES[9528]=["The load of the truck was in excess of three tons.","そのトラックの積み荷は三トンを超えていた。","in excess of"];
EXAMPLES[9529]=["The knight swore an oath of allegiance to the king.","騎士が王への忠誠を誓った。","allegiance"];
EXAMPLES[9530]=["I plan to work in a brothel.","売春宿で働くつもりです。","brothel"];
EXAMPLES[9532]=["At no time does the plain look so perfect as in early autumn.","初秋の頃のほど、その平原が美しく見えるときはない。","At no time"];
EXAMPLES[9533]=["I'm going to do an apprenticeship.","私は実習をします。","apprenticeship"];
EXAMPLES[9535]=["Doctor, I've got an itch in my crotch.","先生、アソコがかゆいんです。","crotch"];
EXAMPLES[9539]=["He embezzled the money from his office.","彼は会社の帳簿に穴を開けた。","embezzled"];
EXAMPLES[9544]=["She blanched at the bad news.","彼女はその悪い知らせを聞いて青くなった。","blanched"];
EXAMPLES[9549]=["I do beseech you, hear me through.","お願いいたします、最後までお聞きください。","beseech"];
EXAMPLES[9552]=["Reporters do not hesitate to intrude into people's privacy.","記者達は個人の生活を侵害することにためらいを感じない。","hesitate to"];
EXAMPLES[9555]=["There are five ways to emancipate themselves from the bond of worldly passions.","この煩悩のきずなから逃れるには五つの方法がある。","emancipate"];
EXAMPLES[9560]=["You scared me! Don't sneak up on me from behind!","びっくりした！いきなり後ろから脅かさないでよ！","sneak up on"];
EXAMPLES[9561]=["Can you fix this door? It's creaking.","このドア、キーキー音がするけど、直してくれない。","creaking"];
EXAMPLES[9562]=["I'll drink some water to quench my thirst.","水を飲んで喉を潤します。","quench"];
EXAMPLES[9567]=["In all probability, the cabinet will fall.","たぶんその内閣はつぶれるでしょう。","In all probability"];
EXAMPLES[9571]=["You do not necessarily have to go there yourself.","必ずしも行く必要はないよ。","not necessarily"];
EXAMPLES[9575]=["Robbers prowl around at midnight.","泥棒は真夜中にうろつき回る。","prowl"];
EXAMPLES[9576]=["Please make up your mind once and for all.","どうかきっぱりと決心してください。","once and for all"];
EXAMPLES[9578]=["We studied the Concordance to Shakespeare to accumulate examples of alliteration.","頭韻の例を収集するために、シェークスピア・コンコーダンスを調べた。","Concordance"];
EXAMPLES[9580]=["When one has a wonderful dream, one doesn't wish to come down to earth.","すばらしい夢をみると、現実にもどりたくなくなるものだ。","down to earth"];
EXAMPLES[9582]=["They are too numerous to enumerate.","それらは枚挙にいとまがない。","enumerate"];
EXAMPLES[9586]=["Let's stop off and see a movie.","映画でも見ていこうか。","stop off"];
EXAMPLES[9587]=["The dentist pulled out my decayed tooth by force.","歯医者は私の虫歯をむりやり引き抜いた。","by force"];
EXAMPLES[9589]=["Each party shall consist of no less than fifteen people.","各隊は少なくとも十五人以上で構成すること。","no less than"];
EXAMPLES[9590]=["The boys scampered in all directions at the sight of their teacher.","少年達は先生の姿を見ると四方八方に駆け出した。","scampered"];
EXAMPLES[9591]=["They got the sack for being careless and tardy.","あの連中は軽率で、仕事がのろかったから、くびになった。","tardy"];
EXAMPLES[9593]=["The children were enthralled by the fairy tale.","子供たちはそのおとぎ話に心を奪われた。","enthralled"];
EXAMPLES[9596]=["2ch, where there are many posts praising specific companies, or, conversely, denigrating their rivals.","特定の企業を賞賛する書き込みや、逆にライバル企業を貶める書き込みが多い2ch。","denigrating"];
EXAMPLES[9598]=["I visited him at intervals during my stay in Paris.","パリに滞在中時おり彼を訪れた。","at intervals"];
EXAMPLES[9599]=["The mean value of the frequency decreases with increasing amplitude.","周波数の平均値は振幅の増大にしたがって減じる。","amplitude"];
EXAMPLES[9600]=["I had a bad cold, and to make matters worse, it began snowing.","悪い風邪をひいていて、さらに悪いことには、雪が降ってきました。","make matters worse"];
EXAMPLES[9602]=["I tried to open the door, but it wouldn't budge.","ドアを開けようとしたけど、びくともしなかったよ。","budge"];
EXAMPLES[9603]=["Standing pools gather filth.","水の淀む所には汚物が溜る。","filth"];
EXAMPLES[9604]=["He chastised them for being noisy.","彼は彼らを騒がしいとたしなめた。","chastised"];
EXAMPLES[9605]=["If you eat this you'll fart a lot.","これを食べたらおならがいっぱい出るよ。","fart"];
EXAMPLES[9606]=["Because of the famine, the cattle starved to death.","食糧不足のため、家畜が餓死した。","to death"];
EXAMPLES[9608]=["Come out with your hands up.","手をあげて出て来い。","Come out with"];
EXAMPLES[9609]=["What has become of your sister?","君の妹はどうなりましたか。","become of"];
EXAMPLES[9612]=["Hang in there. You can do it!","頑張れよ、そうすればできるから。","Hang in"];
EXAMPLES[9616]=["A strange person is loitering around the house.","変な人が家の周りをうろついてるわよ。","loitering"];
EXAMPLES[9617]=["It is a stupendous project.","それは気が遠くなるような計画だ。","stupendous"];
EXAMPLES[9621]=["This year typhoons comes in succession.","今年は台風が次々にやってくる。","in succession"];
EXAMPLES[9623]=["They absolutely detest each other.","彼らはお互いに心の底から憎んでいる。","detest"];
EXAMPLES[9624]=["I refuse to consent to that plan.","その計画に同意することを拒否します。","consent to"];
EXAMPLES[9625]=["Who is going to pick up the tab for this?","この費用は誰が出すの。","pick up the tab"];
EXAMPLES[9626]=["She girded her waist with a belt.","彼女は腰にベルトを締めた。","girded"];
EXAMPLES[9627]=["The Aegis collision – why couldn't it have been avoided?","イージス衝突—なぜ避けられなかったか。","Aegis"];
EXAMPLES[9628]=["Either way I don't like him.","どっちみち私は彼は好きではない。","Either way"];
EXAMPLES[9629]=["I was absolved from paying my father's debt.","私は父の借金返済を免除された。","absolved"];
EXAMPLES[9630]=["Tom certainly wasn't fazed by what Mary said.","トムはメアリーが言ったことに全く動じなかった。","fazed"];
EXAMPLES[9637]=["Snakes are said to mesmerize small animals and birds.","ヘビは小動物や小鳥をにらんですくませるといわれている。","mesmerize"];
EXAMPLES[9639]=["Do not belittle his suggestions.","彼の提案を見くびるな。","belittle"];
EXAMPLES[9640]=["His trembling hands belied his calm attitude.","彼の震える手は落ち着いた態度が偽りである事を示していた。","belied"];
EXAMPLES[9641]=["I'm sometimes in a bad temper.","私は時々機嫌が悪くなる。","in a bad temper"];
EXAMPLES[9642]=["The image is not in focus.","その映像はピントがあっていない。","in focus"];
EXAMPLES[9643]=["I got the gist of what he was saying.","彼が言っていることの要点はわかった。","gist"];
EXAMPLES[9644]=["You have a tendency to talk too fast.","君には早口でしゃべる癖がある。","have a tendency to"];
EXAMPLES[9645]=["I can't stand being cooped up in this prison!","こんな所に監禁されているのはもうごめんだ。","cooped"];
EXAMPLES[9652]=["The wildest colt makes the best horse.","最も野性的な子馬が最高の駿馬になる。","colt"];
EXAMPLES[9655]=["At length, we reached the top of the mountain.","とうとう私達は山の頂上に到着した。","At length"];
EXAMPLES[9656]=["Her beauty was blemished by the scar.","彼女の美貌もその傷で台無しになった。","blemished"];
EXAMPLES[9657]=["We must try to break the deadlock.","われわれは局面の打開を図らなくてはならない。","deadlock"];
EXAMPLES[9662]=["My wife's constant nagging is getting me down.","妻に四六時中ぶつぶつ言われるのには憂鬱になってしまう。","nagging"];
EXAMPLES[9663]=["Where can I get hold of a good tax lawyer?","どこかにいい税理士はいないものだろうか。","get hold of"];
EXAMPLES[9664]=["Tom continued to honk the horn.","トムはクラクションを鳴らし続けた。","honk"];
EXAMPLES[9666]=["It is good for nothing.","何の役にも立たない。","good for nothing"];
EXAMPLES[9668]=["The businessman is thinking of rescinding the contract.","その実業家はその契約から身を引くことを考えている。","rescinding"];
EXAMPLES[9669]=["Anyway, I'm glad you were able to broach this difficult subject.","とにかく、言いづらい事を打ち明けてくれてうれしいよ。","broach"];
EXAMPLES[9675]=["The cartilage has slipped out here.","ここの軟骨が飛び出しています。","cartilage"];
EXAMPLES[9676]=["Sometimes it's fun to reminisce about one's childhood.","少年時代を思い出すのも時には楽しいものだ。","reminisce"];
EXAMPLES[9679]=["An unscrupulous person would sell even his own mother down the river.","破廉恥な人間は自分の母さえも裏切るだろう。","unscrupulous"];
EXAMPLES[9680]=["Industrialization often goes hand in hand with pollution.","産業化は往々にして公害を伴うものだ。","hand in hand with"];
EXAMPLES[9682]=["Take heart and do it again.","気をとりなおしてもう一度やってごらん。","Take heart"];
EXAMPLES[9683]=["It is not for the vanquished to talk of war.","敗軍の将兵を語らず。","vanquished"];
EXAMPLES[9684]=["We all suffer from it to some degree.","我々は皆ある程度それに苦しむ。","to some degree"];
EXAMPLES[9691]=["He will wriggle out of the fix.","窮地から足掻き出る。","wriggle"];
EXAMPLES[9692]=["The water in this brook is cool and clear.","この小川の水は冷たくてきれいね。","brook"];
EXAMPLES[9693]=["This dress creases easily.","この服はすぐしわになる。","creases"];
EXAMPLES[9694]=["Finally he invited all and sundry to partake of the cake and all.","ついに彼は誰もかもみんなにケーキでも何でも食べてくださいと誘った。","sundry"];
EXAMPLES[9696]=["Reading this book, I felt a renewing sense of the importance of camaraderie.","この本を読んで、友情の大切さを改めて実感しました。","camaraderie"];
EXAMPLES[9699]=["His voice quavered with anger.","彼の声は怒りで震えた。","quavered"];
EXAMPLES[9700]=["Many people believe that acupuncture can cure diseases.","鍼治療は病気を治すことができると多くの人が信じています。","acupuncture"];
EXAMPLES[9701]=["Educational reforms still have a long way to go.","教育の改革はまだまだこれからだ。","way to go"];
EXAMPLES[9702]=["The car veered from its course.","車はコースをはずれた。","veered"];
EXAMPLES[9706]=["Doctors should keep abreast of all the latest developments in medicine.","医者というものは、医学の最新の成果に遅れないように、ついていかなければならない。","keep abreast of"];
EXAMPLES[9711]=["The institution of marriage appears to be on the decline.","結婚という制度はあまり重要ではなくなってきているようだ。","on the decline"];
EXAMPLES[9713]=["The slippery snake slithered right out of his hand.","そのつるつるした蛇は、彼の手からにょろりと抜け出した。","slithered"];
EXAMPLES[9715]=["I didn't mean to eavesdrop on your talk.","あなたの話を立ち聞きするつもりはありませんでした。","eavesdrop"];
EXAMPLES[9718]=["Can I chew on this side?","こちら側でかんでもいいですか。","chew on"];
EXAMPLES[9722]=["Your efforts will bear fruit someday.","君の努力はいつかは実を結ぶだろう。","bear fruit"];
EXAMPLES[9723]=["To put it succinctly, I don't know, and I don't want to know.","要するに知らないし知りたくもない。","succinctly"];
EXAMPLES[9726]=["The doctor told me I had a concussion.","脳震盪だとお医者さんに言われました。","concussion"];
EXAMPLES[9728]=["We spoke to no purpose.","我々はしゃべったが何にもならなかった。","to no purpose"];
EXAMPLES[9730]=["We should confine the discussion to the question at issue.","私たちはその討論を争点となっている問題に限定すべきだ。","at issue"];
EXAMPLES[9731]=["Your heart's still beating loud and clear.","君の心臓はまだ大きくハッキリと鳴っている。","loud and clear"];
EXAMPLES[9733]=["The fortress was secure from every kind of attack.","その砦はどのような攻撃にも安全であった。","fortress"];
EXAMPLES[9738]=["My, you're looking green around the gills.","ねえ、元気がないみたいだけど。","gills"];
EXAMPLES[9739]=["This style is much in vogue.","このスタイルは大いにはやっている。","in vogue"];
EXAMPLES[9740]=["For external use only, do not ingest.","外用のみに使用し、内服しないで下さい。","ingest"];
EXAMPLES[9742]=["This is a family heirloom.","これは家宝です。","heirloom"];
EXAMPLES[9743]=["Let's take it for a month on trial.","ためしにそれを１ヶ月使ってみよう。","on trial"];
EXAMPLES[9748]=["The excited woman tried to explain the accident all in one breath.","興奮した女性は一気に事故について説明しようとした。","all in one"];
EXAMPLES[9755]=["The smoldering firewood burst into flame.","くすぶっていた薪が突然燃え上がった。","smoldering"];
EXAMPLES[9757]=["He is infatuated with girls who have cat ears.","彼は猫耳少女にご執心だ。","infatuated"];
EXAMPLES[9760]=["I hereby declare the opening of the Olympic Games.","ここにオリンピック大会の開会を宣言します。","hereby"];
EXAMPLES[9762]=["I would rather starve to death than steal.","私は盗みをするくらいなら餓死したほうがよい。","starve to death"];
EXAMPLES[9767]=["I think there are many who binge eat from stress.","ストレスでやけ食いをされる方も多いと思います。","binge"];
EXAMPLES[9768]=["Do you know which deity this temple is dedicated to?","この寺の本尊は何であるか知っていますか。","deity"];
EXAMPLES[9771]=["He tried to wean his son from his bad habit.","彼は息子に悪習を直させようと努めた。","wean"];
EXAMPLES[9773]=["He is a glutton for work.","彼はバリバリの仕事の鬼だ。","glutton"];
EXAMPLES[9774]=["I came to this country for the purpose of studying music.","音楽を勉強するためにこの国へやってきた。","for the purpose of"];
EXAMPLES[9778]=["I wonder if this performer is really under hypnosis.","この芸能人、本当に催眠術にかかってるのかなあ。","hypnosis"];
EXAMPLES[9780]=["He had to inquire into the record of the event.","彼は事件の記録を調べなければならなかった。","inquire into"];
EXAMPLES[9783]=["It sounds strange, but it is true none the less.","奇妙に思えるが、それでもやはりそれは事実だ。","none the less"];
EXAMPLES[9785]=["I must go there irrespective of what you think.","君がどう思おうと、私はそこへ行かなければならない。","irrespective of"];
EXAMPLES[9786]=["These flowers will live through the winter more often than not.","この花はたいてい冬場も枯れずにもちますよ。","live through"];
EXAMPLES[9788]=["That child is sulking without its parents.","あの子供は親に相手をしてもらえず拗ねている。","sulking"];
EXAMPLES[9796]=["Brass is an alloy of copper and zinc.","真鍮は銅と亜鉛の合金である。","alloy"];
EXAMPLES[9801]=["Take this knife and cut the top off.","このナイフを持って、てっぺんを切り取りなさい。","top off"];
EXAMPLES[9803]=["The enemy was entrenched all around the capital.","敵軍は首都の周囲を塹壕で固めていた。","entrenched"];
EXAMPLES[9807]=["That child is always fretting.","あの子はいつもだだをこねている。","fretting"];
EXAMPLES[9810]=["I found a kindred spirit in Bob.","ボブとはすっかり意気投合した。","kindred"];
EXAMPLES[9812]=["Why does it draw out lunch every day?","なぜ毎日昼食を抜くのですか。","draw out"];
EXAMPLES[9813]=["The youth of our country is apathetic about politics.","我が国の若年層は政治に無関心だ。","apathetic"];
EXAMPLES[9816]=["We're filled to the rafters.","大勢の人出ですよ。","rafters"];
EXAMPLES[9821]=["When we were on the brink of starvation, they saved our lives.","餓死寸前でいるところを、彼らは私達の命を救ってくれた。","on the brink of"];
EXAMPLES[9822]=["This is the bottom line.","つまり結論をいうとね。","the bottom line"];
EXAMPLES[9825]=["Discretion is the better part of valor.","用心深さは勇気の大半である。","valor"];
EXAMPLES[9826]=["The origins of these people is shrouded in mystery.","この民族の起源は神秘につつまれている。","shrouded"];
EXAMPLES[9830]=["She was a rather prim and proper young lady.","彼女はいささかとりすました良家のお嬢さんだった。","prim"];
EXAMPLES[9831]=["No man is a hero to his valet.","従者にとっては誰も英雄ではない。","valet"];
EXAMPLES[9834]=["Love me lithe, love me long.","細く長く愛して。","lithe"];
EXAMPLES[9835]=["We have to catch up on our work as soon as possible.","私たちは仕事の遅れをできるだけ早く取り戻さなければならない。","catch up on"];
EXAMPLES[9837]=["He tended to be lenient toward the children.","彼はともすれば子どもに甘かった。","lenient"];
EXAMPLES[9841]=["I had to compete with him for promotion.","私は昇進をかけて彼と競争しなければならなかった。","compete with"];
EXAMPLES[9844]=["A quarrel estranged one boy from the other.","２人の少年は口論がもとで不和になった。","estranged"];
EXAMPLES[9845]=["All at once the bride burst into laughter.","花嫁が突然大笑いをした。","burst into laughter"];
EXAMPLES[9848]=["The locomotive was pulling a long line of freight cars.","機関車は長い貨物車の列を引っ張って走っていた。","locomotive"];
EXAMPLES[9849]=["Drink up your milk.","ミルクを全部飲んでしまいなさい。","Drink up"];
EXAMPLES[9851]=["The VAT in Germany is 19 per cent.","ドイツでは19%の消費税が課せられています。","VAT"];
EXAMPLES[9852]=["He retorted that it was all my fault.","彼はすべて私が悪いのだと口答えした。","retorted"];
EXAMPLES[9860]=["I was appalled at the sight.","わたしはそれを見てぎょっとした。","appalled"];
EXAMPLES[9865]=["If you sit back and rest, you will feel much better.","ゆったり座って休みなさい。そうすればずっと気分が良くなるでしょう。","sit back"];
EXAMPLES[9867]=["When one would be filial, one's parents are gone.","孝行したいときに親はなし。","filial"];
EXAMPLES[9868]=["This was his one and only hope.","これが彼のたった一つの希望であった。","one and only"];
EXAMPLES[9873]=["She lives in the middle of nowhere.","彼女は人里離れたところに住んでいます。","in the middle of nowhere"];
EXAMPLES[9874]=["The soldiers fought valiantly, but finally they had to give in.","その兵士たちは勇敢に戦ったが、結局降伏しなければならなかった。","valiantly"];
EXAMPLES[9875]=["Check up on the accuracy of this article.","この記事が何処まで本当か調べてくれ。","Check up on"];
EXAMPLES[9878]=["Whichever highway you decide on, it will be crowded with cars and trucks.","どちらの道路を通るにしても、車やトラックで混雑するでしょう。","be crowded with"];
EXAMPLES[9879]=["Large residual stomach contents may lead to loss of appetite, nausea and vomiting.","胃の内容物の残存量が多いと、食欲不振、吐き気および嘔吐が強くなる。","residual"];
EXAMPLES[9881]=["Fish cannot live out of water.","魚は水中でなければ生きられない。","live out"];
EXAMPLES[9886]=["I bump into her.","彼女と偶然出会う。","bump into"];
EXAMPLES[9889]=["It leaves nothing much to be desired.","それは遺憾なところが多い。","nothing much"];
EXAMPLES[9891]=["Some animals are nocturnal.","夜に活動する動物もいる。","nocturnal"];
EXAMPLES[9894]=["Ten to one you can pass the test.","君がそのテストに合格することはまず間違いない。","Ten to one"];
EXAMPLES[9895]=["This book is abridged from the original.","この本は原書の要約版です。","abridged"];
EXAMPLES[9898]=["There is quite a bit of water remaining.","水はかなり多く残っている。","quite a bit"];
EXAMPLES[9900]=["Quite a few students played truant from school.","かなり多くの学生が学校をサボった。","truant"];
EXAMPLES[9901]=["What account can you give of your misbehavior?","君は自分の不始末をどう弁明するのか。","give of"];
EXAMPLES[9902]=["The company is on the verge of bankruptcy.","その会社は今にも倒産しようとしている。","on the verge of"];
EXAMPLES[9910]=["Mint is grown similar to a weed.","ミントは雑草のように育ちます。","Mint"];
EXAMPLES[9914]=["If you can't come, send someone in your stead.","もしあなたが来られなければだれか代理をよこしてください。","stead"];
EXAMPLES[9915]=["My business is at a standstill because of the recession.","不況で私の商売は上がったりだ。","at a standstill"];
EXAMPLES[9920]=["The best laid plans of mice and men often go awry.","この上なく入念に準備した計画でもしばしば失敗する。","awry"];
EXAMPLES[9923]=["He is just a minion of the minister.","彼は大臣の腰ぎんちゃくだ。","minion"];
EXAMPLES[9924]=["I kind of feel queasy. I might've gotten seasick on the boat.","なんか気持ち悪い。船に酔ったかもしれない。","queasy"];
EXAMPLES[9928]=["They are now man and wife duly married.","２人は今はれて夫婦だ。","duly"];
EXAMPLES[9929]=["To all appearances, she is healthy.","どう見ても彼女は元気そうだ。","To all appearances"];
EXAMPLES[9930]=["I was relieved that there are people more wanton than me.","私よりもっとエッチな人もいて安心しました。","wanton"];
EXAMPLES[9931]=["Tom went out to buy kerosene for his stove.","トムなら、ストーブの灯油を買いに行ったよ。","kerosene"];
EXAMPLES[9933]=["In the end, he also faltered in the face of great adversity.","ついに彼も強い反対に折れた。","faltered"];
EXAMPLES[9934]=["We should always act in obedience to the law.","我々はいつも法律に従って行動するべきだ。","in obedience to"];
EXAMPLES[9935]=["Today is the winter solstice.","今日は冬至です。","solstice"];
EXAMPLES[9937]=["Take this folding umbrella with you. It might come in handy.","この折りたたみの傘を持って行きなさい。役に立つかもしれませんから。","come in handy"];
EXAMPLES[9938]=["Enter in a contractual agreement with me and become a young magical girl!","僕と契約して魔法少女になってよ。","contractual"];
EXAMPLES[9939]=["My mother used to be into tennis.","母はかつてテニスに夢中だった。","be into"];
EXAMPLES[9940]=["Now there are charms and talismans for your pet that you can have blessed.","ペットのためにご祈祷していただける御守と御札が実現しました。","talismans"];
EXAMPLES[9941]=["We discussed the matter at large.","我々はその問題を詳細に論じた。","at large"];
EXAMPLES[9945]=["Tom is unusually kind today. I wonder if he has ulterior motives.","今日はトムがやけに親切だけど、何か魂胆でもあるのかしら。","ulterior"];
EXAMPLES[9947]=["I have a kitty and a dog.","子猫と犬を飼ってます。","kitty"];
EXAMPLES[9948]=["I guess the time of reckoning has arrived at last.","ついに年貢の納め時が来たか。","reckoning"];
EXAMPLES[9949]=["That magazine article exposed his devilish acts to the full light of day.","その雑誌の記事で彼の悪業は白日の下にさらされましたね。","to the full"];
EXAMPLES[9951]=["My legs were leaden from fatigue.","疲れて足が重かった。","leaden"];
EXAMPLES[9955]=["I'm afraid she may have the mumps.","おたふく風邪ではないでしょうか。","mumps"];
EXAMPLES[9957]=["The fire was put out at the cost of a fireman's life.","火事は消防士の生命を犠牲にして消された。","at the cost of"];
EXAMPLES[9963]=["The sentry demanded the password from everyone.","歩哨はみんなに合い言葉を言わせた。","sentry"];
EXAMPLES[9966]=["Do you eat veal?","仔牛肉を食べますか。","veal"];
EXAMPLES[9970]=["Foreign products arrived on the market in large quantities.","外国製品がどかっと市場に出回った。","in large"];
EXAMPLES[9971]=["He sells flowers in a little kiosk.","彼は小さな売店で花を売っています。","kiosk"];
EXAMPLES[9973]=["It was very sultry that night.","その晩はとてもむし暑かった。","sultry"];
EXAMPLES[9975]=["The information is leaking piecemeal to the press.","情報は新聞社にぽつりぽつりと洩れているよ。","piecemeal"];
EXAMPLES[9978]=["He is impervious to reason.","彼はものわかりが悪い。","impervious"];
EXAMPLES[9979]=["Do introverts not live as long as extroverts?","内気な人は外向的な人より短命？","extroverts"];
EXAMPLES[9983]=["He seems delirious with a high fever.","彼は高熱に浮かされているようだ。","delirious"];
EXAMPLES[9985]=["Please hurry and finish the prospectus.","急いで内容紹介パンフレットを仕上げて下さい。","prospectus"];
EXAMPLES[9989]=["You shouldn't be impatient with children.","子供に対して短気を起こしてはいけない。","be impatient with"];
EXAMPLES[9991]=["We've become a mockery to the whole village.","我々は村中の笑い者になった。","mockery"];
EXAMPLES[9992]=["He was flying down the road.","ものすごい勢いで駆けていった。","down the road"];
EXAMPLES[9993]=["Carbon monoxide is a poisonous substance formed by the incomplete combustion of carbon compounds.","一酸化炭素とは炭素化合物の不完全燃焼で発生する有害物質です。","monoxide"];
EXAMPLES[9994]=["We need to postulate a completely different paradigm to explain all these phenomena.","これらのすべての現象を説明するにはまったくの異なるパラダイムを立てる必要がある。","paradigm"];
EXAMPLES[9995]=["Jane threw a glance at us.","ジェーンは私達に目線を投げかけた。","glance at"];
EXAMPLES[9998]=["An ounce of practice is worth a pound of precept.","教訓よりも実行が大切。","precept"];
EXAMPLES[10002]=["If you come this way by any chance, drop in to see me.","もしかこの方面に来るようなことがあったらお寄りください。","by any chance"];
EXAMPLES[10005]=["I saw my sister tear up the letter.","私は姉がその手紙をひきさくのを見た。","tear up"];
EXAMPLES[10008]=["Violet light has a shorter wavelength than red light.","紫の光は、赤の光よりも短い波長です。","wavelength"];
EXAMPLES[10011]=["He has only one servant to attend on him.","彼には仕える使用人が１人しかいない。","attend on"];
EXAMPLES[10013]=["When all the group members are silent, somebody must break the ice.","グループの人たち全員が沈黙しているときは、誰かが話の口火を切らねばならない。","break the ice"];
EXAMPLES[10014]=["The job is up for grabs now.","今なら仕事の口があります。","up for grabs"];
EXAMPLES[10015]=["The tycoon endowed each son with a million dollars.","あの大事業家は息子それぞれに１００万ドルを残した。","tycoon"];
EXAMPLES[10017]=["He was wearing a threadbare suit.","彼はくたくたの背広を着ていた。","threadbare"];
EXAMPLES[10019]=["This is, strictly speaking, a mistake.","これは厳密にいえば間違いである。","strictly speaking"];
EXAMPLES[10023]=["Being treated as a minor is irksome.","未成年扱いとは心外だ。","irksome"];
EXAMPLES[10024]=["Lisa, keep an eye on my suitcase while I buy our train tickets.","リサ、私が列車の切符を買う間、私のスーツケースから目を離さないでね。","keep an eye on"];
EXAMPLES[10028]=["I suppose we're a little too indulgent to the dog.","うちの者はどうも犬に少し甘すぎると思う。","indulgent"];
EXAMPLES[10030]=["It is impudent of him to say so.","そう言うことは彼はあつかましい奴だ。","impudent"];
EXAMPLES[10034]=["He is very mercenary.","彼はとても打算的だ。","mercenary"];
EXAMPLES[10036]=["I don't think I'm cut out for city life.","わたしは都会の生活には生まれつき向いていないと思う。","cut out for"];
EXAMPLES[10038]=["Could you speak louder? I'm hard of hearing.","もっと大きな声で話してくれませんか。私は耳が遠いんです。","hard of hearing"];
EXAMPLES[10041]=["The meeting was held as intended at the outset.","その会合は当初の予定どおりに開催された。","at the outset"];
EXAMPLES[10042]=["When I was a child, I was very chubby.","子どもの頃は、とてもぽっちゃりしてました。","chubby"];
EXAMPLES[10043]=["When you go abroad, you'd better keep in mind that tipping is customary.","海外に行ったときは、チップが必要なことを覚えていたほうがいいですよ。","keep in"];
EXAMPLES[10046]=["I need palliative care.","私にはパリアティブケアが必要だ。","palliative"];
EXAMPLES[10050]=["He is doing penance.","彼は罪滅ぼしに難行苦行をしている。","penance"];
EXAMPLES[10053]=["I want to gaze at this scenery forever.","私はこの景色をずっと眺めていたい。","gaze at"];
EXAMPLES[10055]=["The refugees were living in a narrow, squalid backstreet.","難民がごみごみした裏町に住んでいました。","squalid"];
EXAMPLES[10058]=["I'm really looking forward to next March, when they roll out the new PlayStation 2.","プレステ２が来年の３月に発売されるそうだけど、今から楽しみだね。","roll out"];
EXAMPLES[10060]=["This ink stain will not wash out.","このインキの染みは洗っても落ちない。","wash out"];
EXAMPLES[10067]=["Corn starch gives the white sauce its consistency.","コーンスターチで、ホワイトソースにとろみがつきます。","starch"];
EXAMPLES[10068]=["The impending examination loomed large in her mind.","目前に迫った試験のことが彼女の心に大きく広がった。","impending"];
EXAMPLES[10075]=["You've got a good head on your shoulders.","気が利くなあ。","head on"];
EXAMPLES[10076]=["He tries to keep abreast of his classmates.","彼はクラスの仲間に後れをとらぬようにしている。","abreast"];
EXAMPLES[10078]=["As we went around the corner, the lake came in sight.","角を曲がると、湖が見えてきた。","around the corner"];
EXAMPLES[10080]=["Obstetricians also bear a high risk of suits.","訴訟リスクの高さも産科医にのしかかる。","Obstetricians"];
EXAMPLES[10084]=["Show me how to make 10% saline solution.","濃度10%の食塩水の作り方を教えてください。","saline"];
EXAMPLES[10085]=["Why did they wait upon him so servilely?","彼らはなぜあんなに卑屈に彼に仕えたのか。","servilely"];
EXAMPLES[10086]=["She was impressed with the altruistic service of nurses.","彼女は看護婦の献身的な奉仕に感銘を受けた。","altruistic"];
EXAMPLES[10088]=["They overcame many inveterate superstitions.","彼らは多くの根深い迷信に打ち勝った。","inveterate"];
EXAMPLES[10089]=["I like to do a few exercises to loosen up before I run.","私は走る前に、体をほぐすのにちょっと体操をする。","loosen up"];
EXAMPLES[10093]=["Above all, beware of pickpockets.","とりわけスリに御用心。","beware of"];
EXAMPLES[10094]=["The English are a taciturn people.","英国民は無口な国民だ。","taciturn"];
EXAMPLES[10097]=["Because he thought Fred's comment was tacky, Larry got up on his high horse.","フレッドの意見がしゃくにさわったラリーは、居丈高な態度に出た。","tacky"];
EXAMPLES[10098]=["Do not interfere with Tom while he is reading.","トムが本を読んでいる間は邪魔をしてはいけない。","interfere with"];
EXAMPLES[10100]=["Wedlock is a padlock.","結婚は身の枷。","padlock"];
EXAMPLES[10104]=["It's much too pompous for such a trivial thing.","たいしたことではないのに必要以上に物々しい言い方です。","pompous"];
EXAMPLES[10105]=["We have to draw a line somewhere.","どこかで切らなくては。","draw a line"];
EXAMPLES[10106]=["Tom vehemently dislikes being a burden to others.","トムは人に迷惑をかけることを極端に嫌う。","vehemently"];
EXAMPLES[10108]=["We have to take steps to prevent air pollution.","大気汚染を防止するため何か手段をとらなければならない。","take steps"];
EXAMPLES[10109]=["Don't live off your sister any more.","これ以上姉さんのすねかじりはやめたまえ！","live off"];
EXAMPLES[10112]=["It was out of the ordinary for Chris to behave so roughly.","そんなに乱暴にふるまうなんて、クリスにしては普通ではありませんでした。","out of the ordinary"];
EXAMPLES[10113]=["The writing was illegible.","読みにくい筆跡だった。","illegible"];
EXAMPLES[10123]=["If you get bit by a rabid dog, you'll need a tetanus shot.","あなたは病犬に噛まれたら、破傷風の予防注射が必要となってしまいます。","tetanus"];
EXAMPLES[10124]=["They contrived to arrive in time after all.","彼らはどうやらなんとか遅れずに到着できた。","contrived"];
EXAMPLES[10125]=["The coup was meticulously executed.","クーデターは慎重に遂行された。","meticulously"];
EXAMPLES[10128]=["I missed it inadvertently.","うかつにもそれを見逃してしまった。","inadvertently"];
EXAMPLES[10131]=["Next time I'll be more circumspect.","次はもっと慎重にやります。","circumspect"];
EXAMPLES[10133]=["Don't be subservient to your boss.","上役にやたらにぺこぺこするな。","subservient"];
EXAMPLES[10135]=["The volcano poured molten rock.","その火山は溶岩を流し出した。","molten"];
EXAMPLES[10137]=["Tom works more diligently now.","トムはいまや以前にもまして勤勉に働いている。","diligently"];
EXAMPLES[10138]=["The professor who invented it has the right to reasonable remuneration from the university.","それを発明した教授は大学から相当の対価を受ける権利がある。","remuneration"];
EXAMPLES[10140]=["The room is in immaculate order.","部屋はきちんと整っている。","immaculate"];
EXAMPLES[10141]=["The boat fell into a whirlpool and overturned.","ボートが渦潮に巻き込まれ横転しました。","whirlpool"];
EXAMPLES[10143]=["What will become of our close relations if the bilateral security treaty expires?","相互安全保障条約が期限切れになったら、両国の親密な関係はどうなるだろう？","bilateral"];
EXAMPLES[10144]=["His indignation got the better of him.","彼の憤慨は彼を打ちまかした。","indignation"];
EXAMPLES[10151]=["The peddler carried a big bundle on his back.","行商人は大きな包みを背負って運んだ。","peddler"];
EXAMPLES[10152]=["The young men of Japan are apt to jump on the bandwagon.","日本の若者は流行に乗る傾向があります。","jump on the bandwagon"];
EXAMPLES[10153]=["The women led the movement to obtain female suffrage.","彼女たちは選挙権を勝ち取るための運動を指揮した。","suffrage"];
EXAMPLES[10156]=["It's the widget that overcomes web marketing's weaknesses.","Webマーケティングの弱点を克服するウィジェットです。","widget"];
EXAMPLES[10157]=["The government coffers are replete with funds.","国庫は資金が潤沢である。","replete"];
EXAMPLES[10160]=["The accident bereaved her of her son.","事故は彼女から息子さんを奪った。","bereaved"];
EXAMPLES[10161]=["He was completely engrossed in the book.","彼は読書にひたりきっていた。","engrossed"];
EXAMPLES[10162]=["Don't toy with her affections.","彼女の愛情をもて遊ぶな。","toy with"];
EXAMPLES[10163]=["There is no cause for undue alarm.","過度に心配することはない。","undue"];
EXAMPLES[10164]=["Sami wanted to know Layla's zodiac sign.","サミはレイラの星座を知りたかった。","zodiac"];
EXAMPLES[10167]=["Tom was the victim of a heinous crime.","トムは凶悪犯罪の被害者になった。","heinous"];
EXAMPLES[10168]=["He hung his head sheepishly.","おどおどして首をたれた。","sheepishly"];
EXAMPLES[10179]=["She struck me as a tactful girl.","彼女は気の利く女の子である印象を強く受けた。","tactful"];
EXAMPLES[10182]=["She made some derogatory remarks about her colleagues.","彼女は同僚たちの悪口を言った。","derogatory"];
EXAMPLES[10188]=["You are too inquisitive about other people's affairs.","君は他人のことを詮索しすぎる。","inquisitive"];
EXAMPLES[10189]=["The only evidence was the traces of semen stuck to the underwear.","唯一の証拠は、下着に付着していた精液の痕跡。","semen"];
EXAMPLES[10203]=["From beginning to end Tom has only spoken with a lackluster demeanour.","トムは最初から最後まで淡々と話した。","lackluster"];
EXAMPLES[10209]=["I doubt the veracity of his statement.","彼の供述の真実性は疑わしいと思う。","veracity"];
EXAMPLES[10212]=["Don't dawdle about, make haste!","ちんたらしてないで、さっさとしろ。","dawdle"];
EXAMPLES[10214]=["Honest men and knaves may possibly wear the same cloth.","善人も悪人も同じ衣服を着ることができるのである。","knaves"];
EXAMPLES[10218]=["It's invigorating to breathe the brisk, fresh mountain air.","山でおいしい空気をすうと気分も爽快です。","invigorating"];
EXAMPLES[10221]=["He became more obstinate as he grew older.","彼は歳を取るにつれて次第に頑固になった。","obstinate"];
EXAMPLES[10227]=["Let's not quibble over trivial matters.","細かいことでとやかく言うのはよそう。","quibble"];
EXAMPLES[10229]=["Local party members are trying to gerrymander the district.","地方の党員たちは自党に有利な形の選挙区割りをもくろんでいます。","gerrymander"];
EXAMPLES[10238]=["I am afraid he is going to spill the beans.","彼はなんでもしゃべってしまいそうです。","spill the beans"];
EXAMPLES[10242]=["He feigned indifference to the girl.","彼はその少女に関心がないかのように装った。","feigned"];
EXAMPLES[10248]=["It is the psychological moment to let the cat out of the bag.","秘密をばくろするのは、心理的に最も効果のある時である。","let the cat out of the bag"];
EXAMPLES[10254]=["The Esperanto movement has always had to grapple with the problem of'eternal beginners'.","エスペラント運動は常に永遠の初心者の問題を抱えています。","grapple with"];
EXAMPLES[10267]=["You're certainly looking fit as a fiddle today.","今日はとても元気そうだね。","fit as a fiddle"];
EXAMPLES[10268]=["Quit sitting on the fence and make a decision!","おまえもいい加減ウジウジしてないで、決断しなさい！","on the fence"];
EXAMPLES[10278]=["There wasn't a long queue at the stadium.","野球場には長い列はなかった。","queue"];
EXAMPLES[10279]=["He was profuse in his praise of his teacher.","彼は彼の先生を誉めちぎった。","profuse"];
EXAMPLES[10287]=["The knife's serrated edge makes it perfect for cutting such things as bread.","刃にぎざぎざが付いているので、このナイフはパンのようなものを切り分けるのに最適だ。","serrated"];
EXAMPLES[10288]=["The storm didn't abate for several hours.","嵐は数時間静まらなかった。","abate"];
EXAMPLES[10290]=["Tom vehemently dislikes being a burden to others.","トムは人に迷惑をかけることを極端に嫌う。","vehemently"];
EXAMPLES[10293]=["All men are fallible.","人はみな誤りに陥りがちだ。","fallible"];
EXAMPLES[10301]=["The Fed is trying to stave off a run on the banks.","米国連邦準備銀行は銀行の取り付け騒ぎを食い止めようとしています。","stave off"];
EXAMPLES[10304]=["Every writer writes in the way that accords with his own idiosyncrasies.","作家は誰でも自分に合った書き方をする。","idiosyncrasies"];
EXAMPLES[10309]=["Everyone remembers the happy days of youth as his halcyon days.","誰も、楽しい青春を平穏無事な時期として思い起こす。","halcyon"];
EXAMPLES[10310]=["When you think about it, it's all Kenny's fault for being so obtuse.","元はと言えば、健ちゃんが鈍ちんなのがいけないんだからね～っ。","obtuse"];
EXAMPLES[10311]=["His request was tantamount to a threat.","彼の要求は脅しに近かった。","tantamount"];
EXAMPLES[10317]=["Tom is very dexterous.","トムはとっても手先が器用だ。","dexterous"];
EXAMPLES[10320]=["I'll bite the bullet.","我慢しましょう。","bite the bullet"];
EXAMPLES[10325]=["They were under the yoke of a tyrant.","彼らは暴君の支配下にあった。","yoke"];
EXAMPLES[10328]=["My teacher, exasperated, now shifts his eyes upon me.","先生のあきれた視線が僕に向けられる。","exasperated"];
EXAMPLES[10332]=["A small spark often kindles a large flame.","小さな火花はしばしば大きな炎を起こす。","kindles"];
EXAMPLES[10334]=["Don't throw in the towel.","降参するな。","throw in the towel"];
EXAMPLES[10337]=["He is very zealous in his study of English.","彼は英語の勉強に非常に熱心です。","zealous"];
EXAMPLES[10339]=["This is an immutable truth.","これ不変の真理なり。","immutable"];
EXAMPLES[10341]=["The frightened boy's heart palpitated with terror.","そのおびえた少年の心臓は恐怖でどきどき打っていた。","palpitated"];
EXAMPLES[10345]=["It is more ignominious to mistrust our friends than to be deceived by them.","友人に欺かれるよりも友人を信じないことの方が不名誉である。","ignominious"];
EXAMPLES[10355]=["Nothing vexed her more than his selfishness.","彼のわがままほど彼女の気にさわることはなかった。","vexed"];
EXAMPLES[10356]=["The politicians try to pass the buck.","政治家達は責任を逃れようとしている。","pass the buck"];
EXAMPLES[10361]=["The union members were up in arms.","組合員たちは反旗をひるがえした。","up in arms"];
EXAMPLES[10367]=["The dog gave a yelp when I trod on its paw.","私が足を踏むと犬は鳴いた。","yelp"];
EXAMPLES[10373]=["Let's hit the hay.","じゃあ寝ようよ。","hit the hay"];
EXAMPLES[10379]=["He absconded with the money.","彼はその金を持ち逃げした。","absconded"];
EXAMPLES[10380]=["Men who were bereft of reason conducted the war.","理性を失った人たちが戦争を遂行した。","bereft"];
EXAMPLES[10384]=["We will never give in to terrorist demands.","我々は決してテロリストの要求に屈服しないであろう。","give in to"];
EXAMPLES[10388]=["Your appetite's voracious from first thing in the morning, isn't it!","朝から食欲旺盛だね。","voracious"];
EXAMPLES[10390]=["Tom got there just in the nick of time.","トムは遅刻ギリギリで到着した。","in the nick of time"];
